    double hprof_ms[8] = {}, hprof_last = 0;   // (the host's time between the same marks: one GPU)
    void prof_mark(const Dev& d, int stage) {
        if (!prof_window && !prof_chunk) return;
        std::lock_guard<std::mutex> lk(prof_mu);
        if (prof_failed) return;
        if (prof_chunk) {
            const double now = now_ms();
            if (hprof_last > 0) hprof_ms[stage] += now - hprof_last;
            hprof_last = now;
        }
        if (d.id < 0 || (size_t) d.id >= prof_pool.size()) {
            std::fprintf(stderr, "ds4: profiling disabled: CUDA device %d is outside the event pool\n", d.id);
            prof_failed = true;
            return;
        }
        cudaError_t ce = cudaSetDevice(d.id);
        if (ce != cudaSuccess) {
            std::fprintf(stderr, "ds4: profiling disabled: cudaSetDevice(%d): %s\n", d.id, cudaGetErrorString(ce));
            prof_failed = true;
            return;
        }
        auto& pool = prof_pool[(size_t) d.id];
        cudaEvent_t e = nullptr;
        if (pool.empty()) {
            ce = cudaEventCreate(&e);
            if (ce != cudaSuccess) {
                std::fprintf(stderr, "ds4: profiling disabled: cudaEventCreate on CUDA%d: %s\n", d.id,
                             cudaGetErrorString(ce));
                prof_failed = true;
                return;
            }
        } else {
            e = pool.back();
            pool.pop_back();
        }
        ce = cudaEventRecord(e, d.st);
        if (ce != cudaSuccess) {
            std::fprintf(stderr, "ds4: profiling disabled: cudaEventRecord on CUDA%d: %s\n", d.id,
                         cudaGetErrorString(ce));
            (void) cudaEventDestroy(e);
            prof_failed = true;
            return;
        }
        prof_marks.push_back({d.id, e, stage});
    }
    void prof_collect() {
        if (!prof_window && !prof_chunk) return;
        std::lock_guard<std::mutex> lk(prof_mu);
        const bool chunk_sample = prof_chunk;
        bool sample_ok = !prof_failed;
        double sample_ms[8] = {};
        std::vector<std::pair<int, cudaEvent_t>> last;
        int current_dev = -1;
        if (sample_ok) {
            for (const ProfMark& m : prof_marks) {
                if (m.dev < 0 || (size_t) m.dev >= prof_pool.size()) {
                    std::fprintf(stderr, "ds4: profiling disabled: CUDA device %d is outside the event pool\n", m.dev);
                    sample_ok = false;
                    break;
                }
                if (current_dev != m.dev) {
                    const cudaError_t ce = cudaSetDevice(m.dev);
                    if (ce != cudaSuccess) {
                        std::fprintf(stderr, "ds4: profiling disabled: cudaSetDevice(%d): %s\n", m.dev,
                                     cudaGetErrorString(ce));
                        sample_ok = false;
                        break;
                    }
                    current_dev = m.dev;
                }
                auto it = std::find_if(last.begin(), last.end(), [&](const auto& x) { return x.first == m.dev; });
                if (it != last.end()) {
                    float ms = 0.0f;
                    const cudaError_t ce = cudaEventElapsedTime(&ms, it->second, m.ev);
                    if (ce != cudaSuccess) {
                        std::fprintf(stderr, "ds4: profiling disabled: cudaEventElapsedTime on CUDA%d: %s\n", m.dev,
                                     cudaGetErrorString(ce));
                        sample_ok = false;
                        break;
                    }
                    sample_ms[m.stage] += ms;
                    it->second = m.ev;
                } else {
                    last.push_back({m.dev, m.ev});
                }
            }
        }
        if (sample_ok) {
            double* total = chunk_sample ? cprof_ms : st.prof_ms;
            const int stages = chunk_sample ? 8 : 6;
            for (int i = 0; i < stages; ++i) total[i] += sample_ms[i];
            for (const ProfMark& m : prof_marks) prof_pool[(size_t) m.dev].push_back(m.ev);
            prof_marks.clear();
            if (!chunk_sample) ++st.prof_tokens;
            return;
        }
        prof_failed = true;
        std::vector<ProfMark> retry;
        current_dev = -1;
        for (const ProfMark& m : prof_marks) {
            if (m.dev < 0 || (size_t) m.dev >= prof_pool.size()) continue;
            if (current_dev != m.dev) {
                if (cudaSetDevice(m.dev) != cudaSuccess) {
                    retry.push_back(m);
                    continue;
                }
                current_dev = m.dev;
            }
            (void) cudaEventDestroy(m.ev);
        }
        prof_marks = std::move(retry);
    }
    void dump_layer(Dev& d, const float* h, int il, int64_t p0, int T) {
        std::vector<float> v((size_t) T * g.hc * g.dim);
        cudaSetDevice(d.id);
        cudaMemcpyAsync(v.data(), h, v.size() * 4, cudaMemcpyDeviceToHost, d.st);
        cudaStreamSynchronize(d.st);
        std::lock_guard<std::mutex> lk(dump_mu);
        const int64_t hdr[3] = {il, p0, T};
        std::fwrite(hdr, 8, 3, dump_l);
        std::fwrite(v.data(), 4, v.size(), dump_l);
        std::fflush(dump_l);
    }

    ~Impl() {
        {
            std::lock_guard<std::mutex> lk(cs_mu);
            cs_quit = true;
        }
        cs_cv.notify_all();
        if (cs_th.joinable()) cs_th.join();
        warm_end();
        eg_io.stop();   // (its threads write into h_eg)
        for (auto& w : workers) w->stop();
        for (size_t i = 0; i < chunks.size(); ++i)
            if (chunks[i] && chunks[i]->blas) {
                cudaSetDevice(devs[i].id);
                cublasDestroy(chunks[i]->blas);
            }
        quit.store(true);
        if (service.joinable()) service.join();
        {
            std::lock_guard<std::mutex> lk(hq_mu);
            hq_quit = true;
        }
        hq_cv.notify_all();
        if (helper_th.joinable()) helper_th.join();
        {   // (DS4_HELPER_RECENT) its fill thread: a copy under way ends bounded (hr_loop) - then the pool may go
            std::lock_guard<std::mutex> lk(hr_mu);
            hr_quit = true;
        }
        hr_cv.notify_all();
        if (hr_th.joinable()) hr_th.join();
        if (hr_busy.load()) helper_keep = true;   // (a copy that did not finish: its stage and the pool stay)
        helper_close();   // (before any memory its stream reads or writes goes: the requests, its flags and answers)
        if (hr_st != nullptr && !helper_keep) {   // (after the helper's stream: its last 'tables' job's hr_tab_ev)
            int cur = 0;
            cudaGetDevice(&cur);
            if (cudaSetDevice(helper_id) == cudaSuccess) {
                if (hr_fill_ev) cudaEventDestroy(hr_fill_ev);
                if (hr_tab_ev) cudaEventDestroy(hr_tab_ev);
                cudaStreamDestroy(hr_st);
            }
            cudaSetDevice(cur);
            hr_st = nullptr;
        }
        {
            std::lock_guard<std::mutex> lk(pf_mu);
        }
        pf_cv.notify_all();
        if (pf_th.joinable()) pf_th.join();
        {
            std::lock_guard<std::mutex> lk(sw_mu);
        }
        sw_cv.notify_all();
        ram_cv.notify_all();
        for (std::thread& t : cache_ths)
            if (t.joinable()) t.join();
        if (ram_th.joinable()) ram_th.join();
        for (size_t i = 0; i < ram_chunks.size(); ++i) {
            if (i < zc_chunk.size() && zc_chunk[i]) cudaHostUnregister(ram_chunks[i]);
            os::anon_free(ram_chunks[i], ram_chunk_bytes[i]);
        }
        for (size_t di = 0; di < prof_pool.size(); ++di) {
            if (cudaSetDevice((int) di) != cudaSuccess) continue;
            for (cudaEvent_t e : prof_pool[di]) (void) cudaEventDestroy(e);
        }
        for (const ProfMark& m : prof_marks) {
            if (m.dev < 0 || (size_t) m.dev >= prof_pool.size()) continue;
            if (cudaSetDevice(m.dev) == cudaSuccess) (void) cudaEventDestroy(m.ev);
        }
        {
            std::lock_guard<std::mutex> lk(rc_mu);
        }
        rc_cv.notify_all();
        if (rc_th.joinable()) rc_th.join();
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            for (void* p : d.allocs) cudaFree(p);
            if (d.st) cudaStreamDestroy(d.st);
            if (d.ev) cudaEventDestroy(d.ev);
        }
        if (!helper_keep)
            for (void* p : host_allocs) cudaFreeHost(p);
        for (Layer& l : L)
            for (uint8_t* b : l.host)
                if (b != nullptr) {
                    (void) b;   // host blobs live in one mapping per layer, unmapped below
                }
        for (auto& m : host_maps) {
            if (host_pinned) cudaHostUnregister(m.first);
            os::anon_free(m.first, m.second);
        }
    }
    std::vector<std::pair<void*, size_t>> host_maps;
    bool host_pinned = false;   // host_maps page-locked (chunk > 0, when the OS let them all be: #521)

    template <class T>
    bool dalloc(Dev& d, T*& p, size_t n, std::string& err, size_t* acct = nullptr) {
        void* v = nullptr;
        cudaSetDevice(d.id);
        const size_t b = align256(n * sizeof(T));
        if (cudaMalloc(&v, b) != cudaSuccess) {
            err = "cudaMalloc " + std::to_string(b >> 20) + " MiB on CUDA" + std::to_string(d.id) + " failed";
            return false;
        }
        // zeroed before anything lands in it: the loads copy in on the default stream, which the non-blocking d.st
        // does not order against - a zeroing still queued there could wipe the weights just copied
        if (cudaMemsetAsync(v, 0, b, d.st) != cudaSuccess || cudaStreamSynchronize(d.st) != cudaSuccess) {
            cudaFree(v);
            err = "zeroing " + std::to_string(b >> 20) + " MiB on CUDA" + std::to_string(d.id) + " failed";
            return false;
        }
        d.allocs.push_back(v);
        if (acct) *acct += b;
        else d.scratch += b;
        p = (T*) v;
        return true;
    }
    static Layer& member(Layer& l, int m) { return m == 0 ? l : l.mates[(size_t) m - 1]; }
    // abliteration: the T rows of y (a write about to enter hc_post, all-reduced already) lose their component along
    // the direction - what the rank-1 LoRA does to attn_output_b / ffn_down_shexp / ffn_down_exps
    void ablate(const Dev& d, float* y, int T, cudaStream_t s) const {
        if (d.abl_r != nullptr) project_out(y, d.abl_r, abl_scale, g.dim, T, s);
    }
    static const Layer& member(const Layer& l, int m) { return m == 0 ? l : l.mates[(size_t) m - 1]; }
    // bytes of a VRAM slot of l's experts (a member's part of each, in a group)
    static size_t unit(const Layer& l) { return l.nm > 1 ? l.hblob : l.blob; }
    // v1.1.18's prompt-path changes (the borrowed room and its chunk default, a short run's reads through the page cache,
    // the decode warm-up) by default on one GPU, where they were measured; on more as in v1.1.17 unless setting k
    // asks (1 on, 0 off)
    bool one_gpu_or(const char* k) const {
        const char* v = std::getenv(k);
        return v != nullptr ? std::atoi(v) != 0 : devs.size() == 1;
    }
    // DS4_TP_BORROW=1 (off by default): a tensor-parallel group's members lend the prompt path their experts' room too
    // (Chunk::tp_lend) - on the flow only (DS4_FLOW_TP=1), which streams the lent slots' experts, each member its part
    static bool tp_borrow_on() {
        const auto on = [](const char* v) { return v != nullptr && std::atoi(v) != 0; };
        return on(ds4_env("DS4_TP_BORROW")) && on(std::getenv("DS4_FLOW_TP"));
    }
    // VRAM slot s of layer l, member x's part of it: u bytes a slot in its own allocation, the tail's xstep apart
    static uint8_t* sat(const Layer& l, const Layer& x, int s, size_t u) {
        if (!l.maddr.empty()) return l.maddr[(size_t) s];   // (a mixed layer: slot s = expert s, in its class's arena)
        return s < l.n_main ? x.vram_base + (size_t) s * u : x.xbase + (size_t) (s - l.n_main) * x.xstep;
    }
    // the members of a group of nm that take heads: the most the heads and the wo_a groups split among evenly (64
    // heads and 8 groups: 9 -> 8, 7 or 6 -> 4, 5 -> 4, 3 -> 2); the first members the rest, only their FFN share
    int head_members(int nm) const {
        int na = nm;
        while (na > 1 && (g.heads % na != 0 || g.o_groups % na != 0)) --na;
        return na;
    }
    // host-mapped memory (the same address on the host and every device), zeroed
    template <class T>
    bool hmap(T*& p, size_t n, std::string& err) {
        void* v = nullptr;
        if (cudaHostAlloc(&v, n * sizeof(T) + 64, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
            err = "host-mapped memory (" + std::to_string((n * sizeof(T)) >> 20) + " MiB)";
            return false;
        }
        std::memset(v, 0, n * sizeof(T) + 64);
        host_allocs.push_back(v);
        p = (T*) v;
        return true;
    }
    template <class T>
    bool halloc(T*& p, size_t n, std::string& err) {
        void* v = nullptr;
        if (cudaHostAlloc(&v, n * sizeof(T) + 64, cudaHostAllocPortable) != cudaSuccess) {
            err = "cudaHostAlloc " + std::to_string((n * sizeof(T)) >> 20) + " MiB failed";
            return false;
        }
        host_allocs.push_back(v);
        p = (T*) v;
        return true;
    }

    // ---- weights
    bool upload(Dev& d, const Tensor& t, void* dst, std::string& err) {
        std::vector<uint8_t> tmp(t.bytes);
        if (!pk.read(t, tmp.data())) {
            err = "read failed";
            return false;
        }
        cudaSetDevice(d.id);
        CK(cudaMemcpy(dst, tmp.data(), t.bytes, cudaMemcpyHostToDevice));
        return true;
    }
    // a GGUF's BF16 or Q8_0 matrix ([out][in]) onto the device, as mat() takes an EXL3 one: whole, or part `part` of its
    // columns (outputs: a range of its rows) or of its rows (inputs: a range of each row, whole Q8_0 blocks) - a
    // standalone [n][k] matrix; r0 >= 0: the range [r0, r0 + rn) instead of an even part (DS4_TP_GGUF_UNEVEN's shared
    // expert: its member's FFN range)
    bool mat_bf16(Dev& d, const std::string& pre, const Tensor& t, x3::Mat& m, std::string& err, size_t* acct, int part,
                  int np, bool cols, int r0 = -1, int rn = 0) {
        const bool q8 = t.dtype == "Q8_0";
        // a low-bit dense matrix (a GGUF's Q5_K, say): ds4_iq's GEMV for a token, its FP16 rows for a prompt
        const int lb = q8 || t.dtype == "BF16" ? -1 : gg_type_of(t.dtype);
        const int per = q8 ? 32 : lb > 0 ? 256 : 1;
        if (t.shape.size() != 2 || t.shape[1] % per != 0 || lb == gg::kTypeMXFP4) {
            err = pre + ": a " + t.dtype + " tensor that is not a matrix";
            return false;
        }
        int n = (int) t.shape[0], k = (int) t.shape[1];
        // a row's bytes, and the bytes of v of its values (BF16: 2 each; Q8_0: 34 every 32; a low-bit type: its block's
        // every 256)
        auto bytes_of = [&](size_t v) {
            return q8 ? v / 32 * gg::kQ8Bytes : lb > 0 ? v / 256 * (size_t) gg::iq::block_bytes(lb) : v * 2;
        };
        std::vector<uint8_t> w((size_t) n * bytes_of((size_t) k));
        if (t.bytes != w.size() || !pk.read(t, w.data())) {
            err = pre + ": read failed";
            return false;
        }
        if (np > 1) {
            const int whole = cols ? n : k;
            int wd = r0 >= 0 ? rn : whole / np, w0 = r0 >= 0 ? r0 : part * wd;
            const int q = q8 ? 32 : lb > 0 && !cols ? 256 : 8;   // (a low-bit type's inputs: whole blocks)
            // outputs that do not split evenly (a 129280-column head over 3): split128's shares, as head_cols takes them
            const bool uneven = r0 < 0 && cols && whole % np != 0 && whole % 128 == 0 && whole / 128 >= np;
            if (uneven)
                split128(whole, np, part, w0, wd);
            else if ((r0 < 0 && whole % np != 0) || wd % q != 0 || w0 % q != 0 || w0 + wd > whole || wd <= 0) {
                err = pre + ": " + std::to_string(whole) + (cols ? " outputs" : " inputs") + " do not split in " +
                      (r0 >= 0 ? "[" + std::to_string(w0) + ", " + std::to_string(w0 + wd) + ")"
                               : std::to_string(np) + " parts");
                return false;
            }
            const size_t rb = bytes_of((size_t) k);
            std::vector<uint8_t> p;
            if (cols) {
                p.assign(w.begin() + (long) ((size_t) w0 * rb), w.begin() + (long) ((size_t) (w0 + wd) * rb));
                n = wd;
            } else {
                const size_t pb = bytes_of((size_t) wd);
                p.resize((size_t) n * pb);
                for (size_t r = 0; r < (size_t) n; ++r)
                    std::memcpy(p.data() + r * pb, w.data() + r * rb + bytes_of((size_t) w0), pb);
                k = wd;
            }
            w.swap(p);
        }
        // MAYA_DS4_DENSE_REQ=q5_k|q4_k|iq4_xs (opt-in, CHANGES THE ANSWERS): the Q8_0 dense matrices
        // MAYA_DS4_DENSE_REQ_MATCH names (default the attention's three largest: attn.wq_b, attn.wo_a, attn.wo_b)
        // re-quantized at load by ggml's quantizer - fewer bytes every token reads, and VRAM the experts then take.
        // They then run as a GGUF's low-bit dense matrix does (ds4_iq's GEMV, its FP16 rows for a prompt)
        const int rq = q8 ? dense_req_type(pre) : -1;
        bool req = false;
        if (rq >= 0) {
            std::vector<uint8_t> o;
            std::string e2;
            const double t0 = now_ms();
            // the converted bytes kept in the pack (<pack>/dense-req-<type>/<name>.bin, a header with the source's size
            // and a sampled checksum): a later start reads them instead of converting again
            const std::string dir = this->o.pack + "/dense-req-" + dense_req_name(),
                              file = dir + "/" + pre + (np > 1 ? "." + std::to_string(part) + "-of-" + std::to_string(np) +
                                                                     (r0 >= 0 ? "." + std::to_string(r0) : "")
                                                               : "") + ".bin";
            uint64_t sum = 1469598103934665603ull;
            for (size_t i = 0; i < w.size(); i += 4093) sum = (sum ^ w[i]) * 1099511628211ull;
            const uint64_t hdr[4] = {0x31515244ull /* DRQ1 */, (uint64_t) w.size(), sum, (uint64_t) rq};
            const size_t want = (size_t) n * (size_t) gg::iq::block_bytes(rq) * (size_t) (k / 256);
            bool cached = false;
            if (std::FILE* f = std::fopen(file.c_str(), "rb")) {
                uint64_t h[4] = {};
                if (std::fread(h, 8, 4, f) == 4 && std::memcmp(h, hdr, sizeof hdr) == 0) {
                    o.resize(want);
                    cached = std::fread(o.data(), 1, o.size(), f) == o.size();
                }
                std::fclose(f);
            }
            const bool ok = cached || (k % 256 == 0 && gg::dense_requant(w.data(), n, k, rq, o, e2) && o.size() == want);
            if (ok && !cached) {   // (kept for the next start; a failed write only costs the conversion then)
                std::error_code ec;
                std::filesystem::create_directories(dir, ec);
                const std::string tmp = file + ".tmp";
                if (std::FILE* f = std::fopen(tmp.c_str(), "wb")) {
                    const bool wr = std::fwrite(hdr, 8, 4, f) == 4 && std::fwrite(o.data(), 1, o.size(), f) == o.size();
                    std::fclose(f);
                    if (!wr || !os::replace_file(tmp, file)) std::remove(tmp.c_str());
                }
            }
            if (ok) {
                dense_req_saved += (double) w.size() - (double) o.size();
                dense_req_ms += now_ms() - t0;
                ++dense_req_n;
                dense_req_cached += cached ? 1 : 0;
                w.swap(o);
                req = true;
            } else {   // (a reason once: a build without ggml says it for every matrix)
                const std::string why = e2.empty() ? "its rows do not split in 256-value blocks" : e2;
                if (why != dense_req_why) {
                    std::fprintf(stderr, "ds4: MAYA_DS4_DENSE_REQ: %s stays Q8_0 (%s)\n", pre.c_str(), why.c_str());
                    dense_req_why = why;
                }
            }
        }
        uint8_t* dp = nullptr;
        if (!dalloc(d, dp, w.size(), err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(dp, w.data(), w.size(), cudaMemcpyHostToDevice));
        m = x3::Mat{};
        m.fmt = req ? gg::kFmtGG : q8 ? gg::kFmtQ8_0 : lb > 0 ? gg::kFmtGG : gg::kFmtBF16;
        m.gg_type = req ? rq : lb > 0 ? lb : 0;
        m.raw = dp;
        m.k = k;
        m.n = n;
        m.ld = req ? (int) ((size_t) gg::iq::block_bytes(rq) * (size_t) (k / 256))
                   : q8 || lb > 0 ? (int) bytes_of((size_t) k) : k;
        return true;
    }
    // (MAYA_DS4_DENSE_REQ) the ggml type a dense matrix `pre` is re-quantized to, -1: kept as it is
    double dense_req_saved = 0, dense_req_ms = 0;
    int dense_req_n = 0, dense_req_cached = 0;
    std::string dense_req_why;   // (the last reason a matrix stayed Q8_0, logged once)
    // (MAYA_DS4_DENSE_REQ in a config, read as STRATA_DS4_DENSE_REQ; DS4_DENSE_REQ also taken)
    static const char* dense_req_env(const char* name) {
        const char* v = std::getenv((std::string("STRATA_") + name).c_str());
        return v != nullptr ? v : std::getenv(name);
    }
    static const char* dense_req_name() {
        const char* v = dense_req_env("DS4_DENSE_REQ");
        return v != nullptr ? v : "";
    }
    static int dense_req_type(const std::string& pre) {
        static const int t = [] {
            const char* v = dense_req_env("DS4_DENSE_REQ");
            if (v == nullptr || *v == 0 || std::string(v) == "off") return -1;
            const std::string s(v);
            const int r = s == "q5_k" ? gg::iq::kQ5_K : s == "q4_k" ? gg::iq::kQ4_K : s == "iq4_xs" ? gg::iq::kIQ4_XS : -1;
            if (r < 0) std::fprintf(stderr, "ds4: MAYA_DS4_DENSE_REQ=%s not known (q5_k, q4_k, iq4_xs): the dense matrices stay Q8_0\n",
                                    v);
            return r;
        }();
        if (t < 0) return -1;
        static const std::vector<std::string> names = [] {
            const char* v = dense_req_env("DS4_DENSE_REQ_MATCH");
            std::string s = v != nullptr ? v : "attn.wq_b,attn.wo_a,attn.wo_b";
            std::vector<std::string> out;
            for (size_t a = 0; a <= s.size();) {
                const size_t b = s.find(',', a);
                const std::string x = s.substr(a, b == std::string::npos ? std::string::npos : b - a);
                if (!x.empty()) out.push_back(x);
                if (b == std::string::npos) break;
                a = b + 1;
            }
            return out;
        }();
        for (const std::string& x : names)
            if (pre.find(x) != std::string::npos) return t;
        return -1;
    }
    // a Q5_K superblock's 256 values as F32 (host): ggml's dequantize_row_q5_K (get_scale_min_k4's scales)
    // (q5k_values: ds4_q6k.cuh's, the Q5_K token embedding's host decode)
    // a GGUF dense matrix mat_bf16 takes: BF16, Q8_0, or a low-bit type ds4_iq reads (not MXFP4: experts only)
    static bool gguf_dense(const std::string& dtype) {
        const int t = dtype == "BF16" || dtype == "Q8_0" ? 0 : gg_type_of(dtype);
        return t == 0 || (t > 0 && t != gg::kTypeMXFP4);
    }
    // a Q8_0 tensor's values as F32 (host)
    static std::vector<float> q8_values(const uint8_t* q, size_t n) {
        std::vector<float> v(n);
        for (size_t b = 0; b < n / 32; ++b) {
            const uint8_t* p = q + b * gg::kQ8Bytes;
            const float d = f16_to_f32((uint16_t) (p[0] | p[1] << 8));
            for (int j = 0; j < 32; ++j) v[b * 32 + j] = d * (float) (int8_t) p[2 + j];
        }
        return v;
    }
    // an EXL3 matrix onto the device: whole, or (np > 1) part `part` of its columns (cols) or of its rows - a standalone
    // matrix of its own (the rotations' 128-blocks stay whole)
    // (rot: split128's - an EXL3 matrix's uneven 128-block shares going round the members; a GGUF's BF16 / Q8_0 matrix
    // splits evenly, its groups only as wide as that goes)
    bool mat(Dev& d, const std::string& pre, x3::Mat& m, std::string& err, size_t* acct, int part = 0, int np = 1,
             bool cols = true, int rot = 0, int r0 = -1, int rn = 0) {
        if (const Tensor* tw = pk.get(pre + ".weight"); tw != nullptr && gguf_dense(tw->dtype))
            return mat_bf16(d, pre, *tw, m, err, acct, part, np, cols, r0, rn);
        if (r0 >= 0) {   // (an explicit range: a BF16 / Q8_0 matrix's only - an EXL3 one splits by split128's rot)
            err = pre + ": an explicit range of a matrix that is not BF16 or Q8_0";
            return false;
        }
        const Tensor* tr = pk.get(pre + ".trellis");
        const Tensor* su = pk.get(pre + ".suh");
        const Tensor* sv = pk.get(pre + ".svh");
        if (tr == nullptr || su == nullptr || sv == nullptr || tr->shape.size() != 3) {
            err = pre + ": not an EXL3 matrix in the pack";
            return false;
        }
        if (pk.get(pre + ".mul1") == nullptr) {
            err = pre + ": only the mul1 codebook is covered";
            return false;
        }
        m.k = (int) tr->shape[0] * 16;
        m.n = (int) tr->shape[1] * 16;
        m.k2 = (int) tr->shape[2] / 8;
        m.cb = 2;
        m.ld = 0;
        if (np > 1) {
            const int whole = cols ? m.n : m.k;
            int at = 0, w = 0;
            if (whole % 128 != 0 || whole / 128 < np) {
                err = pre + ": " + std::to_string(whole) + (cols ? " columns" : " rows") + " do not split in " +
                      std::to_string(np) + " parts of 128-blocks";
                return false;
            }
            split128(whole, np, part, at, w, rot);
            std::vector<uint8_t> t0(tr->bytes), u0(su->bytes), v0(sv->bytes);
            if (!pk.read(*tr, t0.data()) || !pk.read(*su, u0.data()) || !pk.read(*sv, v0.data())) {
                err = pre + ": read failed";
                return false;
            }
            const size_t tile = tr->bytes / ((size_t) (m.k / 16) * (m.n / 16));
            std::vector<uint8_t> t1, u1, v1;
            if (cols) {   // the tiles [c0 / 16, (c0 + w) / 16) of each 16-row slice, svh [c0, c0 + w)
                const size_t c0 = (size_t) at, nt = (size_t) m.n / 16, nth = (size_t) w / 16;
                t1.resize((size_t) (m.k / 16) * nth * tile);
                for (size_t sl = 0; sl < (size_t) m.k / 16; ++sl)
                    std::memcpy(t1.data() + sl * nth * tile, t0.data() + (sl * nt + c0 / 16) * tile, nth * tile);
                u1 = u0;
                v1.assign(v0.begin() + (long) (c0 * 2), v0.begin() + (long) ((c0 + w) * 2));
                m.n = w;
            } else {      // the 16-row slices [r0 / 16, (r0 + w) / 16), suh [r0, r0 + w)
                const size_t r0 = (size_t) at, row = (size_t) (m.n / 16) * tile;
                t1.assign(t0.begin() + (long) (r0 / 16 * row), t0.begin() + (long) ((r0 + w) / 16 * row));
                u1.assign(u0.begin() + (long) (r0 * 2), u0.begin() + (long) ((r0 + w) * 2));
                v1 = v0;
                m.k = w;
            }
            uint32_t* dt = nullptr;
            uint16_t *ds = nullptr, *dv = nullptr;
            if (!dalloc(d, dt, t1.size() / 4, err, acct) || !dalloc(d, ds, u1.size() / 2, err, acct) ||
                !dalloc(d, dv, v1.size() / 2, err, acct))
                return false;
            cudaSetDevice(d.id);
            CK(cudaMemcpy(dt, t1.data(), t1.size(), cudaMemcpyHostToDevice));
            CK(cudaMemcpy(ds, u1.data(), u1.size(), cudaMemcpyHostToDevice));
            CK(cudaMemcpy(dv, v1.data(), v1.size(), cudaMemcpyHostToDevice));
            m.trellis = dt;
            m.suh = ds;
            m.svh = dv;
            return x3::supported(m) || (err = pre + ": a part not covered by the EXL3 kernels", false);
        }
        uint32_t* dt = nullptr;
        uint16_t *ds = nullptr, *dv = nullptr;
        if (!dalloc(d, dt, tr->bytes / 4, err, acct) || !dalloc(d, ds, su->bytes / 2, err, acct) ||
            !dalloc(d, dv, sv->bytes / 2, err, acct))
            return false;
        if (!upload(d, *tr, dt, err) || !upload(d, *su, ds, err) || !upload(d, *sv, dv, err)) return false;
        m.trellis = dt;
        m.suh = ds;
        m.svh = dv;
        if (!x3::supported(m)) {
            err = pre + ": k " + std::to_string(m.k) + " n " + std::to_string(m.n) + " K " + std::to_string(m.k2 / 2) +
                  (m.k2 & 1 ? ".5" : "") + " not covered by the EXL3 kernels";
            return false;
        }
        return true;
    }
    // a float tensor (F32 / F16 / BF16) as F32 on the device
    bool f32(Dev& d, const std::string& name, float*& p, std::string& err, size_t* acct, size_t want = 0) {
        const Tensor* t = pk.get(name);
        if (t == nullptr) {
            err = name + ": not in the pack";
            return false;
        }
        std::vector<uint8_t> raw(t->bytes);
        if (!pk.read(*t, raw.data())) {
            err = name + ": read failed";
            return false;
        }
        size_t n = 0;
        std::vector<float> v;
        if (t->dtype == "F32") {
            n = t->bytes / 4;
            v.resize(n);
            std::memcpy(v.data(), raw.data(), t->bytes);
        } else if (t->dtype == "F16" || t->dtype == "BF16") {
            n = t->bytes / 2;
            v.resize(n);
            const uint16_t* s = (const uint16_t*) raw.data();
            for (size_t i = 0; i < n; ++i) v[i] = t->dtype == "F16" ? f16_to_f32(s[i]) : bf16_to_f32(s[i]);
        } else if (t->dtype == "Q8_0") {   // (a GGUF's router may come so)
            n = t->bytes / gg::kQ8Bytes * 32;
            v = q8_values(raw.data(), n);
        } else {
            err = name + ": dtype " + t->dtype + " is not a float";
            return false;
        }
        if (want != 0 && n != want) {
            err = name + ": " + std::to_string(n) + " values, expected " + std::to_string(want);
            return false;
        }
        if (!dalloc(d, p, n, err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(p, v.data(), n * 4, cudaMemcpyHostToDevice));
        return true;
    }
    bool f16raw(Dev& d, const std::string& name, uint16_t*& p, std::string& err, size_t* acct) {
        const Tensor* t = pk.get(name);
        if (t != nullptr && (t->dtype == "F32" || t->dtype == "BF16" || t->dtype == "Q8_0")) {   // (a GGUF's)
            const size_t n = t->dtype == "Q8_0" ? t->bytes / gg::kQ8Bytes * 32 : t->bytes / (t->dtype == "F32" ? 4 : 2);
            std::vector<uint8_t> raw(t->bytes);
            if (!pk.read(*t, raw.data())) {
                err = name + ": read failed";
                return false;
            }
            const std::vector<float> q = t->dtype == "Q8_0" ? q8_values(raw.data(), n) : std::vector<float>();
            std::vector<uint16_t> h(n);
            for (size_t i = 0; i < n; ++i) {
                float v;
                if (t->dtype == "F32") std::memcpy(&v, raw.data() + i * 4, 4);
                else if (t->dtype == "Q8_0") v = q[i];
                else v = bf16_to_f32(((const uint16_t*) raw.data())[i]);
                h[i] = strata::kernels::f16_from_f32(v);
            }
            if (!dalloc(d, p, n, err, acct)) return false;
            cudaSetDevice(d.id);
            CK(cudaMemcpy(p, h.data(), n * 2, cudaMemcpyHostToDevice));
            return true;
        }
        if (t == nullptr || t->dtype != "F16") {
            err = name + ": not an F16 tensor in the pack";
            return false;
        }
        if (!dalloc(d, p, t->bytes / 2, err, acct)) return false;
        return upload(d, *t, p, err);
    }

    size_t mat_bytes(const std::string& pre) const {
        if (const Tensor* t = pk.get(pre + ".weight")) return align256(t->bytes);
        size_t b = 0;
        for (const char* s : {".trellis", ".suh", ".svh"})
            if (const Tensor* t = pk.get(pre + s)) b += align256(t->bytes);
        return b;
    }
    size_t tensor_bytes(const std::string& name) const {
        const Tensor* t = pk.get(name);
        return t ? align256(t->bytes * (t->dtype == "F32" ? 1 : 2)) : 0;
    }

    // ---- expert regions and blob layout
    // a GGUF's MXFP4 experts: the blob is gate | up | down ([out][in / 32] blocks each, as the file holds them), every
    // expert's matrix r at the same stride from expert 0's in one file (the GGUF's [n_exp][out][in] tensor)
    // (the other block types: lay.fmt stays kFmtMXFP4 - read in place as these - and lay.gg_type[r] is role r's ggml
    // type)
    static int gg_type_of(const std::string& dtype) {
        for (int t : {gg::kTypeMXFP4, 10, 11, 12, 13, 14, 16, 17, 18, 19, 21, 22, 23, 29})
            if (dtype == gg::type_name(t)) return t;
        return -1;
    }
    bool expert_layout_mx(Layer& l, std::string& err) {
        const std::string P = l.name + "ffn.experts.";
        const char* parts[3] = {"w1", "w3", "w2"};   // gate, up, down
        size_t off = 0;
        for (int r = 0; r < 3; ++r) {
            const int n = r < 2 ? g.ff : g.dim, k = r < 2 ? g.dim : g.ff;
            const Tensor* t0 = pk.get(P + "0." + parts[r] + ".weight");
            const Tensor* t1 = l.n_exp > 1 ? pk.get(P + "1." + parts[r] + ".weight") : t0;
            const int ty = t0 != nullptr ? gg_type_of(t0->dtype) : -1;
            const size_t bytes = ty > 0 && gg::expert_type_ok(ty) ? (size_t) n * gg::type_row_bytes(ty, k) : 0;
            if (t0 == nullptr || t1 == nullptr || bytes == 0 || t0->bytes != bytes) {
                err = P + "0." + parts[r] + ": not an MXFP4 or low-bit [" + std::to_string(n) + "][" + std::to_string(k) +
                      "] matrix the engine reads (" + (t0 != nullptr ? t0->dtype : std::string("missing")) + ")";
                return false;
            }
            l.mx_file[r] = t0->file;
            l.mx_off[r] = t0->off;
            l.mx_stride[r] = l.n_exp > 1 ? t1->off - t0->off : bytes;
            for (int e = 0; e < l.n_exp; ++e) {
                const Tensor* t = pk.get(P + std::to_string(e) + "." + parts[r] + ".weight");
                if (t == nullptr || t->dtype != t0->dtype || t->bytes != bytes || t->file != l.mx_file[r] ||
                    t->off != l.mx_off[r] + (uint64_t) e * l.mx_stride[r]) {
                    err = P + std::to_string(e) + "." + parts[r] + ": missing, or not where the layer's others are";
                    return false;
                }
            }
            l.lay.trellis[r] = off;
            l.lay.suh[r] = l.lay.svh[r] = off;
            l.lay.gg_type[r] = ty;
            off += align256(bytes);
        }
        l.lay.fmt = gg::kFmtMXFP4;
        // (the down may be of another type than gate / up, MXFP4 beside a low-bit one too: each role takes its own
        //  kernels - orcarouter's mixes put MXFP4 downs under IQ3 gate / ups)
        if (gg::expert_type(l.lay, 0) != gg::expert_type(l.lay, 1)) {
            err = P + ": gate / up / down of types " + gg::type_name(l.lay.gg_type[0]) + " / " +
                  gg::type_name(l.lay.gg_type[1]) + " / " + gg::type_name(l.lay.gg_type[2]) + " (gate and up must match)";
            return false;
        }
        l.blob = off;
        return true;
    }
    const uint8_t* mx_mat(const Layer& l, int e, int r) const {   // expert e's matrix r: its RAM-tier slot, else the file's
        if (!l.ram.empty() && l.ram[(size_t) e] >= 0)   // (a copy with NH > 1: part 0's rows only - whole: read_mx)
            return copy_mode ? ram_part[(size_t) l.ram[(size_t) e]][0] + cp_lay[(size_t) l.il][(size_t) r]
                             : ram_slots[(size_t) l.ram[(size_t) e]] + l.lay.trellis[r];
        return pk.at(l.mx_file[r], l.mx_off[r] + (uint64_t) e * l.mx_stride[r]);
    }
    size_t mx_part_bytes(const Layer& l, int r) const {   // (its type's)
        return r < 2 ? (size_t) g.ff * gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim)
                     : (size_t) g.dim * gg::type_row_bytes(gg::expert_type(l.lay, 2), g.ff);
    }
    // (copy_mode) matrix r's rows, and the rows of one NUMA part of it
    int mx_n(int r) const { return r < 2 ? g.ff : g.dim; }
    size_t mx_row_b(const Layer& l, int r) const { return mx_part_bytes(l, r) / (size_t) mx_n(r); }
    // part X's rows [X n / NH, ..) of expert e's matrix r: its copy's part on node X, else where the file has them
    const uint8_t* mx_part_ptr(const Layer& l, int e, int r, int X) const {
        if (copy_mode && l.ram[(size_t) e] >= 0)
            return ram_part[(size_t) l.ram[(size_t) e]][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r];
        return mx_mat(l, e, r) + (size_t) X * (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
    }
    // a copy's NH parts -> the blob, and back (each matrix's rows of part X at X n / NH rows into the blob's matrix)
    void ram_to_blob(const Layer& l, int s, uint8_t* blob) const {
        for (int r = 0; r < 3; ++r) {
            const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
            for (int X = 0; X < NH; ++X)
                std::memcpy(blob + l.lay.trellis[r] + (size_t) X * nb, ram_part[(size_t) s][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r], nb);
        }
    }
    void blob_to_ram(const Layer& l, const uint8_t* blob, int s) const {
        for (int r = 0; r < 3; ++r) {
            const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
            for (int X = 0; X < NH; ++X)
                std::memcpy(ram_part[(size_t) s][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r], blob + l.lay.trellis[r] + (size_t) X * nb, nb);
        }
    }
    // expert e (from the file) -> its blob; and member m of nm's part of a blob (gate / up rows [m n_ff / nm, ..), down
    // inputs of the same range: in each row the blocks [m n_ff / nm / 32, ..)) and back
    bool read_mx(const Layer& l, int e, uint8_t* blob) const {   // (from its RAM-tier slot or copy when it has one)
        if (!l.ram.empty() && l.ram[(size_t) e] >= 0) {
            if (copy_mode) ram_to_blob(l, l.ram[(size_t) e], blob);
            else std::memcpy(blob, ram_slots[(size_t) l.ram[(size_t) e]], l.blob);
            return true;
        }
        return read_mx_file(l, e, blob);
    }
    bool read_mx_file(const Layer& l, int e, uint8_t* blob) const {   // (the movers: never a slot that may change)
        for (int r = 0; r < 3; ++r)
            if (!pk.read_at(l.mx_file[r], l.mx_off[r] + (uint64_t) e * l.mx_stride[r], mx_part_bytes(l, r),
                            blob + l.lay.trellis[r]))
                return false;
        return true;
    }
    // (l the group's first member: member m's own range [ff0, ff0 + ffn) and its own layout - whole blocks of the
    //  down's inputs, even or not)
    void mx_blob_to_half(const Layer& l, const uint8_t* blob, int m, uint8_t* dst) const {
        const Layer& x = member(l, m);
        const size_t dr = gg::type_row_bytes(gg::expert_type(l.lay, 2), g.ff),
                     d0 = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ff0),
                     dh = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn);
        for (int r = 0; r < 2; ++r) {
            const size_t gr = gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim);
            std::memcpy(dst + x.hlay.trellis[r], blob + l.lay.trellis[r] + (size_t) x.ff0 * gr, (size_t) x.ffn * gr);
        }
        for (size_t row = 0; row < (size_t) g.dim; ++row)
            std::memcpy(dst + x.hlay.trellis[2] + row * dh, blob + l.lay.trellis[2] + row * dr + d0, dh);
    }
    void mx_half_to_blob(const Layer& l, const uint8_t* src, int m, uint8_t* blob) const {
        const Layer& x = member(l, m);
        const size_t dr = gg::type_row_bytes(gg::expert_type(l.lay, 2), g.ff),
                     d0 = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ff0),
                     dh = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn);
        for (int r = 0; r < 2; ++r) {
            const size_t gr = gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim);
            std::memcpy(blob + l.lay.trellis[r] + (size_t) x.ff0 * gr, src + x.hlay.trellis[r], (size_t) x.ffn * gr);
        }
        for (size_t row = 0; row < (size_t) g.dim; ++row)
            std::memcpy(blob + l.lay.trellis[2] + row * dr + d0, src + x.hlay.trellis[2] + row * dh, dh);
    }
    // expert e -> member m's part (l the group's first member), as mx_blob_to_half cuts it: from its RAM-tier copy or
    // slot each run of rows from the NUMA part holding it, else its blob read from the file and cut in place (every
    // piece moves down: x.hlay's offsets are at most l.lay's, dh at most dr) - the prompt path's staging, one DMA
    // of the part where a copy of the whole blob and a 2D copy of the down's rows took ~8x the memcpy and ~35 ms
    bool read_mx_part(const Layer& l, int e, int m, uint8_t* dst) const {
        const Layer& x = member(l, m);
        const size_t dr = gg::type_row_bytes(gg::expert_type(l.lay, 2), g.ff),
                     d0 = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ff0),
                     dh = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn);
        if (l.ram.empty() || l.ram[(size_t) e] < 0) {
            if (!read_mx_file(l, e, dst)) return false;
            for (int r = 0; r < 2; ++r) {
                const size_t gr = mx_row_b(l, r);
                std::memmove(dst + x.hlay.trellis[r], dst + l.lay.trellis[r] + (size_t) x.ff0 * gr, (size_t) x.ffn * gr);
            }
            for (size_t row = 0; row < (size_t) g.dim; ++row)
                std::memmove(dst + x.hlay.trellis[2] + row * dh, dst + l.lay.trellis[2] + row * dr + d0, dh);
            return true;
        }
        for (int r = 0; r < 2; ++r) {   // (rows [ff0, ff0 + ffn): one run from each part they reach into)
            const size_t gr = mx_row_b(l, r);
            const int nr = mx_n(r) / NH;
            for (int X = 0; X < NH; ++X) {
                const int a = std::max(x.ff0, X * nr), b = std::min(x.ff0 + x.ffn, (X + 1) * nr);
                if (a < b)
                    std::memcpy(dst + x.hlay.trellis[r] + (size_t) (a - x.ff0) * gr,
                                mx_part_ptr(l, e, r, X) + (size_t) (a - X * nr) * gr, (size_t) (b - a) * gr);
            }
        }
        mx_down_member(l, e, m, dst + x.hlay.trellis[2]);
        return true;
    }
    // (expert e in RAM) member m's part of its down - the member's blocks of each row, each part's rows - into dst
    void mx_down_member(const Layer& l, int e, int m, uint8_t* dst) const {
        const Layer& x = member(l, m);
        const size_t dr = gg::type_row_bytes(gg::expert_type(l.lay, 2), g.ff),
                     d0 = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ff0),
                     dh = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn);
        const int nr = g.dim / NH;
        for (int X = 0; X < NH; ++X) {
            const uint8_t* p = mx_part_ptr(l, e, 2, X) + d0;
            uint8_t* q = dst + (size_t) X * (size_t) nr * dh;
            for (size_t row = 0; row < (size_t) nr; ++row) std::memcpy(q + row * dh, p + row * dr, dh);
        }
    }

    bool expert_layout(Layer& l, std::string& err) {
        if (const Tensor* t = pk.get(l.name + "ffn.experts.0.w1.weight"); t != nullptr && gg_type_of(t->dtype) > 0)
            return expert_layout_mx(l, err);
        const std::string P = l.name + "ffn.experts.";
        const char* parts[3] = {"w1", "w3", "w2"};   // gate, up, down
        const char* pieces[3] = {".trellis", ".suh", ".svh"};
        l.region_off.resize((size_t) l.n_exp);
        l.region_bytes.resize((size_t) l.n_exp);
        l.region_file.resize((size_t) l.n_exp);
        l.cls.assign((size_t) l.n_exp, 0);
        // each expert's K per part and its pieces' bytes: the experts that agree in them make a class - one for every
        // quant before the mixed-precision ones (a K per expert and part); where an expert's pieces lie in its region
        // is its own (esrc)
        struct Sig {
            int k2[3];
            size_t src[3][3], bytes[3][3];
            bool operator==(const Sig& o) const {
                return std::memcmp(k2, o.k2, sizeof k2) == 0 && std::memcmp(bytes, o.bytes, sizeof bytes) == 0;
            }
        };
        l.esrc.assign((size_t) l.n_exp, {});
        l.esplit.assign((size_t) l.n_exp, 0);
        std::vector<Sig> sigs;
        for (int e = 0; e < l.n_exp; ++e) {
            const std::string E = P + std::to_string(e) + ".";
            uint64_t lo = UINT64_MAX, hi = 0;
            int file = -1;
            bool split = false;
            Sig sg{};
            for (int r = 0; r < 3; ++r) {
                const Tensor* tr = pk.get(E + parts[r] + ".trellis");
                if (tr == nullptr || pk.get(E + parts[r] + ".mul1") == nullptr) {
                    err = E + parts[r] + ": not an EXL3 (mul1) matrix";
                    return false;
                }
                if (tr->shape[2] % 8 != 0 || !x3::k2_supported((int) tr->shape[2] / 8, 2)) {
                    err = E + parts[r] + ": " + std::to_string(tr->shape[2]) +
                          " int16 a tile - the kernels take K 1..8 and 1.5 / 2.5 / 3.5 (mul1)";
                    return false;
                }
                sg.k2[r] = (int) tr->shape[2] / 8;
                for (int q = 0; q < 3; ++q) {
                    const Tensor* t = pk.get(E + parts[r] + pieces[q]);
                    if (t == nullptr) {
                        err = E + parts[r] + pieces[q] + ": missing";
                        return false;
                    }
                    if (file < 0) file = t->file;
                    split = split || t->file != file;   // (a mixed quant's shards can cut an expert: read by pieces)
                    lo = std::min(lo, t->off);
                    hi = std::max(hi, t->off + t->bytes);
                    sg.bytes[r][q] = t->bytes;
                }
            }
            {   // (pieces far apart in their file - other tensors between them: read piece by piece too, not the span)
                uint64_t sum = 0;
                for (int r = 0; r < 3; ++r)
                    for (int q = 0; q < 3; ++q) sum += sg.bytes[r][q];
                split = split || hi - lo > 2 * sum + (1u << 20);
            }
            uint64_t cut = 0;   // (an expert across two files: a region of its pieces back to back, read piece by piece)
            for (int r = 0; r < 3; ++r)
                for (int q = 0; q < 3; ++q) {
                    sg.src[r][q] = split ? cut : pk.get(E + parts[r] + pieces[q])->off - lo;
                    cut += sg.bytes[r][q];
                    l.esrc[(size_t) e][(size_t) (r * 3 + q)] = sg.src[r][q];
                }
            l.region_off[(size_t) e] = split ? pk.get(E + "w1.trellis")->off : lo;
            l.region_bytes[(size_t) e] = split ? cut : hi - lo;
            l.region_file[(size_t) e] = file;
            l.esplit[(size_t) e] = split ? 1 : 0;
            size_t c = 0;
            while (c < sigs.size() && !(sigs[c] == sg)) ++c;
            if (c == sigs.size()) {
                if (sigs.size() == (size_t) x3::kMaxClasses) {
                    err = P + ": more than " + std::to_string(x3::kMaxClasses) + " expert layouts in one layer";
                    return false;
                }
                sigs.push_back(sg);
            }
            l.cls[(size_t) e] = (uint8_t) c;
        }
        l.n_cls = (int) sigs.size();
        if (l.n_cls == 1)   // (one layout: the CPU lane reads every expert's pieces where expert 0's lie, in one file)
            for (int e = 0; e < l.n_exp; ++e)
                if (l.esrc[(size_t) e] != l.esrc[0] || l.esplit[(size_t) e]) {
                    err = P + std::to_string(e) + (l.esplit[(size_t) e] ? ": split across files"
                                                                        : ": the pieces lie differently from expert 0's");
                    return false;
                }
        size_t bmax = 0;
        for (int c = 0; c < l.n_cls; ++c) {
            const Sig& sg = sigs[(size_t) c];
            x3::ExpertLayout& lay = l.clay[c];
            lay = x3::ExpertLayout{};
            size_t off = 0;
            for (int r = 0; r < 3; ++r) {
                lay.k2[r] = sg.k2[r];
                lay.trellis[r] = off;
                off += align256(sg.bytes[r][0]);
                lay.suh[r] = off;
                off += align256(sg.bytes[r][1]);
                lay.svh[r] = off;
                off += align256(sg.bytes[r][2]);
                for (int q = 0; q < 3; ++q) {
                    l.cpiece_src[c][r][q] = sg.src[r][q];
                    l.cpiece_bytes[c][r][q] = sg.bytes[r][q];
                }
            }
            lay.cb = 2;
            l.cblob[c] = off;
            bmax = std::max(bmax, off);
            if (l.n_cls > 1 && !x3::mixed_supported(lay)) {
                err = P + ": a mixed-precision layer's experts at K " + std::to_string(sg.k2[0] / 2.0) + " / " +
                      std::to_string(sg.k2[1] / 2.0) + " / " + std::to_string(sg.k2[2] / 2.0) +
                      " - its kernels take K 1, 2, 3 or 4";
                return false;
            }
        }
        // class 0 as the layer's layout (the one-layout paths' fields); blob: the largest class's (staging)
        l.lay = l.clay[0];
        l.blob = bmax;
        std::memcpy(l.piece_src, l.cpiece_src[0], sizeof l.piece_src);
        std::memcpy(l.piece_bytes, l.cpiece_bytes[0], sizeof l.piece_bytes);
        if (l.n_cls > 1 && (o.verbose || l.il == 0)) {
            std::fprintf(stderr, "ds4: %s experts in %d layouts (a mixed-precision quant):", l.name.c_str(), l.n_cls);
            for (int c = 0; c < l.n_cls; ++c) {
                int n = 0;
                for (uint8_t x : l.cls) n += x == c;
                std::fprintf(stderr, " %d at K %g/%g/%g", n, l.clay[c].k2[0] / 2.0, l.clay[c].k2[1] / 2.0,
                             l.clay[c].k2[2] / 2.0);
            }
            std::fprintf(stderr, "\n");
        }
        return true;
    }

    // the region of expert e (read from the file) -> its blob
    // (a mixed layer: expert e's class's layout and pieces)
    void repack(const Layer& l, int e, const uint8_t* region, uint8_t* blob) const {
        const int c = l.n_cls > 1 ? l.cls[(size_t) e] : 0;
        const x3::ExpertLayout& lay = l.n_cls > 1 ? l.clay[c] : l.lay;
        for (int r = 0; r < 3; ++r) {
            const size_t dst[3] = {lay.trellis[r], lay.suh[r], lay.svh[r]};
            for (int q = 0; q < 3; ++q)
                std::memcpy(blob + dst[q], region + (l.n_cls > 1 ? l.esrc[(size_t) e][(size_t) (r * 3 + q)] : l.piece_src[r][q]),
                            l.n_cls > 1 ? l.cpiece_bytes[c][r][q] : l.piece_bytes[r][q]);
        }
    }
    // an expert across two files (esplit): its pieces, each from its own file, into its region where esrc puts them
    bool read_split(const Layer& l, int e, uint8_t* region) const {
        static const char* parts[3] = {"w1", "w3", "w2"};
        static const char* pieces[3] = {".trellis", ".suh", ".svh"};
        const std::string E = l.name + "ffn.experts." + std::to_string(e) + ".";
        for (int r = 0; r < 3; ++r)
            for (int q = 0; q < 3; ++q) {
                const Tensor* t = pk.get(E + parts[r] + pieces[q]);
                if (t == nullptr || !pk.read(*t, region + l.esrc[(size_t) e][(size_t) (r * 3 + q)])) return false;
            }
        return true;
    }
    // bytes of VRAM slot s of l, member x's part (a mixed layer: its expert's class's blob)
    static size_t slot_bytes(const Layer& l, const Layer& x, int s) {
        return l.n_cls > 1 ? l.cblob[l.cls[(size_t) s]] : unit(x);
    }

    // the region of expert e -> its CPU-lane part X (columns [X n / NH, (X + 1) n / NH) of each matrix)
    void repack_part(const Layer& l, const uint8_t* region, int X, uint8_t* dst) const {
        if (l.packed_host) {
            std::vector<uint8_t> blob(l.blob);
            // Packed host slots are restricted to a single expert layout class.
            repack(l, 0, region, blob.data());
            for (int m = 0; m < l.nm; ++m) blob_to_half(l, blob.data(), m, dst + (size_t) m * l.hblob);
            return;
        }
        for (int r = 0; r < 3; ++r) {
            const size_t tile = (size_t) 16 * l.lay.k2[r];
            const int k = l.hl.k[r], nt = l.hl.n[r] * NH / 16, nth = l.hl.n[r] / 16;
            const uint8_t* tr = region + l.piece_src[r][0];
            for (int sl = 0; sl < k / 16; ++sl)
                std::memcpy(dst + l.hl.trellis[r] + (size_t) sl * nth * tile, tr + ((size_t) sl * nt + (size_t) X * nth) * tile,
                            (size_t) nth * tile);
            std::memcpy(dst + l.hl.suh[r], region + l.piece_src[r][1], (size_t) k * 2);
            std::memcpy(dst + l.hl.svh[r], region + l.piece_src[r][2] + (size_t) X * l.hl.n[r] * 2, (size_t) l.hl.n[r] * 2);
        }
    }

    // ---- loading
    bool load(const Options& opt, std::string& err) {
        o = opt;
        const double t0 = now_ms();
        if (!pk.load(o.pack, err)) return false;
        // (AMD: the prompt GEMMs' measured kernels) the pack's lt-picks.txt, or MAYA_DS4_LT_STORE's file - empty: none,
        // each start measures its own and keeps them to itself (a pack that must not change: a run's own store instead)
        const char* lt_store = std::getenv("STRATA_DS4_LT_STORE");
        if (lt_store == nullptr) lt_store = std::getenv("DS4_LT_STORE");
        lt::set_store(lt_store != nullptr ? lt_store : (o.pack + "/lt-picks.txt").c_str());
        g.from(pk);
        if (g.dim == 0 || g.nl == 0 || (int) g.ratios.size() < g.nl) {
            err = o.pack + "/ds4.txt: incomplete geometry";
            return false;
        }
        if (g.hd != 512 || g.ix_hd != 128 || g.k_exp > 8 || g.hc > 8) {
            err = "geometry not covered (head_dim " + std::to_string(g.hd) + ", index_head_dim " +
                  std::to_string(g.ix_hd) + ", experts per token " + std::to_string(g.k_exp) + ")";
            return false;
        }
        freqs_win = rope_freqs(g.rd, 0, g.rope_theta, g.factor, g.beta_fast, g.beta_slow);
        freqs_comp = rope_freqs(g.rd, g.orig_ctx, g.comp_theta, g.factor, g.beta_fast, g.beta_slow);

        // devices
        int ndev = 0;
        if (cudaGetDeviceCount(&ndev) != cudaSuccess || ndev == 0) {
            err = "no CUDA device";
            return false;
        }
        std::vector<int> ids = o.gpus;
        if (ids.empty())
            for (int i = 0; i < ndev; ++i) ids.push_back(i);
        if (!helper_parse(ndev, ids, err)) return false;   // (DS4_HELPER: off the layer devices before any of them)
        if (const char* v = ds4_env("DS4_WARM_CAP_GB")) warm_cap = std::max(0.0, std::atof(v)) * 1e9;
        devs.resize(ids.size());
        if (prof_on) prof_pool.resize((size_t) ndev);
        for (size_t i = 0; i < ids.size(); ++i) {
            Dev& d = devs[i];
            d.id = ids[i];
            CK(cudaSetDevice(d.id));
            // the layers' streams at the device's greatest priority: the expert cache's and the prompt path's other
            // streams (the least, the default) never hold a multiprocessor a layer's kernel could take.
            // DS4_STREAM_PRIO=0: the default priority
            static const bool prio_on =
                std::getenv("DS4_STREAM_PRIO") == nullptr || std::atoi(std::getenv("DS4_STREAM_PRIO")) != 0;
            int least = 0, greatest = 0;
            if (!prio_on || cudaDeviceGetStreamPriorityRange(&least, &greatest) != cudaSuccess) {
                cudaGetLastError();
                greatest = 0;
            }
            CK(cudaStreamCreateWithPriority(&d.st, cudaStreamNonBlocking, greatest));
            CK(cudaEventCreateWithFlags(&d.ev, cudaEventDisableTiming));
            CK(cudaStreamCreateWithPriority(&d.st2, cudaStreamNonBlocking, greatest));
            CK(cudaEventCreateWithFlags(&d.hc_go, cudaEventDisableTiming));
            CK(cudaEventCreateWithFlags(&d.hc_done, cudaEventDisableTiming));
            if (!x3::prepare(d.st) || (pk.gguf && !gg::prepare(d.st))) {
                err = "exl3 scratch on CUDA" + std::to_string(d.id);
                return false;
            }
            CK(mem_info(&d.free0, &d.total));
        }
        // abliteration: the direction read once, a copy on every device (projected out at each hc_post: ablate())
        if (!o.ablate.empty() && !o.vision_only) {
            abl_scale = o.ablate_scale;
            if (!ablate::load_direction(o.ablate, o.ablate_layer, g.nl, abl_scale, abl_dir, abl_what, err)) return false;
            if ((int) abl_dir.size() != g.dim) {
                err = o.ablate + ": direction of " + std::to_string(abl_dir.size()) + " values, the model's dim is " +
                      std::to_string(g.dim);
                return false;
            }
            for (Dev& d : devs) {
                if (!dalloc(d, d.abl_r, abl_dir.size(), err)) return false;
                CK(cudaSetDevice(d.id));
                CK(cudaMemcpy(d.abl_r, abl_dir.data(), abl_dir.size() * sizeof(float), cudaMemcpyHostToDevice));
            }
        }
        // (MAYA_DS4_Q8_BATCH: its line now, at load; MAYA_DS4_Q8_CHECK=1: the batched rounding checked on every device first)
        if (pk.gguf) {
            gg::q8_batch();
            if (std::getenv("STRATA_DS4_Q8_CHECK") != nullptr || std::getenv("DS4_Q8_CHECK") != nullptr) {
                for (int id : ids)
                    if (!gg::q8_batch_check(id, err)) return false;
            }
        }
        if (const char* v = ds4_env("DS4_HC_FUSE")) {   // (MAYA_DS4_HC_FUSE)
            if (std::strcmp(v, "1") != 0 && std::strcmp(v, "2") != 0 && std::strcmp(v, "0") != 0) {
                err = std::string("DS4_HC_FUSE=") + v + ": 2, 1 or 0";
                return false;
            }
            hc_fuse = std::strcmp(v, "1") == 0 || std::strcmp(v, "2") == 0;
            hc_fuse_win = std::strcmp(v, "2") == 0;
#ifdef STRATA_HIP_WAVE64
            if (hc_fuse) {   // (its warp roundings are a 32-lane warp's)
                err = std::string("DS4_HC_FUSE=") + v + " on a wave64 build";
                return false;
            }
#endif
            if (hc_fuse && (!pk.gguf || g.hc != 4 || g.dim % 32 != 0 || g.dim > 8 * 1024 || g.sinkhorn < 1)) {
                err = std::string("DS4_HC_FUSE=") + v +
                      ": not this model's shapes (a GGUF, 4 streams, dim a multiple of 32 up to 8192)";
                return false;
            }
            if (hc_fuse)
                std::fprintf(stderr, "ds4: a decoded token's HC split and norm in one launch, its attention input "
                                     "rounded to int8 there, the layer's pre copy by its FFN split (DS4_HC_FUSE)%s\n",
                             hc_fuse_win ? "; a decode window's rows too, the FFN input rounded for the shared expert "
                                           "(DS4_HC_FUSE=2)"
                                         : "");
        }
        if (const char* v = ds4_env("DS4_DECODE_TRIM")) {   // (MAYA_DS4_DECODE_TRIM)
            char* end = nullptr;
            const long b = std::strtol(v, &end, 10);
            if (*v == 0 || end == nullptr || *end != 0 || b < 0 || b > 15) {
                err = std::string("DS4_DECODE_TRIM=") + v +
                      ": bits 0 .. 15 (1 s2's int8, 2 wq_b's int8, 4 the snapshot copies, 8 the drafter's hand-offs)";
                return false;
            }
            decode_trim = (int) b;
#ifdef STRATA_HIP_WAVE64
            if (decode_trim & 3) {   // (the int8 roundings are a 32-lane warp's)
                err = std::string("DS4_DECODE_TRIM=") + v + ": bits 1 / 2 on a wave64 build";
                return false;
            }
#endif
            if (((decode_trim & 1) && (!pk.gguf || g.ff % 32 != 0)) ||
                ((decode_trim & 2) && (!pk.gguf || g.q_lora % 32 != 0))) {
                err = std::string("DS4_DECODE_TRIM=") + v +
                      ": not this model's shapes (a GGUF, ff and q_lora multiples of 32)";
                return false;
            }
            if (decode_trim != 0)
                std::fprintf(stderr, "ds4: DS4_DECODE_TRIM=%d:%s%s%s%s\n", decode_trim,
                             decode_trim & 1 ? " the shared expert's swiglu rounds s2's int8 input;" : "",
                             decode_trim & 2 ? " q's norm rounds wq_b's int8 input;" : "",
                             decode_trim & 4 ? " the snapshot / latent copies one kernel each;" : "",
                             decode_trim & 8 ? " the drafter's hand-offs by xfer;" : "");
        }
        if (const char* v = ds4_env("DS4_ROUTE_FUSE")) {   // (MAYA_DS4_ROUTE_FUSE)
            if (std::strcmp(v, "1") != 0 && std::strcmp(v, "2") != 0 && std::strcmp(v, "0") != 0) {
                err = std::string("DS4_ROUTE_FUSE=") + v + ": 2, 1 or 0";
                return false;
            }
            route_fuse = std::strcmp(v, "1") == 0 || std::strcmp(v, "2") == 0;
            route_fuse_win = std::strcmp(v, "2") == 0;
#ifdef STRATA_HIP_WAVE64
            if (route_fuse) {   // (its warp reductions are a 32-lane warp's)
                err = std::string("DS4_ROUTE_FUSE=") + v + " on a wave64 build";
                return false;
            }
#endif
            if (route_fuse && ahead_mode != 1) {   // (no other lookahead mode changes under it)
                err = std::string("DS4_ROUTE_FUSE=") + v + " takes one layer of lookahead (DS4_AHEAD 1), not " +
                      std::to_string(ahead_mode);
                return false;
            }
            if (route_fuse)
                std::fprintf(stderr, "ds4: a decoded token's router stage on the lead in two launches: its gate and "
                                     "the next layer's, then the routing and the guesses (DS4_ROUTE_FUSE)%s\n",
                             route_fuse_win ? "; a decode window's rows too (DS4_ROUTE_FUSE=2)" : "");
        }
        if (helper_id >= 0 && !helper_open(err)) return false;
        // the groups' width: o.tp, less while the experts' blocks do not split in it (a member takes n_ff / tp of each
        // expert: the down's inputs in whole blocks - a GGUF's 256-value types split n_ff 2304 in 1, 3 or 9 parts)
        int tp = o.tp;
        // MAYA_DS4_TP_GGUF_UNEVEN=1 (read as STRATA_DS4_TP_GGUF_UNEVEN, or DS4_TP_GGUF_UNEVEN): a GGUF's experts split
        // in whole blocks, as even as they go (no flow on its groups yet)
        const char* tpu = std::getenv("STRATA_DS4_TP_GGUF_UNEVEN");
        if (tpu == nullptr) tpu = std::getenv("DS4_TP_GGUF_UNEVEN");
        if (const char* v = tpu) {
            if (std::strcmp(v, "1") != 0 && std::strcmp(v, "0") != 0) {
                err = std::string("DS4_TP_GGUF_UNEVEN=") + v + ": 1 or 0";
                return false;
            }
            tp_uneven = std::strcmp(v, "1") == 0;
        }
        if (pk.gguf && tp > 1) {
            int blk = 32;
            for (const auto& kv : pk.t) {
                const std::string& n = kv.first;
                if (n.find(".ffn.experts.") == std::string::npos || n.size() < 9 ||
                    n.compare(n.size() - 9, 9, "w2.weight") != 0)
                    continue;
                const int ty = gg_type_of(kv.second.dtype);
                if (ty >= 0) blk = std::max(blk, gg::type_block(ty));
            }
            // (DS4_TP_GGUF_UNEVEN: whole blocks, as many as members at least - n_ff 2304 in 256s: 5 + 4)
            const bool uneven = tp_uneven && g.ff % blk == 0;
            // DS4_TP_UNEVEN_HEADS=1 (experimental): keep a width the heads do not split in evenly - the layers' own
            // check takes the heads over head_members(tp) of the members, as a non-GGUF pack's do (64 heads, tp 3: 2)
            static const bool uneven_heads = [] {
                const char* e = std::getenv("DS4_TP_UNEVEN_HEADS");
                return e != nullptr && std::atoi(e) != 0;
            }();
            while (tp > 1 && ((uneven ? g.ff / blk < tp : (g.ff % tp != 0 || (g.ff / tp) % blk != 0 || (g.ff / tp) % 128 != 0)) ||
                              (!uneven_heads && (g.heads % tp != 0 || g.o_groups % tp != 0))))
                --tp;
            if (tp != o.tp)
                std::fprintf(stderr, "ds4: tensor parallel %d -> %d: the experts' %d-value blocks split n_ff %d no other way "
                                     "(each GPU its own layers)\n", o.tp, tp, blk, g.ff);
            if (uneven && tp > 1) {
                tp_blk = blk;
                int f0 = 0, fa = 0, fb = 0;
                splitb(g.ff, blk, tp, 0, f0, fa, 0);
                splitb(g.ff, blk, tp, tp - 1, f0, fb, 0);
                std::fprintf(stderr, "ds4: tensor parallel %d: the experts' n_ff %d in %d-value blocks, %d to %d a member "
                                     "(the odd blocks going round the members layer by layer) (DS4_TP_GGUF_UNEVEN)\n",
                             tp, g.ff, blk, fa, fb);
            } else
                tp_uneven = false;
        } else
            tp_uneven = false;
        // the groups: runs of tp devices of one kind (their memory), a device unlike the next alone
        // - or, tp the number of GPUs, one group of all of them whatever their kind (its tightest member sets the
        // experts' room); threads mode for the windows (decode) where a group is 2 wide or more or --threads on, the
        // prompt path (its own thread a GPU) as asked for - also where the experts' blocks took the groups' width down
        // to 1 (a 256-value type's: Maya's quants), which left every prompt in windows of 16 - and at --tp 1, each GPU
        // its own layers (--prefill-chunk 0: windows of 16)
        par = o.threads || tp > 1;
        prompt_par = true;
        const bool tp_all = tp > 1 && tp == (int) devs.size();
        for (size_t i = 0; i < devs.size();) {
            Group G;
            G.mem.push_back((int) i);
            size_t j = i + 1;
            while ((int) G.mem.size() < tp && j < devs.size() && (tp_all || devs[j].total == devs[i].total))
                G.mem.push_back((int) j++);
            if ((int) G.mem.size() < tp && G.mem.size() > 1) {   // a short run at the end: devices of their own
                for (int m : G.mem) {
                    Group one;
                    one.mem.push_back(m);
                    groups.push_back(one);
                }
            } else groups.push_back(G);
            i = j;
        }
        for (size_t gi = 0; gi < groups.size(); ++gi)
            for (size_t m = 0; m < groups[gi].mem.size(); ++m) {
                devs[(size_t) groups[gi].mem[m]].grp = (int) gi;
                devs[(size_t) groups[gi].mem[m]].mi = (int) m;
            }
        // whether the CPU lane's experts are read in place (--mmap-experts; auto: the pack's expert bytes beyond what the
        // GPUs can take - their free memory less the other weights and the prompt path's buffers - do not fit the RAM
        // this process can get beside kRamMargin), decided here because it sets the prompt chunk's default: in place
        // every chunk streams every expert VRAM does not hold from the files, so the larger the chunk the fewer times
        if (pk.gguf) file_experts = true;   // (a GGUF's: the files stay their source - copy_experts copies them into RAM
                                            // after VRAM's are in, by --mmap-experts)
        else if (o.mmap_experts >= 0) file_experts = o.mmap_experts > 0;
        else {
            double exp_b = 0, other_b = 0, room = 0;
            for (const auto& kt : pk.t) {
                const std::string& n = kt.first;
                if (n.find(".engram.embed.") != std::string::npos || n.rfind("vision.", 0) == 0 || n == "embed.weight" ||
                    (!o.dspark && n.rfind("mtp.", 0) == 0))
                    continue;
                (n.find(".ffn.experts.") != std::string::npos ? exp_b : other_b) += (double) kt.second.bytes;
            }
            for (const Dev& d : devs)
                room += std::max(0.0, (double) d.free0 - (double) ((size_t) o.reserve_mib << 20) -
                                          (prompt_par ? 1.5 : 0.4) * (1 << 30)) *
                        o.vram_experts;
            file_experts = exp_b - std::max(0.0, room - other_b) + (double) kRamMargin > (double) ram_avail();
        }
        // (4096 in RAM on several GPUs: at --tp 9 a 16K prompt 896 -> 1336 tok/s and a 64K one 1132 -> 1651, its
        // buffers ~240 experts a GPU out of VRAM - decode 54.4 -> 52.3 tok/s at 3.5 bits; 8192 leaves the CPU lane more
        // than the RAM)
        chunk = prompt_par ? (o.prefill_chunk >= 0 ? o.prefill_chunk : file_experts ? kVlRows : devs.size() > 1 ? 4096 : 2048)
                           : 0;
        const char* dc = std::getenv("DS4_CHUNK");   // (tests: down to 16, a short prompt in several chunks)
        if (dc != nullptr) chunk = prompt_par ? std::atoi(dc) : 0;
        else if (chunk > 0 && o.prefill_chunk < 0) chunk = chunk_default(chunk);
        if (const char* v = std::getenv("DS4_CHUNK_MIN")) chunk_min = std::max(1, std::atoi(v));
        one_gpu_path();   // (the devices, their groups and the helper GPU known: before the recent slots' count)
        // (a GGUF: 32 too while streamed experts land in them, DS4_LAND - the link's bytes stay in VRAM)
        recent_n = std::max(0, (int) env_f("DS4_RECENT", chunk > 0 && (!file_experts || (pk.gguf && ln_land)) ? 32.0f : 0.0f));
        if (chunk > 0) {
            chunk = std::min(kMaxChunk, std::max(dc != nullptr ? 16 : 256, chunk / 16 * 16));
            eg_cap = (size_t) chunk;
            tap_cap = std::max(kWin, 128);
        } else   // (only as asked for: --prefill-chunk 0, or --tp 1 with --threads off)
            std::fprintf(stderr,
                         "ds4: prompts run in windows of %d tokens (%s): long prompts prefill far slower than in\n"
                         "     chunks (a 7-GPU RTX 3090 rig, Maya-S read in place: 8K / 32K tokens 115 / 99 tokens/s,\n"
                         "     461 / 1010 in chunks of %d) - %s\n",
                         kWin, o.prefill_chunk == 0 ? "--prefill-chunk 0" : "--tp 1 with --threads off", kVlRows,
                         o.prefill_chunk == 0 ? "leave --prefill-chunk out for chunks"
                                              : "leave --tp 1 out, or pass --threads on, for chunks");
        // the vision tower on the first GPU, before the split: the layers get what it leaves
        if (o.vision && !load_vision(err)) {   // (a tower that cannot load leaves the model reading text: said loudly,
            if (o.vision_only) return false;   // and the server is told pictures are off - info_lines)
            std::fprintf(stderr, "ds4: WARNING: the vision tower did not load (%s): pictures are OFF, the model reads "
                                 "text only\n", err.c_str());
            vision_err = err.empty() ? "unknown reason" : err;
            err.clear();
            vt.release();
            img_tok = -1;
        }
        if (o.vision_only) return true;

        // layers: roles and the sources they read
        if (!o.dspark) g.n_mtp = 0;
        L.resize((size_t) (g.nl + g.n_mtp));
        int last_src = -1;
        for (int il = 0; il < g.nl + g.n_mtp; ++il) {
            Layer& l = L[(size_t) il];
            l.il = il;
            l.mtp = il >= g.nl;
            l.name = l.mtp ? "mtp." + std::to_string(il - g.nl) + "." : "layers." + std::to_string(il) + ".";
            l.n_exp = l.mtp ? g.d_n_exp : g.n_exp;
            l.k_exp = l.mtp ? g.d_k : g.k_exp;
            l.ratio = g.ratios[(size_t) il];
            if (l.mtp) {   // window attention only: no compressor, indexer or Engram
                if (l.ratio != 0 || l.n_exp <= 0 || l.k_exp <= 0 || l.k_exp > kPicks) {
                    err = l.name + ": a DSpark block of compress ratio " + std::to_string(l.ratio) + ", " +
                          std::to_string(l.n_exp) + " experts / " + std::to_string(l.k_exp) + " is not covered";
                    return false;
                }
                if (!expert_layout(l, err)) return false;
                continue;
            }
            l.kv_src = std::find(g.kv_src.begin(), g.kv_src.end(), il) != g.kv_src.end();
            l.ix_src = std::find(g.ix_src.begin(), g.ix_src.end(), il) != g.ix_src.end();
            l.owns_k = l.kv_src;
            l.cand_src = il == g.cand_src;
            l.uses_cand = g.cand_src >= 0 && g.cand_src < il && l.ix_src;
            if (l.kv_src) {
                Src s;
                s.layer = il;
                s.ratio = l.ratio;
                s.cap = (o.max_context + l.ratio - 1) / l.ratio + 1;
                srcs.push_back(s);
                last_src = (int) srcs.size() - 1;
            }
            if (l.ratio > 0) {
                if (last_src < 0 || srcs[(size_t) last_src].ratio != l.ratio) {
                    err = "layer " + std::to_string(il) + ": compress ratio " + std::to_string(l.ratio) +
                          " without a KV source of that ratio before it";
                    return false;
                }
                l.src = last_src;
                l.ik_src = last_src;
            }
            auto eg = std::find(g.eg_layers.begin(), g.eg_layers.end(), il);
            if (eg != g.eg_layers.end()) l.eg = (int) (eg - g.eg_layers.begin());
            if (!expert_layout(l, err)) return false;
        }

        // the split: each layer's dense weights + its experts, the head on the last GPU
        for (Layer& l : L) {
            const std::string& P = l.name;
            size_t b = 0;
            if (l.mtp && l.il == g.nl) b += mat_bytes("mtp.0.main_proj");
            for (const char* m : {"attn.wq_a", "attn.wq_b", "attn.wkv", "attn.wo_b", "ffn.shared_experts.w1",
                                  "ffn.shared_experts.w2", "ffn.shared_experts.w3", "attn.compressor.wkv",
                                  "attn.compressor.wgate", "attn.indexer.wq_b", "attn.indexer.wk", "engram.wkv"})
                b += mat_bytes(P + m);
            for (int gi = 0; gi < g.o_groups; ++gi) b += mat_bytes(P + "attn.wo_a.slice." + std::to_string(gi));
            b += tensor_bytes(P + "hc_attn_fn") + tensor_bytes(P + "hc_ffn_fn") + tensor_bytes(P + "ffn.gate.weight");
            b += (size_t) g.win * win_rb() + (2u << 20);
            l.dense_bytes = b;
        }
        const size_t head_b = mat_bytes("head") + (size_t) g.vocab * 4 + (16u << 20);
        const size_t per_dev_fixed = (size_t) o.reserve_mib << 20;
        const size_t kv_per_src_dev = 0;   // counted after the split
        (void) kv_per_src_dev;
        std::vector<double> avail(groups.size(), 0.0);
        double avail_sum = 0;
        for (size_t gi = 0; gi < groups.size(); ++gi) {
            for (int m : groups[gi].mem)
                avail[gi] += std::max(0.0, (double) devs[(size_t) m].free0 - (double) per_dev_fixed - 400.0 * (1 << 20));
            avail_sum += avail[gi];
        }
        double need_sum = (double) head_b;
        for (const Layer& l : L) need_sum += (double) l.dense_bytes + (double) l.blob * l.n_exp;
        {
            // contiguous layer ranges, each group's share of the total by its free memory
            size_t d = 0;
            double cum = 0, target = avail[0] / avail_sum * need_sum;
            std::vector<Layer*> order;   // the drafter's blocks first (the first GPU), then the trunk's layers
            for (Layer& l : L)
                if (l.mtp) order.push_back(&l);
            for (Layer& l : L)
                if (!l.mtp) order.push_back(&l);
            for (Layer* lp : order) {
                Layer& l = *lp;
                const double lb = (double) l.dense_bytes + (double) l.blob * l.n_exp;
                if (cum + lb / 2 > target && d + 1 < groups.size()) {
                    ++d;
                    target += avail[d] / avail_sum * need_sum;
                }
                l.grp = (int) d;
                cum += lb;
            }
            // with the chunked prompt path: the contiguous split that streams the least into its busiest member (its
            // VRAM short of its layers' experts, per member) - a chunk's groups run as a pipeline, its slowest stage
            // sets the pace; a token's decode passes every layer either way, the experts in VRAM the same in all
            if (chunk > 0 && groups.size() > 1 && groups.size() <= 6 && std::getenv("DS4_SPLIT") == nullptr) {
                const int G = (int) groups.size(), NL = g.nl;
                std::vector<double> cap(groups.size());
                for (int gi = 0; gi < G; ++gi) {
                    const int nm = (int) groups[(size_t) gi].mem.size();
                    double mn = 1e300;
                    for (int m : groups[(size_t) gi].mem)
                        mn = std::min(mn, std::max(0.0, (double) devs[(size_t) m].free0 - (double) per_dev_fixed -
                                                            400.0 * (1 << 20) - 1.1 * (1 << 30)));   // (the chunk's buffers)
                    cap[(size_t) gi] = mn * nm;
                }
                for (const Layer& l : L)
                    if (l.mtp) cap[0] -= (double) l.dense_bytes + (double) l.blob * l.n_exp;
                cap[(size_t) G - 1] -= (double) head_b;
                std::vector<double> pe(NL + 1, 0.0), pd(NL + 1, 0.0);   // prefix sums: experts, dense
                for (int il = 0; il < NL; ++il) {
                    pe[(size_t) il + 1] = pe[(size_t) il] + (double) L[(size_t) il].blob * L[(size_t) il].n_exp;
                    pd[(size_t) il + 1] = pd[(size_t) il] + (double) L[(size_t) il].dense_bytes;
                }
                auto cost = [&](int gi, int a, int b) {   // per-member streaming of layers [a, b) on group gi
                    const int nm = (int) groups[(size_t) gi].mem.size();
                    const double dense = (pd[(size_t) b] - pd[(size_t) a]) * (nm > 1 ? 1.3 : 1.0);
                    return std::max(0.0, pe[(size_t) b] - pe[(size_t) a] - (cap[(size_t) gi] - dense)) / nm;
                };
                // best[gi][b]: the least max cost of layers [0, b) over groups 0..gi (each at least one layer)
                std::vector<std::vector<double>> best((size_t) G, std::vector<double>((size_t) NL + 1, 1e300));
                std::vector<std::vector<int>> cut((size_t) G, std::vector<int>((size_t) NL + 1, 0));
                for (int b = 1; b <= NL; ++b) best[0][(size_t) b] = cost(0, 0, b);
                for (int gi = 1; gi < G; ++gi)
                    for (int b = gi + 1; b <= NL; ++b)
                        for (int a = gi; a < b; ++a) {
                            const double v = std::max(best[(size_t) gi - 1][(size_t) a], cost(gi, a, b));
                            if (v < best[(size_t) gi][(size_t) b]) {
                                best[(size_t) gi][(size_t) b] = v;
                                cut[(size_t) gi][(size_t) b] = a;
                            }
                        }
                int b = NL;
                for (int gi = G - 1; gi >= 0; --gi) {
                    const int a = gi > 0 ? cut[(size_t) gi][(size_t) b] : 0;
                    for (int il = a; il < b; ++il) L[(size_t) il].grp = gi;
                    b = a;
                }
            }
            // DS4_SPLIT=a,b,..: the trunk layers each group takes (the drafter stays with the first)
            if (const char* sp = std::getenv("DS4_SPLIT")) {
                std::vector<int> n;
                for (const char* q = sp; *q;) {
                    n.push_back(std::atoi(q));
                    while (*q && *q != ',') ++q;
                    if (*q == ',') ++q;
                }
                int il = 0;
                for (size_t gi = 0; gi < n.size() && gi < groups.size(); ++gi)
                    for (int j = 0; j < n[gi] && il < g.nl; ++j) L[(size_t) il++].grp = (int) gi;
                for (; il < g.nl; ++il) L[(size_t) il].grp = (int) groups.size() - 1;
            }
            // Experimental placement override: keep the trunk's explicit split unchanged.
            // A drafter on a TP lead consumes room that its mate cannot use for paired slots.
            if (g.n_mtp > 0) {
                if (const char* value = std::getenv("DS4_DSPARK_GROUP")) {
                    char* end = nullptr;
                    const long group = std::strtol(value, &end, 10);
                    if (end == value || *end != '\0' || group < 0 || group >= (long) groups.size() ||
                        std::getenv("DS4_SPLIT") == nullptr) {
                        err = "DS4_DSPARK_GROUP requires a valid group and an explicit DS4_SPLIT";
                        return false;
                    }
                    for (Layer& l : L)
                        if (l.mtp) l.grp = (int) group;
                    std::fprintf(stderr, "ds4: experimental DSpark group %ld, lead CUDA%d\n", group,
                                 devs[(size_t) groups[(size_t) group].mem[0]].id);
                }
            }
            for (Layer& l : L) {
                l.dev = groups[(size_t) l.grp].mem[0];
                l.nm = l.mtp ? 1 : (int) groups[(size_t) l.grp].mem.size();   // (the drafter's blocks: whole, on the lead
            }                                                                  //  unless DS4_DRAFT_DEV names their members)
            if (!draft_devs(err)) return false;
            for (size_t i = 0; i < draft_dev.size(); ++i) {
                Layer& l = L[(size_t) g.nl + i];
                l.dev = groups[(size_t) l.grp].mem[(size_t) draft_dev[i]];
            }
            head_dev = L[(size_t) g.nl - 1].dev;
            d_dev = g.n_mtp > 0 ? L[(size_t) g.nl].dev : 0;
        }
        // the groups' members: copies of each layer's device state, a member's part of an expert
        for (Layer& l : L) {
            l.ff0 = 0;
            l.ffn = g.ff;
            l.ah0 = l.og0 = 0;
            l.ahn = g.heads;
            l.ogn = g.o_groups;
            if (l.nm == 1) continue;
            const int na = head_members(l.nm);
            if (g.heads % na != 0 || g.o_groups % na != 0 || g.ff % 128 != 0 || g.ff / 128 < l.nm) {
                err = "tensor parallel " + std::to_string(l.nm) + ": the heads, output groups or FFN do not split";
                return false;
            }
            for (int m = 1; m < l.nm; ++m) {
                Layer c = l;
                c.mates.clear();
                c.mi = m;
                c.dev = groups[(size_t) l.grp].mem[(size_t) m];
                l.mates.push_back(std::move(c));
            }
            // each member's FFN columns and its part of an expert's layout: an EXL3 expert's in whole 128-blocks, as even
            // as they go (split128, the odd blocks going round the members layer by layer); a GGUF's in even shares (its
            // groups are only as wide as its experts' blocks split evenly: mx_blob_to_half's n_ff / nm)
            const bool gguf_x = l.lay.fmt == gg::kFmtMXFP4;
            for (int m = 0; m < l.nm; ++m) {
                Layer& x = member(l, m);
                const int ha = m - (l.nm - na);   // (its place among the members with heads)
                x.ahn = ha < 0 ? 0 : g.heads / na;
                x.ah0 = ha < 0 ? 0 : ha * x.ahn;
                x.ogn = ha < 0 ? 0 : g.o_groups / na;
                x.og0 = ha < 0 ? 0 : ha * x.ogn;
                if (gguf_x && tp_uneven)   // (DS4_TP_GGUF_UNEVEN: whole blocks, the odd ones round the members)
                    splitb(g.ff, tp_blk, l.nm, m, x.ff0, x.ffn, l.il % l.nm);
                else if (gguf_x) {
                    x.ffn = g.ff / l.nm;
                    x.ff0 = m * x.ffn;
                } else
                    split128(g.ff, l.nm, m, x.ff0, x.ffn, l.il % l.nm);   // (rot: the odd blocks go round the members)
                size_t off = 0;
                for (int r = 0; r < 3; ++r) {
                    const int k = r < 2 ? g.dim : x.ffn, n = r < 2 ? x.ffn : g.dim;
                    x.hlay.k2[r] = l.lay.k2[r];
                    x.hlay.gg_type[r] = l.lay.gg_type[r];
                    x.hlay.trellis[r] = off;
                    if (gguf_x) {   // gate / up rows, down inputs: [n][k / block] blocks
                        const int ty = gg::expert_type(l.lay, r);
                        if (k % gg::type_block(ty) != 0) {
                            err = "tensor parallel " + std::to_string(l.nm) + ": the experts' " + gg::type_name(ty) +
                                  " blocks do not split";
                            return false;
                        }
                        x.hlay.suh[r] = x.hlay.svh[r] = off;
                        off += align256((size_t) n * gg::type_row_bytes(ty, k));
                        continue;
                    }
                    off += align256(x3::trellis_bytes_k2(k, n, l.lay.k2[r]));
                    x.hlay.suh[r] = off;
                    off += align256((size_t) k * 2);
                    x.hlay.svh[r] = off;
                    off += align256((size_t) n * 2);
                }
                x.hlay.cb = l.lay.cb;
                x.hlay.fmt = l.lay.fmt;
                x.hblob = off;
            }
        }
        // which devices hold each source's compressed KV / index keys
        for (Src& s : srcs) {
            s.ckv.assign(devs.size(), nullptr);
            s.ik.assign(devs.size(), nullptr);
        }
        for (const Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m) {
                const Layer& l = member(l0, m);
                if (l.src >= 0) {
                    srcs[(size_t) l.src].ckv[(size_t) l.dev] = (uint8_t*) 1;
                    if (l0.grp != L[(size_t) srcs[(size_t) l.src].layer].grp) srcs[(size_t) l.src].remote = true;
                }
                if (l.ix_src && l.ik_src >= 0) {
                    srcs[(size_t) l.ik_src].ik[(size_t) l.dev] = (uint8_t*) 1;
                    if (l0.grp != L[(size_t) srcs[(size_t) l.ik_src].layer].grp) srcs[(size_t) l.ik_src].remote = true;
                }
            }

        // per device: the scratch, the caches, the dense weights
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            const int D = g.dim, H = g.hc;
            const size_t W = kWin, P = (size_t) kWin * kPicks, cap = (size_t) o.max_context + 64;
            bool ok = dalloc(d, d.h, W * H * D, err) && dalloc(d, d.h2, W * H * D, err) && dalloc(d, d.x, W * D, err) &&
                      dalloc(d, d.qr, W * g.q_lora, err) && dalloc(d, d.q, W * g.heads * g.hd, err) &&
                      dalloc(d, d.kvr, W * g.hd, err) && dalloc(d, d.ckr, W * g.hd, err) &&
                      dalloc(d, d.cgr, W * g.hd, err) && dalloc(d, d.latent, W * g.hd, err) &&
                      dalloc(d, d.ikr, W * g.ix_hd, err) && dalloc(d, d.iq, W * g.ix_heads * g.ix_hd, err) &&
                      dalloc(d, d.iw, W * 64, err) && dalloc(d, d.scores, W * cap, err) &&
                      dalloc(d, d.tks.val, kTksRows * tks_p() * g.ix_topk, err) &&
                      dalloc(d, d.tks.idx, kTksRows * tks_p() * g.ix_topk, err) &&
                      dalloc(d, d.tks.cnt, kTksRows * tks_p(), err) && dalloc(d, d.tks.kth, kTksRows * tks_p(), err) &&
                      dalloc(d, d.bm, W * bm_stride(), err) && dalloc(d, d.o, W * g.heads * g.hd, err) &&
                      dalloc(d, d.oa, W * g.o_groups * g.o_lora, err) && dalloc(d, d.ao, W * D, err) &&
                      dalloc(d, d.mix, W * 32, err) && dalloc(d, d.a_pre, W * 8, err) && dalloc(d, d.a_post, W * 8, err) &&
                      dalloc(d, d.a_comb, W * 64, err) && dalloc(d, d.f_pre, W * 8, err) &&
                      dalloc(d, d.f_post, W * 8, err) && dalloc(d, d.f_comb, W * 64, err) && dalloc(d, d.pre, W * 8, err) &&
                      dalloc(d, d.glog, W * 1024, err) && dalloc(d, d.glog_a, 2 * W * 1024, err) &&
                      dalloc(d, d.rw, W * kPicks, err) &&
                      dalloc(d, d.ridx, W * kPicks, err) && dalloc(d, d.moe_out, W * D, err) &&
                      dalloc(d, d.sg, W * g.ff, err) && dalloc(d, d.su, W * g.ff, err) && dalloc(d, d.sh, W * g.ff, err) &&
                      dalloc(d, d.sh_out, W * D, err) && dalloc(d, d.cpu_part, W * D, err) &&
                      dalloc(d, d.freqs_win, 64, err) && dalloc(d, d.freqs_comp, 64, err) &&
                      dalloc(d, d.topk, W * topk_stride(), err) && dalloc(d, d.cand, W * cand_stride(), err) &&
                      dalloc(d, d.tok, 16, err) && dalloc(d, d.emb_rows, W * D, err) &&
                      dalloc(d, d.ext, ((size_t) g.win + W) * g.hd, err) && dalloc(d, d.xe, P * D, err) &&
                      dalloc(d, d.xg, P * g.ff, err) && dalloc(d, d.xu, P * g.ff, err) && dalloc(d, d.xhh, P * g.ff, err) &&
                      dalloc(d, d.ed, P * D, err) && dalloc(d, d.plan_ptr, P, err) && dalloc(d, d.cpu_any, 1, err);
            if (!ok) return false;
            CK(cudaMemset(d.cpu_any, 0, sizeof(int)));
            d.attn_scr.max_t = kAttnScratchT;
            d.attn_scr.cap = (int) topk_stride();
            if (!dalloc(d, d.attn_scr.rows, (size_t) kAttnScratchT * topk_stride() * g.hd, err)) return false;
            d.tks.T = (int) kTksRows, d.tks.P = (int) tks_p(), d.tks.K = g.ix_topk;
            if ((decode_trim & 1) && !(dalloc(d, d.shq8, (size_t) kWin * g.ff, err) &&
                                       dalloc(d, d.shd8, (size_t) kWin * g.ff / 32, err)))
                return false;
            if ((decode_trim & 2) && !(dalloc(d, d.qrq8, (size_t) kWin * g.q_lora, err) &&
                                       dalloc(d, d.qrd8, (size_t) kWin * g.q_lora / 32, err)))
                return false;
            if ((decode_trim & 8) && g.n_mtp > 0 && !(hmap(d.dhand, dhand_bytes(), err) && hmap(d.dhand_flag, 8, err)))
                return false;   // (hmap zeroes them: the flag starts below every sequence)
            if (hc_fuse && !(dalloc(d, d.xq8, (size_t) (hc_fuse_win ? kWin : 1) * D, err) &&   // (=2: a window's rows)
                             dalloc(d, d.xd8, (size_t) (hc_fuse_win ? kWin : 1) * D / 32, err)))
                return false;
            if (!g.eg_layers.empty()) {
                const int cols = (pk.eg_ngram - 1) * pk.eg_heads;
                ok = dalloc(d, d.eg_rows, W * cols * (pk.eg_hd + pk.eg_hd / 32), err) &&
                     dalloc(d, d.eg_x, W * cols * pk.eg_hd, err) && dalloc(d, d.eg_kv, W * (g.hc + 1) * D, err);
                if (!ok) return false;
            }
            if ((int) di == head_dev && !dalloc(d, d.logits, (size_t) kWin * g.vocab, err)) return false;
            if (!halloc(d.bounce, bounce_bytes(), err)) return false;
            if (!dalloc(d, d.xcnt, 4, err) || !hmap(d.hand, bounce_bytes(), err) || !hmap(d.hand_flag, 32, err) ||
                !dalloc(d, d.grp_ptr, P, err) || !dalloc(d, d.grp_start, P + 1, err) || !dalloc(d, d.grp_ent, P, err) ||
                !dalloc(d, d.n_groups, 4, err))
                return false;
            if (g.n_mtp > 0 && !dalloc(d, d.tap, (size_t) tap_cap * D, err)) return false;
            if (g.n_mtp > 0 && (int) di == head_dev && !dalloc(d, d_confv, kWin, err)) return false;
            if (spec_bufs() && (int) di == head_dev && (!dalloc(d, d_ints, 64, err) || !dalloc(d, d_specq, kWin, err)))
                return false;
            CK(cudaEventCreateWithFlags(&d.ev_out, cudaEventDisableTiming));
            cudaSetDevice(d.id);
            CK(cudaMemcpy(d.freqs_win, freqs_win.data(), freqs_win.size() * 4, cudaMemcpyHostToDevice));
            CK(cudaMemcpy(d.freqs_comp, freqs_comp.data(), freqs_comp.size() * 4, cudaMemcpyHostToDevice));
            for (Src& s : srcs) {
                if (s.h_ckv == nullptr) {   // (its events belong to the source layer's device: it records them)
                    if (!halloc(s.h_ckv, (size_t) kWin * ckv_rb(), err) || !halloc(s.h_ik, (size_t) kWin * ik_rb(), err))
                        return false;
                    CK(cudaSetDevice(devs[(size_t) L[(size_t) s.layer].dev].id));
                    CK(cudaEventCreateWithFlags(&s.ev_ckv, cudaEventDisableTiming));
                    CK(cudaEventCreateWithFlags(&s.ev_ik, cudaEventDisableTiming));
                    CK(cudaSetDevice(d.id));
                }
                if (s.ckv[di] != nullptr && !dalloc(d, s.ckv[di], (size_t) s.cap * ckv_rb(), err, &d.caches))
                    return false;
                if (s.ik[di] != nullptr && !dalloc(d, s.ik[di], (size_t) s.cap * ik_rb(), err, &d.caches))
                    return false;
            }
        }
        for (Src& sr : srcs) {
            if (sr.remote && (!hmap(sr.x_stage, x_cap() * (ckv_rb() + ik_rb()), err) || !hmap(sr.x_flag, 32, err)))
                return false;
            if (sr.remote && chunk > 0 &&
                (!hmap(sr.x_stage1, x_cap() * (ckv_rb() + ik_rb()), err) || !hmap(sr.x_flag1, 32, err) ||
                 !hmap(sr.x_ack, (size_t) 2 * devs.size() * 32, err)))
                return false;
            const int sg = L[(size_t) sr.layer].grp;
            for (size_t di = 0; di < devs.size(); ++di)
                if ((sr.ckv[di] != nullptr || sr.ik[di] != nullptr) && devs[di].grp != sg) sr.readers.push_back((int) di);
        }
        for (Group& G : groups) {
            G.ar.nm = (int) G.mem.size();
            G.ar.slots = 4;
            G.ar.stride = (size_t) kWin * g.dim;
            if (G.ar.nm > 1 && (!hmap(G.ar.data, (size_t) G.ar.nm * G.ar.slots * G.ar.stride, err) ||
                                !hmap(G.ar.flags, (size_t) G.ar.nm * G.ar.slots * 32, err)))
                return false;
            // three members or more: the reduce-scatter's sums and its per-block flags (allreduce)
            if (G.ar.nm > 2 && (!hmap(G.ar.sums, (size_t) G.ar.slots * G.ar.stride, err) ||
                                !hmap(G.ar.bflags, (size_t) 2 * G.ar.nm * G.ar.slots * kArBlocks * 8, err)))
                return false;
            if (G.ar.nm > 1 && &G == &groups[(size_t) devs[(size_t) head_dev].grp] &&
                (!hmap(G.lg_stage, (size_t) 2 * (G.ar.nm - 1) * kWin * ((g.vocab / 128 + G.ar.nm - 1) / G.ar.nm * 128), err) ||
                 !hmap(G.lg_flag, (size_t) 2 * (G.ar.nm - 1) * 32, err) || !hmap(G.lg_ack, (size_t) 2 * 32, err)))
                return false;
            G.arb = G.ar;   // (a chunk's: two slots of chunk rows)
            G.arb.slots = 2;
            G.arb.stride = (size_t) chunk * g.dim;
            if (chunk > 0 && G.arb.nm > 1 && (!hmap(G.arb.data, (size_t) G.arb.nm * G.arb.slots * G.arb.stride, err) ||
                                              !hmap(G.arb.flags, (size_t) G.arb.nm * G.arb.slots * 32, err)))
                return false;
            if (chunk > 0 && G.arb.nm > 2 &&
                (!hmap(G.arb.sums, (size_t) G.arb.slots * G.arb.stride, err) ||
                 !hmap(G.arb.bflags, (size_t) 2 * G.arb.nm * G.arb.slots * kArBlocks * 8, err)))
                return false;
            // 5 members or more: a chunk's sums by the host (DS4_AR_HOST: the members from which, 0 off; threads
            // DS4_AR_HOST_THREADS, 32)
            const char* hm = std::getenv("DS4_AR_HOST");
            const int host_from = hm != nullptr ? std::atoi(hm) : 5;
            if (chunk > 0 && host_from > 0 && G.arb.nm >= host_from && G.arb.nm <= 16 && G.arb.sums != nullptr) {
                const char* ht = std::getenv("DS4_AR_HOST_THREADS");
                std::vector<int> ids;
                for (int m : G.mem) ids.push_back(devs[(size_t) m].id);
                G.hred = std::make_shared<HostReducer>(G.arb, ids, G.arb.stride, ht != nullptr ? std::max(1, std::atoi(ht)) : 32);
                if (!G.hred->ok()) G.hred.reset();   // (the sums by the copy engines then)
            }
            if (chunk > 0 && G.arb.nm == 2 && ar2() > 0) {   // DS4_AR2: ar2_kernel's progress words (zeroed)
                if (!hmap(G.arb.pflags, (size_t) G.arb.nm * G.arb.slots * kAr2Blocks * 16, err)) return false;
                G.arb.ar2 = ar2();
            }
            // DS4_AR2_DECODE=1 (unset: as before): the decode windows' all-reduces of a group of two (G.ar: the
            // attention output's and the MoE's, a window's rows) in ar2_kernel too - its exact mode only (1: member 0's
            // partial plus member 1's, ar_sum_kernel's bits), one launch where xfer_put and ar_sum_kernel were two, the
            // other's rows read 16 bytes a lane.  Its own progress words: G.arb was copied from G.ar before, so it
            // shares none of them
            if (G.ar.nm == 2 && ar2_decode()) {
                if (!hmap(G.ar.pflags, (size_t) G.ar.nm * G.ar.slots * kAr2Blocks * 16, err)) return false;
                G.ar.ar2 = 1;
            }
        }
        if (ar2() < 0) {
            err = "DS4_AR2 takes 0, 1 or 2";
            return false;
        }
        if (ar2_decode()) {
            std::string on;
            for (const Group& G : groups)
                if (G.ar.ar2 > 0)
                    for (int m : G.mem) on += (on.empty() ? "CUDA" : ", CUDA") + std::to_string(devs[(size_t) m].id);
            std::fprintf(stderr, "%s%s%s\n", on.empty() ? "ds4: DS4_AR2_DECODE: no group of two - not used" :
                                                       "ds4: DS4_AR2_DECODE: the decode windows' all-reduces on ",
                         on.c_str(), on.empty() ? "" : " in one launch, the other member's rows read 16 bytes a lane; "
                                                       "the sums bit for bit");
        }
        if (ar2() > 0) {
            std::string on;
            for (const Group& G : groups)
                if (G.arb.ar2 > 0)
                    for (int m : G.mem) on += (on.empty() ? "CUDA" : ", CUDA") + std::to_string(devs[(size_t) m].id);
            if (on.empty())
                std::fprintf(stderr, "ds4: DS4_AR2=%d: no group of two takes prompt chunks - not used\n", ar2());
            else
                std::fprintf(stderr,
                             "ds4: DS4_AR2=%d: the prompt chunks' all-reduces on %s pipelined (%d blocks, %d KB "
                             "pieces), the other member's rows read 16 bytes a lane%s\n",
                             ar2(), on.c_str(), kAr2Blocks, kAr2Piece * 16 >> 10,
                             ar2() == 2 ? "; FP16 on the wire (both partials rounded, summed in F32 in member order)"
                                        : "; the sums bit for bit");
        }
        if (g.n_mtp > 0) {
            if (!halloc(h_taps, (size_t) tap_cap * g.d_targets.size() * g.dim, err)) return false;
            for (size_t di = 0; di < devs.size(); ++di) {   // (each block device: its seeding's event, recorded once)
                if (!block_dev((int) di)) continue;
                Dev& d = devs[di];
                CK(cudaSetDevice(d.id));
                CK(cudaEventCreateWithFlags(&d.ev_seed, cudaEventDisableTiming));
                CK(cudaEventRecord(d.ev_seed, d.st));
            }
        }
        // the dense weights, each device's layers by a thread of its own
        {
            std::vector<std::string> errs(devs.size());
            std::vector<std::thread> th;
            for (size_t di = 0; di < devs.size(); ++di)
                th.emplace_back([this, di, &errs] {
                    std::string e;
                    if (!load_dense((int) di, e)) errs[di] = e;
                });
            for (auto& t : th) t.join();
            for (auto& e : errs)
                if (!e.empty()) {
                    err = e;
                    return false;
                }
        }
        if (o.verbose)
            std::fprintf(stderr, "ds4: dense weights loaded in %.1f s\n", (now_ms() - t0) / 1000.0);
        // the markov steps over a head group of two or more (DS4_MK_SPLIT=0: the lead's whole rows, as before): E
        // host-mapped, the steps' slots
        // (only where every member holds its rows of the markov head: a type load_dense does not take keeps the lead's)
        bool mk_rows = g.n_mtp > 0 && head_nm() > 1;
        for (int m : groups[(size_t) devs[(size_t) head_dev].grp].mem) mk_rows = mk_rows && devs[(size_t) m].mk_share != nullptr;
        if (mk_rows && !(std::getenv("DS4_MK_SPLIT") != nullptr && std::atoi(std::getenv("DS4_MK_SPLIT")) == 0)) {
            const Tensor* te = pk.get("mtp." + std::to_string(g.n_mtp - 1) + ".markov_head.embed.weight");
            if (te == nullptr || te->dtype != "BF16" || te->bytes != (uint64_t) g.vocab * g.d_rank * 2) {
                err = "the markov embed: not a BF16 [vocab][rank] table";
                return false;
            }
            if (!hmap(h_mk_embed, (size_t) g.vocab * g.d_rank, err) || !pk.read(*te, h_mk_embed) ||
                !hmap(mk_slots, (size_t) kWin * head_nm() * 4, err)) {
                if (err.empty()) err = "the markov embed: read failed";
                return false;
            }
            devs[(size_t) head_dev].mk_ints = d_ints;   // (the lead's drafted tokens: where the confidence head reads them)
            mk_split = true;
        }

        // the embedding table, pinned on the host
        {
            const Tensor* t = pk.get("embed.weight");
            const size_t nv = (size_t) g.vocab * g.dim;
            const bool q8 = t != nullptr && t->dtype == "Q8_0" && t->bytes == nv / 32 * gg::kQ8Bytes;
            // (Q4_K: 144 bytes every 256 values; Q5_K: 176; Q6_K: 210)
            const bool q4k = t != nullptr && t->dtype == "Q4_K" && g.dim % 256 == 0 && t->bytes == nv / 256 * 144;
            const bool q5k = t != nullptr && t->dtype == "Q5_K" && g.dim % 256 == 0 && t->bytes == nv / 256 * 176;
            const bool q6k = t != nullptr && t->dtype == "Q6_K" && g.dim % 256 == 0 && t->bytes == nv / 256 * kQ6kBytes;
            if (t == nullptr || (!q8 && !q4k && !q5k && !q6k && (t->dtype != "BF16" || t->bytes != nv * 2))) {
                err = "embed.weight: not a BF16 (or Q8_0, Q4_K, Q5_K, Q6_K) [vocab][dim] table";
                return false;
            }
            if (!halloc(embed_pinned, nv, err)) return false;
            if (q8 || q4k || q5k || q6k) {   // (a GGUF's: each value rounded to BF16, a row at a time)
                const size_t kb = q4k ? 144 : q5k ? 176 : kQ6kBytes;   // (a K-quant's bytes every 256 values)
                std::vector<uint8_t> row(q8 ? (size_t) g.dim / 32 * gg::kQ8Bytes : (size_t) g.dim / 256 * kb);
                for (size_t r = 0; r < (size_t) g.vocab; ++r) {
                    if (!pk.read_at(t->file, t->off + r * row.size(), row.size(), row.data())) {
                        err = "embed.weight: read failed";
                        return false;
                    }
                    std::vector<float> v;
                    if (q8) {
                        v = q8_values(row.data(), (size_t) g.dim);
                    } else {
                        v.resize((size_t) g.dim);
                        for (size_t b = 0; b < (size_t) g.dim / 256; ++b)
                            (q4k ? q4k_values : q5k ? q5k_values : q6k_values)(row.data() + b * kb, v.data() + b * 256);
                    }
                    for (size_t c = 0; c < (size_t) g.dim; ++c) {
                        uint32_t u;
                        std::memcpy(&u, &v[c], 4);
                        u += 0x7fffu + ((u >> 16) & 1u);   // round to nearest even
                        embed_pinned[r * g.dim + c] = (uint16_t) (u >> 16);
                    }
                }
            } else if (!pk.read(*t, embed_pinned)) {
                err = "embed.weight: read failed";
                return false;
            }
        }
        // the host side of the CPU lane and the Engram rows
        const int cols = (pk.eg_ngram - 1) * pk.eg_heads;
        if (!halloc(h_x, (size_t) kWin * g.dim, err) || !halloc(h_w, (size_t) kWin * kPicks, err) ||
            !halloc(h_part, (size_t) kWin * g.dim, err) || !halloc(h_idx, (size_t) kWin * kPicks, err) ||
            !halloc(h_emb, (size_t) std::max(kWin, chunk) * g.dim, err) ||
            !halloc(h_eg, (size_t) std::max(1, pk.eg_layers) * eg_cap * cols * (pk.eg_hd + pk.eg_hd / 32) + 64, err))
            return false;
        if (pk.eg_layers > 0) {
            // the Engram rows' reader: threads enough to keep an SSD's queue busy (reads from the page cache need few);
            // the row cache a small share of the RAM free (DS4_ENGRAM_CACHE_MB: its size, 0 off; DS4_ENGRAM_THREADS)
            const size_t row = (size_t) pk.eg_hd + pk.eg_hd / 32;
#if defined(_WIN32)
            // (Windows: each thread's ReadFile is synchronous, so the threads are the queue depth - a 28K-token prompt
            //  in one chunk, 1.36M rows before layer 1: 10 threads 17.1 s, 32 14.1 s, 64 13.4 s on a 20-core PC)
            int nth = 64;
#else
            const unsigned hw = std::max(1u, std::thread::hardware_concurrency());
            int nth = (int) std::min(16u, std::max(4u, hw / 2));
#endif
            if (const char* e = std::getenv("DS4_ENGRAM_THREADS")) nth = std::max(1, std::atoi(e));
            const uint64_t avail = ram_room();
            uint64_t mb = avail == ~uint64_t{0} ? 64 : std::min<uint64_t>(256, std::max<uint64_t>(16, (avail >> 20) / 64));
            if (const char* e = std::getenv("DS4_ENGRAM_CACHE_MB")) mb = std::strtoull(e, nullptr, 10);
            eg_cache.init((size_t) ((mb << 20) / row), row);
            std::vector<std::string> paths;
            for (const std::string& fn : pk.files) paths.push_back(pk.model_dir + "/" + fn);
            // Windows: the Engram tables' files that hold nothing else are unmapped and read unbuffered - an SSD's
            // queue kept by the reader threads instead of the page cache's (whose reads of one file from many threads
            // went ~255K rows a second here); unbuffered reads of a mapped file take a slow path, so only unmapped
            // ones (DS4_EG_DIRECT=0: buffered, mapped, as before)
            std::vector<char> eg_direct(pk.files.size(), 0);
#if defined(_WIN32)
            if (pk.gguf && (std::getenv("DS4_EG_DIRECT") == nullptr || std::atoi(std::getenv("DS4_EG_DIRECT")) != 0)) {
                std::vector<char> eg_file(pk.files.size(), 0), other(pk.files.size(), 0);
                for (const auto& kt : pk.t)
                    if (kt.second.file >= 0 && (size_t) kt.second.file < pk.files.size())
                        (kt.first.find(".engram.embed.") != std::string::npos ? eg_file : other)[(size_t) kt.second.file] = 1;
                for (size_t i = 0; i < pk.files.size(); ++i)
                    if (eg_file[i] && !other[i] && i < pk.maps.size() && pk.maps[i].first != nullptr) {
                        os::unmap(pk.maps[i].first, pk.maps[i].second);
                        pk.maps[i] = {nullptr, 0};
                        eg_direct[i] = 1;
                        if (o.verbose) std::fprintf(stderr, "ds4: %s unmapped, its Engram rows read unbuffered\n",
                                                    pk.files[i].c_str());
                    }
            }
#endif
            if (const char* mode = std::getenv("DS4_ENGRAM_RAM"); mode && std::atoi(mode) != 0) {
                uint64_t total = 0;
                for (int li = 0; li < pk.eg_layers; ++li) {
                    const Tensor* tw = pk.get("layers." + std::to_string(g.eg_layers[(size_t) li]) + ".engram.embed.weight");
                    if (tw == nullptr || (tw->dtype != "Q6_K" && tw->dtype != "IQ4_NL" && tw->dtype != "MXFP8" &&
                                          tw->dtype != "F8_E4M3")) {
                        err = "Engram RAM: unsupported table type"; return false;
                    }
                    if (!eg_io.pin_range(paths[(size_t) tw->file], tw->file, tw->off, tw->bytes, err)) return false;
                    total += tw->bytes;
                    if (tw->dtype == "F8_E4M3") {
                        const Tensor* ts = pk.get("layers." + std::to_string(g.eg_layers[(size_t) li]) + ".engram.embed.scale");
                        if (ts == nullptr || ts->dtype != "F8_E8M0") { err = "Engram RAM: missing FP8 scales"; return false; }
                        if (!eg_io.pin_range(paths[(size_t) ts->file], ts->file, ts->off, ts->bytes, err)) return false;
                        total += ts->bytes;
                    }
                }
                eg_io.require_ram();
                std::fprintf(stderr, "ds4: Engram RAM ONLY: %d complete tables (Q6_K/IQ4_NL/FP8), %.3f GB locked; reads use memcpy\n",
                             pk.eg_layers, (double) total / 1e9);
            }
            eg_io.start(paths, nth, eg_direct);
            for (int li = 0; li < pk.eg_layers; ++li) {
                eg_win.emplace_back(new EgBatch());
                const Tensor* tw = pk.get("layers." + std::to_string(g.eg_layers[(size_t) li]) + ".engram.embed.weight");
                const bool q6k = tw != nullptr && tw->dtype == "Q6_K", iq4 = tw != nullptr && tw->dtype == "IQ4_NL";
                if ((q6k && pk.eg_hd % 256 != 0) || (iq4 && pk.eg_hd % 32 != 0)) {
                    err = "Engram layer " + std::to_string(g.eg_layers[(size_t) li]) + ": " + tw->dtype + " rows of " +
                          std::to_string(pk.eg_hd) + " values (not whole blocks)";
                    return false;
                }
                if (tw != nullptr && !q6k && !iq4 && tw->dtype != "MXFP8" && tw->dtype != "F8_E4M3") {
                    err = "Engram layer " + std::to_string(g.eg_layers[(size_t) li]) + ": tables in " + tw->dtype +
                          " (the engine reads Q6_K, IQ4_NL, MXFP8 or FP8)";
                    return false;
                }
                eg_q6k.push_back(q6k ? 1 : iq4 ? 2 : 0);
            }
            if (o.verbose)
                std::fprintf(stderr, "ds4: Engram rows read on %d threads, issued with the tokens, collected before "
                                     "their layer; row cache %llu MB (%zu rows)\n",
                             nth, (unsigned long long) mb, eg_cache.capacity());
        }
        prof.assign((size_t) (g.nl + g.n_mtp) * g.n_exp, 0u);
        if (!o.profile.empty()) {
            std::FILE* f = std::fopen(o.profile.c_str(), "rb");
            if (f != nullptr) {
                std::vector<uint32_t> p(prof.size());
                const size_t n = std::fread(p.data(), 4, p.size(), f);
                if (n == p.size() || n == (size_t) g.nl * g.n_exp) std::copy(p.begin(), p.begin() + (long) n, prof.begin());
                std::fclose(f);
            }
        }
        prof_load = prof;

        // the chunked prompt path's buffers (before the experts: they take what is left)
        if (chunk > 0 && !alloc_chunks(err)) return false;
        // the CPU lane's experts read in place (decided above): how much of them the load reads ahead, from what VRAM
        // now leaves over
        if (file_experts) {
            double room = 0, all = 0;   // the VRAM place_experts will find for experts; every expert's bytes
            for (Dev& d : devs) {
                cudaSetDevice(d.id);
                size_t fr = 0, tot = 0;
                CK(mem_info(&fr, &tot));
                room += std::max(0.0, (double) fr - (double) ((size_t) o.reserve_mib << 20)) * o.vram_experts;
            }
            for (const Layer& l : L) all += (double) l.blob * l.n_exp;
            const double need = std::max(0.0, all - room - (double) helper_cap);   // (DS4_HELPER: its pool's)
            uint64_t avail = ram_room();
            const uint64_t hr_est = hr_host_estimate();   // (DS4_HELPER_RECENT: its stage and mirrors, pinned)
            if (avail != ~uint64_t{0}) avail = avail > hr_est ? avail - hr_est : 0;
            warm_bytes = avail > kRamMargin ? std::min<uint64_t>(avail - kRamMargin, (uint64_t) need) : 0;
            if (avail == ~uint64_t{0}) warm_bytes = (uint64_t) need;
            if (warm_cap >= 0) warm_bytes = std::min<uint64_t>(warm_bytes, (uint64_t) warm_cap);
            if (helper_id >= 0)
                std::fprintf(stderr, "ds4: host budget with the helper: its pool %.1f GB (reserved while unfilled: %.1f), "
                                     "its flags and answers %.0f MB pinned%s, the experts read ahead or copied <= %.1f "
                                     "GB (DS4_WARM_CAP_GB), %.0f GB margin; RAM available %.1f GB\n",
                             helper_cap / 1e9, helper_pending / 1e9, (4096.0 + (double) kRing * kWin * g.dim * 4) / 1e6,
                             hr_est > 0 ? (", its recent slots' " + std::to_string((hr_est + (1 << 20) - 1) >> 20) +
                                           " MB pinned").c_str()
                                        : "",
                             warm_bytes / 1e9, kRamMargin / 1e9, ram_avail() / 1e9);
            std::fprintf(stderr,
                         "ds4: the experts VRAM leaves over (~%.1f GB) are read in place from the model's files%s "
                         "(%.1f GB of RAM free to keep them: the most-routed %.1f GB read ahead; prompts in chunks of %d)\n",
                         need / 1e9, o.mmap_experts > 0 ? " (--mmap-experts on)"
                                     : pk.gguf ? " (copied into RAM after the GPUs' share when the RAM holds them all; "
                                                 "--mmap-experts on keeps them in place)" : ", not copied into RAM",
                         avail == ~uint64_t{0} ? 0.0 : avail / 1e9, warm_bytes / 1e9, chunk);
        }
        // the CPU lane: one pool of workers per NUMA node, each expert split in NH column parts (part X on node X); in
        // place, one part (the files' layout) and one pool over every node's cores (the pages lie where the cache put them)
        core_threads = node_threads();
        cores.clear();
        for (const auto& n : core_threads) {
            cores.emplace_back();
            for (const os::Core& c : n) cores.back().push_back(c.cpus[0]);
        }
        NH = file_experts ? 1 : (int) std::min<size_t>(2, cores.size());
        if (NH > 1 && ((g.ff / NH) % 128 != 0 || (g.dim / NH) % 128 != 0)) NH = 1;
        if (!pk.gguf) make_pools();   // (a GGUF's after its experts: copy_experts decides NH)
        {
            const size_t E = (size_t) g.dim, FF = (size_t) g.ff, GQ = E / 256, DQ = FF / 128, S = kSlots;
            c_xh.resize((size_t) NH * S * 2 * E);
            c_xsb.resize((size_t) NH * S * 2 * (E / 128));
            c_acc.resize((size_t) NH * S * 2 * GQ * (FF / NH));
            c_xhd.resize(S * FF);
            c_xsd.resize(S * (FF / 128));
            c_accd.resize((size_t) NH * S * DQ * (E / NH));
            c_yd.resize(S * E);
        }
        // the experts: VRAM slots in what each device has left (after the PCIe lane's staging slots), the rest on the host
        if (!lane_alloc(err)) return false;
        if (!place_experts(err)) return false;
        if (helper_id >= 0 && !helper_select(err)) return false;
        if (!load_experts(err)) return false;
        if (copy_swap && copy_mode) {   // (DS4_COPY_SWAP: after the copies)
            if (const char* v = cs_env("COPY_SWAP_MARGIN")) cs_margin = (float) std::atof(v);
            if (const char* v = cs_env("COPY_SWAP_EVERY")) cs_every = std::max(1, std::atoi(v));
            cs_th = std::thread([this] { cs_loop(); });
            int nfree = 0;
            for (int f : cs_free) nfree += f >= 0;
            std::fprintf(stderr, "ds4: copy swaps: %d layers with a free slot, margin %.2f, every %d tokens\n", nfree,
                         cs_margin, cs_every);
        }
        if (pk.gguf) make_pools();
        if (chunk > 0) {
            // the CPU lane's parts pinned (the chunks stream them to the GPUs by DMA), each layer's virtual slots
            // An OS that will not lock them all keeps them unpinned (#521: Windows counts page-locked memory against its
            // commit limit and refuses nearly all of the RAM - one layer's 4.7 GB failed with 175 GB free): the chunks
            // copy them through the driver's staging instead, the same bytes, slower; the ones pinned before the failure
            // are given back too, so the pinned buffers allocated after this still find room.  (DS4_TEST_PIN_FAIL=N,
            // tests: part N's pin fails)
            const double tr = now_ms();
            const char* tf = std::getenv("DS4_TEST_PIN_FAIL");
            const long fail_at = tf != nullptr ? std::atol(tf) : -1;
            size_t n_pin = 0;
            for (; n_pin < host_maps.size(); ++n_pin)
                if ((long) n_pin == fail_at || cudaHostRegister(host_maps[n_pin].first, host_maps[n_pin].second,
                                                                cudaHostRegisterPortable) != cudaSuccess)
                    break;
            host_pinned = n_pin == host_maps.size();
            if (!host_pinned) {
                cudaGetLastError();
                double gb = 0;
                for (const auto& m : host_maps) gb += (double) m.second / 1e9;
                for (size_t i = 0; i < n_pin; ++i) cudaHostUnregister(host_maps[i].first);
                cudaGetLastError();
                std::fprintf(stderr,
                             "ds4: WARNING: pinning the CPU lane's experts in RAM failed at part %zu of %zu (%.1f GB in "
                             "all: the OS locks no more) - they stay in RAM unpinned: the answers are the same, prompts "
                             "copy them through the driver's staging (slower); --mmap-experts on reads them in place "
                             "from the files instead\n",
                             n_pin + 1, host_maps.size(), gb);
            } else if (o.verbose)
                std::fprintf(stderr, "ds4: CPU lane's experts pinned in %.1f s\n", (now_ms() - tr) / 1000.0);
            if (file_experts) {   // in place: each device's staging for its ring, and its readers (DS4_READERS, 8)
                size_t mr = 0;
                for (const Layer& l : L)
                    if (!l.mtp) {
                        for (uint64_t r : l.region_bytes) mr = std::max<size_t>(mr, r);
                        if (l.lay.fmt == gg::kFmtMXFP4) {   // (a GGUF's: read as its blob)
                            mr = std::max(mr, l.blob);
                            for (int r = 0; r < 3; ++r) flow_part[r] = std::max(flow_part[r], mx_part_bytes(l, r));
                        }
                    }
                const char* nr = std::getenv("DS4_READERS");
                const int n_readers = std::max(1, nr != nullptr ? std::atoi(nr) : 8);
                const bool flow_on = std::getenv("DS4_FLOW") == nullptr || std::atoi(std::getenv("DS4_FLOW")) != 0;
                // (a tensor-parallel group's members on the flow only with DS4_FLOW_TP=1 for now: each reads the
                // whole down of every expert it streams, 25 MB an expert for a pair, 18.8 alone - 3x V100, the
                // 17-token prompt from the page cache: 2.5-2.7 s on the flow, 1.3-1.6 s in the group's windows)
                const bool flow_tp = std::getenv("DS4_FLOW_TP") != nullptr && std::atoi(std::getenv("DS4_FLOW_TP")) != 0;
                for (size_t di = 0; di < chunks.size(); ++di) {
                    auto& cp = chunks[di];
                    if (cp == nullptr || cp->ring == nullptr) continue;
                    cp->stage_stride = (mr + 4095) & ~(size_t) 4095;
                    // the flow: every trunk layer of the device a GGUF's (alone or a tensor-parallel group's member)
                    bool fl = flow_on;
                    int n_exp_max = 0;
                    for (const Layer& l : L)
                        if (!l.mtp)
                            for (int m = 0; m < l.nm; ++m)
                                if (member(l, m).dev == (int) di) {
                                    // (a group's members: each its share of the down's blocks in every row)
                                    fl = fl && l.lay.fmt == gg::kFmtMXFP4 &&
                                         (l.nm == 1 || (flow_tp && (tp_uneven || (g.ff / l.nm) %
                                                        std::max(1, gg::type_block(gg::expert_type(l.lay, 2))) == 0)));
                                    n_exp_max = std::max(n_exp_max, l.n_exp);
                                }
                    if (fl)   // (each part read unbuffered from its offset rounded down: a page more each)
                        cp->stage_stride = std::max(cp->stage_stride, flow_stride());
                    cp->S = cp->ring_n;
                    if (!halloc(cp->stage, (size_t) cp->S * cp->stage_stride, err)) return false;
                    cp->readers = std::make_unique<Pool>(n_readers - 1, std::vector<int>{}, 50);
                    if (!fl) continue;
                    cudaSetDevice(devs[di].id);
                    cp->flow = true;
                    cp->dev = (int) di;
                    cp->io = std::make_unique<IoQueue>(n_readers);
                    cp->stage_item.assign((size_t) cp->S, -1);
                    cp->stage_ev.resize((size_t) cp->S);
                    cp->ring_fill.resize((size_t) cp->ring_n);
                    cp->ring_free.resize((size_t) cp->ring_n);
                    for (auto* v : {&cp->stage_ev, &cp->ring_fill, &cp->ring_free})
                        for (cudaEvent_t& e : *v) CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
                    // (a region is written again only bc_n batches later - more than a layer's items, so after that
                    // layer's bounds wait, which every copy from it precedes)
                    cp->bc_n = n_exp_max + 2;
                    cp->bc_w = cp->ring_n + 1;
                    if (!halloc(cp->bc_pin, (size_t) cp->bc_n * cp->bc_w, err) ||
                        !dalloc(devs[di], cp->bc_dev, (size_t) cp->bc_n * cp->bc_w, err))
                        return false;
                }
                // every device with layers on the flow: a prompt reads only the experts it picks, once, so a short one
                // takes the chunked path too (one pass, where windows of 16 read the CPU lane's picks again for each
                // window, a page fault at a time) - DS4_CHUNK_MIN still overrides
                bool all_flow = true;
                for (const auto& cp : chunks) all_flow = all_flow && (cp == nullptr || cp->ring == nullptr || cp->flow);
                if (all_flow && std::getenv("DS4_CHUNK_MIN") == nullptr) chunk_min = kFlowChunkMin;
                if (down_share()) {   // (DS4_FLOW_DOWN_SHARE: a count a (layer, expert) - the members' flows share it)
                    bool on = tp_uneven && flow_tp;
                    for (const auto& cp : chunks) on = on && (cp == nullptr || cp->ring == nullptr || cp->flow);
                    if (on) {
                        int ne = 0;
                        for (const Layer& l : L) ne = std::max(ne, l.n_exp);
                        down_stride = (size_t) ne;
                        down_reads.reset(new std::atomic<uint8_t>[L.size() * down_stride]);
                        for (size_t i = 0; i < L.size() * down_stride; ++i) down_reads[i].store(0);
                    }
                    std::fprintf(stderr, "%s",
                                 on ? "ds4: DS4_FLOW_DOWN_SHARE: a tensor-parallel group's members read each streamed "
                                      "expert's down from the files once, through the page cache (dropped once every "
                                      "member read it)\n"
                                    : "ds4: DS4_FLOW_DOWN_SHARE: no tensor-parallel members on the prompt path's "
                                      "flow - not used\n");
                }
                if (down_part_env()) {   // (DS4_FLOW_DOWN_PART: an uneven split's members on the flow)
                    bool on = tp_uneven && flow_tp;
                    for (const auto& cp : chunks) on = on && (cp == nullptr || cp->ring == nullptr || cp->flow);
                    down_part = on;
                    std::fprintf(stderr, "%s", on ? "ds4: DS4_FLOW_DOWN_PART: an uneven split's members DMA only their "
                                                    "columns of each streamed expert's down, compacted where it was "
                                                    "read\n"
                                                  : "ds4: DS4_FLOW_DOWN_PART: no uneven split's members on the prompt "
                                                    "path's flow - not used\n");
                }
                if (tp_uneven && flow_tp) {   // (DS4_FLOW_TP with DS4_TP_GGUF_UNEVEN: the members that stream their parts)
                    std::string on;
                    for (size_t di = 0; di < chunks.size(); ++di)
                        if (chunks[di] != nullptr && chunks[di]->flow)
                            on += (on.empty() ? "CUDA" : ", CUDA") + std::to_string(devs[di].id);
                    std::fprintf(stderr, "ds4: tensor-parallel members on the prompt path's flow: %s - each streams its own "
                                         "part of the experts a prompt picks (DS4_FLOW_TP)\n",
                                 on.empty() ? "none" : on.c_str());
                }
            }
            for (Layer& l : L) {
                if (l.mtp) continue;
                for (int m = 0; m < l.nm; ++m) {   // (each member its own: the flow's members decide them each)
                    Layer& x = member(l, m);
                    if (!halloc(x.vs_pin, (size_t) l.n_exp, err)) return false;
                    if (!dalloc(devs[(size_t) x.dev], x.vs_dev, (size_t) l.n_exp, err)) return false;
                }
            }
        }
        {
            void* m = nullptr;
            if (cudaHostAlloc(&m, sizeof(Req) * kRing, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
                err = "host-mapped memory for the decode path's requests";
                return false;
            }
            host_allocs.push_back(m);
            reqs = (Req*) m;
            if (cudaHostAlloc(&m, sizeof(Resp) * kRing, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
                err = "host-mapped memory for the decode path's answers";
                return false;
            }
            host_allocs.push_back(m);
            resps = (Resp*) m;
            if (!hmap(lane_done, 32, err)) return false;
            std::memset((void*) reqs, 0, sizeof(Req) * kRing);
            std::memset((void*) resps, 0, sizeof(Resp) * kRing);
            for (auto& x : layer_of) x.store(-1);
            ahead_fl.assign(L.size() * 1024, 0);
            ahead_rank.assign(L.size() * 1024, 0);
            ahead_for.assign(L.size(), 0);
            if (hc_fuse && !hc_fuse_win && !hc_fuse_check(err)) return false;   // (no request yet)
            if (hc_fuse_win && !(hc_fuse_check(err, 1, true) && hc_fuse_check(err, kWin, true)))   // (=2: a window too)
                return false;
            if (route_fuse && !route_fuse_check(err)) return false;   // (no request yet)
            if ((decode_trim & 3) && !trim_q8_check(err)) return false;   // (DS4_DECODE_TRIM: no request yet)
            if ((decode_trim & 12) && !trim_copy_check(err)) return false;
            if (route_fuse_win && !(route_fuse_check(err, 3) && route_fuse_check(err, kWin)))   // (=2: windows too)
                return false;
            if (tp_uneven && (std::getenv("STRATA_DS4_TP_CHECK") != nullptr || std::getenv("DS4_TP_CHECK") != nullptr) &&
                !tp_check(err))
                return false;   // (MAYA_DS4_TP_CHECK=1: at load, no request yet)
            if (helper_n > 0 && ds4_env("DS4_HELPER_CHECK") != nullptr) helper_check();   // (before the lane runs)
            if (helper_n > 0) helper_th = std::thread([this] { helper_loop(); });
            if (helper_n > 0 && hr_want > 0 && !hr_open(err)) return false;
            const int core = !cores.empty() && !cores[0].empty() ? cores[0][0] : -1;
            service = std::thread([this, core] {
                if (core >= 0) pin_self(core);
                serve_lane();
            });
            if (ahead_mode > 0) pf_th = std::thread([this] { prefetch_loop(); });
        }
        if (par && (!std::getenv("DS4_COPY_IDLE") || std::atoi(std::getenv("DS4_COPY_IDLE")) != 0)) {
            idle_ev.assign(devs.size(), nullptr);
            idle_win.reset(new std::atomic<unsigned>[devs.size()]);
            for (size_t di = 0; di < devs.size(); ++di) {
                cudaSetDevice(devs[di].id);
                CK(cudaEventCreateWithFlags(&idle_ev[di], cudaEventDisableTiming));
                idle_win[di].store(0u);
            }
        }
        if (o.expert_cache) {
            size_t maxb = 0;
            for (const Layer& l : L) maxb = std::max(maxb, l.blob);
            const int nt = std::max(1, std::min(c_inflight, std::getenv("DS4_CACHE_THREADS") ? std::atoi(std::getenv("DS4_CACHE_THREADS"))
                                                                                            : devs.size() > 1 ? 4 : 1));
            sw_bufs.resize((size_t) nt);
            for (SwapBufs& B : sw_bufs) {
                if (!halloc(B.a, maxb, err) || !halloc(B.b, maxb, err) || !halloc(B.h, maxb, err)) return false;
                for (Dev& d : devs) {
                    cudaSetDevice(d.id);
                    cudaStream_t cs = nullptr;
                    CK(cudaStreamCreateWithFlags(&cs, cudaStreamNonBlocking));
                    B.st.push_back(cs);
                }
            }
            for (SwapBufs& B : sw_bufs) cache_ths.emplace_back([this, &B] { cache_loop(B); });
        }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            CK(cudaStreamSynchronize(d.st));
        }
        if (par || chunk > 0)   // (the windows' threads; the prompt path's, whatever mode the windows take)
            for (size_t di = 0; di < devs.size(); ++di) {
                workers.push_back(std::make_unique<Worker>());
                workers.back()->start();
            }
        tune_lane();   // (before calibrate_paths: its CPU-lane speed is the chosen pools')
        calibrate_paths();
        lane_setup();
        one_gpu_plan();   // (#496: the one-GPU path kept only where something streams)
        if (o.verbose) std::fprintf(stderr, "ds4: loaded in %.1f s\n%s", (now_ms() - t0) / 1000.0, describe().c_str());
        reset();
        return true;
    }


    // the caches' row bytes, packed as DeepSeek keeps them (ds4_kernels.cuh): the window ring's (FP8), the compressed
    // KV's (FP4 + E4M3 scales), the index keys' (FP4 + power-of-two scales)
    size_t win_rb() const { return kv_row_bytes(kKvFp8, g.hd); }
    size_t ckv_rb() const { return kv_row_bytes(kKvFp4, g.hd); }
    size_t ik_rb() const { return kv_row_bytes(kKvFp4p, g.ix_hd); }

    // ---- the chunked prompt path
    size_t x_cap() const { return (size_t) std::max<int>(kWin, chunk + 2); }   // a window's / chunk's new source rows
    size_t chunk_hand_bytes() const {
        return (size_t) chunk * ((size_t) g.hc * g.dim * 4 + 8 * 4 + topk_stride() * 4 + cand_stride() * 4);
    }

    // the chunk path's device buffers, laid out from base (nullptr: only their bytes counted): `part` 1 those of a fixed
    // size (the attention's and the indexer's slabs, the weights' FP16 reconstructions, Engram's slabs), 2 those of C rows
    // (a lending device's borrowed room: a short prompt borrows little), 3 both
    size_t lay_chunk(Chunk& c, int C, uint8_t* base, int part = 3) const {
        size_t off = 0;
        auto put = [&](auto*& p, size_t n) {
            using T = std::remove_reference_t<decltype(*p)>;
            if (base != nullptr) p = (T*) (base + off);
            off += align256(n * sizeof(T));
        };
        const size_t Z = (size_t) C, D = (size_t) g.dim, H = (size_t) g.hc, HD = (size_t) g.hd, A = (size_t) c.A,
                     AI = (size_t) c.AI, ss = (size_t) o.max_context + 64, HQ = (size_t) c.HQ, OG = (size_t) c.OG,
                     FF = (size_t) c.FF, ES = 256, cols = (size_t) (pk.eg_ngram - 1) * pk.eg_heads,
                     ehd = (size_t) pk.eg_hd;
        if (part & 1) {
            put(c.q, A * HQ), put(c.o, A * HQ), put(c.o16, A * HQ), put(c.oa, A * OG * g.o_lora);
            put(c.oa16, A * OG * g.o_lora), put(c.iq, AI * g.ix_heads * g.ix_hd), put(c.scores, AI * ss);
            put(c.bm, AI * bm_stride()), put(c.bounds, 2048), put(c.w16, c.w16_elems);
            if (c.has_eg) put(c.eg_x, ES * cols * ehd), put(c.eg_x16, ES * cols * ehd), put(c.eg_kv, ES * (H + 1) * D);
        }
        if (part & 2) {
            put(c.h, Z * H * D), put(c.x, Z * D), put(c.acc, Z * D), put(c.x16, Z * D), put(c.qr, Z * g.q_lora);
            put(c.qr16, Z * g.q_lora), put(c.kvr, Z * HD), put(c.ckr, Z * HD), put(c.cgr, Z * HD);
            put(c.latent, (Z + 2) * HD), put(c.lat16, (Z + 2) * HD), put(c.ikr, (Z + 2) * g.ix_hd);
            put(c.ext, ((size_t) g.win + Z) * HD), put(c.iw, Z * 64), put(c.topk, Z * topk_stride());
            put(c.cand, Z * cand_stride()), put(c.mix, Z * 32), put(c.a_pre, Z * 8), put(c.a_post, Z * 8);
            put(c.a_comb, Z * 64), put(c.f_pre, Z * 8), put(c.f_post, Z * 8), put(c.f_comb, Z * 64), put(c.pre, Z * 8);
            put(c.glog, Z * 1024), put(c.ridx, Z * kPicks), put(c.rw, Z * kPicks), put(c.row_tok, Z * kPicks);
            put(c.pos, Z * kPicks), put(c.sg, Z * FF), put(c.su, Z * FF), put(c.sh16, Z * FF), put(c.h16, Z * FF);
            put(c.y, Z * D + 32);   // (+32: allreduce_dma's FP16 pieces in it)
            if (c.has_first) put(c.emb, Z * D);
            if (c.has_eg) put(c.eg_rows, Z * cols * (ehd + ehd / 32));
        }
        return off;
    }

    // the default chunk where every GPU will lend the prompt path its room (a GGUF's in-place experts on the flow, each
    // layer on one GPU: Chunk::borrow) - the borrowed room is expert slots between prompts, so a larger chunk costs the
    // decode nothing, and a long prompt runs in fewer passes over the streamed experts (one V100, Maya-S from an NVMe,
    // 32K tokens: 200 s in chunks of 8K, 183 in 16K, 157 in 32K): the largest of 32K / 16K tokens whose rows take at
    // most half of each GPU's experts' room (its free memory less the reserve and its share of the other weights,
    // estimated), and with hand-offs between groups their pinned rows (two chunks a GPU) within an eighth of the RAM;
    // else c0
    int chunk_default(int c0) const {
        const auto env_on = [](const char* k) { return std::getenv(k) == nullptr || std::atoi(std::getenv(k)) != 0; };
        const bool tp_lend = tp_borrow_on();   // (DS4_TP_BORROW: a group's members lend their room as one GPU does)
        if (!pk.gguf || !file_experts || !(one_gpu_or("DS4_BORROW") || tp_lend) || !env_on("DS4_FLOW")) return c0;
        for (const Group& G : groups)
            if (G.mem.size() > 1 && !tp_lend) return c0;
        double other_b = 0;
        for (const auto& kt : pk.t) {
            const std::string& n = kt.first;
            if (n.find(".engram.embed.") != std::string::npos || n.rfind("vision.", 0) == 0 || n == "embed.weight" ||
                n.rfind("mtp.", 0) == 0 || n.find(".ffn.experts.") != std::string::npos)
                continue;
            other_b += (double) kt.second.bytes;
        }
        Chunk tc;
        chunk_dims(tc, 1);
        tc.has_first = true;
        tc.has_eg = pk.eg_layers > 0;
        const double hand_row = (double) g.hc * g.dim * 4 + 32 + (double) topk_stride() * 4 + (double) cand_stride() * 4;
        const uint64_t ram = ram_room();
        for (int C : {kMaxChunk, kMaxChunk / 2}) {
            if (C <= c0) break;
            const double rows = (double) lay_chunk(tc, C, nullptr, 2);
            bool ok = true;
            for (const Dev& d : devs) {
                const double room = std::max(0.0, (double) d.free0 - (double) ((size_t) o.reserve_mib << 20)) * o.vram_experts -
                                    other_b / (double) devs.size() - 0.6e9;
                ok = ok && rows <= room / 2.0;
            }
            if (groups.size() > 1 && ram != ~uint64_t{0}) ok = ok && 2.0 * C * hand_row * (double) devs.size() <= (double) ram / 8.0;
            if (ok) return C;
        }
        return c0;
    }
    // a device's chunk dimensions in a group of nm members: its heads' width, wo_a groups and FFN share (the widest
    // member's: member 0 takes split128's odd blocks), the attention's and the indexer's slabs (the indexer's scores
    // rows are the context wide - about 64 MB of them)
    void chunk_dims(Chunk& c, int nm, size_t mem = 0) const {
        const int NHL = g.heads / head_members(nm), HQ = NHL * g.hd, OG = g.o_groups / head_members(nm);
        int FF = 0, ff0_ = 0;
        if (tp_uneven) splitb(g.ff, tp_blk, nm, 0, ff0_, FF);   // (rot 0: member 0 takes the odd block - the widest)
        else split128(g.ff, nm, 0, ff0_, FF);
        c.HQ = HQ, c.OG = OG, c.FF = FF;
        // The attention slab (its q in millions of values: the rows of q, the sparse attention and the output
        // projections at a time) and the dense weights' FP16 scratch (MB): 8 / 16, or on a device with much memory
        // (mem: its free memory) the largest pair 2^k / 2^(k+1) up to 64 / 128 within 3% of it - fewer, wider GEMMs
        // and fewer FP16 reconstructions of the same weights a prompt (a Strix Halo with ~170 GB for its GPU: 64 / 128,
        // a 4K prompt +6%; 8 / 16 left the GEMMs too few tiles for its 40 CUs).  The 0.6% before left a 32 GB card at
        // 8 / 16: slabs of 256 rows, every attention weight decoded to FP16 32 times an 8K chunk (3x V100, Maya-XS: an
        // 8K prompt +16%, 32K +17% at 32 / 64, decode the same within noise).  24-32 GB now 32 / 64, 16 GB 16 / 32.
        // DS4_ATTN_SLAB_MB / DS4_W16_MB set them by hand.
        const size_t row_b = (size_t) HQ * 10 + (size_t) OG * g.o_lora * 6;   // (q, o F32; o FP16; oa F32 + FP16)
        size_t auto_mb = 8;
        for (size_t s = 64; s > 8 && mem > 0; s /= 2) {
            const size_t rows = std::max<size_t>(64, (s << 20) / (size_t) HQ / 64 * 64);
            if ((double) (rows * row_b + ((2 * s) << 20)) <= 0.03 * (double) mem) {
                auto_mb = s;
                break;
            }
        }
        const char* slab_mb = std::getenv("DS4_ATTN_SLAB_MB");
        const char* w16_mb = std::getenv("DS4_W16_MB");
        const size_t qb = (slab_mb != nullptr ? (size_t) std::max(1, std::atoi(slab_mb)) : auto_mb) << 20;
        c.A = std::max(64, (int) (qb / (size_t) HQ) / 64 * 64);
        c.AI = std::max(32, std::min(128, (int) (((size_t) 64 << 20) / (((size_t) o.max_context + 64) * 4)) / 32 * 32));
        c.w16_elems = (w16_mb != nullptr ? (size_t) std::max(1, std::atoi(w16_mb)) : 2 * auto_mb) << 19;
    }

    bool alloc_chunks(std::string& err) {
        chunks.resize(devs.size());
        const int D = g.dim;
        const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
        // a device whose trunk layers will all be on the flow (as in load(): a GGUF's in-place experts, each layer on
        // it alone) lends its buffers' room to its experts between prompts - on one GPU (DS4_BORROW=1: on more too,
        // =0: its own room, as before)
        const bool borrow_on = file_experts && one_gpu_or("DS4_BORROW") &&
                               (std::getenv("DS4_FLOW") == nullptr || std::atoi(std::getenv("DS4_FLOW")) != 0);
        // DS4_TP_BORROW=1: a device whose every trunk layer is a tensor-parallel group's member on the flow (the flow's
        // own condition for a member, below in load) lends as such - only when every member of its group does (a
        // group's slots past n_main lie in each member's tail, or in none)
        std::vector<char> tp_ok(devs.size(), 0);
        if (file_experts && tp_borrow_on() &&
            (std::getenv("DS4_FLOW") == nullptr || std::atoi(std::getenv("DS4_FLOW")) != 0)) {
            std::vector<char> any(devs.size(), 0);
            for (size_t di = 0; di < devs.size(); ++di) tp_ok[di] = 1;
            for (const Layer& l : L)
                for (int m = 0; m < l.nm && !l.mtp; ++m) {
                    const size_t di = (size_t) member(l, m).dev;
                    any[di] = 1;
                    tp_ok[di] = tp_ok[di] && l.nm > 1 && l.lay.fmt == gg::kFmtMXFP4 &&
                                (tp_uneven ||
                                 (g.ff / l.nm) % std::max(1, gg::type_block(gg::expert_type(l.lay, 2))) == 0);
                }
            for (size_t di = 0; di < devs.size(); ++di) tp_ok[di] = tp_ok[di] && any[di];
            for (const Group& G : groups) {
                bool all = G.mem.size() > 1;
                for (int m : G.mem) all = all && tp_ok[(size_t) m];
                for (int m : G.mem) tp_ok[(size_t) m] = all;
            }
        }
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            cudaSetDevice(d.id);
            const size_t s0 = d.scratch;   // (this device's chunk buffers: d.prompt, not d.scratch)
            chunks[di] = std::make_unique<Chunk>();
            Chunk& c = *chunks[di];
            chunk_dims(c, (int) groups[(size_t) d.grp].mem.size(), d.free0);
            if (o.verbose)
                std::fprintf(stderr, "ds4: CUDA%d prompt slabs: the attention %d rows, the dense weights' FP16 scratch %zu MB\n",
                             d.id, c.A, c.w16_elems >> 19);
            const size_t C = (size_t) chunk;
            c.C = chunk;
            bool has_eg = false, has_first = false, lend = borrow_on;
            size_t stride = 0;
            for (const Layer& l : L)
                for (int m = 0; m < l.nm; ++m)
                    if (member(l, m).dev == (int) di && !l.mtp) {
                        has_eg = has_eg || l.eg >= 0;
                        has_first = has_first || l.il == 0;
                        stride = std::max(stride, align256(unit(member(l, m))));
                        lend = lend && l.nm == 1 && l.lay.fmt == gg::kFmtMXFP4;
                    }
            c.has_eg = has_eg, c.has_first = has_first;
            c.tp_lend = tp_ok[di] && stride > 0;   // (DS4_TP_BORROW: lend is false here - its layers are a group's)
            c.borrow = (lend || c.tp_lend) && stride > 0;
            {   // (its own room, laid out once: all of it, or a lending device's buffers of a fixed size)
                const int part = c.borrow ? 1 : 3;
                c.room_bytes = lay_chunk(c, chunk, nullptr, part);
                if (!dalloc(d, c.own, c.room_bytes, err)) return false;
                lay_chunk(c, chunk, c.own, part);
                c.room = c.own;
            }
            if (!halloc(c.bounds_pin, 2048, err)) return false;
            if (stride > 0) {   // DS4_RING_MB (400) of slots in kParts batches
                const size_t mb = std::getenv("DS4_RING_MB") ? (size_t) std::atoi(std::getenv("DS4_RING_MB")) : 400;
                c.ring_stride = stride;
                c.ring_n = std::max(Chunk::kParts, (int) ((mb << 20) / stride) / Chunk::kParts * Chunk::kParts);
                if (!dalloc(d, c.ring, (size_t) c.ring_n * stride, err)) return false;
            }
            const size_t down_b = flow_down_bytes((int) di);   // (the flow's down scratch, where it takes one)
            if (down_b > 0 && !dalloc(d, c.down, down_b, err)) return false;
            CK(cudaStreamCreateWithFlags(&c.cs, cudaStreamNonBlocking));
            for (int i = 0; i < Chunk::kParts; ++i) {
                CK(cudaEventCreateWithFlags(&c.filled[i], cudaEventDisableTiming));
                CK(cudaEventCreateWithFlags(&c.freed[i], cudaEventDisableTiming));
            }
            if (cublasCreate(&c.blas) != CUBLAS_STATUS_SUCCESS || cublasSetStream(c.blas, d.st) != CUBLAS_STATUS_SUCCESS) {
                err = "cuBLAS on CUDA" + std::to_string(d.id);
                return false;
            }
            // (the hand-offs between groups: none where one group holds every layer - a chunk's h alone is 80 KB a row)
            const bool hands = d.mi == 0 && groups.size() > 1;
            for (int sl = 0; sl < 2; ++sl) {
                if (hands && (!hmap(c.hand[sl], chunk_hand_bytes(), err) || !hmap(c.hand_flag[sl], 32, err))) return false;
                if (has_first && !halloc(c.emb_host[sl], C * D, err)) return false;
                if (has_eg && !halloc(c.eg_host[sl], C * pk.eg_layers * (size_t) cols * (ehd + ehd / 32), err)) return false;
                CK(cudaEventCreateWithFlags(&c.emb_ev[sl], cudaEventDisableTiming));
                CK(cudaEventCreateWithFlags(&c.eg_ev[sl], cudaEventDisableTiming));
            }
            if (hands && !hmap(c.hand_ack, (size_t) 2 * 8 * 32, err)) return false;
            CK(cudaStreamCreateWithFlags(&c.ar_aux.s2, cudaStreamNonBlocking));
            for (cudaEvent_t& e : c.ar_aux.ev) CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
            CK(cudaStreamCreateWithFlags(&c.ar_s, cudaStreamNonBlocking));
            CK(cudaStreamCreateWithFlags(&c.ar_aux2.s2, cudaStreamNonBlocking));
            for (cudaEvent_t& e : c.ar_aux2.ev) CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
            CK(cudaEventCreateWithFlags(&c.ar_go, cudaEventDisableTiming));
            CK(cudaEventCreateWithFlags(&c.ar_done, cudaEventDisableTiming));
            d.prompt += d.scratch - s0;
            d.scratch = s0;
        }
        return true;
    }

    // y[r][c] = x16[r] . W[:, c] (+ beta y) for r < rows: W reconstructed to FP16 in whole 128-column blocks, cuBLAS
    bool gemm(Dev& d, Chunk& c, const x3::Mat& m, const uint16_t* x16, int ldx, int rows, float* y, int ldy, float beta,
              std::string& err) {
        if (rows <= 0) return true;
        const int cols = std::max(128, (int) std::min<size_t>((size_t) m.n, c.w16_elems / (size_t) m.k) / 128 * 128);
        for (int c0 = 0; c0 < m.n; c0 += cols) {
            const int nc = std::min(cols, m.n - c0);
            if (m.fmt != 0) gg::rows(nc == m.n ? m : gg::view(m, c0, nc), c.w16, false, d.st);   // (a GGUF's)
            else x3::reconstruct_rows(nc == m.n ? m : x3::view(m, c0, nc), c.w16, false, d.st);
            if (beta == 0.0f && lt::gemm(d.st, c.w16, nc, m.k, x16, ldx, rows, y + c0, ldy)) continue;   // (AMD)
            const float one = 1.0f;
            const cublasStatus_t st = cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, nc, rows, m.k, &one, c.w16, CUDA_R_16F,
                                                   m.k, x16, CUDA_R_16F, ldx, &beta, y + c0, CUDA_R_32F, ldy,
                                                   CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
            if (st != CUBLAS_STATUS_SUCCESS) {
                err = "cublasGemmEx: status " + std::to_string((int) st);
                return false;
            }
        }
        return true;
    }
    // ---- the busy experts (run_set): an expert of many rows as FP16 GEMMs.  The tiles decode its weights again for
    // every 64 of its rows (a prompt's chunk gives a popular expert hundreds); decoded once, to the FP16 values the tiles
    // multiply (iq::f16_rows), the library's GEMM takes them at its own speed.  DS4_FAT_ROWS=N (default 64; 0: off)
    // takes the experts of N rows or more; the same products, only the sums' order differs
    // (3x V100, Maya-XS: 64 rows +6-8% on 8K / 32K prompts; KL vs the reference 0.276, the stock path 0.285 - the same)
    static int fat_rows() {
        static const int n = std::getenv("DS4_FAT_ROWS") ? std::max(0, std::atoi(std::getenv("DS4_FAT_ROWS"))) : 64;
        return n;
    }
    bool fat_ready(Dev& d, Chunk& c, int D, int FF) {
#if defined(STRATA_USE_HIP)
        (void) d, (void) c, (void) D, (void) FF;
        return false;
#else
        if (fat_rows() <= 0 || c.fat_off) return false;
        if (c.fat_w != nullptr) return FF <= c.fat_ff;   // (wider than allocated: the tiles take it)
        // (sized for the widest FFN this device's layers give it, not the first one's: with DS4_TP_GGUF_UNEVEN the odd
        //  block goes round the members layer by layer, so a member's width differs between its layers)
        const int di = (int) (&d - devs.data());   // (c.dev: the flow's chunks only)
        for (const Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m)
                if (member(l0, m).dev == di) FF = std::max(FF, member(l0, m).ffn);
        static const int R = std::getenv("DS4_FAT_PIECE") ? std::max(64, std::atoi(std::getenv("DS4_FAT_PIECE"))) : 1024;
        if (cudaSetDevice(d.id) != cudaSuccess || cudaMalloc(&c.fat_w, (size_t) 2 * FF * D * 2) != cudaSuccess ||
            cudaMalloc(&c.fat_x, (size_t) R * D * 2) != cudaSuccess ||
            cudaMalloc(&c.fat_gu, (size_t) R * 2 * FF * 4) != cudaSuccess) {
            cudaGetLastError();
            std::fprintf(stderr, "ds4: CUDA%d: no VRAM for the busy experts' path (%.0f MB): the tiles take them\n", d.id,
                         ((double) 2 * FF * D * 2 + (double) R * D * 2 + (double) R * 2 * FF * 4) / 1e6);
            c.fat_off = true;
            return false;
        }
        c.fat_r = R;
        c.fat_ff = FF;
        std::fprintf(stderr, "ds4: CUDA%d busy experts (%d rows or more) as FP16 GEMMs, %d rows a piece, FFN up to %d "
                     "(%.0f MB)\n", d.id, fat_rows(), R, FF,
                     ((double) 2 * FF * D * 2 + (double) R * D * 2 + (double) R * 2 * FF * 4) / 1e6);
        return true;
#endif
    }
    // h16[lr0 + r] = FP16 clamped SwiGLU of the expert's gate and up over x16[row_tok[row + r]], r < n
    bool fat_gate_up(Chunk& c, const x3::SetArgs& sa, const uint8_t* blob, int row, int n, int a, int D, int FF,
                     cudaStream_t s, std::string& err) {
        const int tg = gg::expert_type(sa.lay, 0);
        if (!gg::iq::f16_rows(tg, blob + sa.lay.trellis[0], D, FF, c.fat_w, D, s) ||
            !gg::iq::f16_rows(tg, blob + sa.lay.trellis[1], D, FF, c.fat_w + (size_t) FF * D, D, s)) {
            err = "the busy experts' path: gate / up not decoded";
            return false;
        }
        const float one = 1.0f, zero = 0.0f;
        for (int p0 = 0; p0 < n; p0 += c.fat_r) {
            const int np = std::min(c.fat_r, n - p0);
            gg::iq::gather_f16(c.x16, D, c.row_tok + row + p0, np, D, c.fat_x, s);
            if (cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, 2 * FF, np, D, &one, c.fat_w, CUDA_R_16F, D, c.fat_x,
                             CUDA_R_16F, D, &zero, c.fat_gu, CUDA_R_32F, 2 * FF, CUBLAS_COMPUTE_32F,
                             CUBLAS_GEMM_DEFAULT_TENSOR_OP) != CUBLAS_STATUS_SUCCESS) {
                err = "the busy experts' path: cublasGemmEx (gate / up) failed";
                return false;
            }
            gg::iq::swiglu_f16(c.fat_gu, 2 * FF, np, FF, sa.limit, c.h16 + (size_t) (row - a + p0) * FF, FF, s);
        }
        return true;
    }
    // y[lr0 + r] = down(h16[lr0 + r]), r < n
    bool fat_down(Chunk& c, const x3::SetArgs& sa, const uint8_t* blob, int lr0, int n, int D, int FF, cudaStream_t s,
                  std::string& err) {
        if (!gg::iq::f16_rows(gg::expert_type(sa.lay, 2), blob + sa.lay.trellis[2], FF, D, c.fat_w, FF, s)) {
            err = "the busy experts' path: down not decoded";
            return false;
        }
        const float one = 1.0f, zero = 0.0f;
        if (cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, D, n, FF, &one, c.fat_w, CUDA_R_16F, FF,
                         c.h16 + (size_t) lr0 * FF, CUDA_R_16F, FF, &zero, c.y + (size_t) lr0 * D, CUDA_R_32F, D,
                         CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP) != CUBLAS_STATUS_SUCCESS) {
            err = "the busy experts' path: cublasGemmEx (down) failed";
            return false;
        }
        return true;
    }
    // y[r][c] = alpha x16[r] . W[c] for F16 weights W [n][k] (the indexer's weights_proj)
    bool gemm_f16w(Chunk& c, const uint16_t* W, int n, int k, const uint16_t* x16, int ldx, int rows, float alpha,
                   float* y, int ldy, std::string& err) {
        const float zero = 0.0f;
        const cublasStatus_t st = cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, n, rows, k, &alpha, W, CUDA_R_16F, k,
                                               x16, CUDA_R_16F, ldx, &zero, y, CUDA_R_32F, ldy, CUBLAS_COMPUTE_32F,
                                               CUBLAS_GEMM_DEFAULT_TENSOR_OP);
        if (st != CUBLAS_STATUS_SUCCESS) {
            err = "cublasGemmEx (F16 weights): status " + std::to_string((int) st);
            return false;
        }
        return true;
    }
    // hc_mix over a chunk: the dots by an F32 GEMM, then the rms scale
    bool hc_mix_chunk(Dev& d, Chunk& c, const float* h, const float* fn, int T, float* mixes, std::string& err) {
        const int hcd = g.hc * g.dim, n_mix = (2 + g.hc) * g.hc;
        const float one = 1.0f, zero = 0.0f;
        if (cublasSgemm(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, n_mix, T, hcd, &one, fn, hcd, h, hcd, &zero, mixes, 32) !=
            CUBLAS_STATUS_SUCCESS) {
            err = "cublasSgemm (mHC mixes)";
            return false;
        }
        hc_mix_scale(h, hcd, n_mix, T, g.eps, mixes, d.st);
        return true;
    }

    // expert e of l (on the CPU lane: its NH column parts) -> member m's VRAM copy at dst, in the GPU layout (the full
    // blob, or a group member's part), by DMA from the pinned parts on the copy stream (in place: from `src`, its file
    // region read into pinned staging)
    bool stream_expert(const Layer& l, int m, int e, uint8_t* dst, cudaStream_t cs, std::string& err,
                       const uint8_t* src = nullptr) {
        if (l.lay.fmt == gg::kFmtMXFP4) {   // the blob, or member m's rows / blocks: from `src` (the expert read into
            // pinned staging as its blob) or from the file's mapping
            // Copied GGUF experts hold whole matrix rows on each NUMA node. mx_mat() is only
            // part 0 in this case; reading a full matrix from it corrupts its second half.
            const bool copied = src == nullptr && copy_mode && !l.ram.empty() && l.ram[(size_t) e] >= 0;
            auto copy_rows = [&](int r, uint8_t* out, size_t out_pitch, int first, int rows,
                                 size_t col, size_t width) {
                const size_t pitch = mx_row_b(l, r);
                const int parts = copied ? NH : 1, per = mx_n(r) / parts;
                for (int X = 0; X < parts; ++X) {
                    const int lo = std::max(first, X * per), hi = std::min(first + rows, (X + 1) * per);
                    if (lo >= hi) continue;
                    const uint8_t* base = copied ? mx_part_ptr(l, e, r, X)
                                                : src != nullptr ? src + l.lay.trellis[r] : mx_mat(l, e, r);
                    const uint8_t* from = base + (size_t) (lo - X * per) * pitch + col;
                    uint8_t* to = out + (size_t) (lo - first) * out_pitch;
                    const cudaError_t status = width == pitch && width == out_pitch
                        ? cudaMemcpyAsync(to, from, (size_t) (hi - lo) * width, cudaMemcpyHostToDevice, cs)
                        : cudaMemcpy2DAsync(to, out_pitch, from, pitch, width, (size_t) (hi - lo),
                                            cudaMemcpyHostToDevice, cs);
                    if (status != cudaSuccess) return false;
                }
                return true;
            };
            bool ok = true;
            if (l.nm == 1) {
                if (src != nullptr)
                    ok = cudaMemcpyAsync(dst, src, l.blob, cudaMemcpyHostToDevice, cs) == cudaSuccess;
                else
                    for (int r = 0; r < 3; ++r)
                        ok = ok && copy_rows(r, dst + l.lay.trellis[r], mx_row_b(l, r), 0, mx_n(r), 0, mx_row_b(l, r));
            } else {   // gate/up: this member's rows; down: its columns across every NUMA row part
                const Layer& x = member(l, m);
                const size_t d0 = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ff0),
                             dh = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn);
                for (int r = 0; r < 2; ++r) {
                    const size_t gr = mx_row_b(l, r);
                    ok = ok && copy_rows(r, dst + x.hlay.trellis[r], gr, x.ff0, x.ffn, 0, gr);
                }
                ok = ok && copy_rows(2, dst + x.hlay.trellis[2], dh, 0, g.dim, d0, dh);
            }
            if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
            return ok;
        }
        const auto& parts = l.hh[(size_t) e];
        if (l.packed_host && src == nullptr) {
            const bool ok = cudaMemcpyAsync(dst, parts[0] + (size_t) m * l.hblob, l.hblob,
                                             cudaMemcpyHostToDevice, cs) == cudaSuccess;
            if (!ok) err = "streaming packed layer " + std::to_string(l.il) + " expert " + std::to_string(e);
            return ok;
        }
        const int D = g.dim, FF = g.ff;
        auto cp2 = [&](uint8_t* d0, size_t dp, const uint8_t* s0, size_t sp, size_t w, size_t h) {
            return cudaMemcpy2DAsync(d0, dp, s0, sp, w, h, cudaMemcpyHostToDevice, cs) == cudaSuccess;
        };
        auto cp = [&](uint8_t* d0, const uint8_t* s0, size_t n) {
            return cudaMemcpyAsync(d0, s0, n, cudaMemcpyHostToDevice, cs) == cudaSuccess;
        };
        bool ok = true;
        if (NH == 1) {   // one part: the whole expert in exllamav3's layout, its pieces at hl's offsets
            const uint8_t* p = src != nullptr ? src : parts[0];
            if (l.nm == 1) {
                for (int r = 0; r < 3; ++r)
                    ok = ok && cp(dst + l.lay.trellis[r], p + l.hl.trellis[r], l.piece_bytes[r][0]) &&
                         cp(dst + l.lay.suh[r], p + l.hl.suh[r], (size_t) l.hl.k[r] * 2) &&
                         cp(dst + l.lay.svh[r], p + l.hl.svh[r], (size_t) l.hl.n[r] * 2);
            } else {   // member m's part (its FFN columns [f0, f0 + fn)), cut as blob_to_half cuts a blob
                const Layer& x = member(l, m);
                const int f0 = x.ff0, fn = x.ffn;
                for (int r = 0; r < 2; ++r) {
                    const size_t tile = (size_t) 16 * l.lay.k2[r], nt = (size_t) FF / 16, nth = (size_t) fn / 16;
                    ok = ok && cp2(dst + x.hlay.trellis[r], nth * tile, p + l.hl.trellis[r] + (size_t) (f0 / 16) * tile,
                                   nt * tile, nth * tile, (size_t) D / 16) &&
                         cp(dst + x.hlay.suh[r], p + l.hl.suh[r], (size_t) D * 2) &&
                         cp(dst + x.hlay.svh[r], p + l.hl.svh[r] + (size_t) f0 * 2, (size_t) fn * 2);
                }
                const size_t row = (size_t) (D / 16) * 16 * l.lay.k2[2];
                ok = ok && cp(dst + x.hlay.trellis[2], p + l.hl.trellis[2] + (size_t) (f0 / 16) * row,
                              (size_t) (fn / 16) * row) &&
                     cp(dst + x.hlay.suh[2], p + l.hl.suh[2] + (size_t) f0 * 2, (size_t) fn * 2) &&
                     cp(dst + x.hlay.svh[2], p + l.hl.svh[2], (size_t) D * 2);
            }
        } else if (l.nm == 1) {   // the full blob: each matrix's columns from the two parts side by side
            for (int r = 0; r < 3; ++r) {
                const size_t tile = (size_t) 16 * l.lay.k2[r];
                const int k = l.hl.k[r], nh = l.hl.n[r];   // part: k x nh
                for (int X = 0; X < 2; ++X) {
                    ok = ok && cp2(dst + l.lay.trellis[r] + (size_t) X * (nh / 16) * tile, (size_t) (2 * nh / 16) * tile,
                                   parts[(size_t) X] + l.hl.trellis[r], (size_t) (nh / 16) * tile, (size_t) (nh / 16) * tile,
                                   (size_t) (k / 16));
                    ok = ok && cp(dst + l.lay.svh[r] + (size_t) X * nh * 2, parts[(size_t) X] + l.hl.svh[r], (size_t) nh * 2);
                }
                ok = ok && cp(dst + l.lay.suh[r], parts[0] + l.hl.suh[r], (size_t) k * 2);
            }
        } else {   // member m (FFN columns [f0, f0 + fn)): gate / up from the parts holding them; down rows [f0, ..) of
                   // both parts' columns
            const Layer& x = member(l, m);
            const int f0 = x.ff0, fn = x.ffn;
            for (int r = 0; r < 2; ++r) {
                const size_t tile = (size_t) 16 * l.lay.k2[r];
                const int hn = l.hl.n[r];   // part X: columns [X hn, (X + 1) hn)
                for (int X = 0; X < 2; ++X) {
                    const int a = std::max(f0, X * hn), b = std::min(f0 + fn, (X + 1) * hn);
                    if (a >= b) continue;
                    ok = ok && cp2(dst + x.hlay.trellis[r] + (size_t) ((a - f0) / 16) * tile, (size_t) (fn / 16) * tile,
                                   parts[(size_t) X] + l.hl.trellis[r] + (size_t) ((a - X * hn) / 16) * tile,
                                   (size_t) (hn / 16) * tile, (size_t) ((b - a) / 16) * tile, (size_t) (D / 16)) &&
                         cp(dst + x.hlay.svh[r] + (size_t) (a - f0) * 2, parts[(size_t) X] + l.hl.svh[r] + (size_t) (a - X * hn) * 2,
                            (size_t) (b - a) * 2);
                }
                ok = ok && cp(dst + x.hlay.suh[r], parts[0] + l.hl.suh[r], (size_t) D * 2);
            }
            const size_t tile = (size_t) 16 * l.lay.k2[2];
            const int nh = D / 2;
            for (int X = 0; X < 2; ++X) {
                ok = ok && cp2(dst + x.hlay.trellis[2] + (size_t) X * (nh / 16) * tile, (size_t) (D / 16) * tile,
                               parts[(size_t) X] + l.hl.trellis[2] + (size_t) (f0 / 16) * (nh / 16) * tile,
                               (size_t) (nh / 16) * tile, (size_t) (nh / 16) * tile, (size_t) (fn / 16));
                ok = ok && cp(dst + x.hlay.svh[2] + (size_t) X * nh * 2, parts[(size_t) X] + l.hl.svh[2], (size_t) nh * 2);
            }
            ok = ok && cp(dst + x.hlay.suh[2], parts[0] + l.hl.suh[2] + (size_t) f0 * 2, (size_t) fn * 2);
        }
        if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
        return ok;
    }

    // a device's streamed experts: batches of ring_n / kParts of each of its layers' CPU-lane experts, chunk by chunk
    // in layer order; the copies run at most kParts batches ahead of the compute
    struct Batch {
        int k = 0, il = 0, j0 = 0, n = 0;   // chunk, layer, its host_list range
    };
    struct Streamer {
        std::vector<Batch> b;
        size_t cp = 0, kp = 0;        // the next batch to copy, to compute
        std::atomic<size_t> done{0};  // cp, for read_ahead's thread
        const bool collect_prefill = std::getenv("DS4_PREFILL_STATS") != nullptr &&
                                     std::atoi(std::getenv("DS4_PREFILL_STATS")) != 0;
        PrefillCounts prefill;
        void report_prefill(int gpu, int tokens, int chunk, double streamed_bytes) const {
            if (!collect_prefill) return;
            std::fprintf(stderr, "DS4_PREFILL gpu=%d tokens=%d chunk=%d expert_row_picks=%llu vram_row_picks=%llu "
                         "unique_expert_uses=%llu vram_unique_expert_uses=%llu streamed_weight_bytes=%llu\n",
                         gpu, tokens, chunk, (unsigned long long) prefill.picks,
                         (unsigned long long) prefill.vram_picks, (unsigned long long) prefill.unique_uses,
                         (unsigned long long) prefill.vram_unique_uses, (unsigned long long) streamed_bytes);
        }
        int routed_layer = -1, routed_chunk = -1;
        std::vector<int> routed_bounds;
        size_t skipped = 0, copied = 0;
    };
    // in place (file_experts): the batches' file regions read ahead of their copies - POSIX_FADV_WILLNEED, the kernel
    // reading them in the background in large requests, where the copies alone fault the pages in a few at a time -
    // at most DS4_READAHEAD_MB (2048) beyond the batch being copied; each region by its layer's first member alone
    void read_ahead(const Streamer& S, int di, const std::atomic<bool>& stop) const {
        static const double cap = (std::getenv("DS4_READAHEAD_MB") ? std::atof(std::getenv("DS4_READAHEAD_MB")) : 2048.0) *
                                  1048576.0;
        std::deque<std::pair<size_t, double>> issued;   // (batch, bytes) not yet copied
        double ahead = 0;
        for (size_t q = 0; q < S.b.size() && !stop.load(std::memory_order_relaxed);) {
            const size_t done = S.done.load(std::memory_order_relaxed);
            while (!issued.empty() && issued.front().first < done) {
                ahead -= issued.front().second;
                issued.pop_front();
            }
            if (ahead > cap) {
                std::this_thread::sleep_for(std::chrono::microseconds(500));
                continue;
            }
            const Batch& bt = S.b[q];
            const Layer& l0 = L[(size_t) bt.il];
            double nb = 0;
            if (l0.dev == di)
                for (int i = 0; i < bt.n; ++i) {
                    const int e = l0.host_list[(size_t) (bt.j0 + i)];
                    if (l0.lay.fmt == gg::kFmtMXFP4) {
                        if (copy_mode && l0.ram[(size_t) e] >= 0) continue;   // (in RAM: nothing to read)
                        for (int r = 0; r < 3; ++r)
                            os::advise(pk.fds[(size_t) l0.mx_file[r]], (l0.mx_off[r] + (uint64_t) e * l0.mx_stride[r]), mx_part_bytes(l0, r), true);
                        nb += (double) l0.blob;
                        continue;
                    }
                    os::advise(pk.fds[(size_t) l0.region_file[(size_t) e]], l0.region_off[(size_t) e], l0.region_bytes[(size_t) e], true);
                    nb += (double) l0.region_bytes[(size_t) e];
                }
            issued.push_back({q++, nb});
            ahead += nb;
        }
    }
    // copy_ahead's two steps for streamed expert e of l (the group's first member) to the device of member mi: what the
    // readers stage into its slot si, then the copies into the ring.  A GGUF's expert with a pinned copy (cp_dma) DMA'd
    // in place - each matrix's rows from the NUMA part holding them, a member's gate / up rows [ff0, ff0 + ffn) as their
    // runs - the readers gathering only a member's blocks of the down (mx_down_member); else a member's part staged as
    // its layout (read_mx_part, one DMA), alone the blob (read_mx) or an EXL3 expert's file region, as before
    bool stream_direct(const Layer& l, int e) const {
        return cp_dma && l.lay.fmt == gg::kFmtMXFP4 && !l.ram.empty() && l.ram[(size_t) e] >= 0;
    }
    bool stage_needed(const Layer& l, int e) const { return !stream_direct(l, e) || l.nm > 1; }
    bool stage_streamed(const Layer& l, int mi, int e, uint8_t* si) const {
        if (stream_direct(l, e)) {
            if (l.nm > 1) mx_down_member(l, e, mi, si);
            return true;
        }
        if (l.lay.fmt == gg::kFmtMXFP4) return l.nm > 1 ? read_mx_part(l, e, mi, si) : read_mx(l, e, si);
        return pk.read_at(l.region_file[(size_t) e], l.region_off[(size_t) e], l.region_bytes[(size_t) e], si);
    }
    bool copy_streamed(const Layer& l, int mi, int e, const uint8_t* si, uint8_t* dst, cudaStream_t cs,
                       std::string& err) {
        auto cp = [&](uint8_t* to, const uint8_t* from, size_t n) {
            return cudaMemcpyAsync(to, from, n, cudaMemcpyHostToDevice, cs) == cudaSuccess;
        };
        bool ok = true;
        if (stream_direct(l, e) && (l.nm == 1 || si != nullptr)) {
            const int s = l.ram[(size_t) e];
            if (l.nm == 1) {
                for (int r = 0; r < 3; ++r) {
                    const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
                    for (int X = 0; X < NH && ok; ++X)
                        ok = cp(dst + l.lay.trellis[r] + (size_t) X * nb,
                                ram_part[(size_t) s][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r], nb);
                }
            } else {
                const Layer& x = member(l, mi);
                for (int r = 0; r < 2; ++r) {
                    const size_t gr = mx_row_b(l, r);
                    const int nr = mx_n(r) / NH;
                    for (int X = 0; X < NH && ok; ++X) {
                        const int a = std::max(x.ff0, X * nr), b = std::min(x.ff0 + x.ffn, (X + 1) * nr);
                        if (a < b)
                            ok = cp(dst + x.hlay.trellis[r] + (size_t) (a - x.ff0) * gr,
                                    mx_part_ptr(l, e, r, X) + (size_t) (a - X * nr) * gr, (size_t) (b - a) * gr);
                    }
                }
                ok = ok && cp(dst + x.hlay.trellis[2], si,
                              (size_t) g.dim * gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn));
            }
        } else if (l.lay.fmt == gg::kFmtMXFP4 && l.nm > 1 && si != nullptr)
            ok = cp(dst, si, unit(member(l, mi)));
        else
            return stream_expert(l, mi, e, dst, cs, err, si);
        if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
        return ok;
    }
    bool copy_ahead(Dev& d, Chunk& c, Streamer& S, int di, std::string& err) {
        const int P = Chunk::kParts;
#if defined(STRATA_USE_HIP)
        static const bool skip_unpicked = std::getenv("DS4_SKIP_UNPICKED") != nullptr &&
                                          std::atoi(std::getenv("DS4_SKIP_UNPICKED")) != 0;
#else
        constexpr bool skip_unpicked = false;
#endif
        while (S.cp < S.b.size() && S.cp < S.kp + P) {
            const Batch& bt = S.b[S.cp];
            // Wait for this layer's routing rather than staging every expert
            // speculatively. Copies still overlap compute within the layer.
            if (skip_unpicked && (bt.il != S.routed_layer || bt.k != S.routed_chunk)) break;
            const int half = (int) (S.cp % P);
            const Layer& l0 = L[(size_t) bt.il];
            // Preserve the original virtual slots, batches and accumulation order.
            const auto picked = [&](int i) {
                if (!skip_unpicked || bt.il != S.routed_layer || bt.k != S.routed_chunk) return true;
                const size_t v = (size_t) l0.n_slots + bt.j0 + i;
                return S.routed_bounds[v + 1] > S.routed_bounds[v];
            };
            int mi = 0;
            for (int m = 0; m < l0.nm; ++m)
                if (member(l0, m).dev == di) mi = m;
            if (S.cp >= (size_t) P) CK(cudaStreamWaitEvent(c.cs, c.freed[half], 0));
            uint8_t* sb = nullptr;   // in place: the batch's regions in the part's staging slots
            bool staged = false;     // (a batch of copies in place, alone: nothing to stage)
            for (int i = 0; i < bt.n && !staged; ++i)
                staged = stage_needed(l0, l0.host_list[(size_t) (bt.j0 + i)]);
            if (c.stage != nullptr && staged) {
                if (S.cp >= (size_t) P) CK(cudaEventSynchronize(c.filled[half]));   // (its last batch's copies out)
                sb = c.stage + (size_t) half * (c.ring_n / P) * c.stage_stride;
                std::atomic<bool> bad{false};
                c.readers->run(bt.n, [&](int i) {
                    if (!picked(i)) return;   // (DS4_SKIP_UNPICKED: an expert no token routed to)
                    if (!stage_streamed(l0, mi, l0.host_list[(size_t) (bt.j0 + i)], sb + (size_t) i * c.stage_stride))
                        bad.store(true);
                });
                if (bad.load()) {
                    err = "reading layer " + std::to_string(l0.il) + "'s experts from the model's files failed";
                    return false;
                }
            }
            for (int i = 0; i < bt.n; ++i) {
                if (!picked(i)) { ++S.skipped; continue; }
                if (skip_unpicked) ++S.copied;
                uint8_t* dst = c.ring + ((size_t) half * (c.ring_n / P) + i) * c.ring_stride;
                if (!copy_streamed(l0, mi, l0.host_list[(size_t) (bt.j0 + i)], sb != nullptr ? sb + (size_t) i * c.stage_stride
                                                                                             : nullptr,
                                   dst, c.cs, err))
                    return false;
                c.stream_bytes += (double) unit(member(l0, mi));
            }
            CK(cudaEventRecord(c.filled[half], c.cs));
            ++S.cp;
            S.done.store(S.cp, std::memory_order_relaxed);
        }
        return true;
    }

    // ---- the flow (see Chunk)
    // Windows (WDDM: HIP's runtime and CUDA's driver alike) submits queued work only when the host waits on the GPU:
    // the flow's copies and the compute it queued between its waits are submitted at once (win_submit); elsewhere
    // nothing.  (CUDA too since #303: two RTX 3080s hung before the first layer, one GPU spinning on the other's flow)
    static void kick(cudaStream_t s) { win_submit(s); }
    size_t flow_region(int r) const {   // a part's room in a staging slot (read from its offset rounded down)
        return ((flow_part[r] + os::kDirectAlign - 1) & ~(size_t) (os::kDirectAlign - 1)) + os::kDirectAlign;
    }
    size_t flow_stride() const { return flow_region(0) + flow_region(1) + flow_region(2); }
    static Chunk::Item& fit(Chunk& c, size_t i) { return c.items[i - c.base]; }
    // what member m of l's group reads of matrix r of an expert: gate / up its rows [ff0, ff0 + ffn) - one run, from
    // this offset in the matrix, this long; the down the whole matrix (its part, the blocks of those columns in every
    // row, is DMA'd out of it row by row - flow_copy); alone (nm 1) every matrix whole.  (An even split's members:
    // ff0 = m n_ff / nm, ffn = n_ff / nm, as before; DS4_TP_GGUF_UNEVEN's: their own whole blocks)
    size_t mx_read_off(const Layer& l, int m, int r) const {
        return r < 2 && l.nm > 1 ? (size_t) member(l, m).ff0 * gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim) : 0;
    }
    size_t mx_read_len(const Layer& l, int m, int r) const {
        return r < 2 && l.nm > 1 ? (size_t) member(l, m).ffn * gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim)
                                 : mx_part_bytes(l, r);
    }
    // (DS4_FLOW_HELPER_CHECK) item it's parts as copied out of the helper's pool against the same ranges read from the
    // model's files: false (err set) on any difference.  (Any thread: the device's own)
    bool flow_helper_same(const Layer& l, const Chunk::Item& it, std::string& err) {
        std::vector<uint8_t> f;
        for (int r = 0; r < 3; ++r) {
            const uint64_t off = l.mx_off[r] + (uint64_t) it.e * l.mx_stride[r] + mx_read_off(l, it.mi, r);
            const size_t n = mx_read_len(l, it.mi, r);
            f.resize(n);
            if (!pk.read_at(l.mx_file[r], off, n, f.data())) {
                err = "DS4_FLOW_HELPER_CHECK: reading layer " + std::to_string(l.il) + " expert " +
                      std::to_string(it.e) + " from the files failed";
                return false;
            }
            if (r == 0 && flow_helper_fail == "check" && flow_fail_armed.exchange(false)) f[0] ^= 1;   // (the test's)
            size_t nc = n;
            if (r == 2 && it.dpart) {   // (DS4_FLOW_DOWN_PART: staging holds the member's columns, compacted)
                size_t dr = 0, d0 = 0, dh = 0;
                down_cut(l, it.mi, dr, d0, dh);
                compact_rows(f.data(), (size_t) g.dim, dr, d0, dh);
                nc = (size_t) g.dim * dh;
            }
            if (std::memcmp(f.data(), it.src[r], nc) != 0) {
                err = "DS4_FLOW_HELPER_CHECK: layer " + std::to_string(l.il) + " expert " + std::to_string(it.e) +
                      " member " + std::to_string(it.mi) + " matrix " + std::to_string(r) +
                      ": the helper's pool differs from the model's files";
                return false;
            }
        }
        return true;
    }
    // DS4_FLOW_DOWN_SHARE=1 (unset: as before): a tensor-parallel group's members each read the whole down of every
    // expert the flow streams from the files (mx_read_off: r 2 is never cut) - unbuffered, so both from the disk, ~30 %
    // of the bytes (2x RX 7900 XTX, a prof load: the files' 35 GB at 32K, 168 GB at 130K for the pair, ~3 GB/s).  On:
    // that read goes through the page cache (the second member's finds it there, or waits on the first's pages) and the
    // range leaves the cache once every member counted it (down_reads, IoQueue::Job::share).  The bytes are the same
    static bool down_share() {
        static const bool on = [] {
            const char* e = ds4_env("DS4_FLOW_DOWN_SHARE");
            return e != nullptr && std::atoi(e) != 0;
        }();
        return on;
    }
    std::unique_ptr<std::atomic<uint8_t>[]> down_reads;   // (DS4_FLOW_DOWN_SHARE) [layer][expert]: members' reads
    size_t down_stride = 0;
    // DS4_FLOW_DOWN_PART=1 (unset: as before): an uneven split's member (DS4_TP_GGUF_UNEVEN with DS4_FLOW_TP) DMAs the
    // whole down of each streamed expert into its scratch and gathers its columns there (flow_copy) - a third of the
    // expert over the link that the member never uses.  On: the read or the helper's copy into staging is compacted to
    // the member's blocks of each row where it landed (IoQueue's compact_rows, on the reader's thread), and that part
    // alone is DMA'd, in one run - the slot's bytes the same (tp_flow_member checks it at load), ~25 % less over the
    // link a streamed expert.  A RAM-tier expert DMA'd from where it lies, or a copy's NH parts: as before
    static bool down_part_env() {
        static const bool on = [] {
            const char* e = ds4_env("DS4_FLOW_DOWN_PART");
            return e != nullptr && std::atoi(e) != 0;
        }();
        return on;
    }
    bool down_part = false;   // (DS4_FLOW_DOWN_PART on and the members on the flow: set where the flow is set up)
    // member mi of split layer l's down: a whole row's bytes, the member's blocks' offset in it and their bytes
    void down_cut(const Layer& l, int mi, size_t& dr, size_t& d0, size_t& dh) const {
        const Layer& x = member(l, mi);
        const int t2 = gg::expert_type(l.lay, 2);
        dr = gg::type_row_bytes(t2, g.ff);
        d0 = gg::type_row_bytes(t2, x.ff0);
        dh = gg::type_row_bytes(t2, x.ffn);
    }
    // (DS4_FLOW_TP with DS4_TP_GGUF_UNEVEN) the down scratch device di's flow copies a member's part through: the whole
    // down of its largest split layer.  0 - no scratch - for one GPU's layers, a load without the flow for its groups,
    // or an even split's members (DS4_FLOW_TP without the knob), whose down part keeps its 2D copy (flow_copy)
    size_t flow_down_bytes(int di) const {
        const bool flow_tp = std::getenv("DS4_FLOW_TP") != nullptr && std::atoi(std::getenv("DS4_FLOW_TP")) != 0;
        size_t b = 0;
        if (tp_uneven && flow_tp && file_experts)
            for (const Layer& l : L)
                if (!l.mtp && l.nm > 1 && l.lay.fmt == gg::kFmtMXFP4)
                    for (int m = 0; m < l.nm; ++m)
                        if (member(l, m).dev == di) b = std::max(b, mx_part_bytes(l, 2));
        return b;
    }
    // an item's staged matrices into ring slot dst as member mi's part of the expert (laid out as its hlay): gate / up
    // mx_read_len bytes - from src as the read left them (its rows only), or from whole staging (a copy's NH parts:
    // every row) at the member's read offset in it; the down whole in one copy into `down` (the device's scratch), then
    // its blocks of the member's columns [ff0, ff0 + ffn) of every row gathered into the slot on the same stream - a 2D
    // copy of the rows instead costs ~35 ms an expert against ~0.7 (192300Z: per-row transfers).  No scratch (an even
    // split's members: flow_down_bytes): the member's rows of the down as a 2D copy, as before - but an uneven split's
    // member without one (a scratch flow_down_bytes did not give it) fails, nothing enqueued.  Alone (nm 1): each
    // matrix whole, as staged.  dpart (DS4_FLOW_DOWN_PART): staging holds the member's columns of the down already,
    // compacted - one run into the slot, no scratch
    bool flow_copy(const Layer& l, int mi, const uint8_t* const* src, bool whole, uint8_t* dst, uint8_t* down,
                   cudaStream_t s, bool dpart = false) const {
        if (l.nm > 1 && tp_uneven && down == nullptr && !dpart) return false;
        const Layer& x = member(l, mi);
        const x3::ExpertLayout& lay = l.nm > 1 ? x.hlay : l.lay;
        for (int p = 0; p < 2; ++p)
            if (cudaMemcpyAsync(dst + lay.trellis[p], src[p] + (whole ? mx_read_off(l, mi, p) : 0), mx_read_len(l, mi, p),
                                cudaMemcpyHostToDevice, s) != cudaSuccess)
                return false;
        if (l.nm > 1) {   // (the down's part: in each of its rows the member's blocks)
            const int t2 = gg::expert_type(l.lay, 2);
            const size_t dr = gg::type_row_bytes(t2, g.ff), dh = gg::type_row_bytes(t2, x.ffn),
                         d0 = gg::type_row_bytes(t2, x.ff0);
            if (dpart)   // (DS4_FLOW_DOWN_PART: staging holds the member's columns already, compacted: one run)
                return cudaMemcpyAsync(dst + lay.trellis[2], src[2], (size_t) g.dim * dh, cudaMemcpyHostToDevice, s) ==
                       cudaSuccess;
            if (down == nullptr)
                return cudaMemcpy2DAsync(dst + lay.trellis[2], dh, src[2] + d0, dr, dh, (size_t) g.dim,
                                         cudaMemcpyHostToDevice, s) == cudaSuccess;
            if (cudaMemcpyAsync(down, src[2], (size_t) g.dim * dr, cudaMemcpyHostToDevice, s) != cudaSuccess) return false;
            gather_cols(down, dr, d0, dh, g.dim, dst + lay.trellis[2], s);
            return cudaGetLastError() == cudaSuccess;
        }
        return cudaMemcpyAsync(dst + lay.trellis[2], src[2], mx_part_bytes(l, 2), cudaMemcpyHostToDevice, s) == cudaSuccess;
    }
    // the device's member index in L0's group (0 alone)
    int flow_mi(const Chunk& c, const Layer& L0) const {
        for (int m = 0; m < L0.nm; ++m)
            if (member(L0, m).dev == c.dev) return m;
        return 0;
    }
    void flow_push(Chunk& c, const Layer& l, int mi, int k, int e, int v) {
        c.items.emplace_back();
        Chunk::Item& it = c.items.back();
        it.il = l.il;
        it.mi = mi;
        it.k = k;
        it.e = e;
        it.v = v;
        const bool in_ram = !l.ram.empty() && l.ram[(size_t) e] >= 0;
        if (in_ram && ram_pinned) {   // (DMA'd from where it lies)
            const uint8_t* p = ram_slots[(size_t) l.ram[(size_t) e]];
            for (int r = 0; r < 3; ++r) it.src[r] = p + l.lay.trellis[r] + mx_read_off(l, mi, r);
            ++c.it_ram;
            return;
        }
        if (in_ram)   // (copied into staging by io, then DMA'd; copy_mode: from its NH parts, flow_pump)
            it.ram = copy_mode ? ram_part[(size_t) l.ram[(size_t) e]][0] : ram_slots[(size_t) l.ram[(size_t) e]];
        it.dpart = down_part && l.nm > 1 && !(in_ram && copy_mode);   // (DS4_FLOW_DOWN_PART: through staging)
        // (DS4_FLOW_HELPER) one in the helper's pool: copied into staging out of it by io, then DMA'd as a read's -
        // not one of its recent slots (DS4_HELPER_RECENT), which their fills rewrite
        const bool from_helper = !in_ram && flow_helper && helper_owned(l, e) &&
                                 !helper_dead.load(std::memory_order_relaxed) &&
                                 (l.hr_n == 0 || (size_t) e >= l.hr_slot.size() || l.hr_slot[(size_t) e] < 0);
        if (from_helper) it.hsrc = l.helper[(size_t) e];
        bool hit = false;
        // layer-major: from the layer cache, or kept for the chunks after
        if (!in_ram && !from_helper && c.lc != nullptr && l.nm == 1) {
            const size_t i = c.base + c.items.size() - 1, stride = (l.blob + 63) & ~(size_t) 63;
            if (c.lc_il != l.il) {   // (a layer's first item: the slots the layer before used are its own again
                c.lc_il = l.il;      // once that layer's items are all read - `after` below)
                c.lc_used = 0;
                c.lc_n = (int) std::min<size_t>(c.lc_of.size(), c.lc_bytes / stride);
                c.lc_first = i;
                std::fill(c.lc_of.begin(), c.lc_of.end(), -1);
            }
            const int j = c.lc_of[(size_t) e];
            if (j >= 0) {   // (copied into staging by io once its reader is done, then DMA'd)
                it.ram = c.lc + (size_t) j * stride;
                it.after = c.lc_writer[(size_t) j];
                hit = true;
            } else if (k + 1 < (int) c.fl_T.size() && c.lc_used < c.lc_n) {   // (a later chunk may pick it)
                const int jn = c.lc_used++;
                c.lc_of[(size_t) e] = jn;
                c.lc_writer[(size_t) jn] = (int64_t) i;
                it.keep = c.lc + (size_t) jn * stride;
                it.after = (int64_t) c.lc_first - 1;
            }
        }
        it.stage = (int) (c.n_file++ % (uint64_t) c.S);
        uint8_t* sb = c.stage + (size_t) it.stage * c.stage_stride;
        for (int r = 0; r < 3; ++r) {
            const uint64_t off = l.mx_off[r] + (uint64_t) e * l.mx_stride[r] + mx_read_off(l, mi, r);
            it.src[r] = sb + (in_ram || hit || from_helper ? 0 : off % os::kDirectAlign);
            sb += flow_region(r);
        }
        it.left.store(in_ram && copy_mode ? 3 * NH : 3, std::memory_order_relaxed);
        ++(in_ram ? c.it_ram : hit ? c.it_lc : from_helper ? c.it_helper : c.it_file);
    }
    // the likely experts of (chunk k, layer il) for T tokens, first in its stream: the CPU lane's experts whose chance
    // to be picked at least once, 1 - (1 - share)^(picks), is at least DS4_SPEC_Q (0.9: the reads are what takes the
    // time, an unpicked one costs a whole read, and the routing is known a few ms after the layer before is done -
    // early reads pay where a chunk's long attention keeps the disk otherwise idle, and there nearly every expert is
    // that likely), likeliest first, at most what the staging and the ring hold (no more can be read before the layer
    // routes); the layer's virtual slots put them first, then its other CPU-lane experts in index order (the order the
    // rest of its picks are streamed in)
    // (a tensor-parallel group's members each decide their own stream and virtual slots - the same, from the same
    // profile and the same routing - and each reads only its part of every expert)
    void flow_spec(Chunk& c, int k, int il, int T) {
        static const double spec_q = std::getenv("DS4_SPEC_Q") ? std::atof(std::getenv("DS4_SPEC_Q")) : 0.9;
        Layer& l = L[(size_t) il];
        const int mi = flow_mi(c, l);
        int* vs = member(l, mi).vs_pin;
        c.spec_k = k;
        c.spec_il = il;
        c.spec_begin = c.base + c.items.size();
        // (the likely ones lead the layer's virtual slots, and the experts' outputs are summed in that order: with
        //  --no-expert-cache from the profile as loaded, not the hits this process added since)
        const uint32_t* pr = (o.expert_cache ? prof : prof_load).data() + (size_t) il * g.n_exp;
        double sum = 0;
        for (int e = 0; e < l.n_exp; ++e) sum += pr[e];
        std::vector<std::pair<double, int>> cand;
        const double picks = (double) l.k_exp * T;
        // (early reads only while they hit: once a run's likely ones went unpicked more often than DS4_SPEC_WASTE
        // (0.2) of the time, the rest of the run reads only what the routing picked - an unpicked one costs a whole
        // read, and how well the profile guesses depends on the PC's history and the prompt: V100, 64 tokens - 376
        // of 921 likely ones unpicked, 7 GB of 84 read for nothing; Radeon 8065S, 128 and 512 tokens - 44 of 945 and
        // 21 of 1568, the early reads 9-12% faster there)
        static const double waste = std::getenv("DS4_SPEC_WASTE") ? std::atof(std::getenv("DS4_SPEC_WASTE")) : 0.2;
        const bool early = c.it_spec < 2u * (uint64_t) c.ring_n || (double) c.it_spec_unused <= waste * (double) c.it_spec;
        for (int e : l.host_list) {
            if (!early) break;
            const double p = sum > 0 ? pr[e] / sum : 0.0;
            const double q = p >= 1.0 ? 1.0 : 1.0 - std::exp(picks * std::log1p(-p));
            if (q >= spec_q && spec_q <= 1.0) cand.push_back({q, e});
        }
        std::stable_sort(cand.begin(), cand.end(), [](const std::pair<double, int>& a, const std::pair<double, int>& b) {
            return a.first > b.first;
        });
        if (cand.size() > (size_t) (c.S + c.ring_n)) cand.resize((size_t) (c.S + c.ring_n));
        std::vector<char> is((size_t) l.n_exp, 0);
        int j = 0;
        for (const auto& x : cand) {
            vs[x.second] = l.pv_n + j++;
            is[(size_t) x.second] = 1;
        }
        for (int e : l.host_list)
            if (!is[(size_t) e]) vs[e] = l.pv_n + j++;
        for (const auto& x : cand) flow_push(c, l, mi, k, x.second, vs[x.second]);
        c.n_spec = (int) cand.size();
        c.it_spec += cand.size();
    }
    // (chunk k, layer il) routed (bounds b by virtual slot): the rest of its picks after its likely ones
    void flow_rest(Chunk& c, int k, int il, const std::vector<int>& b) {
        const Layer& l = L[(size_t) il];
        const int mi = flow_mi(c, l);
        const int* vs = member(l, mi).vs_pin;
        for (size_t i = c.spec_begin; i < c.spec_begin + (size_t) c.n_spec; ++i) {
            const int v = fit(c, i).v;
            if (b[(size_t) v + 1] == b[(size_t) v]) ++c.it_spec_unused;
        }
        for (int e : l.host_list) {   // (index order: their virtual slots ascending)
            const int v = vs[e];
            if (v >= l.pv_n + c.n_spec && b[(size_t) v + 1] > b[(size_t) v]) flow_push(c, l, mi, k, e, v);
        }
    }
    // the next (chunk, layer) of the device after (k, il) in the run's order that streams experts (false: none) - a
    // long prompt's skip leaves out its early chunks' layers from Run::yoco on (kv_only there: no experts)
    bool flow_next(const Chunk& c, int k, int il, int& k2, int& il2) const {
        while (flow_next1(c, k, il, k2, il2)) {
            if (c.fl_yoco < 0 || k2 >= c.fl_cut_k || il2 < c.fl_yoco) return true;
            k = k2;
            il = il2;
        }
        return false;
    }
    // the rows chunk k runs layer il on (a long prompt's skip: the cut chunk's from cut_r on, from the yoco layer on)
    static int fl_rows(const Chunk& c, int k, int il) {
        const int T = c.fl_T[(size_t) k];
        return c.fl_yoco >= 0 && k == c.fl_cut_k && il >= c.fl_yoco ? T - c.fl_cut_r : T;
    }
    bool flow_next1(const Chunk& c, int k, int il, int& k2, int& il2) const {
        const auto it = std::find(c.fl_layers.begin(), c.fl_layers.end(), il);
        const size_t i = (size_t) (it - c.fl_layers.begin());
        if (c.lm) {   // (layer-major: the layer's next chunk, then the next layer's first)
            if (k + 1 < (int) c.fl_T.size()) {
                k2 = k + 1;
                il2 = il;
                return true;
            }
            if (i + 1 >= c.fl_layers.size()) return false;
            k2 = 0;
            il2 = c.fl_layers[i + 1];
            return true;
        }
        if (i + 1 < c.fl_layers.size()) {
            k2 = k;
            il2 = c.fl_layers[i + 1];
            return true;
        }
        if (k + 1 < (int) c.fl_T.size() && !c.fl_layers.empty()) {
            k2 = k + 1;
            il2 = c.fl_layers[0];
            return true;
        }
        return false;
    }
    // the reads (in order, each into its staging slot once that slot's last DMA is done) and the DMAs (in order, each
    // into its ring slot once that slot's last use is queued: the copy stream waits for it) as far as they can go now
    bool flow_pump(Chunk& c, std::string& err) {
        const size_t end = c.base + c.items.size();
        IoQueue::Job jobs[3 * kMaxNH];   // (3 matrices, each from up to kMaxNH copy parts)
        while (c.n_read < end) {
            Chunk::Item& it = fit(c, c.n_read);
            if (it.after >= 0) {   // layer-major: a slot's expert copied out of it once its reader is done; a slot
                // written again once the layer before's items are all read (none still copies out of it)
                bool wait = false;
                if (it.keep == nullptr)
                    wait = (size_t) it.after >= c.base && fit(c, (size_t) it.after).left.load(std::memory_order_acquire) != 0;
                else {
                    while (c.lc_chk < c.n_read &&
                           (c.lc_chk < c.base || fit(c, c.lc_chk).left.load(std::memory_order_acquire) == 0))
                        ++c.lc_chk;
                    wait = c.lc_chk <= (size_t) it.after;
                }
                if (wait) break;
            }
            if (it.stage >= 0) {
                const int64_t prev = c.stage_item[(size_t) it.stage];
                if (prev >= 0) {
                    if ((size_t) prev >= c.n_dma) break;
                    const cudaError_t q = cudaEventQuery(c.stage_ev[(size_t) it.stage]);
                    if (q == cudaErrorNotReady) break;
                    CK(q);
                }
                c.stage_item[(size_t) it.stage] = (int64_t) c.n_read;
                const Layer& l = L[(size_t) it.il];
                uint8_t* sb = c.stage + (size_t) it.stage * c.stage_stride;
                const int cs = copy_mode && it.ram != nullptr ? l.ram[(size_t) it.e] : -1;   // (a copy's slot)
                int nj = 0;
                for (int r = 0; r < 3; ++r) {
                    if (cs >= 0) {   // a copy: the rows the member reads (as from the file: mx_read_off / _len - a
                        // group's member its gate / up rows [ff0, ff0 + ffn), the down whole), from the NH parts that
                        // hold them, side by side into staging
                        const size_t rb = mx_row_b(l, r);
                        const int per = mx_n(r) / NH;
                        const int lo0 = (int) (mx_read_off(l, it.mi, r) / rb);
                        const int hi0 = lo0 + (int) (mx_read_len(l, it.mi, r) / rb);
                        for (int X = 0; X < NH; ++X) {
                            const int lo = std::max(X * per, lo0), hi = std::min((X + 1) * per, hi0);
                            if (lo >= hi) continue;
                            IoQueue::Job& j = jobs[nj++];
                            j = IoQueue::Job{};
                            j.len = (size_t) (hi - lo) * rb;
                            j.dst = sb + (size_t) (lo - lo0) * rb;
                            j.left = &it.left;
                            j.bad = &it.bad;
                            j.mem = ram_part[(size_t) cs][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r] +
                                    (size_t) (lo - X * per) * rb;
                        }
                        sb += flow_region(r);
                        continue;
                    }
                    if (it.hsrc != nullptr) {   // (DS4_FLOW_HELPER) the member's part of matrix r out of the pool
                        IoQueue::Job& j = jobs[nj++];
                        j = IoQueue::Job{};
                        j.len = mx_read_len(l, it.mi, r);
                        j.dst = sb;
                        j.left = &it.left;
                        j.bad = &it.bad;
                        j.dmem = it.hsrc + l.lay.trellis[r] + mx_read_off(l, it.mi, r);
                        j.ddev = helper_id;
                        if (r == 2 && it.dpart) {   // (DS4_FLOW_DOWN_PART: the member's columns, where copied)
                            down_cut(l, it.mi, j.cpitch, j.coff, j.clen);
                            j.crows = (size_t) g.dim;
                        }
                        j.dcopy = flow_helper_fail == "copy" && flow_fail_armed.exchange(false)
                                      ? &Model::Impl::helper_copy_fail
                                      : &Model::Impl::helper_copy;
                        sb += flow_region(r);
                        continue;
                    }
                    IoQueue::Job& j = jobs[nj++];
                    j = IoQueue::Job{};   // (a job before it in jobs may have been one of the pool's copies)
                    const os::fd_t pf = pk.pfds.empty() ? os::kBadFd : pk.pfds[(size_t) l.mx_file[r]];
                    j.fd = pf != os::kBadFd ? pf : pk.fds[(size_t) l.mx_file[r]];
                    j.dfd = pk.dfds.empty() || c.buffered ? os::kBadFd : pk.dfds[(size_t) l.mx_file[r]];
                    j.off = l.mx_off[r] + (uint64_t) it.e * l.mx_stride[r] + mx_read_off(l, it.mi, r);
                    j.len = mx_read_len(l, it.mi, r);
                    j.dst = sb;
                    j.left = &it.left;
                    j.bad = &it.bad;
                    j.mem = it.ram != nullptr ? it.ram + l.lay.trellis[r] + mx_read_off(l, it.mi, r) : nullptr;
                    if (r == 2 && l.nm > 1 && down_reads != nullptr && it.ram == nullptr && it.keep == nullptr &&
                        (size_t) it.e < down_stride) {   // (DS4_FLOW_DOWN_SHARE: the members' one read of the down)
                        j.dfd = os::kBadFd;
                        j.share = &down_reads[(size_t) it.il * down_stride + (size_t) it.e];
                        j.share_n = l.nm;
                    }
                    j.map = pk.at(l.mx_file[r], j.off);
                    j.keep = it.keep != nullptr ? it.keep + l.lay.trellis[r] : nullptr;
                    if (r == 2 && it.dpart) {   // (DS4_FLOW_DOWN_PART: the member's columns, where the read left them)
                        down_cut(l, it.mi, j.cpitch, j.coff, j.clen);
                        j.crows = (size_t) g.dim;
                    }
                    sb += flow_region(r);
                }
                if (cs >= 0) it.left.store(nj, std::memory_order_relaxed);   // (a member's rows: maybe fewer parts)
                c.io->push(jobs, nj);
            }
            ++c.n_read;
        }
        const size_t R = (size_t) c.ring_n, dma0 = c.n_dma;
        struct Kick {   // (every way out: what was queued is submitted)
            cudaStream_t s;
            const size_t &a, b;
            ~Kick() {
                if (a != b) kick(s);
            }
        } kq{c.cs, c.n_dma, dma0};
        while (c.n_dma < c.n_read && c.n_dma < c.n_comp + R) {
            Chunk::Item& it = fit(c, c.n_dma);
            if (it.left.load(std::memory_order_acquire) != 0) break;
            if (it.bad.load(std::memory_order_acquire)) {
                err = "reading layer " + std::to_string(it.il) + " expert " + std::to_string(it.e) +
                      " from the model's files failed";
                return false;
            }
            const size_t r = c.n_dma % R;
            if (c.n_dma >= R) CK(cudaStreamWaitEvent(c.cs, c.ring_free[r], 0));
            const Layer& l = L[(size_t) it.il];
            if (it.hsrc != nullptr && flow_check_now) {   // (DS4_FLOW_HELPER_CHECK: this run compares every one)
                if (!flow_helper_same(l, it, err)) return false;
                ++c.chk_n;
            }
            // (staging holds the member's gate / up rows only - a read's and, since #377, a copy's)
            if (!flow_copy(l, it.mi, it.src, false, c.ring + r * c.ring_stride, c.down, c.cs, it.dpart)) {
                const cudaError_t e = cudaGetLastError();   // (none: the uneven split's member without its down scratch)
                err = "the flow's copy of layer " + std::to_string(it.il) + " expert " + std::to_string(it.e) + ": " +
                      (e != cudaSuccess ? cudaGetErrorString(e) : "no down scratch for the uneven split's member");
                return false;
            }
            CK(cudaEventRecord(c.ring_fill[r], c.cs));
            if (it.stage >= 0) CK(cudaEventRecord(c.stage_ev[(size_t) it.stage], c.cs));
            c.stream_bytes += (double) unit(member(l, it.mi));
            ++c.n_dma;
        }
        return true;
    }
    // layer L0 of chunk k routed (bounds b, the device's copy d_bounds): its streamed experts as they land, the VRAM
    // ones in shares between them (the device works while the reads run)
    bool flow_layer(Dev& d, Chunk& c, Layer& L0, int mi, int k, int T, const std::vector<int>& b, std::string& err) {
        cudaStream_t s = d.st;
        const Layer& vx = member(L0, mi);   // (a member's: its part of each VRAM expert, L0's slots)
        if (c.spec_k != k || c.spec_il != L0.il) {
            err = "the prompt path's expert stream is out of step (layer " + std::to_string(L0.il) + ")";
            return false;
        }
        flow_rest(c, k, L0.il, b);
        const size_t lb = c.spec_begin, le = c.base + c.items.size(), n_lay = le - lb;
        int k2 = 0, il2 = 0;
        if (flow_next(c, k, L0.il, k2, il2)) flow_spec(c, k2, il2, fl_rows(c, k2, il2));
        const size_t R = (size_t) c.ring_n, bmax = std::max<size_t>(1, R / 2);
        int v_done = 0;
        while (c.n_comp < le) {
            // a batch's bounds are fixed by the stream alone (bmax items, never across the ring's end), never by what
            // has landed: the experts' outputs are summed batch after batch (the VRAM ones' shares between them), so
            // the sums come out the same on every run whatever the reads' timing
            const size_t i0 = c.n_comp, i1 = std::min({le, i0 + bmax, (i0 / R + 1) * R});
            if (!flow_pump(c, err)) return false;
            if (c.n_dma < i1) {   // not all of the batch landed: wait for a read, or for a staging slot's copy
                const double tw = now_ms();
                kick(s);
                if (c.n_read > c.n_dma) c.io->wait_any(500);
                else {
                    const Chunk::Item& it = fit(c, c.n_read);
                    if (it.stage >= 0) CK(cudaEventSynchronize(c.stage_ev[(size_t) it.stage]));
                }
                c.wait_ms += now_ms() - tw;
                continue;
            }
            const int n = (int) (i1 - i0);
            int* bc = c.bc_pin + (size_t) (c.n_batch % (uint64_t) c.bc_n) * c.bc_w;
            int* bcd = c.bc_dev + (size_t) (c.n_batch % (uint64_t) c.bc_n) * c.bc_w;
            ++c.n_batch;
            // (the items' virtual slots ascend and the slots between them have no rows: their bounds side by side)
            for (int m = 0; m < n; ++m) bc[m] = b[(size_t) fit(c, i0 + (size_t) m).v];
            bc[n] = b[(size_t) fit(c, i1 - 1).v + 1];
            if (bc[n] > bc[0]) {
                CK(cudaStreamWaitEvent(s, c.ring_fill[(i1 - 1) % R], 0));
                CK(cudaMemcpyAsync(bcd, bc, (size_t) (n + 1) * 4, cudaMemcpyHostToDevice, s));
                if (!run_set(d, c, vx, c.ring + (i0 % R) * c.ring_stride, 0, c.ring_stride, bcd, bc, 0, n, T, err))
                    return false;
            }
            for (size_t i = i0; i < i1; ++i) CK(cudaEventRecord(c.ring_free[i % R], s));
            kick(s);
            c.n_comp = i1;
            if (!flow_pump(c, err)) return false;
            const int v_to = (int) ((int64_t) L0.pv_n * (int64_t) (c.n_comp - lb) / (int64_t) std::max<size_t>(1, n_lay));
            if (!run_vram(d, c, L0, vx, vx, b.data(), v_done, v_to, T, err)) return false;
            v_done = v_to;
        }
        if (!run_vram(d, c, L0, vx, vx, b.data(), v_done, L0.pv_n, T, err)) return false;
        while (c.base < c.n_comp && c.items.size() > 4096) {   // (done with: read, copied and used)
            c.items.pop_front();
            ++c.base;
        }
        return true;
    }

    // a run's VRAM experts [i0, i1) of layer L0 (its own slots, then the tail's it kept: their blobs at member x's
    // vram_base and xbase), through run_set with layer l's layout
    bool run_vram(Dev& d, Chunk& c, const Layer& L0, const Layer& l, const Layer& x, const int* b, int i0, int i1, int T,
                  std::string& err) {
        const int m = std::min(i1, L0.n_main), t0 = std::max(i0, L0.n_main);
        if (i0 < m && !run_set(d, c, l, x.vram_base, 0, unit(x), c.bounds, b, i0, m, T, err)) return false;
        return t0 >= i1 || run_set(d, c, l, x.xbase, L0.n_main, x.xstep, c.bounds, b, t0, i1, T, err);
    }
    // the experts [i0, i1) of a sorted set (blobs at wbase + i * stride; bounds b on the host, d_bounds on the device)
    // over the chunk's rows, in pieces of at most C rows, each added into acc in pick order
    bool run_set(Dev& d, Chunk& c, const Layer& l, const uint8_t* wbase, int wb0, size_t stride, const int* d_bounds,
                 const int* b, int i0, int i1, int T, std::string& err) {
        const int D = g.dim, FF = l.ffn;
        while (i0 < i1) {
            int j = i0 + 1;
            while (j < i1 && b[j + 1] - b[i0] <= c.C) ++j;
            const int a = b[i0], nrows = b[j] - a;
            int max_rows = 0;
            for (int i = i0; i < j; ++i) max_rows = std::max(max_rows, b[i + 1] - b[i]);
            if (nrows > 0) {
                x3::SetArgs sa;
#if defined(STRATA_USE_HIP)
                gg::iq::MmqRowsScope mmq_rows(nrows, b + i0);
#endif
                sa.wbase = wbase + (size_t) (i0 - wb0) * stride;   // (wbase: set member wb0's blob)
                sa.stride = stride;
                sa.lay = l.nm > 1 ? l.hlay : l.lay;
                if (l.n_cls > 1 && wbase == l.vram_base) {   // (a mixed layer: its experts' own addresses, slot = expert)
                    sa.mix = l.mix;
                    sa.eptr = l.d_maddr + i0;
                }
                sa.n_exp = j - i0;
                sa.bounds = d_bounds + i0;
                sa.row0 = a;
                sa.max_rows = max_rows;
                sa.n_embd = D;
                sa.n_ff = FF;
                sa.limit = g.lim;
                // the busy experts (DS4_FAT_ROWS=N: those of N rows or more): their weights decoded to FP16 once and
                // multiplied by the library's GEMM - the tiles decode an expert's weights again for every 64 of its rows
                // - VRAM's experts only: one streamed into the ring is used for this chunk alone, and on a card short of
                // VRAM (most experts streamed) the path cost prompts 5-7% (a V100 held to 20 GB, Maya-XS; #438)
                std::vector<int> fat;
                const bool ringed = wbase >= c.ring && wbase < c.ring + (size_t) c.ring_n * c.ring_stride;
                // (low-bit experts only, both roles: the MXFP4 tiles take every row of a set)
                if (sa.lay.fmt == gg::kFmtMXFP4 && gg::expert_type(sa.lay, 0) != gg::kTypeMXFP4 &&
                    gg::expert_type(sa.lay, 2) != gg::kTypeMXFP4 && sa.mix.n == 0 && !ringed && fat_ready(d, c, D, FF)) {
                    int rest = 0;
                    for (int i = i0; i < j; ++i) {
                        const int r = b[i + 1] - b[i];
                        if (r >= fat_rows()) fat.push_back(i);
                        else rest = std::max(rest, r);
                    }
                    if (!fat.empty()) {
                        sa.skip_ge = fat_rows();
                        sa.max_rows = rest;
                    }
                }
                if (sa.lay.fmt == gg::kFmtMXFP4) {
                    if (sa.max_rows > 0)
                        gg::set_gate_up(sa, c.x, D, c.row_tok + a, c.h16, FF, d.st, c.x16);   // (c.x16: rows_f16 of c.x)
                    for (const int i : fat)
                        if (!fat_gate_up(c, sa, sa.wbase + (size_t) (i - i0) * stride, b[i], b[i + 1] - b[i], a, D, FF,
                                         d.st, err))
                            return false;
                    if (sa.max_rows > 0) gg::set_down(sa, c.h16, FF, c.y, D, d.st);
                    for (const int i : fat)
                        if (!fat_down(c, sa, sa.wbase + (size_t) (i - i0) * stride, b[i] - a, b[i + 1] - b[i], D, FF,
                                      d.st, err))
                            return false;
                } else {
                    x3::set_gate_up(sa, c.x, D, c.row_tok + a, c.h16, FF, d.st);
                    x3::set_down(sa, c.h16, FF, c.y, D, d.st);
                }
                if (dump_y != nullptr && (dump_y_layer < 0 || l.il == dump_y_layer)) {
                    std::vector<int> bb(b + i0, b + j + 1);
                    std::vector<uint16_t> hv((size_t) nrows * FF);
                    std::vector<float> yv((size_t) nrows * D);
                    CK(cudaStreamSynchronize(d.st));
                    CK(cudaMemcpy(hv.data(), c.h16, hv.size() * 2, cudaMemcpyDeviceToHost));
                    CK(cudaMemcpy(yv.data(), c.y, yv.size() * 4, cudaMemcpyDeviceToHost));
                    std::lock_guard<std::mutex> lk(dump_mu);
                    const int64_t hdr[6] = {l.il, a, nrows, j - i0, wbase == c.ring || (wbase > c.ring &&
                                            wbase < c.ring + (size_t) c.ring_n * c.ring_stride) ? 1 : 0, max_rows};
                    std::fwrite(hdr, 8, 6, dump_y);
                    std::fwrite(bb.data(), 4, bb.size(), dump_y);
                    std::fwrite(hv.data(), 2, hv.size(), dump_y);
                    std::fwrite(yv.data(), 4, yv.size(), dump_y);
                    std::fflush(dump_y);
                }
                moe_combine(c.acc, c.y, c.pos, c.rw, T, l.k_exp, a, a + nrows, D, d.st);
            }
            i0 = j;
        }
        (void) err;
        return true;
    }

    bool load_dense(int di, std::string& err) {
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        size_t* acct = &d.weights;
        for (Layer& l0 : L)
          for (int mi = 0; mi < l0.nm; ++mi) {
            Layer& l = member(l0, mi);
            if (l.dev != di) continue;
            // (a group's member: its share of the heads (wq_b columns, the sinks), of wo_a's groups and wo_b's rows,
            // of the shared expert's FFN; the rest whole)
            const int nm = l0.nm, na = g.heads / std::max(1, l.ahn), ha = l.ah0 / std::max(1, l.ahn);
            const std::string& P = l.name;
            // (DS4_TP_GGUF_UNEVEN: the shared expert split at the member's own FFN range, as the routed experts -
            //  which needs it as wide as theirs)
            const int sr0 = nm > 1 && tp_uneven && l0.lay.fmt == gg::kFmtMXFP4 ? l.ff0 : -1;
            if (sr0 >= 0) {
                const Tensor* sw = pk.get(P + "ffn.shared_experts.w1.weight");
                if (sw == nullptr || sw->shape.size() != 2 || (int) sw->shape[0] != g.ff) {
                    err = "layer " + std::to_string(l.il) + ": DS4_TP_GGUF_UNEVEN needs the shared expert as wide as "
                          "the routed ones (" + std::to_string(g.ff) + ")";
                    return false;
                }
            }
            const std::string A = P + "attn.";
            // (the member's shares in sp; what d.weights gains besides them every member holds whole: tp_w)
            const size_t w0 = d.weights;
            size_t sp = 0;
            bool ok = mat(d, A + "wq_a", l.wq_a, err, acct) &&
                      (l.ahn == 0 || mat(d, A + "wq_b", l.wq_b, err, &sp, ha, na, true)) &&
                      mat(d, A + "wkv", l.wkv, err, acct) &&
                      (l.ahn == 0 || mat(d, A + "wo_b", l.wo_b, err, &sp, ha, na, false)) &&
                      f32(d, A + "q_norm.weight", l.q_norm, err, acct, (size_t) g.q_lora) &&
                      f32(d, A + "kv_norm.weight", l.kv_norm, err, acct, (size_t) g.hd) &&
                      f32(d, A + "attn_sink", l.sink, err, acct, (size_t) g.heads) &&
                      f32(d, P + "attn_norm.weight", l.attn_norm, err, acct, (size_t) g.dim) &&
                      f32(d, P + "ffn_norm.weight", l.ffn_norm, err, acct, (size_t) g.dim) &&
                      f32(d, P + "hc_attn_fn", l.hca_fn, err, acct) && f32(d, P + "hc_attn_scale", l.hca_scale, err, acct) &&
                      f32(d, P + "hc_attn_base", l.hca_base, err, acct) && f32(d, P + "hc_ffn_fn", l.hcf_fn, err, acct) &&
                      f32(d, P + "hc_ffn_scale", l.hcf_scale, err, acct) &&
                      f32(d, P + "hc_ffn_base", l.hcf_base, err, acct) &&
                      f32(d, P + "ffn.gate.weight", l.gate_w, err, acct, (size_t) l.n_exp * g.dim) &&
                      f32(d, P + "ffn.gate.bias", l.gate_bias, err, acct, (size_t) l.n_exp) &&
                      (l.mtp || img_tok < 0 || pk.get(P + "ffn.gate.bias_vl") == nullptr ||
                       f32(d, P + "ffn.gate.bias_vl", l.gate_bias_vl, err, acct, (size_t) l.n_exp)) &&
                      mat(d, P + "ffn.shared_experts.w1", l.s1, err, &sp, mi, nm, true, l.il % nm, sr0, l.ffn) &&
                      mat(d, P + "ffn.shared_experts.w2", l.s2, err, &sp, mi, nm, false, l.il % nm, sr0, l.ffn) &&
                      mat(d, P + "ffn.shared_experts.w3", l.s3, err, &sp, mi, nm, true, l.il % nm, sr0, l.ffn);
            if (!ok) return false;
            // (decode's shared expert runs with the routed experts' FF as its rows' stride: the same width a member)
            if (nm > 1 && tp_uneven && (l.s1.n != l.ffn || l.s3.n != l.ffn || l.s2.k != l.ffn)) {
                err = "layer " + std::to_string(l.il) + ": the shared expert's part (" + std::to_string(l.s1.n) +
                      ") is not the member's FFN range (" + std::to_string(l.ffn) + ")";
                return false;
            }
            l.sink += (size_t) l.ah0;
            for (int gi = 0; gi < l.ogn; ++gi)
                if (!mat(d, A + "wo_a.slice." + std::to_string(l.og0 + gi), l.wo_a[gi], err, &sp)) return false;
            if (l.kv_src) {
                const std::string C = A + "compressor.";
                if (!mat(d, C + "wkv", l.c_wkv, err, acct) || !f32(d, C + "norm.weight", l.c_norm, err, acct)) return false;
                if (l.ratio > 1 && !mat(d, C + "wgate", l.c_wgate, err, acct)) return false;
                if (l.ratio > 1 && (!dalloc(d, l.c_kv, (size_t) l.ratio * g.hd, err) ||
                                    !dalloc(d, l.c_score, (size_t) l.ratio * g.hd, err)))
                    return false;
            }
            if (l.ix_src) {
                const std::string I = A + "indexer.";
                if (!mat(d, I + "wq_b", l.i_wq_b, err, acct) || !f16raw(d, I + "weights_proj.weight", l.i_wproj, err, acct))
                    return false;
                if (l.owns_k && (!mat(d, I + "wk", l.i_wk, err, acct) || !f32(d, I + "k_norm.weight", l.ik_norm, err, acct)))
                    return false;
            }
            if (l.eg >= 0) {
                if (!mat(d, P + "engram.wkv", l.eg_wkv, err, acct)) return false;
                if (pk.get(P + "engram.gate.weight") != nullptr) {   // a GGUF: q_weight * k_weight, folded already
                    if (!f32(d, P + "engram.gate.weight", l.eg_w, err, acct, (size_t) g.hc * g.dim)) return false;
                } else {
                    float *qw = nullptr, *kw = nullptr;
                    if (!f32(d, P + "engram.q_weight", qw, err, acct) || !f32(d, P + "engram.k_weight", kw, err, acct))
                        return false;
                    std::vector<float> a((size_t) g.hc * g.dim), b(a.size());
                    CK(cudaMemcpy(a.data(), qw, a.size() * 4, cudaMemcpyDeviceToHost));
                    CK(cudaMemcpy(b.data(), kw, b.size() * 4, cudaMemcpyDeviceToHost));
                    for (size_t i = 0; i < a.size(); ++i) a[i] *= b[i];   // only ever used as a product
                    CK(cudaMemcpy(qw, a.data(), a.size() * 4, cudaMemcpyHostToDevice));
                    l.eg_w = qw;
                }
            }
            if (!dalloc(d, l.win, (size_t) g.win * win_rb(), err, &d.caches)) return false;
            if (spec_bufs() && !l.mtp) {   // (a verify window's backups: the rows and states a rejected draft undoes)
                if (!dalloc(d, l.ring_bak, (size_t) kWin * win_rb(), err)) return false;
                if (l.kv_src && l.ratio > 1 && (!dalloc(d, l.c_snap, (size_t) 2 * l.ratio * g.hd, err) ||
                                                !dalloc(d, l.c_rows, (size_t) 2 * kWin * g.hd, err)))
                    return false;
            }
            if (!dalloc(d, l.vram_tab, (size_t) l.n_exp, err, acct)) return false;
            if (nm > 1) d.tp_w += (d.weights - w0) / (size_t) nm * (size_t) (nm - 1);
            d.weights += sp;
          }
        if (d.grp == devs[(size_t) head_dev].grp) {   // the head: each member of its group a share of the columns
            const int hn = head_nm();
            if (!mat(d, "head", d.head, err, acct, d.mi, hn, true) || !f32(d, "norm.weight", d.norm_w, err, acct, (size_t) g.dim))
                return false;
            if (g.n_mtp > 0 && !f32(d, "mtp." + std::to_string(g.n_mtp - 1) + ".norm.weight", d.d_norm, err, acct, (size_t) g.dim))
                return false;
            if (!dalloc(d, d.logits_part, (size_t) kWin * ((g.vocab / 128 + hn - 1) / hn * 128), err)) return false;
            if (g.n_mtp > 0 && hn > 1) {   // the markov steps over the group (mk_split): this member's rows of the head
                const Tensor* th = pk.get("mtp." + std::to_string(g.n_mtp - 1) + ".markov_head.head.weight");
                const int R = g.d_rank;
                head_cols(hn, d.mi, d.mk_v0, d.mk_vn);   // (its share of the head's columns: the same rows)
                // F16 as the pack holds it, or a GGUF drafter's BF16 rounded to F16 as f16raw rounds d_mk_head (the same
                // values as the lead's whole rows); another type: no mk_split (the lead's whole rows)
                if (th != nullptr && (th->dtype == "F16" || th->dtype == "BF16") && th->bytes == (uint64_t) g.vocab * R * 2) {
                    std::vector<uint16_t> rows((size_t) d.mk_vn * R);
                    if (!pk.read_at(th->file, th->off + (uint64_t) d.mk_v0 * R * 2, rows.size() * 2, rows.data())) {
                        err = "the markov head: read failed";
                        return false;
                    }
                    if (th->dtype == "BF16")
                        for (uint16_t& h : rows) h = strata::kernels::f16_from_f32(bf16_to_f32(h));
                    if (!dalloc(d, d.mk_share, rows.size(), err, acct) || !dalloc(d, d.mk_erow, (size_t) R, err) ||
                        !dalloc(d, d.mk_ints, (size_t) kWin + 2, err))
                        return false;
                    CK(cudaMemcpy(d.mk_share, rows.data(), rows.size() * 2, cudaMemcpyHostToDevice));
                }
            }
        }
        if (di == head_dev) {
            head = d.head;
            norm_w = d.norm_w;
            d_norm = d.d_norm;
            if (g.n_mtp > 0) {
                const std::string Z = "mtp." + std::to_string(g.n_mtp - 1) + ".";
                if (!f32(d, Z + "confidence_head.proj.weight", d_conf, err, acct, (size_t) (g.dim + g.d_rank)))
                    return false;
                const Tensor* te = pk.get(Z + "markov_head.embed.weight");
                const Tensor* th = pk.get(Z + "markov_head.head.weight");
                if (te == nullptr || th == nullptr || te->dtype != "BF16" || (th->dtype != "F16" && th->dtype != "BF16")) {
                    err = Z + "markov_head: not the BF16 embed and F16 / BF16 head expected";
                    return false;
                }
                if (!dalloc(d, d_mk_embed, te->bytes / 2, err, acct) || !upload(d, *te, d_mk_embed, err) ||
                    !f16raw(d, Z + "markov_head.head.weight", d_mk_head, err, acct))
                    return false;
            }
        }
        if (g.n_mtp > 0 && block_dev(di)) {   // (every device with a block seeds its own: DS4_DRAFT_DEV)
            if (!mat(d, "mtp.0.main_proj", d.d_proj, err, acct) ||
                !f32(d, "mtp.0.main_norm.weight", d.d_proj_norm, err, acct, (size_t) g.dim))
                return false;
        }
        return true;
    }

    void set_vm(Layer& l, int e, int slot) {
        uint8_t* b = sat(l, l, slot, l.blob);
        if (l.lay.fmt == gg::kFmtMXFP4) {
            for (int r = 0; r < 3; ++r) {
                x3::Mat& m = l.vm[(size_t) e][(size_t) r];
                m = x3::Mat{};
                m.gg_type = gg::expert_type(l.lay, r);   // (a low-bit type: its GEMV, ds4_iq's)
                m.fmt = m.gg_type == gg::kTypeMXFP4 ? gg::kFmtMXFP4 : gg::kFmtGG;
                m.raw = b + l.lay.trellis[r];
                m.k = r < 2 ? g.dim : g.ff;
                m.n = r < 2 ? g.ff : g.dim;
            }
            return;
        }
        const x3::ExpertLayout& lay = l.n_cls > 1 ? l.clay[l.cls[(size_t) e]] : l.lay;   // (a mixed layer: its class's)
        for (int r = 0; r < 3; ++r) {
            x3::Mat& m = l.vm[(size_t) e][(size_t) r];
            m.trellis = (const uint32_t*) (b + lay.trellis[r]);
            m.suh = (const uint16_t*) (b + lay.suh[r]);
            m.svh = (const uint16_t*) (b + lay.svh[r]);
            m.k = r < 2 ? g.dim : g.ff;
            m.n = r < 2 ? g.ff : g.dim;
            m.k2 = lay.k2[r];
            m.cb = 2;
            m.ld = 0;
        }
    }
    // an expert's VRAM blob -> its CPU-lane part X, and its NH parts -> the blob (the cache's swaps)
    void blob_to_part(const Layer& l, const uint8_t* blob, int X, uint8_t* dst) const {
        if (l.packed_host) {
            for (int m = 0; m < l.nm; ++m) blob_to_half(l, blob, m, dst + (size_t) m * l.hblob);
            return;
        }
        for (int r = 0; r < 3; ++r) {
            const size_t tile = (size_t) 16 * l.lay.k2[r];
            const int k = l.hl.k[r], nt = l.hl.n[r] * NH / 16, nth = l.hl.n[r] / 16;
            const uint8_t* tr = blob + l.lay.trellis[r];
            for (int sl = 0; sl < k / 16; ++sl)
                std::memcpy(dst + l.hl.trellis[r] + (size_t) sl * nth * tile, tr + ((size_t) sl * nt + (size_t) X * nth) * tile,
                            (size_t) nth * tile);
            std::memcpy(dst + l.hl.suh[r], blob + l.lay.suh[r], (size_t) k * 2);
            std::memcpy(dst + l.hl.svh[r], blob + l.lay.svh[r] + (size_t) X * l.hl.n[r] * 2, (size_t) l.hl.n[r] * 2);
        }
    }
    void parts_to_blob(const Layer& l, const std::array<uint8_t*, 4>& parts, uint8_t* blob) const {
        if (l.packed_host) {
            for (int m = 0; m < l.nm; ++m) half_to_blob(l, parts[0] + (size_t) m * l.hblob, m, blob);
            return;
        }
        for (int r = 0; r < 3; ++r) {
            const size_t tile = (size_t) 16 * l.lay.k2[r];
            const int k = l.hl.k[r], nt = l.hl.n[r] * NH / 16, nth = l.hl.n[r] / 16;
            uint8_t* tr = blob + l.lay.trellis[r];
            for (int X = 0; X < NH; ++X)
                for (int sl = 0; sl < k / 16; ++sl)
                    std::memcpy(tr + ((size_t) sl * nt + (size_t) X * nth) * tile,
                                parts[(size_t) X] + l.hl.trellis[r] + (size_t) sl * nth * tile, (size_t) nth * tile);
            std::memcpy(blob + l.lay.suh[r], parts[0] + l.hl.suh[r], (size_t) k * 2);
            for (int X = 0; X < NH; ++X)
                std::memcpy(blob + l.lay.svh[r] + (size_t) X * l.hl.n[r] * 2, parts[(size_t) X] + l.hl.svh[r],
                            (size_t) l.hl.n[r] * 2);
        }
    }

    // an expert's blob -> member m's part (gate / up columns [ff0, ff0 + ffn), down rows of the same), and back
    void blob_to_half(const Layer& l, const uint8_t* blob, int m, uint8_t* dst) const {
        if (l.lay.fmt == gg::kFmtMXFP4) return mx_blob_to_half(l, blob, m, dst);
        const Layer& x = member(l, m);
        const int f0 = x.ff0, fn = x.ffn;
        for (int r = 0; r < 2; ++r) {
            const size_t tile = (size_t) 16 * l.lay.k2[r], nt = (size_t) g.ff / 16, nth = (size_t) fn / 16;
            for (size_t sl = 0; sl < (size_t) g.dim / 16; ++sl)
                std::memcpy(dst + x.hlay.trellis[r] + sl * nth * tile,
                            blob + l.lay.trellis[r] + (sl * nt + (size_t) f0 / 16) * tile, nth * tile);
            std::memcpy(dst + x.hlay.suh[r], blob + l.lay.suh[r], (size_t) g.dim * 2);
            std::memcpy(dst + x.hlay.svh[r], blob + l.lay.svh[r] + (size_t) f0 * 2, (size_t) fn * 2);
        }
        const size_t row = (size_t) (g.dim / 16) * 16 * l.lay.k2[2];
        std::memcpy(dst + x.hlay.trellis[2], blob + l.lay.trellis[2] + (size_t) (f0 / 16) * row, (size_t) (fn / 16) * row);
        std::memcpy(dst + x.hlay.suh[2], blob + l.lay.suh[2] + (size_t) f0 * 2, (size_t) fn * 2);
        std::memcpy(dst + x.hlay.svh[2], blob + l.lay.svh[2], (size_t) g.dim * 2);
    }
    void half_to_blob(const Layer& l, const uint8_t* src, int m, uint8_t* blob) const {
        if (l.lay.fmt == gg::kFmtMXFP4) return mx_half_to_blob(l, src, m, blob);
        const Layer& x = member(l, m);
        const int f0 = x.ff0, fn = x.ffn;
        for (int r = 0; r < 2; ++r) {
            const size_t tile = (size_t) 16 * l.lay.k2[r], nt = (size_t) g.ff / 16, nth = (size_t) fn / 16;
            for (size_t sl = 0; sl < (size_t) g.dim / 16; ++sl)
                std::memcpy(blob + l.lay.trellis[r] + (sl * nt + (size_t) f0 / 16) * tile,
                            src + x.hlay.trellis[r] + sl * nth * tile, nth * tile);
            if (m == 0) std::memcpy(blob + l.lay.suh[r], src + x.hlay.suh[r], (size_t) g.dim * 2);
            std::memcpy(blob + l.lay.svh[r] + (size_t) f0 * 2, src + x.hlay.svh[r], (size_t) fn * 2);
        }
        const size_t row = (size_t) (g.dim / 16) * 16 * l.lay.k2[2];
        std::memcpy(blob + l.lay.trellis[2] + (size_t) (f0 / 16) * row, src + x.hlay.trellis[2], (size_t) (fn / 16) * row);
        std::memcpy(blob + l.lay.suh[2] + (size_t) f0 * 2, src + x.hlay.suh[2], (size_t) fn * 2);
        if (m == 0) std::memcpy(blob + l.lay.svh[2], src + x.hlay.svh[2], (size_t) g.dim * 2);
    }

    // a group's members' exact expert bytes against each one's own room: a member holds its own part (unit(member)) of
    // each slot of the group's split layers and the whole slots of the group's one-device layers it holds (the
    // drafter's); trimmed a slot at a time - a split layer's, the one with the most; the drafter's when none is left -
    // until each fits; false (err) when one cannot
    bool trim_to_fit(int gi, const std::vector<double>& own, std::string& err) {
        const size_t nm = groups[(size_t) gi].mem.size();
        for (size_t mi = 0; mi < nm; ++mi) {
            const int dv = groups[(size_t) gi].mem[mi];
            auto bytes_of = [&](const Layer& l) -> double {   // (this member's bytes a slot of l: 0 if it holds none)
                if (l.grp != gi) return 0.0;
                if ((size_t) l.nm == nm) return (double) unit(member(l, (int) mi));
                return l.nm == 1 && l.dev == dv ? (double) l.blob : 0.0;
            };
            double b = 0;
            for (const Layer& l : L) b += bytes_of(l) * l.n_vram;
            int trimmed = 0;
            while (b > own[mi]) {
                Layer* pick = nullptr;
                for (Layer& l : L)
                    if (bytes_of(l) > 0 && l.n_vram > 0 &&
                        (pick == nullptr || ((size_t) pick->nm != nm && (size_t) l.nm == nm) ||
                         (((size_t) pick->nm == nm) == ((size_t) l.nm == nm) && l.n_vram > pick->n_vram)))
                        pick = &l;
                if (pick == nullptr) {
                    err = "the experts' VRAM: member " + std::to_string(mi) + " of group " + std::to_string(gi) +
                          " (CUDA" + std::to_string(devs[(size_t) dv].id) + ") has no room for its parts";
                    return false;
                }
                --pick->n_vram;   // (every member gives up its part of that slot: the ones before only fit better)
                b -= bytes_of(*pick);
                ++trimmed;
            }
            if (trimmed > 0)
                std::fprintf(stderr, "ds4: CUDA%d: %d expert slots fewer, its own parts' bytes (%.2f GB) in its room "
                                     "(%.2f GB) (DS4_TP_GGUF_UNEVEN)\n", devs[(size_t) dv].id, trimmed, b / 1e9,
                             own[mi] / 1e9);
        }
        return true;
    }

    // (DS4_DRAFT_DEV) whether device di holds a DSpark block
    bool block_dev(int di) const {
        for (int i = 0; i < g.n_mtp; ++i)
            if (L[(size_t) (g.nl + i)].dev == di) return true;
        return false;
    }
    // the drafter's seeding read h_taps on every block device: a stream about to write the taps waits for each
    bool wait_seed(cudaStream_t s, std::string& err) {
        for (Dev& e : devs)
            if (e.ev_seed != nullptr) CK(cudaStreamWaitEvent(s, e.ev_seed, 0));
        return true;
    }
    // MAYA_DS4_DRAFT_DEV=m, or m0,m1,.. a block (read as STRATA_DS4_DRAFT_DEV, or DS4_DRAFT_DEV): the member of the
    // drafter's group each DSpark block runs on (0: the lead, as before).  place_experts gives a block's VRAM experts out
    // of its own member's room: a tensor-parallel group's members hold the same trunk slots, so every drafter byte on the
    // lead leaves as many idle on the others - with the blocks spread, the tightest member has more left for the trunk.
    // A block on another member than the one before it: its rows go through pinned host memory, as a layer split's
    // groups hand theirs.  Not whole numbers 0 .. the members less one, a count of values neither 1 nor the blocks', no
    // blocks (--dspark none): the load fails.  Unset: every block on the lead, placed as before.
    bool draft_devs(std::string& err) {
        draft_dev.clear();
        const char* v = std::getenv("STRATA_DS4_DRAFT_DEV");
        if (v == nullptr) v = std::getenv("DS4_DRAFT_DEV");
        if (v == nullptr) return true;
        if (g.n_mtp == 0) {
            err = std::string("DS4_DRAFT_DEV=") + v + ": no DSpark blocks loaded (--dspark none)";
            return false;
        }
        const Group& G = groups[(size_t) L[(size_t) g.nl].grp];
        const int nm = (int) G.mem.size();
        std::vector<long> n;
        bool ok = *v != '\0';
        long cur = -1;
        for (const char* q = v; ok; ++q) {
            if (*q >= '0' && *q <= '9') {
                cur = (cur < 0 ? 0 : cur * 10) + (*q - '0');
                ok = cur <= 1000000;
            } else if ((*q == ',' || *q == '\0') && cur >= 0) {
                n.push_back(cur);
                cur = -1;
                if (*q == '\0') break;
            } else {
                ok = false;
            }
        }
        ok = ok && (n.size() == 1 || n.size() == (size_t) g.n_mtp);
        for (const long m : n) ok = ok && m < nm;
        if (!ok) {
            err = std::string("DS4_DRAFT_DEV=") + v + ": not one whole number, or one a block (" + std::to_string(g.n_mtp) +
                  "), each 0 .. " + std::to_string(nm - 1) + " (the drafter's group's members)";
            return false;
        }
        if (n.size() == 1) n.assign((size_t) g.n_mtp, n[0]);   // (one value: every block)
        for (const long m : n) draft_dev.push_back((int) m);
        std::string where;
        for (int i = 0; i < g.n_mtp; ++i)
            where += std::string(i ? ", " : "") + std::to_string(i) + " on CUDA" +
                     std::to_string(devs[(size_t) G.mem[(size_t) draft_dev[(size_t) i]]].id) + " (member " +
                     std::to_string(draft_dev[(size_t) i]) + ")";
        std::fprintf(stderr, "ds4: DS4_DRAFT_DEV %s: DSpark block %s - each block's experts out of its own member's room\n",
                     v, where.c_str());
        return true;
    }

    // the most VRAM experts layer l keeps: a DSpark block DS4_DRAFT_VRAM's (draft_caps), every other layer all
    int vram_cap(const Layer& l) const {
        return l.mtp && !draft_vram.empty() ? std::min(l.n_exp, draft_vram[(size_t) (l.il - g.nl)]) : l.n_exp;
    }
    // MAYA_DS4_DRAFT_VRAM=n, or n0,n1,.. a block (read as STRATA_DS4_DRAFT_VRAM, or DS4_DRAFT_VRAM): the most VRAM
    // experts each DSpark block keeps - its profile's hottest (place_experts' order), the rest on the CPU lane - so the
    // trunk takes the room; one value: every block.  Unset: placed as before.  Not whole numbers 0 .. the block's
    // experts, a count of values neither 1 nor the blocks', or no blocks (--dspark none): the load fails - and so does
    // a cap under a block's experts on a mixed-precision block (n_cls > 1), which place_experts keeps whole in VRAM,
    // its experts in no other tier
    bool draft_caps(std::string& err) {
        draft_vram.clear();
        const char* v = ds4_env("DS4_DRAFT_VRAM");
        if (v == nullptr) return true;
        std::vector<long> n;
        bool ok = *v != '\0';
        long cur = -1;
        for (const char* q = v; ok; ++q) {
            if (*q >= '0' && *q <= '9') {
                cur = (cur < 0 ? 0 : cur * 10) + (*q - '0');
                ok = cur <= 1000000;
            } else if ((*q == ',' || *q == '\0') && cur >= 0) {
                n.push_back(cur);
                cur = -1;
                if (*q == '\0') break;
            } else {
                ok = false;
            }
        }
        ok = ok && g.n_mtp > 0 && (n.size() == 1 || n.size() == (size_t) g.n_mtp);
        for (int i = 0; ok && i < g.n_mtp; ++i) {
            const long c = n[n.size() == 1 ? 0 : (size_t) i];
            ok = c <= L[(size_t) (g.nl + i)].n_exp;
            if (ok) draft_vram.push_back((int) c);
        }
        if (!ok) {
            draft_vram.clear();
            err = std::string("DS4_DRAFT_VRAM=") + v + ": " +
                  (g.n_mtp == 0 ? std::string("no DSpark blocks loaded (--dspark none)")
                                : "not one whole number, or one a block (" + std::to_string(g.n_mtp) + "), each 0 .. " +
                                      std::to_string(g.d_n_exp));
            return false;
        }
        for (int i = 0; i < g.n_mtp; ++i) {
            const Layer& l = L[(size_t) (g.nl + i)];
            if (l.n_cls > 1 && draft_vram[(size_t) i] < l.n_exp) {
                err = std::string("DS4_DRAFT_VRAM=") + v + ": DSpark block " + std::to_string(i) +
                      " is a mixed-precision quant (" + std::to_string(l.n_cls) +
                      " expert layouts), whose experts stay whole in VRAM - no cap";
                draft_vram.clear();
                return false;
            }
        }
        return true;
    }

    bool place_experts(std::string& err) {
        // a mixed-precision quant (layers with experts in several layouts): every expert of those layers
        // in VRAM, in its class's arena - one GPU, no lending of the experts' room (the prompt path keeps its own)
        bool mixed = false;
        for (const Layer& l : L) mixed = mixed || l.n_cls > 1;
        if (mixed && (devs.size() != 1 || groups.size() != 1 || groups[0].mem.size() != 1)) {
            err = "a mixed-precision EXL3 quant (experts at different K in a layer) runs on one GPU for now";
            return false;
        }
        // a lending device (Chunk::borrow) whose experts' room would hardly hold the prompt path's (a GPU with little
        // left for experts, --vram-experts near 0): its own room after all, taken before the experts' as before
        for (size_t di = 0; di < devs.size() && chunk > 0; ++di) {
            if (di >= chunks.size() || chunks[di] == nullptr || !chunks[di]->borrow || chunks[di]->tp_lend) continue;
            Dev& d = devs[di];
            Chunk& c = *chunks[di];
            cudaSetDevice(d.id);
            size_t fr = 0, tot = 0;
            CK(mem_info(&fr, &tot));
            const double room_e = std::max(0.0, (double) fr - (double) ((size_t) o.reserve_mib << 20)) * o.vram_experts;
            const size_t need = lay_chunk(c, chunk, nullptr, 2);
            if (!mixed && room_e >= 2.0 * (double) need) continue;   // (the chunk default's bound: at most half the room)
            c.borrow = false;
            uint8_t* rows = nullptr;
            if (!dalloc(d, rows, need, err)) return false;
            lay_chunk(c, chunk, rows, 2);
            if (need > c.room_bytes) c.room = rows, c.room_bytes = need;
            if (o.verbose)
                std::fprintf(stderr, "ds4: CUDA%d keeps the prompt path's room for itself (%.2f GB): its experts' room "
                                     "(%.2f GB) holds too little to lend it\n", d.id, need / 1e9, room_e / 1e9);
        }
        // (DS4_TP_BORROW) a tensor-parallel group's lending members, all or none: one whose experts' room would hardly
        // hold its buffers keeps its own room, and so does every other member of its group (the same bound as above)
        for (const Group& G : groups) {
            if (G.mem.size() < 2 || chunk <= 0) continue;
            bool any = false, lend = !mixed;
            for (int m : G.mem) {
                if ((size_t) m >= chunks.size() || chunks[(size_t) m] == nullptr || !chunks[(size_t) m]->tp_lend)
                    continue;
                any = true;
                Dev& d = devs[(size_t) m];
                cudaSetDevice(d.id);
                size_t fr = 0, tot = 0;
                CK(mem_info(&fr, &tot));
                const double room_e =
                    std::max(0.0, (double) fr - (double) ((size_t) o.reserve_mib << 20)) * o.vram_experts;
                lend = lend && room_e >= 2.0 * (double) lay_chunk(*chunks[(size_t) m], chunk, nullptr, 2);
            }
            if (!any || lend) continue;
            for (int m : G.mem) {
                if ((size_t) m >= chunks.size() || chunks[(size_t) m] == nullptr || !chunks[(size_t) m]->tp_lend)
                    continue;
                Dev& d = devs[(size_t) m];
                Chunk& c = *chunks[(size_t) m];
                cudaSetDevice(d.id);
                c.borrow = c.tp_lend = false;
                const size_t need = lay_chunk(c, chunk, nullptr, 2);
                uint8_t* rows = nullptr;
                if (!dalloc(d, rows, need, err)) return false;
                lay_chunk(c, chunk, rows, 2);
                if (need > c.room_bytes) c.room = rows, c.room_bytes = need;   // (a picture's room too)
                std::fprintf(stderr, "ds4: CUDA%d keeps the prompt path's room for itself (%.2f GB), as every member "
                                     "of its group does: one's experts' room holds too little to lend it "
                                     "(DS4_TP_BORROW)\n",
                             d.id, need / 1e9);
            }
        }
        // a picture's room (load_vision: lent on demand): the first device's prompt buffers when their region holds
        // it; else, where that device alone lends its prompt buffers' rows to the experts (Chunk::borrow, one GPU), its
        // tail of expert slots (sized for it below); else - a tensor-parallel member's tail (DS4_TP_BORROW: the slots a
        // group shares part by part) is not lent to the tower - the tower's own after all, taken now, before the experts
        // take the rest
        if (vis_mode == kVisChunk) {
            const Chunk* c = chunks.empty() ? nullptr : chunks[0].get();
            if (c != nullptr && c->room != nullptr && c->room_bytes >= vt.room_bytes()) {
            } else if (c != nullptr && c->borrow && !c->tp_lend) {
                vis_mode = kVisTail;
            } else {
                if (!dalloc(devs[0], vis_res, vt.room_bytes(), err, &vis_acct)) return false;
                vis_mode = kVisResident;
                std::fprintf(stderr, "ds4: the vision tower's room (%.0f MiB) stays on CUDA%d: its prompt buffers (%.0f "
                                     "MiB) are smaller\n", (double) vt.room_bytes() / (1 << 20), devs[0].id,
                             (c != nullptr ? (double) c->room_bytes : 0.0) / (1 << 20));
            }
        }
        // (Windows, an integrated GPU: what its experts may commit - commit_room - and what that kept off the GPU)
        double room = 1e300, kept = 0;
        for (const Dev& d : devs)
            if (commit_charged(d)) room = commit_room();
        const double room0 = room;
        if (!draft_caps(err)) return false;   // (DS4_DRAFT_VRAM: the blocks' caps, before any is placed)
        // per group: what its tightest member has left (each member holds its part of every VRAM expert of the
        // group's layers, its unit bytes a slot - counted at the members' mean: an uneven split's odd blocks go round
        // the members layer by layer, so each member's total comes to about the mean's)
        auto ucount = [](const Layer& l) {
            double s = 0;
            for (int m = 0; m < l.nm; ++m) s += (double) unit(member(l, m));
            return s / l.nm;
        };
        for (size_t gi = 0; gi < groups.size(); ++gi) {
            std::vector<double> mroom;   // each member's
            bool charged = false;
            std::vector<double> own;   // (each member's own room, this snapshot: its dense, scratch and head already in)
            for (int m : groups[gi].mem) {
                cudaSetDevice(devs[(size_t) m].id);
                size_t fr = 0, tot = 0;
                CK(mem_info(&fr, &tot));
                mroom.push_back(std::max(0.0, ((double) fr - (double) ((size_t) o.reserve_mib << 20))) * o.vram_experts);
                own.push_back(mroom.back());
                charged = charged || commit_charged(devs[(size_t) m]);
            }
            if (charged && room < 1e300) {   // (each member's slots charged: the group's share of the room)
                const double budget = *std::min_element(mroom.begin(), mroom.end());
                double all = 0;
                for (const Layer& l : L)
                    if (l.grp == (int) gi) all += (double) unit(l) * l.n_exp;
                const double nm = (double) groups[gi].mem.size(), capped = std::min(budget, room / nm);
                kept += std::max(0.0, std::min(budget, all) - std::min(capped, all)) * nm;
                for (double& r : mroom) r = std::min(r, capped);
                room = std::max(0.0, room - std::min(capped, all) * nm);
                for (double& v : own) v = std::min(v, capped);   // (DS4_TP_GGUF_UNEVEN's fit: the commit's share too)
            }
            // a mixed-precision layer's experts first, every one of them (its kernels find each in its class's arena;
            // such a quant runs on one GPU, so the group's one member)
            for (Layer& l : L)
                if (l.grp == (int) gi && l.n_cls > 1) {
                    double b = 0;
                    for (int e = 0; e < l.n_exp; ++e) b += (double) align256(l.cblob[l.cls[(size_t) e]]);
                    if (b > mroom[0]) {
                        err = "layer " + std::to_string(l.il) + "'s experts (" + std::to_string(b / 1e9) +
                              " GB) do not fit the GPU's room left (" + std::to_string(mroom[0] / 1e9) +
                              " GB): a mixed-precision quant keeps every expert in VRAM";
                        return false;
                    }
                    mroom[0] -= b;
                    l.n_vram = l.n_exp;
                }
            // the drafter's experts first (every draft uses its blocks) - a block is its member's alone (the lead's,
            // unless DS4_DRAFT_DEV names another), so it takes that member's room; the trunk's layers then what the
            // tightest member has left
            const std::vector<int>& gm = groups[gi].mem;
            auto bm = [&](const Layer& l) -> size_t {   // (the member a block runs on)
                for (size_t m = 0; m < gm.size(); ++m)
                    if (gm[m] == l.dev) return m;
                return 0;
            };
            auto others = [&](size_t m) -> double {   // (the room of the group's tightest member but m)
                double r = 1e300;
                for (size_t k = 0; k < mroom.size(); ++k)
                    if (k != m) r = std::min(r, mroom[k]);
                return r;
            };
            bool dseen = false;
            for (const Layer& l : L)
                if (l.grp == (int) gi && l.mtp && l.n_cls == 1)
                    for (int e = 0; e < l.n_exp; ++e) dseen = dseen || prof[(size_t) l.il * g.n_exp + e] > 0;
            // (DS4_DRAFT_VRAM: each block's hottest up to its cap, as room goes - the profile's rule below not asked)
            if (mroom.size() == 1 || !dseen || std::getenv("DS4_PLACE_UNIFORM") != nullptr || !draft_vram.empty()) {
                for (Layer& l : L)   // all of them, as room goes (DS4_DRAFT_VRAM: up to vram_cap)
                    if (l.grp == (int) gi && l.mtp && l.n_cls == 1) {
                        double& r = mroom[bm(l)];
                        l.n_vram = std::min(vram_cap(l), (int) std::floor(r / (double) ucount(l)));
                        r -= (double) l.n_vram * ucount(l);
                    }
            } else {
                // by the profile: each block's experts that take 99% of its routes always, the others only while its
                // member keeps the room of the next tightest member (past it, each drafter expert's bytes on that
                // member are as many trunk experts lost on every member: a trunk expert in VRAM takes its part on each)
                std::vector<std::vector<double>> sh(L.size());
                using Top = std::pair<double, int>;   // (the next expert's share a byte, layer)
                std::priority_queue<Top> pq;
                for (Layer& l : L) {
                    if (l.grp != (int) gi || !l.mtp || l.n_cls > 1) continue;
                    const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
                    double sum = 0;
                    for (int e = 0; e < l.n_exp; ++e) sum += p[e];
                    std::vector<double>& s = sh[(size_t) l.il];
                    for (int e = 0; e < l.n_exp; ++e) s.push_back(sum > 0 ? p[e] / sum : 1.0 / l.n_exp);
                    std::sort(s.begin(), s.end(), std::greater<double>());
                    int keep = 0;
                    for (double c = 0; keep < l.n_exp && c < 0.99; ++keep) c += s[(size_t) keep];
                    double& r = mroom[bm(l)];
                    l.n_vram = std::min(keep, (int) std::floor(r / (double) ucount(l)));
                    r -= (double) l.n_vram * ucount(l);
                    if (l.n_vram < l.n_exp) pq.push({s[(size_t) l.n_vram] / ucount(l), l.il});
                }
                while (!pq.empty()) {
                    const int il = pq.top().second;
                    pq.pop();
                    Layer& l = L[(size_t) il];
                    const size_t m = bm(l);
                    if (mroom[m] - ucount(l) < others(m)) continue;
                    mroom[m] -= ucount(l);
                    if (++l.n_vram < l.n_exp) pq.push({sh[(size_t) il][(size_t) l.n_vram] / ucount(l), il});
                }
            }
            const double budget = *std::min_element(mroom.begin(), mroom.end());
            double want = 0, seen = 0;
            for (const Layer& l : L)
                if (l.grp == (int) gi && !l.mtp && l.n_cls == 1) {
                    want += (double) ucount(l) * l.n_exp;
                    for (int e = 0; e < l.n_exp; ++e) seen += prof[(size_t) l.il * g.n_exp + e];
                }
            if (seen > 0 && std::getenv("DS4_PLACE_UNIFORM") == nullptr) {
                // by the profile: the room to the experts that take the largest share of their layer's routes a byte
                // (every layer routes as often; one whose routes spread wider gets more of the room) - each layer's
                // shares smoothed a tenth toward even, so a layer the profile barely saw is not left without
                std::vector<std::vector<double>> sh(L.size());
                using Top = std::pair<double, int>;   // (the next expert's share a byte, layer)
                std::priority_queue<Top> pq;
                for (Layer& l : L) {
                    if (l.grp != (int) gi || l.mtp || l.n_cls > 1) continue;
                    l.n_vram = 0;
                    const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
                    double sum = 0;
                    for (int e = 0; e < l.n_exp; ++e) sum += p[e];
                    std::vector<double>& s = sh[(size_t) l.il];
                    for (int e = 0; e < l.n_exp; ++e)
                        s.push_back(0.9 * (sum > 0 ? p[e] / sum : 1.0 / l.n_exp) + 0.1 / l.n_exp);
                    std::sort(s.begin(), s.end(), std::greater<double>());
                    pq.push({s[0] / ucount(l), l.il});
                }
                double used = 0;
                while (!pq.empty()) {
                    const int il = pq.top().second;
                    pq.pop();
                    Layer& l = L[(size_t) il];
                    if (used + ucount(l) > budget) continue;   // (this layer's experts no longer fit; smaller ones may)
                    used += ucount(l);
                    if (++l.n_vram < l.n_exp) pq.push({sh[(size_t) il][(size_t) l.n_vram] / ucount(l), il});
                }
            } else {   // as even as the room goes: each layer the same share of its experts
                const double frac = want > 0 ? std::min(1.0, budget / want) : 0.0;
                for (Layer& l : L) {
                    if (l.grp != (int) gi || l.mtp || l.n_cls > 1) continue;
                    l.n_vram = std::min(l.n_exp, (int) std::floor(frac * l.n_exp));
                    // never more than fits: the floor of each layer's share can still round up the total
                    while (l.n_vram > 0 && (double) ucount(l) * l.n_vram > budget) --l.n_vram;
                }
                double used = 0;
                for (Layer& l : L)
                    if (l.grp == (int) gi && !l.mtp && l.n_cls == 1) used += (double) ucount(l) * l.n_vram;
                // what the floors left: whole experts, layer by layer
                for (Layer& l : L) {
                    if (l.grp != (int) gi || l.mtp || l.n_cls > 1) continue;
                    while (l.n_vram < l.n_exp && used + (double) ucount(l) <= budget) {
                        ++l.n_vram;
                        used += (double) ucount(l);
                    }
                }
            }
            if (o.verbose) {
                int nv = 0, ne = 0;
                for (const Layer& l : L)
                    if (l.grp == (int) gi) nv += l.n_vram, ne += l.n_exp;
                std::fprintf(stderr, "ds4: group %zu (%zu GPUs): %.2f GB a member for experts, %d of %d in VRAM\n", gi,
                             groups[gi].mem.size(), budget / 1e9, nv, ne);
                for (const Layer& l : L)
                    if (l.grp == (int) gi && std::getenv("DS4_PLACE_DEBUG"))
                        std::fprintf(stderr, "  layer %d%s: blob %.2f MB, mean unit %.2f MB, member 0 %.2f MB, %d of %d\n",
                                     l.il, l.mtp ? " (mtp)" : "", l.blob / 1e6, ucount(l) / 1e6, unit(member(l, 0)) / 1e6,
                                     l.n_vram, l.n_exp);
            }
            // (DS4_TP_GGUF_UNEVEN: the mean above only proposed - each member's exact bytes, its own part of every slot,
            //  against its own room from the same snapshot; over it, a slot less in its group's layer with the most
            //  (the drafter's last), one at a time, till every member fits - no slot left to take: the load refused)
            if (tp_uneven && groups[gi].mem.size() > 1 && !trim_to_fit((int) gi, own, err)) return false;
        }
        if (kept > 0) {   // the commit kept experts off the GPU: say so, and the page file that keeps them on it
            const os::Commit c = os::commit();
            const double gib = (double) (1ull << 30);
            const double pf = c.limit != ~uint64_t{0} && c.ram != ~uint64_t{0} && c.limit > c.ram ? (double) (c.limit - c.ram) : 0.0;
            commit_kept = kept;
            pagefile_hint = std::ceil((pf + kept) / gib);
            std::fprintf(stderr,
                         "ds4: WARNING: %.1f GB of experts stay off the GPU - Windows charges the GPU's memory to its "
                         "commit (RAM + page file) and can commit only %.1f GB more for them (%.0f GB kept for the "
                         "other programs). A page file of %.0f GB (%.0f MB; now %.0f GB) keeps them on the GPU: System "
                         "> About > Advanced system settings > Performance > Advanced > Virtual memory, then restart\n",
                         kept / 1e9, room0 / 1e9, commit_margin() / 1e9, pagefile_hint, pagefile_hint * 1024.0, pf / gib);
        } else if (room0 < 1e300 && o.verbose) {
            std::fprintf(stderr, "ds4: Windows' commit has room for the GPU's experts (%.1f GB beside %.0f GB for the other "
                                 "programs)\n", room0 / 1e9, commit_margin() / 1e9);
        }
        // the prompt path's borrowed room (Chunk::borrow): such a device's layers keep their last tail_k slots in one
        // region, slot-major - the room a run of chunks lays its buffers out in (its chunk size's bytes, at the region's
        // end), the experts' slots the rest of the time
        std::vector<int> n_tail(L.size(), 0);
        for (size_t di = 0; di < devs.size() && chunk > 0; ++di) {
            if (di >= chunks.size() || chunks[di] == nullptr || !chunks[di]->borrow || chunks[di]->tp_lend) continue;
            Dev& d = devs[di];
            Chunk& c = *chunks[di];
            size_t step = 0;
            int min_slots = 1 << 30;
            for (const Layer& l : L)
                if (l.dev == (int) di && !l.mtp) {
                    step += align256(unit(l));
                    min_slots = std::min(min_slots, std::min(l.n_vram, l.n_exp));
                }
            const size_t need = lay_chunk(c, chunk, nullptr, 2) + 256;
            // (the first device's tail is a picture's room too, kVisTail: as many slots a layer as that takes, when it
            //  is more - the tail stays expert slots between prompts and pictures, so it costs the decode nothing)
            const size_t vneed = di == 0 && vis_mode == kVisTail ? vt.room_bytes() + 256 : 0;
            const int k = (int) std::min<size_t>((std::max(need, vneed) + step - 1) / step,
                                                 (size_t) std::max(0, min_slots - 1));
            const size_t cap = (size_t) k * step;
            if (vneed > cap)
                std::fprintf(stderr, "ds4: CUDA%d keeps too few experts in VRAM (%d a layer) to lend a picture its room: "
                                     "a picture takes %.0f MiB of free memory while it is read\n",
                             d.id, min_slots, (double) vt.room_bytes() / (1 << 20));
            if (cap < need) {   // (a device with few VRAM slots a layer: chunks as large as its tail holds)
                int c2 = chunk;
                while (c2 > 256 && lay_chunk(c, c2, nullptr, 2) + 256 > cap) c2 = (c2 - 1) / 256 * 256;
                if (lay_chunk(c, c2, nullptr, 2) + 256 > cap) {
                    std::fprintf(stderr, "ds4: CUDA%d keeps too few experts in VRAM (%d a layer) to lend the prompt path "
                                         "its room: prompts in windows of %d\n", d.id, min_slots, kWin);
                    chunk = 0;
                    for (int& t : n_tail) t = 0;
                    break;
                }
                std::fprintf(stderr, "ds4: CUDA%d lends the prompt path room for chunks of %d tokens (not %d): %d VRAM "
                                     "experts a layer\n", d.id, c2, chunk, min_slots);
                chunk = c2;
            }
            uint8_t* t = nullptr;
            if (!dalloc(d, t, cap, err)) return false;
            d.tail = t;
            d.tail_bytes = cap;
            d.tail_step = step;
            d.tail_k = k;
            d.experts += cap;
            size_t xoff = 0;
            for (Layer& l : L)
                if (l.dev == (int) di && !l.mtp) {
                    l.xbase = t + xoff;
                    l.xstep = step;
                    n_tail[(size_t) (&l - &L[0])] = k;
                    xoff += align256(unit(l));
                }
            if (o.verbose)
                std::fprintf(stderr, "ds4: CUDA%d lends the prompt path up to %.2f GB of its experts' VRAM (%d slots a "
                                     "layer) while a prompt runs: chunks of up to %d tokens\n", d.id, cap / 1e9, k, chunk);
        }
        // (DS4_TP_BORROW) a tensor-parallel group's lending members: one k for the group's layers (a slot past n_main
        // lies in every member's tail: sat() takes each member's xbase / xstep), each member's tail k of its own parts
        // of a slot of each of its layers, its buffers at the tail's end - k the most any member needs (tp_tail_k)
        for (size_t gi = 0; gi < groups.size() && chunk > 0; ++gi) {
            std::vector<int> mems;
            for (int m : groups[gi].mem)
                if ((size_t) m < chunks.size() && chunks[(size_t) m] != nullptr && chunks[(size_t) m]->tp_lend)
                    mems.push_back(m);
            if (mems.empty()) continue;
            std::vector<size_t> step(mems.size(), 0), need(mems.size(), 0);
            int min_slots = 1 << 30;
            for (const Layer& l : L) {
                if (l.grp != (int) gi || l.mtp) continue;
                min_slots = std::min(min_slots, std::min(l.n_vram, l.n_exp));
                for (int m = 0; m < l.nm; ++m)
                    for (size_t i = 0; i < mems.size(); ++i)
                        if (member(l, m).dev == mems[i]) step[i] += align256(unit(member(l, m)));
            }
            const auto needs = [&](int C) {
                for (size_t i = 0; i < mems.size(); ++i) need[i] = lay_chunk(*chunks[(size_t) mems[i]], C, nullptr, 2);
            };
            needs(chunk);
            const int k = tp_tail_k(need, step, min_slots - 1);
            if (k > 0 && !tp_tail_fits(need, step, k)) {   // (few VRAM slots a layer: chunks the tails hold)
                int c2 = chunk;
                while (c2 > 256 && !tp_tail_fits(need, step, k)) {
                    c2 = (c2 - 1) / 256 * 256;
                    needs(c2);
                }
                if (tp_tail_fits(need, step, k)) {
                    std::fprintf(stderr, "ds4: CUDA%d's tensor-parallel group lends the prompt path room for chunks of "
                                         "%d tokens (not %d): %d VRAM experts a layer (DS4_TP_BORROW)\n",
                                 devs[(size_t) mems[0]].id, c2, chunk, min_slots);
                    chunk = c2;
                }
            }
            if (k <= 0 || !tp_tail_fits(need, step, k)) {
                std::fprintf(stderr, "ds4: CUDA%d's tensor-parallel group keeps too few experts in VRAM (%d a layer) "
                                     "to lend the prompt path its room: prompts in windows of %d (DS4_TP_BORROW)\n",
                             devs[(size_t) mems[0]].id, min_slots, kWin);
                chunk = 0;
                for (int& t : n_tail) t = 0;
                break;
            }
            for (size_t i = 0; i < mems.size(); ++i) {
                Dev& d = devs[(size_t) mems[i]];
                cudaSetDevice(d.id);
                const size_t cap = (size_t) k * step[i];
                uint8_t* t = nullptr;
                if (!dalloc(d, t, cap, err)) return false;
                d.tail = t;
                d.tail_bytes = cap;
                d.tail_step = step[i];
                d.tail_k = k;
                d.experts += cap;
                size_t xoff = 0;
                for (Layer& l : L) {
                    if (l.grp != (int) gi || l.mtp) continue;
                    for (int m = 0; m < l.nm; ++m) {
                        Layer& x = member(l, m);
                        if (x.dev != mems[i]) continue;
                        x.xbase = t + xoff;
                        x.xstep = step[i];
                        xoff += align256(unit(x));
                        n_tail[(size_t) (&l - &L[0])] = k;
                    }
                }
                std::fprintf(stderr, "ds4: CUDA%d lends the prompt path up to %.2f GB of its experts' VRAM (%d slots a "
                                     "layer, its part of each) while a prompt runs: chunks of up to %d tokens "
                                     "(DS4_TP_BORROW)\n", d.id, cap / 1e9, k, chunk);
            }
        }
        for (Layer& l : L) {
            // the hottest experts of the profile first, then by index
            std::vector<int> order((size_t) l.n_exp);
            std::iota(order.begin(), order.end(), 0);
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            std::stable_sort(order.begin(), order.end(), [&](int a, int b) { return p[a] > p[b]; });
            l.slot.assign((size_t) l.n_exp, -1);
            l.host.assign((size_t) l.n_exp, nullptr);
            if (l.n_cls > 1) {   // every expert in VRAM, slot e = expert e, class c's experts in its own arena
                Dev& d = devs[(size_t) l.dev];
                cudaSetDevice(d.id);
                l.n_slots = l.n_vram = l.n_main = l.pv_n = l.n_exp;
                l.spare_vram = -1;
                l.maddr.assign((size_t) l.n_exp, nullptr);
                l.mix = x3::MixedLayouts{};
                l.mix.n = l.n_cls;
                for (int c = 0; c < l.n_cls; ++c) {
                    int n = 0;
                    for (uint8_t x : l.cls) n += x == c;
                    const size_t step = align256(l.cblob[c]);
                    void* v = nullptr;
                    if (cudaMalloc(&v, (size_t) n * step) != cudaSuccess) {
                        err = "cudaMalloc of layer " + std::to_string(l.il) + "'s class " + std::to_string(c) + " (" +
                              std::to_string(n) + " experts) failed";
                        return false;
                    }
                    d.allocs.push_back(v);
                    d.experts += (size_t) n * step;
                    int i = 0;
                    for (int e = 0; e < l.n_exp; ++e)
                        if (l.cls[(size_t) e] == c) l.maddr[(size_t) e] = (uint8_t*) v + (size_t) (i++) * step;
                    l.mix.lo[c] = (unsigned long long) v;
                    l.mix.hi[c] = (unsigned long long) v + (size_t) n * step;
                    l.mix.lay[c] = l.clay[c];
                }
                if (l.vram_base == nullptr) l.vram_base = l.maddr[0];
                for (int e = 0; e < l.n_exp; ++e) l.slot[(size_t) e] = e;
                std::vector<unsigned long long> tab((size_t) l.n_exp);
                for (int e = 0; e < l.n_exp; ++e) tab[(size_t) e] = (unsigned long long) l.maddr[(size_t) e];
                if (!dalloc(d, l.d_maddr, (size_t) l.n_exp, err)) return false;
                CK(cudaMemcpy(l.d_maddr, tab.data(), tab.size() * 8, cudaMemcpyHostToDevice));
                CK(cudaMemcpy(l.vram_tab, tab.data(), tab.size() * 8, cudaMemcpyHostToDevice));
                l.heat.assign((size_t) l.n_exp, 0.0f);
                l.hh.assign((size_t) l.n_exp, {nullptr, nullptr, nullptr, nullptr});
                l.vm.assign((size_t) l.n_exp, {});
                for (int e = 0; e < l.n_exp; ++e) set_vm(l, e, e);
                if (!halloc(l.tab_pin, (size_t) 2 * l.nm, err)) return false;
                if (o.verbose) {
                    double gb = 0;
                    for (int c = 0; c < l.n_cls; ++c) gb += (double) (l.mix.hi[c] - l.mix.lo[c]) / 1e9;
                    std::fprintf(stderr, "ds4: %s %d experts in VRAM in %d class arenas (%.2f GB)\n", l.name.c_str(),
                                 l.n_exp, l.n_cls, gb);
                }
                continue;
            }
            // a layer with experts on both sides keeps one VRAM slot free for the cache's swaps
            l.n_slots = std::min(l.n_vram, l.n_exp);
            if (o.expert_cache && l.n_slots >= 2 && l.n_slots < l.n_exp) {   // (every expert fits: nothing to swap)
                const int r = recent_n > 0 && !l.mtp && (!file_experts || (pk.gguf && ln_land)) &&
                                      l.n_slots - 1 - recent_n >= 1 ? recent_n : 0;
                l.n_vram = l.n_slots - 1 - r;   // (the recent slots: [n_vram, n_vram + r), from the profile's coldest)
                l.spare_vram = l.n_slots - 1;
                l.rc_base = l.n_vram;
                l.rc_n = r;
            } else {
                l.n_vram = l.n_slots;
                l.spare_vram = -1;
            }
            for (int i = 0; i < l.n_vram; ++i) l.slot[(size_t) order[(size_t) i]] = i;
            // (the last n_tail slots - the coldest of them, and the cache's spare - in the device's tail region)
            l.n_main = l.n_slots - std::min(l.n_slots, n_tail[(size_t) (&l - &L[0])]);
            l.pv_n = l.n_slots;
            for (int m = 0; m < l.nm && l.n_main > 0; ++m) {
                Layer& x = member(l, m);
                Dev& d = devs[(size_t) x.dev];
                cudaSetDevice(d.id);
                void* v = nullptr;
                if (cudaMalloc(&v, (size_t) l.n_main * unit(x)) != cudaSuccess) {
                    err = "cudaMalloc of layer " + std::to_string(l.il) + "'s " + std::to_string(l.n_main) +
                          " experts on CUDA" + std::to_string(d.id) + " failed";
                    return false;
                }
                d.allocs.push_back(v);
                d.experts += (size_t) l.n_main * unit(x);
                x.vram_base = (uint8_t*) v;
            }
            l.heat.assign((size_t) l.n_exp, 0.0f);
            {   // the profile as the starting heat: its counts scaled to ~512 hits a layer
                double sum = 0;
                for (int e = 0; e < l.n_exp; ++e) sum += p[e];
                const double sc = sum > 0 ? 512.0 / sum : 0.0;
                for (int e = 0; e < l.n_exp; ++e) l.heat[(size_t) e] = (float) (p[e] * sc);
            }
            const int n_host = l.n_exp - l.n_vram;
            {   // the CPU lane's parts of an expert (in place: the whole expert, its pieces where the file has them)
                size_t off = 0;
                for (int r = 0; r < 3; ++r) {
                    const int k = r < 2 ? g.dim : g.ff, nf = r < 2 ? g.ff : g.dim, n = nf / NH;
                    l.hl.k[r] = k;
                    l.hl.n[r] = n;
                    l.hl.trellis[r] = file_experts ? l.piece_src[r][0] : off;
                    off += align256((size_t) (k / 16) * (n / 16) * 16 * l.lay.k2[r]);
                    l.hl.suh[r] = file_experts ? l.piece_src[r][1] : off;
                    off += align256((size_t) k * 2);
                    l.hl.svh[r] = file_experts ? l.piece_src[r][2] : off;
                    off += align256((size_t) n * 2);
                }
                l.hl.bytes = off;
                const char* packed = std::getenv("DS4_EXL3_PACKED_HOST");
                bool eligible = packed && std::atoi(packed) != 0 && !file_experts && NH == 1 &&
                                l.lay.fmt != gg::kFmtMXFP4 && l.n_cls == 1 && l.nm == 2 &&
                                (g.ff / l.nm) % 128 == 0;
                for (int m = 0; m < l.nm && eligible; ++m)
                    eligible = member(l, m).ff0 == m * (g.ff / l.nm) &&
                               member(l, m).ffn == g.ff / l.nm && member(l, m).hblob == l.hblob;
                for (int r = 0; r < 3 && eligible; ++r)
                    eligible = (l.lay.k2[r] % 2) == 0;
                if (eligible) {
                    const size_t bytes = (size_t) l.nm * l.hblob;
                    const size_t slots = (size_t) n_host + (l.spare_vram >= 0 ? 1 : 0);
                    const uint64_t avail = ram_room();
                    if (bytes >= off && (avail == ~uint64_t{0} ||
                        (avail > kRamMargin && slots <= (avail - kRamMargin) / bytes))) {
                        l.hl.bytes = bytes;
                        l.packed_host = true;
                        if (o.verbose)
                            std::fprintf(stderr, "ds4: packed EXL3 TP host layer %d: %d members, %zu bytes/slot\n",
                                         l.il, l.nm, bytes);
                    }
                }
            }
            l.hh.assign((size_t) l.n_exp, {nullptr, nullptr, nullptr, nullptr});
            if (l.lay.fmt == gg::kFmtMXFP4) {   // a GGUF's: read in place from the file's mapping
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) l.host[(size_t) e] = (uint8_t*) mx_mat(l, e, 0);
            } else if (file_experts) {   // every expert's file mapped (the cache's swaps hand VRAM experts back to the files)
                for (int e = 0; e < l.n_exp; ++e)
                    if (pk.map(l.region_file[(size_t) e]) == nullptr) {
                        err = "mapping " + pk.files[(size_t) l.region_file[(size_t) e]] + " failed";
                        return false;
                    }
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) {
                        l.hh[(size_t) e][0] = file_part(l, e);
                        l.host[(size_t) e] = l.hh[(size_t) e][0];
                    }
            } else if (n_host > 0) {
                const int n_parts = n_host + (l.spare_vram >= 0 ? 1 : 0);   // (+ the cache's spare)
                const size_t bytes = (size_t) n_parts * l.hl.bytes;
                for (int X = 0; X < NH; ++X) {
                    void* m = node_map(bytes, X, NH);
                    if (m == nullptr) {
                        err = "host memory for layer " + std::to_string(l.il) + "'s " + std::to_string(n_host) +
                              " CPU experts (" + std::to_string(bytes >> 20) + " MiB on node " + std::to_string(X) + ")";
                        return false;
                    }
                    host_maps.emplace_back(m, bytes);
                    int hi = 0;
                    for (int e = 0; e < l.n_exp; ++e)
                        if (l.slot[(size_t) e] < 0) l.hh[(size_t) e][(size_t) X] = (uint8_t*) m + (size_t) (hi++) * l.hl.bytes;
                    if (l.spare_vram >= 0) l.spare_host[(size_t) X] = (uint8_t*) m + (size_t) hi * l.hl.bytes;
                }
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) l.host[(size_t) e] = l.hh[(size_t) e][0];
            }
            l.vm.assign((size_t) l.n_exp, {});
            if (l.nm == 1)   // (the host-routed window path's views: a group's members take the device-routed path)
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] >= 0) set_vm(l, e, l.slot[(size_t) e]);
            if (!halloc(l.tab_pin, (size_t) 2 * l.nm, err)) return false;
            if (l.rc_n > 0) {
                l.rc_exp.assign((size_t) l.rc_n, -1);
                l.rc_fill.assign((size_t) l.rc_n, -1);
                l.rc_land.assign((size_t) l.rc_n, -1);
                l.rc_lseq.assign((size_t) l.rc_n, 0u);
                l.rc_lq.assign((size_t) l.rc_n, 0);
                l.rc_gen.assign((size_t) l.rc_n, 0u);
                l.rc_stamp.assign((size_t) l.rc_n, 0u);
                if (!halloc(l.rc_pin, (size_t) l.rc_n * l.nm + 1, err)) return false;
                l.rc_ev.assign((size_t) l.rc_n * l.nm, nullptr);
                for (int i = 0; i < l.rc_n; ++i)
                    for (int m = 0; m < l.nm; ++m) {
                        Layer& x = member(l, m);
                        // (sat: a slot past the main arena lies in the extension - a GGUF's layers have one)
                        l.rc_pin[(size_t) i * l.nm + m] = (unsigned long long) sat(l, x, l.rc_base + i, unit(x));
                        CK(cudaSetDevice(devs[(size_t) x.dev].id));
                        CK(cudaEventCreateWithFlags(&l.rc_ev[(size_t) i * l.nm + m], cudaEventDisableTiming));
                    }
                l.rc_pin[(size_t) l.rc_n * l.nm] = 0ull;
            }
            for (int m = 0; m < l.nm; ++m) {
                Layer& x = member(l, m);
                std::vector<unsigned long long> tab((size_t) l.n_exp, 0ull);
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] >= 0)
                        tab[(size_t) e] = (unsigned long long) sat(l, x, l.slot[(size_t) e], unit(x));
                cudaSetDevice(devs[(size_t) x.dev].id);
                CK(cudaMemcpy(x.vram_tab, tab.data(), tab.size() * 8, cudaMemcpyHostToDevice));
            }
        }
        for (const Layer& l : L)   // (DS4_DRAFT_VRAM: what each block kept - its slots, the cache's spare among them)
            if (l.mtp && !draft_vram.empty())
                std::fprintf(stderr, "ds4: DSpark block %d: %d of its %d experts' slots in VRAM, at most %d "
                                     "(DS4_DRAFT_VRAM), the profile's hottest; the rest on the CPU lane\n",
                             l.il - g.nl, l.n_slots, l.n_exp, vram_cap(l));
        return true;
    }

    // a GGUF's VRAM experts, in file order, by a few threads through pinned staging blobs (the CPU lane's stay in the
    // file: the mapping reads them on first use)
    bool load_experts_mx(std::string& err) {
        struct Job {
            int layer, e;
            bool help;   // (into the helper GPU's pool)
        };
        std::vector<Job> jobs;
        size_t maxb = 0;
        for (const Layer& l : L) {
            maxb = std::max(maxb, l.blob);
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] >= 0 || helper_owned(l, e)) jobs.push_back({l.il, e, l.slot[(size_t) e] < 0});
        }
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.mx_file[0] != lb.mx_file[0]) return la.mx_file[0] < lb.mx_file[0];
            return la.mx_off[0] + (uint64_t) a.e * la.mx_stride[0] < lb.mx_off[0] + (uint64_t) b.e * lb.mx_stride[0];
        });
        std::atomic<size_t> next{0};
        std::atomic<bool> failed{false};
        std::mutex emu;
        std::string ferr;
        std::atomic<int64_t> done_bytes{0};
        const double t0 = now_ms();
        std::vector<std::thread> th;
        for (int t = 0; t < 12; ++t)
            th.emplace_back([&] {
                uint8_t *stage = nullptr, *stage2 = nullptr;
                cudaHostAlloc((void**) &stage, maxb, cudaHostAllocPortable);
                cudaHostAlloc((void**) &stage2, maxb, cudaHostAllocPortable);
                for (;;) {
                    const size_t i = next.fetch_add(1);
                    if (i >= jobs.size() || failed.load()) break;
                    const Layer& l = L[(size_t) jobs[i].layer];
                    const int e = jobs[i].e;
                    bool ok = stage != nullptr && stage2 != nullptr && read_mx(l, e, stage);
                    if (jobs[i].help)
                        ok = ok && cudaSetDevice(helper_id) == cudaSuccess &&
                             cudaMemcpy(l.helper[(size_t) e], stage, l.blob, cudaMemcpyHostToDevice) == cudaSuccess;
                    for (int m = 0; m < l.nm && ok && !jobs[i].help; ++m) {   // (a group: each member its part)
                        const Layer& x = member(l, m);
                        cudaSetDevice(devs[(size_t) x.dev].id);
                        if (l.nm > 1) blob_to_half(l, stage, m, stage2);
                        ok = cudaMemcpy(sat(l, x, l.slot[(size_t) e], unit(x)), l.nm > 1 ? stage2 : stage,
                                        unit(x), cudaMemcpyHostToDevice) == cudaSuccess;
                    }
                    if (!ok) {
                        std::lock_guard<std::mutex> lk(emu);
                        ferr = "loading layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
                        failed.store(true);
                        break;
                    }
                    const int64_t db = done_bytes.fetch_add((int64_t) l.blob) + (int64_t) l.blob;
                    if (o.verbose && (i % 1024) == 0)
                        std::fprintf(stderr, "ds4: experts %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(), db / 1e9,
                                     db / 1e6 / std::max(1.0, now_ms() - t0));
                }
                if (stage) cudaFreeHost(stage);
                if (stage2) cudaFreeHost(stage2);
            });
        for (auto& t : th) t.join();
        if (failed.load()) {
            err = ferr;
            return false;
        }
        if (helper_n > 0) {   // (the helper's pool filled: what it takes of the host RAM is ram_avail's to see now)
            helper_pending = 0;
            const uint64_t av = ram_avail();
            std::fprintf(stderr, "ds4: helper CUDA%d: %d experts in (%.1f GB); RAM available %.1f GB\n", helper_id,
                         helper_n, helper_prof / 1e9, av == ~uint64_t{0} ? 0.0 : av / 1e9);
        }
        // as load_experts in place: the VRAM experts' pages leave the cache, the most-routed of the others (the
        // profile's share of their layer, then by index) are read once, up to warm_bytes, so the cache starts with them
        struct Warm {
            int layer, e;
            double share;
        };
        std::vector<Warm> warm;
        for (const Layer& l : L) {
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            double sum = 0;
            for (int e = 0; e < l.n_exp; ++e) sum += p[e];
            for (int e = 0; e < l.n_exp; ++e) {
                if (l.slot[(size_t) e] >= 0 || helper_owned(l, e)) {   // (the helper's: in its pool)
                    for (int r = 0; r < 3; ++r)
                        os::advise(pk.fds[(size_t) l.mx_file[r]], (l.mx_off[r] + (uint64_t) e * l.mx_stride[r]), mx_part_bytes(l, r), false);
                } else {
                    warm.push_back({l.il, e, sum > 0 ? p[e] / sum : 0.0});
                }
            }
        }
        std::stable_sort(warm.begin(), warm.end(), [](const Warm& a, const Warm& b) { return a.share > b.share; });
        if (!ram_tier && !warm.empty()) {   // copied into RAM (copy_experts decides), the rest read ahead into what is left
            std::vector<std::pair<int, int>> hot;
            for (const Warm& w : warm) hot.push_back({w.layer, w.e});
            if (!copy_experts(hot, err)) return false;
            if (copy_mode) {
                warm.erase(std::remove_if(warm.begin(), warm.end(),
                                          [&](const Warm& w) { return L[(size_t) w.layer].ram[(size_t) w.e] >= 0; }),
                           warm.end());
                const uint64_t av = ram_room();
                if (av != ~uint64_t{0}) warm_bytes = av > kRamMargin ? std::min<uint64_t>(warm_bytes, av - kRamMargin) : 0;
            }
        }
        if (ram_tier && warm_bytes > 0 && !warm.empty()) {
            // chunks of 32 slots up to warm_bytes (all the RAM the rest leaves, kRamMargin kept), one slot kept free for
            // a move in; the hottest experts read in, their pages then dropped from the page cache.  Plain memory, not
            // pinned: only the CPU reads it (what goes to a GPU passes the pinned staging), and pinned memory is capped on
            // Windows - the engine's own pinned buffers come after this
            const size_t want = std::min(warm.size(), (size_t) (warm_bytes / maxb));
            while (ram_slots.size() < want + 1) {
                const size_t n = std::min<size_t>(32, want + 1 - ram_slots.size());
                uint8_t* c = (uint8_t*) os::anon_alloc(n * maxb, -1, 1);
                if (c == nullptr) break;
                ram_chunks.push_back(c);
                ram_chunk_bytes.push_back(n * maxb);
                for (size_t i = 0; i < n; ++i) ram_slots.push_back(c + i * maxb);
            }
            ram_held = ram_slots.empty() ? 0 : (int) ram_slots.size() - 1;
            for (Layer& l : L)
                if (l.lay.fmt == gg::kFmtMXFP4) l.ram.assign((size_t) l.n_exp, -1);
            std::atomic<size_t> ri{0};
            std::atomic<bool> rfail{false};
            std::vector<std::thread> rt;
            for (int t = 0; t < 12 && ram_held > 0; ++t)
                rt.emplace_back([&] {
                    for (size_t i; (i = ri.fetch_add(1)) < (size_t) ram_held;) {
                        const Layer& l = L[(size_t) warm[i].layer];
                        if (!read_mx_file(l, warm[i].e, ram_slots[i])) rfail.store(true);
                        for (int r = 0; r < 3; ++r)
                            os::advise(pk.fds[(size_t) l.mx_file[r]], l.mx_off[r] + (uint64_t) warm[i].e * l.mx_stride[r],
                                       mx_part_bytes(l, r), false);
                    }
                });
            for (auto& t : rt) t.join();
            if (rfail.load()) {
                err = "reading the RAM tier's experts from the model's files failed";
                return false;
            }
            for (int i = 0; i < ram_held; ++i) L[(size_t) warm[(size_t) i].layer].ram[(size_t) warm[(size_t) i].e] = i;
            if (ram_held > 0) ram_free.push_back(ram_held);
            if (o.expert_cache && ram_held > 0) ram_th = std::thread([this] { ram_loop(); });
            if (o.verbose)
                std::fprintf(stderr, "ds4: RAM tier: %d experts (%.1f GB of RAM), the hottest after VRAM's; the other %zu "
                                     "read from the model's files (%.1f s)\n",
                             ram_held, ram_slots.size() * (double) maxb / 1e9, warm.size() - (size_t) ram_held,
                             (now_ms() - t0) / 1000.0);
            return true;
        }
        size_t nw = 0;
        for (double b = 0; nw < warm.size() && b + (double) L[(size_t) warm[nw].layer].blob <= (double) warm_bytes; ++nw)
            b += (double) L[(size_t) warm[nw].layer].blob;
        std::atomic<size_t> wi{0};
        std::vector<std::thread> wt;
        for (int t = 0; t < 12 && nw > 0; ++t)
            wt.emplace_back([&] {
                std::vector<uint8_t> buf(maxb);
                for (size_t i; (i = wi.fetch_add(1)) < nw;) read_mx(L[(size_t) warm[i].layer], warm[i].e, buf.data());
            });
        for (auto& t : wt) t.join();
        if (o.verbose && nw > 0)
            std::fprintf(stderr, "ds4: %zu CPU-lane experts read ahead (%.1f GB) in %.1f s\n", nw,
                         nw * (double) L[0].blob / 1e9, (now_ms() - t0) / 1000.0);
        return true;
    }

    // a GGUF's CPU-lane experts copied into RAM (copy_mode), decided once VRAM's are in - on a unified-memory APU the GPU
    // has taken its share of the RAM by then, so the copies only get what it leaves.  `hot`: the CPU lane's experts, the
    // most-routed first.  --mmap-experts off: all that fit beside kRamMargin (a warning if not all do); auto: all of
    // them when the RAM holds every one with kAutoCopyRoom more to spare, else none (#339: copied, decode +22% on 4x V100
    // with 504 GB, ~2x on a 20 GB Ada with 255 GB, +23% on 4x RTX 3090 with 126 GB - the experts were read from the SSD
    // at every token in place; a PART copied cost decode speed on 32 / 64 GB, so auto never copies a part); on: none -
    // read in place; DS4_COPY_GB=<n>: the
    // hottest n GB (the static hybrid, for tests).  Each copy in NH parts on the NUMA nodes (DS4_COPY_NUMA=1: one), read from the files in file
    // order by a few threads, anonymous memory on huge pages (Windows: plain), not pinned (only the CPU reads it; what
    // goes to a GPU passes the pinned staging) - a layer that cannot get its memory keeps its experts in place
    // STRATA_DS4_LOAD_DROP_CACHE (1): once an expert's bytes are copied into VRAM or RAM, drop their pages from the
    // file cache (posix_fadvise DONTNEED) instead of holding the same bytes twice: without it a pack whose copies and
    // their cache do not fit reclaims in the copying thread (0.8 GB/s measured).  0 keeps every region's pages - a
    // restart then starts warm, and a pack that does fit loads a few seconds faster without the calls.
    static bool load_drop_cache() {
        const char* v = std::getenv("STRATA_DS4_LOAD_DROP_CACHE");
        return v == nullptr || std::atoi(v) != 0;
    }
    bool copy_experts(const std::vector<std::pair<int, int>>& hot, std::string& err) {
        const char* require_ram = std::getenv("DS4_REQUIRE_ALL_RAM");
        const bool strict_ram = require_ram && std::atoi(require_ram) != 0;
        if (strict_ram && o.mmap_experts != 0) { err = "strict RAM requires --mmap-experts off"; return false; }
        if (o.mmap_experts > 0 || hot.empty()) return true;
#if defined(_WIN32)
        const bool drop_copy_cache = false, direct_copy = false;
#else
        const char* direct_copy_env = std::getenv("DS4_COPY_DIRECT");
        const bool direct_copy = direct_copy_env && std::atoi(direct_copy_env) != 0;
        const char* drop_cache_env = std::getenv("DS4_COPY_DROP_CACHE");
        const bool drop_copy_cache = drop_cache_env && std::atoi(drop_cache_env) != 0;
#endif
        std::atomic<uint64_t> cache_hint_bytes{0}, direct_copy_bytes{0}, buffered_fallback_bytes{0};
        const double t0 = now_ms();
        auto spare_of = [&](const Layer& l) { return o.expert_cache && l.spare_vram >= 0 ? 1 : 0; };
        double all = 0;
        {
            std::vector<char> seen(L.size(), 0);
            for (const auto& h : hot) {
                const Layer& l = L[(size_t) h.first];
                all += (double) l.blob * (1 + (seen[(size_t) l.il]++ == 0 ? spare_of(l) : 0));
            }
        }
        const uint64_t avail = ram_room();
        // (Windows: the copies are committed memory, within what its commit still has beside the other programs' margin)
        const double can = std::min(avail == ~uint64_t{0} ? 1e300 : std::max(0.0, (double) avail - (double) kRamMargin),
                                    commit_room());
        // (auto: all or none - a part copied cost decode speed on 64 GB and on 32 GB of RAM, but every expert in RAM
        // keeps the SSD out of the decode: #339's reports)
        const bool auto_all = o.mmap_experts < 0 && all + (double) kAutoCopyRoom <= can;
        double budget = strict_ram ? all : (o.mmap_experts == 0 ? std::min(all, can) : auto_all ? all : 0.0);
        if (auto_all)
            std::fprintf(stderr, "ds4: --mmap-experts auto: the CPU lane's experts (%.1f GB) fit the RAM this process can "
                                 "get (%.1f GB): copied into RAM (--mmap-experts on keeps them in the files)\n",
                         all / 1e9, can / 1e9);
        if (!strict_ram) if (const char* v = std::getenv("DS4_COPY_GB")) budget = std::atof(v) * 1e9;
        if (!strict_ram && warm_cap >= 0) budget = std::min(budget, warm_cap);   // (DS4_WARM_CAP_GB)
        if (!strict_ram && o.mmap_experts == 0 && all > can)
            std::fprintf(stderr, "ds4: --mmap-experts off: the CPU lane's experts (%.1f GB) do not all fit the RAM this "
                                 "process can get (%.1f GB beside %.0f GB for the rest) - the most-routed copied, the "
                                 "others read in place\n", all / 1e9, can / 1e9, kRamMargin / 1e9);
        if (budget <= 0) {
            if (o.verbose)
                std::fprintf(stderr, "ds4: the CPU lane's experts (%.1f GB) stay in place: the RAM this process can get "
                                     "(%.1f GB beside %.0f GB for the rest) does not hold them all\n",
                             all / 1e9, can / 1e9, kRamMargin / 1e9);
            return true;
        }
        // NUMA parts: whole rows of each matrix, so any row count the nodes divide
        int nh = (int) std::min<size_t>(2, std::max<size_t>(1, cores.size()));
        if (const char* v = std::getenv("DS4_COPY_NUMA"))   // (0 / 1: one part; 2-4: that many, a node each; more
            nh = std::max(1, std::min(kMaxNH, std::atoi(v)));   // than the host's nodes: a test on fewer)
        if (g.ff % nh != 0 || g.dim % nh != 0) nh = 1;
        NH = nh;
        cp_lay.assign(L.size(), {0, 0, 0, 0});
        for (const Layer& l : L) {
            size_t off = 0;
            for (int r = 0; r < 3; ++r) {
                cp_lay[(size_t) l.il][(size_t) r] = off;
                off += align256((size_t) (mx_n(r) / NH) * mx_row_b(l, r));
            }
            cp_lay[(size_t) l.il][3] = off;
        }
        // the hottest that fit the budget (a layer's first one brings its spare)
        std::vector<int> n_copy(L.size(), 0);
        double used = 0;
        size_t take = 0;
        for (; take < hot.size(); ++take) {
            const Layer& l = L[(size_t) hot[take].first];
            const double add = (double) l.blob * (1 + (n_copy[(size_t) l.il] == 0 ? spare_of(l) + (copy_swap ? 1 : 0) : 0));
            if (used + add > budget) break;
            used += add;
            ++n_copy[(size_t) l.il];
        }
        // each layer's slots: one block per node of (copies + spare) parts
        std::vector<int> first(L.size(), -1);
        copy_spare.assign(L.size(), -1);
        cs_free.assign(L.size(), -1);
        for (Layer& l : L) {
            l.ram.assign((size_t) l.n_exp, -1);
            const int ns = n_copy[(size_t) l.il] + (n_copy[(size_t) l.il] > 0 ? spare_of(l) + (copy_swap ? 1 : 0) : 0);
            if (ns == 0) continue;
            const size_t part = cp_lay[(size_t) l.il][3], bytes = (size_t) ns * part;
            std::array<uint8_t*, kMaxNH> base{};
            bool ok = true;
            for (int X = 0; X < NH && ok; ++X) {
                base[(size_t) X] = (uint8_t*) node_map(bytes, X, NH);
                ok = base[(size_t) X] != nullptr;
                if (ok) {
                    ram_chunks.push_back(base[(size_t) X]);
                    ram_chunk_bytes.push_back(bytes);
                }
            }
            if (!ok) {
                if (strict_ram) { err = "strict RAM: cannot allocate every CPU expert; refusing disk fallback"; return false; }
                std::fprintf(stderr, "ds4: no RAM for layer %d's %d copied experts (%.1f GB): they stay in place\n", l.il,
                             ns, (double) bytes * NH / 1e9);
                n_copy[(size_t) l.il] = 0;
                continue;
            }
            first[(size_t) l.il] = (int) ram_part.size();
            for (int i = 0; i < ns; ++i) {
                std::array<uint8_t*, kMaxNH> slot{};
                for (int X = 0; X < NH; ++X) slot[(size_t) X] = base[(size_t) X] + (size_t) i * part;
                ram_part.push_back(slot);
            }
            if (spare_of(l)) copy_spare[(size_t) l.il] = first[(size_t) l.il] + n_copy[(size_t) l.il];
            if (copy_swap) cs_free[(size_t) l.il] = first[(size_t) l.il] + n_copy[(size_t) l.il] + spare_of(l);
        }
        struct Job {
            int layer, e, slot;
        };
        std::vector<Job> jobs;
        {
            std::vector<int> next = first;
            for (size_t i = 0; i < take; ++i) {
                const int il = hot[i].first;
                if (n_copy[(size_t) il] == 0) continue;
                jobs.push_back({il, hot[i].second, next[(size_t) il]++});
            }
        }
        if (strict_ram && jobs.size() != hot.size()) { err = "strict RAM: incomplete CPU expert allocation"; return false; }
        if (strict_ram) std::fprintf(stderr, "ds4: strict RAM: all %zu CPU experts selected, no disk fallback\n", jobs.size());
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {   // (file order: the disk reads ahead)
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.mx_file[0] != lb.mx_file[0]) return la.mx_file[0] < lb.mx_file[0];
            return la.mx_off[0] + (uint64_t) a.e * la.mx_stride[0] < lb.mx_off[0] + (uint64_t) b.e * lb.mx_stride[0];
        });
        std::atomic<size_t> ji{0};
        std::atomic<bool> bad{false};
        std::atomic<int64_t> done_b{0};
        const bool drop_cache = load_drop_cache();
        std::vector<std::thread> th;
        for (int t = 0; t < 12 && !jobs.empty(); ++t)
            th.emplace_back([&] {
                std::vector<uint8_t> direct_staging;   // thread-local scratch; never aliases NUMA model storage
                for (size_t i; (i = ji.fetch_add(1)) < jobs.size() && !bad.load();) {
                    const Job& j = jobs[i];
                    const Layer& l = L[(size_t) j.layer];
                    for (int r = 0; r < 3; ++r) {
                        const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
                        for (int X = 0; X < NH; ++X) {
                            const uint64_t off = l.mx_off[r] + (uint64_t) j.e * l.mx_stride[r] + (uint64_t) X * nb;
                            auto* dst = ram_part[(size_t) j.slot][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r];
                            const os::fd_t dfd = (size_t) l.mx_file[r] < pk.dfds.size() ? pk.dfds[(size_t) l.mx_file[r]] : os::kBadFd;
                            if (direct_copy && os::copy_direct(dfd, off, nb, dst, direct_staging)) {
                                direct_copy_bytes.fetch_add(nb, std::memory_order_relaxed);
                            } else {
                                if (direct_copy) buffered_fallback_bytes.fetch_add(nb, std::memory_order_relaxed);
                                if (!pk.read_at(l.mx_file[r], off, nb, dst)) bad.store(true);
                            }
                        }
                    }
                    // Both NUMA halves of all three matrices must be copied before releasing any source pages.
                    // Partial edge pages are retained, so adjacent experts/tensors are never discarded by this hint.
                    // (#434's MAYA_DS4_LOAD_DROP_CACHE, on by default, and DS4_COPY_DROP_CACHE=1 both take this release:
                    // without it the pack's copies and their cache held twice reclaim in this thread)
                    if ((drop_copy_cache || drop_cache) && !bad.load()) {
                        uint64_t hinted = 0;
                        for (int r = 0; r < 3; ++r) {
                            const uint64_t nb = (uint64_t) (mx_n(r) / NH) * mx_row_b(l, r) * NH;
                            hinted += os::release_copied_cache(pk.fds[(size_t) l.mx_file[r]],
                                                              l.mx_off[r] + (uint64_t) j.e * l.mx_stride[r], nb);
                        }
                        cache_hint_bytes.fetch_add(hinted, std::memory_order_relaxed);
                    }
                    const int64_t db = done_b.fetch_add((int64_t) l.blob) + (int64_t) l.blob;
                    if (o.verbose && i % 2048 == 0)
                        std::fprintf(stderr, "ds4: copying experts %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(), db / 1e9,
                                     db / 1e6 / std::max(1.0, now_ms() - t0));
                }
            });
        for (auto& t : th) t.join();
        if (bad.load()) {
            err = "copying the CPU lane's experts from the model's files failed";
            return false;
        }
        for (const Job& j : jobs) L[(size_t) j.layer].ram[(size_t) j.e] = j.slot;
        if (direct_copy)
            std::fprintf(stderr, "ds4: expert copy I/O: %.3f GB direct, %.3f GB buffered fallback\n",
                         (double) direct_copy_bytes.load() / 1e9, (double) buffered_fallback_bytes.load() / 1e9);
        if (drop_copy_cache || drop_cache)
            std::fprintf(stderr, "ds4: copied expert cache: DONTNEED hints accepted for %.3f GB of whole source pages (eviction is advisory)\n",
                         (double) cache_hint_bytes.load() / 1e9);
        copy_mode = true;
        ram_held = (int) jobs.size();
        zc_pin();
        cp_pin();
        double cb = 0;
        for (const Job& j : jobs) cb += (double) L[(size_t) j.layer].blob;
        std::fprintf(stderr, "ds4: %zu of the CPU lane's %zu experts copied into RAM (%.1f GB, %d NUMA part%s) in %.1f s%s\n",
                     jobs.size(), hot.size(), cb / 1e9, NH, NH > 1 ? "s" : "", (now_ms() - t0) / 1000.0,
                     jobs.size() < hot.size() ? "; the others read in place" : "");
        return true;
    }

    // the stream lane in place (DS4_STREAM_ZC, on by default): the CPU lane's copies (copy_mode, one part: each copy is
    // its expert's blob, cp_lay the blob's layout) pinned and mapped, so the fetch kernel pulls a streamed pick straight
    // from its copy - no read into the pinned staging first.  A streamed expert then crosses the memory once instead of
    // three times (read, staging write, DMA read) and takes no reader's core from the CPU lane.  (Not the page cache's
    // pages in place: a GeForce pins no read-only mapping - cudaDevAttrHostRegisterReadOnlySupported is 0)
    // STRATA_DS4_PIN_BY_NEED=1 (opt-in): where the system cannot lock every copy - Windows lets a GPU lock about half
    // the RAM - pin them a layer at a time, the layers whose copies the routing profile uses most a byte first, until a
    // pin fails or STRATA_DS4_PIN_GB is reached: those are pulled in place, the others pass the staging.  Without it a
    // failed pin leaves every copy to the staging.  A device that does not address registered memory at its host
    // address (Windows' WDDM) takes its mapped pointer (cudaHostGetDevicePointer, one GPU)
    const bool pin_by_need = env_f("STRATA_DS4_PIN_BY_NEED", 0.0f) != 0.0f;
    const double pin_cap_gb = env_f("STRATA_DS4_PIN_GB", 0.0f);
    std::vector<char> zc_slot;             // ram_part slot -> its copy is pinned (pin by need)
    std::vector<ptrdiff_t> zc_delta;       // ram_part slot -> device address - host address (0: the same)
    bool zc_host_ptr() const {   // (the pinned pages' host addresses are the devices' too)
        for (const Dev& d : devs) {
            int ok = 0;
            if (cudaDeviceGetAttribute(&ok, cudaDevAttrCanUseHostPointerForRegisteredMem, d.id) != cudaSuccess) ok = 0;
            if (!ok) {
                cudaGetLastError();
                return false;
            }
        }
        return true;
    }
    // ln_one and the settings that follow it (see ln_one): Linux + NVIDIA + one discrete GPU in a group of its own and
    // no helper GPU - the setup #476's path was measured on.  Windows, AMD, several GPUs or groups, an integrated GPU or
    // a helper GPU: off, as in v1.1.27 (DS4_STREAM_WIN / DS4_LAND / DS4_STREAM_ZC = 1 turn one on anyway, 0 off)
    static int env_tri(const char* name) {   // -1: not set, else its value != 0
        const char* v = std::getenv(name);
        return v == nullptr || v[0] == '\0' ? -1 : std::atoi(v) != 0;
    }
    // ... and only where the CPU lane's experts actually stream from RAM (#496): it costs VRAM and decode time where
    // nothing streams - a 48 GB L40S beside 28 Xeon threads (an expert 0.13 ms on the CPU lane against 0.77 streamed:
    // 0 of every pick count streamed) decoded 17-19% slower with it.  At the start it is off when the pack's times file
    // says this GPU's PCIe lane streamed nothing at an earlier start (its "lane off") or the lane is off (DS4_STREAM=0);
    // else on until the load's plan (one_gpu_plan, after the lane's timing) finds that nothing streams
    std::string lane_file() const {   // the PCIe lane's times file ("": none)
        const char* cf = std::getenv("DS4_LANE_CAL");
        return cf == nullptr ? o.pack + "/lane-times.txt" : std::string(cf) == "none" ? "" : cf;
    }
    bool one_auto = false;   // the one-GPU path on by default (not by DS4_STREAM_WIN / DS4_LAND): one_gpu_plan may end it
    void one_gpu_path() {
        bool one = false;
        const char* why = "off (v1.1.27's path: not Linux + NVIDIA + one GPU)";
#if !defined(STRATA_USE_HIP) && !defined(_WIN32)
        one = devs.size() == 1 && groups.size() == 1 && groups[0].mem.size() == 1 && helper_id < 0;
        if (one) {
            cudaDeviceProp pr{};
            one = cudaGetDeviceProperties(&pr, devs[0].id) == cudaSuccess && pr.integrated == 0;
            if (!one) (void) cudaGetLastError();
        }
        if (one) {
            why = "on for now (Linux, NVIDIA, one GPU: kept if the PCIe lane's plan streams experts from RAM)";
            const std::string lf = lane_file();
            if (lane_env_off()) {
                one = false;
                why = "off (v1.1.27's path: DS4_STREAM=0, nothing streams)";
            } else if (std::getenv("DS4_STREAM_FORCE") == nullptr && !lf.empty() &&
                       pcie::cal_get(lf, lane_dev_key(0) + " | lane") == "off") {
                one = false;
                why = "off (v1.1.27's path: this GPU's PCIe lane streamed nothing at an earlier start - lane-times.txt "
                      "in the pack; delete it to measure again)";
            }
        }
#endif
        ln_one = one;
        one_auto = one;
        const int w = env_tri("DS4_STREAM_WIN"), d = env_tri("DS4_LAND");
        ln_win = w < 0 ? one : w != 0;
        ln_land = d < 0 ? one : d != 0;
        gg::iq_cpu_iq1s_rows(one);
        if (pk.gguf)
            std::fprintf(stderr, "ds4: the one-GPU decode path (in-place pulls, windows streamed, landings): %s%s%s\n", why,
                         w >= 0 ? (w ? ", DS4_STREAM_WIN=1" : ", DS4_STREAM_WIN=0") : "",
                         d >= 0 ? (d ? ", DS4_LAND=1" : ", DS4_LAND=0") : "");
    }
    // after the PCIe lane's timing (lane_setup): the one-GPU path on by default stays on only if some layer streams
    // CPU-lane experts; else v1.1.27's path for the run - the copies' pins given back (the VRAM it placed experts
    // around stays as placed until the next start, which the times file then starts on v1.1.27's path)
    void one_gpu_plan() {
        if (!one_auto) return;
        bool streams = false;
        for (int c : ln_layer) streams = streams || c >= 0;
        const bool hold = lane_env() != nullptr && std::atoi(lane_env()) == 2;   // (DS4_STREAM=2, tests: as it was)
        if (streams || hold || std::getenv("DS4_STREAM_FORCE") != nullptr) {
            if (pk.gguf)
                std::fprintf(stderr, "ds4: the one-GPU decode path: on - the PCIe lane streams CPU-lane experts from "
                                     "RAM on this GPU\n");
            return;
        }
        ln_one = false;
        one_auto = false;
        if (env_tri("DS4_STREAM_WIN") < 0) ln_win = false;
        if (env_tri("DS4_LAND") < 0) ln_land = false;
        gg::iq_cpu_iq1s_rows(false);
        double gb = 0;
        if (ln_zc && env_tri("DS4_STREAM_ZC") < 0) {   // (nothing pulls them: the RAM unlocked again)
            for (size_t c = 0; c < zc_chunk.size() && c < ram_chunks.size(); ++c)
                if (zc_chunk[c]) {
                    cudaHostUnregister(ram_chunks[c]);
                    zc_chunk[c] = 0;
                    gb += (double) ram_chunk_bytes[c] / 1e9;
                }
            cudaGetLastError();
            std::fill(zc_slot.begin(), zc_slot.end(), 0);
            ln_zc = false;
        }
        if (pk.gguf)
            std::fprintf(stderr, "ds4: the one-GPU decode path: off - the PCIe lane's plan streams nothing on this GPU "
                                 "(its CPU lane is as fast or there is no lane); v1.1.27's path%s\n",
                         gb > 0 ? " (the copies' pins given back)" : "");
    }
    bool zc_allowed() const {
        const char* v = std::getenv("DS4_STREAM_ZC");
        if ((v != nullptr && std::atoi(v) == 0) || lane_env_off() || !pk.gguf) return false;
        // (off the one-GPU path: only when asked - DS4_STREAM_ZC=1, or MAYA_DS4_PIN_BY_NEED's own opt-in)
        if (!ln_one && v == nullptr && !pin_by_need) return false;
        for (const LaneDev& D : ln_dev)   // (an integrated GPU's kernels may read the staging in place: theirs)
            if (D.integrated) return false;
        return zc_host_ptr() || (pin_by_need && devs.size() == 1);
    }
    void zc_pin() {   // (copy_mode)
        if (NH != 1 || ram_chunks.empty() || !zc_allowed()) return;
        const double t0 = now_ms();
        const size_t nc = ram_chunks.size();
        // each chunk's need a byte: its copies' routes in the profile (pin by need's order; else file order)
        std::vector<size_t> order(nc);
        for (size_t c = 0; c < nc; ++c) order[c] = c;
        std::vector<int> chunk_of(ram_part.size(), -1);
        for (size_t sl = 0; sl < ram_part.size(); ++sl)
            for (size_t c = 0; c < nc; ++c)
                if (ram_part[sl][0] >= ram_chunks[c] && ram_part[sl][0] < ram_chunks[c] + ram_chunk_bytes[c]) {
                    chunk_of[sl] = (int) c;
                    break;
                }
        if (pin_by_need) {
            std::vector<double> need(nc, 0.0);
            for (const Layer& l : L)
                for (int e = 0; e < l.n_exp && !l.ram.empty(); ++e)
                    if (l.ram[(size_t) e] >= 0 && chunk_of[(size_t) l.ram[(size_t) e]] >= 0)
                        need[(size_t) chunk_of[(size_t) l.ram[(size_t) e]]] += (double) prof[(size_t) l.il * g.n_exp + e];
            std::stable_sort(order.begin(), order.end(), [&](size_t x, size_t y) {
                return need[x] / (double) ram_chunk_bytes[x] > need[y] / (double) ram_chunk_bytes[y];
            });
        }
        std::vector<char> done(nc, 0);
        if (pin_by_need) {   // (in order, until one fails or the cap: one at a time)
            double gb = 0;
            for (size_t k = 0; k < nc; ++k) {
                const size_t c = order[k];
                if (pin_cap_gb > 0 && gb + (double) ram_chunk_bytes[c] / 1e9 > pin_cap_gb) break;
                if (cudaHostRegister(ram_chunks[c], ram_chunk_bytes[c], cudaHostRegisterPortable | cudaHostRegisterMapped) !=
                    cudaSuccess) {
                    cudaGetLastError();
                    break;
                }
                done[c] = 1;
                gb += (double) ram_chunk_bytes[c] / 1e9;
            }
        } else {
            // (a few threads: pinning is the kernel's walk of the pages, ~0.6 GB/s a thread)
            std::atomic<size_t> next{0};
            std::vector<std::thread> th;
            for (int t = 0; t < 8; ++t)
                th.emplace_back([&] {
                    for (size_t c; (c = next.fetch_add(1)) < nc;)
                        done[c] = cudaHostRegister(ram_chunks[c], ram_chunk_bytes[c],
                                                   cudaHostRegisterPortable | cudaHostRegisterMapped) == cudaSuccess;
                });
            for (auto& t : th) t.join();
            if (std::find(done.begin(), done.end(), 0) != done.end()) {
                cudaGetLastError();
                for (size_t c = 0; c < nc; ++c)
                    if (done[c]) cudaHostUnregister(ram_chunks[c]);
                std::fprintf(stderr, "ds4: PCIe lane: pinning the copied experts failed - streamed ones pass the staging "
                                     "(STRATA_DS4_PIN_BY_NEED=1 pins the ones it can)\n");
                return;
            }
        }
        const bool same = zc_host_ptr();
        zc_slot.assign(ram_part.size(), 0);
        zc_delta.assign(ram_part.size(), 0);
        std::vector<ptrdiff_t> cdelta(nc, 0);
        for (size_t c = 0; c < nc; ++c) {
            if (!done[c] || same) continue;
            void* dp = nullptr;
            if (cudaHostGetDevicePointer(&dp, ram_chunks[c], 0) != cudaSuccess || dp == nullptr) {
                cudaGetLastError();
                cudaHostUnregister(ram_chunks[c]);
                done[c] = 0;
                continue;
            }
            cdelta[c] = (uint8_t*) dp - ram_chunks[c];
        }
        double gb = 0, all = 0;
        for (size_t c = 0; c < nc; ++c) {
            all += (double) ram_chunk_bytes[c] / 1e9;
            if (done[c]) gb += (double) ram_chunk_bytes[c] / 1e9;
        }
        for (size_t sl = 0; sl < ram_part.size(); ++sl)
            if (chunk_of[sl] >= 0 && done[(size_t) chunk_of[sl]]) {
                zc_slot[sl] = 1;
                zc_delta[sl] = cdelta[(size_t) chunk_of[sl]];
            }
        zc_chunk = std::move(done);
        ln_zc = gb > 0;
        if (pin_by_need)
            std::fprintf(stderr, "ds4: PCIe lane: pin by need: %.1f of the copies' %.1f GB pinned, the most-used layers first "
                                 "(%.1f s): those pulled in place, the rest through the staging\n", gb, all,
                         (now_ms() - t0) / 1000.0);
        else
            std::fprintf(stderr, "ds4: PCIe lane: the copied experts pinned (%.1f GB in %.1f s): streamed ones pulled in "
                                 "place\n", gb, (now_ms() - t0) / 1000.0);
    }
    std::vector<char> zc_chunk;   // ram_chunks -> pinned (zc_pin, cp_pin)
    // the prompt path's copies in place (copy_mode, prompts in chunks): every chunk of the CPU lane's copies pinned, so
    // copy_ahead DMAs a streamed expert straight from its copy (copy_in_place) - the CPU gathers only a group member's
    // blocks of the down - where the readers staged every byte of it before: ~490 GB of copies for a 16K prompt at
    // tp 8 (orcarouter's Mix-256G), the 72 readers ~33 GB/s together, the prompt's limit (nsys: each member's thread
    // staging ~20 of 38 s).  All or none (DS4_COPY_PIN=0: none - the staging, as before); zc_pin's chunks count
    bool cp_dma = false;
    void cp_pin() {
        if (!copy_mode || chunk <= 0 || ram_chunks.empty()) return;
        if (const char* v = std::getenv("DS4_COPY_PIN"); v != nullptr && std::atoi(v) == 0) return;
        const double t0 = now_ms();
        const size_t nc = ram_chunks.size();
        zc_chunk.resize(nc, 0);
        std::vector<char> mine(nc, 0);   // (1: this call pinned it, 2: it failed)
        std::atomic<size_t> next{0};
        std::vector<std::thread> th;
        for (int t = 0; t < 8; ++t)   // (pinning is the kernel's walk of the pages, ~0.6 GB/s a thread)
            th.emplace_back([&] {
                for (size_t c; (c = next.fetch_add(1)) < nc;)
                    if (!zc_chunk[c])
                        mine[c] = cudaHostRegister(ram_chunks[c], ram_chunk_bytes[c], cudaHostRegisterPortable) == cudaSuccess
                                      ? 1 : 2;
            });
        for (auto& t : th) t.join();
        double gb = 0;
        bool all = true;
        for (size_t c = 0; c < nc; ++c) {
            all = all && (zc_chunk[c] || mine[c] == 1);
            gb += (double) ram_chunk_bytes[c] / 1e9;
        }
        if (!all) {
            cudaGetLastError();
            for (size_t c = 0; c < nc; ++c)
                if (mine[c] == 1) cudaHostUnregister(ram_chunks[c]);
            std::fprintf(stderr, "ds4: pinning the copied experts (%.1f GB) failed - the prompt path stages them as before\n", gb);
            return;
        }
        for (size_t c = 0; c < nc; ++c)
            if (mine[c] == 1) zc_chunk[c] = 1;
        cp_dma = true;
        std::fprintf(stderr, "ds4: the copied experts pinned (%.1f GB in %.1f s): the prompt path DMAs them in place\n", gb,
                     (now_ms() - t0) / 1000.0);
    }
    bool zc_ok(const Layer& l, int e) const {   // expert e pulled in place: it has a pinned copy
        if (!ln_zc || l.ram.empty() || l.ram[(size_t) e] < 0) return false;
        return zc_slot[(size_t) l.ram[(size_t) e]] != 0;
    }
    bool zc_layer_full(const Layer& l) const {
        // The device decides before the service thread returns this route's mask, so route-local coverage is not enough.
        // Every possible non-VRAM pick must have a pinned source and no other producer/skip rule may be involved.
        if (!ln_zc_all_live || !ln_zc_nowait || tok_ab_off.load() || l.nm != 1 || l.mtp ||
            l.helper_tab != nullptr || disk_skip_w > 0.0f || ram_skip_w > 0.0f)
            return false;
        for (int e = 0; e < l.n_exp; ++e)
            if (l.slot[(size_t) e] < 0 && !zc_ok(l, e)) return false;
        return true;
    }
    const uint8_t* zc_mat(const Layer& l, int e, int r) const {   // (zc_ok) its matrix r as the devices address it
        const int sl = l.ram[(size_t) e];
        return ram_part[(size_t) sl][0] + cp_lay[(size_t) l.il][(size_t) r] + zc_delta[(size_t) sl];
    }

    bool load_experts(std::string& err) {
        if (!L.empty() && L[0].lay.fmt == gg::kFmtMXFP4) return load_experts_mx(err);
        const bool drop_cache = load_drop_cache();
        // every expert's region, in file order, by a few threads; VRAM ones through a pinned staging blob.  In place
        // (file_experts) the CPU lane's experts are not copied: the most-routed of them (the profile's share of their
        // layer) are read once, up to warm_bytes, so the page cache starts with them, and the VRAM ones' pages are
        // dropped from it again
        struct Job {
            int layer, e;
        };
        std::vector<Job> jobs;
        for (const Layer& l : L)
            for (int e = 0; e < l.n_exp; ++e)
                if (!file_experts || l.slot[(size_t) e] >= 0) jobs.push_back({l.il, e});
        uint64_t warm = 0;
        if (file_experts) {
            std::vector<std::pair<double, Job>> cand;
            for (const Layer& l : L) {
                const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
                double sum = 0;
                for (int e = 0; e < l.n_exp; ++e) sum += p[e];
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) cand.push_back({sum > 0 ? p[e] / sum : 0.0, Job{l.il, e}});
            }
            std::stable_sort(cand.begin(), cand.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
            for (const auto& c : cand) {
                const uint64_t b = L[(size_t) c.second.layer].region_bytes[(size_t) c.second.e];
                if (warm + b > warm_bytes) break;
                warm += b;
                jobs.push_back(c.second);
            }
        }
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.region_file[(size_t) a.e] != lb.region_file[(size_t) b.e])
                return la.region_file[(size_t) a.e] < lb.region_file[(size_t) b.e];
            return la.region_off[(size_t) a.e] < lb.region_off[(size_t) b.e];
        });
        // STRATA_DS4_LOAD_INTERLEAVE (0): 1 = the files round-robin - the first expert of each file, then the second,
        // ... - so the threads read several files at once (a pack split over two drives streams both).  0: file by
        // file, as before.
        if (const char* iv = std::getenv("STRATA_DS4_LOAD_INTERLEAVE"); iv != nullptr && std::atoi(iv) != 0) {
            std::vector<int> rank(jobs.size());
            int cur = -1, r = 0;
            for (size_t i = 0; i < jobs.size(); ++i) {
                const int f = L[(size_t) jobs[i].layer].region_file[(size_t) jobs[i].e];
                if (f != cur) { cur = f; r = 0; }
                rank[i] = r++;
            }
            std::vector<size_t> idx(jobs.size());
            for (size_t i = 0; i < idx.size(); ++i) idx[i] = i;
            std::sort(idx.begin(), idx.end(), [&](size_t a, size_t b) {
                if (rank[a] != rank[b]) return rank[a] < rank[b];
                return L[(size_t) jobs[a].layer].region_file[(size_t) jobs[a].e] <
                       L[(size_t) jobs[b].layer].region_file[(size_t) jobs[b].e];
            });
            std::vector<Job> sorted;
            sorted.reserve(jobs.size());
            for (size_t i : idx) sorted.push_back(jobs[i]);
            jobs.swap(sorted);
        }
        std::atomic<size_t> next{0};
        std::atomic<bool> failed{false};
        std::mutex emu;
        std::string ferr;
        // STRATA_DS4_LOAD_THREADS (12): the threads that read the experts' regions.
        const char* ntv = std::getenv("STRATA_DS4_LOAD_THREADS");
        const int nth = std::max(1, ntv != nullptr ? std::atoi(ntv) : 12);
        size_t maxr = 0, maxb = 0;
        for (const Layer& l : L) {
            maxb = std::max(maxb, l.blob);
            for (uint64_t r : l.region_bytes) maxr = std::max<size_t>(maxr, r);
        }
        std::atomic<int64_t> done_bytes{0};
        const double t0 = now_ms();
        if (o.verbose)
            std::fprintf(stderr, "ds4: loading %zu experts (regions up to %.1f MB, blobs up to %.1f MB)\n", jobs.size(),
                         maxr / 1e6, maxb / 1e6);
        std::vector<std::thread> th;
        for (int t = 0; t < nth; ++t)
            th.emplace_back([&] {
                std::vector<uint8_t> region(maxr);
                uint8_t *stage = nullptr, *stage2 = nullptr;
                cudaHostAlloc((void**) &stage, maxb, cudaHostAllocPortable);
                cudaHostAlloc((void**) &stage2, maxb, cudaHostAllocPortable);
                int cur_dev = -1;
                for (;;) {
                    const size_t i = next.fetch_add(1);
                    if (i >= jobs.size() || failed.load()) break;
                    const Layer& l = L[(size_t) jobs[i].layer];
                    const int e = jobs[i].e;
                    if (!(e < (int) l.esplit.size() && l.esplit[(size_t) e]
                              ? read_split(l, e, region.data())
                              : pk.read_at(l.region_file[(size_t) e], l.region_off[(size_t) e], l.region_bytes[(size_t) e],
                                           region.data()))) {
                        std::lock_guard<std::mutex> lk(emu);
                        ferr = "reading layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
                        failed.store(true);
                        break;
                    }
                    if (l.slot[(size_t) e] >= 0) {
                        repack(l, e, region.data(), stage);
                        bool up = true;
                        for (int m = 0; m < l.nm && up; ++m) {   // (a group: each member its part)
                            const Layer& x = member(l, m);
                            const Dev& d = devs[(size_t) x.dev];
                            if (cur_dev != d.id) {
                                cudaSetDevice(d.id);
                                cur_dev = d.id;
                            }
                            if (l.nm > 1) blob_to_half(l, stage, m, stage2);
                            up = cudaMemcpy(sat(l, x, l.slot[(size_t) e], unit(x)), l.nm > 1 ? stage2 : stage,
                                            slot_bytes(l, x, l.slot[(size_t) e]), cudaMemcpyHostToDevice) == cudaSuccess;
                        }
                        if (!up) {
                            std::lock_guard<std::mutex> lk(emu);
                            ferr = "uploading layer " + std::to_string(l.il) + " expert " + std::to_string(e);
                            failed.store(true);
                            break;
                        }
                        if (drop_cache)
                            os::advise(pk.fds[(size_t) l.region_file[(size_t) e]], l.region_off[(size_t) e], l.region_bytes[(size_t) e], false);
                    } else if (!file_experts) {
                        for (int X = 0; X < NH; ++X) repack_part(l, region.data(), X, l.hh[(size_t) e][(size_t) X]);
                        // copied into RAM: the pages are dead.  In place (file_experts) the CPU lane's experts *are*
                        // the cache, and only the VRAM ones' pages go, as they already did.
                        if (drop_cache && (e >= (int) l.esplit.size() || !l.esplit[(size_t) e]))
                            os::advise(pk.fds[(size_t) l.region_file[(size_t) e]], l.region_off[(size_t) e],
                                       l.region_bytes[(size_t) e], false);
                    }
                    const int64_t db = done_bytes.fetch_add((int64_t) l.region_bytes[(size_t) e]) +
                                       (int64_t) l.region_bytes[(size_t) e];
                    if (o.verbose && (i % 1024) == 0)
                        std::fprintf(stderr, "ds4: experts %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(),
                                     db / 1e9, db / 1e6 / std::max(1.0, now_ms() - t0));
                }
                if (stage) cudaFreeHost(stage);
                if (stage2) cudaFreeHost(stage2);
            });
        for (auto& t : th) t.join();
        if (failed.load()) {
            err = ferr;
            return false;
        }
        if (file_experts)
            std::fprintf(stderr, "ds4: experts loaded in %.1f s (%.1f GB of the CPU lane's read ahead)\n",
                         (now_ms() - t0) / 1000.0, warm / 1e9);
        return true;
    }

    std::string describe() const {
        std::ostringstream s;
        if (!abl_what.empty()) s << abl_what << "\n";
        for (size_t di = 0; di < devs.size(); ++di) {
            const Dev& d = devs[di];
            int a = -1, b = -1, ev = 0, et = 0;
            for (const Layer& l : L)
                for (int m = 0; m < l.nm; ++m)
                    if (member(l, m).dev == (int) di) {
                        if (a < 0) a = l.il;
                        b = l.il;
                        ev += l.n_vram;
                        et += l.n_exp;
                    }
            size_t fr = 0, tot = 0;
            cudaSetDevice(d.id);
            mem_info(&fr, &tot);
            const size_t gsz = groups.empty() ? 1 : groups[(size_t) d.grp].mem.size();
            char tp[64] = "";
            if (gsz > 1) std::snprintf(tp, sizeof tp, " (tensor parallel %zu, part %d)", gsz, d.mi);
            char dr[48] = "";   // (DS4_DRAFT_DEV: the DSpark blocks this device holds)
            for (int i = 0; i < g.n_mtp && !draft_dev.empty(); ++i)
                if (L[(size_t) (g.nl + i)].dev == (int) di)
                    std::snprintf(dr + std::strlen(dr), sizeof dr - std::strlen(dr), "%s%d", *dr ? "," : " + blocks ", i);
            if (dense_req_n > 0 && d.id == devs[0].id)
                std::fprintf(stderr, "ds4: MAYA_DS4_DENSE_REQ: %d dense matrices re-quantized (%d from the pack's cache), %.2f GB "
                                     "fewer, %.1f s\n",
                             dense_req_n, dense_req_cached, dense_req_saved / 1e9, dense_req_ms / 1000.0);
            char line[384];
            std::snprintf(line, sizeof line,
                          "ds4: CUDA%d layers [%d, %d]%s%s%s: weights %.2f GB, experts %.2f GB (%d of %d in VRAM), caches "
                          "%.2f GB, %.0f MiB free\n",
                          d.id, a, b, tp, (int) di == head_dev ? " + head" : "", dr, d.weights / 1e9, d.experts / 1e9, ev, et,
                          d.caches / 1e9, fr / 1048576.0);
            s << line;
        }
        int nh = 0;
        size_t hb_ = 0;
        for (const Layer& l : L) {
            nh += l.n_exp - l.n_vram;
            hb_ += (size_t) (l.n_exp - l.n_vram) * l.blob;
        }
        char line[200];
        if (copy_mode)
            std::snprintf(line, sizeof line, "ds4: %d routed experts on the CPU lane (%.1f GB): %d copied into RAM (%d NUMA "
                                             "parts), the rest in place in the model's files; %d threads\n",
                          nh, hb_ / 1e9, ram_held, NH, cpu_threads());
        else if (file_experts)
            std::snprintf(line, sizeof line,
                          "ds4: %d routed experts on the CPU lane (%.1f GB, in place in the model's files), %d threads\n",
                          nh, hb_ / 1e9, cpu_threads());
        else
            std::snprintf(line, sizeof line, "ds4: %d routed experts on the CPU lane (%.1f GB of RAM, %d NUMA parts), %d threads\n", nh,
                          hb_ / 1e9, NH, cpu_threads());
        s << line;
        return s.str();
    }

    int cpu_threads() const {
        int n = 0;
        for (const auto& pl : pools) n += pl->size() - 1;
        return n + 1;
    }
    // The ways this host's CPUs can serve the CPU lane (tune_lane times them at load and keeps the fastest): a CPU list
    // per part X - NH of them, part X's pool on node X; in place with one part, one pool over every node's cores (the
    // pages lie where the cache put them) - in the order its workers take them.  The service thread (pinned to node 0's
    // first core) helps part 0's pool in place of a worker there.
    //   cores   a thread a physical core (as before; with --cpu-threads n, at most n)
    //   pcores  the performance cores alone (a hybrid CPU: Intel's P- and E-cores)
    //   node    node 0's cores alone (in place on two NUMA nodes or more: one pool spinning on both sockets syncs
    //           across them - GLM's lane on a 2-socket Xeon: 531 us an expert on 88 threads, 216 on one socket's 44)
    //   smt     a thread a logical CPU: every core's first CPU, then their siblings (a CPU with SMT) - by hand only
    //           (STRATA_DS4_CPU_LANE=smt), never measured: the lane's calls time the same on a core's two CPUs as on
    //           one (i5-12600T 1.84 / 1.86 ms, Ryzen AI Max+ 395 0.62 / 0.63), while decoding with the siblings busy
    //           was no faster and once slower - the siblings are left to the readers, as GLM's lane leaves them
    struct LaneCfg {
        std::string name;
        std::vector<std::vector<int>> cpus;
        bool measured = true;   // (tune_lane times it; false: by hand only)
    };
    std::vector<LaneCfg> lane_cfgs() const {
        std::vector<std::vector<os::Core>> parts = core_threads;
        if ((int) parts.size() < NH && !parts.empty()) {   // (DS4_COPY_NUMA=2 on one node, a test: its cores split in NH)
            std::vector<os::Core> all = parts[0];
            parts.assign((size_t) NH, {});
            for (size_t i = 0; i < all.size(); ++i) parts[i * (size_t) NH / all.size()].push_back(all[i]);
        }
        const bool one_over_all = file_experts && NH == 1 && parts.size() > 1;
        if (one_over_all)
            for (size_t Y = 1; Y < parts.size(); ++Y) parts[0].insert(parts[0].end(), parts[Y].begin(), parts[Y].end());
        parts.resize((size_t) std::max(1, std::min((int) parts.size(), std::max(NH, 1))));
        // a configuration from each part's cores that `keep` takes: their first CPUs, then (smt) their second ones, ..
        auto make = [&](const std::string& name, bool smt, const std::function<bool(const os::Core&)>& keep) {
            LaneCfg c;
            c.name = name;
            for (const auto& p : parts) {
                std::vector<int> v;
                for (size_t k = 0; k < (smt ? 4u : 1u); ++k)
                    for (const os::Core& co : p)
                        if (keep(co) && k < co.cpus.size()) v.push_back(co.cpus[k]);
                c.cpus.push_back(v);
            }
            return c;
        };
        std::vector<LaneCfg> out = {make("cores", false, [](const os::Core&) { return true; })};
        bool smt = false, mixed = false;
        int top = 0;
        for (const auto& p : parts)
            for (const os::Core& co : p) {
                smt = smt || co.cpus.size() > 1;
                top = std::max(top, co.eff);
            }
        for (const auto& p : parts)
            for (const os::Core& co : p) mixed = mixed || co.eff != top;
        if (smt) {
            out.push_back(make("smt", true, [](const os::Core&) { return true; }));
            out.back().measured = false;
        }
        if (mixed) out.push_back(make("pcores", false, [top](const os::Core& co) { return co.eff == top; }));
        if (one_over_all && !core_threads.empty()) {
            LaneCfg c;
            c.name = "node";
            c.cpus.emplace_back();
            for (const os::Core& co : core_threads[0]) c.cpus[0].push_back(co.cpus[0]);
            out.push_back(c);
        }
        return out;
    }
    // the CPU lane's workers' idle spin before they sleep on their pool's condition variable, us: by default 20 ms,
    // through a token's layers; DS4_LANE_SPIN_US=<us> another - a whole number 0 .. 1000000, its digits only (no sign,
    // no spaces), else the default (bad: set, not such a number).  A spin keeps every worker's core busy between the
    // layers that hand the lane experts - on a die the CPU shares with a GPU (an APU) that heat and power can clock
    // down the lane and the GPU; a short spin sleeps them, a layer then wakes them.  No output changes: every row is
    // one job's sum, whichever thread runs it, whenever it wakes
    static int lane_spin_us(bool* bad = nullptr) {
        const char* v = ds4_env("DS4_LANE_SPIN_US");
        const size_t len = v == nullptr ? 0 : std::strlen(v);
        bool ok = len >= 1 && len <= 7;
        long n = 0;
        for (size_t i = 0; ok && i < len; ++i) {
            ok = v[i] >= '0' && v[i] <= '9';
            n = n * 10 + (v[i] - '0');
        }
        ok = ok && n <= 1000000;
        if (bad != nullptr) *bad = v != nullptr && !ok;
        return ok ? (int) n : 20000;
    }
    std::vector<std::unique_ptr<Pool>> pools_for(const LaneCfg& c) const {
        std::vector<std::unique_ptr<Pool>> out;
        const int svc = !cores.empty() && !cores[0].empty() ? cores[0][0] : -1;
        // cores of the first part left free beside the service thread's, for the thread that launches the decode's
        // kernels (and waits on the device) and whatever else the PC runs.  With every other core a worker spinning
        // between a token's layers - 19 on a 20-core Core Ultra 7 265K, Windows 11 - that thread waited for a core:
        // decode 28.3 tok/s, the device waiting 21.4 ms a token for the lane; 18 workers 47.2, 17 workers 55.5.
        // MAYA_DS4_LANE_FREE (a config's env reaches the engine as STRATA_DS4_LANE_FREE; DS4_LANE_FREE for tests): the
        // cores left free (2 by default, 0: as before).  Only where the lane would take every logical CPU: with SMT the
        // lane runs a thread a core and the siblings are free already - there leaving cores out cost decode (#394: a
        // 16-core Threadripper, 16 threads 50.6 tok/s against 14 threads 45.9)
        static const int spare_cores = [] {
            const char* v = std::getenv("STRATA_DS4_LANE_FREE");
            if (v == nullptr) v = std::getenv("MAYA_DS4_LANE_FREE");
            if (v == nullptr) v = std::getenv("DS4_LANE_FREE");
            return v != nullptr ? std::max(0, std::atoi(v)) : 2;
        }();
        size_t logical = 0, used = 0;
        for (const auto& p : core_threads)
            for (const os::Core& co : p) logical += co.cpus.size();
        for (const auto& v : c.cpus) used += v.size();
        const bool leaves_none = logical == 0 || logical - std::min(logical, used) < (size_t) spare_cores + 1;
        for (size_t X = 0; X < c.cpus.size(); ++X) {
            std::vector<int> v = c.cpus[X];
            if (X == 0) v.erase(std::remove(v.begin(), v.end(), svc), v.end());   // (the service thread's)
            if (X == 0 && o.cpu_threads <= 0 && leaves_none && (int) v.size() > spare_cores + 1)
                v.resize(v.size() - (size_t) spare_cores);
            int nw = (int) v.size();
            if (o.cpu_threads > 0) nw = std::max(X == 0 ? 0 : 1, std::min(nw, o.cpu_threads / NH - (X == 0 ? 1 : 0)));
            out.push_back(std::make_unique<Pool>(nw, v, lane_spin_us()));
        }
        return out;
    }
    // the CPU lane's workers: lane_cfgs' first (cores), or the one STRATA_DS4_CPU_LANE=<name> asks for; tune_lane may
    // change them once the experts are placed
    void make_pools() {
        const std::vector<LaneCfg> cfgs = lane_cfgs();
        size_t pick = 0;
        if (const char* v = std::getenv("STRATA_DS4_CPU_LANE"))
            for (size_t i = 0; i < cfgs.size(); ++i)
                if (cfgs[i].name == v) pick = i;
        lane_name = cfgs[pick].name;
        pools = pools_for(cfgs[pick]);
        bool spin_bad = false;
        const int spin = lane_spin_us(&spin_bad);
        if (spin_bad)
            std::fprintf(stderr, "ds4: CPU lane: DS4_LANE_SPIN_US=%s is not a whole number of us 0 .. 1000000 - "
                                 "ignored, its workers spin %d us idle\n", ds4_env("DS4_LANE_SPIN_US"), spin);
        else if (ds4_env("DS4_LANE_SPIN_US") != nullptr)
            std::fprintf(stderr, "ds4: CPU lane: its workers spin %d us idle before they sleep (DS4_LANE_SPIN_US)\n",
                         spin);
        (void) gg::mx_tier();   // (measured here, not on the first token)
        if (o.verbose) {
            int nthr = 0;
            for (auto& p : pools) nthr += p->size();
            std::fprintf(stderr, "ds4: CPU lane: %d threads, MXFP4 rows %s (%s)\n", nthr, gg::mx_tier_name(gg::mx_tier()),
                         gg::mx_tier_report());
        }
    }
    // The CPU lane's configuration measured on this host, once its experts are placed: each of lane_cfgs() times the
    // same calls - 4 CPU-lane experts of one token, as a decode step's layer hands the lane, going round 24 experts of
    // one layer so the weights come from RAM and not from the CPU's caches (read once first: the page cache or the
    // copies) - on the service thread's CPU, in rounds taken in turns (other work on the host hits them alike), each
    // round's median, the best round kept (interference only adds time).  Another configuration replaces the cores'
    // only when it is faster by more than kLaneGain.  The choice changes no output - every row is one job's sum,
    // whichever thread runs it - only the speed.  Not with --cpu-threads or STRATA_DS4_CPU_LANE=<name> (the one asked
    // for), nor with fewer than 8 experts on the lane in any layer.
    static constexpr double kLaneGain = 0.05;
    void tune_lane() {
        if (o.cpu_threads > 0 || std::getenv("STRATA_DS4_CPU_LANE") != nullptr || pools.empty()) return;
        std::vector<LaneCfg> cfgs = lane_cfgs();
        cfgs.erase(std::remove_if(cfgs.begin(), cfgs.end(), [](const LaneCfg& c) { return !c.measured; }), cfgs.end());
        if (cfgs.size() < 2) return;   // (one way on this host: nothing to measure)
        constexpr int kPer = 4, kSets = 6, kRounds = 5, kCalls = 8;
        int il = -1, most = 0;
        for (int i = 0; i < g.nl; ++i) {
            int n = 0;
            for (int e = 0; e < L[(size_t) i].n_exp; ++e) n += L[(size_t) i].slot[(size_t) e] < 0;
            if (n > most) most = n, il = i;
        }
        if (il < 0 || most < 2 * kPer) return;
        const Layer& l = L[(size_t) il];
        std::vector<std::vector<Ent>> sets;
        for (int e = 0, k = 0; e < l.n_exp && (int) sets.size() < kSets; ++e) {
            if (l.slot[(size_t) e] >= 0) continue;
            if (k % kPer == 0) sets.emplace_back();
            Ent en;
            en.e = e;
            en.n = 1;
            en.slot0 = k % kPer;
            en.tok[0] = 0;
            sets.back().push_back(en);
            ++k;
        }
        if ((int) sets.back().size() < kPer) sets.pop_back();
        if (sets.size() < 2) return;
        std::vector<float> x((size_t) g.dim);
        for (size_t i = 0; i < x.size(); ++i) x[i] = 0.02f * std::sin(0.37f * (float) i);
        size_t cur = 0;
        for (size_t i = 0; i < cfgs.size(); ++i)
            if (cfgs[i].name == lane_name) cur = i;
        std::vector<std::vector<std::unique_ptr<Pool>>> cand(cfgs.size());
        for (size_t i = 0; i < cfgs.size(); ++i)
            if (i != cur) cand[i] = pools_for(cfgs[i]);
        std::vector<double> best(cfgs.size(), 1e30);
        const int svc = !cores.empty() && !cores[0].empty() ? cores[0][0] : -1;
        std::thread th([&] {
            if (svc >= 0) pin_self(svc);
            size_t set = 0;
            auto call = [&] { cpu_experts(l, x.data(), sets[set++ % sets.size()], (size_t) g.dim); };
            auto busy = [&](double ms) {
                for (const double t0 = now_ms(); now_ms() - t0 < ms;) call();
            };
            for (size_t s = 0; s < sets.size(); ++s) call();   // (the experts' pages read in)
            busy(100);
            for (int r = 0; r < kRounds; ++r)
                for (size_t j = 0; j < cfgs.size(); ++j) {
                    const size_t i = (j + (size_t) r) % cfgs.size();
                    // (the last one's workers asleep first: they spin 20 ms after their last job)
                    std::this_thread::sleep_for(std::chrono::milliseconds(25));
                    if (i != cur) pools.swap(cand[i]);
                    busy(30);
                    std::array<double, kCalls> t{};
                    for (int c = 0; c < kCalls; ++c) {
                        const double a = now_ms();
                        call();
                        t[(size_t) c] = now_ms() - a;
                    }
                    if (i != cur) pools.swap(cand[i]);
                    std::sort(t.begin(), t.end());
                    best[i] = std::min(best[i], 0.5 * (t[kCalls / 2 - 1] + t[kCalls / 2]));
                }
        });
        th.join();
        size_t pick = cur;
        for (size_t i = 0; i < cfgs.size(); ++i)
            if (best[i] < best[pick]) pick = i;
        if (pick != cur && best[pick] > best[cur] * (1.0 - kLaneGain)) pick = cur;
        lane_report.clear();
        for (size_t i = 0; i < cfgs.size(); ++i) {
            char b[64];
            std::snprintf(b, sizeof b, "%s%s %.2f ms", i ? ", " : "", cfgs[i].name.c_str(), best[i]);
            lane_report += b;
        }
        if (pick != cur) {
            pools.swap(cand[pick]);
            lane_name = cfgs[pick].name;
        }
        cand.clear();   // (the others' workers stopped)
        std::fprintf(stderr, "ds4: CPU lane: %s, %d threads (measured, %d experts of one token a call: %s)\n",
                     lane_name.c_str(), cpu_threads(), kPer, lane_report.c_str());
    }

    void reset() {
        pos = 0;
        toks.clear();
        ctoks.clear();
        slot_held = false;
        ck[0].pos = ck[1].pos = ck[2].pos = -1;
        for (Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m) {
                Layer& l = member(l0, m);
                Dev& d = devs[(size_t) l.dev];
                cudaSetDevice(d.id);
                cudaMemsetAsync(l.win, 0, (size_t) g.win * win_rb(), d.st);
                if (l.c_kv) cudaMemsetAsync(l.c_kv, 0, (size_t) l.ratio * g.hd * 4, d.st);
                if (l.c_score) cudaMemsetAsync(l.c_score, 0, (size_t) l.ratio * g.hd * 4, d.st);
            }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
    }

    // the state at pos into checkpoint `slot` (the window rings and the compressors' partial groups: the rest of the
    // state is indexed by position, and what lies past a restored position is written again)
    void checkpoint(int slot) {
        Check& c = ck[slot & 1];
        c.pos = pos;
        c.win.resize(L.size());
        c.comp.resize(L.size() * 2);
        for (size_t i = 0; i < L.size(); ++i) {
            Layer& l = L[i];
            Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            c.win[i].resize((size_t) g.win * win_rb());
            cudaMemcpyAsync(c.win[i].data(), l.win, c.win[i].size(), cudaMemcpyDeviceToHost, d.st);
            if (l.c_kv) {
                c.comp[2 * i].resize((size_t) l.ratio * g.hd);
                c.comp[2 * i + 1].resize((size_t) l.ratio * g.hd);
                cudaMemcpyAsync(c.comp[2 * i].data(), l.c_kv, c.comp[2 * i].size() * 4, cudaMemcpyDeviceToHost, d.st);
                cudaMemcpyAsync(c.comp[2 * i + 1].data(), l.c_score, c.comp[2 * i + 1].size() * 4,
                                cudaMemcpyDeviceToHost, d.st);
            }
        }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
    }

    // the checkpoint at or before position limit (the state's tokens agree with a new prompt up to there), or -1
    int best_check(int64_t limit) const {
        int b = -1;
        for (int i = 0; i < 3; ++i)
            if (ck[i].pos >= 0 && ck[i].pos <= limit && ck[i].pos <= pos && (b < 0 || ck[i].pos > ck[b].pos)) b = i;
        return b;
    }
    int64_t restorable(int64_t limit) const {
        const int b = best_check(limit);
        return b < 0 ? -1 : ck[b].pos;
    }

    // checkpoint 1 (the position before the last prompt's end) becomes the anchor too
    void pin() {
        if (ck[1].pos > 0) ck[2] = ck[1];
    }
    // the checkpoints the state can go back to (what a slot of it keeps), latest first
    std::vector<int64_t> check_positions() const {
        std::vector<int64_t> v;
        for (const Check& c : ck)
            if (c.pos > 0 && c.pos <= pos && c.win.size() == L.size() &&
                std::find(v.begin(), v.end(), c.pos) == v.end())
                v.push_back(c.pos);
        std::sort(v.rbegin(), v.rend());
        return v;
    }
    // the checkpoints a slot keeps (each with its role: 0, 1 or the anchor)
    std::vector<int> slot_checks() const {
        std::vector<int> v;
        for (int i = 0; i < 3; ++i)
            if (ck[i].pos > 0 && ck[i].pos <= pos && ck[i].win.size() == L.size()) v.push_back(i);
        return v;
    }
    size_t check_bytes() const {
        size_t n = 16;
        for (const Layer& l : L) n += (size_t) g.win * win_rb() + (l.c_kv ? 2 * (size_t) l.ratio * g.hd * 4 : 0);
        return n;
    }

    bool restore(int64_t limit) {
        const int b = best_check(limit);
        if (b < 0) return false;
        const Check& c = ck[b];
        for (size_t i = 0; i < L.size(); ++i)
            for (int m = 0; m < L[i].nm; ++m) {   // (a group's members hold the same state: the lead's copy)
                Layer& l = member(L[i], m);
                Dev& d = devs[(size_t) l.dev];
                cudaSetDevice(d.id);
                cudaMemcpyAsync(l.win, c.win[i].data(), c.win[i].size(), cudaMemcpyHostToDevice, d.st);
                if (l.c_kv) {
                    cudaMemcpyAsync(l.c_kv, c.comp[2 * i].data(), c.comp[2 * i].size() * 4, cudaMemcpyHostToDevice, d.st);
                    cudaMemcpyAsync(l.c_score, c.comp[2 * i + 1].data(), c.comp[2 * i + 1].size() * 4,
                                    cudaMemcpyHostToDevice, d.st);
                }
            }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        pos = c.pos;
        toks.resize((size_t) pos);
        ctoks.resize((size_t) pos);
        slot_held = false;
        for (Check& o2 : ck)   // a later checkpoint saw tokens the state no longer has
            if (o2.pos > pos) o2.pos = -1;
        return true;
    }

    // ---- the kept conversations (a slot): the state out of the model and back, through a file or a host buffer.
    // A prompt that continues the state is reused in place (checkpoint / restore, the compressed KV left where it is);
    // a conversation that leaves the model for another one is a slot - the whole state: the position, its tokens,
    // every window ring (the DSpark blocks' included), the compressors' partial groups and each KV source's compressed
    // KV and index keys up to it (rows 0 .. pos / ratio, the groups its position completed; one the prompt has not
    // completed yet lives in the compressor's partial group).  A tensor parallel group's members hold the same state,
    // so one member's ring is saved and written back into all of them.  Pictures: a slot keeps each picture's mark
    // (where its span starts, its pixels' fingerprint, its span's length), not the pixels and not the rows - the rows'
    // work is in the KV, and a prompt reads a span's rows only while it feeds the span itself.  A slot is taken back
    // only for a prompt whose pictures are the same at the same places (the caller compares the marks against its
    // prompt; the marks travel with the slot so it can).
    static constexpr uint64_t kSlotMagic = 0x32544f4c53345344ull;   // "DS4SLOT2" (little endian)

    int64_t src_rows(const Src& s) const { return pos / std::max(1, s.ratio); }

    // the slot's bytes: the header, the tokens, the pictures' marks, every layer's ring and partial group, every
    // source's rows, the end
    size_t slot_bytes(size_t n_pics) const {
        size_t n = 8 + 8 + slot_identity().size() + 8 + (size_t) pos * 4;
        n += 8 + n_pics * 24;   // (a picture: start, hash, len)
        for (const Layer& l : L) n += 8 + (size_t) g.win * win_rb() + 8 + (l.c_kv ? 2 * (size_t) l.ratio * g.hd * 4 : 0);
        for (const Src& s : srcs) n += 8 + (size_t) src_rows(s) * (ckv_rb() + ik_rb());
        n += 8 + slot_checks().size() * check_bytes();   // (the checkpoints: what the slot can be taken back at)
        return n + 8;
    }

    uint64_t slot_save(std::vector<uint8_t>& out, std::string& err, const std::vector<PicMark>& pics) {
        if (slot_held) {
            err = "it is already set aside";
            return 0;
        }
        if (pos <= 0) {
            err = "there is no conversation";
            return 0;
        }
        if ((int64_t) toks.size() != pos) {
            err = "the state's tokens do not match its position";
            return 0;
        }
        for (size_t i = 0; i < pics.size(); ++i) {   // (the caller's marks: its state's pictures, in prompt order)
            const PicMark& k = pics[i];
            if (k.start < 0 || k.len == 0 || k.start + (int64_t) k.len > pos ||
                (i > 0 && k.start <= pics[i - 1].start)) {
                err = "a picture's mark (span " + std::to_string(k.start) + " + " + std::to_string(k.len) +
                      ") is not in the state, or the marks are out of order";
                return 0;
            }
        }
        const std::string id = slot_identity();
        out.assign(slot_bytes(pics.size()), 0);
        uint8_t* p = out.data();
        size_t off = 0;
        const auto put = [&](const void* s, size_t b) {
            std::memcpy(p + off, s, b);
            off += b;
        };
        const uint64_t il = id.size(), n = (uint64_t) pos;
        put(&kSlotMagic, 8);
        put(&il, 8);
        put(id.data(), (size_t) il);
        put(&n, 8);
        put(toks.data(), (size_t) n * 4);
        {
            const uint64_t np = pics.size();
            put(&np, 8);
            for (const PicMark& k : pics) {
                put(&k.start, 8);
                put(&k.hash, 8);
                put(&k.len, 8);
            }
        }
        for (Dev& d : devs) {   // (the devices' work ends before their state is read)
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        for (size_t i = 0; i < L.size(); ++i) {
            const Layer& l = L[i];
            const Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            const uint64_t wb = (uint64_t) g.win * win_rb();
            put(&wb, 8);
            if (cudaMemcpy(p + off, l.win, (size_t) wb, cudaMemcpyDeviceToHost) != cudaSuccess) {
                err = l.name + "window ring: " + cudaGetErrorString(cudaGetLastError());
                return 0;
            }
            off += (size_t) wb;
            const uint64_t cn = l.c_kv ? (uint64_t) l.ratio * (uint64_t) g.hd : 0;
            put(&cn, 8);
            if (cn > 0) {
                const size_t cb = (size_t) cn * 4;
                if (cudaMemcpy(p + off, l.c_kv, cb, cudaMemcpyDeviceToHost) != cudaSuccess ||
                    cudaMemcpy(p + off + cb, l.c_score, cb, cudaMemcpyDeviceToHost) != cudaSuccess) {
                    err = l.name + "compressor's group: " + cudaGetErrorString(cudaGetLastError());
                    return 0;
                }
                off += 2 * cb;
            }
        }
        for (const Src& s : srcs) {
            const uint64_t rows = (uint64_t) src_rows(s);
            put(&rows, 8);
            if (rows == 0) continue;
            const int di = L[(size_t) s.layer].dev;
            const uint8_t* ckv = s.ckv[(size_t) di];
            const uint8_t* ik = s.ik[(size_t) di];   // (a pack whose sources are not index sources: none, zeros)
            if (ckv == nullptr) {
                err = "source layer " + std::to_string(s.layer) + "'s rows are not on its device";
                return 0;
            }
            const size_t cb = (size_t) rows * ckv_rb(), ib = (size_t) rows * ik_rb();
            cudaSetDevice(devs[(size_t) di].id);
            if (cudaMemcpy(p + off, ckv, cb, cudaMemcpyDeviceToHost) != cudaSuccess ||
                (ik != nullptr && cudaMemcpy(p + off + cb, ik, ib, cudaMemcpyDeviceToHost) != cudaSuccess)) {
                err = "source layer " + std::to_string(s.layer) + "'s compressed KV: " + cudaGetErrorString(cudaGetLastError());
                return 0;
            }
            off += cb + ib;
        }
        {
            const std::vector<int> cs = slot_checks();
            const uint64_t nc = cs.size();
            put(&nc, 8);
            for (int k : cs) {
                const Check& c = ck[k];
                const uint64_t role = (uint64_t) k, cp = (uint64_t) c.pos;
                put(&role, 8);
                put(&cp, 8);
                for (size_t i = 0; i < L.size(); ++i) {
                    put(c.win[i].data(), (size_t) g.win * win_rb());
                    if (L[i].c_kv) {
                        put(c.comp[2 * i].data(), (size_t) L[i].ratio * g.hd * 4);
                        put(c.comp[2 * i + 1].data(), (size_t) L[i].ratio * g.hd * 4);
                    }
                }
            }
        }
        if (off + 8 != out.size()) {
            err = "the state's size does not add up";
            return 0;
        }
        put(&kSlotMagic, 8);
        slot_held = true;
        return (uint64_t) off;
    }

    bool slot_load(const uint8_t* data, size_t bytes, int64_t n_pos, std::string& err, std::vector<PicMark>* pics) {
        size_t off = 0;
        bool wrote = false, ok = false;
        // a load that stops after some of another conversation's state went into the layers leaves a state no
        // checkpoint can repair: it is reset (the prompt is read from token 0), never served from the mix
        struct FailClosed {
            Impl& p;
            const bool& wrote;
            const bool& ok;
            ~FailClosed() {
                if (!ok && wrote) p.reset();
            }
        } guard{*this, wrote, ok};
        const auto room = [&](size_t b) { return b <= bytes && off <= bytes - b; };
        uint64_t magic = 0, il = 0, n = 0;
        if (!room(16)) {
            err = "the slot is cut short";
            return false;
        }
        std::memcpy(&magic, data + off, 8);
        std::memcpy(&il, data + off + 8, 8);
        off += 16;
        if (magic != kSlotMagic || il == 0 || il > (1u << 20)) {
            err = "not a saved conversation";
            return false;
        }
        if (!room((size_t) il + 8)) {
            err = "the slot is cut short";
            return false;
        }
        {
            std::string id((size_t) il, '\0');
            std::memcpy(id.data(), data + off, (size_t) il);
            off += (size_t) il;
            std::memcpy(&n, data + off, 8);
            off += 8;
            if (id != slot_identity()) {
                err = "another model's, or another engine version's, conversation";
                return false;
            }
        }
        if (n != (uint64_t) n_pos || n_pos <= 0 || n_pos > o.max_context || !room((size_t) n * 4)) {
            err = "the conversation's position is not this prompt's";
            return false;
        }
        std::vector<int32_t> toks_in((size_t) n);
        std::memcpy(toks_in.data(), data + off, (size_t) n * 4);
        off += (size_t) n * 4;
        std::vector<PicMark> marks;
        {
            uint64_t np = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&np, data + off, 8);
            off += 8;
            if (np > 4096 || !room((size_t) np * 24)) {
                err = "the slot's pictures are damaged";
                return false;
            }
            if (np > 0 && pics == nullptr) {   // (a caller that cannot check the pictures must not serve the state)
                err = "the slot holds pictures";
                return false;
            }
            marks.resize((size_t) np);
            for (uint64_t k = 0; k < np; ++k) {
                PicMark& m = marks[(size_t) k];
                std::memcpy(&m.start, data + off, 8);
                std::memcpy(&m.hash, data + off + 8, 8);
                std::memcpy(&m.len, data + off + 16, 8);
                off += 24;
                if (m.start < 0 || m.len == 0 || m.start + (int64_t) m.len > n_pos ||
                    (k > 0 && m.start <= marks[(size_t) k - 1].start)) {
                    err = "the slot's pictures are damaged";
                    return false;
                }
            }
        }
        for (Dev& d : devs) {   // (their work ends before the state is written over)
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        for (size_t i = 0; i < L.size(); ++i) {
            Layer& l = L[i];
            const Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            uint64_t wb = 0, cn = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&wb, data + off, 8);
            off += 8;
            if (wb != (uint64_t) g.win * win_rb() || !room((size_t) wb + 8)) {
                err = l.name + "window ring of another size";
                return false;
            }
            wrote = true;
            for (int m = 0; m < l.nm; ++m) {
                Layer& lm = member(l, m);
                if (cudaMemcpy(lm.win, data + off, (size_t) wb, cudaMemcpyHostToDevice) != cudaSuccess) {
                    err = l.name + "window ring: " + cudaGetErrorString(cudaGetLastError());
                    return false;
                }
            }
            off += (size_t) wb;
            std::memcpy(&cn, data + off, 8);
            off += 8;
            if (cn != (l.c_kv ? (uint64_t) l.ratio * (uint64_t) g.hd : 0)) {
                err = l.name + "compressor's group of another size";
                return false;
            }
            if (cn > 0) {
                const size_t cb = (size_t) cn * 4;
                if (!room(2 * cb)) {
                    err = "the slot is cut short";
                    return false;
                }
                for (int m = 0; m < l.nm; ++m) {
                    Layer& lm = member(l, m);
                    if (cudaMemcpy(lm.c_kv, data + off, cb, cudaMemcpyHostToDevice) != cudaSuccess ||
                        cudaMemcpy(lm.c_score, data + off + cb, cb, cudaMemcpyHostToDevice) != cudaSuccess) {
                        err = l.name + "compressor's group: " + cudaGetErrorString(cudaGetLastError());
                        return false;
                    }
                }
                off += 2 * cb;
            }
        }
        for (const Src& s : srcs) {
            uint64_t rows = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&rows, data + off, 8);
            off += 8;
            if (rows != (uint64_t) (n_pos / std::max(1, s.ratio))) {
                err = "source layer " + std::to_string(s.layer) + "'s rows are not this conversation's";
                return false;
            }
            if (rows == 0) continue;
            const size_t cb = (size_t) rows * ckv_rb(), ib = (size_t) rows * ik_rb();
            if (!room(cb + ib)) {
                err = "the slot is cut short";
                return false;
            }
            for (size_t di = 0; di < devs.size(); ++di) {
                if (s.ckv[di] == nullptr && s.ik[di] == nullptr) continue;
                cudaSetDevice(devs[di].id);
                if (s.ckv[di] != nullptr && cudaMemcpy(s.ckv[di], data + off, cb, cudaMemcpyHostToDevice) != cudaSuccess) {
                    err = "source layer " + std::to_string(s.layer) + "'s compressed KV: " + cudaGetErrorString(cudaGetLastError());
                    return false;
                }
                if (s.ik[di] != nullptr &&
                    cudaMemcpy(s.ik[di], data + off + cb, ib, cudaMemcpyHostToDevice) != cudaSuccess) {
                    err = "source layer " + std::to_string(s.layer) + "'s index keys: " + cudaGetErrorString(cudaGetLastError());
                    return false;
                }
            }
            off += cb + ib;
        }
        Check got[3];   // the slot's checkpoints: the positions it can be taken back at
        {
            uint64_t nc = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&nc, data + off, 8);
            off += 8;
            if (nc > 3) {
                err = "the slot's checkpoints are damaged";
                return false;
            }
            for (uint64_t k = 0; k < nc; ++k) {
                uint64_t role = 0, cp = 0;
                if (!room(16)) {
                    err = "the slot is cut short";
                    return false;
                }
                std::memcpy(&role, data + off, 8);
                std::memcpy(&cp, data + off + 8, 8);
                off += 16;
                if (role > 2 || got[role].pos >= 0 || cp == 0 || cp > (uint64_t) n_pos) {
                    err = "the slot's checkpoints are damaged";
                    return false;
                }
                Check& c = got[role];
                c.pos = (int64_t) cp;
                c.win.resize(L.size());
                c.comp.resize(L.size() * 2);
                for (size_t i = 0; i < L.size(); ++i) {
                    const size_t wb = (size_t) g.win * win_rb(), cb = L[i].c_kv ? (size_t) L[i].ratio * g.hd * 4 : 0;
                    if (!room(wb + 2 * cb)) {
                        err = "the slot is cut short";
                        return false;
                    }
                    c.win[i].assign(data + off, data + off + wb);
                    off += wb;
                    if (cb > 0) {
                        c.comp[2 * i].resize(cb / 4);
                        c.comp[2 * i + 1].resize(cb / 4);
                        std::memcpy(c.comp[2 * i].data(), data + off, cb);
                        std::memcpy(c.comp[2 * i + 1].data(), data + off + cb, cb);
                        off += 2 * cb;
                    }
                }
            }
        }
        uint64_t end = 0;
        if (!room(8)) {
            err = "the slot is cut short";
            return false;
        }
        std::memcpy(&end, data + off, 8);
        off += 8;
        if (end != kSlotMagic) {
            err = "the slot does not end where it should";
            return false;
        }
        pos = n_pos;
        toks.swap(toks_in);
        ctoks.resize((size_t) pos);
        for (size_t i = 0; i < (size_t) pos; ++i)
            // (a picture's token: no Engram rows, its look-back stops at it - as ctok() says it while the span is fed)
            ctoks[i] = img_tok >= 0 && toks[i] == img_tok
                           ? -1
                           : (toks[i] < pk.eg_vocab ? pk.eg_map[(size_t) toks[i]] : 0);
        imgs.clear();   // (the slot holds no rows: a span the prompt feeds again is encoded again)
        if (pics != nullptr) *pics = std::move(marks);
        for (int k = 0; k < 3; ++k) ck[k] = std::move(got[k]);   // (the slot's own; the old ones held the state
                                                               // this one replaced)
        slot_held = false;
        ok = true;
        return true;
    }

    std::string slot_identity() const {
        const auto size_of = [](const std::string& p) {
            std::error_code ec;
            const auto s = std::filesystem::file_size(p, ec);
            return ec ? 0ull : (unsigned long long) s;
        };
        std::ostringstream id;
        id << "maya-ds4-session-2 engine=" << STRATA_VERSION << " mtp=" << g.n_mtp << " dim=" << g.dim << " hd=" << g.hd
           << " win=" << g.win << " ratios=";
        for (int r : g.ratios) id << r << ",";
        id << " kv=";
        for (int v : g.kv_src) id << v << ",";
        id << " ix=";
        for (int v : g.ix_src) id << v << ",";
        id << " ds4.txt:" << size_of(pk.dir + "/ds4.txt") << " engram.bin:" << size_of(pk.dir + "/engram.bin")
           << " tensors.txt:" << size_of(pk.dir + "/tensors.txt");
        for (size_t i = 0; i < pk.files.size(); ++i)
            id << " " << pk.files[i] << ":" << os::file_size(pk.fds[i]);
        return id.str();
    }

    size_t bounce_bytes() const {
        return (size_t) kWin * ((size_t) g.hc * g.dim * 4 + 8 * 4 + topk_stride() * 4 + cand_stride() * 4);
    }
    size_t topk_stride() const { return (size_t) std::max(g.ix_topk, 32); }
    size_t cand_stride() const { return (size_t) std::max(g.cand_topk, 32); }
    size_t bm_stride() const { return (size_t) (o.max_context + 64) / std::max(1, g.cand_blk) + 64; }
    static constexpr int kSlots = kWin * kPicks;   // the CPU lane's (token, expert) rows a window can need

    // ---- the vision tower (the checkpoint's vision.* / aligner.*) on the first GPU, its weights streamed from the
    // host; a prompt's pictures as their spans' rows (set_images)
    VisionTower vt;
    VisionGeo vg;
    int img_tok = -1;
    std::string vision_err;              // why the tower did not load (pictures off), or empty
    std::vector<uint16_t> img_mark[3];   // image_start, image_newline, image_end: BF16 [dim]
    std::vector<Image> imgs;             // the pictures of the prompt being fed, by start
    // Nothing of the tower stays in VRAM between pictures: a picture's room (VisionTower::room_bytes, ~320 MB) on the
    // first GPU is lent for its encode and given back after it - by the device's prompt buffers (idle between prompts:
    // kVisChunk, zeroed again after), by its tail of expert slots (a device that lends those to the prompt path:
    // kVisTail, the experts under it read back after, as after a run of chunks), or taken from free memory (kVisFree).
    // A device with no prompt buffers to lend it (prompts in windows) keeps the room for the whole run (kVisResident,
    // as before v1.1.31; MAYA_DS4_VISION_RESIDENT=1 asks for that too).
    enum { kVisNone = 0, kVisChunk, kVisTail, kVisFree, kVisResident };
    int vis_mode = kVisNone;             // where a picture's room comes from (load_vision, then place_experts)
    uint8_t* vis_res = nullptr;          // kVisResident: the room, held for the run
    size_t vis_acct = 0;                 // ... its bytes
    uint8_t* vis_room = nullptr;         // the room held now (an encode, or a request's pictures: vision_hold)
    int vis_src = kVisNone;              // ... and who lent it
    bool vis_hold = false;               // keep it from one encode_image to the next, till vision_release
    std::function<void()> vis_note;      // after the room is taken and after it is given back (the VRAM lines)
    double vis_ms = 0;                   // the last lending's cost: taking the room and giving it back
    bool load_vision(std::string& err) {
        vg.layers = (int) pk.num("vision.num_hidden_layers", 0);
        const int tok = (int) pk.num("image_token_id", -1);
        if (vg.layers <= 0 || tok < 0 || pk.get("vision.patch_embed.proj.weight") == nullptr) return true;   // none
        vg.dim = (int) pk.num("vision.hidden_size", 1024), vg.heads = (int) pk.num("vision.num_attention_heads", 16);
        vg.inter = (int) pk.num("vision.intermediate_size", 2816), vg.patch = (int) pk.num("vision.patch_size", 14);
        vg.merge = (int) pk.num("vision.downsample_ratio", 3), vg.theta = (float) pk.num("vision.rope_theta", 1e4);
        vg.max_tokens = (int) pk.num("vision.max_image_tokens", 1024), vg.out = g.dim;
        const char* mark[3] = {"image_start", "image_newline", "image_end"};
        for (int i = 0; i < 3; ++i) {
            const Tensor* t = pk.get(mark[i]);
            img_mark[i].resize((size_t) g.dim);
            if (t == nullptr || t->dtype != "BF16" || t->bytes != (uint64_t) g.dim * 2 || !pk.read(*t, img_mark[i].data())) {
                err = std::string(mark[i]) + ": not a BF16 row of the model's width";
                return false;
            }
        }
        const double t0 = now_ms();
        Dev& d = devs[0];
        auto read = [this](const std::string& n, std::vector<int64_t>& shape, void* dst) {
            const Tensor* t = pk.get(n);
            if (t == nullptr || t->dtype != "BF16") return false;
            shape = t->shape;
            return dst == nullptr || pk.read(*t, dst);
        };
        if (!vt.load(vg, d.id, read, err)) return false;
        img_tok = tok;
        // a picture's room: lent on demand (place_experts says by whom) where the prompt runs in chunks; prompts in
        // windows have no buffers to lend it, so the room is the tower's own then - taken here, before the split
        // (the settings' MAYA_DS4_VISION_RESIDENT=1, or DS4_VISION_RESIDENT for tests: the room kept, as before)
        const char* rv = std::getenv("DS4_VISION_RESIDENT");
        if (rv == nullptr) rv = std::getenv("STRATA_DS4_VISION_RESIDENT");
        const bool resident = rv != nullptr && std::atoi(rv) != 0;
        vis_mode = o.vision_only ? kVisFree : chunk > 0 && !resident ? kVisChunk : kVisResident;
        if (vis_mode == kVisResident && !dalloc(d, vis_res, vt.room_bytes(), err, &vis_acct)) return false;
        CK(cudaSetDevice(d.id));
        CK(mem_info(&d.free0, &d.total));   // (the split sees what the tower left)
        if (o.verbose)
            std::fprintf(stderr, "ds4: vision tower (%d blocks) for CUDA%d: its weights %.0f MiB in pinned RAM, a picture's "
                                 "room %.0f MiB (%s), up to %d patches, %.1f s\n",
                         vg.layers, d.id, (double) vt.host_bytes() / (1 << 20), (double) vt.room_bytes() / (1 << 20),
                         vis_mode == kVisResident ? "kept on the GPU for the run" : "lent for each picture",
                         vt.max_patches(), (now_ms() - t0) / 1000.0);
        return true;
    }
    // (the INFO line's name of a room's lender)
    static const char* vis_name(int m) {
        return m == kVisChunk ? "chunk" : m == kVisTail ? "tail" : m == kVisFree ? "free" : m == kVisResident ? "resident"
                                                                                                           : "none";
    }
    // a picture's room on the tower's GPU (vis_mode's lender; one that cannot lend it now: free memory)
    uint8_t* take_vis_room(int& src, std::string& err) {
        Dev& d = devs[0];
        const size_t need = vt.room_bytes();
        cudaSetDevice(d.id);
        src = kVisNone;
        Chunk* c = chunks.empty() ? nullptr : chunks[0].get();
        // (DS4_VISION_ROOM=tail or =free, tests: that lender even where the prompt buffers would lend the room - the
        //  tail only on a device that has one, Chunk::borrow)
        static const std::string force = std::getenv("DS4_VISION_ROOM") != nullptr ? std::getenv("DS4_VISION_ROOM") : "";
        const bool chunk_room = force.empty() && c != nullptr && c->room != nullptr && c->room_bytes >= need;
        // (DS4_VISION_LEND=1, tests: the prompt buffers lend the room even to a tower that keeps its own - the experts
        //  placed as with the room kept, so the answers show that where the room is changes nothing)
        static const bool lend_test = std::getenv("DS4_VISION_LEND") != nullptr && std::atoi(std::getenv("DS4_VISION_LEND")) != 0;
        if (vis_mode == kVisResident && !(lend_test && chunk_room)) {
            src = kVisResident;
            return vis_res;
        }
        // (between prompts: no run of chunks, no decode - what the device's streams still hold done first)
        cudaStreamSynchronize(d.st);
        if (d.st2 != nullptr) cudaStreamSynchronize(d.st2);
        if (c != nullptr && c->cs != nullptr) cudaStreamSynchronize(c->cs);
        if ((vis_mode == kVisChunk || vis_mode == kVisResident) && chunk_room) {
            src = kVisChunk;
            return c->room;
        }
        uint8_t* p = nullptr;
        if ((vis_mode == kVisTail || force == "tail") && lend_tail(need, p)) {
            src = kVisTail;
            return p;
        }
        void* v = nullptr;
        if (cudaMalloc(&v, need) == cudaSuccess) {
            src = kVisFree;
            return (uint8_t*) v;
        }
        cudaGetLastError();
        err = "vision: " + std::to_string(need >> 20) + " MiB of CUDA" + std::to_string(d.id) +
              " for the picture: none free and none lent";
        return nullptr;
    }
    // false: the tail's experts did not all come back as they were (borrow_end's false: DS4_CHECK_LEND, or a device
    // failed - lend_broken, sticky), so the request fails before its prompt, as after a run of chunks
    bool give_vis_room(uint8_t* p, int src) {
        Dev& d = devs[0];
        cudaSetDevice(d.id);
        if (src == kVisChunk) {   // (zeroed again: the prompt buffers as the tower found them, where it wrote)
            cudaMemsetAsync(p, 0, vt.room_bytes(), d.st);
            cudaStreamSynchronize(d.st);
        } else if (src == kVisTail) {
            return borrow_end();   // (the experts under it read back into their slots)
        } else if (src == kVisFree) {
            cudaFree(p);
        }
        return true;
    }
    // the tail of the first device's expert slots (Chunk::borrow's region) lent to a picture: as borrow_begin, its end
    // `need` bytes out of the VRAM set until borrow_end reads their experts back
    bool lend_tail(size_t need, uint8_t*& p) {
        Dev& d = devs[0];
        if (lent || d.tail == nullptr || need + 256 > d.tail_bytes) return false;
        cache_drain();
        if (ln_one || ln_land) rc_drain();
        const size_t b0 = (d.tail_bytes - need) & ~(size_t) 255;
        for (Layer& l : L) {
            if (l.dev != 0 || l.mtp || l.n_main >= l.n_slots) continue;
            const size_t off = (size_t) (l.xbase - d.tail), u = align256(unit(l));
            int keep = 0;   // (the slots wholly before the room)
            while (l.n_main + keep < l.n_slots && off + (size_t) keep * d.tail_step + u <= b0) ++keep;
            l.pv_n = l.n_main + keep;
        }
        lent = true;
        cudaSetDevice(d.id);
        cudaStreamSynchronize(d.st);
        p = d.tail + b0;
        return true;
    }
    bool vision_release() {
        if (vis_room == nullptr) return true;
        const double t0 = now_ms();
        const bool back = give_vis_room(vis_room, vis_src);
        vis_ms += now_ms() - t0;
        const int src = vis_src;
        vis_room = nullptr;
        vis_src = kVisNone;
        if (src != kVisResident && vis_note) vis_note();
        return back;
    }
    bool encode_image(const uint8_t* rgb, int w, int h, std::vector<uint16_t>& span, std::string& err) {
        if (img_tok < 0) {
            err = "this model has no vision tower (or it is off)";
            return false;
        }
        if (vis_room == nullptr) {
            const double t0 = now_ms();
            vis_room = take_vis_room(vis_src, err);
            if (vis_room == nullptr) return false;
            vis_ms = now_ms() - t0;
            if (vis_src != kVisResident) {
                static bool said[kVisResident + 1] = {};
                if (!said[vis_src] || o.verbose)
                    std::fprintf(stderr, "ds4: vision: a picture's room, %.0f MiB of CUDA%d, %s (%.0f ms)\n",
                                 (double) vt.room_bytes() / (1 << 20), devs[0].id,
                                 vis_src == kVisChunk  ? "lent by the prompt buffers"
                                 : vis_src == kVisTail ? "lent by the tail of expert slots (their experts read back after)"
                                                       : "from free memory",
                                 vis_ms);
                said[vis_src] = true;
                if (vis_note) vis_note();
            }
        }
        std::vector<uint16_t> rows;
        int nh = 0, nw = 0;
        const bool ok = vt.encode(rgb, w, h, vis_room, rows, nh, nw, err);
        if (!vis_hold && !vision_release() && ok) {
            err = "vision: the expert slots lent for the picture were not read back as they were";
            return false;
        }
        if (!ok) return false;
        const size_t D = (size_t) g.dim;
        span.resize(((size_t) nh * (nw + 1) + 2) * D);
        uint16_t* o = span.data();
        auto put = [&](const uint16_t* r) {
            std::memcpy(o, r, D * 2);
            o += D;
        };
        put(img_mark[0].data());
        for (int i = 0; i < nh; ++i) {
            for (int j = 0; j < nw; ++j) put(rows.data() + ((size_t) i * nw + j) * D);
            put(img_mark[1].data());
        }
        put(img_mark[2].data());
        return true;
    }
    // the row of a picture's span at position p (null: p is in none)
    const uint16_t* image_row(int64_t p) const {
        if (imgs.empty()) return nullptr;
        auto it = std::upper_bound(imgs.begin(), imgs.end(), p, [](int64_t v, const Image& im) { return v < im.start; });
        if (it == imgs.begin()) return nullptr;
        const Image& im = *(it - 1);
        const int64_t r = p - im.start;
        if (!im.rows || r >= (int64_t) (im.rows->size() / (size_t) g.dim)) return nullptr;
        return im.rows->data() + (size_t) r * g.dim;
    }
    // token tk's embedding row at position p: inside a picture's span, the picture's
    const uint16_t* emb_row(int64_t p, int tk) const {
        const uint16_t* r = tk == img_tok ? image_row(p) : nullptr;
        return r != nullptr ? r : embed_pinned + (size_t) tk * g.dim;
    }
    bool in_image(int64_t p) const { return img_tok >= 0 && toks[(size_t) p] == img_tok && image_row(p) != nullptr; }
    // the Engram's compressed id of token tk at p (-1: a picture's, which no n-gram spans)
    int32_t ctok(int64_t p, int tk) const {
        if (tk == img_tok && image_row(p) != nullptr) return -1;
        return tk < pk.eg_vocab ? pk.eg_map[(size_t) tk] : 0;
    }
    // a chunk's image rows (route()'s bits); false: none
    bool vl_bits(int64_t p0, int T, VlBits& b) const {
        if (imgs.empty()) return false;
        std::memset(&b, 0, sizeof b);
        bool any = false;
        for (int t = 0; t < T && t < kVlRows; ++t)
            if (in_image(p0 + t)) {
                b.w[t >> 5] |= 1u << (t & 31);
                any = true;
            }
        return any;
    }

    // ---- Engram: a window's rows of one table (Engram layer li), tokens p0 .. p0 + T - 1 into dst ([token] of [cols]
    // [hd] codes then the scales; nullptr: h_eg).  eg_issue serves the rows already fetched from the row cache (and a
    // row the window needs twice from one read) and hands the rest to the reader's threads; eg_finish waits for them,
    // copies the repeats and keeps the new rows in the cache.  The rows are the file's bytes either way.
    void eg_issue(int64_t p0, int T, int li, uint8_t* dst, EgBatch& b, bool account = true, bool submit = true,
                  bool defer_dups = false) {
        const int cols = (pk.eg_ngram - 1) * pk.eg_heads, hd = pk.eg_hd;
        const size_t per = (size_t) cols * (hd + hd / 32);
        b.clear();
        b.reads.reserve((size_t) T * cols);
        const std::string P = "layers." + std::to_string(g.eg_layers[(size_t) li]) + ".engram.embed.";
        const Tensor* tw = pk.get(P + "weight");
        const Tensor* ts = pk.get(P + "scale");
        const bool mx8 = tw->dtype == "MXFP8";   // (a GGUF: the scales between the codes, one per 32)
        const bool q6k = eg_q6k[(size_t) li] == 1;   // (a GGUF: one Q6_K superblock a 256 values, its scales inside)
        const bool iq4 = eg_q6k[(size_t) li] == 2;   // (IQ4_NL blocks of 32, their scales inside)
        std::unordered_map<uint64_t, int> first;   // a row this batch reads already -> its read
        if (!defer_dups) first.reserve((size_t) T * cols);
        int64_t hits = 0;
        {
            std::lock_guard<std::mutex> lk(eg_cache_mu);
            for (int t = 0; t < T; ++t) {
                const int64_t p = p0 + t;
                uint8_t* rows = dst != nullptr ? dst + (size_t) t * per : h_eg + ((size_t) li * eg_cap + t) * per;
                uint8_t* scales = rows + (size_t) cols * hd;
                if (ctoks[(size_t) p] < 0) {   // a picture's token: no rows (zeros: its gate adds nothing)
                    std::memset(rows, 0, per);
                    continue;
                }
                int64_t prod[8];
                bool blocked = false;
                for (int s = 0; s < pk.eg_ngram; ++s) {   // (the look-back stops at the start and at a picture)
                    blocked = blocked || p < s || ctoks[(size_t) (p - s)] < 0;
                    const int64_t tk = blocked ? pk.eg_pad : ctoks[(size_t) (p - s)];
                    prod[s] = tk * pk.eg_mult[(size_t) li * pk.eg_ngram + s];
                }
                int64_t rolling = prod[0];
                for (int n = 1; n < pk.eg_ngram; ++n) {
                    rolling ^= prod[n];
                    for (int h = 0; h < pk.eg_heads; ++h) {
                        const int c = (n - 1) * pk.eg_heads + h;
                        const int64_t id = rolling % pk.eg_primes[(size_t) li * cols + c] + pk.eg_off[(size_t) li * cols + c];
                        uint8_t* rd = rows + (size_t) c * hd;
                        uint8_t* sd = scales + (size_t) c * (hd / 32);
                        const uint64_t key = (uint64_t) id * 8 + (uint64_t) li;
                        if (const uint8_t* hit = eg_cache.find(key)) {
                            std::memcpy(rd, hit, (size_t) hd);
                            std::memcpy(sd, hit + hd, (size_t) hd / 32);
                            ++hits;
                            continue;
                        }
                        if (!defer_dups) {
                            const auto fi = first.find(key);
                            if (fi != first.end()) {
                                b.dups.push_back({fi->second, {rd, sd}});
                                continue;
                            }
                            first.emplace(key, (int) b.reads.size());
                        }
                        EgRead r;
                        r.file = tw->file;
                        r.dst = rd;
                        r.scales = sd;
                        r.key = key;
                        if (mx8) {
                            r.mx8 = true;
                            r.n = (uint32_t) (hd / 32 * 33);
                            r.off = tw->off + (uint64_t) id * r.n;
                        } else if (q6k || iq4) {   // (into the row's code bytes; its scale bytes unused)
                            r.n = (uint32_t) (q6k ? hd / 256 * 210 : hd / 32 * 18);
                            r.off = tw->off + (uint64_t) id * r.n;
                        } else {
                            r.n = (uint32_t) hd;
                            r.off = tw->off + (uint64_t) id * hd;
                            r.file2 = ts->file;
                            r.n2 = (uint32_t) (hd / 32);
                            r.off2 = ts->off + (uint64_t) id * (hd / 32);
                        }
                        b.reads.push_back(r);
                    }
                }
            }
        }
        b.lookups = hits + (int64_t) b.reads.size() + (int64_t) b.dups.size();
        if (account) {
            eg_rows_n += b.lookups;
            eg_hits_n += hits + (int64_t) b.dups.size();
            eg_reads_n += (int64_t) b.reads.size();
        }
        if (submit) eg_io.submit(b);
    }
    // b's rows all in place (any thread; a group's members may ask at once: one finishes, the others wait for it)
    void eg_finish(EgBatch& b, bool account = true) {
        if (b.post.load(std::memory_order_acquire) == 2) return;
        const int64_t t0 = now_ns();
        eg_io.wait(b);
        int want = 0;
        if (b.post.compare_exchange_strong(want, 1, std::memory_order_acq_rel)) {
            const int hd = pk.eg_hd;
            for (const auto& d : b.dups) {
                const EgRead& r = b.reads[(size_t) d.first];
                if (b.ok[(size_t) d.first] == 1) {
                    std::memcpy(d.second.first, r.dst, (size_t) hd);
                    std::memcpy(d.second.second, r.scales, (size_t) hd / 32);
                } else {   // a failed canonical read must not publish uninitialised duplicate destinations
                    std::memset(d.second.first, 0, (size_t) hd);
                    std::memset(d.second.second, 0, (size_t) hd / 32);
                }
            }
            {
                std::lock_guard<std::mutex> lk(eg_cache_mu);
                for (size_t i = 0; i < b.reads.size(); ++i) {
                    const EgRead& r = b.reads[i];
                    if (b.ok[i] == 2) continue;   // sorted duplicate: copied above; only the canonical enters the cache
                    if (!b.ok[i]) {   // (a failed read: zeros, its gate adds nothing; not kept)
                        std::memset(r.dst, 0, (size_t) hd);
                        std::memset(r.scales, 0, (size_t) hd / 32);
                        continue;
                    }
                    if (uint8_t* c = eg_cache.put(r.key)) {
                        std::memcpy(c, r.dst, (size_t) hd);
                        std::memcpy(c + hd, r.scales, (size_t) hd / 32);
                    }
                }
            }
            if (!account) {
                // One logical lookup is either a canonical read attempt or served by cache/a duplicate destination.
                // Account here, after zone planning has reduced the reads to their canonical set, and only once.
                eg_pf_rows_n += b.lookups;
                eg_pf_hits_n += b.lookups - b.io_reads;
                eg_pf_reads_n += b.io_reads;
            }
            if (account) eg_io_ns += b.t1.load() - b.t0;
            else eg_pf_io_ns += b.t1.load() - b.t0;
            b.live = false;
            b.post.store(2, std::memory_order_release);
        } else {
            while (b.post.load(std::memory_order_acquire) != 2) std::this_thread::yield();
        }
        if (account) eg_wait_ns += now_ns() - t0;
        else eg_pf_wait_ns += now_ns() - t0;
    }
    void eg_stats() {
        st.eg_rows = eg_rows_n.load();
        st.eg_hits = eg_hits_n.load();
        st.eg_reads = eg_reads_n.load();
        st.eg_pf_rows = eg_pf_rows_n.load();
        st.eg_pf_hits = eg_pf_hits_n.load();
        st.eg_pf_reads = eg_pf_reads_n.load();
        st.eg_io_ms = (double) eg_io_ns.load() / 1e6;
        st.eg_pf_io_ms = (double) eg_pf_io_ns.load() / 1e6;
        st.eg_pf_wait_ms = (double) eg_pf_wait_ns.load() / 1e6;
        std::lock_guard<std::mutex> lk(eg_cache_mu);
        st.eg_cached = (int64_t) eg_cache.size();
        st.eg_cache_cap = (int64_t) eg_cache.capacity();
        st.eg_cache_row_bytes = (int64_t) eg_cache.row_bytes();
    }
    // the chunked prompt path: rows of Engram layer `only` into dst, now (a helper thread, a chunk ahead)
    void engram_rows(int64_t p0, int T, int only, uint8_t* dst, bool account = true) {
        EgBatch b;
        eg_issue(p0, T, only, dst, b, account);
        eg_finish(b, account);
    }

    // ---- the CPU lane: a window's routed experts that live on the host, as entries (an expert and up to 8 of its
    // tokens, in rows slot0 ..) computed together: each node its column part of every matrix, from memory on that node,
    // in four steps (the gate / up split-K pieces, each preparing its two input blocks of every token; each band's
    // sums / codebook / Hadamard / swiglu and that block of the down input, which both nodes then read whole; the down
    // pieces; the down bands) - an EXL3 layer's as one flowing batch a node (ds4_cpu_exl3.hpp).  yd[slot] gets each
    // row's expert output.
    using Ent = LaneEnt;
    void run_nodes(int n, const std::function<void(int)>* f, int ph = -1) {
        static const bool stats = std::getenv("DS4_CPU_STATS") != nullptr;
        if (stats && ph >= 0) {   // (each job's own time, summed: the phase's work beside its wall time)
            std::function<void(int)> g[4];
            for (int X = 0; X < NH; ++X)
                g[X] = [this, &f, X, ph](int j) {
                    const auto t0 = std::chrono::steady_clock::now();
                    f[X](j);
                    cpu_job_ns[ph].fetch_add((uint64_t) std::chrono::duration_cast<std::chrono::nanoseconds>(
                                                 std::chrono::steady_clock::now() - t0).count(),
                                             std::memory_order_relaxed);
                    cpu_job_n[ph].fetch_add(1, std::memory_order_relaxed);
                };
            for (int X = 0; X < NH; ++X) pools[(size_t) X]->start(n, g[X]);
            pools[0]->help();
            for (int X = 0; X < NH; ++X) pools[(size_t) X]->wait();
            return;
        }
        for (int X = 0; X < NH; ++X) pools[(size_t) X]->start(n, f[X]);
        pools[0]->help();
        for (int X = 0; X < NH; ++X) pools[(size_t) X]->wait();
    }

    // a GGUF's MXFP4 experts on the CPU lane, read from the file's mapping or their copy in RAM (mx_part_ptr): each
    // node its rows of every matrix - the gate / up rows [X n_ff / NH, ..) of each entry (the swiglu into its h row),
    // then (h whole) the down rows [X dim / NH, ..) into yd.  A row's sum is the same whatever the split: the same bits
    // in a copy as in place.  The device's arithmetic (gg::mx_rows: int8 activations rounded as the device rounds
    // them, exact integer sums a block; every CPU tier the same bits): each token's input quantized once, whatever
    // number of entries take it, and each job its band of h straight into the down's int8 input.
    // (ord: the order the entries are computed in - their slots, so the sums, stay the same; null: as they are)
    void cpu_experts_mx(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx, const int* ord) {
        const bool mx_gu = gg::expert_type(l.lay, 0) == gg::kTypeMXFP4, mx_d = gg::expert_type(l.lay, 2) == gg::kTypeMXFP4;
        if (!mx_gu && !mx_d) return cpu_experts_iq(l, x, ents, ldx, ord);
        if (!mx_gu || !mx_d) return cpu_experts_both(l, x, ents, ldx, ord, mx_gu);
        constexpr int RB = 64;   // rows a job (whole blocks of h: RB % 32 == 0)
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH;
        const int GB = (FFh + RB - 1) / RB, DB = (Eh + RB - 1) / RB, ne = (int) ents.size();
        const size_t gr = gg::mx_row_bytes(E), dr = gg::mx_row_bytes(FF);
        const size_t xa = gg::mx_act_bytes(E), ha = gg::mx_act_bytes(FF);
        const bool band_q = FFh % 32 == 0;   // (each job's rows whole blocks of h)
        const float lim = g.lim;
        static_assert(kc::kExl3CpuMaxN <= gg::kMxCpuMaxN, "a CPU-lane entry's tokens in one call");
        {   // the experts read from the files (not in the RAM tier) that are not resident: all their pages asked for at
            // once, so the SSD reads them with large requests side by side while the first entries compute
            // (os::prefetch_cold: the resident ones are left alone - the hint walks every page of a range, which cost
            // more than computing a warm expert, 0.34 ms a 6.3 MB matrix on Windows)
            std::vector<std::pair<const void*, size_t>> want;
            for (const Ent& en : ents)
                if (l.ram.empty() || l.ram[(size_t) en.e] < 0)
                    for (int r = 0; r < 3; ++r) want.push_back({mx_mat(l, en.e, r), mx_part_bytes(l, r)});
            os::prefetch_cold(want);
        }
        // the int8 inputs in c_xh's bytes: token t's (t < kWin) at t xa, then the slots' h at (kWin + slot) ha; a token
        // index past the window (none on the decode or chunk paths) gets a row of its own after them
        uint8_t* xq = (uint8_t*) c_xh.data();
        uint8_t* hq = xq + (size_t) kWin * xa;
        uint8_t* xq_extra = hq + (size_t) kSlots * ha;
        auto x_act = [&](const Ent& en, int i) -> const void* {
            const int t = en.tok[i];
            return t < kWin ? xq + (size_t) t * xa : xq_extra + (size_t) (en.slot0 + i) * xa;
        };
        {
            bool done[kWin] = {};
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i) {
                    const int t = en.tok[i];
                    if (t < kWin && done[t]) continue;
                    if (t < kWin) done[t] = true;
                    gg::mx_quant(x + (size_t) t * ldx, E, (void*) x_act(en, i));
                }
        }
        std::function<void(int)> f[4];
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / GB] : j / GB)];
                const int r0 = X * FFh + (j % GB) * RB, r1 = std::min(X * FFh + FFh, r0 + RB);
                const void* ap[gg::kMxCpuMaxN];
                float yg[gg::kMxCpuMaxN][RB], yu[gg::kMxCpuMaxN][RB];
                float *gp[gg::kMxCpuMaxN], *up[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = x_act(en, i);
                    gp[i] = yg[i];
                    up[i] = yu[i];
                }
                // (part X's rows, from where they are: a copy's part on node X, or the file's)
                gg::mx_rows(mx_part_ptr(l, en.e, 0, X), gr, E, r0 - X * FFh, r1 - X * FFh, ap, en.n, gp);
                gg::mx_rows(mx_part_ptr(l, en.e, 1, X), gr, E, r0 - X * FFh, r1 - X * FFh, ap, en.n, up);
                for (int i = 0; i < en.n; ++i) {
                    float* h = band_q ? yg[i] : c_xhd.data() + (size_t) (en.slot0 + i) * FF + r0;
                    for (int r = r0; r < r1; ++r) {
                        float gv = yg[i][r - r0], uv = yu[i][r - r0];
                        if (lim > 0.0f) {
                            gv = std::min(gv, lim);
                            uv = std::min(std::max(uv, -lim), lim);
                        }
                        h[r - r0] = gv / (1.0f + std::exp(-gv)) * uv;
                    }
                    if (band_q) gg::mx_quant_blocks(h, r0 / 32, r1 / 32, hq + (size_t) (en.slot0 + i) * ha, FF);
                }
            };
        run_nodes(ne * GB, f);
        if (!band_q)
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i)
                    gg::mx_quant(c_xhd.data() + (size_t) (en.slot0 + i) * FF, FF, hq + (size_t) (en.slot0 + i) * ha);
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / DB] : j / DB)];
                const int r0 = X * Eh + (j % DB) * RB, r1 = std::min(X * Eh + Eh, r0 + RB);
                const void* ap[gg::kMxCpuMaxN];
                float* yp[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = hq + (size_t) (en.slot0 + i) * ha;
                    yp[i] = c_yd.data() + (size_t) (en.slot0 + i) * E + r0;
                }
                gg::mx_rows(mx_part_ptr(l, en.e, 2, X), dr, FF, r0 - X * Eh, r1 - X * Eh, ap, en.n, yp);
            };
        run_nodes(ne * DB, f);
    }
    // ... the low-bit ones (ds4_iq's types): as above, through ggml-cpu's dots (gg::iq_cpu_*) - each token's input
    // quantized once to the weight type's activation (Q8_K) in its c_xh row's bytes, then (h whole) its h the same
    void cpu_experts_iq(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx, const int* ord) {
        constexpr int RB = 64;   // rows a job
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH;
        const int GB = (FFh + RB - 1) / RB, DB = (Eh + RB - 1) / RB, ne = (int) ents.size();
        gg::IqCpu fm;
        std::string ferr;
        if (!gg::iq_cpu_fmt(gg::expert_type(l.lay, 0), gg::expert_type(l.lay, 2), E, FF, fm, ferr) ||
            fm.act_bytes > (size_t) E * 4 || fm.h_bytes > (size_t) E * 4) {
            static std::atomic<bool> said{false};
            if (!said.exchange(true)) std::fprintf(stderr, "ds4: layer %d's CPU-lane experts: %s\n", l.il, ferr.c_str());
            for (const Ent& en : ents) std::memset(c_yd.data() + (size_t) en.slot0 * E, 0, (size_t) en.n * E * 4);
            return;
        }
        const float lim = g.lim;
        {   // (os::prefetch_cold, as above: the resident ones are left alone - on Windows the hint walks every page of a
            // range, ~0.13 ms an IQ2_XXS expert, on the lane's critical path before the first entry computes.
            // DS4_IQ_PF_ALL=1: every range, as before)
            std::vector<std::pair<const void*, size_t>> want;
            for (const Ent& en : ents)
                if (l.ram.empty() || l.ram[(size_t) en.e] < 0)
                    for (int r = 0; r < 3; ++r) want.push_back({mx_mat(l, en.e, r), mx_part_bytes(l, r)});
            static const bool pf_all = std::getenv("DS4_IQ_PF_ALL") != nullptr && std::atoi(std::getenv("DS4_IQ_PF_ALL")) != 0;
            if (pf_all) os::prefetch(want);
            else os::prefetch_cold(want);
        }
        // the activations in c_xh's bytes, E 4 apart: token t's (t < kWin) at row t - quantized once, whatever number of
        // entries take it - then a row a slot (kWin + slot): a token past the window's input (none on the decode or
        // chunk paths), then (x no longer needed) the slot's h
        uint8_t* aq = (uint8_t*) c_xh.data();
        auto x_act = [&](const Ent& en, int i) -> uint8_t* {
            const int t = en.tok[i];
            return aq + (size_t) (t < kWin ? t : kWin + en.slot0 + i) * E * 4;
        };
        {
            bool done[kWin] = {};
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i) {
                    const int t = en.tok[i];
                    if (t < kWin && done[t]) continue;
                    if (t < kWin) done[t] = true;
                    gg::iq_cpu_quant(fm.gu_act, x + (size_t) t * ldx, E, x_act(en, i));
                }
        }
        std::function<void(int)> f[4];
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / GB] : j / GB)];
                const int r0 = X * FFh + (j % GB) * RB, r1 = std::min(X * FFh + FFh, r0 + RB);
                const void* ap[gg::kMxCpuMaxN];
                float* hp[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = x_act(en, i);
                    hp[i] = c_xhd.data() + (size_t) (en.slot0 + i) * FF + (size_t) X * FFh;   // (part X's rows of h)
                }
                // (part X's rows, from where they are: a copy's part on node X, or the file's - whole rows, so any
                // block size of the type)
                gg::iq_cpu_gate_up(fm, mx_part_ptr(l, en.e, 0, X), mx_part_ptr(l, en.e, 1, X), ap, en.n, hp,
                                   r0 - X * FFh, r1 - X * FFh, lim);
            };
        run_nodes(ne * GB, f);
        for (const Ent& en : ents)
            for (int i = 0; i < en.n; ++i)
                gg::iq_cpu_quant(fm.d_act, c_xhd.data() + (size_t) (en.slot0 + i) * FF, FF,
                                 aq + (size_t) (kWin + en.slot0 + i) * E * 4);
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / DB] : j / DB)];
                const int r0 = X * Eh + (j % DB) * RB, r1 = std::min(X * Eh + Eh, r0 + RB);
                const void* hp[gg::kMxCpuMaxN];
                float* yp[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    hp[i] = aq + (size_t) (kWin + en.slot0 + i) * E * 4;
                    yp[i] = c_yd.data() + (size_t) (en.slot0 + i) * E + (size_t) X * Eh;   // (part X's rows of it)
                }
                gg::iq_cpu_down(fm, mx_part_ptr(l, en.e, 2, X), hp, en.n, yp, r0 - X * Eh, r1 - X * Eh);
            };
        run_nodes(ne * DB, f);
    }

    // ... a layer of both (MXFP4 gate / up over a low-bit down, or the other way round): each role as its kind above -
    // its input quantized as that kind's (gg::mx_quant, or the low-bit type's Q8_K), its rows by gg::mx_rows or
    // ggml-cpu's dots - with h whole in F32 between them.  The activations as cpu_experts_iq lays them out (E 4 apart:
    // token t's at row t, then a row a slot), both kinds' fit there.
    void cpu_experts_both(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx, const int* ord,
                          bool mx_gu) {
        constexpr int RB = 64;   // rows a job
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH;
        const int GB = (FFh + RB - 1) / RB, DB = (Eh + RB - 1) / RB, ne = (int) ents.size();
        const int tq = gg::expert_type(l.lay, mx_gu ? 2 : 0);   // (the low-bit role's type: its activation's)
        gg::IqCpu fm;
        std::string ferr;
        if (!gg::iq_cpu_fmt(tq, tq, E, FF, fm, ferr) || fm.act_bytes > (size_t) E * 4 || fm.h_bytes > (size_t) E * 4 ||
            gg::mx_act_bytes(E) > (size_t) E * 4 || gg::mx_act_bytes(FF) > (size_t) E * 4) {
            static std::atomic<bool> said{false};
            if (!said.exchange(true)) std::fprintf(stderr, "ds4: layer %d's CPU-lane experts: %s\n", l.il, ferr.c_str());
            for (const Ent& en : ents) std::memset(c_yd.data() + (size_t) en.slot0 * E, 0, (size_t) en.n * E * 4);
            return;
        }
        const float lim = g.lim;
        {   // (os::prefetch_cold, as above)
            std::vector<std::pair<const void*, size_t>> want;
            for (const Ent& en : ents)
                if (l.ram.empty() || l.ram[(size_t) en.e] < 0)
                    for (int r = 0; r < 3; ++r) want.push_back({mx_mat(l, en.e, r), mx_part_bytes(l, r)});
            os::prefetch_cold(want);
        }
        uint8_t* aq = (uint8_t*) c_xh.data();
        auto x_act = [&](const Ent& en, int i) -> uint8_t* {
            const int t = en.tok[i];
            return aq + (size_t) (t < kWin ? t : kWin + en.slot0 + i) * E * 4;
        };
        auto h_act = [&](const Ent& en, int i) -> uint8_t* { return aq + (size_t) (kWin + en.slot0 + i) * E * 4; };
        {
            bool done[kWin] = {};
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i) {
                    const int t = en.tok[i];
                    if (t < kWin && done[t]) continue;
                    if (t < kWin) done[t] = true;
                    if (mx_gu) gg::mx_quant(x + (size_t) t * ldx, E, x_act(en, i));
                    else gg::iq_cpu_quant(fm.gu_act, x + (size_t) t * ldx, E, x_act(en, i));
                }
        }
        const size_t gr = gg::mx_row_bytes(E), dr = gg::mx_row_bytes(FF);
        std::function<void(int)> f[4];
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / GB] : j / GB)];
                const int r0 = X * FFh + (j % GB) * RB, r1 = std::min(X * FFh + FFh, r0 + RB);
                const void* ap[gg::kMxCpuMaxN];
                float* hp[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = x_act(en, i);
                    hp[i] = c_xhd.data() + (size_t) (en.slot0 + i) * FF + (size_t) X * FFh;   // (part X's rows of h)
                }
                if (!mx_gu) {
                    gg::iq_cpu_gate_up(fm, mx_part_ptr(l, en.e, 0, X), mx_part_ptr(l, en.e, 1, X), ap, en.n, hp,
                                       r0 - X * FFh, r1 - X * FFh, lim);
                    return;
                }
                float yg[gg::kMxCpuMaxN][RB], yu[gg::kMxCpuMaxN][RB];
                float *gp[gg::kMxCpuMaxN], *up[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) gp[i] = yg[i], up[i] = yu[i];
                gg::mx_rows(mx_part_ptr(l, en.e, 0, X), gr, E, r0 - X * FFh, r1 - X * FFh, ap, en.n, gp);
                gg::mx_rows(mx_part_ptr(l, en.e, 1, X), gr, E, r0 - X * FFh, r1 - X * FFh, ap, en.n, up);
                for (int i = 0; i < en.n; ++i)
                    for (int r = r0; r < r1; ++r) {   // (cpu_experts_mx's swiglu)
                        float gv = yg[i][r - r0], uv = yu[i][r - r0];
                        if (lim > 0.0f) {
                            gv = std::min(gv, lim);
                            uv = std::min(std::max(uv, -lim), lim);
                        }
                        hp[i][r - X * FFh] = gv / (1.0f + std::exp(-gv)) * uv;
                    }
            };
        run_nodes(ne * GB, f);
        for (const Ent& en : ents)
            for (int i = 0; i < en.n; ++i) {
                const float* h = c_xhd.data() + (size_t) (en.slot0 + i) * FF;
                if (mx_gu) gg::iq_cpu_quant(fm.d_act, h, FF, h_act(en, i));
                else gg::mx_quant(h, FF, h_act(en, i));
            }
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / DB] : j / DB)];
                const int r0 = X * Eh + (j % DB) * RB, r1 = std::min(X * Eh + Eh, r0 + RB);
                const void* hp[gg::kMxCpuMaxN];
                float* yp[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    hp[i] = h_act(en, i);
                    yp[i] = c_yd.data() + (size_t) (en.slot0 + i) * E + (size_t) X * Eh;   // (part X's rows of it)
                }
                if (mx_gu) {
                    gg::iq_cpu_down(fm, mx_part_ptr(l, en.e, 2, X), hp, en.n, yp, r0 - X * Eh, r1 - X * Eh);
                    return;
                }
                for (int i = 0; i < en.n; ++i) yp[i] += r0 - X * Eh;   // (mx_rows: y from row r0 on)
                gg::mx_rows(mx_part_ptr(l, en.e, 2, X), dr, FF, r0 - X * Eh, r1 - X * Eh, hp, en.n, yp);
            };
        run_nodes(ne * DB, f);
    }

    // DS4_CPU_STATS: the CPU lane's calls, entries, rows and each phase's time, printed with the profile's save
    double cpu_ph_ms[4] = {};
    long cpu_calls = 0, cpu_ents = 0, cpu_rows = 0;
    std::atomic<uint64_t> cpu_job_ns[4] = {}, cpu_job_n[4] = {};

    void cpu_experts_packed(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx = 0,
                     const int* ord = nullptr) {
        if (ldx == 0) ldx = (size_t) g.dim;
        static const bool stats = std::getenv("DS4_CPU_STATS") != nullptr;
        double tph = stats ? now_ms() : 0.0;
        auto phase = [&](int i) {
            if (!stats) return;
            const double t = now_ms();
            cpu_ph_ms[i] += t - tph;
            tph = t;
        };
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH, GQ = E / 256, DQ = FF / 128;
        const int GB = FFh / 128, DB = Eh / 128, EB = E / 128, FB = FF / 128;
        const int ne = (int) ents.size();
        const float lim = g.lim;
        const int FH = FF / l.nm, blocks = FH / 128;
        auto part = [&](int e, int X, int r, int m = 0) {
            const uint8_t* b = l.hh[(size_t) e][0] + (size_t) m * l.hblob;
            const auto& lay = member(l, m).hlay;
            kc::Exl3Part p;
            p.trellis = (const uint32_t*) (b + lay.trellis[r]);
            p.suh = (const uint16_t*) (b + lay.suh[r]);
            p.svh = (const uint16_t*) (b + lay.svh[r]);
            p.k = r < 2 ? E : FH;
            p.n = r < 2 ? FH : E;
            p.k2 = l.lay.k2[r];
            return p;
        };
        auto xh = [&](int X, int sl, int r) { return c_xh.data() + ((size_t) (X * kSlots + sl) * 2 + r) * E; };
        auto xsb = [&](int X, int sl, int r) { return c_xsb.data() + ((size_t) (X * kSlots + sl) * 2 + r) * EB; };
        auto acc = [&](int X, int sl, int r, int q) {
            return c_acc.data() + (((size_t) (X * kSlots + sl) * 2 + r) * GQ + q) * FFh;
        };
        auto xhd = [&](int sl) { return c_xhd.data() + (size_t) sl * FF; };
        auto xsd = [&](int sl) { return c_xsd.data() + (size_t) sl * FB; };
        auto accd = [&](int X, int sl, int q) { return c_accd.data() + ((size_t) (X * kSlots + sl) * DQ + q) * Eh; };
        std::function<void(int)> f[4];
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (j / (2 * GQ))];
                const int r = (j / GQ) % 2, q = j % GQ;
                const kc::Exl3Part p = part(en.e, X, r);
                const float* xp[kc::kExl3CpuMaxN];
                float* ap[kc::kExl3CpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    const int sl = en.slot0 + i;
                    const float* xt = x + (size_t) en.tok[i] * ldx;
                    for (int b = 2 * q; b < 2 * q + 2; ++b)
                        xsb(X, sl, r)[b] = kc::exl3_cpu_prepare_block(p.suh + b * 128, xt + b * 128, xh(X, sl, r) + b * 128);
                    xp[i] = xh(X, sl, r);
                    ap[i] = acc(X, sl, r, q);
                }
                for (int m = 0; m < l.nm; ++m) {
                    const auto view = part(en.e, X, r, m);
                    float* out[kc::kExl3CpuMaxN];
                    for (int i = 0; i < en.n; ++i) out[i] = ap[i] + m * FH;
                    if (en.n == 1) kc::exl3_cpu_rows_acc(view, xp[0], q * 16, (q + 1) * 16, out[0]);
                    else kc::exl3_cpu_rows_acc_n(view, xp, en.n, q * 16, (q + 1) * 16, out);
                }
            };
        run_nodes(ne * 2 * GQ, f, 0);
        phase(0);
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (j / GB)];
                const int b = j % GB;
                const kc::Exl3Part pg = part(en.e, X, 0, b / blocks), pu = part(en.e, X, 1, b / blocks),
                                      pd = part(en.e, X, 2, b / blocks);
                for (int i = 0; i < en.n; ++i) {
                    const int sl = en.slot0 + i;
                    float y[2][128], a[128], hb[128];
                    for (int r = 0; r < 2; ++r) {
                        for (int c = 0; c < 128; ++c) a[c] = 0.0f;
                        for (int q = 0; q < GQ; ++q) {
                            const float* aq = acc(X, sl, r, q) + b * 128;
                            for (int c = 0; c < 128; ++c) a[c] += aq[c];
                        }
                        double xs = 0.0;
                        for (int k = 0; k < EB; ++k) xs += xsb(X, sl, r)[k];
                        kc::exl3_cpu_band_out(r == 0 ? pg : pu, a, (float) xs, (b % blocks) * 128, y[r]);
                    }
                    for (int c = 0; c < 128; ++c) {
                        float gv = y[0][c], uv = y[1][c];
                        if (lim > 0.0f) {
                            gv = std::min(gv, lim);
                            uv = std::min(std::max(uv, -lim), lim);
                        }
                        hb[c] = gv / (1.0f + std::exp(-gv)) * uv;
                    }
                    const int gb = X * GB + b;
                    xsd(sl)[gb] = kc::exl3_cpu_prepare_block(pd.suh + (gb % blocks) * 128, hb, xhd(sl) + gb * 128);
                }
            };
        run_nodes(ne * GB, f, 1);
        phase(1);
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (j / DQ)];
                const int q = j % DQ;
                const kc::Exl3Part p = part(en.e, X, 2, q / blocks);
                const float* xp[kc::kExl3CpuMaxN];
                float* ap[kc::kExl3CpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    xp[i] = xhd(en.slot0 + i) + (q / blocks) * FH;
                    ap[i] = accd(X, en.slot0 + i, q);
                }
                if (en.n == 1) kc::exl3_cpu_rows_acc(p, xp[0], (q % blocks) * 8, (q % blocks + 1) * 8, ap[0]);
                else kc::exl3_cpu_rows_acc_n(p, xp, en.n, (q % blocks) * 8, (q % blocks + 1) * 8, ap);
            };
        run_nodes(ne * DQ, f, 2);
        phase(2);
        for (int X = 0; X < NH; ++X)
            f[X] = [&, X](int j) {
                const Ent& en = ents[(size_t) (j / DB)];
                const int b = j % DB;
                const kc::Exl3Part pd = part(en.e, X, 2);
                for (int i = 0; i < en.n; ++i) {
                    const int sl = en.slot0 + i;
                    float a[128];
                    for (int c = 0; c < 128; ++c) a[c] = 0.0f;
                    for (int q = 0; q < DQ; ++q) {
                        const float* aq = accd(X, sl, q) + b * 128;
                        for (int c = 0; c < 128; ++c) a[c] += aq[c];
                    }
                    double xs = 0.0;
                    for (int k = 0; k < FB; ++k) xs += xsd(sl)[k];
                    kc::exl3_cpu_band_out(pd, a, (float) xs, b * 128, c_yd.data() + (size_t) sl * E + (size_t) X * Eh + b * 128);
                }
            };
        run_nodes(ne * DB, f, 3);
        phase(3);
    }

    void cpu_experts(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx = 0,
                     const int* ord = nullptr) {
        if (ldx == 0) ldx = (size_t) g.dim;
        static const bool stats = std::getenv("DS4_CPU_STATS") != nullptr;
        double tph = stats ? now_ms() : 0.0;
        auto phase = [&](int i) {
            if (!stats) return;
            const double t = now_ms();
            cpu_ph_ms[i] += t - tph;
            tph = t;
        };
        if (stats) {
            ++cpu_calls;
            cpu_ents += (long) ents.size();
            for (const Ent& en : ents) cpu_rows += en.n;
        }
        if (l.packed_host) return cpu_experts_packed(l, x, ents, ldx, ord);
        if (l.lay.fmt == gg::kFmtMXFP4) return cpu_experts_mx(l, x, ents, ldx, ord);
        const int E = g.dim, FF = g.ff;
        Exl3Lane& c = lane_x;
        c.E = E;
        c.FF = FF;
        c.NH = NH;
        c.slots = kSlots;
        c.lim = g.lim;
        c.xh = c_xh.data();
        c.xsb = c_xsb.data();
        c.acc = c_acc.data();
        c.xhd = c_xhd.data();
        c.xsd = c_xsd.data();
        c.accd = c_accd.data();
        c.yd = c_yd.data();
        if (!c.cnt) c.alloc_counters(2);
        auto part = [&](int e, int X, int r) {
            const uint8_t* b = l.hh[(size_t) e][(size_t) X];
            kc::Exl3Part p;
            p.trellis = (const uint32_t*) (b + l.hl.trellis[r]);
            p.suh = (const uint16_t*) (b + l.hl.suh[r]);
            p.svh = (const uint16_t*) (b + l.hl.svh[r]);
            p.k = l.hl.k[r];
            p.n = l.hl.n[r];
            p.k2 = l.lay.k2[r];
            return p;
        };
        auto nodes = [&](int n, const std::function<void(int)>* f, int ph) { run_nodes(n, f, ph); };
        // DS4_CPU_FLOW=0: the four steps as four batches (as before); DS4_CPU_STATS times them, so it takes them too.
        // DS4_CPU_FLOW_CHECK=1: each call's flow outputs against the steps', bit for bit (twice the time)
        static const bool flow_on =
            !stats && (std::getenv("DS4_CPU_FLOW") == nullptr || std::atoi(std::getenv("DS4_CPU_FLOW")) != 0);
        static const bool flow_check = flow_on && std::getenv("DS4_CPU_FLOW_CHECK") != nullptr;
        const int ne = (int) ents.size();
        exl3_experts(c, x, ldx, ents.data(), ne, part, nodes, phase, flow_on);
        if (flow_check && ne > 0) {
            int rows = 0;
            for (const Ent& en : ents) rows = std::max(rows, en.slot0 + en.n);
            std::vector<float> fl(c_yd.begin(), c_yd.begin() + (size_t) rows * E);
            exl3_experts(c, x, ldx, ents.data(), ne, part, nodes, phase, false);
            const bool bad = std::memcmp(fl.data(), c_yd.data(), fl.size() * 4) != 0;
            static std::atomic<long long> calls{0}, diffs{0};
            if (bad) ++diffs;
            const long long nc = ++calls;
            if (nc % 256 == 0 || bad)
                std::fprintf(stderr, "ds4: CPU flow check: %lld calls, %lld differed\n", nc, diffs.load());
        }
    }

    // ---- the expert cache.  A swap moves a CPU-lane expert (`in`) into the layer's spare VRAM slot and the VRAM expert it
    // replaces (`out`) into the spare host parts - both copies of weights that do not change, made while the model runs
    // (the copy stream, the host's repacking) - and cache_tick switches the tables between windows, so the device's
    // table and the host's view of a layer always agree within a window.  In place (file_experts) `out` needs no copy:
    // the CPU lane reads it from the file again.
    void ram_loop() {   // the RAM tier's moves in: an expert read from the file into a free slot
        for (;;) {
            RamSwap rs;
            {
                std::unique_lock<std::mutex> lk(sw_mu);
                ram_cv.wait(lk, [&] { return quit.load() || !ram_queue.empty(); });
                if (quit.load()) return;
                rs = ram_queue.front();
                ram_queue.pop_front();
            }
            const Layer& l = L[(size_t) rs.layer];
            if (read_mx_file(l, rs.in, ram_slots[(size_t) rs.slot])) {
                for (int r = 0; r < 3; ++r)   // (one copy of it in RAM)
                    os::advise(pk.fds[(size_t) l.mx_file[r]], l.mx_off[r] + (uint64_t) rs.in * l.mx_stride[r],
                               mx_part_bytes(l, r), false);
            } else {
                rs.in = -1;   // (failed: the slot goes back)
            }
            std::lock_guard<std::mutex> lk(sw_mu);
            ram_ready.push_back(rs);
        }
    }

    void cache_loop(SwapBufs& B) {
        const bool direct_packed = env_f("DS4_EXL3_DIRECT_SWAPS", 0) != 0;
        for (;;) {
            Swap sw;
            {
                std::unique_lock<std::mutex> lk(sw_mu);
                sw_cv.wait(lk, [&] { return quit.load() || !sw_queue.empty(); });
                if (quit.load()) return;
                sw = sw_queue.front();
                sw_queue.pop_front();
            }
            Layer& l = L[(size_t) sw.layer];
            if (l.lay.fmt == gg::kFmtMXFP4) {   // in: from the file; out: nothing to keep (the file has it)
                swap_in_mx(l, sw, B);
                std::lock_guard<std::mutex> lk(sw_mu);
                sw_ready.push_back(sw);
                continue;
            }
            auto off_turn = [&](int di, cudaStream_t cs) {   // (false: quitting)
                while (!copy_open(di, sw.win)) {
                    if (quit.load()) return false;
                    std::this_thread::sleep_for(std::chrono::microseconds(50));
                }
                copy_after_idle(di, cs);
                return true;
            };
            if (direct_packed && l.packed_host && NH == 1 && !file_experts && l.nm == 2 &&
                member(l, 0).hblob == member(l, 1).hblob) {
                // Packed host slots already contain the members' GPU-ready blobs.
                // The incoming host and outgoing VRAM slots stay owned until
                // publication; spare_host is private to this pending swap.
                auto checked = [&](cudaError_t status) {
                    if (status != cudaSuccess) {
                        std::fprintf(stderr, "ds4: direct packed swap failed at layer %d: %s\n",
                                     l.il, cudaGetErrorString(status));
                        std::abort();
                    }
                };
                // A quit can arrive between member submissions; drain issued
                // transfers before the cache thread releases its buffers.
                auto drain = [&] {
                    for (int m = 0; m < l.nm; ++m) {
                        const Layer& x = member(l, m);
                        checked(cudaSetDevice(devs[(size_t) x.dev].id));
                        checked(cudaStreamSynchronize(B.st[(size_t) x.dev]));
                    }
                };
                for (int m = 0; m < l.nm; ++m) {
                    const Layer& x = member(l, m);
                    checked(cudaSetDevice(devs[(size_t) x.dev].id));
                    const size_t offset = (size_t) m * l.hblob;
                    cudaStream_t cs = B.st[(size_t) x.dev];
                    if (!off_turn(x.dev, cs)) {
                        drain();
                        return;
                    }
                    checked(cudaMemcpyAsync(sat(l, x, l.spare_vram, x.hblob),
                                            l.hh[(size_t) sw.in][0] + offset, x.hblob,
                                            cudaMemcpyHostToDevice, cs));
                    if (!off_turn(x.dev, cs)) {
                        drain();
                        return;
                    }
                    checked(cudaMemcpyAsync(l.spare_host[0] + offset,
                                            sat(l, x, l.slot[(size_t) sw.out], x.hblob), x.hblob,
                                            cudaMemcpyDeviceToHost, cs));
                }
                drain();
                if (check_swaps)
                    std::fprintf(stderr, "ds4 direct packed swap: layer %d expert %d in, %d out\n",
                                 l.il, sw.in, sw.out);
            } else {
                parts_to_blob(l, l.hh[(size_t) sw.in], B.a);
                if (l.nm == 1) {
                    const Dev& d = devs[(size_t) l.dev];
                    cudaSetDevice(d.id);
                    cudaStream_t cs = B.st[(size_t) l.dev];
                    if (!off_turn(l.dev, cs)) return;
                    cudaMemcpyAsync(sat(l, l, l.spare_vram, l.blob), B.a, l.blob, cudaMemcpyHostToDevice, cs);
                    if (!file_experts)
                        cudaMemcpyAsync(B.b, sat(l, l, l.slot[(size_t) sw.out], l.blob), l.blob,
                                        cudaMemcpyDeviceToHost, cs);
                    cudaStreamSynchronize(cs);
                } else {   // a group: each member's part in, each member's part out
                    for (int m = 0; m < l.nm; ++m) {
                        const Layer& x = member(l, m);
                        cudaSetDevice(devs[(size_t) x.dev].id);
                        cudaStream_t cs = B.st[(size_t) x.dev];
                        blob_to_half(l, B.a, m, B.h);
                        if (!off_turn(x.dev, cs)) return;
                        cudaMemcpyAsync(sat(l, x, l.spare_vram, x.hblob), B.h, x.hblob, cudaMemcpyHostToDevice, cs);
                        cudaStreamSynchronize(cs);
                        if (file_experts) continue;
                        if (!off_turn(x.dev, cs)) return;
                        cudaMemcpyAsync(B.h, sat(l, x, l.slot[(size_t) sw.out], x.hblob), x.hblob,
                                        cudaMemcpyDeviceToHost, cs);
                        cudaStreamSynchronize(cs);
                        half_to_blob(l, B.h, m, B.b);
                    }
                }
                if (!file_experts)
                    for (int X = 0; X < NH; ++X) blob_to_part(l, B.b, X, l.spare_host[(size_t) X]);
            }
            if (check_swaps) {   // DS4_CHECK_SWAPS: both moves against the model file, byte for byte
                std::vector<uint8_t> reg, blob(l.blob), part(l.hl.bytes);
                bool ok = true;
                for (int pass = 0; pass < (file_experts ? 1 : 2); ++pass) {   // (in place: no host copy of `out`)
                    const int e = pass == 0 ? sw.in : sw.out;
                    reg.resize(l.region_bytes[(size_t) e]);
                    pk.read_at(l.region_file[(size_t) e], l.region_off[(size_t) e], reg.size(), reg.data());
                    if (pass == 0) {
                        repack(l, e, reg.data(), blob.data());
                        std::vector<uint8_t> dev(l.blob);
                        if (l.nm == 1)
                            cudaMemcpy(dev.data(), sat(l, l, l.spare_vram, l.blob), l.blob, cudaMemcpyDeviceToHost);
                        else
                            for (int m = 0; m < l.nm; ++m) {   // (the members' parts, put together again)
                                std::vector<uint8_t> h(member(l, m).hblob);
                                cudaSetDevice(devs[(size_t) member(l, m).dev].id);
                                cudaMemcpy(h.data(), sat(l, member(l, m), l.spare_vram, member(l, m).hblob), member(l, m).hblob,
                                           cudaMemcpyDeviceToHost);
                                half_to_blob(l, h.data(), m, dev.data());
                            }
                        for (int r = 0; r < 3; ++r)
                            ok = ok && std::memcmp(dev.data() + l.lay.trellis[r], blob.data() + l.lay.trellis[r], l.piece_bytes[r][0]) == 0 &&
                                 std::memcmp(dev.data() + l.lay.suh[r], blob.data() + l.lay.suh[r], l.piece_bytes[r][1]) == 0 &&
                                 std::memcmp(dev.data() + l.lay.svh[r], blob.data() + l.lay.svh[r], l.piece_bytes[r][2]) == 0;
                    } else if (l.packed_host) {
                        repack(l, e, reg.data(), blob.data());
                        std::vector<uint8_t> actual(l.blob);
                        parts_to_blob(l, l.spare_host, actual.data());
                        for (int r = 0; r < 3; ++r)
                            ok = ok && std::memcmp(actual.data() + l.lay.trellis[r], blob.data() + l.lay.trellis[r], l.piece_bytes[r][0]) == 0 &&
                                 std::memcmp(actual.data() + l.lay.suh[r], blob.data() + l.lay.suh[r], l.piece_bytes[r][1]) == 0 &&
                                 std::memcmp(actual.data() + l.lay.svh[r], blob.data() + l.lay.svh[r], l.piece_bytes[r][2]) == 0;
                    } else {
                        for (int X = 0; X < NH; ++X) {
                            repack_part(l, reg.data(), X, part.data());
                            for (int r = 0; r < 3; ++r) {
                                const size_t tb = (size_t) (l.hl.k[r] / 16) * (l.hl.n[r] / 16) * 16 * l.lay.k2[r];
                                ok = ok && std::memcmp(part.data() + l.hl.trellis[r], l.spare_host[(size_t) X] + l.hl.trellis[r], tb) == 0 &&
                                     std::memcmp(part.data() + l.hl.suh[r], l.spare_host[(size_t) X] + l.hl.suh[r], (size_t) l.hl.k[r] * 2) == 0 &&
                                     std::memcmp(part.data() + l.hl.svh[r], l.spare_host[(size_t) X] + l.hl.svh[r], (size_t) l.hl.n[r] * 2) == 0;
                            }
                        }
                    }
                }
                std::fprintf(stderr, "ds4 cache: layer %d expert %d in, %d out: %s\n", l.il, sw.in, sw.out,
                             ok ? "both match the model file" : "MISMATCH");
            }
            std::lock_guard<std::mutex> lk(sw_mu);
            sw_ready.push_back(sw);
        }
    }

    void rc_loop() {
        std::vector<RcJob> fly;     // issued, not yet done
        std::deque<RcJob> held;     // waiting for their group's turn to end (copy_open)
        std::string err;
        for (;;) {
            {
                std::unique_lock<std::mutex> lk(rc_mu);
                if (fly.empty() && held.empty()) rc_cv.wait(lk, [&] { return quit.load() || !rc_q.empty(); });
                if (quit.load()) return;
                for (const RcJob& j : rc_q) held.push_back(j);
                rc_q.clear();
            }
            for (size_t i = 0; i < held.size();) {
                const RcJob j = held[i];
                Layer& l = L[(size_t) j.layer];
                bool open = true;   // (a layer's members are one group's)
                for (int m = 0; m < l.nm && open; ++m) open = copy_open(member(l, m).dev, j.win);
                if (!open) {
                    ++i;
                    continue;
                }
                for (int m = 0; m < l.nm; ++m) {
                    Layer& x = member(l, m);
                    const int di = x.dev;
                    cudaSetDevice(devs[(size_t) di].id);
                    cudaStreamWaitEvent(rc_cs[(size_t) di], rc_go[(size_t) di], 0);   // (after the tick's tables)
                    copy_after_idle(di, rc_cs[(size_t) di]);
                    stream_expert(l, m, j.expert, sat(l, x, l.rc_base + j.slot, unit(x)), rc_cs[(size_t) di], err);
                    cudaEventRecord(l.rc_ev[(size_t) j.slot * l.nm + m], rc_cs[(size_t) di]);
                }
                fly.push_back(j);
                held.erase(held.begin() + (std::ptrdiff_t) i);
            }
            for (size_t i = 0; i < fly.size();) {   // the ones whose copies are all done: marked
                const RcJob& j = fly[i];
                Layer& l = L[(size_t) j.layer];
                bool done = true;
                for (int m = 0; m < l.nm && done; ++m) {
                    cudaSetDevice(devs[(size_t) member(l, m).dev].id);
                    done = cudaEventQuery(l.rc_ev[(size_t) j.slot * l.nm + m]) == cudaSuccess;
                }
                if (done) {
                    rc_done[(size_t) (l.rc_off + j.slot)].store(j.gen, std::memory_order_release);
                    rc_pending.fetch_sub(1);
                    fly[i] = fly.back();
                    fly.pop_back();
                } else
                    ++i;
            }
            if (!fly.empty() || !held.empty()) std::this_thread::sleep_for(std::chrono::microseconds(held.empty() ? 200 : 50));
        }
    }

    // before a run of chunks borrows the tail (borrow_begin): the recent slots lie in it, so no fill may still be
    // writing there - every one waited for, then the fills done and the window's landings mapped (no new fills): the
    // run's buffers then cover only mapped experts, which borrow_end reads back like any other VRAM one
    // At most kRcDrainMs: a fill held for its device's next turn (copy_open - none comes while the prompt waits here) or
    // a stalled copy must not hang the prompt, so past it the prompt goes on as in v1.1.27 (no wait, nothing mapped
    // now: the next tick maps what landed).  The wait itself makes no GPU call.
    static constexpr double kRcDrainMs = 5000.0;
    void rc_drain() {
        if (recent_n <= 0 || rc_cs.empty()) return;
        const double t0 = now_ms();
        while (rc_pending.load() > 0) {
            if (now_ms() - t0 > kRcDrainMs) {
                static std::atomic<bool> said{false};
                if (!said.exchange(true))
                    std::fprintf(stderr, "ds4: recent slots: %d fills still running %.0f ms before a prompt - the prompt goes "
                                         "on without waiting for them\n", rc_pending.load(), now_ms() - t0);
                return;
            }
            std::this_thread::sleep_for(std::chrono::microseconds(100));
        }
        tick_begin();
        rc_tick(false);
        tick_flush();
    }
    void rc_tick(bool start_fills = true) {
        if (recent_n <= 0) return;
        const double t_tick = now_ms();
        struct Tm {
            Model::Impl* m;
            double t;
            ~Tm() {
                m->rc_tick_ms += now_ms() - t;
                ++m->rc_ticks;
            }
        } tm{this, t_tick};
        if (rc_cs.empty()) {
            if (!tab_bufs()) return;
            rc_cs.assign(devs.size(), nullptr);
            for (size_t di = 0; di < devs.size(); ++di) {
                cudaSetDevice(devs[di].id);
                cudaStreamCreateWithFlags(&rc_cs[di], cudaStreamNonBlocking);
            }
            int off = 0;
            for (Layer& l : L) {
                l.rc_off = off;
                off += l.rc_n;
            }
            rc_done.reset(new std::atomic<unsigned>[(size_t) std::max(1, off)]);
            for (int i = 0; i < off; ++i) rc_done[(size_t) i].store(0u);
            rc_th = std::thread([this] { rc_loop(); });
        }
        const unsigned now = rc_clock.fetch_add(1, std::memory_order_relaxed) + 1;
        std::vector<std::vector<unsigned long long>>& upd = tick_upd;
        std::vector<RcJob>& jobs = tick_jobs;
        for (Layer& l : L) {
            if (l.rc_n == 0) continue;
            const int nm = l.nm;
            auto set_tab = [&](int e, int i) {   // (i < 0: out of VRAM)
                for (int m = 0; m < nm; ++m) {
                    Layer& x = member(l, m);
                    upd[(size_t) x.dev].push_back((unsigned long long) (x.vram_tab + e));
                    upd[(size_t) x.dev].push_back(i < 0 ? 0ull : l.rc_pin[(size_t) i * nm + m]);
                }
            };
            for (int i = 0; i < l.rc_n; ++i) {   // the window's landings (rc_land): the slot's old expert out, the new in
                const int e = l.rc_land[(size_t) i];
                if (e < 0) continue;
                l.rc_land[(size_t) i] = -1;
                const int old = l.rc_exp[(size_t) i];
                if (old >= 0 && l.slot[(size_t) old] == l.rc_base + i) {   // (its bytes are gone either way)
                    l.slot[(size_t) old] = -1;
                    set_tab(old, -1);
                }
                l.rc_exp[(size_t) i] = -1;
                const pcie::Pull* P = ln_pull + l.rc_lseq[(size_t) i] % kRing;
                const int q = l.rc_lq[(size_t) i];
                if (*(volatile const unsigned*) &P->done != l.rc_lseq[(size_t) i] || P->bad[q] != 0u ||
                    l.slot[(size_t) e] >= 0)
                    continue;
                l.slot[(size_t) e] = l.rc_base + i;
                l.rc_exp[(size_t) i] = e;
                l.rc_stamp[(size_t) i] = now;
                if (nm == 1) set_vm(l, e, l.rc_base + i);
                set_tab(e, i);
                ++rc_lands;
                if (check_swaps) {   // DS4_CHECK_SWAPS: the landed slot against the model file, byte for byte
                    std::vector<uint8_t> want(l.blob), dev(l.blob);
                    bool ok = read_mx_file(l, e, want.data());
                    cudaSetDevice(devs[(size_t) l.dev].id);
                    cudaMemcpy(dev.data(), (const void*) l.rc_pin[(size_t) i], l.blob, cudaMemcpyDeviceToHost);
                    for (int r = 0; r < 3; ++r)
                        ok = ok && std::memcmp(dev.data() + l.lay.trellis[r], want.data() + l.lay.trellis[r],
                                               mx_part_bytes(l, r)) == 0;
                    std::fprintf(stderr, "ds4 landing: layer %d expert %d in slot %d: %s\n", l.il, e, l.rc_base + i,
                                 ok ? "matches the model file" : "MISMATCH");
                }
            }
            for (int i = 0; i < l.rc_n; ++i) {   // the fills done: mapped (unless a swap took the expert in meanwhile)
                const int e = l.rc_fill[(size_t) i];
                if (e < 0 || rc_done[(size_t) (l.rc_off + i)].load(std::memory_order_acquire) != l.rc_gen[(size_t) i]) continue;
                l.rc_fill[(size_t) i] = -1;
                if (l.slot[(size_t) e] >= 0) continue;
                l.slot[(size_t) e] = l.rc_base + i;
                l.rc_exp[(size_t) i] = e;
                l.rc_stamp[(size_t) i] = now;
                if (nm == 1) set_vm(l, e, l.rc_base + i);
                set_tab(e, i);
                ++rc_fills_done;
                if (check_swaps && l.lay.fmt == gg::kFmtMXFP4 && nm == 1) {   // (a GGUF's: its blob, as a landing's)
                    std::vector<uint8_t> want(l.blob), dev(l.blob);
                    bool ok = read_mx_file(l, e, want.data());
                    cudaSetDevice(devs[(size_t) l.dev].id);
                    cudaMemcpy(dev.data(), (const void*) l.rc_pin[(size_t) i], l.blob, cudaMemcpyDeviceToHost);
                    for (int r = 0; r < 3; ++r)
                        ok = ok && std::memcmp(dev.data() + l.lay.trellis[r], want.data() + l.lay.trellis[r],
                                               mx_part_bytes(l, r)) == 0;
                    std::fprintf(stderr, "ds4 recent: layer %d expert %d in slot %d: %s\n", l.il, e, l.rc_base + i,
                                 ok ? "matches the model file" : "MISMATCH");
                } else if (check_swaps) {   // DS4_CHECK_SWAPS: the slot against the model file, byte for byte
                    std::vector<uint8_t> reg(l.region_bytes[(size_t) e]), want(l.blob), dev(l.blob);
                    pk.read_at(l.region_file[(size_t) e], l.region_off[(size_t) e], reg.size(), reg.data());
                    repack(l, e, reg.data(), want.data());
                    if (nm == 1) {
                        cudaSetDevice(devs[(size_t) l.dev].id);
                        cudaMemcpy(dev.data(), (const void*) l.rc_pin[(size_t) i], l.blob, cudaMemcpyDeviceToHost);
                    } else
                        for (int m = 0; m < nm; ++m) {
                            std::vector<uint8_t> h(member(l, m).hblob);
                            cudaSetDevice(devs[(size_t) member(l, m).dev].id);
                            cudaMemcpy(h.data(), (const void*) l.rc_pin[(size_t) i * nm + m],
                                       member(l, m).hblob, cudaMemcpyDeviceToHost);
                            half_to_blob(l, h.data(), m, dev.data());
                        }
                    bool ok = true;
                    for (int r = 0; r < 3; ++r)
                        ok = ok && std::memcmp(dev.data() + l.lay.trellis[r], want.data() + l.lay.trellis[r], l.piece_bytes[r][0]) == 0 &&
                             std::memcmp(dev.data() + l.lay.suh[r], want.data() + l.lay.suh[r], l.piece_bytes[r][1]) == 0 &&
                             std::memcmp(dev.data() + l.lay.svh[r], want.data() + l.lay.svh[r], l.piece_bytes[r][2]) == 0;
                    std::fprintf(stderr, "ds4 recent: layer %d expert %d in slot %d: %s\n", l.il, e, l.rc_base + i,
                                 ok ? "matches the model file" : "MISMATCH");
                }
            }
            {   // this tick's CPU-lane experts into the history
                std::vector<int> cur(l.cpu_hits.begin(), l.cpu_hits.end());
                std::sort(cur.begin(), cur.end());
                cur.erase(std::unique(cur.begin(), cur.end()), cur.end());
                l.rc_hist.push_back(std::move(cur));
                while ((int) l.rc_hist.size() > recent_win) l.rc_hist.pop_front();
            }
            int started = 0;
            for (size_t h = l.cpu_hits.size(); start_fills && h-- > 0 && started < recent_fills;) {   // (latest first)
                const int e = l.cpu_hits[h];
                if (e < 0 || e >= l.n_exp || l.slot[(size_t) e] >= 0 || e == l.sw_in) continue;
                int uses = 0;
                for (const std::vector<int>& hv : l.rc_hist) uses += std::binary_search(hv.begin(), hv.end(), e) ? 1 : 0;
                if (uses < recent_need) continue;
                bool filling = false;
                for (int i = 0; i < l.rc_n; ++i) filling = filling || l.rc_fill[(size_t) i] == e;
                if (filling) continue;
                int v = -1;   // an empty slot, else the least recently used one not filling
                for (int i = 0; i < l.rc_n && v < 0; ++i)
                    if (l.rc_fill[(size_t) i] < 0 && l.rc_land[(size_t) i] < 0 && l.rc_exp[(size_t) i] < 0) v = i;
                if (v < 0)
                    for (int i = 0; i < l.rc_n; ++i)
                        if (l.rc_fill[(size_t) i] < 0 && l.rc_land[(size_t) i] < 0 &&
                            (v < 0 || l.rc_stamp[(size_t) i] < l.rc_stamp[(size_t) v]))
                            v = i;
                if (v < 0) break;
                if (l.rc_exp[(size_t) v] >= 0) {   // (out: its table entry, before the next window)
                    const int old = l.rc_exp[(size_t) v];
                    l.slot[(size_t) old] = -1;
                    set_tab(old, -1);
                    l.rc_exp[(size_t) v] = -1;
                }
                l.rc_fill[(size_t) v] = e;
                l.rc_gen[(size_t) v] = now;
                jobs.push_back({l.il, v, e, now, win_now.load(std::memory_order_relaxed)});
                ++started;
                ++rc_fills_started;
            }
        }
    }

    // a tick's table entries (the recent slots', the swaps'): one launch a device, before the next window; then rc_go
    // there (the fills after it).  (A copy of each entry on its own was ~10 us of the host's, 48 of them 0.5 ms between
    // two windows)
    std::vector<std::vector<unsigned long long>> tick_upd;   // [device]: (entry, value) pairs
    std::vector<RcJob> tick_jobs;
    bool tab_bufs() {
        if (!rc_upd.empty()) return true;
        std::string e0;
        rc_go.assign(devs.size(), nullptr);
        rc_upd.assign(devs.size(), nullptr);
        for (size_t di = 0; di < devs.size(); ++di) {
            cudaSetDevice(devs[di].id);
            cudaEventCreateWithFlags(&rc_go[di], cudaEventDisableTiming);
            if (!hmap(rc_upd[di], (size_t) 2 * kRcUpd, e0)) {
                rc_upd.clear();
                return false;
            }
        }
        return true;
    }
    void tick_flush() {
        const std::vector<RcJob>& jobs = tick_jobs;
        bool any = !jobs.empty();
        for (const auto& u : tick_upd) any = any || !u.empty();
        if (!any || !tab_bufs()) return;
        for (size_t di = 0; di < devs.size(); ++di) {
            const std::vector<unsigned long long>& u = tick_upd[di];
            if (u.empty() && jobs.empty()) continue;
            cudaSetDevice(devs[di].id);
            const int n = (int) std::min<size_t>(u.size() / 2, (size_t) kRcUpd);
            if (n > 0) {
                std::memcpy(rc_upd[di], u.data(), (size_t) n * 16);
                tab_set(rc_upd[di], n, devs[di].st);
            }
            cudaEventRecord(rc_go[di], devs[di].st);
        }
        if (!jobs.empty()) {
            {
                std::lock_guard<std::mutex> lk(rc_mu);
                for (const RcJob& j : jobs) rc_q.push_back(j);
            }
            rc_pending.fetch_add((int) jobs.size());
            rc_cv.notify_one();
        }
    }

    // a GGUF's swap: expert sw.in from the file (copy_mode: its copy) into the spare VRAM slot (each member its part);
    // the expert it replaces goes back to the CPU lane, which reads it from the file's mapping - or (copy_mode, sw.ram)
    // from the layer's spare RAM slot, which it is copied into from VRAM here
    void swap_in_mx(Layer& l, Swap& sw, SwapBufs& B) {
        uint8_t *sw_a = B.a, *sw_b = B.b, *sw_h = B.h;   // (this thread's)
        const std::vector<cudaStream_t>& copy_st = B.st;
        bool ok = copy_mode ? read_mx(l, sw.in, sw_a) : read_mx_file(l, sw.in, sw_a);   // (a copy holds its slot till
                                                                                          // this swap's switch)
        for (int m = 0; m < l.nm && ok; ++m) {
            const Layer& x = member(l, m);
            cudaSetDevice(devs[(size_t) x.dev].id);
            cudaStream_t cs = copy_st[(size_t) x.dev];
            if (l.nm > 1) blob_to_half(l, sw_a, m, sw_h);
            ok = cudaMemcpyAsync(sat(l, x, l.spare_vram, unit(x)), l.nm > 1 ? sw_h : sw_a, unit(x),
                                 cudaMemcpyHostToDevice, cs) == cudaSuccess &&
                 cudaStreamSynchronize(cs) == cudaSuccess;
        }
        if (sw.ram >= 0) {   // `out` from its VRAM slot (each member its part) into the spare RAM slot
            bool got = ok;
            for (int m = 0; m < l.nm && got; ++m) {
                const Layer& x = member(l, m);
                cudaSetDevice(devs[(size_t) x.dev].id);
                cudaStream_t cs = copy_st[(size_t) x.dev];
                got = cudaMemcpyAsync(l.nm > 1 ? sw_h : sw_b, sat(l, x, l.slot[(size_t) sw.out], unit(x)),
                                      unit(x), cudaMemcpyDeviceToHost, cs) == cudaSuccess &&
                      cudaStreamSynchronize(cs) == cudaSuccess;
                if (got && l.nm > 1) half_to_blob(l, sw_h, m, sw_b);
            }
            if (got) blob_to_ram(l, sw_b, sw.ram);
            else sw.ram = -1;   // (back to the file's pages then)
        }
        if (check_swaps) {   // DS4_CHECK_SWAPS: the slot (and `out`'s RAM copy) against the model file, byte for byte
            std::vector<uint8_t> dev(l.blob), h(l.blob), file(l.blob);   // (h: the widest member's part fits)
            for (int m = 0; m < l.nm && ok; ++m) {
                const Layer& x = member(l, m);
                cudaSetDevice(devs[(size_t) x.dev].id);
                cudaMemcpy(l.nm > 1 ? h.data() : dev.data(), sat(l, x, l.spare_vram, unit(x)), unit(x),
                           cudaMemcpyDeviceToHost);
                if (l.nm > 1) half_to_blob(l, h.data(), m, dev.data());
            }
            ok = ok && read_mx_file(l, sw.in, file.data());
            for (int r = 0; r < 3 && ok; ++r)
                ok = std::memcmp(dev.data() + l.lay.trellis[r], file.data() + l.lay.trellis[r], mx_part_bytes(l, r)) == 0;
            bool ok_out = true;
            if (sw.ram >= 0) {
                ok_out = read_mx_file(l, sw.out, file.data());
                ram_to_blob(l, sw.ram, dev.data());
                for (int r = 0; r < 3 && ok_out; ++r)
                    ok_out = std::memcmp(dev.data() + l.lay.trellis[r], file.data() + l.lay.trellis[r], mx_part_bytes(l, r)) == 0;
            }
            std::fprintf(stderr, "ds4 cache: layer %d expert %d in, %d out%s: %s\n", l.il, sw.in, sw.out,
                         sw.ram >= 0 ? " (into RAM)" : "", ok && ok_out ? "matches the model file" : "MISMATCH");
        } else if (!ok) {
            std::fprintf(stderr, "ds4 cache: layer %d expert %d: the move into VRAM failed\n", l.il, sw.in);
        }
    }

    // a tick's table entries start empty, and go to the devices in tick_flush (the recent slots' and the swaps')
    void tick_begin() {
        tick_upd.resize(devs.size());
        for (auto& u : tick_upd) u.clear();
        tick_jobs.clear();
    }
    void cache_tick(int T) {
        tick_begin();
        rc_tick();
        hr_tick(T);   // (DS4_HELPER_RECENT: before the swaps, whose queue takes this window's CPU-lane hits)
        swap_tick(T);
        tick_flush();
    }
    // (DS4_COPY_SWAP) the moves read in, switched while nothing reads the copies (between windows)
    void cs_switch() {
        std::vector<CSwap> rd;
        {
            std::lock_guard<std::mutex> lk(cs_mu);
            rd.swap(cs_ready);
        }
        for (const CSwap& c : rd) {
            Layer& l = L[(size_t) c.layer];
            --cs_inflight;
            if (!c.ok || l.ram[(size_t) c.in] >= 0 || l.slot[(size_t) c.in] >= 0 || l.ram[(size_t) c.out] < 0 ||
                l.slot[(size_t) c.out] >= 0 || l.swap_pending) {
                cs_free[(size_t) c.layer] = c.slot;   // (things moved meanwhile: the slot back, nothing switched)
                continue;
            }
            l.ram[(size_t) c.in] = c.slot;
            cs_free[(size_t) c.layer] = l.ram[(size_t) c.out];
            l.ram[(size_t) c.out] = -1;
            ++cs_done;
        }
    }
    void cs_loop() {
        for (;;) {
            CSwap c;
            {
                std::unique_lock<std::mutex> lk(cs_mu);
                cs_cv.wait(lk, [&] { return cs_quit || !cs_q.empty(); });
                if (cs_quit) return;
                c = cs_q.front();
                cs_q.pop_front();
            }
            const Layer& l = L[(size_t) c.layer];
            bool ok = true;
            for (int r = 0; r < 3 && ok; ++r) {
                const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
                for (int X = 0; X < NH && ok; ++X)
                    ok = pk.read_at(l.mx_file[r], l.mx_off[r] + (uint64_t) c.in * l.mx_stride[r] + (uint64_t) X * nb, nb,
                                    ram_part[(size_t) c.slot][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r]);
            }
            c.ok = ok;
            std::lock_guard<std::mutex> lk(cs_mu);
            cs_ready.push_back(c);
        }
    }
    void swap_tick(int T) {
        if (copy_swap && copy_mode) {
            cs_switch();
            cs_since += T;
        }
        // (DISK_SKIP_W: every 512 decoded tokens the log gets the experts a token left out, and the copy swaps)
        if (T == 1 && disk_skip_w > 0.0f && ++sk_tok % 512 == 0) {
            std::fprintf(stderr, "ds4: DISK_SKIP: %.2f experts a token left out over the last 512 tokens, %lld copy swaps\n",
                         (double) (st.skipped - sk_last) / 512.0, cs_done - cs_last);
            sk_last = st.skipped;
            cs_last = cs_done;
        }
        if (!o.expert_cache || cache_ths.empty()) return;
        cache_switch();
        decay_tokens += T;
        if (decay_tokens >= 256) {   // older use counts less: x0.9 every 256 tokens
            decay_tokens = 0;
            for (Layer& l : L)
                for (float& h : l.heat) h *= c_decay;
        }
        cache_queue();
    }
    // the swaps under way waited for and switched in: before a run of chunks lends the tail its slots (a swap's copy
    // into the spare slot, or out of the slot it frees, must not meet the run's buffers there)
    void cache_drain() {
        if (!o.expert_cache || cache_ths.empty()) return;
        for (;;) {
            {
                std::lock_guard<std::mutex> lk(sw_mu);
                if (sw_queue.empty() && (int) sw_ready.size() >= sw_inflight) break;
            }
            std::this_thread::sleep_for(std::chrono::microseconds(200));
        }
        tick_begin();
        cache_switch();
        tick_flush();
    }
    // the moves that landed, switched in (between windows: nothing reads the tables or the tier meanwhile)
    void cache_switch() {
        std::vector<Swap> ready;
        std::vector<RamSwap> rready;
        {
            std::lock_guard<std::mutex> lk(sw_mu);
            ready.swap(sw_ready);
            rready.swap(ram_ready);
        }
        for (const RamSwap& rs : rready) {   // (nothing reads the tier between windows)
            --ram_inflight;
            Layer& l = L[(size_t) rs.layer];
            if (rs.in < 0 || l.ram[(size_t) rs.in] >= 0 || l.slot[(size_t) rs.in] >= 0) {
                ram_free.push_back(rs.slot);
                continue;
            }
            l.ram[(size_t) rs.in] = rs.slot;
            if (rs.out >= 0 && l.ram[(size_t) rs.out] >= 0) {
                ram_free.push_back(l.ram[(size_t) rs.out]);
                l.ram[(size_t) rs.out] = -1;
            }
            ++st.ram_moves;
        }
        for (const Swap& sw : ready) {
            Layer& l = L[(size_t) sw.layer];
            const int old_slot = l.slot[(size_t) sw.out];
            const std::array<uint8_t*, 4> old_parts = l.hh[(size_t) sw.in];
            if (copy_mode) {   // (`out` takes the RAM place `in` leaves: through the spare, which `in`'s slot becomes)
                const int s_in = l.ram[(size_t) sw.in];
                l.ram[(size_t) sw.in] = -1;
                if (sw.ram >= 0) {
                    l.ram[(size_t) sw.out] = sw.ram;
                    copy_spare[(size_t) l.il] = s_in;
                } else if (s_in >= 0) {   // (the move into RAM failed: `out` back to the file, one copy fewer)
                    --ram_held;
                    if (copy_spare[(size_t) l.il] < 0) copy_spare[(size_t) l.il] = s_in;
                }
            } else if (!l.ram.empty() && l.ram[(size_t) sw.in] >= 0) {   // (in VRAM now: its RAM slot for the next hottest)
                ram_free.push_back(l.ram[(size_t) sw.in]);
                l.ram[(size_t) sw.in] = -1;
            }
            l.slot[(size_t) sw.in] = l.spare_vram;
            if (l.nm == 1) set_vm(l, sw.in, l.spare_vram);
            l.hh[(size_t) sw.in] = {nullptr, nullptr, nullptr, nullptr};
            l.host[(size_t) sw.in] = nullptr;
            l.slot[(size_t) sw.out] = -1;
            if (l.lay.fmt == gg::kFmtMXFP4) {   // (the file has it)
                l.host[(size_t) sw.out] = (uint8_t*) mx_mat(l, sw.out, 0);
            } else if (file_experts) {   // (back to its pages in the file)
                l.hh[(size_t) sw.out] = {file_part(l, sw.out), nullptr, nullptr, nullptr};
                l.host[(size_t) sw.out] = l.hh[(size_t) sw.out][0];
            } else {
                l.hh[(size_t) sw.out] = l.spare_host;
                l.host[(size_t) sw.out] = l.spare_host[0];
                l.spare_host = old_parts;
            }
            l.spare_vram = old_slot;
            for (int m = 0; m < l.nm; ++m) {   // (tick_flush: stream order, before the next window)
                Layer& x = member(l, m);
                std::vector<unsigned long long>& u = tick_upd[(size_t) x.dev];
                u.push_back((unsigned long long) (x.vram_tab + sw.in));
                u.push_back((unsigned long long) sat(l, x, l.slot[(size_t) sw.in], unit(x)));
                u.push_back((unsigned long long) (x.vram_tab + sw.out));
                u.push_back(0ull);
            }
            l.swap_pending = false;
            l.sw_in = -1;
            --sw_inflight;
            ++st.swaps;
        }
    }
    // the next moves: per layer the hottest CPU-lane expert the windows used, in place of the coldest VRAM one (and of
    // the RAM tier's coldest)
    void cache_queue() {
        bool queued = false, rqueued = false;
        for (Layer& l : L) {
            if (l.cpu_hits.empty()) continue;
            std::vector<int> hits;
            hits.swap(l.cpu_hits);
            int best = -1, vin = -1;
            for (int e : hits) {
                bool filling = false;   // (a recent slot's fill brings it: the swaps leave it be)
                for (int i = 0; i < l.rc_n; ++i) filling = filling || l.rc_fill[(size_t) i] == e;
                // (never one of the helper's either: its picks are its own, in one place - the sync path's hits can
                //  name them)
                if (!filling && l.slot[(size_t) e] < 0 && !helper_owned(l, e) && !(l.hr_n > 0 && hr_filling(l, e)) &&
                    (best < 0 || l.heat[(size_t) e] > l.heat[(size_t) best]))
                    best = e;
            }
            if (best >= 0 && l.spare_vram >= 0 && !l.swap_pending && sw_inflight < c_inflight) {   // VRAM: the hottest in
                int cold = -1;   // (of the layer's own slots: a recent slot's expert stays)
                for (int e = 0; e < l.n_exp; ++e) {
                    const int sl = l.slot[(size_t) e];
                    if (sl >= 0 && !(l.rc_n > 0 && sl >= l.rc_base && sl < l.rc_base + l.rc_n) &&
                        (cold < 0 || l.heat[(size_t) e] < l.heat[(size_t) cold]))
                        cold = e;
                }
                if (cold >= 0 && l.heat[(size_t) best] > l.heat[(size_t) cold] * c_margin + c_bonus) {
                    l.swap_pending = true;
                    l.sw_in = best;
                    ++sw_inflight;
                    vin = best;
                    Swap sw{l.il, best, cold};
                    sw.win = win_now.load(std::memory_order_relaxed);
                    if (copy_mode && l.ram[(size_t) best] >= 0) sw.ram = copy_spare[(size_t) l.il];   // (-1: none)
                    std::lock_guard<std::mutex> lk(sw_mu);
                    sw_queue.push_back(sw);
                    queued = true;
                }
            }
            if (copy_mode && copy_swap && cs_inflight == 0 && cs_since >= cs_every && !l.swap_pending &&
                cs_free[(size_t) l.il] >= 0 && !l.ram.empty()) {   // (DS4_COPY_SWAP) a copy: the hottest from the files in
                int rb = -1;
                for (int e : hits)
                    if (e != vin && l.slot[(size_t) e] < 0 && l.ram[(size_t) e] < 0 &&
                        (rb < 0 || l.heat[(size_t) e] > l.heat[(size_t) rb]))
                        rb = e;
                int rc = -1;
                if (rb >= 0)
                    for (int e = 0; e < l.n_exp; ++e)
                        if (l.ram[(size_t) e] >= 0 && l.slot[(size_t) e] < 0 &&
                            (rc < 0 || l.heat[(size_t) e] < l.heat[(size_t) rc]))
                            rc = e;
                if (rb >= 0 && rc >= 0 && l.heat[(size_t) rb] > l.heat[(size_t) rc] * cs_margin + 1.0f) {
                    CSwap cs;
                    cs.layer = l.il;
                    cs.in = rb;
                    cs.out = rc;
                    cs.slot = cs_free[(size_t) l.il];
                    cs_free[(size_t) l.il] = -1;
                    ++cs_inflight;
                    cs_since = 0;
                    {
                        std::lock_guard<std::mutex> lk(cs_mu);
                        cs_q.push_back(cs);
                    }
                    cs_cv.notify_one();
                }
            }
            if (l.ram.empty() || ram_free.empty() || ram_inflight >= kMaxSwaps) continue;
            int rb = -1;   // RAM: the hottest read from the file, in place of the layer's coldest held (or a free slot)
            for (int e : hits)
                if (e != vin && l.slot[(size_t) e] < 0 && l.ram[(size_t) e] < 0 && !helper_owned(l, e) &&
                    (rb < 0 || l.heat[(size_t) e] > l.heat[(size_t) rb]))
                    rb = e;
            if (rb < 0) continue;
            int rc = -1;
            for (int e = 0; e < l.n_exp; ++e)
                if (l.ram[(size_t) e] >= 0 && (rc < 0 || l.heat[(size_t) e] < l.heat[(size_t) rc])) rc = e;
            const bool room = ram_free.size() > 1;   // (slots VRAM freed: filled at once)
            if (!room && !(rc >= 0 && l.heat[(size_t) rb] > l.heat[(size_t) rc] * 1.25f + 1.0f)) continue;
            RamSwap rs;
            rs.layer = l.il;
            rs.in = rb;
            rs.out = room ? -1 : rc;
            rs.slot = ram_free.back();
            ram_free.pop_back();
            ++ram_inflight;
            std::lock_guard<std::mutex> lk(sw_mu);
            ram_queue.push_back(rs);
            rqueued = true;
        }
        if (queued) sw_cv.notify_all();
        if (rqueued) ram_cv.notify_one();
    }

    // lookahead's thread: the ranges the CPU lane asked for, read in (os::prefetch) off the lane, which computes
    void prefetch_loop() {
        std::vector<std::pair<const void*, size_t>> b;
        for (;;) {
            {
                std::unique_lock<std::mutex> lk(pf_mu);
                pf_cv.wait(lk, [&] { return quit.load(std::memory_order_relaxed) || !pf_q.empty(); });
                if (quit.load(std::memory_order_relaxed)) return;
                b.swap(pf_q);
            }
            os::prefetch_cold(b);   // (the resident ones would only cost the page walk)
            b.clear();
        }
    }
    // an expert the CPU lane reads from the files (neither in VRAM nor in the RAM tier)
    static bool file_read(const Layer& l, int e) {   // (the helper's are in its pool: never read for the CPU lane)
        return l.slot[(size_t) e] < 0 && (l.ram.empty() || l.ram[(size_t) e] < 0) &&
               (l.helper.empty() || l.helper[(size_t) e] == nullptr);
    }
    // the layer whose picks layer l0 guesses a layers ahead (1, 2): the next ones of its stack on its device, MXFP4
    // experts read in place, some of them from the files now (none: nothing to read early - null)
    const Layer* ahead_layer(const Layer& l0, int a) const {
        const int j = l0.il + a, end = l0.mtp ? g.nl + g.n_mtp : g.nl;
        if (j >= end || j >= (int) L.size()) return nullptr;
        const Layer& n = L[(size_t) j];
        if (n.dev != l0.dev || n.mtp != l0.mtp || n.lay.fmt != gg::kFmtMXFP4 || n.gate_w == nullptr || n.n_exp > 1024 ||
            (int) n.slot.size() < n.n_exp)
            return nullptr;
        for (int e = 0; e < n.n_exp; ++e)
            if (file_read(n, e)) return &n;
        return nullptr;
    }
    // lookahead on the CPU lane: request r (layer li, seq) carries the device's guesses for the next layers - the
    // guessed experts read from the files asked for now (each once a window), the guesses kept for the hit counts
    std::vector<std::pair<const void*, size_t>> pf_want;
    void ahead_ask(int li, const Req& r, unsigned seq, int T) {
        pf_want.clear();
        for (int a = 1; a <= 2; ++a) {
            const int m = std::min(r.na[a - 1], a == 1 ? kAhead1 : kPicks), j = li + a;
            if (m <= 0 || j >= (int) L.size()) continue;
            const Layer& n = L[(size_t) j];
            uint8_t* fl = ahead_fl.data() + (size_t) j * 1024;
            uint8_t* rk = ahead_rank.data() + (size_t) j * 1024;
            if (ahead_for[(size_t) j] != seq + (unsigned) a) {
                std::memset(fl, 0, 1024);
                std::memset(rk, 0, 1024);
                ahead_for[(size_t) j] = seq + (unsigned) a;
            }
            for (int t = 0; t < T; ++t)
                for (int i = 0; i < m; ++i) {
                    const int e = r.ahead[t][(a - 1) * kAhead1 + i];
                    if (e < 0 || e >= n.n_exp || e >= (int) n.slot.size()) continue;
                    fl[e] |= a == 2 ? 4 : (i < n.k_exp ? 3 : 2);
                    if (a == 1 && (rk[e] == 0 || rk[e] > i + 1)) rk[e] = (uint8_t) (i + 1);
                    if ((fl[e] & 8) || !file_read(n, e)) continue;
                    fl[e] |= 8;
                    // (DISK_SKIP_AUTO while skipping: not in RAM when asked for - the lookahead's read would hide it)
                    if (disk_skip_auto && j < g.nl && sk_auto.on.load(std::memory_order_relaxed) && !in_ram(n, e))
                        fl[e] |= 16;
                    for (int q = 0; q < 3; ++q) pf_want.push_back({mx_mat(n, e, q), mx_part_bytes(n, q)});
                    ++st.ahead_pf;
                }
        }
        if (pf_want.empty()) return;
        {
            std::lock_guard<std::mutex> lk(pf_mu);
            pf_q.insert(pf_q.end(), pf_want.begin(), pf_want.end());
        }
        pf_cv.notify_one();
    }

    // DS4_TP_CHECK: the largest difference allowed against the whole, a fraction of the largest output; how long a
    // member's kernels may take to end
    static constexpr double kTpCheckTol = 1e-3, kTpCheckWaitMs = 10000.0;
    // the shared expert of layer l whole, on the host, as the GPUs' GEMVs round it: Q8_0 - the input rounded to int8 a
    // 32-block at a time (q8_quant's rule), each block's integer dot times its two scales; BF16 - in F32 (no rounding);
    // Q5_K / Q6_K (orcarouter's mixes) - the input rounded as Q8_0's (mv's rule for a dense low-bit matrix), each
    // block's dot with the row's values as ggml decodes them
    bool shared_host(const Layer& l, const std::vector<float>& x, std::vector<float>& y, std::string& err) const {
        auto gemv = [&](const std::string& name, const std::vector<float>& in, std::vector<float>& out) {
            const Tensor* t = pk.get(l.name + name + ".weight");
            const bool kq = t != nullptr && (t->dtype == "Q5_K" || t->dtype == "Q6_K") && in.size() % 256 == 0;
            if (t == nullptr || t->shape.size() != 2 || (int) t->shape[1] != (int) in.size() ||
                (t->dtype != "Q8_0" && t->dtype != "BF16" && !kq)) {
                err = l.name + name + ": not a BF16 / Q8_0 / Q5_K / Q6_K matrix of " + std::to_string(in.size()) +
                      " inputs";
                return false;
            }
            const int n = (int) t->shape[0], k = (int) t->shape[1];
            std::vector<uint8_t> w(t->bytes);
            if (!pk.read(*t, w.data())) {
                err = l.name + name + ": read failed";
                return false;
            }
            out.assign((size_t) n, 0.0f);
            if (t->dtype == "BF16") {
                for (int r = 0; r < n; ++r) {
                    double acc = 0;
                    for (int c = 0; c < k; ++c)
                        acc += (double) bf16_to_f32(((const uint16_t*) w.data())[(size_t) r * k + c]) * in[(size_t) c];
                    out[(size_t) r] = (float) acc;
                }
                return true;
            }
            const int nb = k / 32;
            std::vector<int8_t> xq((size_t) k);
            std::vector<float> xd((size_t) nb);
            for (int b = 0; b < nb; ++b) {
                float am = 0.0f;
                for (int j = 0; j < 32; ++j) am = std::max(am, std::fabs(in[(size_t) b * 32 + j]));
                const float sc = am / 127.0f;
                xd[(size_t) b] = sc;
                for (int j = 0; j < 32; ++j)
                    xq[(size_t) b * 32 + j] = (int8_t) (am > 0.0f ? (int) std::nearbyint(in[(size_t) b * 32 + j] / sc) : 0);
            }
            if (kq) {
                const bool q5 = t->dtype == "Q5_K";
                const size_t kb = q5 ? 176 : kQ6kBytes, rkb = (size_t) k / 256 * kb;
                std::vector<float> row((size_t) k);
                for (int r = 0; r < n; ++r) {
                    for (int b = 0; b < k / 256; ++b)
                        (q5 ? q5k_values : q6k_values)(w.data() + (size_t) r * rkb + (size_t) b * kb, row.data() + (size_t) b * 256);
                    double acc = 0;
                    for (int b = 0; b < nb; ++b) {
                        double sum = 0;
                        for (int j = 0; j < 32; ++j)
                            sum += (double) row[(size_t) b * 32 + j] * (double) xq[(size_t) b * 32 + j];
                        acc += (double) xd[(size_t) b] * sum;
                    }
                    out[(size_t) r] = (float) acc;
                }
                return true;
            }
            const size_t rb = (size_t) nb * gg::kQ8Bytes;
            for (int r = 0; r < n; ++r) {
                double acc = 0;
                for (int b = 0; b < nb; ++b) {
                    const uint8_t* q = w.data() + (size_t) r * rb + (size_t) b * gg::kQ8Bytes;
                    int sum = 0;
                    for (int j = 0; j < 32; ++j) sum += (int) (int8_t) q[2 + j] * (int) xq[(size_t) b * 32 + j];
                    acc += (double) (f16_to_f32((uint16_t) (q[0] | q[1] << 8)) * xd[(size_t) b]) * (double) sum;
                }
                out[(size_t) r] = (float) acc;
            }
            return true;
        };
        std::vector<float> sg, su;
        if (!gemv("ffn.shared_experts.w1", x, sg) || !gemv("ffn.shared_experts.w3", x, su)) return false;
        std::vector<float> sh(sg.size());
        for (size_t i = 0; i < sg.size(); ++i) {   // (swiglu_kernel's)
            float gv = sg[i], uv = su[i];
            if (g.lim > 0.0f) {
                gv = std::min(gv, g.lim);
                uv = std::min(std::max(uv, -g.lim), g.lim);
            }
            sh[i] = gv / (1.0f + std::exp(-gv)) * uv;
        }
        return gemv("ffn.shared_experts.w2", sh, y);
    }
    // member m of layer l's group: one token x through its parts as decode runs them - its VRAM part of the experts
    // `held` (weights w) by moe_gate_up / moe_down with its own layout and FF, its part of the shared expert by mv /
    // swiglu / mv - all on its stream: uploaded from the check's own host copies (not the caller's, not this frame's),
    // both outputs read back on that stream into pinned memory before the end's event, the end waited for
    // (kTpCheckWaitMs).  Only a clean end frees anything; an error before it then fails the load as any other.  No
    // clean end - an error at the end, or none in time: the kernels may still read the model's memory (the layer's
    // weights, its expert slots, the stream), which the failed load's teardown would free under them - tp_unknown
    bool tp_check_member(const Layer& l, int m, const std::vector<float>& x, const std::vector<int>& held,
                         const float* w, std::vector<float>& routed, std::vector<float>& shared, std::string& err) {
        const Layer& xm = member(l, m);
        Dev& d = devs[(size_t) xm.dev];
        const int D = g.dim, FF = xm.ffn;
        if (cudaSetDevice(d.id) != cudaSuccess) {   // (before anything is made or enqueued: an ordinary failure)
            (void) cudaGetLastError();
            err = "TP check: CUDA" + std::to_string(d.id) + " (layer " + std::to_string(l.il) + " member " +
                  std::to_string(m) + "): cudaSetDevice failed";
            return false;
        }
        struct In {   // (the uploads' sources, freed after a clean end only)
            std::vector<float> x;
            unsigned long long p[kPicks] = {};
            float w[kPicks] = {};
        };
        In* in = new In;
        in->x = x;
        for (size_t i = 0; i < held.size() && i < (size_t) kPicks; ++i) {
            in->p[i] = (unsigned long long) (uintptr_t) sat(l, xm, l.slot[(size_t) held[i]], unit(xm));
            in->w[i] = w[i];
        }
        float *dx = nullptr, *dh = nullptr, *dout = nullptr, *dsg = nullptr, *dsu = nullptr, *dsh = nullptr,
              *dsho = nullptr, *dw = nullptr, *back = nullptr;   // (back: pinned - dout's D, then dsho's)
        unsigned long long* dp = nullptr;
        std::vector<void*> bufs;
        auto take = [&](auto*& p, size_t n) {
            void* v = nullptr;
            const bool ok = cudaMalloc(&v, n) == cudaSuccess;
            if (ok) bufs.push_back(v);
            p = (std::remove_reference_t<decltype(p)>) v;
            return ok;
        };
        cudaEvent_t ev = nullptr;
        if (cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) ev = nullptr;
        bool ok = ev != nullptr && take(dx, (size_t) D * 4) && take(dh, (size_t) kPicks * FF * 4) &&
                  take(dout, (size_t) D * 4) && take(dsg, (size_t) FF * 4) && take(dsu, (size_t) FF * 4) &&
                  take(dsh, (size_t) FF * 4) && take(dsho, (size_t) D * 4) && take(dw, (size_t) kPicks * 4) &&
                  take(dp, (size_t) kPicks * 8);
        if (ok && cudaMallocHost((void**) &back, (size_t) 2 * D * 4) != cudaSuccess) {
            back = nullptr;
            ok = false;
        }
        const int e0 = gg::launch_errors();
        bool submitted = false;   // (anything on the stream: its end waited for before any free)
        if (ok) {
            submitted = true;
            ok = cudaMemcpyAsync(dx, in->x.data(), (size_t) D * 4, cudaMemcpyHostToDevice, d.st) == cudaSuccess &&
                 cudaMemcpyAsync(dp, in->p, sizeof in->p, cudaMemcpyHostToDevice, d.st) == cudaSuccess &&
                 cudaMemcpyAsync(dw, in->w, sizeof in->w, cudaMemcpyHostToDevice, d.st) == cudaSuccess;
            if (ok) {
                x3::MoeArgs ma;
                ma.plan_ptr = dp;
                ma.plan_w = dw;
                ma.lay = xm.hlay;
                ma.k = l.k_exp;
                ma.n_embd = D;
                ma.n_ff = FF;
                ma.limit = g.lim;
                gg::moe_gate_up(ma, dx, dh, d.st);
                gg::moe_down(ma, dh, nullptr, dout, d.st);
                ok = mv(d, {job(xm.s1, dx, dsg, 1, D, FF), job(xm.s3, dx, dsu, 1, D, FF)}, err);
                if (ok) swiglu(dsg, dsu, FF, g.lim, dsh, d.st);
                ok = ok && mv(d, {job(xm.s2, dsh, dsho, 1, FF, D)}, err);
            }
            ok = ok && cudaGetLastError() == cudaSuccess && gg::launch_errors() == e0 &&   // (the readback: before the end)
                 cudaMemcpyAsync(back, dout, (size_t) D * 4, cudaMemcpyDeviceToHost, d.st) == cudaSuccess &&
                 cudaMemcpyAsync(back + D, dsho, (size_t) D * 4, cudaMemcpyDeviceToHost, d.st) == cudaSuccess;
        }
        if (submitted) {   // (its event, else - not recorded - the stream itself; only a clean end goes on)
            const bool rec = cudaEventRecord(ev, d.st) == cudaSuccess;
            const double t0 = now_ms();
            cudaError_t q;
            while ((q = rec ? cudaEventQuery(ev) : cudaStreamQuery(d.st)) == cudaErrorNotReady &&
                   now_ms() - t0 < kTpCheckWaitMs)
                std::this_thread::sleep_for(std::chrono::microseconds(100));
            if (q != cudaSuccess) tp_unknown(d.id, l.il, m, q == cudaErrorNotReady ? "no end in time" : "an error at its end");
            ok = ok && rec;
        }
        if (ok) {
            routed.assign(back, back + D);
            shared.assign(back + D, back + 2 * D);
        } else
            (void) cudaGetLastError();
        for (void* v : bufs) cudaFree(v);
        if (back != nullptr) cudaFreeHost(back);
        if (ev != nullptr) cudaEventDestroy(ev);
        delete in;
        if (!ok && err.empty())
            err = "TP check: CUDA" + std::to_string(d.id) + " (layer " + std::to_string(l.il) + " member " +
                  std::to_string(m) + "): a CUDA error";
        return ok;
    }
    // DS4_TP_CHECK with the group's members on the flow (DS4_FLOW_TP): member m of layer l, one expert's blob staged on
    // the host twice as the flow stages it - the member's read (its gate / up rows, the down whole) and a copy's (each
    // matrix whole) - each through flow_copy into a device buffer between guard bytes, read back: both must be
    // blob_to_half's part for the member byte for byte, every guard untouched - the down through a scratch of its own
    // where the flow gives the device one (flow_down_bytes), else as the flow copies it without; with
    // DS4_FLOW_DOWN_PART the read's down compacted on the host (compact_rows) and DMA'd as one run, as the flow does.
    // On one stream, the readback before the end's event, its own host and device buffers kept until a clean end (none:
    // tp_unknown)
    bool tp_flow_member(const Layer& l, int m, std::string& err) {
        const Layer& x = member(l, m);
        Dev& d = devs[(size_t) x.dev];
        auto fail = [&](const std::string& why) {
            err = "TP check: flow copies (layer " + std::to_string(l.il) + " member " + std::to_string(m) + "): " + why;
            return false;
        };
        if (cudaSetDevice(d.id) != cudaSuccess) {   // (before anything is made or enqueued)
            (void) cudaGetLastError();
            return fail("cudaSetDevice failed");
        }
        constexpr size_t kGuard = 256;
        const size_t u = unit(x), blob = l.blob, dev_bytes = 2 * u + 4 * kGuard,   // (the slots, then the down's scratch)
                     down_b = flow_down_bytes(x.dev) > 0 ? mx_part_bytes(l, 2) : 0;
        std::vector<uint8_t> whole(blob), want(u);
        if (!read_mx(l, 0, whole.data())) return fail("expert 0 not read");
        blob_to_half(l, whole.data(), m, want.data());
        size_t part_b = 0;
        for (int r = 0; r < 3; ++r) part_b += mx_read_len(l, m, r);
        uint8_t *stage = nullptr, *back = nullptr, *dv = nullptr;   // (stage: the member's read, then the whole blob)
        cudaEvent_t ev = nullptr;
        if (cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) ev = nullptr;
        bool ok = ev != nullptr;
        if (ok && cudaMallocHost((void**) &stage, part_b + blob) != cudaSuccess) stage = nullptr, ok = false;
        if (ok && cudaMallocHost((void**) &back, dev_bytes) != cudaSuccess) back = nullptr, ok = false;
        if (ok && cudaMalloc((void**) &dv, dev_bytes + down_b) != cudaSuccess) dv = nullptr, ok = false;
        const uint8_t *ps[3] = {}, *ws[3] = {};
        if (ok) {
            size_t o = 0;
            for (int r = 0; r < 3; ++r) {
                const size_t n = mx_read_len(l, m, r);
                std::memcpy(stage + o, whole.data() + l.lay.trellis[r] + mx_read_off(l, m, r), n);
                ps[r] = stage + o;
                o += n;
            }
            std::memcpy(stage + part_b, whole.data(), blob);
            for (int r = 0; r < 3; ++r) ws[r] = stage + part_b + l.lay.trellis[r];
            if (down_part) {   // (DS4_FLOW_DOWN_PART: the read's down compacted to the member's columns, as io does)
                size_t dr = 0, d0 = 0, dh = 0;
                down_cut(l, m, dr, d0, dh);
                compact_rows(stage + (ps[2] - stage), (size_t) g.dim, dr, d0, dh);   // (ps[2]: in stage)
            }
        }
        bool submitted = false;   // (anything on the stream: its end waited for before any free)
        if (ok) {
            submitted = true;
            ok = cudaMemsetAsync(dv, 0xA5, dev_bytes, d.st) == cudaSuccess &&
                 flow_copy(l, m, ps, false, dv + kGuard, down_b > 0 ? dv + dev_bytes : nullptr, d.st, down_part) &&
                 flow_copy(l, m, ws, true, dv + u + 3 * kGuard, down_b > 0 ? dv + dev_bytes : nullptr, d.st) &&
                 cudaMemcpyAsync(back, dv, dev_bytes, cudaMemcpyDeviceToHost, d.st) == cudaSuccess;   // (before the end)
        }
        if (submitted) {   // (its event, else - not recorded - the stream itself; only a clean end goes on)
            const bool rec = cudaEventRecord(ev, d.st) == cudaSuccess;
            const double t0 = now_ms();
            cudaError_t q;
            while ((q = rec ? cudaEventQuery(ev) : cudaStreamQuery(d.st)) == cudaErrorNotReady &&
                   now_ms() - t0 < kTpCheckWaitMs)
                std::this_thread::sleep_for(std::chrono::microseconds(100));
            if (q != cudaSuccess) tp_unknown(d.id, l.il, m, q == cudaErrorNotReady ? "no end in time" : "an error at its end");
            ok = ok && rec;
        }
        size_t bad_part = 0, bad_whole = 0, bad_guard = 0;
        if (ok) {
            for (size_t i = 0; i < u; ++i) {
                bad_part += back[kGuard + i] != want[i];
                bad_whole += back[u + 3 * kGuard + i] != want[i];
            }
            for (size_t i = 0; i < kGuard; ++i)
                bad_guard += (back[i] != 0xA5) + (back[kGuard + u + i] != 0xA5) + (back[u + 2 * kGuard + i] != 0xA5) +
                             (back[2 * u + 3 * kGuard + i] != 0xA5);
        } else
            (void) cudaGetLastError();
        if (dv != nullptr) cudaFree(dv);
        if (back != nullptr) cudaFreeHost(back);
        if (stage != nullptr) cudaFreeHost(stage);
        if (ev != nullptr) cudaEventDestroy(ev);
        if (!ok) return fail("a CUDA error");
        std::string fmt;
        for (int r = 0; r < 3; ++r) fmt += std::string(r ? "/" : "") + gg::type_name(gg::expert_type(l.lay, r));
        if (bad_part + bad_whole + bad_guard > 0) {
            std::fprintf(stderr, "ds4: TP check: flow copies %s (layer %d, member %d takes %d of %d) FAILED: %zu part bytes, "
                                 "%zu whole-staging bytes, %zu guard bytes differ (DS4_FLOW_TP)\n",
                         fmt.c_str(), l.il, m, x.ffn, g.ff, bad_part, bad_whole, bad_guard);
            return fail("bytes differ");
        }
        std::fprintf(stderr, "ds4: TP check: flow copies %s (layer %d, member %d takes %d of %d): part and whole staging "
                             "the member's blob byte for byte, guards intact (DS4_FLOW_TP)\n",
                     fmt.c_str(), l.il, m, x.ffn, g.ff);
        return true;
    }
    // DS4_TP_CHECK, the prompt path off the flow (copy_ahead): expert e of l to member m's device as a prompt streams it -
    // stage_streamed into pinned staging, copy_streamed into a device buffer between guard bytes (in place from its
    // pinned copy where cp_dma has one) - read back: the whole blob as read_mx reads it (a member's part: cut by
    // mx_blob_to_half) byte for byte over the pieces, the guards untouched.  On one stream, the readback before the
    // end's event, its own buffers kept until a clean end (none: tp_unknown)
    bool tp_copy_member(const Layer& l, int m, int e, size_t& bad, size_t& bad_guard, std::string& err) {
        const Layer& x = member(l, m);
        Dev& d = devs[(size_t) x.dev];
        auto fail = [&](const std::string& why) {
            err = "TP check: prompt copies (layer " + std::to_string(l.il) + " member " + std::to_string(m) + " expert " +
                  std::to_string(e) + "): " + why;
            return false;
        };
        if (cudaSetDevice(d.id) != cudaSuccess) {   // (before anything is made or enqueued)
            (void) cudaGetLastError();
            return fail("cudaSetDevice failed");
        }
        constexpr size_t kGuard = 256;
        const size_t u = unit(x), dev_bytes = u + 2 * kGuard;
        std::vector<uint8_t> whole(l.blob), want(u, 0);
        if (!read_mx(l, e, whole.data())) return fail("not read");
        if (l.nm > 1) mx_blob_to_half(l, whole.data(), m, want.data());
        else std::memcpy(want.data(), whole.data(), u);
        uint8_t *stage = nullptr, *back = nullptr, *dv = nullptr;
        cudaEvent_t ev = nullptr;
        if (cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) ev = nullptr;
        bool ok = ev != nullptr;
        if (ok && cudaMallocHost((void**) &stage, l.blob) != cudaSuccess) stage = nullptr, ok = false;
        if (ok && cudaMallocHost((void**) &back, dev_bytes) != cudaSuccess) back = nullptr, ok = false;
        if (ok && cudaMalloc((void**) &dv, dev_bytes) != cudaSuccess) dv = nullptr, ok = false;
        const bool read = ok && stage_streamed(l, m, e, stage);
        bool submitted = false;   // (anything on the stream: its end waited for before any free)
        std::string cerr;
        if (read) {
            submitted = true;
            ok = cudaMemsetAsync(dv, 0xA5, dev_bytes, d.st) == cudaSuccess &&
                 copy_streamed(l, m, e, stage, dv + kGuard, d.st, cerr) &&
                 cudaMemcpyAsync(back, dv, dev_bytes, cudaMemcpyDeviceToHost, d.st) == cudaSuccess;   // (before the end)
        }
        if (submitted) {   // (its event, else - not recorded - the stream itself; only a clean end goes on)
            const bool rec = cudaEventRecord(ev, d.st) == cudaSuccess;
            const double t0 = now_ms();
            cudaError_t q;
            while ((q = rec ? cudaEventQuery(ev) : cudaStreamQuery(d.st)) == cudaErrorNotReady &&
                   now_ms() - t0 < kTpCheckWaitMs)
                std::this_thread::sleep_for(std::chrono::microseconds(100));
            if (q != cudaSuccess) tp_unknown(d.id, l.il, m, q == cudaErrorNotReady ? "no end in time" : "an error at its end");
            ok = ok && rec;
        }
        bad = bad_guard = 0;
        if (ok && read) {
            const x3::ExpertLayout& lay = l.nm > 1 ? x.hlay : l.lay;
            for (int r = 0; r < 3; ++r) {
                const size_t a = lay.trellis[r],
                             n = l.nm == 1 ? mx_part_bytes(l, r)
                                 : r < 2  ? (size_t) x.ffn * mx_row_b(l, r)
                                          : (size_t) g.dim * gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn);
                for (size_t i = a; i < a + n; ++i) bad += back[kGuard + i] != want[i];
            }
            for (size_t i = 0; i < kGuard; ++i) bad_guard += (back[i] != 0xA5) + (back[kGuard + u + i] != 0xA5);
        } else
            (void) cudaGetLastError();
        if (dv != nullptr) cudaFree(dv);
        if (back != nullptr) cudaFreeHost(back);
        if (stage != nullptr) cudaFreeHost(stage);
        if (ev != nullptr) cudaEventDestroy(ev);
        if (!read && ok) return fail("not staged");
        if (!ok) return fail(cerr.empty() ? "a CUDA error" : cerr);
        return true;
    }
    // a TP check's work without a clean end: what it may still read is the model's - the layer's weights, the expert
    // slots, the device's stream - and a failed load's teardown frees all of it, so there is none: the line, then the
    // process ends at once (exit 3: the device's state unknown - whoever runs the engine loads nothing more on these
    // GPUs and retries nothing until a clean device check)
    static constexpr int kExitUnknown = 3;
    [[noreturn]] static void tp_unknown(int dev, int il, int m, const char* why) {
        std::fprintf(stderr, "ds4: TP check: CUDA%d (layer %d, member %d): %s - the device's state unknown; the process "
                             "ends without teardown (exit %d)\n", dev, il, m, why, kExitUnknown);
        std::fflush(stderr);
        std::fflush(stdout);
        std::_Exit(kExitUnknown);
    }
    // DS4_HC_FUSE=1 (at load, before any request), on every device with layers: hc_split_pre_norm against what it
    // replaces - hc_split, hc_pre_norm, gguf mv's own int8 rounding of the input (q8_round) and its GEMVs, the layer's
    // copy of the pre slots - for layers the device holds: the first of each kind of attention input (2 GEMVs; 3 with
    // the compressed KV; 4 with its gate too; a kind held and not run fails) and the last, each layer's attention (its
    // split weights and norm, x's int8 rounding, its input GEMVs through the rounding given) and its FFN (the pre
    // copy), on three inputs: random; edges (x's 32-blocks of zeros, negative zeros, tiny and large magnitudes and a
    // lone maximum, mixes past expf's range, a zero and a negative lagged weight); and ties (the lagged mix 1 0 0 0, h
    // +-8 - the norm's scale 1 / 8, past eps - and a synthetic norm of 127 or 254 and k + 0.5 a block: int8 rounding
    // at its halves).  Every output region starts 0xA5 between guards, the pre buffers' 8 slots as sentinels (slots
    // 4..7 a NaN payload, -0, a denormal, -123.5); both paths' bytes must be equal - every output, slot and guard, the
    // guards untouched - the written values finite and the int8 scales written (>= 0).  On d.st, each run's end waited
    // for (10 s): a CUDA error or a mismatch after a clean end fails the load (everything freed); no clean end ends the
    // process at once (hc_unknown - what the run may still touch is the model's).  T rows (DS4_HC_FUSE=2: kWin, a
    // decode window's): every input and output T rows at the decode buffers' strides, each row its own inputs, x's int8
    // rows by q8_round a row and the GEMVs on T columns (the fused path's PreQ8 rows T); T 1 is the check above.
    // ffn_q8 (DS4_HC_FUSE=2): the FFN's split rounds x too, checked as the attention's is, with the shared expert's
    // w1 / w3 GEMVs on it (the decode's other FFN GEMVs take x as F32 or round it their own way)
    [[noreturn]] static void hc_unknown(int dev, int il, bool ffn, const char* why) {
        std::fprintf(stderr, "ds4: HC fuse check: CUDA%d (layer %d, %s): %s - the device's state unknown; the process "
                             "ends without teardown (exit %d)\n",
                     dev, il, ffn ? "FFN" : "attention", why, kExitUnknown);
        std::fflush(stderr);
        std::fflush(stdout);
        std::_Exit(kExitUnknown);
    }
    bool hc_fuse_check(std::string& err, int T = 1, bool ffn_q8 = false) {
        const int D = g.dim, HD = g.hd, QL = g.q_lora, FF = g.ff;
        constexpr size_t kGuard = 64;
        static constexpr uint32_t kSent[8] = {0x3e800000u, 0x3f000000u, 0x3f400000u, 0x3f800000u,
                                              0x7fc0beefu, 0x80000000u, 0x00000001u, 0xc2f70000u};
        // one set of outputs: [guard | region]... | guard, in bytes
        enum { kPre, kPost, kComb, kCopy, kX, kQ, kQd, kQr, kKvr, kCkr, kCgr, kS1, kS3, kRegions };
        const size_t rb1[kRegions] = {32, 32, 256, 32, (size_t) D * 4, (size_t) D, (size_t) D / 32 * 4, (size_t) QL * 4,
                                      (size_t) HD * 4, (size_t) HD * 4, (size_t) HD * 4, (size_t) FF * 4,
                                      (size_t) FF * 4};   // (a row's)
        size_t rb[kRegions], at[kRegions], set_bytes = 0;
        for (int r = 0; r < kRegions; ++r) {
            rb[r] = rb1[r] * (size_t) T;
            at[r] = set_bytes + kGuard;
            set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
        }
        set_bytes += kGuard;
        // h | mixes | the lagged mix (T rows each) | a synthetic norm
        const size_t n_in = (size_t) T * (4 * (size_t) D + 32 + 8) + (size_t) D;
        const std::string rows = T > 1 ? " (" + std::to_string(T) + " rows)" : "";
        uint32_t st = 0x2545f491u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            std::vector<const Layer*> ls;   // (the first of each kind, then the last)
            const Layer* last = nullptr;
            bool kind_held[5] = {}, kind_run[5] = {};   // (by the attention's GEMVs: 2, 3 or 4)
            for (const Layer& l0 : L)
                if (!l0.mtp)
                    for (int m = 0; m < l0.nm; ++m)
                        if (member(l0, m).dev == (int) di) {
                            const Layer& x = member(l0, m);
                            const int nk = 2 + (x.kv_src ? 1 : 0) + (x.kv_src && x.ratio > 1 ? 1 : 0);
                            if (!kind_held[nk]) ls.push_back(&x);
                            kind_held[nk] = true;
                            last = &x;
                        }
            if (ls.empty()) continue;
            if (std::find(ls.begin(), ls.end(), last) == ls.end()) ls.push_back(last);
            auto fail_at = [&](const std::string& why) {
                err = "HC fuse check" + rows + " on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d HC fuse check%s FAILED: %s\n", d.id, rows.c_str(), why.c_str());
                return false;
            };
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                return fail_at("cudaSetDevice failed");
            }
            const cudaStream_t s = d.st;
            float* in = nullptr;
            uint8_t *out = nullptr, *back = nullptr;
            cudaEvent_t ev = nullptr;
            if (cudaMalloc((void**) &in, n_in * 4) != cudaSuccess ||
                cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess ||
                cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess ||
                cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
                (void) cudaGetLastError();
                if (in != nullptr) cudaFree(in);
                if (out != nullptr) cudaFree(out);
                if (back != nullptr) cudaFreeHost(back);
                if (ev != nullptr) cudaEventDestroy(ev);
                return fail_at("its buffers");
            }
            float *h = in, *mixes = in + (size_t) T * 4 * D, *lag = mixes + 32 * T, *wsyn = lag + 8 * T;
            std::vector<float> hin(n_in);   // (the host's inputs: written again only after the run before has ended)
            int runs = 0;
            std::string bad;
            for (const Layer* lp : ls)
                for (int kind = 0; kind < 3 && bad.empty(); ++kind)
                    for (int ffn = 0; ffn < 2 && bad.empty(); ++ffn) {
                        const Layer& l = *lp;
                        const bool q8 = !ffn || ffn_q8;   // (x's int8 rows: the attention's; the FFN's with ffn_q8)
                        float *hh = hin.data(), *hm = hh + (size_t) T * 4 * D, *hl = hm + 32 * T, *hw = hl + 8 * T;
                        for (int t = 0; t < T; ++t)
                            for (int e = 0; e < D; ++e) {
                                const int blk = e / 32, lane = e % 32;
                                for (int k = 0; k < 4; ++k) {
                                    float v = rnd() * (float) (1 + k);
                                    if (kind == 1)
                                        switch (blk % 8) {
                                            case 0: v = 0.0f; break;
                                            case 1: v = -0.0f; break;
                                            case 2: v = rnd() * 1e-20f; break;
                                            case 3: v = rnd() * 1e15f; break;
                                            case 4: v = lane == 5 ? 1000.0f : rnd(); break;
                                            default: break;
                                        }
                                    if (kind == 2) v = k == 0 ? (blk % 2 ? -8.0f : 8.0f) : 7.0f;
                                    hh[((size_t) t * 4 + k) * D + e] = v;
                                }
                                hw[e] = (lane == 0 ? 127.0f : (float) (lane - 16) + 0.5f) * (blk % 2 ? 2.0f : 1.0f);
                            }
                        for (int t = 0; t < T; ++t)
                            for (int i = 0; i < 32; ++i)   // (edges: every third mix +-80, expf past its range)
                                hm[32 * t + i] = i < 24 ? rnd() * (kind == 1 && i % 3 == 0 ? 20.0f : 1.0f) : 0.0f;
                        const float lag_k[3][4] = {{0.4f, 0.9f, 0.6f, 1.2f}, {1.5f, 0.0f, -0.75f, 0.25f}, {1, 0, 0, 0}};
                        for (int t = 0; t < T; ++t)
                            for (int i = 0; i < 8; ++i) {
                                if (i < 4) hl[8 * t + i] = lag_k[kind][i];
                                else std::memcpy(&hl[8 * t + i], &kSent[i], 4);
                            }
                        const float* w = kind == 2 ? wsyn : ffn ? l.ffn_norm : l.attn_norm;
                        uint8_t* set[2] = {out, out + set_bytes};   // the old path's, the fused one's
                        auto F = [&](int b, int r) { return (float*) (set[b] + at[r]); };
                        bool ok = cudaMemcpyAsync(in, hin.data(), n_in * 4, cudaMemcpyHostToDevice, s) == cudaSuccess &&
                                  cudaMemsetAsync(out, 0xA5, 2 * set_bytes, s) == cudaSuccess;
                        for (int b = 0; b < 2; ++b)
                            for (int t = 0; ok && t < T; ++t)
                                ok = cudaMemcpyAsync(set[b] + at[kPre] + 32 * t, kSent, 32, cudaMemcpyHostToDevice,
                                                     s) == cudaSuccess;
                        x3::MvJob j[4];
                        int nj = 0;
                        auto ffn_jobs = [&](float* x, float* y1, float* y3) {   // (the shared expert's w1 / w3 on x)
                            j[0] = job(l.s1, x, y1, T, D, FF);
                            j[1] = job(l.s3, x, y3, T, D, FF);
                            return 2;
                        };
                        if (ok) {   // the old path
                            hc_split(mixes, ffn ? l.hcf_scale : l.hca_scale, ffn ? l.hcf_base : l.hca_base, g.hc,
                                     g.sinkhorn, g.hc_eps, T, F(0, kPre), F(0, kPost), F(0, kComb), s);
                            hc_pre_norm(h, lag, w, D, g.hc, T, g.eps, F(0, kX), s);
                            if (ffn)
                                ok = cudaMemcpyAsync(F(0, kCopy), F(0, kPre), (size_t) 32 * T, cudaMemcpyDeviceToDevice,
                                                     s) == cudaSuccess;
                            if (ok && q8) {
                                for (int t = 0; t < T; ++t)
                                    gg::q8_round(F(0, kX) + (size_t) t * D, D,
                                                 (int8_t*) (set[0] + at[kQ]) + (size_t) t * D,
                                                 F(0, kQd) + (size_t) t * (D / 32), s);
                                nj = ffn ? ffn_jobs(F(0, kX), F(0, kS1), F(0, kS3))
                                         : attn_in_jobs(l, F(0, kX), F(0, kQr), F(0, kKvr), F(0, kCkr), F(0, kCgr), T,
                                                        j);
                                ok = mv_any(j, nj, s);
                            }
                        }
                        if (ok) {   // the fused one
                            HcFuse a = hc_args(l, ffn != 0, mixes, h, lag, F(1, kX),
                                               q8 ? (int8_t*) (set[1] + at[kQ]) : nullptr, q8 ? F(1, kQd) : nullptr,
                                               F(1, kPre), F(1, kPost), F(1, kComb), ffn ? F(1, kCopy) : nullptr);
                            a.w = w;
                            hc_split_pre_norm(a, s, T);
                            if (q8) {
                                gg::PreQ8 pq;
                                pq.x = F(1, kX);
                                pq.q = (const int8_t*) (set[1] + at[kQ]);
                                pq.d = F(1, kQd);
                                pq.k = D;
                                pq.rows = T;
                                nj = ffn ? ffn_jobs(F(1, kX), F(1, kS1), F(1, kS3))
                                         : attn_in_jobs(l, F(1, kX), F(1, kQr), F(1, kKvr), F(1, kCkr), F(1, kCgr), T,
                                                        j);
                                ok = mv_any(j, nj, s, &pq);
                                if (!ffn) kind_run[nj] = true;
                            }
                        }
                        ok = ok && cudaGetLastError() == cudaSuccess &&
                             cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, s) == cudaSuccess;
                        // (the end of whatever went in: its event, else the stream itself - bounded)
                        const bool recorded = ok && cudaEventRecord(ev, s) == cudaSuccess;
                        const auto t0 = std::chrono::steady_clock::now();
                        cudaError_t q;
                        while ((q = recorded ? cudaEventQuery(ev) : cudaStreamQuery(s)) == cudaErrorNotReady &&
                               std::chrono::steady_clock::now() - t0 < std::chrono::seconds(10))
                            std::this_thread::sleep_for(std::chrono::microseconds(100));
                        if (q != cudaSuccess)
                            hc_unknown(d.id, l.il, ffn != 0,
                                       q == cudaErrorNotReady ? "no end in time" : "an error at its end");
                        if (!recorded) {   // (a CUDA error before the end, which was clean)
                            (void) cudaGetLastError();
                            bad = "a launch refused or a CUDA error";
                            break;
                        }
                        ++runs;
                        const char* what[3] = {"random", "edges", "ties"};
                        auto where = [&](const std::string& r, size_t o) {
                            return "layer " + std::to_string(l.il) + (ffn ? " FFN, " : " attention, ") + what[kind] +
                                   ": " + r + " byte " + std::to_string(o);
                        };
                        const uint8_t *A = back, *B = back + set_bytes;
                        for (size_t o = 0; o < set_bytes && bad.empty(); ++o)
                            if (A[o] != B[o]) bad = where("an output", o);
                        const char* rname[kRegions] = {"pre",       "post",        "comb",
                                                       "the pre copy", "x",        "int8",
                                                       "scale",     "q's GEMV",    "the KV GEMV",
                                                       "the compressed KV GEMV",   "its gate GEMV",
                                                       "the shared expert's w1 GEMV", "its w3 GEMV"};
                        for (int r = 0; r < kRegions && bad.empty(); ++r) {   // (A == B now: A's guards and values)
                            const size_t lo = r == 0 ? 0 : (at[r - 1] + rb[r - 1]);
                            for (size_t o = lo; o < at[r] && bad.empty(); ++o)
                                if (A[o] != 0xA5) bad = where(std::string("a guard before ") + rname[r], o);
                            const bool written = r == kX || r == kPre || r == kPost || r == kComb ||
                                                 (ffn && r == kCopy) || (q8 && r == kQd) ||
                                                 (!ffn && r >= kQr && r <= kCgr && r - kQr < nj) ||
                                                 (ffn && q8 && (r == kS1 || r == kS3));
                            if (!written || r == kQ) continue;
                            const size_t n = r == kPre || r == kPost || r == kCopy ? 4
                                             : r == kComb                          ? 16
                                             : r >= kS1                            ? (size_t) j[r - kS1].m->n
                                             : r >= kQr                            ? (size_t) j[r - kQr].m->n
                                                                                   : rb1[r] / 4;   // (a row's)
                            for (int t = 0; t < T; ++t)
                                for (size_t i = 0; i < n && bad.empty(); ++i) {
                                    const size_t o = rb1[r] * t + 4 * i;
                                    float v;
                                    std::memcpy(&v, A + at[r] + o, 4);
                                    if (!std::isfinite(v) || (r == kQd && !(v >= 0.0f))) bad = where(rname[r], o);
                                }
                        }
                        for (size_t o = at[kRegions - 1] + rb[kRegions - 1]; o < set_bytes && bad.empty(); ++o)
                            if (A[o] != 0xA5) bad = where("the last guard", o);
                    }
            cudaFree(in);   // (every run ended cleanly)
            cudaFree(out);
            cudaFreeHost(back);
            cudaEventDestroy(ev);
            if (!bad.empty()) return fail_at(bad);
            std::string kinds;
            for (int k = 2; k <= 4; ++k) {
                if (kind_held[k] && !kind_run[k])
                    return fail_at("the attention's " + std::to_string(k) + "-GEMV input not checked");
                if (kind_run[k]) kinds += (kinds.empty() ? "" : ", ") + std::to_string(k);
            }
            std::string ids;
            for (const Layer* lp : ls) ids += (ids.empty() ? "" : " ") + std::to_string(lp->il);
            std::fprintf(stderr,
                         "ds4: CUDA%d HC fuse check%s: %d runs (layers %s; attention inputs of %s GEMVs; attention and "
                         "FFN; random / edges / ties): pre, post, comb, the pre copy, x, its int8 rounding and the "
                         "attention GEMVs%s the old kernels' bit for bit, all finite, every guard intact "
                         "(DS4_HC_FUSE%s)\n",
                         d.id, rows.c_str(), runs, ids.c_str(), kinds.c_str(),
                         ffn_q8 ? ", the FFN's int8 rounding and the shared expert's w1 / w3 GEMVs" : "",
                         ffn_q8 ? "=2" : "");
        }
        return true;
    }

    // DS4_DECODE_TRIM's checks (at load, before any request).  trim_run: one run on device d's stream - the inputs up,
    // both output sets 0xA5, enqueue() (the old path into set 0, the new one into set 1), the readback, its end waited
    // for (10 s) - then the two sets' bytes compared and the bytes outside `regions` checked untouched.  false (why
    // set): a difference, a guard touched, a launch refused or a CUDA error before a clean end; no clean end ends the
    // process (trim_unknown: what the run may still touch is the model's)
    [[noreturn]] static void trim_unknown(int dev, const char* what, const char* why) {
        std::fprintf(stderr, "ds4: DS4_DECODE_TRIM check: CUDA%d (%s): %s - the device's state unknown; the process "
                             "ends without teardown (exit %d)\n",
                     dev, what, why, kExitUnknown);
        std::fflush(stderr);
        std::fflush(stdout);
        std::_Exit(kExitUnknown);
    }
    template <class F>
    bool trim_run(Dev& d, const std::string& what, const std::vector<float>& hin, size_t set_bytes,
                  const std::vector<std::pair<size_t, size_t>>& regions, F&& enqueue, std::string& why) {
        float* in = nullptr;
        uint8_t *out = nullptr, *back = nullptr;
        cudaEvent_t ev = nullptr;
        if (cudaMalloc((void**) &in, std::max<size_t>(1, hin.size()) * 4) != cudaSuccess ||
            cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess ||
            cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess ||
            cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
            (void) cudaGetLastError();
            if (in != nullptr) cudaFree(in);
            if (out != nullptr) cudaFree(out);
            if (back != nullptr) cudaFreeHost(back);
            if (ev != nullptr) cudaEventDestroy(ev);
            why = what + ": its buffers";
            return false;
        }
        bool ok = cudaMemcpyAsync(in, hin.data(), hin.size() * 4, cudaMemcpyHostToDevice, d.st) == cudaSuccess &&
                  cudaMemsetAsync(out, 0xA5, 2 * set_bytes, d.st) == cudaSuccess;
        ok = ok && enqueue(in, out, out + set_bytes);
        ok = ok && cudaGetLastError() == cudaSuccess &&
             cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, d.st) == cudaSuccess;
        const bool recorded = ok && cudaEventRecord(ev, d.st) == cudaSuccess;
        const auto t0 = std::chrono::steady_clock::now();
        cudaError_t q;
        while ((q = recorded ? cudaEventQuery(ev) : cudaStreamQuery(d.st)) == cudaErrorNotReady &&
               std::chrono::steady_clock::now() - t0 < std::chrono::seconds(10))
            std::this_thread::sleep_for(std::chrono::microseconds(100));
        if (q != cudaSuccess)
            trim_unknown(d.id, what.c_str(), q == cudaErrorNotReady ? "no end in time" : "an error at its end");
        if (!recorded) {
            (void) cudaGetLastError();
            why = what + ": a launch refused or a CUDA error";
        } else {
            const uint8_t *A = back, *B = back + set_bytes;
            for (size_t o = 0; o < set_bytes && why.empty(); ++o)
                if (A[o] != B[o]) why = what + ": byte " + std::to_string(o) + " differs";
            size_t prev = 0;   // (A == B now: A's bytes outside the regions)
            for (const auto& r : regions) {
                for (size_t o = prev; o < r.first && why.empty(); ++o)
                    if (A[o] != 0xA5) why = what + ": guard byte " + std::to_string(o);
                prev = r.first + r.second;
            }
            for (size_t o = prev; o < set_bytes && why.empty(); ++o)
                if (A[o] != 0xA5) why = what + ": the last guard byte " + std::to_string(o);
        }
        cudaFree(in);   // (the run ended cleanly)
        cudaFree(out);
        cudaFreeHost(back);
        cudaEventDestroy(ev);
        return recorded && why.empty();
    }
    // DS4_DECODE_TRIM 1 / 2, on every device with layers: for its first and last layer (its member), on 1 and kWin
    // rows of random inputs and of edges (zeros, negative zeros, tiny, and large past the clamp, 32-blocks of each):
    // 1 swiglu_q8 against swiglu, 2 q's norm finish with its int8 rounding against the finish, each then q8_round (the
    // rounding gguf mv gives the old path) and the layer's s2 / wq_b through mv - the old path's rounding its own, the
    // new one's given (PreQ8): the activations, the int8 rows and scales and the GEMV's rows equal byte for byte
    bool trim_q8_check(std::string& err) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x51ed2701u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            std::vector<const Layer*> ls;
            for (const Layer& l0 : L)
                if (!l0.mtp)
                    for (int mm = 0; mm < l0.nm; ++mm)
                        if (member(l0, mm).dev == (int) di) ls.push_back(&member(l0, mm));
            if (ls.empty()) continue;
            if (ls.size() > 2) ls = {ls.front(), ls.back()};
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            int runs = 0;
            for (const Layer* lp : ls)
                for (int part = 1; part <= 2; ++part) {
                    if (!(decode_trim & part)) continue;
                    const Layer& l = *lp;
                    const x3::Mat& m = part == 1 ? l.s2 : l.wq_b;
                    if (m.raw == nullptr || m.n <= 0 || m.k <= 0) continue;
                    const int K = m.k, N = m.n;   // (s2: the member's ff part in; wq_b: q_lora in, its heads out)
                    if (K % 32 != 0 || (part == 2 && K != g.q_lora)) {
                        err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": layer " +
                              std::to_string(l.il) + (part == 1 ? "'s s2" : "'s wq_b") + " takes " + std::to_string(K) +
                              " values";
                        return false;
                    }
                    for (int T : {1, kWin})
                        for (int kind = 0; kind < 2; ++kind) {
                            const size_t n = (size_t) T * K;
                            const size_t rb[4] = {n * 4, n, n / 32 * 4, (size_t) T * N * 4};   // act | q | qd | y
                            size_t at[4], set_bytes = 0;
                            std::vector<std::pair<size_t, size_t>> regions;
                            for (int r = 0; r < 4; ++r) {
                                at[r] = set_bytes + kGuard;
                                set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
                                regions.push_back({at[r], rb[r]});
                            }
                            set_bytes += kGuard;
                            std::vector<float> hin(part == 1 ? 2 * n : n);
                            for (size_t i = 0; i < hin.size(); ++i) {
                                float v = rnd();
                                if (kind == 1)
                                    switch ((i / 32) % 6) {
                                        case 0: v = 0.0f; break;
                                        case 1: v = -0.0f; break;
                                        case 2: v *= 1e-20f; break;
                                        case 3: v *= 1e6f; break;   // (past swiglu's clamp)
                                        default: break;
                                    }
                                hin[i] = v;
                            }
                            auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                                uint8_t* set[2] = {s0, s1};
                                auto A = [&](int b) { return (float*) (set[b] + at[0]); };
                                auto Q = [&](int b) { return (int8_t*) (set[b] + at[1]); };
                                auto Qd = [&](int b) { return (float*) (set[b] + at[2]); };
                                auto Y = [&](int b) { return (float*) (set[b] + at[3]); };
                                bool ok = true;
                                if (part == 1) {
                                    swiglu(in, in + n, (int) n, g.lim, A(0), d.st);
                                    ok = swiglu_q8(in, in + n, (int) n, g.lim, A(1), Q(1), Qd(1), d.st);
                                } else {
                                    Finish f0;
                                    f0.w = l.q_norm;
                                    f0.eps = g.eps;
                                    Finish f1 = f0;
                                    f1.q8 = Q(1);
                                    f1.q8d = Qd(1);
                                    ok = cudaMemcpyAsync(A(0), in, n * 4, cudaMemcpyDeviceToDevice, d.st) ==
                                             cudaSuccess &&
                                         cudaMemcpyAsync(A(1), in, n * 4, cudaMemcpyDeviceToDevice, d.st) ==
                                             cudaSuccess;
                                    finish(A(0), T, K, K, f0, d.st);
                                    finish(A(1), T, K, K, f1, d.st);
                                }
                                for (int t = 0; t < T; ++t)   // (the old path's rounding, as mv gives it)
                                    gg::q8_round(A(0) + (size_t) t * K, K, Q(0) + (size_t) t * K,
                                                 Qd(0) + (size_t) t * (K / 32), d.st);
                                x3::MvJob j0 = job(m, A(0), Y(0), T, K, N), j1 = job(m, A(1), Y(1), T, K, N);
                                gg::PreQ8 pq;
                                pq.x = A(1);
                                pq.q = Q(1);
                                pq.d = Qd(1);
                                pq.k = K;
                                pq.rows = T;
                                return ok && mv_any(&j0, 1, d.st) && mv_any(&j1, 1, d.st, &pq);
                            };
                            std::string why;
                            const std::string what =
                                std::string(part == 1 ? "s2's int8 from swiglu" : "wq_b's int8 from q's norm") +
                                ", layer " + std::to_string(l.il) + ", " + std::to_string(T) +
                                (kind ? " rows, edges" : " rows, random");
                            if (!trim_run(d, what, hin, set_bytes, regions, enqueue, why)) {
                                err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": " + why;
                                std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check FAILED: %s\n", d.id,
                                             why.c_str());
                                return false;
                            }
                            ++runs;
                        }
                }
            std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check: %d runs (the first and last layers; 1 and %d "
                                 "rows; random / edges):%s%s the activations, int8 rows and scales and the GEMVs the "
                                 "old path's bit for bit, every guard intact\n",
                         d.id, runs, kWin, decode_trim & 1 ? " swiglu_q8 + s2;" : "",
                         decode_trim & 2 ? " q's norm + wq_b;" : "");
        }
        return true;
    }
    // DS4_DECODE_TRIM 4 / 8: 4 copy_regions against four runtime copies (odd lengths, every device); 8 the drafter's
    // hand-off path - xfer_put of random rows into a device's host-mapped dhand (both regions: a block's h | pre and
    // the x rows) and xfer_get on every other device - against the rows put, for every ordered pair of devices
    bool trim_copy_check(std::string& err) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x2b7e1516u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        if (decode_trim & 4)
            for (Dev& d : devs) {
                if (cudaSetDevice(d.id) != cudaSuccess) {
                    (void) cudaGetLastError();
                    err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                    return false;
                }
                const size_t nf[4] = {1, 37, 1024, 4099};   // (floats a region)
                size_t at[4], set_bytes = 0, src_at[4], n_in = 0;
                std::vector<std::pair<size_t, size_t>> regions;
                for (int r = 0; r < 4; ++r) {
                    at[r] = set_bytes + kGuard;
                    set_bytes = (at[r] + nf[r] * 4 + 255) / 256 * 256;
                    regions.push_back({at[r], nf[r] * 4});
                    src_at[r] = n_in;
                    n_in += nf[r];
                }
                set_bytes += kGuard;
                std::vector<float> hin(n_in);
                for (float& v : hin) v = rnd();
                auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                    CopyRegions cr;
                    bool ok = true;
                    for (int r = 0; r < 4; ++r) {
                        ok = ok && cudaMemcpyAsync(s0 + at[r], in + src_at[r], nf[r] * 4, cudaMemcpyDeviceToDevice,
                                                   d.st) == cudaSuccess;
                        cr.dst[r] = s1 + at[r];
                        cr.src[r] = in + src_at[r];
                        cr.bytes[r] = nf[r] * 4;
                    }
                    cr.n = 4;
                    return ok && copy_regions(cr, d.st);
                };
                std::string why;
                if (!trim_run(d, "copy_regions", hin, set_bytes, regions, enqueue, why)) {
                    err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": " + why;
                    std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check FAILED: %s\n", d.id, why.c_str());
                    return false;
                }
                std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check: copy_regions (4 regions, 1 .. 4099 floats) "
                                     "the runtime copies' bytes, every guard intact\n",
                             d.id);
            }
        if (!(decode_trim & 8) || g.n_mtp == 0) return true;
        int pairs = 0;
        for (Dev& a : devs)
            for (Dev& b : devs) {
                if (&a == &b || a.dhand == nullptr || b.dhand == nullptr) continue;
                const size_t r0 = dhand_x(), r1 = (size_t) kWin * g.dim * 4;   // (the two regions' bytes)
                std::vector<float> hin((r0 + r1) / 4);
                for (float& v : hin) v = rnd();
                float *src = nullptr, *dst = nullptr, *back = nullptr;
                cudaEvent_t ea = nullptr, eb = nullptr;
                bool ok = cudaSetDevice(a.id) == cudaSuccess && cudaMalloc((void**) &src, r0 + r1) == cudaSuccess &&
                          cudaEventCreateWithFlags(&ea, cudaEventDisableTiming) == cudaSuccess &&
                          cudaSetDevice(b.id) == cudaSuccess && cudaMalloc((void**) &dst, r0 + r1) == cudaSuccess &&
                          cudaMallocHost((void**) &back, r0 + r1) == cudaSuccess &&
                          cudaEventCreateWithFlags(&eb, cudaEventDisableTiming) == cudaSuccess;
                const unsigned sq = ++d_xseq;
                bool recorded = false;
                if (ok) {
                    Xfer px, gx;
                    px.n = gx.n = 2;
                    px.src[0] = src;
                    px.dst[0] = a.dhand;
                    px.src[1] = (const uint8_t*) src + r0;
                    px.dst[1] = a.dhand + r0;
                    gx.src[0] = a.dhand;
                    gx.dst[0] = dst;
                    gx.src[1] = a.dhand + r0;
                    gx.dst[1] = (uint8_t*) dst + r0;
                    px.bytes[0] = gx.bytes[0] = r0;
                    px.bytes[1] = gx.bytes[1] = r1;
                    cudaSetDevice(a.id);
                    ok = cudaMemcpyAsync(src, hin.data(), r0 + r1, cudaMemcpyHostToDevice, a.st) == cudaSuccess;
                    if (ok) xfer_put(px, a.dhand_flag, sq, a.xcnt, a.st);
                    ok = ok && cudaGetLastError() == cudaSuccess && cudaEventRecord(ea, a.st) == cudaSuccess;
                    cudaSetDevice(b.id);
                    if (ok) xfer_get(gx, a.dhand_flag, sq, b.st);
                    ok = ok && cudaGetLastError() == cudaSuccess &&
                         cudaMemcpyAsync(back, dst, r0 + r1, cudaMemcpyDeviceToHost, b.st) == cudaSuccess;
                    recorded = ok && cudaEventRecord(eb, b.st) == cudaSuccess;
                }
                const auto t0 = std::chrono::steady_clock::now();
                for (Dev* e : {&a, &b}) {   // (each device's end: its event, else its stream)
                    cudaSetDevice(e->id);
                    cudaEvent_t ev = e == &a ? ea : eb;
                    cudaError_t q;
                    while ((q = recorded ? cudaEventQuery(ev) : cudaStreamQuery(e->st)) == cudaErrorNotReady &&
                           std::chrono::steady_clock::now() - t0 < std::chrono::seconds(10))
                        std::this_thread::sleep_for(std::chrono::microseconds(100));
                    if (q != cudaSuccess)
                        trim_unknown(e->id, "the drafter's hand-off",
                                     q == cudaErrorNotReady ? "no end in time" : "an error at its end");
                }
                std::string why;
                if (!recorded) {
                    (void) cudaGetLastError();
                    why = "a launch refused or a CUDA error";
                } else if (std::memcmp(back, hin.data(), r0 + r1) != 0)
                    why = "the rows differ";
                cudaSetDevice(a.id);
                if (src != nullptr) cudaFree(src);
                if (ea != nullptr) cudaEventDestroy(ea);
                cudaSetDevice(b.id);
                if (dst != nullptr) cudaFree(dst);
                if (back != nullptr) cudaFreeHost(back);
                if (eb != nullptr) cudaEventDestroy(eb);
                if (!why.empty()) {
                    err = "DS4_DECODE_TRIM check: the drafter's hand-off CUDA" + std::to_string(a.id) + " -> CUDA" +
                          std::to_string(b.id) + ": " + why;
                    std::fprintf(stderr, "ds4: DS4_DECODE_TRIM check FAILED: %s\n", err.c_str());
                    return false;
                }
                ++pairs;
            }
        std::fprintf(stderr, "ds4: DS4_DECODE_TRIM check: the drafter's hand-offs by xfer, %d device pairs (both "
                             "regions, %zu + %zu bytes): every row as put\n",
                     pairs, dhand_x(), (size_t) kWin * g.dim * 4);
        return true;
    }

    // DS4_ROUTE_FUSE=1 (at load, before any request), on every device with layers: gemv_f32_pair and route_pair (with
    // its publish) against what they replace - two gemv_f32 launches; route_ahead, then route_publish with its publish.
    // The GEMVs: the device's first and last pair of a layer and its next (and the first layer with an image-token
    // bias), their real gates on a random and an edge x (zeros, negative zeros, tiny and large magnitudes), plus rows
    // not a whole block (300 and 13 of the first gate's).  The routing: the real logits, real gates' biases and VRAM
    // table; tied logits, logits past the softplus's 20 and negative, the request's x copied (a pick on the CPU lane)
    // and not (every pick in VRAM), no image bias / its bit on / its pointer given and its bit off, n 257 (not a whole
    // block), m 1, k and 16.  Every output (both logits, idx / w / plan_ptr, the whole request) starts 0xA5 between
    // guards; both paths' bytes must be equal - every value, untouched byte and guard - and the weights finite.  On
    // d.st, each run's end waited for (10 s): a mismatch or an error after a clean end fails the load (everything
    // freed); no clean end ends the process at once (route_unknown).  T rows (DS4_ROUTE_FUSE=2: 3 and kWin, a decode
    // window's - 3 a part of gemv_f32_rows_kernel's 8 tokens a block, kWin two whole ones): x, both logits, the picks,
    // weights and plan T rows at the decode buffers' strides, the old path's gemv_f32 / route_ahead / route_publish
    // on T rows, the image bit on row 0 or 1; T 1 is the check above
    [[noreturn]] static void route_unknown(int dev, int il, const char* what, const char* why) {
        std::fprintf(stderr, "ds4: route fuse check: CUDA%d (layer %d, %s): %s - the device's state unknown; the "
                             "process ends without teardown (exit %d)\n",
                     dev, il, what, why, kExitUnknown);
        std::fflush(stderr);
        std::fflush(stdout);
        std::_Exit(kExitUnknown);
    }
    bool route_fuse_check(std::string& err, int T = 1) {
        const int D = g.dim;
        constexpr size_t kGuard = 64;
        // one set of outputs: [guard | region]... | guard, in bytes (T rows each, the decode buffers' strides)
        enum { kLog, kLogA, kIdx, kW, kPlan, kReq, kRegions };
        const size_t rb[kRegions] = {(size_t) T * 1024 * 4,   (size_t) T * 1024 * 4,   (size_t) T * kPicks * 4,
                                     (size_t) T * kPicks * 4, (size_t) T * kPicks * 8, sizeof(Req)};
        size_t at[kRegions], set_bytes = 0;
        for (int r = 0; r < kRegions; ++r) {
            at[r] = set_bytes + kGuard;
            set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
        }
        set_bytes += kGuard;
        // inputs: x | synthetic logits, the guesses' logits (T rows each) | biases (routing, image, guesses) | a VRAM
        // table
        const size_t n_in = (size_t) T * (D + 2 * 1024) + 1024 * 3;
        const std::string rows = T > 1 ? " (" + std::to_string(T) + " rows)" : "";
        uint32_t st = 0x7f4a7c15u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[(size_t) di];
            // (a layer, its next layer: both this device's member of the trunk's consecutive layers)
            std::vector<std::pair<const Layer*, const Layer*>> pairs, all;
            for (size_t j = 0; j + 1 < L.size(); ++j) {
                const Layer &a0 = L[j], &b0 = L[j + 1];
                if (a0.mtp || b0.mtp) continue;
                for (int m = 0; m < a0.nm && m < b0.nm; ++m)
                    if (member(a0, m).dev == (int) di && member(b0, m).dev == (int) di &&
                        member(a0, m).gate_w != nullptr && member(b0, m).gate_w != nullptr &&
                        member(a0, m).n_exp <= 1024 && member(b0, m).n_exp <= 1024)
                        all.push_back({&member(a0, m), &member(b0, m)});
            }
            if (all.empty()) continue;
            pairs.push_back(all.front());
            if (all.size() > 1) pairs.push_back(all.back());
            for (const auto& p : all)
                if (p.first->gate_bias_vl != nullptr) {
                    if (std::find(pairs.begin(), pairs.end(), p) == pairs.end()) pairs.push_back(p);
                    break;
                }
            auto fail_at = [&](const std::string& why) {
                err = "route fuse check" + rows + " on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d route fuse check%s FAILED: %s\n", d.id, rows.c_str(), why.c_str());
                return false;
            };
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                return fail_at("cudaSetDevice failed");
            }
            const cudaStream_t s = d.st;
            float* in = nullptr;
            uint8_t *out = nullptr, *back = nullptr;
            cudaEvent_t ev = nullptr;
            if (cudaMalloc((void**) &in, n_in * 4) != cudaSuccess ||
                cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess ||
                cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess ||
                cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
                (void) cudaGetLastError();
                if (in != nullptr) cudaFree(in);
                if (out != nullptr) cudaFree(out);
                if (back != nullptr) cudaFreeHost(back);
                if (ev != nullptr) cudaEventDestroy(ev);
                return fail_at("its buffers");
            }
            float *x = in, *lg = in + (size_t) D * T, *lga = lg + 1024 * T, *bias = lga + 1024 * T,
                  *bias_vl = bias + 1024;
            unsigned long long* vram = (unsigned long long*) (bias_vl + 1024);   // (1024 floats: 512 entries)
            std::vector<float> hin(n_in);   // (the host's inputs: written again only after the run before has ended)
            uint8_t* set[2] = {out, out + set_bytes};   // the old path's, the fused one's
            auto F = [&](int b, int r) { return (float*) (set[b] + at[r]); };
            int runs = 0;
            std::string bad;
            // one run: the inputs up, both sets filled, the old path (b 0) then the fused one (b 1), the readback, its
            // end; then every byte compared
            auto run = [&](const char* what, int il, auto&& old_path, auto&& new_path, size_t n_log, size_t n_loga,
                           int k) {
                bool ok = cudaMemcpyAsync(in, hin.data(), n_in * 4, cudaMemcpyHostToDevice, s) == cudaSuccess &&
                          cudaMemsetAsync(out, 0xA5, 2 * set_bytes, s) == cudaSuccess;
                ok = ok && old_path() && new_path();
                ok = ok && cudaGetLastError() == cudaSuccess &&
                     cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, s) == cudaSuccess;
                const bool recorded = ok && cudaEventRecord(ev, s) == cudaSuccess;
                const auto t0 = std::chrono::steady_clock::now();
                cudaError_t q;
                while ((q = recorded ? cudaEventQuery(ev) : cudaStreamQuery(s)) == cudaErrorNotReady &&
                       std::chrono::steady_clock::now() - t0 < std::chrono::seconds(10))
                    std::this_thread::sleep_for(std::chrono::microseconds(100));
                if (q != cudaSuccess)
                    route_unknown(d.id, il, what, q == cudaErrorNotReady ? "no end in time" : "an error at its end");
                if (!recorded) {   // (a CUDA error or a refused launch before the end, which was clean)
                    (void) cudaGetLastError();
                    bad = std::string(what) + ", layer " + std::to_string(il) + ": a launch refused or a CUDA error";
                    return;
                }
                ++runs;
                const uint8_t *A = back, *B = back + set_bytes;
                for (size_t o = 0; o < set_bytes && bad.empty(); ++o)
                    if (A[o] != B[o])
                        bad = std::string(what) + ", layer " + std::to_string(il) + ": an output byte " +
                              std::to_string(o);
                size_t prev = 0;   // (A == B now: A's guards and values)
                for (int r = 0; r < kRegions && bad.empty(); ++r) {
                    for (size_t o = prev; o < at[r] && bad.empty(); ++o)
                        if (A[o] != 0xA5) bad = std::string(what) + ": a guard byte " + std::to_string(o);
                    prev = at[r] + rb[r];
                }
                for (size_t o = prev; o < set_bytes && bad.empty(); ++o)
                    if (A[o] != 0xA5) bad = std::string(what) + ": the last guard byte " + std::to_string(o);
                const size_t nf[3] = {n_log, n_loga, (size_t) k};   // (the logits written, then the weights: a row's)
                const int rf[3] = {kLog, kLogA, kW};
                const size_t rs[3] = {1024, 1024, kPicks};   // (rows apart)
                for (int q2 = 0; q2 < 3 && bad.empty(); ++q2)
                    for (int t = 0; t < T; ++t)
                        for (size_t i = 0; i < nf[q2] && bad.empty(); ++i) {
                            float v;
                            std::memcpy(&v, A + at[rf[q2]] + 4 * (rs[q2] * t + i), 4);
                            if (!std::isfinite(v)) bad = std::string(what) + ": a value not finite";
                        }
            };
            for (const auto& pr : pairs) {
                const Layer &l = *pr.first, &nx = *pr.second;
                for (int kind = 0; kind < 2 && bad.empty(); ++kind) {   // the GEMVs: random, edges
                    for (size_t e = 0; e < (size_t) D * T; ++e) {
                        float v = rnd();
                        if (kind == 1)
                            switch ((e % (size_t) D / 32) % 6) {
                                case 0: v = 0.0f; break;
                                case 1: v = -0.0f; break;
                                case 2: v *= 1e-20f; break;
                                case 3: v *= 1e15f; break;
                                default: break;
                            }
                        hin[(size_t) e] = v;
                    }
                    run(kind ? "the gates, edges" : "the gates, random", l.il,
                        [&] {
                            gemv_f32(l.gate_w, x, l.n_exp, D, T, F(0, kLog), 1024, s);
                            gemv_f32(nx.gate_w, x, nx.n_exp, D, T, F(0, kLogA), 1024, s);
                            return true;
                        },
                        [&] {
                            return gemv_f32_pair(l.gate_w, l.n_exp, F(1, kLog), nx.gate_w, nx.n_exp, F(1, kLogA), x, D,
                                                 s, T, 1024);
                        },
                        (size_t) l.n_exp, (size_t) nx.n_exp, 0);
                }
            }
            const Layer &l = *pairs.front().first, &nx = *pairs.front().second;
            if (bad.empty())   // (rows not a whole block: 300 and 13 of the first gate's)
                run("the gates, 300 and 13 rows", l.il,
                    [&] {
                        gemv_f32(l.gate_w, x, std::min(300, l.n_exp), D, T, F(0, kLog), 1024, s);
                        gemv_f32(nx.gate_w, x, std::min(13, nx.n_exp), D, T, F(0, kLogA), 1024, s);
                        return true;
                    },
                    [&] {
                        return gemv_f32_pair(l.gate_w, std::min(300, l.n_exp), F(1, kLog), nx.gate_w,
                                             std::min(13, nx.n_exp), F(1, kLogA), x, D, s, T, 1024);
                    },
                    (size_t) std::min(300, l.n_exp), (size_t) std::min(13, nx.n_exp), 0);
            // the routing: logits kind (0 real - the first gates' on a random x, 1 ties, 2 past 20 and negative, 3
            // random), VRAM (0 the layer's, 1 every pick in VRAM, 2 none, 3 mixed), image bias (0 none, 1 its bit on,
            // 2 its pointer and its bit off), n (0 the layer's, 1 257), m
            struct Case {
                int logits, vram, vl, n257, m;
            };
            const Case cases[] = {{0, 0, 0, 0, l.k_exp}, {1, 1, 0, 0, kAhead1}, {1, 2, 1, 0, 1}, {2, 3, 2, 0, l.k_exp},
                                  {3, 3, 0, 1, kAhead1}, {0, 2, l.gate_bias_vl != nullptr ? 1 : 0, 0, l.k_exp}};
            for (const Case& c : cases) {
                if (!bad.empty()) break;
                const int n = c.n257 ? std::min(257, l.n_exp) : l.n_exp;
                const int an = c.n257 ? std::min(257, nx.n_exp) : nx.n_exp;
                for (size_t e = 0; e < (size_t) D * T; ++e) hin[e] = rnd();
                float *hl = hin.data() + (size_t) D * T, *hla = hl + 1024 * T, *hb = hla + 1024 * T, *hbv = hb + 1024;
                for (int t = 0; t < T; ++t)
                    for (int i = 0; i < 1024; ++i) {
                        float v = rnd(), va = rnd();
                        if (c.logits == 1) v = (float) (i % 5) * 0.5f, va = (float) (i % 3);          // ties
                        if (c.logits == 2) v = i % 2 ? 20.0f + (float) (i % 7) : -v * 10.0f, va = -va * 5.0f;
                        hl[1024 * t + i] = v;
                        hla[1024 * t + i] = va;
                        if (t > 0) continue;   // (the biases: one set)
                        hb[i] = c.logits == 1 ? 0.0f : 0.05f * rnd();
                        hbv[i] = 0.05f * rnd();
                    }
                unsigned long long* hv = (unsigned long long*) (hbv + 1024);
                for (int i = 0; i < 512; ++i)   // (every pick in VRAM, none, or two in three)
                    hv[i] = c.vram == 1   ? 0x1000ull + (unsigned long long) i * 64
                            : c.vram == 2 ? 0ull
                                          : (i % 3 ? 0x2000ull + (unsigned long long) i : 0ull);
                const unsigned vl = c.vl == 1 ? 1u : c.vl == 2 ? 2u : 0u;
                const float* bv = c.vl == 0                                    ? nullptr
                                  : c.logits == 0 && l.gate_bias_vl != nullptr ? l.gate_bias_vl
                                                                               : bias_vl;
                const float* rb0 = c.logits == 0 ? l.gate_bias : bias;
                const float* rba = c.logits == 0 ? nx.gate_bias : bias;
                const unsigned long long* vt = c.vram == 0 ? l.vram_tab : vram;
                if (c.vram == 0 && vt == nullptr) continue;   // (no VRAM table on this member: nothing to compare)
                if (c.vram != 0 && n > 512) continue;
                const unsigned seq = 0x51u + (unsigned) runs;
                run("the routing", l.il,
                    [&] {
                        if (c.logits == 0) {   // (the logits: the first gates' on this x, the same in both sets)
                            gemv_f32(l.gate_w, x, n, D, T, F(0, kLog), 1024, s);
                            gemv_f32(nx.gate_w, x, an, D, T, F(0, kLogA), 1024, s);
                            gemv_f32(l.gate_w, x, n, D, T, F(1, kLog), 1024, s);
                            gemv_f32(nx.gate_w, x, an, D, T, F(1, kLogA), 1024, s);
                        } else {
                            for (int b = 0; b < 2; ++b)
                                if (cudaMemcpyAsync(F(b, kLog), lg, (size_t) T * 1024 * 4, cudaMemcpyDeviceToDevice,
                                                    s) != cudaSuccess ||
                                    cudaMemcpyAsync(F(b, kLogA), lga, (size_t) T * 1024 * 4, cudaMemcpyDeviceToDevice,
                                                    s) != cudaSuccess)
                                    return false;
                        }
                        Req* rq = (Req*) (set[0] + at[kReq]);
                        route_ahead(F(0, kLogA), rba, an, c.m, T, rq, 0, s);
                        route_publish(F(0, kLog), rb0, n, l.k_exp, T, g.route_scale, vt, x, D, (int*) F(0, kIdx),
                                      F(0, kW), (unsigned long long*) F(0, kPlan), rq, seq, s, bv, vl, c.m, 0);
                        return true;
                    },
                    [&] {
                        RoutePair a;
                        a.logits = F(1, kLog);
                        a.bias = rb0;
                        a.n = n;
                        a.k = l.k_exp;
                        a.route_scale = g.route_scale;
                        a.vram = vt;
                        a.x = x;
                        a.dim = D;
                        a.idx = (int*) F(1, kIdx);
                        a.w = F(1, kW);
                        a.plan_ptr = (unsigned long long*) F(1, kPlan);
                        a.req = (Req*) (set[1] + at[kReq]);
                        a.vl = vl;
                        a.bias_vl = vl != 0 ? bv : nullptr;
                        a.seq = seq;
                        a.na0 = c.m;
                        a.a_logits = F(1, kLogA);
                        a.a_bias = rba;
                        a.a_n = an;
                        a.m = c.m;
                        a.T = T;
                        return route_pair(a, s);
                    },
                    c.logits == 0 ? (size_t) n : 1024, c.logits == 0 ? (size_t) an : 1024, l.k_exp);
            }
            cudaFree(in);   // (every run ended cleanly)
            cudaFree(out);
            cudaFreeHost(back);
            cudaEventDestroy(ev);
            if (!bad.empty()) return fail_at(bad);
            std::string ids;
            for (const auto& p : pairs) ids += (ids.empty() ? "" : " ") + std::to_string(p.first->il);
            std::fprintf(stderr,
                         "ds4: CUDA%d route fuse check%s: %d runs (gates of layers %s and their next; the routing: "
                         "real, tied, past 20 and negative logits, the request's x copied and not, the image bias off "
                         "/ on / given and off, n 257, m 1 .. 16): both logits, the picks, weights, plan and the whole "
                         "request the old launches' bit for bit, all finite, every guard intact (DS4_ROUTE_FUSE%s)\n",
                         d.id, rows.c_str(), runs, ids.c_str(), T > 1 ? "=2" : "");
        }
        return true;
    }

    // DS4_TP_CHECK=1 (DS4_TP_GGUF_UNEVEN, at load, before any request): for each expert format and each rotation of the
    // split layers (which member takes the odd block) - every one they have - one token through every member's parts
    // (tp_check_member: three experts the layer holds in VRAM, weights 0.5 / 0.3 / 0.2, and the shared expert), the
    // parts summed on the host in member order, against the whole: the CPU lane's sums of the same experts
    // (cpu_experts) and the shared expert from the pack's whole matrices (shared_host). Off by more than kTpCheckTol of
    // the largest output, not finite, a CUDA error, or a format and rotation with no split layer holding three of its
    // experts in VRAM (not checked - so no pass): the load fails
    bool tp_check(std::string& err) {
        const int D = g.dim;
        const float w[3] = {0.5f, 0.3f, 0.2f};
        auto split = [&](const Layer& l) { return !l.mtp && l.nm > 1 && l.lay.fmt == gg::kFmtMXFP4; };
        auto format = [&](const Layer& l) {
            std::string fmt;
            for (int r = 0; r < 3; ++r) fmt += std::string(r ? "/" : "") + gg::type_name(gg::expert_type(l.lay, r));
            return fmt;
        };
        std::vector<std::string> want, seen;   // (format + " " + rotation)
        for (const Layer& l : L)
            if (split(l)) {
                const std::string key = format(l) + " " + std::to_string(l.il % l.nm);
                if (std::find(want.begin(), want.end(), key) == want.end()) want.push_back(key);
            }
        for (const Layer& l : L) {
            if (!split(l)) continue;
            const std::string fmt = format(l);
            const std::string key = fmt + " " + std::to_string(l.il % l.nm);
            if (std::find(seen.begin(), seen.end(), key) != seen.end()) continue;
            std::vector<int> held;
            for (int e = 0; e < l.n_exp && held.size() < 3; ++e)
                if (l.slot[(size_t) e] >= 0) held.push_back(e);
            if (held.size() < 3) continue;
            seen.push_back(key);
            std::vector<float> x((size_t) D);
            double ss = 0;
            for (int i = 0; i < D; ++i) {
                x[(size_t) i] = std::sin(0.37f * (float) i + 0.11f * (float) l.il) + ((i % 89) == 0 ? 5.0f : 0.0f);
                ss += (double) x[(size_t) i] * x[(size_t) i];
            }
            for (float& v : x) v = (float) (v / std::sqrt(ss / D));
            std::vector<float> got_r((size_t) D, 0.0f), got_s((size_t) D, 0.0f), r, sh;
            for (int m = 0; m < l.nm; ++m) {   // (member order: the all-reduce's)
                if (!tp_check_member(l, m, x, held, w, r, sh, err)) return false;
                for (int j = 0; j < D; ++j) {
                    got_r[(size_t) j] += r[(size_t) j];
                    got_s[(size_t) j] += sh[(size_t) j];
                }
            }
            std::vector<float> want_r((size_t) D, 0.0f), want_s;
            for (int i = 0; i < 3; ++i) {
                std::vector<Ent> ents(1);
                ents[0].e = held[(size_t) i];
                ents[0].n = 1;
                ents[0].tok[0] = 0;
                cpu_experts(l, x.data(), ents, (size_t) D);
                for (int j = 0; j < D; ++j) want_r[(size_t) j] += w[i] * c_yd[(size_t) j];
            }
            if (!shared_host(l, x, want_s, err)) return false;
            auto compare = [&](const std::vector<float>& want, const std::vector<float>& got, double& worst_rel) {
                double mx = 0, worst = 0;
                bool finite = true;   // (both sides: a reference's NaN or Inf would pass any std::max bound unseen)
                for (int j = 0; j < D; ++j) mx = std::max(mx, (double) std::fabs(want[(size_t) j]));
                for (int j = 0; j < D; ++j) {
                    finite = finite && std::isfinite(got[(size_t) j]) && std::isfinite(want[(size_t) j]);
                    worst = std::max(worst, std::fabs((double) want[(size_t) j] - (double) got[(size_t) j]));
                }
                worst_rel = mx > 0 ? worst / mx : worst;
                return finite && worst_rel <= kTpCheckTol;
            };
            double rr = 0, rs = 0;
            const bool ok_r = compare(want_r, got_r, rr), ok_s = compare(want_s, got_s, rs);
            int f0 = 0, wide = 0;
            for (int m = 0; m < l.nm; ++m)
                if (member(l, m).ffn > wide) wide = member(l, m).ffn, f0 = m;
            std::fprintf(stderr, "ds4: TP check: %s (layer %d, member %d takes %d of %d): %d members' parts summed against "
                                 "the whole - routed (3 experts) %s%.3g of the largest, shared %s%.3g\n",
                         fmt.c_str(), l.il, f0, wide, g.ff, l.nm, ok_r ? "" : "TOO FAR - ", rr, ok_s ? "" : "TOO FAR - ",
                         rs);
            if (!ok_r || !ok_s) {
                err = "TP check FAILED: " + fmt + " (layer " + std::to_string(l.il) + ")";
                return false;
            }
        }
        for (const std::string& key : want)
            if (std::find(seen.begin(), seen.end(), key) == seen.end()) {
                err = "TP check: " + key.substr(0, key.rfind(' ')) + ", rotation " + key.substr(key.rfind(' ') + 1) +
                      ": no split layer holds three of its experts in VRAM - not checked";
                return false;
            }
        if (want.empty()) {
            err = "TP check: no split layer to check";
            return false;
        }
        bool flow = false;   // (DS4_FLOW_TP: a split layer's member on the flow)
        for (const Layer& l : L)
            if (split(l))
                for (int m = 0; m < l.nm; ++m) {
                    const int di = member(l, m).dev;
                    flow = flow || ((size_t) di < chunks.size() && chunks[(size_t) di] != nullptr && chunks[(size_t) di]->flow);
                }
        if (flow) {   // (each format and rotation, each member: the first split layer of the key)
            int n = 0;
            for (const std::string& key : want)
                for (const Layer& l : L) {
                    if (!split(l) || format(l) + " " + std::to_string(l.il % l.nm) != key) continue;
                    for (int m = 0; m < l.nm; ++m, ++n)
                        if (!tp_flow_member(l, m, err)) return false;
                    break;
                }
            std::fprintf(stderr, "ds4: TP check: the flow's copies passed (%d of the formats', rotations' and members' "
                                 "copies) (DS4_FLOW_TP)\n", n);
        }
        {   // the prompt path off the flow (copy_ahead: stage_streamed, copy_streamed) - each split layer's format and
            // rotation, each such member, and each format of the layers a device holds alone: an expert from its RAM
            // copy and one from the file, through the device (tp_copy_member)
            int n = 0;
            std::vector<std::string> done;   // (each key's first layer: a split one's format and rotation, else its format)
            for (const Layer& l : L) {
                const bool sp = split(l);
                if (l.mtp || l.lay.fmt != gg::kFmtMXFP4 || (!sp && l.nm != 1)) continue;
                const std::string key = sp ? format(l) + " " + std::to_string(l.il % l.nm) : format(l) + " alone";
                if (std::find(done.begin(), done.end(), key) != done.end()) continue;
                bool any = false;
                for (int m = 0; m < l.nm; ++m) {
                    const Layer& x = member(l, m);
                    const Chunk* cp = (size_t) x.dev < chunks.size() ? chunks[(size_t) x.dev].get() : nullptr;
                    if (cp == nullptr || cp->stage == nullptr || cp->flow) continue;
                    any = true;
                    int e_ram = -1, e_file = -1;
                    for (int e = 0; e < l.n_exp; ++e) {
                        const bool in_ram = !l.ram.empty() && l.ram[(size_t) e] >= 0;
                        if (in_ram && e_ram < 0) e_ram = e;
                        if (!in_ram && e_file < 0) e_file = e;
                    }
                    for (int e : {e_ram, e_file}) {
                        if (e < 0) continue;
                        size_t bad = 0, bad_guard = 0;
                        if (!tp_copy_member(l, m, e, bad, bad_guard, err)) return false;
                        if (bad + bad_guard > 0) {
                            std::fprintf(stderr, "ds4: TP check: prompt copies %s (layer %d, member %d takes %d of %d, expert "
                                                 "%d from %s%s) FAILED: %zu bytes, %zu guard bytes differ\n",
                                         format(l).c_str(), l.il, m, x.ffn, g.ff, e, e == e_ram ? "RAM" : "the file",
                                         stream_direct(l, e) ? ", in place" : "", bad, bad_guard);
                            err = "TP check FAILED: prompt copies (layer " + std::to_string(l.il) + ")";
                            return false;
                        }
                        ++n;
                    }
                }
                if (any) done.push_back(key);
            }
            if (n > 0)
                std::fprintf(stderr, "ds4: TP check: the prompt path's copies passed (%d experts' parts, from RAM%s and from "
                                     "the file, on the devices byte for byte)\n", n, cp_dma ? " in place" : "");
        }
        std::fprintf(stderr, "ds4: TP check passed (%zu expert formats and rotations, all the split layers have) "
                             "(DS4_TP_CHECK)\n", seen.size());
        return true;
    }

    // ---- the helper GPU (DS4_HELPER; the state's note by helper_id)
    // a DS4_ setting as MAYA_DS4_* sets it (read as STRATA_DS4_*), else the DS4_* name itself
    static const char* ds4_env(const char* name) {
        const char* v = std::getenv((std::string("STRATA_") + name).c_str());
        return v != nullptr ? v : std::getenv(name);
    }
    static bool helper_owned(const Layer& l, int e) { return !l.helper.empty() && l.helper[(size_t) e] != nullptr; }
    // a layer whose CPU-lane picks the helper may take: a GGUF's trunk layer of one GPU - or, with DS4_TP_GGUF_UNEVEN,
    // of a tensor-parallel group.  A group's helper state (its pool's experts, the table, the recent slots) is member
    // 0's, the Layer the routing is published from and the service thread answers; its whole-expert sums join the
    // lead's CPU part, added once before the MoE all-reduce, and never in any member's vram_tab
    bool helper_layer(const Layer& l) const {
        return !l.mtp && (l.nm == 1 || tp_uneven) && l.lay.fmt == gg::kFmtMXFP4;
    }
    // any of the helper's state on a Layer (a group's members other than 0 must hold none)
    static bool helper_state(const Layer& x) {
        return !x.helper.empty() || x.helper_tab != nullptr || x.hr_n != 0 || x.hr_base != nullptr ||
               !x.hr_exp.empty() || !x.hr_fill.empty() || !x.hr_slot.empty() || !x.hr_stamp.empty() ||
               !x.hr_hist.empty() || !x.hr_hits.empty() || x.hr_mirror != nullptr;
    }
    // DS4_HELPER_FAIL=flags|pool (tests): that allocation fails as a real one would - the load's error and the teardown
    // of what was made before it
    static bool helper_fail(const char* what) {
        const char* v = std::getenv("DS4_HELPER_FAIL");
        return v != nullptr && std::strcmp(v, what) == 0;
    }

    // DS4_HELPER=<visible GPU> with DS4_HELPER_GB=<its pool, GB>: both or neither (no default size: the pool is the
    // run's to name), the GPU taken off the layer devices before any of them is set up - one --gpus names is refused
    bool helper_parse(int ndev, std::vector<int>& ids, std::string& err) {
        const char* hv = ds4_env("DS4_HELPER");
        const char* gv = ds4_env("DS4_HELPER_GB");
        if (hv == nullptr && gv == nullptr) {
            for (const char* k : {"DS4_HELPER_RECENT", "DS4_HELPER_RECENT_NEED", "DS4_HELPER_RECENT_WIN",
                                  "DS4_HELPER_RECENT_FILLS"})
                if (ds4_env(k) != nullptr) {
                    err = std::string(k) + ": the helper's recent slots need DS4_HELPER";
                    return false;
                }
            return true;
        }
        char *he = nullptr, *ge = nullptr;
        const long id = hv != nullptr ? std::strtol(hv, &he, 10) : -1;
        const double gb = gv != nullptr ? std::strtod(gv, &ge) : 0.0;
        if (hv == nullptr || gv == nullptr || he == hv || *he != 0 || ge == gv || *ge != 0 || id < 0 || id >= ndev ||
            !(gb > 0.0 && gb <= 1024.0)) {
            err = "DS4_HELPER=<visible GPU, 0.." + std::to_string(ndev - 1) +
                  "> and DS4_HELPER_GB=<its experts' pool, GB> go together";
            return false;
        }
        if (!pk.gguf) {
            err = "DS4_HELPER: a GGUF pack's experts only";
            return false;
        }
        if (std::find(o.gpus.begin(), o.gpus.end(), (int) id) != o.gpus.end()) {
            err = "DS4_HELPER: CUDA" + std::to_string(id) + " is one of the layer devices (--gpus)";
            return false;
        }
        ids.erase(std::remove(ids.begin(), ids.end(), (int) id), ids.end());
        if (ids.empty()) {
            err = "DS4_HELPER: no layer device left";
            return false;
        }
        const char* wv = ds4_env("DS4_WARM_CAP_GB");
        char* we = nullptr;
        const double wc = wv != nullptr ? std::strtod(wv, &we) : -1.0;
        if (wv == nullptr || we == wv || *we != 0 || !(wc >= 0.0)) {
            err = "DS4_HELPER needs DS4_WARM_CAP_GB=<the load's experts in host RAM, GB>: the host's budget beside its pool";
            return false;
        }
        // DS4_HELPER_RECENT (0 .. 64), _NEED (1 .. 64, at most _WIN), _WIN (1 .. 64), _FILLS (1 .. 16): digits only
        struct Knob {
            const char* name;
            int lo, hi;
            int* to;
        };
        for (const Knob& k : {Knob{"DS4_HELPER_RECENT", 0, 64, &hr_want}, Knob{"DS4_HELPER_RECENT_NEED", 1, 64,
                                                                                 &hr_need},
                              Knob{"DS4_HELPER_RECENT_WIN", 1, 64, &hr_win},
                              Knob{"DS4_HELPER_RECENT_FILLS", 1, 16, &hr_fills}}) {
            const char* v = ds4_env(k.name);
            if (v == nullptr) continue;
            const size_t n = std::strlen(v);
            bool good = n >= 1 && n <= 2;
            int x = 0;
            for (size_t i = 0; good && i < n; ++i) {
                good = v[i] >= '0' && v[i] <= '9';
                x = x * 10 + (v[i] - '0');
            }
            if (!good || x < k.lo || x > k.hi) {
                err = std::string(k.name) + "=" + v + ": a whole number " + std::to_string(k.lo) + " .. " +
                      std::to_string(k.hi);
                return false;
            }
            *k.to = x;
        }
        if (hr_need > hr_win) {
            err = "DS4_HELPER_RECENT_NEED (" + std::to_string(hr_need) + ") over DS4_HELPER_RECENT_WIN (" +
                  std::to_string(hr_win) + ")";
            return false;
        }
        helper_id = (int) id;
        helper_cap = (size_t) (gb * 1e9) & ~(size_t) 255;
        return true;
    }

    // its stream (the expert kernels' scratch for it) and buffers, the pool's size checked and (an integrated GPU's)
    // reserved - first, before the experts' VRAM and the RAM budgets (the read-ahead's, the RAM tier's, the hand-offs')
    bool helper_open(std::string& err) {
        int cur = 0;
        cudaGetDevice(&cur);
        const uint64_t avail0 = ram_avail();
        bool ok = cudaSetDevice(helper_id) == cudaSuccess;
        size_t fr = 0, tot = 0;
        cudaDeviceProp pr{};
        ok = ok && mem_info(&fr, &tot) == cudaSuccess && cudaGetDeviceProperties(&pr, helper_id) == cudaSuccess;
        ok = ok && cudaStreamCreateWithFlags(&helper_st, cudaStreamNonBlocking) == cudaSuccess && gg::prepare(helper_st);
        auto dev = [&](size_t b) -> void* {
            void* p = nullptr;
            if (!ok || cudaMalloc(&p, align256(b)) != cudaSuccess) {
                ok = false;
                return nullptr;
            }
            helper_allocs.push_back(p);
            return p;
        };
        const size_t D = (size_t) g.dim, FF = (size_t) g.ff;
        helper_plan = (unsigned long long*) dev((size_t) kWin * kPicks * 8);
        helper_w = (float*) dev((size_t) kWin * kPicks * 4);
        helper_x = (float*) dev((size_t) kWin * D * 4);
        helper_h = (float*) dev((size_t) kPicks * FF * 4);
        ok = ok && cudaMemset(helper_h, 0, (size_t) kPicks * FF * 4) == cudaSuccess;   // (a skipped pick's row: quantized too)
        const size_t WE = (size_t) kWin * kPicks;
        helper_hw = (float*) dev(WE * FF * 4);
        helper_part = (float*) dev(WE * D * 4);
        helper_grp_ptr = (unsigned long long*) dev(WE * 8);
        helper_grp_start = (int*) dev((WE + 1) * 4);
        helper_grp_ent = (int*) dev(WE * 4);
        helper_n_groups = (int*) dev(4);
        void* m = nullptr;
        if (ok && !helper_fail("flags") &&
            cudaHostAlloc(&m, 4096 + (size_t) kRing * kWin * D * 4, cudaHostAllocMapped | cudaHostAllocPortable) ==
                cudaSuccess) {
            host_allocs.push_back(m);
            std::memset(m, 0, 4096);
            helper_flags = (unsigned*) m;
            helper_res = (float*) ((uint8_t*) m + 4096);
        } else ok = false;
        cudaSetDevice(cur);
        if (!ok) {
            err = "DS4_HELPER: CUDA" + std::to_string(helper_id) + " (" + std::to_string(fr >> 20) +
                  " MiB free): its stream, scratch or flags";
            return false;
        }
        if (helper_cap > fr) {
            err = "DS4_HELPER_GB: " + std::to_string(helper_cap >> 20) + " MiB, CUDA" + std::to_string(helper_id) +
                  " has " + std::to_string(fr >> 20) + " MiB free";
            return false;
        }
        helper_integrated = pr.integrated != 0;
        if (helper_integrated) helper_pending = helper_cap;
        std::fprintf(stderr,
                     "ds4: helper CUDA%d (%s%s): no layers, up to %.1f GB of experts the layer devices' VRAM leaves over "
                     "(DS4_HELPER_GB; %.1f of its %.1f GB free)%s; RAM available %.1f GB\n",
                     helper_id, pr.name, pr.integrated ? ", integrated" : "", helper_cap / 1e9, fr / 1e9, tot / 1e9,
                     pr.integrated ? ", reserved from the host RAM budgets until filled" : "",
                     avail0 == ~uint64_t{0} ? 0.0 : avail0 / 1e9);
        return true;
    }

    // the pool's experts: the most-routed of those the layer devices left without a VRAM slot (the profile's share of
    // their layer, as the read-ahead ranks them) on a trunk layer of one device - or a group's, with DS4_TP_GGUF_UNEVEN
    // (helper_layer) - a GGUF's blob each, until it is full; each layer's table of them on the helper (load_experts_mx
    // copies them in)
    bool helper_select(std::string& err) {
        struct Cand {
            int layer, e;
            double share;
        };
        std::vector<Cand> c;
        for (const Layer& l : L) {
            if (!helper_layer(l)) continue;
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            double sum = 0;
            for (int e = 0; e < l.n_exp; ++e) sum += p[e];
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] < 0) c.push_back({l.il, e, sum > 0 ? p[e] / sum : 0.0});
        }
        std::stable_sort(c.begin(), c.end(), [](const Cand& a, const Cand& b) { return a.share > b.share; });
        // DS4_HELPER_RECENT: hr_want slots of each layer it takes experts of, carved first (the profile's coldest of
        // its pool give way) - all of them inside DS4_HELPER_GB, refused before any upload if they do not fit
        size_t hr_bytes = 0;
        if (hr_want > 0)
            for (const Layer& l : L)
                if (helper_layer(l)) hr_bytes += align256(l.blob) * (size_t) hr_want;
        if (hr_bytes >= helper_cap) {
            err = "DS4_HELPER_RECENT=" + std::to_string(hr_want) + ": its slots (" + std::to_string(hr_bytes >> 20) +
                  " MiB) do not fit DS4_HELPER_GB (" + std::to_string(helper_cap >> 20) + " MiB)";
            return false;
        }
        double took = 0, left = 0;
        std::vector<std::pair<const Cand*, size_t>> at;   // (the expert, its offset in the pool)
        for (const Cand& x : c) {
            const size_t b = align256(L[(size_t) x.layer].blob);
            if (helper_used + b > helper_cap - hr_bytes) {
                left += x.share;
                continue;
            }
            at.push_back({&x, helper_used});
            helper_used += b;
            took += x.share;
        }
        helper_prof = helper_used;   // (the profile's experts' bytes; the pool is these and the recent slots)
        helper_used += hr_bytes;
        int cur = 0;
        cudaGetDevice(&cur);
        bool ok = cudaSetDevice(helper_id) == cudaSuccess;
        if (ok && helper_used > 0) {   // (the pool: what its experts take)
            ok = !helper_fail("pool") && cudaMalloc((void**) &helper_pool, helper_used) == cudaSuccess;
            if (ok) helper_allocs.push_back(helper_pool);
        }
        if (ok && hr_bytes > 0) {   // (the recent slots: after the profile's, each layer's hr_want blobs in a row)
            size_t off = helper_prof;
            for (Layer& l : L) {
                if (!helper_layer(l)) continue;
                if (l.helper.empty()) l.helper.assign((size_t) l.n_exp, nullptr);
                l.hr_n = hr_want;
                l.hr_base = helper_pool + off;
                off += align256(l.blob) * (size_t) hr_want;
                l.hr_exp.assign((size_t) hr_want, -1);
                l.hr_fill.assign((size_t) hr_want, -1);
                l.hr_stamp.assign((size_t) hr_want, 0u);
                l.hr_slot.assign((size_t) l.n_exp, -1);
            }
        }
        for (const auto& a : at) {
            Layer& l = L[(size_t) a.first->layer];
            if (!ok) break;
            if (l.helper.empty()) l.helper.assign((size_t) l.n_exp, nullptr);
            l.helper[(size_t) a.first->e] = helper_pool + a.second;
            ++helper_n;
        }
        for (Layer& l : L) {
            if (!ok || l.helper.empty()) continue;
            std::vector<unsigned long long> t((size_t) l.n_exp, 0ull);
            for (int e = 0; e < l.n_exp; ++e) t[(size_t) e] = (unsigned long long) l.helper[(size_t) e];
            void* p = nullptr;
            ok = cudaMalloc(&p, align256(t.size() * 8)) == cudaSuccess;
            if (!ok) break;
            helper_allocs.push_back(p);
            ok = cudaMemcpy(p, t.data(), t.size() * 8, cudaMemcpyHostToDevice) == cudaSuccess;
            l.helper_tab = (unsigned long long*) p;
            if (ok && l.hr_n > 0) {   // (its pinned mirror: the table the next 'tables' job copies, recent slots too)
                void* m = nullptr;
                ok = cudaHostAlloc(&m, t.size() * 8, cudaHostAllocPortable) == cudaSuccess;
                if (!ok) break;
                host_allocs.push_back(m);
                std::memcpy(m, t.data(), t.size() * 8);
                l.hr_mirror = (unsigned long long*) m;
                hr_host += t.size() * 8;
            }
        }
        cudaSetDevice(cur);
        if (!ok) {
            err = "DS4_HELPER: its " + std::to_string(helper_used >> 20) + " MiB pool or the layers' tables on CUDA" +
                  std::to_string(helper_id);
            return false;
        }
        int tp_layers = 0, tp_experts = 0;
        for (const Layer& l : L) {
            for (int m = 1; m < l.nm; ++m) {   // (a group's members other than 0: none of the helper's state)
                if (helper_state(member(l, m))) {
                    err = "DS4_HELPER: layer " + std::to_string(l.il) + " member " + std::to_string(m) +
                          " holds helper state (only member 0 may)";
                    return false;
                }
            }
            if (l.nm > 1 && !l.helper.empty()) {
                ++tp_layers;
                for (int e = 0; e < l.n_exp; ++e) tp_experts += l.helper[(size_t) e] != nullptr;
            }
        }
        st.helper_held = helper_n;
        if (tp_uneven)
            std::fprintf(stderr,
                         "ds4: helper CUDA%d: %d of its layers tensor-parallel, %d of its experts theirs - each pick's "
                         "whole expert added once, on the group's lead before the all-reduce (DS4_TP_GGUF_UNEVEN)\n",
                         helper_id, tp_layers, tp_experts);
        std::fprintf(stderr,
                     "ds4: helper CUDA%d holds %d experts (%.1f of %.1f GB): %.1f%% of the routing the layer devices' "
                     "VRAM leaves over, by the profile (each layer's share)\n",
                     helper_id, helper_n, helper_prof / 1e9, helper_cap / 1e9,
                     took + left > 0 ? 100.0 * took / (took + left) : 0.0);
        if (hr_bytes > 0) {
            int layers = 0;
            for (const Layer& l : L) layers += l.hr_n > 0;
            std::fprintf(stderr,
                         "ds4: helper CUDA%d recent slots: %d a layer on %d layers (%.2f GB of its pool), each a "
                         "CPU-lane expert the layer used %d times in its last %d ticks, %d new a layer a tick at most "
                         "(DS4_HELPER_RECENT)\n",
                         helper_id, hr_want, layers, hr_bytes / 1e9, hr_need, hr_win, hr_fills);
        }
        return true;
    }

    // (the helper's thread) the recent slots' table updates the last tick made: each changed layer's whole table from
    // its pinned mirror, on the helper's stream - before the next window's takes, which hq queues after this job - then
    // hr_tab_ev, waited for here (bounded: a few KB, the helper's stream idle at a window's end) before this thread
    // enqueues those takes.  A copy not enqueued, or one that did not end cleanly: helper_dead before any of them and
    // before the tick may look (the host already switched its l.helper - the CPU lane computes all the helper's picks
    // from then on, so the host's and the device's tables never disagree on a sum)
    void helper_tables() {
        std::vector<int> ls;
        {
            std::lock_guard<std::mutex> lk(hq_mu);
            ls.swap(hr_tables);
        }
        int cur = 0;
        cudaGetDevice(&cur);
        bool ok = cudaSetDevice(helper_id) == cudaSuccess;
        for (int il : ls) {
            const Layer& l = L[(size_t) il];
            ok = ok && cudaMemcpyAsync(l.helper_tab, l.hr_mirror, (size_t) l.n_exp * 8, cudaMemcpyHostToDevice,
                                       helper_st) == cudaSuccess;
        }
        ok = ok && cudaEventRecord(hr_tab_ev, helper_st) == cudaSuccess;
        if (ok) {
            const double t0 = now_ms();
            cudaError_t q;
            while ((q = cudaEventQuery(hr_tab_ev)) == cudaErrorNotReady && now_ms() - t0 < kHelperWaitMs) cpu_relax();
            ok = q == cudaSuccess;
        }
        if (!ok) {
            (void) cudaGetLastError();
            st.helper_dead = 1;
            if (!helper_dead.exchange(true))
                std::fprintf(stderr, "ds4: helper CUDA%d: a launch failed - the CPU lane takes its picks from now on\n",
                             helper_id);
        }
        hr_tab_rec.store(true, std::memory_order_release);
        cudaSetDevice(cur);
    }
    // (DS4_HELPER_RECENT, once its pool is in) the fills' stream and events on the helper, the pinned stage (the
    // largest blob of a layer with recent slots), the fill thread
    bool hr_open(std::string& err) {
        size_t maxb = 0;
        for (const Layer& l : L)
            if (l.hr_n > 0) maxb = std::max(maxb, l.blob);
        if (maxb == 0) return true;
        int cur = 0;
        cudaGetDevice(&cur);
        void* m = nullptr;
        bool ok = cudaSetDevice(helper_id) == cudaSuccess &&
                  cudaStreamCreateWithFlags(&hr_st, cudaStreamNonBlocking) == cudaSuccess &&
                  cudaEventCreateWithFlags(&hr_fill_ev, cudaEventDisableTiming) == cudaSuccess &&
                  cudaEventCreateWithFlags(&hr_tab_ev, cudaEventDisableTiming) == cudaSuccess &&
                  cudaHostAlloc(&m, maxb, cudaHostAllocPortable) == cudaSuccess;
        cudaSetDevice(cur);
        if (!ok) {
            err = "DS4_HELPER_RECENT: its stream, events or " + std::to_string(maxb >> 20) +
                  " MiB pinned stage on CUDA" + std::to_string(helper_id);
            return false;
        }
        host_allocs.push_back(m);
        hr_stage = (uint8_t*) m;
        hr_host += maxb;
        hr_th = std::thread([this] { hr_loop(); });
        return true;
    }
    // the fill thread: each fill's expert read into the pinned stage (read_mx: its file parts, resident - the CPU lane
    // just used it) and copied into its slot on hr_st; the copy's end waited for by polling hr_fill_ev, bounded
    // (kHelperWaitMs), on quit too - a copy still under way after the bound: hr_busy (no more fills; the stage and the
    // pool kept at the end, as the helper's own memory is when its stream does not finish)
    void hr_loop() {
        for (;;) {
            HrFill f;
            {
                std::unique_lock<std::mutex> lk(hr_mu);
                hr_cv.wait(lk, [&] { return hr_quit || !hr_q.empty(); });
                if (hr_quit) return;   // (fills not started: their slots stay unmapped)
                f = hr_q.front();
                hr_q.pop_front();
            }
            const Layer& l = L[(size_t) f.layer];
            f.ok = false;
            if (!helper_dead.load(std::memory_order_relaxed) && !hr_busy.load() && read_mx(l, f.e, hr_stage)) {
                int cur = 0;
                cudaGetDevice(&cur);
                // (the copy once submitted reads the stage until it ends: its end is waited for by its event - or, if
                //  the event could not be recorded, by the stream itself - bounded; any end but a clean one stops the
                //  fills and keeps the stage and the pool)
                const bool submitted = cudaSetDevice(helper_id) == cudaSuccess &&
                                       cudaMemcpyAsync(l.hr_base + (size_t) f.slot * align256(l.blob), hr_stage, l.blob,
                                                       cudaMemcpyHostToDevice, hr_st) == cudaSuccess;
                const bool recorded = submitted && cudaEventRecord(hr_fill_ev, hr_st) == cudaSuccess;
                if (submitted) {
                    const double t0 = now_ms();
                    cudaError_t q = cudaErrorNotReady;
                    // (not given up on quit: a fill the last tick queued is often still in flight when the engine
                    //  ends, and it ends within the bound - the destructor joins this thread before the pool goes)
                    for (;;) {
                        q = recorded ? cudaEventQuery(hr_fill_ev) : cudaStreamQuery(hr_st);
                        if (q != cudaErrorNotReady || now_ms() - t0 > kHelperWaitMs) break;
                        std::this_thread::sleep_for(std::chrono::microseconds(50));
                    }
                    f.ok = recorded && q == cudaSuccess;
                    if (q != cudaSuccess) {
                        if (q != cudaErrorNotReady) (void) cudaGetLastError();
                        hr_busy.store(true);
                        std::fprintf(stderr, "ds4: helper CUDA%d recent slots: a fill's copy did not end cleanly (%s) "
                                             "- no more fills, its memory kept\n",
                                     helper_id, q == cudaErrorNotReady ? "still under way" : cudaGetErrorString(q));
                    }
                } else
                    (void) cudaGetLastError();   // (nothing submitted: the stage is free again)
                cudaSetDevice(cur);
            }
            std::lock_guard<std::mutex> lk(hr_mu);
            hr_done.push_back(f);
            if (hr_busy.load()) return;
        }
    }
    // (DS4_HELPER_RECENT) its pinned host bytes before the pool is chosen: the stage (the largest blob of a layer that
    // gets recent slots) and each such layer's table mirror
    uint64_t hr_host_estimate() const {
        if (hr_want <= 0 || helper_id < 0) return 0;
        uint64_t maxb = 0, mirrors = 0;
        for (const Layer& l : L)
            if (helper_layer(l)) {
                maxb = std::max<uint64_t>(maxb, l.blob);
                mirrors += (uint64_t) l.n_exp * 8;
            }
        return maxb + mirrors;
    }
    // a slot of l for a new fill: a free one, else the least recently used mapped one no window used since the last
    // tick (-1: none)
    static int hr_pick_slot(const Layer& l, unsigned clock) {
        int best = -1;
        for (int s = 0; s < l.hr_n; ++s) {
            if (l.hr_fill[(size_t) s] >= 0) continue;
            if (l.hr_exp[(size_t) s] < 0) return s;
            if (l.hr_stamp[(size_t) s] >= clock) continue;
            if (best < 0 || l.hr_stamp[(size_t) s] < l.hr_stamp[(size_t) best]) best = s;
        }
        return best;
    }
    static bool hr_filling(const Layer& l, int e) {
        for (int x : l.hr_fill)
            if (x == e) return true;
        return false;
    }
    // (cache_tick, the decode thread, a window of up to kWin answered - the service and helper threads idle, the next
    // window's requests not out) the recent slots' tick: the fills done mapped, the CPU-lane experts the rule picks
    // given slots (their old experts unmapped) and their fills queued, the changed layers' tables handed to the
    // helper's thread.  Every ownership change of an expert - VRAM's (cache_switch, cache_queue, DS4_RECENT's
    // rc_tick), the helper's - happens on this thread, here and in cache_tick around it, so none races another.  A
    // mirror changes only once the last 'tables' job's copies are done (hr_tab_ev): else nothing is mapped or let go
    // this tick - or, the query an error, ever
    void hr_tick(int T) {
        if (hr_want <= 0 || helper_n <= 0 || T > kWin || helper_dead.load(std::memory_order_relaxed)) return;
        ++hr_clock;
        bool free_mirrors = hr_tab_rec.load(std::memory_order_acquire);
        if (free_mirrors) {   // (not yet done: wait a tick; an error - the device, the copy, the event - helper_dead)
            int cur = 0;
            cudaGetDevice(&cur);
            cudaError_t q = cudaSetDevice(helper_id);
            if (q == cudaSuccess) q = cudaEventQuery(hr_tab_ev);
            cudaSetDevice(cur);
            free_mirrors = q == cudaSuccess;
            if (!free_mirrors && q != cudaErrorNotReady) {
                (void) cudaGetLastError();
                st.helper_dead = 1;
                if (!helper_dead.exchange(true))
                    std::fprintf(stderr, "ds4: helper CUDA%d: a launch failed - the CPU lane takes its picks from now "
                                         "on\n",
                                 helper_id);
                return;
            }
        }
        std::vector<HrFill> done;
        {
            std::lock_guard<std::mutex> lk(hr_mu);
            if (free_mirrors) done.swap(hr_done);
            for (Layer& l : L) {   // (the windows' hits of the recent slots: their stamps)
                for (int e : l.hr_hits)
                    if (l.hr_slot[(size_t) e] >= 0) l.hr_stamp[(size_t) l.hr_slot[(size_t) e]] = hr_clock;
                l.hr_hits.clear();
            }
        }
        std::vector<int> changed;
        for (const HrFill& f : done) {
            Layer& l = L[(size_t) f.layer];
            l.hr_fill[(size_t) f.slot] = -1;
            if (!f.ok) {
                ++st.hr_fails;
                continue;
            }
            if (l.slot[(size_t) f.e] >= 0 || helper_owned(l, f.e) || f.e == l.sw_in) {   // (VRAM has it now)
                ++st.hr_abandoned;
                continue;
            }
            uint8_t* at = l.hr_base + (size_t) f.slot * align256(l.blob);
            l.helper[(size_t) f.e] = at;
            l.hr_slot[(size_t) f.e] = f.slot;
            l.hr_exp[(size_t) f.slot] = f.e;
            l.hr_stamp[(size_t) f.slot] = hr_clock;
            l.hr_mirror[(size_t) f.e] = (unsigned long long) at;
            changed.push_back(l.il);
            ++st.hr_maps;
        }
        int queued = 0;
        {
            std::lock_guard<std::mutex> lk(hr_mu);
            queued = (int) hr_q.size();
        }
        std::vector<HrFill> fills;
        for (Layer& l : L) {
            if (l.hr_n <= 0) continue;
            l.hr_hist.push_back(l.cpu_hits);   // (this window's CPU-lane experts: cache_queue takes them after this)
            while ((int) l.hr_hist.size() > hr_win) l.hr_hist.pop_front();
            if (!o.expert_cache || cache_ths.empty()) l.cpu_hits.clear();   // (no cache_queue to take them)
            if (!free_mirrors || hr_busy.load() || queued >= kHrQueued) continue;
            std::vector<int> n((size_t) l.n_exp, 0);
            for (const auto& h : l.hr_hist) {
                std::vector<char> seen((size_t) l.n_exp, 0);   // (a window's tokens: one use of an expert a tick)
                for (int e : h)
                    if (e >= 0 && e < l.n_exp && !seen[(size_t) e]) seen[(size_t) e] = 1, ++n[(size_t) e];
            }
            std::vector<int> want;
            for (int e = 0; e < l.n_exp; ++e)
                if (n[(size_t) e] >= hr_need && l.slot[(size_t) e] < 0 && !helper_owned(l, e) && e != l.sw_in &&
                    !hr_filling(l, e))
                    want.push_back(e);
            std::stable_sort(want.begin(), want.end(), [&](int a, int b) { return n[(size_t) a] > n[(size_t) b]; });
            int made = 0;
            for (int u : want) {
                if (made >= hr_fills || queued >= kHrQueued) break;
                const int s = hr_pick_slot(l, hr_clock);
                if (s < 0) break;
                if (l.hr_exp[(size_t) s] >= 0) {   // (out by its table entry alone: its file parts are where they were)
                    const int v = l.hr_exp[(size_t) s];
                    l.helper[(size_t) v] = nullptr;
                    l.hr_slot[(size_t) v] = -1;
                    l.hr_mirror[(size_t) v] = 0ull;
                    l.hr_exp[(size_t) s] = -1;
                    changed.push_back(l.il);
                    ++st.hr_evicts;
                }
                l.hr_fill[(size_t) s] = u;
                fills.push_back({l.il, s, u, false});
                ++made;
                ++queued;
            }
        }
        if (!fills.empty()) {
            {
                std::lock_guard<std::mutex> lk(hr_mu);
                hr_q.insert(hr_q.end(), fills.begin(), fills.end());
            }
            hr_cv.notify_one();
        }
        if (!changed.empty()) {
            std::sort(changed.begin(), changed.end());
            changed.erase(std::unique(changed.begin(), changed.end()), changed.end());
            hr_tab_rec.store(false, std::memory_order_release);
            {
                std::lock_guard<std::mutex> lk(hq_mu);
                hr_tables.insert(hr_tables.end(), changed.begin(), changed.end());
                hq.push_back({-1, 0u, 0, true});
            }
            hq_cv.notify_one();
        }
    }

    // (the window's plan) its layers' requests to the helper's thread, in seq order
    void helper_window(int T, const WinPlan& wp) {
        if (helper_dead.load(std::memory_order_relaxed)) return;
        {
            std::lock_guard<std::mutex> lk(hq_mu);
            for (int il = 0; il < g.nl; ++il)
                if (L[(size_t) il].helper_tab != nullptr) hq.push_back({il, wp.seq[il], T});
        }
        hq_cv.notify_one();
    }
    void helper_loop() {
        for (;;) {
            HelperJob j;
            {
                std::unique_lock<std::mutex> lk(hq_mu);
                hq_cv.wait(lk, [&] { return hq_quit || !hq.empty(); });
                if (hq.empty()) return;   // (the end: after what was asked)
                j = hq.front();
                hq.pop_front();
            }
            if (helper_dead.load(std::memory_order_relaxed)) continue;
            if (j.tables) helper_tables();
            else helper_enqueue(L[(size_t) j.il], (int) (j.seq % kRing), j.seq, j.T);
        }
    }

    // (the helper's thread, or the check at load: one thread a time) the helper's share of request seq in slot on its
    // stream: it takes the request once the device publishes it, then the expert kernels a token at a time (its plan
    // rows, the CPU lane's weighted sum's form: no shared expert, no other part) into helper_res, then its flag.  The
    // current device is kept; a CUDA error: helper_dead (the service thread's wait ends, the CPU lane computes them)
    // A window of T > 1 (a draft's verify) goes through gg::win_experts instead - its picks grouped by expert, each
    // read once for its tokens, every token's sum the per-token kernels' bit for bit (WinArgs' contract; the load
    // check compares the two) - unless `tokens` (the check's per-token run)
    void helper_enqueue(const Layer& l, int slot, unsigned sq, int T, bool tokens = false) {
        int cur = 0;
        cudaGetDevice(&cur);
        const int e0 = gg::launch_errors();
        bool ok = cudaSetDevice(helper_id) == cudaSuccess;
        if (ok) {
            const size_t D = (size_t) g.dim;
            helper_take(reqs + slot, sq, l.k_exp, g.dim, l.helper_tab, l.n_exp, helper_plan, helper_w, helper_x,
                        helper_flags + slot, helper_flags + 2 * kRing, helper_st);
            if (T > 1 && !tokens) {
                gf::MoeWin mw;
                mw.plan_ptr = helper_plan;
                mw.T = T;
                mw.k = l.k_exp;
                mw.grp_ptr = helper_grp_ptr;
                mw.grp_start = helper_grp_start;
                mw.grp_ent = helper_grp_ent;
                mw.n_groups = helper_n_groups;
                gf::moe_win_group(mw, helper_st);
                x3::WinArgs wa;
                wa.grp_ptr = helper_grp_ptr;
                wa.grp_start = helper_grp_start;
                wa.grp_ent = helper_grp_ent;
                wa.n_groups = helper_n_groups;
                wa.plan_ptr = helper_plan;
                wa.plan_w = helper_w;
                wa.x = helper_x;
                wa.x_stride = D;
                wa.h = helper_hw;
                wa.part = helper_part;
                wa.out = helper_res + (size_t) slot * kWin * D;
                wa.out_stride = D;
                wa.lay = l.lay;
                wa.T = T;
                wa.k = l.k_exp;
                wa.n_embd = g.dim;
                wa.n_ff = g.ff;
                wa.limit = g.lim;   // (no CPU part, no shared expert, no wait: the helper's sums alone)
                ok = gg::win_experts(wa, helper_st);
            }
            for (int t = 0; ok && (T == 1 || tokens) && t < T; ++t) {
                x3::MoeArgs ma;
                ma.plan_ptr = helper_plan + (size_t) t * kPicks;
                ma.plan_w = helper_w + (size_t) t * kPicks;
                ma.lay = l.lay;
                ma.k = l.k_exp;
                ma.n_embd = g.dim;
                ma.n_ff = g.ff;
                ma.limit = g.lim;
                gg::moe_gate_up(ma, helper_x + (size_t) t * D, helper_h, helper_st);
                gg::moe_down(ma, helper_h, nullptr, helper_res + ((size_t) slot * kWin + (size_t) t) * D, helper_st);
            }
            // (its answer's flag only after every launch went in: a failed one leaves the flag down, so the service
            //  thread's wait ends on helper_dead and the CPU lane computes the picks - never a stale sum)
            ok = ok && cudaGetLastError() == cudaSuccess && gg::launch_errors() == e0;
            if (ok) signal_seq(helper_flags + kRing + slot, sq, helper_st);
            ok = ok && cudaGetLastError() == cudaSuccess;
        }
        cudaSetDevice(cur);
        if (ok) return;
        st.helper_dead = 1;
        if (!helper_dead.exchange(true))
            std::fprintf(stderr, "ds4: helper CUDA%d: a launch failed - the CPU lane takes its picks from now on\n",
                         helper_id);
    }

    // (the service thread, after its own part of request seq) the helper's: its flag waited for - it took the request
    // (no picks of its own: the slot is free again), or answered it - no CUDA call; each token's sum then added into the
    // answer.  Failed or late (kHelperWaitMs): its picks on the CPU lane, now and from then on
    void helper_answer(const Layer& l, const Req& r, Resp& rp, unsigned seq, int T,
                       const std::vector<std::pair<int, int>>& hp, std::vector<Ent>& ents) {
        const int slot = (int) (seq % kRing);
        const volatile unsigned* f = helper_flags + (hp.empty() ? 0 : kRing) + slot;
        const double t0 = now_ms();
        bool ok = true;
        for (unsigned n = 0; *f != seq; ++n) {
            if (helper_dead.load(std::memory_order_relaxed) || ((n & 1023) == 0 && now_ms() - t0 > kHelperWaitMs)) {
                ok = false;
                break;
            }
            cpu_relax();
        }
        std::atomic_thread_fence(std::memory_order_acquire);
        st.helper_ms += now_ms() - t0;
        if (!ok && !helper_dead.exchange(true))
            std::fprintf(stderr, "ds4: helper CUDA%d: no answer to request %u in %.0f ms - the CPU lane takes its picks "
                                 "from now on\n", helper_id, seq, now_ms() - t0);
        if (!ok) st.helper_dead = 1;
        if (hp.empty()) return;
        const size_t D = (size_t) g.dim;
        unsigned tmask = 0;
        for (const auto& pk_ : hp) tmask |= 1u << (pk_.second / kPicks);
        if (ok) {
            for (int t = 0; t < T; ++t) {
                if (!((tmask >> t) & 1u)) continue;
                const float* y = helper_res + ((size_t) slot * kWin + (size_t) t) * D;
                float* o = rp.part[t];
                if (rp.cpu[t])
                    for (size_t e = 0; e < D; ++e) o[e] += y[e];
                else
                    for (size_t e = 0; e < D; ++e) o[e] = y[e];
                rp.cpu[t] = 1;
            }
            st.helper_experts += (int64_t) hp.size();
            return;
        }
        // the CPU lane's, as its own picks (hp by expert)
        float wv[kWin * kPicks];
        int tok_of[kWin * kPicks];
        int nslots = 0;
        ents.clear();
        for (size_t a = 0; a < hp.size();) {
            Ent en;
            en.e = hp[a].first;
            en.slot0 = nslots;
            en.n = 0;
            while (a < hp.size() && hp[a].first == en.e && en.n < kc::kExl3CpuMaxN) {
                const int t = hp[a].second / kPicks, i = hp[a].second % kPicks;
                en.tok[en.n++] = t;
                tok_of[nslots] = t;
                wv[nslots] = r.w[t][i];
                ++nslots;
                ++a;
            }
            ents.push_back(en);
        }
        cpu_experts(l, &r.x[0][0], ents, (size_t) kMaxDim);
        for (int t = 0; t < T; ++t) {
            if (!((tmask >> t) & 1u)) continue;
            float* o = rp.part[t];
            if (!rp.cpu[t])
                for (size_t e = 0; e < D; ++e) o[e] = 0.0f;
            for (int sl = 0; sl < nslots; ++sl) {
                if (tok_of[sl] != t) continue;
                const float* y = c_yd.data() + (size_t) sl * D;
                for (size_t e = 0; e < D; ++e) o[e] += wv[sl] * y[e];
            }
            rp.cpu[t] = 1;
        }
        st.helper_fallback += (int64_t) hp.size();
    }

    // DS4_HELPER_CHECK=1 (at load, before decode: nothing waits on the helper yet): for each expert format the pool
    // holds, a made-up request of two tokens through helper_enqueue as decode makes it - its take from the request
    // slot, the layer's table (a pick it does not hold left out), the token rows' plans, the kernels' sum with no shared
    // expert and no CPU part - against the CPU lane's weighted sums of the same picks.  Off by more than kHelperTol of
    // the largest output, or not answered: the helper off (helper_dead) - STAT says so
    static constexpr double kHelperTol = 1e-3;
    void helper_check() {
        std::vector<std::string> seen;
        const int E = g.dim, slot = kRing - 1;
        const unsigned seq = 0x40000000u + (unsigned) slot;   // (not a seq decode reaches before the slot is reset)
        bool all_ok = true;
        for (const Layer& l : L) {
            if (l.helper_tab == nullptr) continue;
            std::string fmt;
            for (int r = 0; r < 3; ++r) fmt += std::string(r ? "/" : "") + gg::type_name(gg::expert_type(l.lay, r));
            if (l.nm > 1) fmt += " (a group's)";   // (DS4_TP_GGUF_UNEVEN: its lead's, checked apart from one GPU's)
            if (std::find(seen.begin(), seen.end(), fmt) != seen.end()) continue;
            seen.push_back(fmt);
            std::vector<int> own, other;   // (experts it holds; one it does not)
            for (int e = 0; e < l.n_exp; ++e) (helper_owned(l, e) ? own : other).push_back(e);
            if (own.empty()) continue;
            // a window of 4 tokens (decode's T = 1 runs H's per-token kernels; a draft's verify window the grouped
            // ones): token 0 one pick of its own (weight 1, position 0); token 1 two of its own (positions 1 and k - 1,
            // 0.6 / 0.4) and one it does not hold between them (its weight must not count); token 2 the experts of
            // tokens 0 and 1 again (0.7, 0.3: groups of two); token 3 one more (0.9). Run grouped, then per token on
            // the next seq of the same slot: the two bit for bit, the grouped sums against the CPU lane's
            const int T = 4, k = l.k_exp;
            auto own_at = [&](size_t i) { return own[std::min(i, own.size() - 1)]; };
            Req& r = reqs[slot];
            std::memset((void*) &r, 0, sizeof r);
            for (int t = 0; t < T; ++t)
                for (int i = 0; i < kPicks; ++i) r.ids[t][i] = -1;
            auto pick = [&](int t, int i, int e, float w) {
                r.ids[t][i] = e;
                r.w[t][i] = w;
            };
            pick(0, 0, own_at(0), 1.0f);
            pick(1, 1, own_at(1), 0.6f);
            pick(1, k - 1, own_at(2), 0.4f);
            if (!other.empty() && k > 3) pick(1, 2, other[0], 0.5f);
            pick(2, std::min(3, k - 1), own_at(0), 0.7f);
            pick(2, 0, own_at(1), 0.3f);
            pick(3, 2 % k, own_at(2), 0.9f);
            for (int t = 0; t < T; ++t) {
                double ss = 0;
                for (int i = 0; i < E; ++i) {
                    r.x[t][i] = std::sin((0.71f + 0.13f * (float) t) * (float) i) + ((i % (97 + t)) == 0 ? 6.0f : 0.0f);
                    ss += (double) r.x[t][i] * r.x[t][i];
                }
                for (int i = 0; i < E; ++i) r.x[t][i] = (float) (r.x[t][i] / std::sqrt(ss / E));
            }
            r.T = T;
            auto send = [&](unsigned sq, bool tokens) {   // (published as the device would: then the take may read it)
                helper_flags[slot] = helper_flags[kRing + slot] = 0u;
                std::atomic_thread_fence(std::memory_order_seq_cst);
                *(volatile unsigned*) &r.seq = sq;
                helper_enqueue(l, slot, sq, T, tokens);
                const double t0 = now_ms();
                while (*(volatile unsigned*) &helper_flags[kRing + slot] != sq && now_ms() - t0 < kHelperWaitMs &&
                       !helper_dead.load())
                    std::this_thread::sleep_for(std::chrono::microseconds(50));
                const bool got = *(volatile unsigned*) &helper_flags[kRing + slot] == sq &&
                                 *(volatile unsigned*) &helper_flags[slot] == sq;
                std::atomic_thread_fence(std::memory_order_acquire);
                return got;
            };
            const float* res = helper_res + (size_t) slot * kWin * (size_t) E;
            bool answered = send(seq, false);
            std::vector<float> grouped;   // (read only once its answer is in: a late kernel may still write the rows)
            if (answered) grouped.assign(res, res + (size_t) T * E);
            int64_t win_same = 0;
            if (answered && (answered = send(seq + kRing, true)))
                for (size_t j = 0; j < (size_t) T * E; ++j) win_same += std::memcmp(&grouped[j], &res[j], 4) == 0;
            const bool win_ok = answered && win_same == (int64_t) T * E;
            // the CPU lane's sums of the same picks it holds, against the grouped ones
            double worst = 0, worst_rel = 0;
            int64_t same = 0, outs = 0;
            bool finite = true;
            for (int t = 0; t < T && answered; ++t) {
                std::vector<float> want((size_t) E, 0.0f);
                for (int i = 0; i < k; ++i) {
                    const int e = r.ids[t][i];
                    if (e < 0 || !helper_owned(l, e)) continue;
                    std::vector<Ent> ents(1);
                    ents[0].e = e;
                    ents[0].n = 1;
                    ents[0].tok[0] = 0;
                    cpu_experts(l, &r.x[t][0], ents, (size_t) kMaxDim);
                    for (int j = 0; j < E; ++j) want[(size_t) j] += r.w[t][i] * c_yd[(size_t) j];
                }
                const float* got = grouped.data() + (size_t) t * E;
                double mx = 0;
                for (int j = 0; j < E; ++j) mx = std::max(mx, (double) std::fabs(want[(size_t) j]));
                for (int j = 0; j < E; ++j) {
                    finite = finite && std::isfinite(got[j]);
                    const double df = std::fabs((double) want[(size_t) j] - (double) got[j]);
                    worst = std::max(worst, df);
                    worst_rel = std::max(worst_rel, mx > 0 ? df / mx : df);
                    same += std::memcmp(&want[(size_t) j], &got[j], 4) == 0;
                    ++outs;
                }
            }
            const bool ok = answered && finite && worst_rel <= kHelperTol && win_ok;
            all_ok = all_ok && ok;
            std::fprintf(stderr, "ds4: helper check: %s (layer %d): CUDA%d vs the CPU lane, %d tokens, 6 picks of its "
                                 "own and %s: %s%lld of %lld outputs bit-identical, max |diff| %.3g (%.3g of the largest)\n",
                         fmt.c_str(), l.il, helper_id, T, !other.empty() && k > 3 ? "one not" : "none other",
                         !answered ? "NO ANSWER - " : !finite ? "NOT FINITE - " : worst_rel > kHelperTol ? "TOO FAR - " : "",
                         (long long) same, (long long) outs, worst, worst_rel);
            std::fprintf(stderr, "ds4: helper check: %s (layer %d): CUDA%d's window of %d grouped against per token: "
                                 "%s%lld of %lld outputs bit-identical\n",
                         fmt.c_str(), l.il, helper_id, T, !answered ? "NO ANSWER - " : win_ok ? "" : "NOT IDENTICAL - ",
                         (long long) win_same, (long long) T * E);
            // the slot as decode expects it, once the stream is done with it (unanswered: told to quit first, waited
            // for kHelperIdleMs; still busy - its take may still read the slot - the slot is left alone)
            if (!answered) *(volatile unsigned*) (helper_flags + 2 * kRing) = 1u;
            if (helper_idle()) {
                std::memset((void*) &r, 0, sizeof r);
                helper_flags[slot] = helper_flags[kRing + slot] = 0u;
            } else {
                all_ok = false;
                std::fprintf(stderr, "ds4: helper check: CUDA%d's stream did not finish - request slot %d left to it\n",
                             helper_id, slot);
            }
            if (!ok || !all_ok) break;
        }
        if (!all_ok) {   // (said whoever turned it off: a launch error in helper_enqueue, or this)
            helper_dead.store(true);
            st.helper_dead = 1;
            std::fprintf(stderr, "ds4: helper check FAILED: the CPU lane takes the helper's picks\n");
        } else
            std::fprintf(stderr, "ds4: helper check passed (%zu expert formats)\n", seen.size());
    }

    // its stream done within kHelperIdleMs (a query at a time: no wait that a stalled device could hold)
    bool helper_idle() {
        std::atomic_thread_fence(std::memory_order_seq_cst);
        int cur = 0;
        cudaGetDevice(&cur);
        cudaSetDevice(helper_id);
        const double t0 = now_ms();
        cudaError_t q;
        while ((q = cudaStreamQuery(helper_st)) == cudaErrorNotReady && now_ms() - t0 < kHelperIdleMs)
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        cudaSetDevice(cur);
        if (q != cudaSuccess && q != cudaErrorNotReady) (void) cudaGetLastError();
        return q == cudaSuccess;
    }

    // (after the service thread) its stream's work done before its memory goes - a take still waiting on a request no
    // device publishes ends on the quit flag; one that still does not finish: the memory kept, the process ends with it
    void helper_close() {
        if (helper_st == nullptr) return;   // (helper_open's own failure: what it made, its flags maybe not)
        if (helper_flags != nullptr) *(volatile unsigned*) (helper_flags + 2 * kRing) = 1u;
        if (!helper_idle()) {
            std::fprintf(stderr, "ds4: helper CUDA%d: its stream did not finish - its memory kept\n", helper_id);
            helper_keep = true;
            return;
        }
        if (helper_keep) return;   // (kept already: a recent slot's fill still copying into it - DS4_HELPER_RECENT)
        for (void* p : helper_allocs) cudaFree(p);
        helper_allocs.clear();
        cudaStreamDestroy(helper_st);
        helper_st = nullptr;
    }

    // the decode path's host side: each published routing in turn - its CPU lane experts (if any) into the answer's
    // part, then the answer's seq.  Spins while requests come (a token's 40 layers), naps after 2 ms without one.
    // DS4_ROUTE_TRACE=FILE: the CPU lane's requests (a window's routing, layer by layer) for offline cache studies -
    // first each trunk layer's experts in VRAM ('P' layer n e..), then a record a request ('R' layer T k, T x k picks,
    // T x k in-VRAM flags), all int32 / uint8, little-endian
    std::FILE* rtrace = nullptr;
    void rtrace_open() {
        const char* f = std::getenv("DS4_ROUTE_TRACE");
        if (f == nullptr || rtrace != nullptr) return;
        rtrace = std::fopen(f, "wb");
        if (rtrace == nullptr) return;
        for (const Layer& l : L) {
            if (l.mtp) continue;
            std::vector<int32_t> v;
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] >= 0) v.push_back(e);
            const int32_t hdr[3] = {'P', l.il, (int32_t) v.size()};
            std::fwrite(hdr, 4, 3, rtrace);
            std::fwrite(v.data(), 4, v.size(), rtrace);
        }
    }
    void serve_lane() {
        unsigned next = 1;
        rtrace_open();
        auto last = std::chrono::steady_clock::now();
        std::vector<Ent> ents, hents;
        std::vector<std::pair<int, int>> hpicks;   // (expert, t * kPicks + i), the helper's
        while (!quit.load(std::memory_order_relaxed)) {
            Req& r = reqs[next % kRing];
            if (*(volatile unsigned*) &r.seq != next) {
                cpu_relax();
                if (std::chrono::steady_clock::now() - last > std::chrono::milliseconds(2))
                    std::this_thread::sleep_for(std::chrono::microseconds(20));
                continue;
            }
            std::atomic_thread_fence(std::memory_order_acquire);
            const int li = layer_of[next % kRing].load(std::memory_order_acquire);
            Resp& rp = resps[next % kRing];
            const int T = std::max(1, std::min(kWin, r.T));
            for (int t = 0; t < T; ++t) rp.cpu[t] = 0;
            if (li >= 0 && li < (int) L.size()) {
                Layer& l = L[(size_t) li];
                uint32_t* pr = prof.data() + (size_t) li * g.n_exp;
                ents.clear();
                // lookahead: the guesses made for this layer (when they are for this request), counted on decode
                const uint8_t* fl = T == 1 && !ahead_for.empty() && ahead_for[(size_t) li] == next
                                        ? ahead_fl.data() + (size_t) li * 1024 : nullptr;
                // the window's CPU-lane picks by expert (up to 8 tokens an entry), their weights by entry row
                float wv[kWin * kPicks];
                int tok_of[kWin * kPicks];
                int nslots = 0;
                std::vector<std::pair<int, int>> picks;   // (expert, t * kPicks + i), CPU-lane only
                // the helper's (DS4_HELPER: a layer with experts in its pool, while it works) - its own lane: not the
                // CPU lane's cache hits, RAM tier, disk skip or stream
                const bool hon = l.helper_tab != nullptr && !helper_dead.load(std::memory_order_relaxed);
                hpicks.clear();
                const bool dsk_rule = disk_skip_w > 0.0f && !l.mtp && li >= disk_skip_from && li < g.nl;
                // (DISK_SKIP_AUTO: skipping now; its counts only then - the routed experts computed either way, of them
                //  on the CPU lane and not in RAM, of them on the CPU lane)
                const bool aon = dsk_rule && disk_skip_auto && sk_auto.on.load(std::memory_order_relaxed);
                const bool dsk = dsk_rule && (!disk_skip_auto || aon);
                const bool rsk = ram_skip_w > 0.0f && !l.mtp && li >= disk_skip_from && li < g.nl;
                int heavy = 0, cold = 0, heavy_cpu = 0;
                for (int t = 0; t < T; ++t) {
                    float wsum = 0.0f;   // (DISK_SKIP_W: the token's route weights)
                    if (dsk || rsk)
                        for (int i = 0; i < l.k_exp; ++i)
                            if (r.ids[t][i] >= 0 && r.ids[t][i] < l.n_exp) wsum += r.w[t][i];
                    for (int i = 0; i < l.k_exp; ++i) {
                        const int e = r.ids[t][i];
                        if (e < 0 || e >= l.n_exp) continue;
                        ++pr[e];
                        l.heat[(size_t) e] += 1.0f;
                        if (fl != nullptr) {
                            ++st.ahead_picks;
                            st.ahead_hit_k += fl[e] & 1;
                            st.ahead_hit += (fl[e] & 6) != 0;
                            st.ahead_hit2 += (fl[e] >> 2) & 1;
                        }
                        const bool light = dsk && r.w[t][i] < disk_skip_w * wsum;
                        if (aon && !light) ++heavy;
                        if (l.slot[(size_t) e] < 0) {
                            if (hon && l.helper[(size_t) e] != nullptr) {
                                hpicks.push_back({e, t * kPicks + i});
                                if (l.hr_n > 0 && l.hr_slot[(size_t) e] >= 0) {   // (a recent slot's: its stamp)
                                    ++st.hr_hits;
                                    std::lock_guard<std::mutex> lk(hr_mu);
                                    l.hr_hits.push_back(e);
                                }
                                continue;
                            }
                            l.cpu_hits.push_back(e);
                            if ((light && !in_ram(l, e)) || (rsk && r.w[t][i] < ram_skip_w * wsum)) {
                                ++st.skipped;
                                continue;
                            }
                            if (aon && !light) {   // (cold: not in RAM now, or not when the lookahead asked for it)
                                ++heavy_cpu;
                                cold += in_ram(l, e) && !(fl != nullptr && (fl[e] & 16)) ? 0 : 1;
                            }
                            if (!l.ram.empty() && l.ram[(size_t) e] >= 0) ++st.ram_experts;
                            else if (fl != nullptr) {
                                ++st.ahead_cold;
                                st.ahead_cold_hit += (fl[e] >> 3) & 1;
                            }
                            picks.push_back({e, t * kPicks + i});
                        } else if (l.rc_n > 0 && l.slot[(size_t) e] >= l.rc_base && l.slot[(size_t) e] < l.rc_base + l.rc_n)
                            l.rc_stamp[(size_t) (l.slot[(size_t) e] - l.rc_base)] = rc_clock.load(std::memory_order_relaxed);
                    }
                }
                if (rtrace != nullptr) {
                    const int32_t hdr[4] = {'R', li, T, l.k_exp};
                    std::fwrite(hdr, 4, 4, rtrace);
                    std::vector<int32_t> ids;
                    std::vector<uint8_t> in;
                    for (int t = 0; t < T; ++t)
                        for (int i = 0; i < l.k_exp; ++i) {
                            const int e = r.ids[t][i];
                            ids.push_back(e);
                            in.push_back(e >= 0 && e < l.n_exp && l.slot[(size_t) e] >= 0 ? 1 : 0);
                        }
                    std::fwrite(ids.data(), 4, ids.size(), rtrace);
                    std::fwrite(in.data(), 1, in.size(), rtrace);
                }
                if (aon) skip_auto_tick(li, T, heavy, cold, heavy_cpu);
                if (disk_skip_auto && dsk_rule && !picks.empty()) {   // (the experts this answer leaves in RAM)
                    std::lock_guard<std::mutex> lk(sk_auto.mu);
                    for (const auto& pk_ : picks) {
                        if (sk_auto.recent.size() < kRecent) sk_auto.recent.push_back({li, pk_.first});
                        else sk_auto.recent[sk_auto.recent_pos] = {li, pk_.first};
                        sk_auto.recent_pos = (sk_auto.recent_pos + 1) % kRecent;
                    }
                }
                if (fl != nullptr) {   // the guesses by rank: how many were picked
                    const uint8_t* rk = ahead_rank.data() + (size_t) li * 1024;
                    for (int e = 0; e < l.n_exp && e < 1024; ++e) {
                        if (rk[e] == 0 || rk[e] > 16) continue;
                        bool hit = false;
                        for (int i = 0; i < l.k_exp; ++i) hit = hit || r.ids[0][i] == e;
                        ++st.ahead_rank_n[rk[e] - 1];
                        st.ahead_rank_hit[rk[e] - 1] += hit;
                    }
                }
                if (ahead_mode > 0 && !ahead_for.empty()) ahead_ask(li, r, next, T);
                // the PCIe lane (a decoded token on a layer that streams): the picks it takes leave the CPU lane's, their
                // copies start now (lane_take)
                const int lc = T == 1 ? lane_class(li) : (ln_win && T <= kWin) ? lane_win_class(li) : -1;
                LaneTake lt;
                if (lc >= 0) {
                    if (T == 1) lane_take(l, ln_cls[(size_t) lc], picks, lt, next, r.ids);
                    else lane_take_win(l, ln_cls[(size_t) lc], picks, lt, next, r.ids, T);
                }
                std::sort(picks.begin(), picks.end());
                for (size_t a = 0; a < picks.size();) {
                    Ent en;
                    en.e = picks[a].first;
                    en.slot0 = nslots;
                    en.n = 0;
                    while (a < picks.size() && picks[a].first == en.e && en.n < kc::kExl3CpuMaxN) {
                        const int t = picks[a].second / kPicks, i = picks[a].second % kPicks;
                        en.tok[en.n++] = t;
                        tok_of[nslots] = t;
                        wv[nslots] = r.w[t][i];
                        ++nslots;
                        ++a;
                    }
                    ents.push_back(en);
                }
                // lookahead: the entries asked for early (or in the RAM tier) computed first, so the ones asked for
                // only now get the others' time to come in from the SSD (their slots, so the sums, stay the same)
                int ord[kWin * kPicks];
                const int* po = nullptr;
                if (ahead_order && !ahead_for.empty() && ahead_for[(size_t) li] == next && ents.size() > 1 &&
                    ents.size() <= (size_t) (kWin * kPicks)) {
                    const uint8_t* fa = ahead_fl.data() + (size_t) li * 1024;
                    int n = 0;
                    for (int pass = 0; pass < 2; ++pass)
                        for (size_t q = 0; q < ents.size(); ++q) {
                            const int e = ents[q].e;
                            const bool early = !file_read(l, e) || (fa[e] & 8) != 0;
                            if (early == (pass == 0)) ord[n++] = (int) q;
                        }
                    po = ord;
                }
                if (!ents.empty()) {
                    const double tc = now_ms();
                    cpu_experts(l, &r.x[0][0], ents, (size_t) kMaxDim, po);
                    lt.c_ms = now_ms() - tc;
                    lt.n_cpu = (int) ents.size();
                    const int D = g.dim;
                    for (int t = 0; t < T; ++t) {
                        bool any = false;
                        for (int sl = 0; sl < nslots; ++sl) any = any || tok_of[sl] == t;
                        if (!any) continue;
                        float* o = rp.part[t];
                        for (int e = 0; e < D; ++e) o[e] = 0.0f;
                        for (int sl = 0; sl < nslots; ++sl) {
                            if (tok_of[sl] != t) continue;
                            const float* y = c_yd.data() + (size_t) sl * D;
                            for (int e = 0; e < D; ++e) o[e] += wv[sl] * y[e];
                        }
                        rp.cpu[t] = 1;
                    }
                    st.cpu_ms += now_ms() - tc;
                    st.cpu_experts += nslots;
                    if (l.mtp) st.draft_cpu += nslots;
                }
                if (lc >= 0) lane_answer(ln_cls[(size_t) lc], lt);
                if (hon) {
                    std::sort(hpicks.begin(), hpicks.end());
                    helper_answer(l, r, rp, next, T, hpicks, hents);
                }
            }
            std::atomic_thread_fence(std::memory_order_release);
            *(volatile unsigned*) &rp.seq = next;
            *(volatile unsigned*) lane_done = next;
            ++next;
            last = std::chrono::steady_clock::now();
        }
    }

    // ---- the decode path's PCIe lane (ds4_pcie.hpp).  A decoded token's routed experts that VRAM does not hold were all
    // the CPU lane's; as GLM's maya does, some of them now go to the GPU instead: read into pinned memory (ln_host - from
    // the page cache, the disk or the RAM tier) by the reading threads, pulled over the link into a staging slot of
    // their layer's GPU by the GPU itself (pcie::stream_fetch, enqueued with the layer: the host only reads and writes
    // flags - a thread that enqueues layers can be blocked in the driver until the device moves on, so any GPU call from
    // the host while the device waits on it could hang both) and computed there by the device's own expert kernels -
    // their gate / up before the wait for the CPU lane's answer - while the CPU lane computes the rest; which ones by this
    // PC's measured costs (lane_setup, lane_take; decode times both lanes again - lane_note), so that both lanes finish
    // together.  A decoded token
    // (moe_token_path) on a GGUF's experts (MXFP4 or a low-bit type) of a layer on one GPU (not a tensor-parallel
    // group); each GPU streams its own layers' experts over its own link.  The device's sums take a streamed expert as
    // a VRAM one (the same kernels, the same order); the CPU lane's and the device's sums of one expert agree to their
    // order (both lanes round a low-bit expert's activations alike, ggml's Q8_K, unless DS4_IQ_Q8K=0 - DS4_LANE_CHECK).
    // DS4_STREAM=0 (or the settings' MAYA_DS4_STREAM=0): off (the CPU lane alone, as before; 2: the slots kept but
    // nothing streams - tests, the same experts'
    // placement as a streaming start); DS4_STREAM_THREADS=<n>: the reading threads (2);
    // DS4_STREAM_FORCE=<digits>: of n picks of a request the stream lane takes digit n (the first ones; tests - the
    // timing then plans nothing); DS4_STREAM_DIRECT=0/1: (an integrated GPU) its kernels read the pinned staging in place
    // instead of a copy in its memory (default: whichever measured faster); DS4_LANE_CAL=<file>|none: the times kept
    // across starts (<pack>/lane-times.txt); DS4_LANE_CHECK=1: each format's expert through both lanes at load.
    struct LaneDev {
        bool on = false;          // some of its layers stream: their decode requests take the stream wait
        bool direct = false;      // (an integrated GPU) the kernels read the pinned staging where it lies, no copy
        uint8_t* vram = nullptr;  // `slots` staging slots of `stride` bytes (a request's streamed pick i in slot i)
        size_t stride = 0;
        int slots = 0;
        int blocks = 1;           // the fetch kernel's grid (a block a multiprocessor)
        cudaStream_t cs = nullptr;   // (the calibration's pulls)
        unsigned long long* plan2 = nullptr;   // device [kPicks]: the streamed picks' plan (the second gate / up)
        unsigned *dflag = nullptr, *cflag = nullptr;   // device: the fetch kernel's flags (decode's, the calibration's)
        uint8_t* host_dev = nullptr;           // ln_host as this device addresses it, its slots hstride apart
        size_t hstride = 0;
        bool integrated = false, mode_set = false;
        uint8_t* slot_ptr(int i) const {
            return direct ? host_dev + (size_t) i * hstride : vram + (size_t) i * stride;
        }
    };
    // decode's own timing of a lane (lane_note): since the last look, its experts, ms and calls on requests whose
    // experts (that lane's) were all in RAM; windows looked at, a change's direction and the window before it, changes
    struct LaneRetime {
        int64_t n = 0, calls = 0;
        double ms = 0, prev = 0;
        int win = 0, dir = 0, changes = 0;
    };
    // decode's check that streaming pays on this PC (lane_ab): the requests the split streams some of take turns -
    // the split, or the CPU lane alone - and the lanes' time of each (from the split to the last lane's end) is
    // summed; per kind of request (0: every pick in RAM, 1: some from the disk), windows of 32 of each.  The costs
    // above are each lane's alone; here both lanes run at once and share the memory, the disk and the cores (a PC
    // whose CPU lane is bound by its memory gains nothing: a streamed expert crosses the memory three times)
    struct LaneAB {
        double ms[2] = {0, 0};
        int n[2] = {0, 0};
        int flip = 0, wins = 0, good = 0, bad = 0;
        int verdict = 0;           // 1: streaming measured faster, -1: not (this kind streams nothing), 0: measuring
    };
    struct LaneCls {               // a format class (its experts' types and blob size) on one GPU
        std::string fmt;           // "IQ2_XXS/IQ2_XXS/IQ3_XXS 10633216 B"
        int dev = 0, il = -1;      // its device; the layer of it with the most CPU-lane experts (the calibration's)
        bool stream = false;       // its split streams for some request
        bool win = false;          // the unforced split's original verify-window eligibility
        pcie::Costs cost, start;   // the split's costs (decode may time them again); the start-up timing
        std::string key;           // its line in the times file
        LaneRetime rc, rs;         // decode's own timing of its CPU lane, of its stream lane (lane_note)
        LaneAB ab[2];              // decode's check that streaming pays, per kind of request (lane_ab)
        int64_t n_req = 0, n_stream = 0;   // its decode requests with CPU-lane picks, the experts it streamed
    };
    std::vector<LaneDev> ln_dev;
    std::vector<LaneCls> ln_cls;
    std::vector<int> ln_layer;               // layer -> its LaneCls (-1: the CPU lane alone)
    std::vector<int> ln_win_layer;           // verify windows keep the original, unforced class eligibility
    uint8_t* ln_host = nullptr;              // pinned, mapped: pcie::kSlots slots of ln_stride (where the reads land)
    size_t ln_stride = 0;
    pcie::Pull* ln_pull = nullptr;           // host-mapped [kRing]: a decode request's pull (by its seq)
    pcie::Pull* ln_cal_pull = nullptr;       // host-mapped: the calibration's
    unsigned ln_cal_seq = 0;
    std::unique_ptr<Pool> ln_pool;           // the reading threads (a streamed expert a job)
    int ln_readers = 0;
    std::string ln_file;                     // the times file ("": none)
    std::string ln_force;                    // DS4_STREAM_FORCE
    bool ln_zc_all = false;                  // DS4_STREAM_ZC_ALL requested
    bool ln_zc_all_live = false;             // the baseline lane exists and a real pinned copy makes ZC-all usable
    bool ln_zc_nowait = false;               // DS4_STREAM_ZC_NOWAIT: a fully covered layer has no CPU response to wait for
    std::atomic<bool> zc_nowait_seen{false}; // log the first actual no-wait layer, not only the setting
    // a request's reads (one batch at a time: the service thread's, or the calibration's)
    struct LaneJob {
        int di = 0, n = 0;
        const Layer* l = nullptr;
        pcie::Pull* pull = nullptr;
        unsigned seq = 0;
        int slot[pcie::kSlots] = {}, e[pcie::kSlots] = {};
        std::atomic<int> left{0};
        std::atomic<unsigned> bad{0};
        double t0 = 0, t_done = 0;   // its reads' start; the device's pull of the last one seen (0: not seen)
        double t_dev = 0;            // (in place) the device's own time for the pull, ms (0: not seen)
        LaneCls* cls = nullptr;      // (decode's: its class, its experts all in RAM - lane_note times the stream lane)
        bool warm = false;
        int ab = -1;                 // (decode's check, lane_ab: the request's kind; its start, its CPU lane's end)
        double t_start = 0, t_cpu = 0;
    } ln_job;
    std::atomic<bool> ln_no_done{false};   // a pull's end not seen in time once: not waited for again
    std::function<void(int)> ln_fn;
    // a request's split, serve_lane's (lane_take -> lane_answer)
    struct LaneTake {
        unsigned mask = 0;          // the token's picks i streamed
        int n_s = 0, n_cpu = 0;     // streamed experts; the CPU lane's entries
        bool warm = true;           // every pick of both lanes in RAM (decode's timing counts only those)
        double c_ms = 0;            // the CPU lane's call
        int ab = -1;                // decode's check (lane_ab): the request's kind, and whether it took the split
        bool ab_split = false;
        double t0 = 0;              // the split's time
    };

    // DS4_STREAM, or the settings' MAYA_DS4_STREAM (STRATA_DS4_STREAM): 0 off, 2 the slots kept and nothing streamed
    static const char* lane_env() {
        const char* v = std::getenv("DS4_STREAM");
        return v != nullptr ? v : std::getenv("STRATA_DS4_STREAM");
    }
    static bool lane_env_off() {
        const char* v = lane_env();
        return v != nullptr && std::atoi(v) == 0;
    }
    int lane_class(int li) const { return li >= 0 && li < (int) ln_layer.size() ? ln_layer[(size_t) li] : -1; }
    int lane_win_class(int li) const {
        return li >= 0 && li < (int) ln_win_layer.size() ? ln_win_layer[(size_t) li] : -1;
    }
    // a layer the PCIe lane can serve: a trunk layer of one GPU, a GGUF's experts, whose decode picks fit the slots
    static bool lane_layer_ok(const Layer& l) {
        return !l.mtp && l.nm == 1 && l.lay.fmt == gg::kFmtMXFP4 && l.k_exp > 0 && l.k_exp <= kPicks && l.blob > 0;
    }
    std::string lane_fmt(const Layer& l) const {
        return std::string(gg::type_name(gg::expert_type(l.lay, 0))) + "/" + gg::type_name(gg::expert_type(l.lay, 1)) +
               "/" + gg::type_name(gg::expert_type(l.lay, 2)) + " " + std::to_string(l.blob) + " B";
    }
    std::string lane_dev_key(int di) const {
        char bus[32] = "?";
        if (cudaDeviceGetPCIBusId(bus, (int) sizeof bus, devs[(size_t) di].id) != cudaSuccess) cudaGetLastError();
        cudaDeviceProp prop{};
        if (cudaGetDeviceProperties(&prop, devs[(size_t) di].id) != cudaSuccess) {
            cudaGetLastError();
            prop.name[0] = 0;
        }
        return std::string(STRATA_VERSION) + " " + __DATE__ + " " + __TIME__ + " | " + o.pack + " | " + bus + " " +
               prop.name;
    }
    void lane_put(const std::string& key, const std::string& vals) {
        if (!ln_file.empty())
            pcie::cal_put(ln_file, key, vals,
                          [](const std::string& a, const std::string& b) { return os::replace_file(a, b); });
    }

    // the staging slots on each GPU whose layers may stream, before place_experts - its VRAM experts take what they
    // leave: a request's picks, k_exp slots of the largest blob (~64 MB for Maya's quant, ~113 MB for MXFP4: ~0.3% of a
    // 32 GB card's experts).  Not where every expert of its layers fits in VRAM (no CPU lane), nor where the times file
    // says this GPU's split never streams (its start costs no VRAM then).
    bool lane_alloc(std::string& err) {
        if (!pk.gguf || lane_env_off() || !moe_token_path || sync_decode) return true;
        ln_file = lane_file();
        if (const char* v = std::getenv("DS4_STREAM_FORCE")) ln_force = v;
        ln_zc_all = std::getenv("DS4_STREAM_ZC_ALL") != nullptr && std::atoi(std::getenv("DS4_STREAM_ZC_ALL")) != 0;
        ln_zc_nowait = std::getenv("DS4_STREAM_ZC_NOWAIT") != nullptr && std::atoi(std::getenv("DS4_STREAM_ZC_NOWAIT")) != 0;
        ln_dev.assign(devs.size(), LaneDev{});
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            LaneDev& D = ln_dev[di];
            size_t stride = 0;
            double exp_b = 0;
            for (const Layer& l : L)
                if (lane_layer_ok(l) && l.dev == (int) di) {
                    stride = std::max(stride, align256(l.blob));
                    D.slots = ln_win ? pcie::kSlots : std::max(D.slots, l.k_exp);   // (a window streams more)
                    exp_b += (double) l.blob * l.n_exp;
                }
            if (stride == 0) continue;
            CK(cudaSetDevice(d.id));
            size_t fr = 0, tot = 0;
            CK(mem_info(&fr, &tot));
            const double room = std::max(0.0, (double) fr - (double) ((size_t) o.reserve_mib << 20)) * o.vram_experts;
            if (exp_b <= room) continue;   // (every expert of its layers fits)
            if (ln_force.empty() &&
                pcie::baseline_lane_off(ln_force, pcie::cal_get(ln_file, lane_dev_key((int) di) + " | lane"))) continue;
            void* v = nullptr;
            if (cudaMalloc(&v, (size_t) D.slots * stride) != cudaSuccess) {   // (none: this GPU's CPU lane alone)
                cudaGetLastError();
                continue;
            }
            d.allocs.push_back(v);
            D.vram = (uint8_t*) v;
            D.stride = stride;
            ln_stride = std::max(ln_stride, stride);
            CK(cudaStreamCreateWithFlags(&D.cs, cudaStreamNonBlocking));
            if (!dalloc(d, D.plan2, kPicks, err) || !dalloc(d, D.dflag, pcie::kPullFlags, err) ||
                !dalloc(d, D.cflag, pcie::kPullFlags, err))
                return false;
            int integ = 0, sms = 0;
            if (cudaDeviceGetAttribute(&integ, cudaDevAttrIntegrated, d.id) != cudaSuccess) cudaGetLastError();
            if (cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, d.id) != cudaSuccess) cudaGetLastError();
            D.integrated = integ != 0;
            D.blocks = std::max(1, std::min(128, sms));
        }
        return true;
    }
    void lane_free(int di) {   // (a GPU whose split never streams: its slots back)
        LaneDev& D = ln_dev[(size_t) di];
        Dev& d = devs[(size_t) di];
        if (D.vram == nullptr) return;
        cudaSetDevice(d.id);
        auto it = std::find(d.allocs.begin(), d.allocs.end(), (void*) D.vram);
        if (it != d.allocs.end()) d.allocs.erase(it);
        cudaFree(D.vram);
        D.vram = nullptr;
    }

    // a streamed expert's read (ln_pool's job j of ln_job): its file region (or its RAM-tier copy) read into its pinned
    // slot a matrix at a time, each matrix's ready flag set as it lands - the device pulls the gate while the up and
    // the down are read (bad: a read failed - the device leaves the pick out; every flag is set either way).  No GPU call
    void lane_copy(int j) {
        LaneJob& J = ln_job;
        const Layer& l = *J.l;
        const int i = J.slot[j], e = J.e[j];
        uint8_t* stg = ln_host + (size_t) i * ln_stride;
        const bool zc = zc_ok(l, e);   // (in place: the device pulls it from where it lies, nothing to read)
        const bool held = zc || (!l.ram.empty() && l.ram[(size_t) e] >= 0);
        bool ok = !held || zc || read_mx(l, e, stg);
        for (int r = 0; r < 3; ++r) {
            if (ok && !held)
                ok = pk.read_at(l.mx_file[r], l.mx_off[r] + (uint64_t) e * l.mx_stride[r], mx_part_bytes(l, r),
                                stg + l.lay.trellis[r]);
            if (!ok && *(volatile unsigned*) &J.pull->bad[i] == 0u) {
                J.bad.fetch_or(1u << i);
                *(volatile unsigned*) &J.pull->bad[i] = 1u;
            }
            std::atomic_thread_fence(std::memory_order_release);
            *(volatile unsigned*) &J.pull->ready[i][r] = J.seq;
        }
        if (J.left.fetch_sub(1, std::memory_order_acq_rel) != 1 || ln_no_done.load()) return;
        // the last read: until the device has pulled them all (the stream lane's end, decode's timing of it) - it does
        // soon (its fetch kernel waits for nothing else); not seen within 200 ms: never waited for again
        const double t = now_ms();
        for (int it = 0; *(volatile unsigned*) &J.pull->done != J.seq; ++it) {
            if (now_ms() - t > 200.0) {
                ln_no_done.store(true);
                std::fprintf(stderr, "ds4: PCIe lane: the device's pull of streamed experts not seen by the host - "
                                     "decode times the CPU lane alone\n");
                return;
            }
            if (it < 64)
                cpu_relax();
            else
                std::this_thread::yield();
        }
        J.t_done = now_ms();
        const volatile pcie::Pull* vp = J.pull;
        const unsigned long long tb = vp->t_beg, te = vp->t_end;
        J.t_dev = te > tb ? (double) (te - tb) / 1e6 : 0.0;
    }
    pcie::Mats lane_mats(const Layer& l) const {   // the layer's matrices in its blob
        pcie::Mats m;
        for (int r = 0; r < 3; ++r) {
            m.off[r] = l.lay.trellis[r];
            m.bytes[r] = mx_part_bytes(l, r);
        }
        return m;
    }
    // n experts of layer l read into the pinned slots slot[q] <- expert ex[q] for pull P (seq); lane_wait: until the
    // reads are done (one batch at a time), the picks that failed (their bits)
    void lane_go(const Layer& l, int di, int n, const int* slot, const int* ex, pcie::Pull* P, unsigned seq,
                 LaneCls* cls = nullptr, bool warm = false) {
        LaneJob& J = ln_job;
        J.l = &l;
        J.cls = cls;
        J.warm = warm;
        J.di = di;
        J.n = n;
        J.pull = P;
        J.seq = seq;
        for (int q = 0; q < n; ++q) J.slot[q] = slot[q], J.e[q] = ex[q];
        J.bad.store(0);
        J.left.store(n);
        J.t0 = now_ms();
        J.t_done = 0;
        J.t_dev = 0;
        if (n > 0) ln_pool->start(n, ln_fn);
    }
    unsigned lane_wait() {
        if (ln_job.n > 0) ln_pool->wait();
        ln_job.n = 0;
        return ln_job.bad.load();
    }
    // a pull's picks: src[i] for slot i (0: none), the read flags clear, then its seq (after a release fence); mat[i]:
    // an expert pulled in place (se[i], slot i's expert of layer l) - its matrices where they lie, else 0
    void lane_publish(pcie::Pull* P, unsigned seq, const LaneDev& D, unsigned mask, const Layer* l = nullptr,
                      const int* se = nullptr, const signed char* went = nullptr,
                      const unsigned long long* dst = nullptr) {
        for (int i = 0; i < pcie::kSlots; ++i) {
            const bool on = ((mask >> i) & 1u) != 0u;
            const bool zc = on && l != nullptr && se != nullptr && zc_ok(*l, se[i]);
            P->src[i] = on ? (unsigned long long) (D.host_dev + (size_t) i * D.hstride) : 0ull;
            for (int r = 0; r < 3; ++r) P->mat[i][r] = zc ? (unsigned long long) zc_mat(*l, se[i], r) : 0ull;
            P->dst[i] = on && dst != nullptr ? dst[i] : 0ull;
            P->bad[i] = 0u;
        }
        for (int e = 0; e < pcie::kPullEnt; ++e) P->ent[e] = went != nullptr ? went[e] : (signed char) -1;
        std::atomic_thread_fence(std::memory_order_release);
        *(volatile unsigned*) &P->seq = seq;
    }

    // expert e of layer l in RAM now (the RAM tier, or its pages in the page cache: two sampled pages, of its gate and
    // of its down - an expert's pages come and go together).  (Windows: the engine's working set - a page on the standby
    // list counts as not in RAM, though a read takes it about as fast: the split then plans a disk read for it, and
    // decode's timing leaves its request out.  Taking every page as in RAM there had decode time the SSD as the CPU
    // lane: a Strix Halo's MXFP4 expert 5.9 ms against 0.14)
    bool lane_warm(const Layer& l, int e) const {
        if (!l.ram.empty() && l.ram[(size_t) e] >= 0) return true;
        return os::resident_sampled(mx_mat(l, e, 0), mx_part_bytes(l, 0), 1) &&
               os::resident_sampled(mx_mat(l, e, 2), mx_part_bytes(l, 2), 1);
    }
    // (serve_lane) of a decode request's CPU-lane picks (expert, pick i), the ones the stream lane takes (pcie::split
    // on this class's costs, at most the device's slots): out of `picks`, the request's pull published (always - the
    // device's fetch kernel waits for it; none streamed: no src), their reads started.  The batch before is done by now
    // (the device pulled it before it routed this request): waited for, its failures said
    void lane_take(Layer& l, LaneCls& C, std::vector<std::pair<int, int>>& picks, LaneTake& lt, unsigned seq,
                   const int (*ids)[kPicks]) {
        pcie::Pull* P = ln_pull + seq % kRing;
        if (ln_job.n > 0) {
            const int jn = ln_job.n;
            if (lane_wait() != 0) {
                static std::atomic<bool> said{false};
                if (!said.exchange(true))
                    std::fprintf(stderr, "ds4: PCIe lane: reading a streamed expert failed - that token went without it\n");
            } else if (ln_job.cls != nullptr && ln_job.t_done > ln_job.t0) {
                // (in place: the device's own time - the host's includes the device's queue before the pull)
                if (ln_job.warm)
                    lane_note(*ln_job.cls, true, jn, ln_zc && ln_job.t_dev > 0 ? ln_job.t_dev : ln_job.t_done - ln_job.t0);
                if (ln_job.ab >= 0 && ln_job.t_cpu > 0)
                    lane_ab(*ln_job.cls, ln_job.ab, true, std::max(ln_job.t_cpu, ln_job.t_done) - ln_job.t_start);
            }
            ln_job.ab = -1;
        }
        lt.t0 = now_ms();
        const LaneDev& D = ln_dev[(size_t) C.dev];
        const int n = std::min((int) picks.size(), kPicks);
        unsigned cold = 0, m = 0;
        if (n > 0) {
            ++C.n_req;
            for (int j = 0; j < n; ++j)
                if (!lane_warm(l, picks[(size_t) j].first)) cold |= 1u << j;
            lt.warm = cold == 0;
            if (!ln_force.empty()) {   // (tests: digit n of the first ones)
                const int s = n < (int) ln_force.size() ? std::max(0, std::min(n, ln_force[(size_t) n] - '0')) : 0;
                m = (1u << std::min(s, D.slots)) - 1u;
            } else {
                bool full_zc = ln_zc_all_live;
                if (full_zc)
                    for (int j = 0; j < n; ++j) full_zc = full_zc && zc_ok(l, picks[(size_t) j].first);
                if (full_zc && !tok_ab_off) {
                    // Full coverage replaces only the streaming arm. The whole-step check's CPU arm and fallback stay intact.
                    m = (1u << n) - 1u;
                } else {
                    m = pcie::split(C.cost, n, cold, D.slots);
                    LaneAB& A = C.ab[cold != 0 ? 1 : 0];
                    if (m != 0 && (A.verdict < 0 || tok_ab_off))   // (tok_ab_off: the whole-step check's turn, or its verdict)
                        m = 0;
                    else if (m != 0 && A.verdict == 0 && !ln_no_done.load()) {   // (the check: turn by turn)
                        lt.ab = cold != 0 ? 1 : 0;
                        lt.ab_split = (A.flip ^= 1) != 0;
                        if (!lt.ab_split) m = 0;
                    }
                }
            }
        }
        int slot[kPicks], ex[kPicks], se[kPicks], ns = 0;
        unsigned long long dst[pcie::kSlots] = {};
        if (m != 0) {
            std::vector<std::pair<int, int>> keep;
            for (int j = 0; j < (int) picks.size(); ++j) {
                if (j < n && ((m >> j) & 1u)) {
                    const int i = picks[(size_t) j].second % kPicks;
                    slot[ns] = i;
                    se[i] = ex[ns++] = picks[(size_t) j].first;
                    lt.mask |= 1u << i;
                    dst[i] = land_dst(l, se[i], i, seq, ids, 1);
                } else
                    keep.push_back(picks[(size_t) j]);
            }
            picks.swap(keep);
        }
        lane_publish(P, seq, D, lt.mask, &l, se, nullptr, dst);
        lt.n_s = ns;
        C.n_stream += ns;
        st.stream_experts += ns;
        if (ns > 0) {
            lane_go(l, C.dev, ns, slot, ex, P, seq, ln_force.empty() ? &C : nullptr, (cold & m) == 0u);
            ln_job.ab = lt.ab_split ? lt.ab : -1;
            ln_job.t_start = lt.t0;
            ln_job.t_cpu = 0;
        }
    }
    // (DS4_LAND, on by default where a layer has recent slots) a streamed expert's landing: the least recently used of
    // its layer's recent slots that this request does not route to (its expert's table entry still points there until
    // the window ends) and no fill or other landing holds - the device pulls the expert there instead of a staging slot,
    // and the tick after the window maps it: the bytes the link carried stay in VRAM, no second copy (rc_tick).  0: none
    unsigned long long land_dst(Layer& l, int e, int q, unsigned seq, const int (*ids)[kPicks], int T) {
        if (!ln_land || l.rc_n == 0 || l.nm != 1) return 0ull;
        int v = -1;
        for (int i = 0; i < l.rc_n; ++i) {
            if (l.rc_fill[(size_t) i] >= 0 || l.rc_land[(size_t) i] >= 0) continue;
            const int old = l.rc_exp[(size_t) i];
            bool used = false;
            for (int t = 0; t < T && !used && old >= 0; ++t)
                for (int j = 0; j < l.k_exp && !used; ++j) used = ids[t][j] == old;
            if (used) continue;
            if (old < 0) {
                v = i;
                break;
            }
            if (v < 0 || l.rc_stamp[(size_t) i] < l.rc_stamp[(size_t) v]) v = i;
        }
        if (v < 0) return 0ull;
        l.rc_land[(size_t) v] = e;
        l.rc_lseq[(size_t) v] = seq;
        l.rc_lq[(size_t) v] = q;
        return l.rc_pin[(size_t) v];
    }
    // (serve_lane, a verify window of T > 1 tokens, ln_win) of the window's CPU-lane picks (expert, t * kPicks + i), the
    // experts the stream lane takes - each with all of its entries: the ones in RAM, those with the most tokens first,
    // as many as make the slower lane finish first on this class's costs (each expert one on either lane, whatever its
    // tokens), at most the slots - out of `picks`; the pull published with each entry's slot (always: the device's fetch
    // waits for it), their reads started.  Not timed (decode's timing and its check stay the token's)
    void lane_take_win(Layer& l, LaneCls& C, std::vector<std::pair<int, int>>& picks, LaneTake& lt, unsigned seq,
                       const int (*ids)[kPicks], int T) {
        pcie::Pull* P = ln_pull + seq % kRing;
        if (ln_job.n > 0) {
            const int jn = ln_job.n;
            if (lane_wait() != 0) {
                static std::atomic<bool> said{false};
                if (!said.exchange(true))
                    std::fprintf(stderr, "ds4: PCIe lane: reading a streamed expert failed - that token went without it\n");
            } else if (ln_job.cls != nullptr && ln_job.t_done > ln_job.t0) {
                // (in place: the device's own time - the host's includes the device's queue before the pull)
                if (ln_job.warm)
                    lane_note(*ln_job.cls, true, jn, ln_zc && ln_job.t_dev > 0 ? ln_job.t_dev : ln_job.t_done - ln_job.t0);
                if (ln_job.ab >= 0 && ln_job.t_cpu > 0)
                    lane_ab(*ln_job.cls, ln_job.ab, true, std::max(ln_job.t_cpu, ln_job.t_done) - ln_job.t_start);
            }
            ln_job.ab = -1;
        }
        lt.t0 = now_ms();
        lt.warm = false;   // (lane_answer: no timing of a window's CPU lane)
        const LaneDev& D = ln_dev[(size_t) C.dev];
        // the window's distinct experts: (tokens, expert), in RAM ones the candidates
        std::vector<std::pair<int, int>> ex;   // (-tokens, expert)
        int n_u = 0, n_cold = 0;
        {
            std::vector<std::pair<int, int>> sp = picks;
            std::sort(sp.begin(), sp.end());
            for (size_t a = 0; a < sp.size();) {
                size_t b = a;
                while (b < sp.size() && sp[b].first == sp[a].first) ++b;
                ++n_u;
                if (lane_warm(l, sp[a].first)) ex.push_back({-(int) (b - a), sp[a].first});
                else ++n_cold;
                a = b;
            }
        }
        std::sort(ex.begin(), ex.end());
        const pcie::Costs& k = C.cost;
        int ns = 0;
        const LaneAB& A = C.ab[0];
        // (tok_ab_off is the whole-step check's turn of a token's step - set by step(), so a window would keep the
        // last token's turn: only its verdict, unless the lane pulls in place, which is what that check guards against)
        const bool off = !ln_zc && (tok_ab.verdict < 0 || A.verdict < 0);
        if (k.ok() && !off && ln_force.empty()) {
            double bt = 1e30;
            const int top = std::min({(int) ex.size(), D.slots, ln_win_max});
            for (int s_ = 0; s_ <= top; ++s_) {
                const int nc = n_u - s_;
                const double tc = nc > 0 ? k.oc + k.c * nc + k.disk * n_cold : 0.0, tp = s_ > 0 ? k.op + k.p * s_ : 0.0;
                const double tm = std::fmax(tc, tp) + k.g * s_;
                if (tm < bt - 1e-9) bt = tm, ns = s_;
            }
        }
        signed char went[pcie::kPullEnt];
        for (int e = 0; e < pcie::kPullEnt; ++e) went[e] = -1;
        int slot[pcie::kSlots], exq[pcie::kSlots], se[pcie::kSlots];
        unsigned long long dst[pcie::kSlots] = {};
        if (ns > 0) {
            std::vector<std::pair<int, int>> keep;
            for (const auto& pk_ : picks) {
                int q = 0;
                while (q < ns && ex[(size_t) q].second != pk_.first) ++q;
                if (q < ns) {
                    if (pk_.second < pcie::kPullEnt) went[pk_.second] = (signed char) q;
                } else
                    keep.push_back(pk_);
            }
            picks.swap(keep);
            for (int q = 0; q < ns; ++q) {
                slot[q] = q;
                se[q] = exq[q] = ex[(size_t) q].second;
                lt.mask |= 1u << q;
                dst[q] = land_dst(l, se[q], q, seq, ids, T);
            }
        }
        lane_publish(P, seq, D, lt.mask, &l, se, went, dst);
        lt.n_s = ns;
        C.n_stream += ns;
        st.stream_experts += ns;
        if (ns > 0) {
            lane_go(l, C.dev, ns, slot, exq, P, seq, ln_zc ? &C : nullptr, ln_zc);   // (in place: the device's time)
            ln_job.ab = -1;
            ln_job.t_start = lt.t0;
            ln_job.t_cpu = 0;
        }
    }
    // (serve_lane) after the CPU lane's part: decode's timing of it (the streamed picks need nothing from the host: the
    // device pulls them as their reads land; the stream lane's timing comes with the next request - lane_take)
    void lane_answer(LaneCls& C, const LaneTake& lt) {
        if (ln_force.empty() && lt.warm) lane_note(C, false, lt.n_cpu, lt.c_ms);
        if (lt.ab < 0) return;
        if (lt.ab_split)   // (the stream lane's end comes with the next request - lane_take)
            ln_job.t_cpu = now_ms();
        else
            lane_ab(C, lt.ab, false, now_ms() - lt.t0);
    }

    // decode's check that streaming pays (LaneAB): a window's mean time with the split against the CPU lane alone;
    // the first window only warms up; 3% faster twice in a row: on, else twice not: off (this kind of request streams
    // nothing from then on); undecided after 8 windows: off.  The times file keeps the verdict for the next start
    void lane_ab(LaneCls& C, int kind, bool split, double ms) {
        LaneAB& A = C.ab[kind];
        if (A.verdict != 0 || !(ms >= 0.0)) return;
        A.ms[split ? 1 : 0] += ms;
        ++A.n[split ? 1 : 0];
        if (A.n[0] < 32 || A.n[1] < 32) return;
        const double m0 = A.ms[0] / A.n[0], m1 = A.ms[1] / A.n[1], gain = 1.0 - m1 / m0;
        A.ms[0] = A.ms[1] = 0;
        A.n[0] = A.n[1] = 0;
        if (++A.wins == 1) return;
        if (gain >= 0.03) {
            A.bad = 0;
            if (++A.good >= 2) A.verdict = 1;
        } else {
            A.good = 0;
            if (++A.bad >= 2) A.verdict = -1;
        }
        if (A.verdict == 0 && A.wins >= 9) A.verdict = -1;
        if (A.verdict == 0) return;
        std::fprintf(stderr, "ds4: PCIe lane: CUDA%d %s: decode measured the split against the CPU lane alone on "
                             "requests with %s: %.2f against %.2f ms (%+.1f%%) -> %s\n",
                     devs[(size_t) C.dev].id, C.fmt.c_str(), kind == 0 ? "every expert in RAM" : "experts from the disk",
                     m1, m0, -100.0 * gain,
                     A.verdict > 0 ? "it streams them" : "it no longer streams them (kept for the next start)");
        lane_put(C.key, lane_vals(C));
        bool off = true;   // (every class of its GPU off: the next start takes no slots there)
        for (const LaneCls& K : ln_cls)
            if (K.dev == C.dev && K.stream && (K.ab[0].verdict >= 0 || K.ab[1].verdict >= 0)) off = false;
        if (off && !ln_zc_all_live) lane_put(lane_dev_key(C.dev) + " | lane", "off");
    }

    // decode's check over whole decode steps (#329): lane_ab times one layer's lanes, where the split wins - and the
    // token as a whole got slower (2x 4090, a 7900 XTX, an RTX PRO 6000: 10-30%): the streamed experts' trips through
    // the host memory slow the rest of the step, which no layer's own timing sees.  Steps take turns in runs of 8 -
    // streaming allowed, or none (decoded tokens: the lane serves T == 1 steps only) - and their time a token decides with lane_ab's rule over windows of 64 tokens of each:
    // 3% faster twice in a row: streaming stays (lane_ab decides the rest); twice not, or undecided after 9 windows:
    // none from then on, and the times file keeps it for the next start.  DS4_STREAM_TOKEN_AB=0: off (A/B tests)
    struct TokAB {
        double ms[2] = {0, 0};
        int64_t n[2] = {0, 0};
        int arm = 0, left = 0, wins = 0, good = 0, bad = 0;
        int verdict = 0;           // 1: streaming measured faster, -1: not (none from then on), 0: measuring
    };
    TokAB tok_ab;
    std::atomic<bool> tok_ab_off{false};   // this step: the split takes no experts (the check's CPU-lane-only turn;
                                           // read by serve_lane's thread)
    double tok_ab_t0 = 0;
    bool tok_ab_active() const {
        static const bool on = [] {
            const char* v = std::getenv("DS4_STREAM_TOKEN_AB");
            return v == nullptr || std::atoi(v) != 0;
        }();
        if (!on || !ln_force.empty() || tok_ab.verdict > 0) return false;
        for (const LaneCls& C : ln_cls)
            if (C.stream) return true;
        return false;
    }
    void tok_ab_begin() {
        tok_ab_off = false;
        if (!tok_ab_active()) return;
        if (tok_ab.verdict < 0) {
            tok_ab_off = true;
            return;
        }
        if (tok_ab.left <= 0) {
            tok_ab.arm ^= 1;
            tok_ab.left = 8;
        }
        --tok_ab.left;
        tok_ab_off = tok_ab.arm == 0;
        tok_ab_t0 = now_ms();
    }
    void tok_ab_end(int T, bool ok) {
        if (!ok || !tok_ab_active() || tok_ab.verdict != 0) return;
        TokAB& A = tok_ab;
        A.ms[A.arm] += now_ms() - tok_ab_t0;
        A.n[A.arm] += T;
        if (A.n[0] < 64 || A.n[1] < 64) return;
        const double m0 = A.ms[0] / (double) A.n[0], m1 = A.ms[1] / (double) A.n[1], gain = 1.0 - m1 / m0;
        A.ms[0] = A.ms[1] = 0;
        A.n[0] = A.n[1] = 0;
        if (++A.wins == 1) return;   // (the first window warms up)
        if (gain >= 0.03) {
            A.bad = 0;
            if (++A.good >= 2) A.verdict = 1;
        } else {
            A.good = 0;
            if (++A.bad >= 2) A.verdict = -1;
        }
        if (A.verdict == 0 && A.wins >= 9) A.verdict = -1;
        if (A.verdict == 0) return;
        std::fprintf(stderr, "ds4: PCIe lane: decode measured whole steps with the split against the CPU lane alone: "
                             "%.2f against %.2f ms a token (%+.1f%%) -> %s\n", m1, m0, -100.0 * gain,
                     A.verdict > 0 ? "it streams" : "it no longer streams (kept for the next start)");
        if (A.verdict < 0) {
            tok_ab_off = true;
            std::vector<int> seen;
            for (const LaneCls& C : ln_cls)
                if (C.stream && std::find(seen.begin(), seen.end(), C.dev) == seen.end()) {
                    seen.push_back(C.dev);
                    if (!ln_zc_all_live) lane_put(lane_dev_key(C.dev) + " | lane", "off");
                }
        }
    }

    // decode's own timing of a class's lanes (GLM's lane_retime): the start-up timing is one moment, each lane alone;
    // decode times them under load (the other lane beside it, the GPU's own work, a desktop's, an integrated GPU's share
    // of the power) - a lane's time less its overhead a call over its experts, on requests whose experts (that lane's)
    // were all in RAM (the stream lane's: from its reads' start until the device has pulled the last one).  Windows of 96
    // experts (the first one only warms up); when two in a row are off the cost the split plans with by more than 15%
    // the same way, it plans with their mean from then on (at most 4 times a lane), and the times file keeps it for the
    // next start
    void lane_note(LaneCls& C, bool stream, int n, double ms) {
        LaneRetime& R = stream ? C.rs : C.rc;
        double& cost = stream ? C.cost.p : C.cost.c;
        if (R.changes >= 4 || n <= 0) return;
        R.n += n, R.calls += 1, R.ms += ms;
        if (R.n < 96) return;
        const double obs = (R.ms - (stream ? C.cost.op : C.cost.oc) * (double) R.calls) / (double) R.n;
        R.n = R.calls = 0;
        R.ms = 0;
        if (++R.win == 1) return;
        const int dir = !(obs > 0.0) ? 0 : obs > 1.15 * cost ? 1 : obs < cost / 1.15 ? -1 : 0;
        if (dir == 0 || dir != R.dir) {
            R.dir = dir;
            R.prev = obs;
            return;
        }
        const double was = cost;
        cost = 0.5 * (obs + R.prev);
        R.dir = 0;
        ++R.changes;
        const LaneDev& D = ln_dev[(size_t) C.dev];
        std::fprintf(stderr, "ds4: PCIe lane: CUDA%d %s: the %s lane timed again in decode: an expert %.3f ms (planned "
                             "with %.3f; %s %.3f) -> of 0..8 picks in RAM it streams %s\n",
                     devs[(size_t) C.dev].id, C.fmt.c_str(), stream ? "stream" : "CPU", cost, was,
                     stream ? "the CPU lane" : "streamed", stream ? C.cost.c : C.cost.p,
                     pcie::table(C.cost, D.slots).c_str());
        lane_put(C.key, lane_vals(C));
    }
    std::string lane_vals(const LaneCls& C) const {
        char v[256];
        std::snprintf(v, sizeof v, "%.4f %.4f %.4f %.4f %.4f %.4f %d %.4f %.4f %d %d", C.start.c, C.start.oc,
                      C.start.p, C.start.op, C.start.g, C.start.disk, ln_dev[(size_t) C.dev].direct ? 1 : 0,
                      C.cost.c != C.start.c ? C.cost.c : 0.0, C.cost.p != C.start.p ? C.cost.p : 0.0, C.ab[0].verdict,
                      C.ab[1].verdict);
        return v;
    }

    // ---- the PCIe lane's timing at load (each lane alone; lane_note times the CPU lane again in decode)
    // the CPU lane: n experts of one token a call (ex in turn, so the weights come from RAM, not the cache), the
    // median ms of `reps` calls
    double lane_cpu_ms(const Layer& l, const std::vector<int>& ex, int n, int reps, size_t& rot) {
        std::vector<float> x((size_t) g.dim);
        for (int i = 0; i < g.dim; ++i) x[(size_t) i] = 0.02f * std::sin(0.37f * (float) i) + ((i % 97) == 0 ? 0.3f : 0.0f);
        std::vector<double> t;
        for (int k = 0; k < reps; ++k) {
            std::vector<Ent> ents;
            for (int i = 0; i < n; ++i) {
                Ent en;
                en.e = ex[rot++ % ex.size()];
                en.n = 1;
                en.slot0 = i;
                en.tok[0] = 0;
                ents.push_back(en);
            }
            const double a = now_ms();
            cpu_experts(l, x.data(), ents, (size_t) g.dim);
            t.push_back(now_ms() - a);
        }
        std::sort(t.begin(), t.end());
        return t[t.size() / 2];
    }
    // the timing's device scratch: plans, weights, x, h, sh, out
    struct LaneGpu {
        unsigned long long *plan = nullptr, *plan2 = nullptr;
        float *w = nullptr, *x = nullptr, *h = nullptr, *sh = nullptr, *out = nullptr;
    };
    // (load time only: the calibration's, the check's) n experts ex[q] of layer l into device di's slots 0..n - 1 by
    // decode's own path - the readers into pinned memory, the fetch kernel pulling them (on the copy stream, waited for
    // here: nothing waits on the device now) - plan / plan2 its device scratch [kPicks]; false: failed
    bool lane_pull_cal(const Layer& l, int di, int n, const int* ex, unsigned long long* plan, unsigned long long* plan2) {
        LaneDev& D = ln_dev[(size_t) di];
        const unsigned seq = ++ln_cal_seq;
        int slot[kPicks], se[kPicks];
        for (int q = 0; q < n; ++q) slot[q] = q, se[q] = ex[q];
        lane_publish(ln_cal_pull, seq, D, (1u << n) - 1u, &l, se);
        cudaSetDevice(devs[(size_t) di].id);
        pcie::stream_fetch(ln_cal_pull, seq, D.cflag, D.vram, D.stride, lane_mats(l), !D.direct, plan, plan2,
                           std::max(n, 1), D.blocks, D.cs);
        lane_go(l, di, n, slot, ex, ln_cal_pull, seq);
        const bool ok = cudaStreamSynchronize(D.cs) == cudaSuccess;
        const unsigned bad = lane_wait();
        if (!ok) cudaGetLastError();
        return ok && bad == 0;
    }
    // the stream lane: n experts into the first n slots (read + pulled), the median ms of `reps` requests
    double lane_stream_ms(const Layer& l, int di, const std::vector<int>& ex, int n, int reps, size_t& rot,
                          const LaneGpu& b) {
        std::vector<double> t;
        for (int k = 0; k < reps; ++k) {
            int e[kPicks];
            for (int i = 0; i < n; ++i) e[i] = ex[rot++ % ex.size()];
            const double a = now_ms();
            if (!lane_pull_cal(l, di, n, e, b.plan, b.plan2)) return -1.0;
            t.push_back(now_ms() - a);
        }
        std::sort(t.begin(), t.end());
        return t[t.size() / 2];
    }
    // the GPU: a token's gate / up and down over the plan's first n slots (n streamed experts, the rest off the device),
    // the median ms of 9 (events)
    double lane_gpu_ms(const Layer& l, int di, const LaneGpu& b, int n) {
        Dev& d = devs[(size_t) di];
        const LaneDev& D = ln_dev[(size_t) di];
        cudaSetDevice(d.id);
        unsigned long long pl[kPicks] = {};
        for (int i = 0; i < n; ++i) pl[i] = (unsigned long long) D.slot_ptr(i);
        if (cudaMemcpy(b.plan, pl, sizeof pl, cudaMemcpyHostToDevice) != cudaSuccess) return -1.0;
        x3::MoeArgs ma;
        ma.plan_ptr = b.plan;
        ma.plan_w = b.w;
        ma.lay = l.lay;
        ma.k = l.k_exp;
        ma.n_embd = g.dim;
        ma.n_ff = g.ff;
        ma.limit = g.lim;
        cudaEvent_t e0 = nullptr, e1 = nullptr;
        cudaEventCreate(&e0);
        cudaEventCreate(&e1);
        std::vector<double> t;
        for (int k = 0; k < 12; ++k) {
            cudaEventRecord(e0, d.st);
            gg::moe_gate_up(ma, b.x, b.h, d.st);
            gg::moe_down(ma, b.h, b.sh, b.out, d.st);
            cudaEventRecord(e1, d.st);
            cudaEventSynchronize(e1);
            float ms = 0.0f;
            cudaEventElapsedTime(&ms, e0, e1);
            if (k >= 3) t.push_back(ms);
        }
        cudaEventDestroy(e0);
        cudaEventDestroy(e1);
        if (cudaGetLastError() != cudaSuccess) return -1.0;
        std::sort(t.begin(), t.end());
        return t[t.size() / 2];
    }
    // a class's costs on its GPU, timed: the CPU lane (calls of 1 and 3 experts after ~50 ms of the same work - an idle
    // CPU's clocks ramp up - the faster of 5 rounds: interference only adds time), the stream lane the same way, the
    // GPU's time an expert streamed, a read from the disk (calibrate_paths' rate, else one cold expert timed, else
    // 2 GB/s).  `cpu`: the CPU lane's, measured already for this format (another GPU's class), else timed here
    bool lane_time(LaneCls& C, const std::vector<int>& ex, const LaneGpu& b, const pcie::Costs* cpu) {
        const Layer& l = L[(size_t) C.il];
        size_t rot = 0;
        pcie::Costs k;
        if (cpu != nullptr) {
            k.c = cpu->c;
            k.oc = cpu->oc;
        } else {
            const double t0 = now_ms();
            while (now_ms() - t0 < 50.0) lane_cpu_ms(l, ex, 3, 1, rot);
            double t1 = 1e30, t3 = 1e30;
            for (int round = 0; round < 5; ++round) {
                t1 = std::min(t1, lane_cpu_ms(l, ex, 1, 4, rot));
                t3 = std::min(t3, lane_cpu_ms(l, ex, 3, 4, rot));
            }
            k.c = std::max(0.5 * (t3 - t1), t3 / 6.0);
            k.oc = std::max(0.0, t1 - k.c);
        }
        double s1 = 1e30, s3 = 1e30;
        lane_stream_ms(l, C.dev, ex, 3, 1, rot, b);   // (the link and the readers awake)
        for (int round = 0; round < 5; ++round) {
            const double a = lane_stream_ms(l, C.dev, ex, 1, 3, rot, b);
            const double c = lane_stream_ms(l, C.dev, ex, 3, 3, rot, b);
            if (a < 0 || c < 0) return false;
            s1 = std::min(s1, a);
            s3 = std::min(s3, c);
        }
        k.p = std::max(0.5 * (s3 - s1), s3 / 6.0);
        k.op = std::max(0.0, s1 - k.p);
        const int ng = std::min(ln_dev[(size_t) C.dev].slots, (int) ex.size());
        if (lane_stream_ms(l, C.dev, ex, ng, 1, rot, b) < 0) return false;   // (every slot the timing reads: an expert)
        const double g0 = lane_gpu_ms(l, C.dev, b, 0), gn = lane_gpu_ms(l, C.dev, b, ng);
        if (g0 < 0 || gn < 0) return false;
        k.g = std::max(0.0, (gn - g0) / std::max(1, ng));
        if (pm.disk > 0) k.disk = 1000.0 * (double) l.blob / pm.disk;
        else {
            int cold = -1;
            for (int e = 0; e < l.n_exp && cold < 0; ++e)
                if (l.slot[(size_t) e] < 0 && (l.ram.empty() || l.ram[(size_t) e] < 0) && !lane_warm(l, e)) cold = e;
            if (cold >= 0) {
                const double a = now_ms();
                if (read_mx_file(l, cold, ln_host)) k.disk = now_ms() - a;
            }
            if (!(k.disk > 0)) k.disk = 1000.0 * (double) l.blob / 2e9;
        }
        C.start = C.cost = k;
        return true;
    }

    // after the load: the classes (each GPU's layers by their experts' format), their costs (the times file's after a
    // cheap re-check, else timed), the split's plan; a GPU whose split never streams gives its slots back
    void lane_setup() {
        bool any = false;
        for (const LaneDev& D : ln_dev) any = any || D.vram != nullptr;
        if (!any) return;
        int cur = 0;   // (the calling thread's device, given back at the end: the timing visits each GPU)
        if (cudaGetDevice(&cur) != cudaSuccess) cudaGetLastError();
        lane_setup_gpus();
        cudaSetDevice(cur);
    }
    // per GPU: its classes timed on it, alone (a GPU whose timing cannot run, or whose pinned slots it cannot address,
    // keeps the CPU lane alone: no slots, nothing streams)
    void lane_setup_gpus() {
        const double t0 = now_ms();
        const bool hold = lane_env() != nullptr && std::atoi(lane_env()) == 2;
        // Allocation and expert placement have already followed the baseline lane decision. Only real pinned copies may
        // widen ordinary streaming now; without one, every experimental setting and calibration write stays inert.
        ln_zc_all_live = pcie::zc_all_usable(ln_zc_all, !ln_force.empty(), hold, ln_zc, zc_slot);
        ln_layer.assign(L.size(), -1);
        ln_win_layer.assign(L.size(), -1);
        std::vector<int> cls_of(L.size(), -1);
        for (const Layer& l : L) {
            if (!lane_layer_ok(l) || ln_dev[(size_t) l.dev].vram == nullptr || l.n_vram >= l.n_exp) continue;
            const std::string f = lane_fmt(l);
            int ci = -1;
            for (size_t c = 0; c < ln_cls.size(); ++c)
                if (ln_cls[c].dev == l.dev && ln_cls[c].fmt == f) ci = (int) c;
            if (ci < 0) {
                LaneCls C;
                C.fmt = f;
                C.dev = l.dev;
                ln_cls.push_back(C);
                ci = (int) ln_cls.size() - 1;
            }
            LaneCls& C = ln_cls[(size_t) ci];
            if (C.il < 0 || L[(size_t) C.il].n_exp - L[(size_t) C.il].n_vram < l.n_exp - l.n_vram) C.il = l.il;
            cls_of[(size_t) l.il] = ci;
        }
        std::string err;
        const char* rv = std::getenv("DS4_STREAM_THREADS");
        ln_readers = std::max(1, std::min(8, rv != nullptr ? std::atoi(rv) : 2));
        // (a window's streamed experts need kSlots of pinned staging; a token's alone, kPicks as before)
        if (ln_cls.empty() || !hmap(ln_host, (size_t) (ln_win ? pcie::kSlots : kPicks) * ln_stride, err) ||
            !hmap(ln_pull, (size_t) kRing, err) ||
            !hmap(ln_cal_pull, 1, err)) {
            if (!err.empty()) std::fprintf(stderr, "ds4: PCIe lane off: %s\n", err.c_str());
            for (size_t di = 0; di < ln_dev.size(); ++di) lane_free((int) di);
            return;
        }
        ln_pool = std::make_unique<Pool>(ln_readers, std::vector<int>{}, 2000);
        ln_fn = [this](int j) { lane_copy(j); };
        for (size_t di = 0; di < ln_dev.size(); ++di) {
            LaneDev& D = ln_dev[di];
            if (D.vram == nullptr) continue;
            void* hd = nullptr;
            cudaSetDevice(devs[di].id);
            if (cudaHostGetDevicePointer(&hd, ln_host, 0) != cudaSuccess || hd == nullptr) {
                cudaGetLastError();
                std::fprintf(stderr, "ds4: PCIe lane: CUDA%d cannot address the pinned slots - its CPU lane alone\n",
                             devs[di].id);
                lane_free((int) di);
                continue;
            }
            D.host_dev = (uint8_t*) hd;
            D.hstride = ln_stride;
        }
        // each class: its layer's CPU-lane experts (up to 8, in RAM first - read once, so both lanes time warm ones)
        std::vector<std::pair<std::string, pcie::Costs>> cpu_done;   // (a format's CPU lane: timed once)
        std::string report;
        bool timed = false;
        for (LaneCls& C : ln_cls) {
            const Layer& l = L[(size_t) C.il];
            LaneDev& D = ln_dev[(size_t) C.dev];
            if (D.vram == nullptr || D.host_dev == nullptr) continue;   // (its GPU keeps the CPU lane alone)
            std::vector<int> ex;
            for (int pass = 0; pass < 2 && ex.size() < 8; ++pass)
                for (int e = 0; e < l.n_exp && ex.size() < 8; ++e)
                    if (l.slot[(size_t) e] < 0 && lane_warm(l, e) == (pass == 0)) ex.push_back(e);
            if (ex.empty()) continue;
            for (int e : ex) read_mx(l, e, ln_host);   // (their pages in RAM)
            LaneGpu b;
            Dev& d = devs[(size_t) C.dev];
            size_t tmp_b = 0;   // (freed below: not the device's scratch)
            if (!dalloc(d, b.plan, kPicks, err, &tmp_b) || !dalloc(d, b.plan2, kPicks, err, &tmp_b) ||
                !dalloc(d, b.w, kPicks, err, &tmp_b) || !dalloc(d, b.x, (size_t) g.dim, err, &tmp_b) ||
                !dalloc(d, b.h, (size_t) kPicks * g.ff, err, &tmp_b) || !dalloc(d, b.sh, (size_t) g.dim, err, &tmp_b) ||
                !dalloc(d, b.out, (size_t) g.dim, err, &tmp_b)) {
                std::fprintf(stderr, "ds4: PCIe lane: %s\n", err.c_str());
                continue;
            }
            {
                std::vector<float> w(kPicks, 1.0f / (float) l.k_exp), x((size_t) g.dim);
                for (int i = 0; i < g.dim; ++i) x[(size_t) i] = 0.02f * std::sin(0.37f * (float) i);
                cudaMemcpy(b.w, w.data(), w.size() * 4, cudaMemcpyHostToDevice);
                cudaMemcpy(b.x, x.data(), x.size() * 4, cudaMemcpyHostToDevice);
                cudaMemset(b.sh, 0, (size_t) g.dim * 4);
            }
            C.key = lane_dev_key(C.dev) + " | " + C.fmt + " | " + std::to_string(cpu_threads()) + " threads, " +
                    std::to_string(ln_readers) + " readers" + (copy_mode ? ", copies" : "");
            const pcie::Costs* cpu = nullptr;
            for (const auto& cd : cpu_done)
                if (cd.first == C.fmt) cpu = &cd.second;
            // the times file's: kept when a cheap re-check agrees (a call of 3 experts on each lane within 35%)
            bool have = false;
            const std::string vals = ln_force.empty() ? pcie::cal_get(ln_file, C.key) : std::string();
            if (!vals.empty()) {
                pcie::Costs k;
                int direct = 0;
                double dc = 0, dp = 0;
                int v0 = 0, v1 = 0;
                const auto dir_ok = [&] {   // (a GPU's classes share its mode: the first one's)
                    const bool want = direct != 0 && D.integrated && D.host_dev != nullptr;
                    return !D.mode_set || want == D.direct;
                };
                if (std::sscanf(vals.c_str(), "%lf %lf %lf %lf %lf %lf %d %lf %lf %d %d", &k.c, &k.oc, &k.p, &k.op, &k.g,
                                &k.disk, &direct, &dc, &dp, &v0, &v1) >= 7 && k.ok() && dir_ok()) {
                    D.direct = direct != 0 && D.integrated && D.host_dev != nullptr;
                    size_t rot = 0;
                    lane_cpu_ms(l, ex, 3, 2, rot);
                    const double tc = lane_cpu_ms(l, ex, 3, 3, rot);
                    lane_stream_ms(l, C.dev, ex, 3, 1, rot, b);
                    const double ts = lane_stream_ms(l, C.dev, ex, 3, 3, rot, b);
                    const double wc = k.oc + 3 * k.c, ws = k.op + 3 * k.p;
                    have = tc > 0 && ts > 0 && tc < 1.35 * wc && tc > wc / 1.35 && ts < 1.35 * ws && ts > ws / 1.35;
                    if (have) {
                        C.start = C.cost = k;
                        if (dc > 0) C.cost.c = dc;
                        if (dp > 0) C.cost.p = dp;
                        C.ab[0].verdict = std::max(-1, std::min(1, v0));
                        C.ab[1].verdict = std::max(-1, std::min(1, v1));
                        D.mode_set = true;
                    } else
                        std::fprintf(stderr, "ds4: PCIe lane: CUDA%d %s: the times file's (%.2f / %.2f ms for 3 experts on "
                                             "the CPU / streamed) do not hold now (%.2f / %.2f) - timed again\n",
                                     d.id, C.fmt.c_str(), wc, ws, tc, ts);
                }
            }
            if (!have) {
                bool ok = false;
                const char* dv = std::getenv("DS4_STREAM_DIRECT");
                if (D.mode_set) {   // (the GPU's mode: its first class's)
                    ok = lane_time(C, ex, b, cpu);
                } else if (D.integrated && D.host_dev != nullptr && (dv == nullptr || std::atoi(dv) != 0)) {
                    // an integrated GPU: the kernels reading the pinned slots in place, or a copy in its memory -
                    // whichever plans the faster split of k_exp picks (DS4_STREAM_DIRECT=1: in place alone)
                    LaneCls cd = C;
                    D.direct = true;
                    const bool okd = lane_time(cd, ex, b, cpu);
                    D.direct = false;
                    const pcie::Costs* cpu2 = cpu != nullptr ? cpu : okd ? &cd.start : nullptr;
                    const bool okv = (dv != nullptr && std::atoi(dv) != 0) ? false : lane_time(C, ex, b, cpu2);
                    double td = 1e30, tv = 1e30;
                    if (okd) pcie::split(cd.cost, l.k_exp, 0u, D.slots, &td);
                    if (okv) pcie::split(C.cost, l.k_exp, 0u, D.slots, &tv);
                    if (okd && td < tv) {
                        C = cd;
                        D.direct = true;
                    }
                    ok = okd || okv;
                } else {
                    D.direct = false;
                    ok = lane_time(C, ex, b, cpu);
                }
                if (ok) {
                    D.mode_set = true;
                    timed = true;
                    if (ln_force.empty()) lane_put(C.key, lane_vals(C));
                } else {
                    std::fprintf(stderr, "ds4: PCIe lane: CUDA%d %s: timing failed - the CPU lane alone\n", d.id,
                                 C.fmt.c_str());
                    C.cost = C.start = pcie::Costs{};
                }
            }
            if (C.cost.ok()) {
                if (cpu == nullptr) cpu_done.push_back({C.fmt, C.start});
                const bool measured = pcie::streams_any(C.cost, D.slots, l.k_exp) &&
                                      (C.ab[0].verdict >= 0 || C.ab[1].verdict >= 0);
                C.win = !ln_force.empty() || measured;   // the baseline's class decision, shared with verify windows
                C.stream = C.win || ln_zc_all_live;
                if (std::getenv("DS4_LANE_CHECK") != nullptr) lane_check(C, ex, b);
            }
            for (void* p : {(void*) b.plan, (void*) b.plan2, (void*) b.w, (void*) b.x, (void*) b.h, (void*) b.sh,
                            (void*) b.out}) {
                auto it = std::find(d.allocs.begin(), d.allocs.end(), p);
                if (it != d.allocs.end()) d.allocs.erase(it);
                cudaFree(p);
            }
            if (!C.cost.ok()) continue;
            const char* vw[3] = {"slower: off", "being measured", "faster"};   // (decode's check, lane_ab)
            char line[640];
            std::snprintf(line, sizeof line,
                          "ds4: PCIe lane: CUDA%d %s: an expert %.3f ms on the CPU lane (+%.3f a call), %.3f streamed "
                          "(+%.3f a request%s), %.3f on the GPU, %.2f from the disk -> of 0..%d picks in RAM it streams %s "
                          "(decode's check of streaming - picks all in RAM: %s, some from the disk: %s)\n",
                          d.id, C.fmt.c_str(), C.cost.c, C.cost.oc, C.cost.p, C.cost.op, D.direct ? ", read in place" : "",
                          C.cost.g, C.cost.disk, l.k_exp, pcie::table(C.cost, D.slots, l.k_exp).c_str(),
                          vw[C.ab[0].verdict + 1], vw[C.ab[1].verdict + 1]);
            report += line;
        }
        // the layers that stream; the GPUs none of whose layers do give their slots back (and the times file says so).
        // (DS4_STREAM=2, tests: the slots kept, nothing streams - the CPU lane alone with the experts' placement of a
        // start that streams, the baseline a streaming run's answers compare with bit for bit)
        for (const Layer& l : L) {
            const int ci = cls_of[(size_t) l.il];
            if (ci < 0 || !ln_cls[(size_t) ci].cost.ok() || hold) continue;
            const LaneCls& C = ln_cls[(size_t) ci];
            if (C.stream) {
                ln_layer[(size_t) l.il] = ci;
                ln_dev[(size_t) l.dev].on = true;
            }
            if (C.win) ln_win_layer[(size_t) l.il] = ci;
        }
        int n_on = 0;
        for (size_t di = 0; di < ln_dev.size(); ++di) {
            LaneDev& D = ln_dev[di];
            if (D.vram == nullptr || hold) continue;
            if (ln_force.empty() && !ln_zc_all_live) lane_put(lane_dev_key((int) di) + " | lane", D.on ? "on" : "off");
            if (!D.on || D.direct) lane_free((int) di);
            n_on += D.on;
        }
        int nl = 0;
        for (int c : ln_layer) nl += c >= 0;
        std::fprintf(stderr, "%sds4: PCIe lane: %d layers on %d GPU(s) stream some of a token's CPU-lane experts (%d "
                             "reading threads; %s, %.0f ms)%s\n",
                     report.c_str(), nl, n_on, ln_readers, timed ? "timed" : "the times file's", now_ms() - t0,
                     hold                ? " - DS4_STREAM=2: the slots kept, nothing streams"
                     : ln_force.empty() ? ""
                                        : " - DS4_STREAM_FORCE");
        if (ln_zc_all_live)
            std::fprintf(stderr, "ds4: PCIe lane: DS4_STREAM_ZC_ALL=1: ordinary routes with every pick pinned stream whole\n");
        if (ln_zc_all_live && ln_zc_nowait)
            std::fprintf(stderr, "ds4: PCIe lane: DS4_STREAM_ZC_NOWAIT=1: fully covered layers skip the empty CPU response\n");
    }

    // DS4_LANE_CHECK: one expert of the class through both lanes on one normalised input - the CPU lane's output and the
    // device's (streamed into slot 0, its kernels: weight 1, nothing else in the sum) - and how far apart they are
    void lane_check(const LaneCls& C, const std::vector<int>& ex, const LaneGpu& b) {
        const Layer& l = L[(size_t) C.il];
        Dev& d = devs[(size_t) C.dev];
        const int E = g.dim;
        std::vector<float> x((size_t) E);
        double ss = 0;
        for (int i = 0; i < E; ++i) {
            x[(size_t) i] = std::sin(0.71f * (float) i) + ((i % 97) == 0 ? 6.0f : 0.0f);
            ss += (double) x[(size_t) i] * x[(size_t) i];
        }
        for (float& v : x) v = (float) (v / std::sqrt(ss / E));
        int n_bad = 0;
        double worst = 0, worst_rel = 0;
        int64_t same = 0, all = 0;
        for (size_t q = 0; q < ex.size() && q < 4; ++q) {
            const int e = ex[q];
            std::vector<Ent> ents(1);
            ents[0].e = e;
            ents[0].n = 1;
            ents[0].tok[0] = 0;
            cpu_experts(l, x.data(), ents, (size_t) E);
            const std::vector<float> yc(c_yd.begin(), c_yd.begin() + E);
            if (!lane_pull_cal(l, C.dev, 1, &e, b.plan, b.plan2)) {
                ++n_bad;
                continue;
            }
            cudaSetDevice(d.id);
            unsigned long long pl[kPicks] = {};
            pl[0] = (unsigned long long) ln_dev[(size_t) C.dev].slot_ptr(0);
            std::vector<float> w(kPicks, 0.0f);
            w[0] = 1.0f;
            cudaMemcpy(b.plan, pl, sizeof pl, cudaMemcpyHostToDevice);
            cudaMemcpy(b.w, w.data(), w.size() * 4, cudaMemcpyHostToDevice);
            cudaMemcpy(b.x, x.data(), x.size() * 4, cudaMemcpyHostToDevice);
            x3::MoeArgs ma;
            ma.plan_ptr = b.plan;
            ma.plan_w = b.w;
            ma.lay = l.lay;
            ma.k = l.k_exp;
            ma.n_embd = E;
            ma.n_ff = g.ff;
            ma.limit = g.lim;
            gg::moe_gate_up(ma, b.x, b.h, d.st);
            gg::moe_down(ma, b.h, b.sh, b.out, d.st);
            std::vector<float> yg((size_t) E);
            cudaMemcpyAsync(yg.data(), b.out, (size_t) E * 4, cudaMemcpyDeviceToHost, d.st);
            cudaStreamSynchronize(d.st);
            double mx = 0;
            for (int i = 0; i < E; ++i) mx = std::max(mx, (double) std::fabs(yc[(size_t) i]));
            for (int i = 0; i < E; ++i) {
                const double df = std::fabs((double) yc[(size_t) i] - (double) yg[(size_t) i]);
                worst = std::max(worst, df);
                worst_rel = std::max(worst_rel, mx > 0 ? df / mx : df);
                same += std::memcmp(&yc[(size_t) i], &yg[(size_t) i], 4) == 0;
                ++all;
            }
        }
        std::fprintf(stderr, "ds4: lane check: %s: an expert on the CPU lane vs streamed to CUDA%d: %lld of %lld outputs "
                             "bit-identical, max |diff| %.3g (%.3g of the largest output)%s\n",
                     C.fmt.c_str(), d.id, (long long) same, (long long) all, worst, worst_rel,
                     n_bad ? " - a copy FAILED" : "");
    }

    // a GGUF's matrices (BF16 / MXFP4) to its own kernels, EXL3 ones to x3's
    static bool mv_any(const x3::MvJob* j, int n, cudaStream_t s, const gg::PreQ8* pre = nullptr) {
        bool g = false;
        for (int i = 0; i < n; ++i) g = g || j[i].m->fmt != 0;
        return g ? (pre != nullptr ? gg::mv(j, n, s, pre) : gg::mv(j, n, s)) : x3::mv(j, n, s);
    }
    bool mv(Dev& d, std::initializer_list<x3::MvJob> jobs, std::string& err) {
        x3::MvJob j[x3::kMaxMvJobs];
        int n = 0;
        for (const x3::MvJob& x : jobs) j[n++] = x;
        if (!mv_any(j, n, d.st)) {
            err = "exl3 mv failed";
            return false;
        }
        return true;
    }
    bool mv_n(Dev& d, x3::MvJob* j, int n, std::string& err, const gg::PreQ8* pre = nullptr) {
        for (int a = 0; a < n; a += x3::kMaxMvJobs)
            if (!mv_any(j + a, std::min(x3::kMaxMvJobs, n - a), d.st, pre)) {
                err = "exl3 mv failed";
                return false;
            }
        return true;
    }
    // y[c] = x[c] W for the T activations x + c * x_cs (floats), into y + c * y_cs
    static x3::MvJob job(const x3::Mat& m, const float* x, float* y, int T = 1, size_t x_cs = 0, size_t y_cs = 0,
                         float alpha = 1.0f) {
        x3::MvJob j;
        j.m = &m;
        j.xf = x;
        j.y = y;
        j.alpha = alpha;
        j.ncol = T;
        j.xf_cs = x_cs;
        j.y_cs = y_cs;
        return j;
    }
    // the attention's input GEMVs of layer l on x: q's low rank, the KV row, and the compressed KV and its gate where
    // the layer has them
    int attn_in_jobs(const Layer& l, const float* x, float* qr, float* kvr, float* ckr, float* cgr, int T,
                     x3::MvJob* j) const {
        const int D = g.dim, HD = g.hd;
        int nj = 0;
        j[nj++] = job(l.wq_a, x, qr, T, D, g.q_lora);
        j[nj++] = job(l.wkv, x, kvr, T, D, HD);
        if (l.kv_src) j[nj++] = job(l.c_wkv, x, ckr, T, D, HD);
        if (l.kv_src && l.ratio > 1) j[nj++] = job(l.c_wgate, x, cgr, T, D, HD);
        return nj;
    }
    // the shared expert's swiglu on d.sg / d.su (rows of FF) and its down GEMV into d.sh_out: DS4_DECODE_TRIM 1 rounds
    // the swiglu's output to int8 where it is made, for the GEMV (swiglu_q8, PreQ8); else as before
    bool shared_down(Dev& d, const Layer& l, int T, int FF, std::string& err) {
        const bool q8 = (decode_trim & 1) && FF % 32 == 0 && T <= kWin && d.shq8 != nullptr;
        gg::PreQ8 pq;
        if (q8) {
            if (!swiglu_q8(d.sg, d.su, T * FF, g.lim, d.sh, d.shq8, d.shd8, d.st)) {
                err = "DS4_DECODE_TRIM: swiglu_q8 refused";
                return false;
            }
            pq.x = d.sh;
            pq.q = d.shq8;
            pq.d = d.shd8;
            pq.k = FF;
            pq.rows = T;
        } else
            swiglu(d.sg, d.su, T * FF, g.lim, d.sh, d.st);
        x3::MvJob j = job(l.s2, d.sh, d.sh_out, T, FF, g.dim);
        return mv_n(d, &j, 1, err, q8 ? &pq : nullptr);
    }
    // (DS4_HC_FUSE) hc_split_pre_norm's arguments for layer l's attention (ffn false) or FFN: its split weights and
    // norm, the model's constants, these buffers (a decoded token's)
    HcFuse hc_args(const Layer& l, bool ffn, const float* mixes, const float* h, const float* mix, float* x, int8_t* q,
                   float* qd, float* pre, float* post, float* comb, float* pre_copy) const {
        HcFuse a;
        a.mixes = mixes;
        a.scale = ffn ? l.hcf_scale : l.hca_scale;
        a.base = ffn ? l.hcf_base : l.hca_base;
        a.hc = g.hc;
        a.iters = g.sinkhorn;
        a.hc_eps = g.hc_eps;
        a.pre = pre;
        a.post = post;
        a.comb = comb;
        a.pre_copy = pre_copy;
        a.h = h;
        a.mix = mix;
        a.w = ffn ? l.ffn_norm : l.attn_norm;
        a.dim = g.dim;
        a.eps = g.eps;
        a.x = x;
        a.q = q;
        a.qd = qd;
        return a;
    }

    // ---- the DSpark drafter (DeepSeek's DSparkBlock / forward_spec).  Its blocks' rings hold the trunk's main KV:
    // seed() turns a window's taps (the streams' mean entering layers 37..39) into it, through main_proj / main_norm
    // and each block's wkv / kv_norm / rope / FP8, for the positions the trunk kept.  draft() runs the block [y, noise x
    // (block - 1)] at positions pos .. through the blocks (each query attending to the ring and to the whole block),
    // the trunk's head, the markov bias token by token (greedy) and the confidence head.
    bool seed_drafter(int64_t p0, int n, int row0, std::string& err) {
        if (g.n_mtp == 0 || n <= 0) return true;
        if (n > kWin * kPicks) {
            err = "seeding the drafter with " + std::to_string(n) + " rows";
            return false;
        }
        const int nt = (int) g.d_targets.size(), D = g.dim, HD = g.hd;
        if (dump_d != nullptr) {   // DS4_DSPARK_DUMP: 'S', the first position, the rows, then the taps
            for (Dev& e : devs) {
                cudaSetDevice(e.id);
                CK(cudaStreamSynchronize(e.st));
            }
            const int64_t hdr[4] = {'S', p0, n, (int64_t) nt * D};
            std::fwrite(hdr, 8, 4, dump_d);
            std::fwrite(h_taps + (size_t) row0 * nt * D, 4, (size_t) n * nt * D, dump_d);
            std::fflush(dump_d);
        }
        // each block device (DS4_DRAFT_DEV: more than one) projects the taps itself - main_proj / main_norm are on every
        // one - then seeds its own blocks' rings, in block order; no row crosses the cards
        std::vector<char> projected(devs.size(), 0);
        for (int i = 0; i < g.n_mtp; ++i) {
            Layer& l = L[(size_t) (g.nl + i)];
            Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            if (!projected[(size_t) l.dev]) {
                if (d.d_proj_norm == nullptr) {
                    err = "CUDA" + std::to_string(d.id) + " holds DSpark block " + std::to_string(i) + " but not main_proj";
                    return false;
                }
                for (int a = 0; a < n; a += kWin) {   // (a chunk's last 128 rows: 16 a GEMV)
                    const int na = std::min(kWin, n - a);
                    CK(cudaMemcpyAsync(d.xe, h_taps + (size_t) (row0 + a) * nt * D, (size_t) na * nt * D * 4,
                                       cudaMemcpyHostToDevice, d.st));
                    if (!mv(d, {job(d.d_proj, d.xe, d.ed + (size_t) a * D, na, (size_t) nt * D, D)}, err)) return false;
                }
                CK(cudaEventRecord(d.ev_seed, d.st));
                Finish fm;
                fm.w = d.d_proj_norm;
                fm.eps = g.eps;
                finish(d.ed, n, D, D, fm, d.st);
                projected[(size_t) l.dev] = 1;
            }
            for (int a = 0; a < n; a += kWin) {
                const int na = std::min(kWin, n - a);
                if (!mv(d, {job(l.wkv, d.ed + (size_t) a * D, d.kvr, na, D, HD)}, err)) return false;
                Finish fk;
                fk.w = l.kv_norm;
                fk.eps = g.eps;
                fk.rd = g.rd;
                fk.pos = (int) (p0 + a);
                fk.freqs = d.freqs_win;
                fk.quant = 1;
                fk.dst = d.ext + (size_t) g.win * HD;
                fk.dst_stride = HD;
                finish(d.kvr, na, HD, HD, fk, d.st);
                ext_to_ring(d.ext, l.win, p0 + a, g.win, na, HD, d.st);
            }
        }
        return true;
    }

    bool draft(int y, std::vector<int>& out, std::vector<float>& conf, std::string& err, float temperature, float top_p,
               int top_k, float min_p, uint64_t seed, uint64_t counter) {
        const double t0 = now_ms();
        // (with penalties the drafts are the drafter's argmax: its own draws know no history - verify() is as exact)
        drafts_q = temperature > 0.0f && sample_drafts && pen_n <= 0;
        dq_temp = temperature;
        dq_top_p = top_p;
        dq_top_k = top_k;
        dq_min_p = min_p;
        dq_seed = seed;
        dq_counter = counter;
        const bool ok = draft_(y, out, conf, err);
        if (!ok) drafts_q = false;
        if (max_drafts > 0 && (int) out.size() > max_drafts) {
            out.resize((size_t) max_drafts);
            conf.resize((size_t) max_drafts);
        }
        st.draft_ms += now_ms() - t0;
        ++st.drafts_rounds;
        return ok;
    }
    bool draft_(int y, std::vector<int>& out, std::vector<float>& conf, std::string& err) {
        out.clear();
        conf.clear();
        const int T = g.d_block, D = g.dim, H = g.hc, V = g.vocab, R = g.d_rank;
        const int64_t p0 = pos;
        if (g.n_mtp == 0 || T < 1 || T > kWin || p0 + T > o.max_context) return true;
        int tk[kWin];
        tk[0] = y;
        for (int t = 1; t < T; ++t) tk[t] = g.d_noise;
        Dev& d = devs[(size_t) d_dev];
        cudaSetDevice(d.id);
        for (int t = 0; t < T; ++t) std::memcpy(h_emb + (size_t) t * D, embed_pinned + (size_t) tk[t] * D, (size_t) D * 2);
        CK(cudaMemcpyAsync(d.emb_rows, h_emb, (size_t) T * D * 2, cudaMemcpyHostToDevice, d.st));
        embed(d.emb_rows, T, d.h, D, H, d.st);
        init_pre(d.pre, T, d.st);
        WinPlan dp;   // (window attention alone: the mailbox seqs)
        dp.async = !sync_decode && T <= async_max_t;
        for (int i = 0; i < g.n_mtp && dp.async; ++i) {
            const int il = g.nl + i;
            dp.seq[il] = 0;
            if (host_free(L[(size_t) il])) continue;
            dp.seq[il] = ++seq_issued;
            layer_of[dp.seq[il] % kRing].store(il, std::memory_order_release);
        }
        const size_t hs = (size_t) T * H * D, rs = (size_t) g.win * g.hd;
        if (dump_d != nullptr && h_dump == nullptr &&
            (!halloc(h_dump, (size_t) g.n_mtp * kWin * H * D, err) || !halloc(h_dump_ring, (size_t) g.n_mtp * rs, err)))
            return false;
        int cur = d_dev;   // the device the block's rows are on
        std::vector<char> handed(devs.size(), 0);   // (DS4_DECODE_TRIM 8: a device's one block hand-off region)
        for (int i = 0; i < g.n_mtp; ++i) {
            Layer& l = L[(size_t) (g.nl + i)];
            if (l.dev != cur && (decode_trim & 8) && !handed[(size_t) cur] && devs[(size_t) cur].dhand != nullptr) {
                // (DS4_DECODE_TRIM 8: h, then pre, through the device's host-mapped rows and its flag - xfer_put on
                //  the block's card, xfer_get on the next's, no runtime copy or event)
                Dev& a = devs[(size_t) cur];
                Dev& b = devs[(size_t) l.dev];
                const size_t nh = (size_t) T * H * D * 4, np = (size_t) T * 8 * 4;
                const unsigned sq = ++d_xseq;
                Xfer px, gx;
                px.n = gx.n = 2;
                px.src[0] = a.h;
                px.dst[0] = a.dhand;
                px.bytes[0] = gx.bytes[0] = nh;
                px.src[1] = a.pre;
                px.dst[1] = a.dhand + nh;
                px.bytes[1] = gx.bytes[1] = np;
                gx.src[0] = a.dhand;
                gx.dst[0] = b.h;
                gx.src[1] = a.dhand + nh;
                gx.dst[1] = b.pre;
                cudaSetDevice(a.id);
                xfer_put(px, a.dhand_flag, sq, a.xcnt, a.st);
                cudaSetDevice(b.id);
                xfer_get(gx, a.dhand_flag, sq, b.st);
                handed[(size_t) cur] = 1;
                cur = l.dev;
            }
            if (l.dev != cur) {   // (DS4_DRAFT_DEV: the next block on another card - its rows through pinned host memory,
                Dev& a = devs[(size_t) cur];   //  as a layer split's groups hand theirs: h, then pre)
                Dev& b = devs[(size_t) l.dev];
                const size_t nh = (size_t) T * H * D * 4, np = (size_t) T * 8 * 4;
                cudaSetDevice(a.id);
                CK(cudaMemcpyAsync(a.bounce, a.h, nh, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(a.bounce + nh, a.pre, np, cudaMemcpyDeviceToHost, a.st));
                CK(cudaEventRecord(a.ev_out, a.st));
                cudaSetDevice(b.id);
                CK(cudaStreamWaitEvent(b.st, a.ev_out, 0));
                CK(cudaMemcpyAsync(b.h, a.bounce, nh, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.pre, a.bounce + nh, np, cudaMemcpyHostToDevice, b.st));
                cur = l.dev;
            }
            Dev& db = devs[(size_t) cur];
            if (dump_d != nullptr) {   // (stream order: the ring the block reads - as BF16 rows - the stream it leaves)
                cudaSetDevice(db.id);
                ring_to_ext(l.win, db.ext, g.win, g.win, g.hd, db.st);
                CK(cudaMemcpyAsync(h_dump_ring + (size_t) i * rs, db.ext, rs * 2, cudaMemcpyDeviceToHost, db.st));
            }
            if (!layer(l, 0, p0, T, dp, err)) return false;
            if (dump_d != nullptr) {
                cudaSetDevice(db.id);
                CK(cudaMemcpyAsync(h_dump + (size_t) i * hs, db.h, hs * 4, cudaMemcpyDeviceToHost, db.st));
            }
        }
        Dev& dl = devs[(size_t) cur];   // the last block's device: the drafts' rows
        cudaSetDevice(dl.id);
        hc_pre_norm(dl.h, dl.pre, nullptr, D, H, T, g.eps, dl.x, dl.st);   // (the confidence head reads it before the norm)
        Dev& hd = devs[(size_t) head_dev];
        // (through the host to the head's device, and to the head group's other members - the last block's device can
        // be the head group's lead itself, a group of every GPU, or one of its other members; DS4_DECODE_TRIM 8: by
        // xfer, through dl's host-mapped x rows and its flag)
        const bool xh = (decode_trim & 8) && dl.dhand != nullptr;
        unsigned xsq = 0;
        auto get_x = [&](Dev& e, float* dst) {   // (on e's stream: waits for dl's flag, then the rows)
            Xfer gx;
            gx.n = 1;
            gx.src[0] = dl.dhand + dhand_x();
            gx.dst[0] = dst;
            gx.bytes[0] = (size_t) T * D * 4;
            xfer_get(gx, dl.dhand_flag, xsq, e.st);
        };
        if (cur != head_dev || groups[(size_t) hd.grp].mem.size() > 1) {
            if (xh) {
                xsq = ++d_xseq;
                Xfer px;
                px.n = 1;
                px.src[0] = dl.x;
                px.dst[0] = dl.dhand + dhand_x();
                px.bytes[0] = (size_t) T * D * 4;
                xfer_put(px, dl.dhand_flag, xsq, dl.xcnt, dl.st);
            } else {
                CK(cudaMemcpyAsync(dl.bounce, dl.x, (size_t) T * D * 4, cudaMemcpyDeviceToHost, dl.st));
                CK(cudaEventRecord(dl.ev_out, dl.st));
            }
        }
        if (cur != head_dev) {
            cudaSetDevice(hd.id);
            if (xh) get_x(hd, hd.x);
            else {
                CK(cudaStreamWaitEvent(hd.st, dl.ev_out, 0));
                CK(cudaMemcpyAsync(hd.x, dl.bounce, (size_t) T * D * 4, cudaMemcpyHostToDevice, hd.st));
            }
        }
        // the drafter's final norm and the trunk's head, on every member of the head group (the others' shares first)
        const std::vector<int>& hg = groups[(size_t) hd.grp].mem;
        const bool mk = mk_split && !drafts_q;   // (sampled drafts: the lead's whole rows, gathered)
        for (int m = (int) hg.size() - 1; m >= 0; --m) {
            Dev& e = devs[(size_t) hg[(size_t) m]];
            cudaSetDevice(e.id);
            if (m > 0 && &e != &dl && xh) get_x(e, e.ao);
            else if (m > 0 && &e != &dl) {
                CK(cudaStreamWaitEvent(e.st, dl.ev_out, 0));
                CK(cudaMemcpyAsync(e.ao, dl.bounce, (size_t) T * D * 4, cudaMemcpyHostToDevice, e.st));
            } else   // (the lead's x came from the last block's device above; a member that is that device: its own)
                CK(cudaMemcpyAsync(e.ao, m > 0 ? dl.x : e.x, (size_t) T * D * 4, cudaMemcpyDeviceToDevice, e.st));
            Finish fn;
            fn.w = e.d_norm;
            fn.eps = g.eps;
            finish(e.ao, T, D, D, fn, e.st);
            if (!head_share(e, m, e.ao, T, err, !mk)) return false;
        }
        h_idx[0] = y;
        if (mk) {
            // the markov steps over the group: each member its rows of the bias and its share's argmax, every member
            // then the global one (the sampler's tie rule) and its E row - the same drafts as the lead's whole rows,
            // each step ~1/nm of their 66 MB and no gather of the shares
            const int nm = (int) hg.size();
            const unsigned seq = ++mk_seq;
            for (int m = 0; m < nm; ++m) {
                Dev& e = devs[(size_t) hg[(size_t) m]];
                cudaSetDevice(e.id);
                CK(cudaMemcpyAsync(e.mk_ints, h_idx, 4, cudaMemcpyHostToDevice, e.st));
                CK(cudaMemcpyAsync(e.mk_erow, h_mk_embed + (size_t) y * R, (size_t) R * 2, cudaMemcpyHostToDevice, e.st));
            }
            for (int i = 0; i < T; ++i)
                for (int m = 0; m < nm; ++m) {
                    Dev& e = devs[(size_t) hg[(size_t) m]];
                    cudaSetDevice(e.id);
                    float* row = m == 0 ? hd.logits + (size_t) i * V : e.logits_part + (size_t) i * e.mk_vn;
                    markov_share(row, e.mk_share, e.mk_erow, e.mk_vn, R, e.st);
                    argmax_share(row, e.mk_vn, e.mk_v0, mk_slots + ((size_t) i * nm + m) * 4, seq, e.st);
                    markov_pick(mk_slots + (size_t) i * nm * 4, nm, seq, e.mk_ints + i + 1, h_mk_embed, e.mk_erow, R,
                                e.st);
                }
            cudaSetDevice(hd.id);
        } else {
            CK(cudaMemcpyAsync(d_ints, h_idx, 4, cudaMemcpyHostToDevice, hd.st));
            strata::kernels::SamplerParams sp;
            sp.greedy = true;
            sp.temperature = 0.0f;
            if (drafts_q) {   // the request's own chain: draft i drawn as the model's token i would be (verify's counter + i)
                sp.greedy = false;
                sp.temperature = dq_temp * (q_temp_scale > 0.0f ? q_temp_scale : 1.0f);
                sp.top_p = dq_top_p;
                sp.top_k = dq_top_k;
                sp.min_p = dq_min_p;
                sp.seed = dq_seed;
            }
            for (int i = 0; i < T; ++i) {   // the markov bias of the token before, then that position's draft
                markov_add(hd.logits + (size_t) i * V, d_mk_embed, d_mk_head, d_ints + i, V, R, hd.st);
                if (drafts_q) {
                    sp.counter = dq_counter + (uint64_t) i;
                    strata::kernels::sample_draft(hd.logits + (size_t) i * V, 1, V, sp, d_specq + i, d_ints + i + 1, hd.st);
                } else
                    strata::kernels::sample_tokens(hd.logits + (size_t) i * V, 1, V, nullptr, 0, sp, d_ints + i + 1, hd.st);
            }
        }
        confidence(hd.x, d_mk_embed, d_ints, d_conf, T, D, R, d_confv, hd.st);
        int tok[kWin + 1];
        float cf[kWin];
        CK(cudaMemcpyAsync(h_idx, d_ints, (size_t) (T + 1) * 4, cudaMemcpyDeviceToHost, hd.st));
        CK(cudaMemcpyAsync(h_w, d_confv, (size_t) T * 4, cudaMemcpyDeviceToHost, hd.st));
        CK(cudaStreamSynchronize(hd.st));
        for (int i = 0; i <= T; ++i) tok[i] = h_idx[i];
        for (int i = 0; i < T; ++i) cf[i] = h_w[i];
        if (dump_d != nullptr) {   // 'D', the block's position, y, T, then the drafts, their confidences, the hidden
            std::vector<float> xs((size_t) T * D);   // rows before the final norm; then each block's ring and stream
            CK(cudaMemcpy(xs.data(), hd.x, xs.size() * 4, cudaMemcpyDeviceToHost));
            for (Dev& e : devs)   // (every block device's dump copies)
                if (block_dev((int) (&e - &devs[0]))) {
                    cudaSetDevice(e.id);
                    CK(cudaStreamSynchronize(e.st));
                }
            const int64_t hdr[4] = {'D', p0, y, T};
            std::fwrite(hdr, 8, 4, dump_d);
            std::fwrite(tok + 1, 4, (size_t) T, dump_d);
            std::fwrite(cf, 4, (size_t) T, dump_d);
            std::fwrite(xs.data(), 4, xs.size(), dump_d);
            for (int i = 0; i < g.n_mtp; ++i) {
                std::fwrite(h_dump_ring + (size_t) i * rs, 2, rs, dump_d);
                std::fwrite(h_dump + (size_t) i * hs, 4, hs, dump_d);
            }
            std::fflush(dump_d);
            cudaSetDevice(hd.id);
        }
        for (int i = 0; i < T; ++i) {
            out.push_back(tok[i + 1]);
            conf.push_back(cf[i]);
        }
        return true;
    }

    // the penalty rows of T picks (on the head device, its stream): row t the last h of toks[0 .. end0 + t), -1 in
    // front; the penalties into sp.  nullptr and h = 0 (sp untouched) for a request without penalties
    const int* pen_rows(int64_t end0, int T, strata::kernels::SamplerParams& sp, int& h) {
        h = 0;
        if (pen_n <= 0 || T < 1 || T > kWin) return nullptr;
        Dev& d = devs[(size_t) head_dev];
        if (d_pen == nullptr) {
            std::string e;
            if (!halloc(h_pen, (size_t) kWin * kPenCap, e) || !dalloc(d, d_pen, (size_t) kWin * kPenCap, e)) {
                std::fprintf(stderr, "ds4: the penalty rows: %s - picks without the penalties\n", e.c_str());
                pen_n = 0;
                return nullptr;
            }
        }
        cudaSetDevice(d.id);
        h = std::min(pen_n, kPenCap);
        for (int t = 0; t < T; ++t) {
            int32_t* row = h_pen + (size_t) t * (size_t) h;
            const int64_t end = std::min<int64_t>(end0 + t, (int64_t) toks.size());
            const int take = (int) std::min<int64_t>(h, std::max<int64_t>(0, end));
            std::fill(row, row + (h - take), -1);
            std::copy(toks.begin() + (end - take), toks.begin() + end, row + (h - take));
        }
        cudaMemcpyAsync(d_pen, h_pen, (size_t) T * (size_t) h * sizeof(int32_t), cudaMemcpyHostToDevice, d.st);
        sp.penalty_last_n = h;
        sp.penalty_repeat = pen_repeat;
        sp.penalty_freq = pen_freq;
        sp.penalty_present = pen_present;
        return d_pen;
    }

    // `hist_end`: the pick's penalty history ends there (toks[0 .. hist_end): the tokens up to its row's position)
    int sample_row(int row, float temperature, float top_p, int top_k, float min_p, uint64_t seed, uint64_t counter,
                   const float* bias, int64_t hist_end) {
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        strata::kernels::SamplerParams sp;
        sp.temperature = temperature;
        sp.greedy = temperature <= 0.0f;
        sp.top_p = top_p;
        sp.top_k = top_k;
        sp.min_p = min_p;
        sp.seed = seed;
        sp.counter = counter;
        sp.logit_bias = bias;
        int h = 0;
        const int* hr = pen_rows(hist_end, 1, sp, h);
        strata::kernels::sample_tokens(d.logits + (size_t) row * g.vocab, 1, g.vocab, hr, h, sp, d.tok, d.st);
        int t = -1;
        cudaMemcpyAsync(&t, d.tok, 4, cudaMemcpyDeviceToHost, d.st);
        cudaStreamSynchronize(d.st);
        return t;
    }

    // [y, drafts] at positions pos ..: the trunk's verdict, its next token, and the state back to what it kept.
    // Greedy: the drafts the trunk's argmax agrees with.  Sampled: the speculative-sampling rule over the request's own
    // chain (top_k, top_p, min_p, temperature): draft d stands with probability min(1, p(d) / q(d)), q the distribution
    // it was drawn from (the drafter's argmax: a point at d, so p(d)), a rejected one is replaced by a draw from the
    // residual max(0, p - q) - so each kept token is distributed as the trunk's own draw.
    bool verify(int y, const std::vector<int>& drafts, float temperature, float top_p, int top_k, float min_p,
                uint64_t seed, uint64_t counter, int& accepted, int& next, std::string& err) {
        const int n = (int) std::min<size_t>(drafts.size(), (size_t) kWin - 1);
        const int T = n + 1, V = g.vocab;
        const int64_t p0 = pos;
        int tk[kWin];
        tk[0] = y;
        for (int i = 0; i < n; ++i) tk[i + 1] = drafts[(size_t) i];
        spec_win = true;
        const double tv = now_ms();
        const bool ok = forward(tk, T, T, err, 0);   // (a window streams nothing - the lane is a decoded token's)
        st.verify_ms += now_ms() - tv;
        spec_win = false;
        if (!ok) return false;
        Dev& hd = devs[(size_t) head_dev];
        cudaSetDevice(hd.id);
        int m = 0;
        // (penalties: row t counts the tokens up to its own position - y and the drafts before it, toks[0 .. p0 + 1 + t))
        if (temperature <= 0.0f) {
            strata::kernels::SamplerParams sp;
            sp.greedy = true;
            sp.temperature = 0.0f;
            int h = 0;
            const int* hr = pen_rows(p0 + 1, T, sp, h);
            strata::kernels::sample_tokens(hd.logits, T, V, hr, h, sp, d_ints + 16, hd.st);   // (the T rows at once)
            CK(cudaMemcpyAsync(h_idx, d_ints + 16, (size_t) T * 4, cudaMemcpyDeviceToHost, hd.st));
            CK(cudaStreamSynchronize(hd.st));
            while (m < n && h_idx[m] == drafts[(size_t) m]) ++m;
            next = h_idx[m];
        } else {
            // row i keeps draft i with probability min(1, p(d) / q(d)), else draws from the residual max(0, p - q)
            // (never d itself): each row a token distributed as the model's own draw at that position, p through the
            // request's chain - the top_k / top_p / min_p cut included (the drafter's argmax can lie outside it: p(d) 0,
            // never kept); past the first rejection the rows do not count
            const bool own = drafts_q && dq_temp == temperature && dq_top_p == top_p && dq_top_k == top_k &&
                             dq_min_p == min_p && dq_seed == seed && dq_counter == counter;
            if (!own) {   // the drafter's argmax: q a point at each draft
                for (int i = 0; i < n; ++i) {
                    h_specq[(size_t) i].n = 1;
                    h_specq[(size_t) i].ids[0] = drafts[(size_t) i];
                    h_specq[(size_t) i].p[0] = 1.0;
                }
                CK(cudaMemcpyAsync(d_specq, h_specq.data(), (size_t) n * sizeof(strata::kernels::SpecList),
                                   cudaMemcpyHostToDevice, hd.st));
            }
            for (int i = 0; i < n; ++i) h_idx[i] = drafts[(size_t) i];
            CK(cudaMemcpyAsync(d_ints + 32, h_idx, (size_t) n * 4, cudaMemcpyHostToDevice, hd.st));
            strata::kernels::SamplerParams sp;
            sp.greedy = false;
            sp.temperature = temperature;
            sp.top_p = top_p;
            sp.top_k = top_k;
            sp.min_p = min_p;
            sp.seed = seed;
            sp.counter = counter;
            int h = 0;
            const int* hr = pen_rows(p0 + 1, n, sp, h);
            strata::kernels::sample_verify(hd.logits, n, V, sp, d_specq, d_ints + 32, d_ints + 16, hd.st, hr, h);
            CK(cudaMemcpyAsync(h_idx, d_ints + 16, (size_t) n * 4, cudaMemcpyDeviceToHost, hd.st));
            CK(cudaStreamSynchronize(hd.st));
            while (m < n && h_idx[m] == drafts[(size_t) m]) ++m;
            next = m < n ? h_idx[m]
                         : sample_row(n, temperature, top_p, top_k, min_p, seed, counter + (uint64_t) n, nullptr,
                                      p0 + 1 + n);
        }
        drafts_q = false;
        rollback(p0, T, m + 1);
        if (!seed_drafter(p0, m + 1, 0, err)) return false;
        accepted = m;
        st.drafts_offered += n;
        st.drafts_accepted += m;
        for (int i = 0; i < n && i <= m && i < 8; ++i) {
            ++st.draft_reached[i];
            if (i < m) ++st.draft_kept[i];
        }
        return true;
    }

    // a verified window keeps its first `keep` positions: the ring rows and the compressors' state of the rest undone
    // (the compressed KV and the index keys past them are written again when those positions come)
    void rollback(int64_t p0, int T, int keep) {
        if (keep >= T) return;
        // the ring rows: one launch a device for all its layers (a launch a layer and member was ~300 on 8-way tensor
        // parallel, a millisecond of the host's before the next draft)
        std::vector<RingBatch> rb(devs.size());
        for (int il = 0; il < g.nl; ++il)
            for (int m = 0; m < L[(size_t) il].nm; ++m) {
                Layer& l = member(L[(size_t) il], m);
                RingBatch& b = rb[(size_t) l.dev];
                if (b.n == kMaxRingBatch) {   // (more layers on a device than a batch takes: this one alone)
                    cudaSetDevice(devs[(size_t) l.dev].id);
                    ring_restore(l.win, l.ring_bak, p0, g.win, keep, T, g.hd, devs[(size_t) l.dev].st);
                    continue;
                }
                b.ring[b.n] = l.win;
                b.bak[b.n++] = l.ring_bak;
            }
        for (size_t di = 0; di < devs.size(); ++di)
            if (rb[di].n > 0) {
                cudaSetDevice(devs[di].id);
                ring_restore_batch(rb[di], p0, g.win, keep, T, g.hd, devs[di].st);
            }
        // the compressors' state: the same, one launch a device (two copies and a launch a layer and member were
        // ~0.3 ms of the host's before the next draft)
        std::vector<CompBatch> cb(devs.size());
        for (int il = 0; il < g.nl; ++il)
            for (int m = 0; m < L[(size_t) il].nm; ++m) {
                Layer& l = member(L[(size_t) il], m);
                Dev& d = devs[(size_t) l.dev];
                if (l.c_snap == nullptr) continue;
                CompBatch& b = cb[(size_t) l.dev];
                if (b.n == kMaxRingBatch) {   // (more than a batch takes: this one alone)
                    cudaSetDevice(d.id);
                    const size_t ns = (size_t) l.ratio * g.hd * 4;
                    cudaMemcpyAsync(l.c_kv, l.c_snap, ns, cudaMemcpyDeviceToDevice, d.st);
                    cudaMemcpyAsync(l.c_score, l.c_snap + (size_t) l.ratio * g.hd, ns, cudaMemcpyDeviceToDevice, d.st);
                    compress_win(l.c_rows, l.c_rows + (size_t) kWin * g.hd, l.c_kv, l.c_score, l.ratio, (int) p0, keep,
                                 g.hd, l.c_norm, g.eps, d.latent, d.st);
                    continue;
                }
                b.kv_state[b.n] = l.c_kv;
                b.score_state[b.n] = l.c_score;
                b.snap[b.n] = l.c_snap;
                b.kv[b.n] = l.c_rows;
                b.score[b.n] = l.c_rows + (size_t) kWin * g.hd;
                b.ratio[b.n++] = l.ratio;
            }
        for (size_t di = 0; di < devs.size(); ++di)
            if (cb[di].n > 0) {
                cudaSetDevice(devs[di].id);
                comp_restore_batch(cb[di], p0, keep, g.hd, devs[di].st);
            }
        pos = p0 + keep;
        toks.resize((size_t) pos);
        ctoks.resize((size_t) pos);
        slot_held = false;
    }

    // ---- a window: T tokens at positions pos .. pos + T - 1 through every layer; the logits of its last `logits` rows
    bool step(int token, bool want_logits, std::string& err) {
        tok_ab_begin();
        const bool ok = forward(&token, 1, want_logits ? 1 : 0, err);
        tok_ab_end(1, ok);
        return ok;
    }


    // DS4_AR2=1 / 2 (0 / unset: off): a group of two's chunk all-reduces - the attention output's and the MoE's - in
    // ar2_kernel: the put and the sums pipelined in pieces, the other member's rows read 16 bytes a lane.  1:
    // ar_sum_kernel's sums bit for bit; 2: FP16 on the wire (both partials rounded, summed in F32 in member order).
    // Decode's all-reduces (G.ar) never take it.  Another value: the load refuses (-1)
    static int ar2() {
        static const int v = [] {
            const char* e = ds4_env("DS4_AR2");
            if (e == nullptr || *e == 0) return 0;
            const int x = std::atoi(e);
            return (x >= 0 && x <= 2 && std::strspn(e, "0123456789") == std::strlen(e)) ? x : -1;
        }();
        return v;
    }
    static bool ar2_decode() {   // (DS4_AR2_DECODE: see the groups' setup)
        static const bool on = [] {
            const char* e = ds4_env("DS4_AR2_DECODE");
            return e != nullptr && std::atoi(e) != 0;
        }();
        return on;
    }
    // a chunk's sum over its group: three members or more through the copy engines (allreduce_dma, c.y its scratch:
    // free between the MoE's sets), or (Group::hred) summed on the host; unless DS4_AR_DMA=0
    void chunk_allreduce(Dev& d, Chunk& c, const ArGroup& ab, int mi, int n, cudaStream_t s) {
        chunk_allreduce_on(d, c, ab, mi, c.acc, n, s, c.ar_aux);
    }
    void chunk_allreduce_on(Dev& d, Chunk& c, const ArGroup& ab, int mi, float* buf, int n, cudaStream_t s,
                            ArAux& aux) {
        static const bool dma = [] {
            const char* e = std::getenv("DS4_AR_DMA");
            return e == nullptr || std::atoi(e) != 0;
        }();
        HostReducer* hr = groups[(size_t) d.grp].hred.get();
        if (dma && hr != nullptr) {   // (the lead submits the sum before its members' copies come)
            const unsigned seq = ++c.arb_seq;
            if (mi == 0) hr->submit(seq, n);
            allreduce_host(buf, n, ab, *hr, mi, seq, c.y, s, aux);
            return;
        }
        if (dma && ab.nm > 2 && ab.sums != nullptr && ab.bflags != nullptr) allreduce_dma(buf, n, ab, mi, ++c.arb_seq, c.y, s, &aux);
        else allreduce(buf, n, ab, mi, ++c.arb_seq, d.xcnt, s);
    }

    // layer L0 for a chunk of T tokens at p0 as group member mi: layer()'s arithmetic over the chunk's rows (the
    // projections as GEMMs, the attention and the indexer in slabs, the routed experts as sorted rows: the VRAM ones in
    // place, the CPU lane's streamed in batches).  kv_only (a long prompt's first pass, Run::stop): only what the layers
    // after it read of these rows - its compressed KV and index keys - and nothing of its own attention or experts
    bool layer_chunk(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, Streamer& S, std::string& err,
                     bool kv_only = false) {
        Layer& l = member(L0, mi);
        Dev& d = devs[(size_t) l.dev];
        Chunk& c = *chunks[(size_t) l.dev];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        prof_mark(d, 0);
        const int nm = L0.nm;
        const int D = g.dim, H = g.hc, HD = g.hd, NHL = l.ahn, HQ = NHL * HD, OG = l.ogn, FF = l.ffn;
        const ArGroup& ab = groups[(size_t) L0.grp].arb;
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        // Engram, in slabs of 256 tokens
        if (l.eg >= 0) {
            const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
            const size_t per = (size_t) cols * (ehd + ehd / 32);
            const int slot = wp.eg_slot >= 0 ? wp.eg_slot : wp.k % 2;   // (read ahead by the run: two in flight)
            uint8_t* host = chunks[(size_t) eg_src_dev(l.dev)]->eg_host[slot] + (size_t) l.eg * c.C * per;
            CK(cudaMemcpyAsync(c.eg_rows, host, (size_t) T * per, cudaMemcpyHostToDevice, s));
            CK(cudaEventRecord(c.eg_ev[slot], s));
            for (int s0 = 0; s0 < T; s0 += 256) {
                const int ns = std::min(256, T - s0);
                engram_dequant_tok(c.eg_rows + (size_t) s0 * per, per, cols, ns, ehd, c.eg_x, s, (int) eg_q6k[(size_t) l.eg]);
                x3::rows_f16(c.eg_x, cols * ehd, nullptr, ns, cols * ehd, c.eg_x16, s);
                if (!gemm(d, c, l.eg_wkv, c.eg_x16, cols * ehd, ns, c.eg_kv, (H + 1) * D, 0.0f, err)) return false;
                engram_gate(c.h + (size_t) s0 * H * D, c.eg_kv, l.eg_w, H, D, ns, g.eps, s);
            }
        }
        // attention
        if (!hc_mix_chunk(d, c, c.h, l.hca_fn, T, c.mix, err)) return false;
        hc_split(c.mix, l.hca_scale, l.hca_base, H, g.sinkhorn, g.hc_eps, T, c.a_pre, c.a_post, c.a_comb, s);
        hc_pre_norm(c.h, c.pre, l.attn_norm, D, H, T, g.eps, c.x, s);
        x3::rows_f16(c.x, D, nullptr, T, D, c.x16, s);
        if (!kv_only && (!gemm(d, c, l.wq_a, c.x16, D, T, c.qr, g.q_lora, 0.0f, err) ||
                         !gemm(d, c, l.wkv, c.x16, D, T, c.kvr, HD, 0.0f, err)))
            return false;
        if (l.kv_src && !gemm(d, c, l.c_wkv, c.x16, D, T, c.ckr, HD, 0.0f, err)) return false;
        if (l.kv_src && l.ratio > 1 && !gemm(d, c, l.c_wgate, c.x16, D, T, c.cgr, HD, 0.0f, err)) return false;
        prof_mark(d, 4);
        const bool snap = !kv_only && wp.snap_t >= 0 && mi == 0 && L0.snap_win != nullptr;
        if (!kv_only) {
            Finish fq;
            fq.w = l.q_norm;
            fq.eps = g.eps;
            finish(c.qr, T, g.q_lora, g.q_lora, fq, s);
            x3::rows_f16(c.qr, g.q_lora, nullptr, T, g.q_lora, c.qr16, s);
            // the window rows: the ring's (positions p0 - win ..) then the chunk's
            ring_to_ext(l.win, c.ext, p0, g.win, HD, s);
            Finish fk;
            fk.w = l.kv_norm;
            fk.eps = g.eps;
            fk.rd = g.rd;
            fk.pos = (int) p0;
            fk.freqs = freqs;
            fk.quant = 1;
            fk.dst = c.ext + (size_t) g.win * HD;
            fk.dst_stride = HD;
            finish(c.kvr, T, HD, HD, fk, s);
            // feed_mark's checkpoint: the ring as it was before row snap_t - the old ring, then the chunk's rows before it
            if (snap) {
                CK(cudaMemcpyAsync(L0.snap_win, l.win, (size_t) g.win * win_rb(), cudaMemcpyDeviceToDevice, s));
                if (wp.snap_t > 0) ext_to_ring(c.ext, L0.snap_win, p0, g.win, wp.snap_t, HD, s, nullptr);
            }
            ext_to_ring(c.ext, l.win, p0, g.win, T, HD, s, nullptr);
        }
        const uint8_t* ckv = nullptr;
        const long long ss = (long long) o.max_context + 64;
        if (l.ratio > 0) {
            Src& sr = srcs[(size_t) l.src];
            const int R = l.ratio;
            const int64_t g_first = p0 / R, g_end = (p0 + T) / R;
            const int ng = (int) std::max<int64_t>(0, g_end - g_first);
            const float* latent = c.latent;
            if (l.kv_src) {
                if (R == 1) {
                    Finish fc;
                    fc.w = l.c_norm;
                    fc.eps = g.eps;
                    finish(c.ckr, T, HD, HD, fc, s);
                    latent = c.ckr;
                } else {
                    if (snap && L0.snap_kv != nullptr) {   // (each slot: the latest row before snap_t that holds it)
                        const int64_t ps = p0 + wp.snap_t;
                        for (int sl = 0; sl < R; ++sl) {
                            const int64_t q = ps - 1 - (((ps - 1 - sl) % R) + R) % R;
                            const float* kv = q >= p0 ? c.ckr + (size_t) (q - p0) * HD : l.c_kv + (size_t) sl * HD;
                            const float* sc = q >= p0 ? c.cgr + (size_t) (q - p0) * HD : l.c_score + (size_t) sl * HD;
                            CK(cudaMemcpyAsync(L0.snap_kv + (size_t) sl * HD, kv, (size_t) HD * 4, cudaMemcpyDeviceToDevice, s));
                            CK(cudaMemcpyAsync(L0.snap_sc + (size_t) sl * HD, sc, (size_t) HD * 4, cudaMemcpyDeviceToDevice, s));
                        }
                    }
                    compress_win(c.ckr, c.cgr, l.c_kv, l.c_score, R, (int) p0, T, HD, l.c_norm, g.eps, c.latent, s);
                }
            }
            const int clen_max = (int) ((p0 + T) / R);
            if (l.ix_src) {
                Src& ks = srcs[(size_t) l.ik_src];
                if (l.owns_k && ng > 0) {
                    x3::rows_f16(latent, HD, nullptr, ng, HD, c.lat16, s);
                    if (!gemm(d, c, l.i_wk, c.lat16, HD, ng, c.ikr, g.ix_hd, 0.0f, err)) return false;
                    Finish fi;
                    fi.w = l.ik_norm;
                    fi.eps = g.eps;
                    fi.rd = g.rd;
                    fi.pos = (int) (g_first * R);
                    fi.pos_step = R;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    fi.pdst = ks.ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                    fi.pdst_stride = (long long) ik_rb();
                    finish(c.ikr, ng, g.ix_hd, g.ix_hd, fi, s);
                }
                if (clen_max > 0 && !kv_only) {
                    if (!gemm_f16w(c, l.i_wproj, g.ix_heads, D, c.x16, D, T,
                                   1.0f / std::sqrt((float) g.ix_hd) / std::sqrt((float) g.ix_heads), c.iw, 64, err))
                        return false;
                    for (int a0 = 0; a0 < T; a0 += c.AI) {
                        const int na = std::min(c.AI, T - a0);
                        const int64_t pa = p0 + a0;
                        if (!gemm(d, c, l.i_wq_b, c.qr16 + (size_t) a0 * g.q_lora, g.q_lora, na, c.iq,
                                  g.ix_heads * g.ix_hd, 0.0f, err))
                            return false;
                        Finish fi;
                        fi.rd = g.rd;
                        fi.pos = (int) pa;
                        fi.vpp = g.ix_heads;
                        fi.freqs = freqs;
                        fi.quant = 3;
                        finish(c.iq, na * g.ix_heads, g.ix_hd, g.ix_hd, fi, s);
                        Rows lim;
                        lim.gen = 1;
                        lim.p0 = pa;
                        lim.R = R;
                        lim.kcap = g.ix_topk;
                        lim.ccap = g.cand_topk;
                        lim.blk = std::max(1, g.cand_blk);
                        const int nlast = (int) ((pa + na) / R);   // the slab's widest query
                        int* tk = c.topk + (size_t) a0 * topk_stride();
                        int* cd = c.cand + (size_t) a0 * cand_stride();
                        const float* iw = c.iw + (size_t) a0 * 64;
                        if (nlast <= 0) continue;
                        if (l.uses_cand && (nlast + g.cand_blk - 1) / g.cand_blk > g.cand_topk) {
                            Rows cl = lim;
                            cl.gen = 2;
                            index_score(c.iq, iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, na, g.cand_topk * g.cand_blk,
                                        cd, (int) cand_stride(), g.cand_blk, cl, c.scores, ss, s);
                            Rows tr = lim;
                            tr.gen = 3;
                            topk(c.scores, ss, na, tr, cd, (int) cand_stride(), g.cand_blk, tk, (int) topk_stride(), s);
                        } else {
                            index_score(c.iq, iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, na, nlast, nullptr, 0, 1,
                                        lim, c.scores, ss, s);
                            if (l.cand_src) {
                                Rows cr = lim;
                                cr.kcap = g.cand_topk;
                                cand_blocks(c.scores, ss, na, cr, g.cand_blk, c.bm, (long long) bm_stride(), cd,
                                            (int) cand_stride(), s);
                            }
                            topk(c.scores, ss, na, lim, nullptr, 0, 1, tk, (int) topk_stride(), s);
                        }
                    }
                }
            }
            if (l.kv_src && ng > 0) {
                Finish fc;
                fc.rd = g.rd;
                fc.pos = (int) (g_first * R);
                fc.pos_step = R;
                fc.freqs = freqs;
                fc.quant = 2;
                fc.pdst = sr.ckv[(size_t) l.dev] + (size_t) g_first * ckv_rb();
                fc.pdst_stride = (long long) ckv_rb();
                finish(const_cast<float*>(latent), ng, HD, HD, fc, s);
                if (mi == 0 && sr.remote) {   // the new rows for the other groups' readers (slot k % 2, once
                    const int slot = wp.k % 2;  // they took the chunk before last's)
                    if (wp.k >= 2)
                        for (int r : sr.readers) wait_flags(sr.x_ack + ((size_t) slot * devs.size() + r) * 32, 1, 32, wp.win - 2, s);
                    Xfer x;
                    x.src[0] = fc.pdst;
                    x.dst[0] = sr.stage(slot);
                    x.bytes[0] = (size_t) ng * ckv_rb();
                    x.n = 1;
                    if (l.owns_k && srcs[(size_t) l.ik_src].ik[(size_t) l.dev] != nullptr) {
                        x.src[1] = srcs[(size_t) l.ik_src].ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                        x.dst[1] = sr.stage(slot) + x_cap() * ckv_rb();
                        x.bytes[1] = (size_t) ng * ik_rb();
                        x.n = 2;
                    }
                    xfer_put(x, sr.flag(slot), wp.win, d.xcnt, s);
                }
            }
            ckv = sr.ckv[(size_t) l.dev];
        }
        prof_mark(d, 5);
        if (kv_only) {   // (DS4_PROF: its time the attention's - it ends where the attention would start)
            prof_mark(d, 1);
            return true;
        }
        // the attention in slabs: q, the sparse attention, wo_a, wo_b (this member's share) into acc; with three
        // members or more each slab's sum on ar_s while the next slab computes (every member the same slabs: c.A
        // is the group's, a member without heads its zeros)
        static const bool overlap = [] {
            const char* e = std::getenv("DS4_AR_OVERLAP");
            return e == nullptr || std::atoi(e) != 0;
        }();
        const bool slab_ar = overlap && nm > 2 && c.ar_s != nullptr;
        if (NHL == 0 && !slab_ar) CK(cudaMemsetAsync(c.acc, 0, (size_t) T * D * sizeof(*c.acc), s));   // (no heads)
        for (int a0 = 0; a0 < T && (NHL > 0 || slab_ar); a0 += c.A) {
            const int na = std::min(c.A, T - a0);
            if (NHL == 0) {
                CK(cudaMemsetAsync(c.acc + (size_t) a0 * D, 0, (size_t) na * D * sizeof(*c.acc), s));
                CK(cudaEventRecord(c.ar_go, s));
                CK(cudaStreamWaitEvent(c.ar_s, c.ar_go, 0));
                chunk_allreduce_on(d, c, ab, mi, c.acc + (size_t) a0 * D, na * D, c.ar_s, c.ar_aux2);
                continue;
            }
            if (!gemm(d, c, l.wq_b, c.qr16 + (size_t) a0 * g.q_lora, g.q_lora, na, c.q, HQ, 0.0f, err)) return false;
            Finish fr;
            fr.rd = g.rd;
            fr.pos = (int) (p0 + a0);
            fr.vpp = NHL;
            fr.freqs = freqs;
            finish(c.q, na * NHL, HD, HD, fr, s);
            prof_mark(d, 6);
            AttnRows ar;
            ar.gen = 1;
            ar.p0 = p0;
            ar.t0 = a0;
            ar.win = g.win;
            ar.R = l.ratio;
            ar.kcap = g.ix_topk;
            sparse_attn(c.q, c.ext, ckv, c.topk + (size_t) a0 * topk_stride(), (int) topk_stride(), ar, l.sink, NHL, HD,
                        na, 1.0f / std::sqrt((float) HD), c.o, s, kKvFp4, na > kAttnScratchT ? kAttnWmma : 0,
                        &d.attn_scr);   // (a short last slab: the scratch)
            prof_mark(d, 7);
            Finish fo;
            fo.rd = g.rd;
            fo.pos = (int) (p0 + a0);
            fo.vpp = NHL;
            fo.freqs = freqs;
            fo.inverse = 1;
            fo.quant = 1;
            fo.dst = c.o16;   // (straight to the FP16 rows wo_a reads - rows_f16's rounding of the same values: one pass
            fo.dst_stride = HD;   // over the slab's 2048 x 32768 outputs, not three)
            fo.dst_f16 = 1;
            finish(c.o, na * NHL, HD, HD, fo, s);
            const int per = HQ / OG;
            for (int gi = 0; gi < OG; ++gi)
                if (!gemm(d, c, l.wo_a[gi], c.o16 + (size_t) gi * per, HQ, na, c.oa + (size_t) gi * g.o_lora,
                          OG * g.o_lora, 0.0f, err))
                    return false;
            x3::rows_f16(c.oa, OG * g.o_lora, nullptr, na, OG * g.o_lora, c.oa16, s);
            if (!gemm(d, c, l.wo_b, c.oa16, OG * g.o_lora, na, c.acc + (size_t) a0 * D, D, 0.0f, err)) return false;
            prof_mark(d, 1);
            if (slab_ar) {
                CK(cudaEventRecord(c.ar_go, s));
                CK(cudaStreamWaitEvent(c.ar_s, c.ar_go, 0));
                chunk_allreduce_on(d, c, ab, mi, c.acc + (size_t) a0 * D, na * D, c.ar_s, c.ar_aux2);
            }
        }
        if (slab_ar) {   // (the residual and the MoE after every slab's sum)
            CK(cudaEventRecord(c.ar_done, c.ar_s));
            CK(cudaStreamWaitEvent(s, c.ar_done, 0));
        } else if (nm > 1)
            chunk_allreduce(d, c, ab, mi, T * D, s);
        ablate(d, c.acc, T, s);
        hc_post_inplace(c.acc, c.h, c.a_post, c.a_comb, D, H, T, s);
        prof_mark(d, 1);
        kick(s);   // (the attention submitted while the host queues the routing)
        // the MoE
        if (!hc_mix_chunk(d, c, c.h, l.hcf_fn, T, c.mix, err)) return false;
        hc_split(c.mix, l.hcf_scale, l.hcf_base, H, g.sinkhorn, g.hc_eps, T, c.f_pre, c.f_post, c.f_comb, s);
        hc_pre_norm(c.h, c.a_pre, l.ffn_norm, D, H, T, g.eps, c.x, s);
        x3::rows_f16(c.x, D, nullptr, T, D, c.x16, s);
        gemv_f32(l.gate_w, c.x, l.n_exp, D, T, c.glog, 1024, s);   // (F32 x: the token path's bits)
        for (int r0 = 0; r0 < T; r0 += kVlRows) {   // (route()'s image bits cover kVlRows rows a call)
            const int nr = std::min(kVlRows, T - r0);
            VlBits vb;
            const bool vl = l.gate_bias_vl != nullptr && vl_bits(p0 + r0, nr, vb);
            route(c.glog + (size_t) r0 * 1024, l.gate_bias, l.n_exp, l.k_exp, nr, g.route_scale,
                  c.ridx + (size_t) r0 * kPicks, c.rw + (size_t) r0 * kPicks, s, l.gate_bias_vl, vl ? &vb : nullptr);
        }
        const int n_vs = L0.pv_n + (int) L0.host_list.size();
        CK(cudaMemcpyAsync(l.vs_dev, l.vs_pin, (size_t) l.n_exp * 4, cudaMemcpyHostToDevice, s));   // (this member's)
        moe_sort(c.ridx, T, l.k_exp, l.vs_dev, n_vs, c.bounds, c.row_tok, c.pos, s);
        CK(cudaMemcpyAsync(c.bounds_pin, c.bounds, (size_t) (n_vs + 1) * 4, cudaMemcpyDeviceToHost, s));
        // the shared expert into acc while the host waits for the bounds
        if (!gemm(d, c, l.s1, c.x16, D, T, c.sg, FF, 0.0f, err) || !gemm(d, c, l.s3, c.x16, D, T, c.su, FF, 0.0f, err))
            return false;
        swiglu(c.sg, c.su, T * FF, g.lim, c.sg, s);
        x3::rows_f16(c.sg, FF, nullptr, T, FF, c.sh16, s);
        if (!gemm(d, c, l.s2, c.sh16, FF, T, c.acc, D, 0.0f, err)) return false;
        prof_mark(d, 2);
        // the expert stream's copies keep going while the device runs this layer's attention, routing and shared
        // expert: the next items (this layer's likely experts, queued when the layer before routed) go out as they
        // are ready and ring slots free, not only once the bounds are back (DS4_FLOW_PUMP_WAIT=0: wait as before)
        static const bool pump_wait = std::getenv("DS4_FLOW_PUMP_WAIT") == nullptr ||
                                      std::atoi(std::getenv("DS4_FLOW_PUMP_WAIT")) != 0;
        if (c.flow && pump_wait)
            while (cudaStreamQuery(s) == cudaErrorNotReady) {
                if (!flow_pump(c, err)) return false;
                std::this_thread::yield();
            }
        CK(cudaStreamSynchronize(s));
        std::vector<int> b(c.bounds_pin, c.bounds_pin + n_vs + 1);
        // pv_n is this run's resident prefix: slots lent to buffers are streamed, not hits.
        if (S.collect_prefill && !S.prefill.add_bounds(b.data(), (size_t) n_vs, (size_t) L0.pv_n)) {
            err = "invalid prefill routing bounds for statistics";
            return false;
        }
        if (dump_r != nullptr && mi == 0) {
            const size_t nk = (size_t) T * l.k_exp, np = (size_t) T * kPicks;
            std::vector<int> ri(np), rt(nk);
            std::vector<float> gl((size_t) T * l.n_exp), gb((size_t) l.n_exp);
            CK(cudaMemcpy(ri.data(), c.ridx, np * 4, cudaMemcpyDeviceToHost));
            CK(cudaMemcpy(rt.data(), c.row_tok, nk * 4, cudaMemcpyDeviceToHost));
            CK(cudaMemcpy2D(gl.data(), (size_t) l.n_exp * 4, c.glog, 1024 * 4, (size_t) l.n_exp * 4, (size_t) T,
                            cudaMemcpyDeviceToHost));
            CK(cudaMemcpy(gb.data(), l.gate_bias, gb.size() * 4, cudaMemcpyDeviceToHost));
            std::lock_guard<std::mutex> lk(dump_mu);
            const int64_t hdr[8] = {l.il, p0, T, l.k_exp, l.n_exp, n_vs, L0.pv_n, kPicks};
            std::fwrite(hdr, 8, 8, dump_r);
            std::fwrite(ri.data(), 4, np, dump_r);
            std::fwrite(L0.vs_pin, 4, (size_t) l.n_exp, dump_r);
            std::fwrite(b.data(), 4, b.size(), dump_r);
            std::fwrite(rt.data(), 4, nk, dump_r);
            std::fwrite(gl.data(), 4, gl.size(), dump_r);
            std::fwrite(gb.data(), 4, gb.size(), dump_r);
            std::fflush(dump_r);
        }
        if (mi == 0) {   // the profile (the CPU lane's experts: by the plan's order)
            uint32_t* pr = prof.data() + (size_t) l.il * g.n_exp;
            for (int e = 0; e < l.n_exp; ++e) {
                const int v = L0.vs_pin[e];
                pr[e] += (uint32_t) (b[(size_t) v + 1] - b[(size_t) v]);
            }
            st.experts += (int64_t) T * l.k_exp;
            if (c.flow && wp.k + 1 == (int) c.fl_T.size()) {   // (a run's last chunk: its last rows' picks, warm_after)
                const int w = std::min(T, kWarmRows);
                L0.last_picks.resize((size_t) w * kPicks);
                CK(cudaMemcpy(L0.last_picks.data(), c.ridx + (size_t) (T - w) * kPicks, L0.last_picks.size() * 4,
                              cudaMemcpyDeviceToHost));
            }
        }
        if (c.flow) {
            if (!flow_layer(d, c, L0, mi, wp.k, T, b, err)) return false;
            if (nm > 1) allreduce(c.acc, T * D, ab, mi, ++c.arb_seq, d.xcnt, s);
            ablate(d, c.acc, T, s);
            hc_post_inplace(c.acc, c.h, c.f_post, c.f_comb, D, H, T, s);
            CK(cudaMemcpyAsync(c.pre, c.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));
            prof_mark(d, 3);
            kick(s);
            return true;
        }
        // the streamed experts as their batches arrive (each batch's slots freed for the copies at once), the VRAM ones
        // in shares between them (the device works while the copies run)
        const int di = l.dev, P = Chunk::kParts;
#if defined(STRATA_USE_HIP)
        if (std::getenv("DS4_SKIP_UNPICKED") != nullptr && std::atoi(std::getenv("DS4_SKIP_UNPICKED")) != 0) {
            S.routed_layer = L0.il;
            S.routed_chunk = wp.k;
            S.routed_bounds = b;
            if (!copy_ahead(d, c, S, di, err)) return false;
        }
#endif
        int nb = 0;
        for (size_t q = S.kp; q < S.b.size() && S.b[q].il == L0.il && S.b[q].k == wp.k; ++q) ++nb;
        int v_done = 0;
        for (int bi = 0; bi < nb; ++bi) {
            const Batch& bt = S.b[S.kp];
            const int half = (int) (S.kp % P);
            CK(cudaStreamWaitEvent(s, c.filled[half], 0));
            const int v0 = L0.pv_n + bt.j0;
            if (!run_set(d, c, l, c.ring + (size_t) half * (c.ring_n / P) * c.ring_stride, v0, c.ring_stride, c.bounds,
                         b.data(), v0, v0 + bt.n, T, err))
                return false;
            CK(cudaEventRecord(c.freed[half], s));
            ++S.kp;
            if (!copy_ahead(d, c, S, di, err)) return false;
            const int v_to = (int) ((int64_t) L0.pv_n * (bi + 1) / nb);
            if (!run_vram(d, c, L0, l, l, b.data(), v_done, v_to, T, err)) return false;
            v_done = v_to;
        }
        if (!run_vram(d, c, L0, l, l, b.data(), v_done, L0.pv_n, T, err)) return false;
        if (nm > 1) chunk_allreduce(d, c, ab, mi, T * D, s);
        ablate(d, c.acc, T, s);
        hc_post_inplace(c.acc, c.h, c.f_post, c.f_comb, D, H, T, s);
        CK(cudaMemcpyAsync(c.pre, c.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));
        prof_mark(d, 3);
        kick(s);   // (Windows HIP: the experts and the layer's end submitted now, not at the next layer's wait)
        return true;
    }

    // the CPU lane's experts of every layer, in index order, and each expert's virtual slot (before a chunk)
    void plan_streams() {
        for (Layer& l : L) {
            if (l.mtp || l.vs_pin == nullptr) continue;
            l.host_list.clear();
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] < 0 || l.slot[(size_t) e] >= l.pv_n) l.host_list.push_back(e);
            for (int m = 0; m < l.nm; ++m) {   // (a group's members: each its own copy)
                Layer& x = member(l, m);
                int j = 0;
                for (int e = 0; e < l.n_exp; ++e)
                    x.vs_pin[e] = l.slot[(size_t) e] >= 0 && l.slot[(size_t) e] < l.pv_n ? l.slot[(size_t) e] : l.pv_n + j++;
            }
        }
    }

    // a chunk's hand-off between groups: h | pre | topk | cand of a chunk of T rows
    Xfer chunk_xfer(uint8_t* host, Chunk& c, int T, bool put) const {
        const size_t nh = (size_t) T * g.hc * g.dim * 4, np = (size_t) T * 8 * 4, nk = (size_t) T * topk_stride() * 4,
                     nc = (size_t) T * cand_stride() * 4;
        void* dv[4] = {c.h, c.pre, c.topk, c.cand};
        uint8_t* hv[4] = {host, host + nh, host + nh + np, host + nh + np + nk};
        const size_t nb[4] = {nh, np, nk, nc};
        Xfer x;
        x.n = 4;
        for (int i = 0; i < 4; ++i) {
            x.src[i] = put ? (const void*) dv[i] : (const void*) hv[i];
            x.dst[i] = put ? (void*) hv[i] : dv[i];
            x.bytes[i] = nb[i];
        }
        return x;
    }

    // a run of chunks (start positions p0[k], sizes T[k], seqs seq[k]) on device di: its layers chunk after chunk, the
    // groups pipelined (a group takes chunk k + 1 while the next takes chunk k: the hand-offs and the sources' rows
    // two deep, each slot reused once its readers acknowledged it), the streamed experts' copies running ahead across
    // layers and chunks
    struct Run {
        std::vector<int64_t> p0;
        std::vector<int> T;
        std::vector<unsigned> seq;
        int64_t snap_pos = -1;   // feed_mark: the position whose state before it the layers keep (-1: none)
        // a long prompt's skip (forward_chunks): the cut at row cut_r of chunk cut_k - the chunks before it go through
        // the layers before `yoco`, that layer as layer_chunk's kv_only and none after it; chunk cut_k's rows before
        // cut_r the same, its rows from cut_r on and the chunks after it through every layer (yoco -1: no skip)
        int yoco = -1, cut_k = 0, cut_r = 0;
        bool runs(int k, int il) const { return yoco < 0 || k >= cut_k || il <= yoco; }
        bool kv_only(int k, int il) const { return yoco >= 0 && k < cut_k && il == yoco; }
        int r0(int k, int il) const { return yoco >= 0 && k == cut_k && il >= yoco ? cut_r : 0; }   // the first row
    };
    // Whole-prompt Engram read-ahead: fill the ordinary row cache in consumption order, independently of the two
    // pinned staging slots.  A consumer waits for its unit before doing the normal lookup/copy, so no row is read by
    // the prefetcher and the normal path at once.  The worker never outlives forward_chunks' tokens or image state.
    struct EgPrefetch {
        Impl* p;
        const Run& run;
        std::vector<std::pair<int, int>> units;
        std::vector<char> ready;
        std::vector<int> seen;
        bool lm;
        int ahead;
        int seen_chunk = -1;
        std::mutex mu;
        std::condition_variable cv;
        std::atomic<bool> stop{false};
        bool done = false;
        std::thread worker;
        EgPrefetch(Impl* p, const Run& run, std::vector<std::pair<int, int>> units, bool lm, int ahead)
            : p(p), run(run), units(std::move(units)), ready(this->units.size(), 0),
              seen((size_t) p->pk.eg_layers, -1), lm(lm), ahead(ahead) {}
        ~EgPrefetch() {
            stop.store(true, std::memory_order_release);
            cv.notify_all();
            if (worker.joinable()) worker.join();
            if (p->eg_pf == this) p->eg_pf = nullptr;
        }
        void start() { worker = std::thread([this] { work(); }); }
        void wake() { cv.notify_all(); }   // halt/eg_abort are set by other threads, not through this prefetcher
        void work() {
            const size_t per = (size_t) (p->pk.eg_ngram - 1) * p->pk.eg_heads * (p->pk.eg_hd + p->pk.eg_hd / 32);
            size_t zone = std::getenv("DS4_EG_ZONE_KB") ? (size_t) std::max(0, std::atoi(std::getenv("DS4_EG_ZONE_KB"))) << 10 : 0;
            auto publish = [&](size_t u) {
                {
                    std::lock_guard<std::mutex> lk(mu);
                    ready[u] = 1;
                }
                cv.notify_all();
            };
            auto gate = [&](int li, int start) {
                if (start == 0) return;
                std::unique_lock<std::mutex> lk(mu);
                cv.wait(lk, [&] {
                    const int seen_at = li >= 0 ? seen[(size_t) li] : seen_chunk;
                    return seen_at >= start - ahead || stop.load(std::memory_order_acquire) ||
                           p->halt.load(std::memory_order_acquire) || p->eg_abort.load(std::memory_order_acquire);
                });
            };
            if (zone) {
                std::vector<int> lis;
                for (const auto& unit : units)
                    if (std::find(lis.begin(), lis.end(), unit.first) == lis.end()) lis.push_back(unit.first);
                for (int li : lis) {
                    size_t count = 0;
                    for (const auto& unit : units) count += unit.first == li;
                    if (count != run.T.size()) {
                        zone = 0;
                        break;
                    }
                }
                auto load = [&](int li, int start) {
                    const int end = std::min((int) run.T.size(), start + ahead);
                    int total = 0;
                    for (int k = start; k < end; ++k) total += run.T[(size_t) k];
                    std::vector<uint8_t> scratch((size_t) total * per);
                    EgBatch b;
                    static const bool profile = std::getenv("DS4_EG_PROFILE") != nullptr;
                    const double t0 = now_ms();
                    p->eg_issue(run.p0[(size_t) start], total, li, scratch.data(), b, false, false, true);
                    const double t1 = now_ms();
                    p->eg_io.submit_zones(b, zone);
                    const double t2 = now_ms();
                    p->eg_finish(b, false);
                    if (profile)
                        std::fprintf(stderr, "ds4: Engram window: layer %d, chunk %d, %d tokens: generate %.1f ms, plan %.1f ms, read/cache %.1f ms\n",
                                     li, start, total, t1 - t0, t2 - t1, now_ms() - t2);
                    for (size_t u = 0; u < units.size(); ++u)
                        if (units[u].first == li && units[u].second >= start && units[u].second < end) publish(u);
                };
                if (lm) {
                    for (int li : lis)
                        for (int start = 0; start < (int) run.T.size() && zone; start += ahead) {
                            gate(li, start);
                            if (stop.load(std::memory_order_acquire) || p->halt.load(std::memory_order_acquire) ||
                                p->eg_abort.load(std::memory_order_acquire)) break;
                            load(li, start);
                        }
                } else {
                    for (int start = 0; start < (int) run.T.size() && zone; start += ahead) {
                        gate(-1, start);
                        if (stop.load(std::memory_order_acquire) || p->halt.load(std::memory_order_acquire) ||
                            p->eg_abort.load(std::memory_order_acquire)) break;
                        for (int li : lis) load(li, start);
                    }
                }
                if (zone) {
                    std::lock_guard<std::mutex> lk(mu);
                    done = true;
                    cv.notify_all();
                    return;
                }
            }
            std::vector<uint8_t> scratch;
            for (size_t u = 0; u < units.size(); ++u) {
                const int li = units[u].first, k = units[u].second;
                gate(lm ? li : -1, k);
                if (stop.load(std::memory_order_acquire) || p->halt.load(std::memory_order_acquire) ||
                    p->eg_abort.load(std::memory_order_acquire)) break;
                scratch.resize((size_t) run.T[(size_t) k] * per);
                p->engram_rows(run.p0[(size_t) k], run.T[(size_t) k], li, scratch.data(), false);
                publish(u);
            }
            {
                std::lock_guard<std::mutex> lk(mu);
                done = true;
            }
            cv.notify_all();
        }
        void wait_unit(int li, int k) {
            size_t u = 0;
            while (u < units.size() && (units[u].first != li || units[u].second != k)) ++u;
            if (u == units.size()) return;
            std::unique_lock<std::mutex> lk(mu);
            cv.wait(lk, [&] { return ready[u] || done || stop.load(std::memory_order_acquire); });
        }
        void finish_unit(int li, int k) {
            {
                std::lock_guard<std::mutex> lk(mu);
                seen[(size_t) li] = std::max(seen[(size_t) li], k);
            }
            cv.notify_all();
        }
        void finish_chunk(int k) {
            {
                std::lock_guard<std::mutex> lk(mu);
                seen_chunk = std::max(seen_chunk, k);
            }
            cv.notify_all();
        }
    };
    // topk's segments (TopkScratch): for a verify window's rows (a drafter's block and its token: 6; wider windows, a
    // prompt's 16, take topk_kernel), as many a row as the longest row needs - 0.5 MB a device at 256K
    static constexpr size_t kTksRows = 8;
    size_t tks_p() const {
        return (size_t) std::max(2, std::min(kTopkSegMax, (int) ((o.max_context + kTopkSeg - 1) / kTopkSeg)));
    }
    // layer L0 over chunk k per a long prompt's skip (Run): its kv_only, or its rows from Run::r0 on - the chunk's
    // buffers seen from that row (the yoco layer: its kv_only over the rows before it first)
    bool run_layer(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, Streamer& S, std::string& err,
                   const Run& run, int k, int il) {
        if (run.kv_only(k, il)) return layer_chunk(L0, mi, p0, T, wp, S, err, true);
        const int r0 = run.r0(k, il);
        if (r0 <= 0) return layer_chunk(L0, mi, p0, T, wp, S, err);
        if (il == run.yoco) {
            WinPlan w0 = wp;
            w0.snap_t = -1;
            if (!layer_chunk(L0, mi, p0, r0, w0, S, err, true)) return false;
        }
        Chunk& c = *chunks[(size_t) member(L0, mi).dev];
        float* const h0 = c.h;
        float* const pre0 = c.pre;
        c.h += (size_t) r0 * g.hc * g.dim;
        c.pre += (size_t) r0 * 8;
        WinPlan w1 = wp;
        w1.snap_t = wp.snap_t >= r0 ? wp.snap_t - r0 : -1;
        const bool ok = layer_chunk(L0, mi, p0 + r0, T - r0, w1, S, err);
        c.h = h0;
        c.pre = pre0;
        return ok;
    }

    // layer-major (c.lm: a run of several chunks, device di every trunk layer, the flow set up by run_dev_chunks):
    // layer after layer, each through all the chunks in order - a chunk's state to host memory after each of its
    // layers and back before the next - so a layer's experts are read from the files once for the whole run (the
    // layer cache keeps what a chunk read for the chunks after it), where chunk after chunk reads them once a chunk
    bool run_dev_layers(int di, const Run& run, std::string& err, double stream_start) {
        Dev& d = devs[(size_t) di];
        Chunk& c = *chunks[(size_t) di];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int D = g.dim, H = g.hc, nk = (int) run.T.size();
        Streamer S;   // (none: the flow streams)
        const size_t hb = chunk_hand_bytes();
        // the Engram rows: (layer, chunk) after (layer, chunk) in the run's order, each read on a helper thread while
        // the one before runs (slot u % 2, once unit u - 2's copy of it is done)
        std::vector<std::pair<int, int>> egu;   // (Engram layer, chunk)
        for (int il : c.fl_layers)
            if (L[(size_t) il].eg >= 0)
                for (int k = 0; k < nk; ++k)
                    if (run.runs(k, il)) egu.push_back({L[(size_t) il].eg, k});
        const size_t eg_per = (size_t) (pk.eg_ngram - 1) * pk.eg_heads * (pk.eg_hd + pk.eg_hd / 32);
        auto read_eg = [this, &c, &run, &egu, eg_per](size_t u) {
            if (u >= 2) cudaEventSynchronize(c.eg_ev[u % 2]);
            const int li = egu[u].first, k = egu[u].second;
            if (eg_pf != nullptr) eg_pf->wait_unit(li, k);
            engram_rows(run.p0[(size_t) k], run.T[(size_t) k], li, c.eg_host[u % 2] + (size_t) li * c.C * eg_per);
            if (eg_pf != nullptr) eg_pf->finish_unit(li, k);
        };
        size_t eg_u = 0;
        std::future<void> eg_next;
        if (!egu.empty()) eg_next = std::async(std::launch::async, read_eg, (size_t) 0);
        for (size_t li = 0; li < c.fl_layers.size(); ++li) {
            const int il = c.fl_layers[li];
            Layer& L0 = L[(size_t) il];
            const bool last_l = li + 1 == c.fl_layers.size();
            for (int k = 0; k < nk; ++k) {
                if (!run.runs(k, il)) continue;   // (a skipped early chunk: nothing after the yoco layer)
                if (halt_now()) return halt_end(di, err);   // (a Stop: one GPU, this one)
                const int64_t p0 = run.p0[(size_t) k];
                const int T = run.T[(size_t) k], slot = k % 2;
                const bool last_k = k + 1 == nk;
                WinPlan wp;
                wp.par = true;
                wp.async = true;
                wp.win = run.seq[(size_t) k];
                wp.k = k;
                wp.snap_t = run.snap_pos >= p0 && run.snap_pos < p0 + T ? (int) (run.snap_pos - p0) : -1;
                if (L0.eg >= 0) {   // this unit's rows ready, the next one's on their way
                    const double te = now_ms();
                    eg_next.get();
                    st.engram_ms += now_ms() - te;
                    wp.eg_slot = (int) (eg_u % 2);
                    if (++eg_u < egu.size()) eg_next = std::async(std::launch::async, read_eg, eg_u);
                }
                if (li == 0) {   // the chunk's input: its embedding rows
                    if (k >= 2) CK(cudaEventSynchronize(c.emb_ev[slot]));
                    for (int t = 0; t < T; ++t)
                        std::memcpy(c.emb_host[slot] + (size_t) t * D, emb_row(p0 + t, toks[(size_t) (p0 + t)]),
                                    (size_t) D * 2);
                    CK(cudaMemcpyAsync(c.emb, c.emb_host[slot], (size_t) T * D * 2, cudaMemcpyHostToDevice, s));
                    CK(cudaEventRecord(c.emb_ev[slot], s));
                    embed(c.emb, T, c.h, D, H, s);
                    init_pre(c.pre, T, s);
                } else {   // or its state after the layer before
                    const Xfer x = chunk_xfer(c.lm_state + (size_t) k * hb, c, T, false);
                    for (int i = 0; i < x.n; ++i)
                        CK(cudaMemcpyAsync(x.dst[i], x.src[i], x.bytes[i], cudaMemcpyHostToDevice, s));
                }
                if (last_k && g.n_mtp > 0) {   // the drafter's taps: the last chunk's last rows
                    const auto it = std::find(g.d_targets.begin(), g.d_targets.end(), il);
                    if (it != g.d_targets.end()) {
                        const size_t j = (size_t) (it - g.d_targets.begin()), nt = g.d_targets.size();
                        const int nr = std::min(T, tap_cap);
                        hc_mean(c.h + (size_t) (T - nr) * H * D, nr, H, D, d.tap, D, s);
                        if (!wait_seed(s, err)) return false;
                        CK(cudaMemcpy2DAsync(h_taps + j * D, nt * D * 4, d.tap, (size_t) D * 4, (size_t) D * 4,
                                             (size_t) nr, cudaMemcpyDeviceToHost, s));
                    }
                }
                const bool kvo = run.kv_only(k, il);
                if (!run_layer(L0, 0, p0, T, wp, S, err, run, k, il)) return false;
                if (dump_l != nullptr) dump_layer(d, c.h, il, p0, T);
                if (kvo) continue;   // (no layer after it reads this chunk's state)
                if (!last_l) {   // the chunk's state kept for the next layer
                    const Xfer x = chunk_xfer(c.lm_state + (size_t) k * hb, c, T, true);
                    for (int i = 0; i < x.n; ++i)
                        CK(cudaMemcpyAsync(x.dst[i], x.src[i], x.bytes[i], cudaMemcpyDeviceToHost, s));
                    continue;
                }
                // through every layer: the chunk's end, and the logits
                if ((size_t) k < chunk_done.size()) {
                    CK(cudaEventRecord(chunk_done[(size_t) k], s));
                    chunk_rec[(size_t) k].store(1, std::memory_order_release);
                }
                if (logits_all) {   // every row's logits (tests): the head over the chunk's rows, 16 at a time
                    const size_t base = (size_t) (p0 - run.p0[0]) * g.vocab;
                    for (int r0 = 0; r0 < T; r0 += kWin) {
                        const int nr = std::min(kWin, T - r0);
                        hc_pre_norm(c.h + (size_t) r0 * H * D, c.pre + (size_t) r0 * 8, d.norm_w, D, H, nr, g.eps, d.x, s);
                        if (!head_share(d, d.mi, d.x, nr, err)) return false;
                        CK(cudaMemcpyAsync(chunk_logits.data() + base + (size_t) r0 * g.vocab, d.logits,
                                           (size_t) nr * g.vocab * 4, cudaMemcpyDeviceToHost, s));
                        CK(cudaStreamSynchronize(s));
                    }
                } else if (last_k && n_logits > 0) {   // (the last rows' logits, into the window path's buffers)
                    const int t0 = T - n_logits;
                    hc_pre_norm(c.h + (size_t) t0 * H * D, c.pre + (size_t) t0 * 8, d.norm_w, D, H, n_logits, g.eps, d.x, s);
                    if (!head_share(d, d.mi, d.x, n_logits, err)) return false;
                }
            }
            lm_layers.store((int) li + 1, std::memory_order_release);
        }
        S.report_prefill(d.id, std::accumulate(run.T.begin(), run.T.end(), 0), chunk, c.stream_bytes - stream_start);
        return true;
    }
    bool run_dev_chunks(int di, const Run& run, std::string& err) {
        Dev& d = devs[(size_t) di];
        Chunk& c = *chunks[(size_t) di];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int D = g.dim, H = g.hc, nk = (int) run.T.size();
        Streamer S;
        const double stream_start = c.stream_bytes;
        const int B = std::max(1, c.ring_n / Chunk::kParts);
        if (c.flow) {   // (the flow decides its streams as the layers route; nothing planned here)
            CK(cudaStreamSynchronize(s));
            CK(cudaStreamSynchronize(c.cs));
            c.items.clear();
            c.base = c.n_read = c.n_dma = c.n_comp = 0;
            c.n_file = 0;
            std::fill(c.stage_item.begin(), c.stage_item.end(), -1);
            c.fl_layers.clear();
            for (int il = 0; il < g.nl; ++il)   // (a group's layers: on each member)
                for (int m = 0; m < L[(size_t) il].nm; ++m)
                    if (member(L[(size_t) il], m).dev == di) c.fl_layers.push_back(il);
            c.fl_T = run.T;
            c.fl_yoco = run.yoco;
            c.fl_cut_k = run.cut_k;
            c.fl_cut_r = run.cut_r;
            c.spec_k = c.spec_il = -1;
            c.wait_ms = 0;
            c.it_file = c.it_ram = c.it_spec = c.it_spec_unused = c.it_lc = c.it_helper = c.chk_n = 0;
            c.lc_il = -1;
            c.lc_used = 0;
            c.lc_first = c.lc_chk = 0;
            c.io_d0 = c.io->direct_bytes();
            c.io_b0 = c.io->buffered_bytes();
            c.io_h0 = c.io->device_bytes();
            // (a short prompt's reads through the page cache, which keeps them for the decode after it - as the CPU
            // lane's reads in windows did: one V100, Maya-S from an NVMe, decode after 17 tokens 12.7 tokens/s read
            // past the cache, 14.0 after windows; a long one's past it, more than the cache holds - DS4_FLOW_BUFFERED,
            // 1024 tokens on one GPU, 0 on more: the longest run read through it)
            static const int buf_max = std::getenv("DS4_FLOW_BUFFERED") ? std::atoi(std::getenv("DS4_FLOW_BUFFERED"))
                                                                        : devs.size() == 1 ? 1024 : 0;
            int run_n = 0;
            for (int t : run.T) run_n += t;
            c.buffered = run_n <= buf_max;
            if (!c.fl_layers.empty()) {
                // A group starting at the YOCO source has only KV work before the cut: no flow_layer to advance it.
                const int il = c.fl_layers[0], k = run.yoco >= 0 && il >= run.yoco ? run.cut_k : 0;
                flow_spec(c, k, il, fl_rows(c, k, il));
                if (!flow_pump(c, err)) return false;
            }
            if (c.lm) return run_dev_layers(di, run, err, stream_start);
        }
        for (int k = 0; k < nk && !c.flow; ++k)
            for (int il = 0; il < g.nl; ++il) {
                if (!run.runs(k, il) || run.kv_only(k, il)) continue;   // (a long prompt's skip: no experts there)
                const Layer& L0 = L[(size_t) il];
                bool here = false;
                for (int m = 0; m < L0.nm; ++m) here = here || member(L0, m).dev == di;
                if (!here) continue;
                for (int j0 = 0; j0 < (int) L0.host_list.size(); j0 += B)
                    S.b.push_back({k, il, j0, std::min(B, (int) L0.host_list.size() - j0)});
            }
        if (!S.b.empty() && c.ring == nullptr) {
            err = "no slots to stream experts into on CUDA" + std::to_string(d.id);
            return false;
        }
        std::atomic<bool> ra_stop{false};
        std::thread ra;
        if (file_experts && !S.b.empty()) ra = std::thread([this, &S, di, &ra_stop] { read_ahead(S, di, ra_stop); });
        struct Join {   // (every way out of the run: the read-ahead ends before S does)
            std::atomic<bool>& stop;
            std::thread& th;
            ~Join() {
                stop.store(true);
                if (th.joinable()) th.join();
            }
        } ra_join{ra_stop, ra};
        if (!copy_ahead(d, c, S, di, err)) return false;
        // this device's Engram layers: chunk k's rows read on a helper thread while chunk k - 1 runs (slot k % 2, once
        // chunk k - 2's copy of it is done)
        std::vector<int> egs;
        for (const Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m)
                if (member(l0, m).dev == di && !l0.mtp && l0.eg >= 0) egs.push_back(l0.eg);
        const size_t eg_per = (size_t) (pk.eg_ngram - 1) * pk.eg_heads * (pk.eg_hd + pk.eg_hd / 32);
        // (a group's: its first member reads them for every member - slot k % 2 once each member's copies of chunk
        //  k - 2 out of it are done - and the others wait for its slots)
        const int eg_src = egs.empty() ? di : eg_src_dev(di);
        std::vector<int> eg_mates;   // the devices whose copies read this one's slots (this one too)
        for (size_t j = 0; j < devs.size() && eg_src == di; ++j)
            if (chunks[j] != nullptr && devs[j].grp == d.grp && eg_src_dev((int) j) == di) eg_mates.push_back((int) j);
        auto eg_wait_seq = [this](const std::atomic<unsigned>& a, unsigned seq) {   // (false: the run ends)
            while ((int) (a.load(std::memory_order_acquire) - seq) < 0) {
                if (eg_abort.load(std::memory_order_acquire) || halt.load(std::memory_order_acquire)) return false;
                std::this_thread::sleep_for(std::chrono::microseconds(50));
            }
            return true;
        };
        auto read_eg = [this, &c, &run, &egs, eg_per, &eg_mates, &eg_wait_seq](int k) {
            const int sl = k % 2;
            if (k >= 2)
                for (int j : eg_mates) {
                    Chunk& m = *chunks[(size_t) j];
                    if (!eg_wait_seq(m.eg_copied_seq[sl], run.seq[(size_t) k - 2])) return;
                    cudaEventSynchronize(m.eg_ev[sl]);
                }
            for (int li : egs) {
                if (eg_pf != nullptr) eg_pf->wait_unit(li, k);
                engram_rows(run.p0[(size_t) k], run.T[(size_t) k], li, c.eg_host[sl] + (size_t) li * c.C * eg_per);
                if (eg_pf != nullptr) eg_pf->finish_unit(li, k);
            }
            if (eg_pf != nullptr) eg_pf->finish_chunk(k);
            c.eg_read_seq[sl].store(run.seq[(size_t) k], std::memory_order_release);
        };
        std::future<void> eg_next;
        if (!egs.empty() && eg_src == di) eg_next = std::async(std::launch::async, read_eg, 0);
        for (int k = 0; k < nk; ++k) {
            if (!chunk_go(k)) return halt_end(di, err);   // (a Stop: the chunks every device reaches are done)
            const int64_t p0 = run.p0[(size_t) k];
            const int T = run.T[(size_t) k], slot = k % 2;
            const bool last_k = k + 1 == nk;
            if (!egs.empty()) {   // chunk k's rows ready, chunk k + 1's on their way
                const double te = now_ms();
                if (eg_src == di) {
                    eg_next.get();
                    if (k + 1 < nk) eg_next = std::async(std::launch::async, read_eg, k + 1);
                } else if (!eg_wait_seq(chunks[(size_t) eg_src]->eg_read_seq[slot], run.seq[(size_t) k])) {
                    if (halt.load(std::memory_order_acquire)) return halt_end(di, err);
                    err = "the Engram rows' reader stopped";
                    return false;
                }
                if (d.mi == 0) st.engram_ms += now_ms() - te;
            }
            WinPlan wp;
            wp.par = true;
            wp.async = true;
            wp.win = run.seq[(size_t) k];
            wp.k = k;
            wp.snap_t = run.snap_pos >= p0 && run.snap_pos < p0 + T ? (int) (run.snap_pos - p0) : -1;
            bool started = false;
            std::vector<char> got(srcs.size(), 0);
            for (int il = 0; il < g.nl; ++il) {
                if (halt_now()) return halt_end(di, err);   // (one GPU: after the layer it is on)
                Layer& L0 = L[(size_t) il];
                int mi = -1;
                for (int m = 0; m < L0.nm; ++m)
                    if (member(L0, m).dev == di) mi = m;
                if (mi < 0) continue;
                if (!started && run.runs(k, il)) {   // the chunk's input: its embedding rows, or the previous group's hand-off
                    started = true;
                    if (il == 0) {
                        if (k >= 2) CK(cudaEventSynchronize(c.emb_ev[slot]));
                        for (int t = 0; t < T; ++t)
                            std::memcpy(c.emb_host[slot] + (size_t) t * D, emb_row(p0 + t, toks[(size_t) (p0 + t)]),
                                        (size_t) D * 2);
                        CK(cudaMemcpyAsync(c.emb, c.emb_host[slot], (size_t) T * D * 2, cudaMemcpyHostToDevice, s));
                        CK(cudaEventRecord(c.emb_ev[slot], s));
                        embed(c.emb, T, c.h, D, H, s);
                        init_pre(c.pre, T, s);
                    } else {
                        Chunk& a = *chunks[(size_t) L[(size_t) il - 1].dev];
                        xfer_get(chunk_xfer(a.hand[slot], c, T, false), a.hand_flag[slot], wp.win, s);
                        set_flag(a.hand_ack + ((size_t) slot * 8 + mi) * 32, wp.win, s);
                    }
                }
                for (int sidx : {L0.src, L0.ix_src ? L0.ik_src : -1}) {
                    if (sidx < 0 || got[(size_t) sidx]) continue;
                    got[(size_t) sidx] = 1;
                    Src& sr = srcs[(size_t) sidx];
                    if (L[(size_t) sr.layer].grp == L0.grp) continue;
                    const int64_t g_first = p0 / sr.ratio;
                    const int ng = (int) std::max<int64_t>(0, (p0 + T) / sr.ratio - g_first);
                    Xfer x;
                    if (ng > 0 && sr.ckv[(size_t) di] != nullptr) {
                        x.src[x.n] = sr.stage(slot);
                        x.dst[x.n] = sr.ckv[(size_t) di] + (size_t) g_first * ckv_rb();
                        x.bytes[x.n++] = (size_t) ng * ckv_rb();
                    }
                    if (ng > 0 && sr.ik[(size_t) di] != nullptr) {
                        x.src[x.n] = sr.stage(slot) + x_cap() * ckv_rb();
                        x.dst[x.n] = sr.ik[(size_t) di] + (size_t) g_first * ik_rb();
                        x.bytes[x.n++] = (size_t) ng * ik_rb();
                    }
                    if (x.n > 0) xfer_get(x, sr.flag(slot), wp.win, s);
                    set_flag(sr.x_ack + ((size_t) slot * devs.size() + di) * 32, wp.win, s);   // (taken, or none)
                }
                if (last_k && mi == 0 && g.n_mtp > 0) {   // the drafter's taps: the last chunk's last rows
                    const auto it = std::find(g.d_targets.begin(), g.d_targets.end(), il);
                    if (it != g.d_targets.end()) {
                        const size_t j = (size_t) (it - g.d_targets.begin()), nt = g.d_targets.size();
                        const int nr = std::min(T, tap_cap);
                        hc_mean(c.h + (size_t) (T - nr) * H * D, nr, H, D, d.tap, D, s);
                        if (!wait_seed(s, err)) return false;
                        CK(cudaMemcpy2DAsync(h_taps + j * D, nt * D * 4, d.tap, (size_t) D * 4, (size_t) D * 4,
                                             (size_t) nr, cudaMemcpyDeviceToHost, s));
                    }
                }
                // (a chunk before the cut, past the yoco layer: its sources' rows taken above, for the chunks after it)
                if (!run.runs(k, il)) continue;
                if (!run_layer(L0, mi, p0, T, wp, S, err, run, k, il)) return false;
                if (dump_l != nullptr && mi == 0) dump_layer(d, c.h, il, p0, T);
                const bool last = il + 1 == g.nl || L[(size_t) il + 1].grp != L0.grp;
                // the hand-off, once the next group took the chunk before last (the chunks it takes: past the yoco
                // layer, those from the cut on)
                if (last && mi == 0 && il + 1 < g.nl && run.runs(k, il + 1)) {
                    const int nnext = L[(size_t) il + 1].nm;
                    if (k >= 2 && run.runs(k - 2, il + 1))
                        wait_flags(c.hand_ack + (size_t) slot * 8 * 32, nnext, 32, wp.win - 2, s);
                    xfer_put(chunk_xfer(c.hand[slot], c, T, true), c.hand_flag[slot], wp.win, d.xcnt, s);
                }
            }
            // (chunk k's copies out of its Engram slot issued, their event recorded: the reader may refill it)
            if (!egs.empty()) c.eg_copied_seq[slot].store(wp.win, std::memory_order_release);
            if (di == head_dev && (size_t) k < chunk_done.size()) {
                CK(cudaEventRecord(chunk_done[(size_t) k], s));
                chunk_rec[(size_t) k].store(1, std::memory_order_release);
            }
            if (d.grp == devs[(size_t) head_dev].grp) {   // the head group: each member its share of the logits
                if (logits_all) {   // every row's logits (tests): the head over the chunk's rows, 16 at a time
                    const size_t base = (size_t) (p0 - run.p0[0]) * g.vocab;
                    for (int r0 = 0; r0 < T; r0 += kWin) {
                        const int nr = std::min(kWin, T - r0);
                        hc_pre_norm(c.h + (size_t) r0 * H * D, c.pre + (size_t) r0 * 8, d.norm_w, D, H, nr, g.eps, d.x, s);
                        if (!head_share(d, d.mi, d.x, nr, err)) return false;
                        if (di != head_dev) continue;
                        CK(cudaMemcpyAsync(chunk_logits.data() + base + (size_t) r0 * g.vocab, d.logits,
                                           (size_t) nr * g.vocab * 4, cudaMemcpyDeviceToHost, s));
                        CK(cudaStreamSynchronize(s));
                    }
                } else if (last_k && n_logits > 0) {   // (the last rows' logits, into the window path's buffers)
                    const int t0 = T - n_logits;
                    hc_pre_norm(c.h + (size_t) t0 * H * D, c.pre + (size_t) t0 * 8, d.norm_w, D, H, n_logits, g.eps, d.x, s);
                    if (!head_share(d, d.mi, d.x, n_logits, err)) return false;
                }
            }
        }
        S.report_prefill(d.id, std::accumulate(run.T.begin(), run.T.end(), 0), chunk, c.stream_bytes - stream_start);
        if (!c.flow && S.copied + S.skipped > 0 && std::getenv("DS4_FLOW_STATS") != nullptr)
            std::fprintf(stderr, "ds4 prompt batches, CUDA%d: %zu experts copied, %zu unpicked experts skipped\n",
                         devs[(size_t) di].id, S.copied, S.skipped);
        return true;
    }

    // ---- a prompt's path: the flow or windows of 16
    // this PC's speeds for pick_path (every device on the flow, the experts in place): the DMA from pinned staging to a
    // GPU; the readers copying RAM into staging; the disk read by them (experts not in RAM); the CPU lane on experts in
    // RAM and on ones it reads from the disk first - each timed once, a few experts' worth (DS4_PATH_PICK=0: always the
    // flow, as before)
    void calibrate_paths() {
        if (chunk <= 0 || chunk_min != kFlowChunkMin || std::getenv("DS4_CHUNK_MIN") != nullptr) return;
        if (const char* v = std::getenv("DS4_PATH_PICK"))
            if (std::atoi(v) == 0) return;
        int di = -1;
        for (size_t i = 0; i < chunks.size() && di < 0; ++i)
            if (chunks[i] != nullptr && chunks[i]->flow && chunks[i]->S >= 2) di = (int) i;
        if (di < 0) return;
        Chunk& c = *chunks[(size_t) di];
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        const double t0 = now_ms();
        // the DMA: staging -> the ring (once to warm up, once timed)
        const size_t nb = std::min({(size_t) 256 << 20, (size_t) c.S * c.stage_stride, (size_t) c.ring_n * c.ring_stride});
        double ms = 0;
        for (int rep = 0; rep < 2; ++rep) {
            const double a = now_ms();
            if (cudaMemcpyAsync(c.ring, c.stage, nb, cudaMemcpyHostToDevice, c.cs) != cudaSuccess ||
                cudaStreamSynchronize(c.cs) != cudaSuccess) {
                cudaGetLastError();
                return;
            }
            ms = now_ms() - a;
        }
        pm.dma = (double) nb / std::max(1e-3, ms / 1000.0);
        // the readers: RAM -> staging (a buffer of its own, touched first), in as many jobs as they are
        auto run_jobs = [&](std::vector<IoQueue::Job>& jobs, std::atomic<int>& left) {
            const double a = now_ms();
            left.store((int) jobs.size());
            c.io->push(jobs.data(), (int) jobs.size());
            while (left.load(std::memory_order_acquire) != 0) c.io->wait_any(500);
            return now_ms() - a;
        };
        {
            const size_t part = std::min(nb, (size_t) 64 << 20) / 8 / 4096 * 4096;
            std::vector<uint8_t> src(part * 8, 1);
            std::vector<IoQueue::Job> jobs(8);
            std::atomic<int> left{0};
            std::atomic<bool> bad{false};
            for (int i = 0; i < 8; ++i) {
                jobs[(size_t) i].mem = src.data() + (size_t) i * part;
                jobs[(size_t) i].dst = c.stage + (size_t) i * part;
                jobs[(size_t) i].len = part;
                jobs[(size_t) i].left = &left;
                jobs[(size_t) i].bad = &bad;
            }
            run_jobs(jobs, left);
            const double t1 = run_jobs(jobs, left), t2 = run_jobs(jobs, left);
            pm.copy = (double) (part * 8) / std::max(1e-3, std::min(t1, t2) / 1000.0);
        }
        // experts not in RAM (none of their sampled pages resident), of the trunk layer with the most CPU-lane ones:
        // up to min(8, staging slots) read by the readers as the flow reads them, then 8 others through the CPU lane
        // three times (from the disk, then in RAM: the faster of two)
        int best = -1, most = 0;
        for (int il = 0; il < g.nl; ++il) {
            int n = 0;
            for (int e = 0; e < L[(size_t) il].n_exp; ++e) n += L[(size_t) il].slot[(size_t) e] < 0;
            if (n > most) most = n, best = il;
        }
        if (best < 0) return;
        const Layer& l = L[(size_t) best];
        std::vector<int> cold;
        const int n_read = std::min(8, c.S), n_cpu = 8;
        for (int e = 0; e < l.n_exp && (int) cold.size() < n_read + n_cpu; ++e) {
            if (l.slot[(size_t) e] >= 0 || (!l.ram.empty() && l.ram[(size_t) e] >= 0)) continue;
            bool res = false;
            for (int r = 0; r < 3; ++r) res = res || os::resident_sampled(mx_mat(l, e, r), mx_part_bytes(l, r), 4);
            if (!res) cold.push_back(e);
        }
        if ((int) cold.size() >= n_read + n_cpu) {
            std::vector<IoQueue::Job> jobs;
            std::atomic<int> left{0};
            std::atomic<bool> bad{false};
            for (int i = 0; i < n_read; ++i) {
                uint8_t* sb = c.stage + (size_t) i * c.stage_stride;
                for (int r = 0; r < 3; ++r) {
                    IoQueue::Job j;
                    const os::fd_t pf = pk.pfds.empty() ? os::kBadFd : pk.pfds[(size_t) l.mx_file[r]];
                    j.fd = pf != os::kBadFd ? pf : pk.fds[(size_t) l.mx_file[r]];
                    j.dfd = pk.dfds.empty() ? os::kBadFd : pk.dfds[(size_t) l.mx_file[r]];
                    j.off = l.mx_off[r] + (uint64_t) cold[(size_t) i] * l.mx_stride[r];
                    j.len = mx_part_bytes(l, r);
                    j.dst = sb;
                    j.left = &left;
                    j.bad = &bad;
                    j.map = pk.at(l.mx_file[r], j.off);
                    jobs.push_back(j);
                    sb += flow_region(r);
                }
            }
            const double rd = run_jobs(jobs, left);
            if (!bad.load()) pm.disk = (double) n_read * (double) l.blob / std::max(1e-3, rd / 1000.0);
        }
        {   // the CPU lane: entries of one token (as most of a window's are), from the disk (if any were cold), then RAM
            const size_t first = (int) cold.size() >= n_read + n_cpu ? (size_t) n_read : 0;
            std::vector<Ent> ents;
            for (int i = 0; i < n_cpu; ++i) {
                Ent en;
                en.e = first + (size_t) i < cold.size() ? cold[first + (size_t) i] : -1;
                if (en.e < 0)   // (no cold ones: the first CPU-lane experts, wherever they are)
                    for (int e = 0, k = 0; e < l.n_exp && en.e < 0; ++e)
                        if (l.slot[(size_t) e] < 0 && k++ == i) en.e = e;
                if (en.e < 0) break;
                en.n = 1;
                en.slot0 = i;
                en.tok[0] = 0;
                ents.push_back(en);
            }
            if (ents.empty()) return;
            std::vector<float> x((size_t) g.dim);
            for (size_t i = 0; i < x.size(); ++i) x[i] = 0.02f * std::sin(0.37f * (float) i);
            const double bytes = (double) ents.size() * (double) l.blob;
            double a = now_ms();
            cpu_experts(l, x.data(), ents, (size_t) g.dim);
            const double t_first = now_ms() - a;
            double t_warm = 1e30;
            for (int rep = 0; rep < 2; ++rep) {
                a = now_ms();
                cpu_experts(l, x.data(), ents, (size_t) g.dim);
                t_warm = std::min(t_warm, now_ms() - a);
            }
            pm.cpu = bytes / std::max(1e-3, t_warm / 1000.0);
            if (first > 0 || (int) cold.size() >= n_cpu) pm.cpu_cold = bytes / std::max(1e-3, t_first / 1000.0);
        }
        pm.on = pm.dma > 0 && pm.copy > 0 && pm.cpu > 0;
        if (o.verbose) {
            char dk[32] = "not measured", cc[32] = "not measured";
            if (pm.disk > 0) std::snprintf(dk, sizeof dk, "%.2f GB/s", pm.disk / 1e9);
            if (pm.cpu_cold > 0) std::snprintf(cc, sizeof cc, "%.2f GB/s", pm.cpu_cold / 1e9);
            std::fprintf(stderr,
                         "ds4: prompts through the flow or windows by this PC's speeds: DMA %.1f GB/s, RAM to staging "
                         "%.1f GB/s, the disk %s; the CPU lane %.1f GB/s in RAM, %s from the disk (%.0f ms)\n",
                         pm.dma / 1e9, pm.copy / 1e9, dk, pm.cpu / 1e9, cc, now_ms() - t0);
        }
    }
    // layer l's CPU-lane experts (VRAM holds the rest) and the chance a token picks a given one of them: the profile's
    // share of the layer's picks they took, spread evenly over them, times pm.m (what the flow's runs found)
    double pm_rate(const Layer& l, int& n_cold) const {
        const uint32_t* pr = prof.data() + (size_t) l.il * g.n_exp;
        double sum = 0, cold = 0;
        n_cold = 0;
        for (int e = 0; e < l.n_exp; ++e) {
            sum += pr[e];
            if (l.slot[(size_t) e] < 0) cold += pr[e], ++n_cold;
        }
        if (n_cold == 0) return 0.0;
        const double share = sum > 0 && cold > 0 ? cold / sum : (double) n_cold / l.n_exp;
        return pm.m * (double) l.k_exp * share / n_cold;
    }
    // the CPU-lane experts n tokens pick in the trunk's layers, expected (each layer's n_cold (1 - e^(-rate n)))
    double pm_picks(int n) const {
        double d = 0;
        for (int il = 0; il < g.nl; ++il) {
            int nc = 0;
            const double a = pm_rate(L[(size_t) il], nc);
            d += nc * (1.0 - std::exp(-a * n));
        }
        return d;
    }
    // a run of one chunk of n tokens on the flow picked `picked` CPU-lane experts: pm.m to what makes the expectation
    // that (bisection over its log; a running mean of the log)
    void pm_learn(int n, double picked) {
        if (!pm.on || n < 2 || picked < 1) return;
        const double m0 = pm.m;
        double lo = std::log(1e-3), hi = std::log(1e3);
        for (int it = 0; it < 40; ++it) {
            pm.m = std::exp(0.5 * (lo + hi));
            (pm_picks(n) < picked ? lo : hi) = 0.5 * (lo + hi);
        }
        const double obs = 0.5 * (lo + hi);
        pm.m = std::exp(pm.n_m == 0 ? obs : 0.7 * std::log(m0) + 0.3 * obs);
        ++pm.n_m;
    }
    // a prompt of n tokens that the flow could take (n >= chunk_min): true the flow, false windows of 16 - each path's
    // time predicted from the bytes of CPU-lane experts it would move (the flow: each picked one once, n_cold (1 -
    // e^(-rate n)) a layer, pm_rate) or compute (windows: each window's own picks), those in RAM (each layer's share:
    // sampled pages of up to 32 of its CPU-lane experts, mincore / QueryWorkingSetEx; the RAM tier's) and those not at
    // this PC's speeds - the flow's times what it really took against its predictions so far for prompts of that size
    // (pm_k), windows' once some ran what a window took times the windows; the flow unless windows are predicted
    // faster (by half, with less than kPickRes in RAM); said with --verbose
    // --no-expert-cache (pinned placement, for repeatable answers): always the flow - the choice goes by this run's
    // timings, what earlier prompts took and what the page cache holds, and the two paths round differently, so the
    // same prompt would give other logits after other requests than in a fresh process
    bool pick_path(int n) {
        pm.last = -1;
        if (!pm.on || n >= kPickMax || !o.expert_cache) return true;
        double f_res = 0, f_cold = 0, w = 0;
        const int nw = n / kWin, rem = n % kWin;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            int nc = 0;
            const double a = pm_rate(l, nc);
            if (nc == 0) continue;
            int sampled = 0, res = 0, seen = 0;
            const int step = std::max(1, nc / 32);
            for (int e = 0; e < l.n_exp; ++e) {
                if (l.slot[(size_t) e] >= 0 || seen++ % step != 0) continue;
                bool r = !l.ram.empty() && l.ram[(size_t) e] >= 0;
                if (!r) {
                    r = true;
                    for (int p = 0; p < 3 && r; ++p) r = os::resident_sampled(mx_mat(l, e, p), mx_part_bytes(l, p), 2);
                }
                ++sampled;
                res += r;
            }
            const double share = sampled > 0 ? (double) res / sampled : 0.0, b = (double) l.blob;
            auto u = [&](int t) { return nc * (1.0 - std::exp(-a * t)); };
            f_res += share * u(n) * b;
            f_cold += (1.0 - share) * u(n) * b;
            w += ((double) nw * u(kWin) + (rem > 0 ? u(rem) : 0.0)) * b;
        }
        const double r_fr = std::min(pm.copy, pm.dma), r_fc = pm.disk > 0 ? std::min(pm.disk, pm.dma) : r_fr;
        const double r_wc = pm.cpu_cold > 0 ? pm.cpu_cold : 1.0 / (1.0 / r_fc + 1.0 / pm.cpu);
        const double t_flow = f_res / r_fr + f_cold / r_fc;
        const double t_win = std::max(0.0, w - f_cold) / pm.cpu + f_cold / r_wc;
        const int cls = pm_cls(n), n_win = (n + kWin - 1) / kWin;
        // (windows: once some ran, what a window took on average times the windows the prompt needs - each pays the
        // fixed costs of every layer on every GPU again, which a pass of the flow pays once)
        const double pf = pm_k(cls) * t_flow, pw = pm.win_n > 0 ? pm.win_s * n_win : t_win;
        // (the flow unless windows are predicted faster - in half its time at least, unless kPickRes of the CPU-lane
        // experts' bytes are in RAM: the flow wins on every PC whose experts come from an SSD, where a wrong pick would
        // cost the most; windows win where they are all in RAM)
        const double res_share = f_res / std::max(1.0, f_res + f_cold);
        const bool flow = !(pw < pf && (res_share >= kPickRes || 2.0 * pw <= pf));
        pm.last = flow ? 1 : 0;
        pm.last_cls = cls;
        pm.last_nw = n_win;
        pm.last_pred = flow ? t_flow : t_win;
        if (o.verbose)
            std::fprintf(stderr,
                         "ds4: a prompt of %d tokens through %s: predicted %.2f s, %s %.2f s (%.0f%% of its CPU-lane "
                         "experts' %.1f GB in RAM)\n",
                         n, flow ? "the flow" : "windows", flow ? pf : pw, flow ? "windows" : "the flow", flow ? pw : pf,
                         100.0 * res_share, (f_res + f_cold) / 1e9);
        return flow;
    }
    // a prompt's size class for pm.k: 2-31, 32-127, 128-511, 512 tokens and more
    static int pm_cls(int n) { return n < 32 ? 0 : n < 128 ? 1 : n < 512 ? 2 : 3; }
    // the flow's time factor for size class c: its own, else its nearest class's, else 1 (never the windows': theirs
    // is mostly the fixed costs a window pays again and again)
    double pm_k(int c) const {
        for (int dc = 0; dc < 4; ++dc)
            for (int cc : {c - dc, c + dc})
                if (cc >= 0 && cc < 4 && pm.kn[0][cc] > 0) return pm.k[0][cc];
        return 1.0;
    }
    // n tokens through windows of 16, the last one's logits_rows rows of logits
    bool feed_windows(const int* tokens, int n, int logits_rows, std::string& err) {
        logits_all = false;
        for (int a = 0; a < n; a += kWin) {
            const int T = std::min(kWin, n - a);
            if (!forward(tokens + a, T, a + T == n ? logits_rows : 0, err)) return false;
        }
        return true;
    }
    // the picked path took ms: the flow's predictions for the prompt's size class scaled by what it really takes (taken
    // / predicted), windows' time a window - running means
    void path_done(double ms) {
        if (pm.last < 0 || pm.last_pred <= 0) return;
        if (pm.last == 0) {
            const double w = ms / 1000.0 / std::max(1, pm.last_nw);
            pm.win_s = pm.win_n == 0 ? w : 0.7 * pm.win_s + 0.3 * w;
            ++pm.win_n;
        } else {
            const double ratio = std::min(8.0, std::max(0.25, ms / 1000.0 / pm.last_pred));
            double& k = pm.k[0][pm.last_cls];
            int64_t& n = pm.kn[0][pm.last_cls];
            k = n == 0 ? ratio : 0.7 * k + 0.3 * ratio;
            ++n;
        }
        pm.last = -1;
    }
    // a run layer-major? - one device holding every layer on the flow, several chunks, and what the chunks after the
    // first would read from the files again more than the chunks' states moved to host memory and back at every layer
    // (DS4_LAYER_MAJOR=0: never); then its host memory: the chunks' states (pinned, else pageable) and the layer cache,
    // the largest layer's experts read from the files if RAM allows (ram_avail() less kRamMargin; DS4_LAYER_CACHE_MB
    // sets it) - at least one expert, or not layer-major
    bool lm_begin(const Run& run) {
        static const char* env = std::getenv("DS4_LAYER_MAJOR");
        if (devs.size() != 1 || run.T.size() < 2 || (env != nullptr && std::atoi(env) == 0)) return false;
        Chunk& c = *chunks[0];
        if (!c.flow) return false;
        size_t need = 0, n_exp = 0, blob_max = 0;
        double file_b = 0;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            size_t ne = 0;
            for (int e : l.host_list)
                if (l.ram.empty() || l.ram[(size_t) e] < 0) ++ne;
            const size_t stride = (l.blob + 63) & ~(size_t) 63;
            need = std::max(need, ne * stride);
            n_exp = std::max(n_exp, (size_t) l.n_exp);
            blob_max = std::max(blob_max, stride);
            file_b += (double) ne * (double) l.blob;
        }
        int64_t rows = 0;
        for (int T : run.T) rows += T;
        const size_t hb = chunk_hand_bytes(), state_b = run.T.size() * hb;
        const double moved = 2.0 * (double) rows * ((double) hb / (double) chunk) * (double) g.nl;
        if (need == 0 || (double) (run.T.size() - 1) * file_b <= moved) return false;
        size_t lc_bytes = need;
        if (const char* mb = std::getenv("DS4_LAYER_CACHE_MB")) lc_bytes = std::min(need, (size_t) std::atoll(mb) << 20);
        else {
            const uint64_t avail = ram_room();
            if (avail != ~uint64_t{0})
                lc_bytes = std::min<uint64_t>(need, avail > kRamMargin + state_b ? avail - kRamMargin - state_b : 0);
        }
        if (lc_bytes < blob_max) return false;
        void* st_p = nullptr;
        c.lm_pinned = cudaHostAlloc(&st_p, state_b, cudaHostAllocPortable) == cudaSuccess;
        if (!c.lm_pinned) {
            cudaGetLastError();
            st_p = os::anon_alloc(state_b, -1, 1);
            if (st_p == nullptr) return false;
        }
        c.lc = (uint8_t*) os::anon_alloc(lc_bytes, -1, 1);
        if (c.lc == nullptr) {
            if (c.lm_pinned) cudaFreeHost(st_p);
            else os::anon_free(st_p, state_b);
            return false;
        }
        c.lm_state = (uint8_t*) st_p;
        c.lm_state_bytes = state_b;
        c.lc_bytes = lc_bytes;
        c.lc_of.assign(n_exp, -1);
        c.lc_writer.assign(n_exp, -1);
        c.lm = true;
        lm_layers.store(0);
        return true;
    }
    void lm_end() {
        for (size_t di = 0; di < chunks.size(); ++di) {
            Chunk& c = *chunks[di];
            if (!c.lm) continue;
            cudaSetDevice(devs[di].id);
            cudaStreamSynchronize(devs[di].st);   // (nothing of the run's still reads or writes them: the device's
            cudaStreamSynchronize(c.cs);          // copies done, every read the run issued done - a failed run's too)
            for (size_t i = c.base; i < c.n_read; ++i)
                while (fit(c, i).left.load(std::memory_order_acquire) != 0) c.io->wait_any(500);
            if (c.lm_pinned) cudaFreeHost(c.lm_state);
            else os::anon_free(c.lm_state, c.lm_state_bytes);
            os::anon_free(c.lc, c.lc_bytes);
            c.lm_state = c.lc = nullptr;
            c.lm_state_bytes = c.lc_bytes = 0;
            c.lm = c.lm_pinned = false;
        }
    }

    // a run of chunks of C rows borrows each lending device's room (Chunk::borrow): its buffers laid out at the end of
    // the tail region (zeroed, as their own room was), and of every layer the slots under them out of the run's VRAM
    // set (pv_n: their experts stream in as the CPU lane's do)
    bool borrow_begin(int C, std::string& err) {
        bool any = false;
        for (const auto& cp : chunks) any = any || (cp != nullptr && cp->borrow);
        if (!any) return true;
        cache_drain();
        if (ln_one || ln_land) rc_drain();   // (the one-GPU path's; elsewhere v1.1.27's: no wait)
        bool tp = false;   // (DS4_TP_BORROW: a group's layer keeps the fewest of its members' slots - from all of them)
        for (const auto& cp : chunks) tp = tp || (cp != nullptr && cp->tp_lend);
        // (every lending device's room first, before any is touched: a refusal leaves every slot as it was)
        for (size_t di = 0; di < chunks.size(); ++di) {
            if (chunks[di] == nullptr || !chunks[di]->borrow) continue;
            const Dev& d = devs[di];
            const size_t need = lay_chunk(*chunks[di], C, nullptr, 2);
            if (d.tail == nullptr || !chunks[di]->flow || need + 256 > d.tail_bytes) {   // (only the flow streams them)
                err = "the prompt path's room on CUDA" + std::to_string(d.id) + ": " + std::to_string(need >> 20) +
                      " MiB for chunks of " + std::to_string(C) + " tokens, " + std::to_string(d.tail_bytes >> 20) +
                      " lent";
                return false;
            }
        }
        if (tp)
            for (Layer& l : L) l.pv_n = l.n_slots;
        for (size_t di = 0; di < chunks.size(); ++di) {
            if (chunks[di] == nullptr || !chunks[di]->borrow) continue;
            Dev& d = devs[di];
            Chunk& c = *chunks[di];
            const size_t need = lay_chunk(c, C, nullptr, 2);
            const size_t b0 = (d.tail_bytes - need) & ~(size_t) 255;
            lay_chunk(c, C, d.tail + b0, 2);
            c.C = C;
            // (the clear writes over slots still mapped: a failure leaves them unknown - sticky, no later request runs;
            //  a device lent before this one is handed back by the caller's guard)
            cudaError_t e = cudaSetDevice(d.id);
            if (e == cudaSuccess) e = cudaMemsetAsync(d.tail + b0, 0, d.tail_bytes - b0, d.st);
            if (e == cudaSuccess) e = cudaStreamSynchronize(d.st);
            if (e != cudaSuccess) {
                lend_broken = true;
                err = std::string("the prompt path's room on CUDA") + std::to_string(d.id) + ": " +
                      cudaGetErrorString(e) + " - " + kLendBroken;
                std::fprintf(stderr, "ds4: %s - the device's state unknown; no further request runs\n", err.c_str());
                return false;
            }
            if (c.tp_lend) {   // (DS4_TP_BORROW) its parts of the slots under its buffers; the group keeps the fewest
                for (Layer& l : L) {
                    if (l.mtp || l.n_main >= l.n_slots) continue;
                    for (int m = 0; m < l.nm; ++m) {
                        const Layer& x = member(l, m);
                        if (x.dev != (int) di) continue;
                        const int keep = tail_keep((size_t) (x.xbase - d.tail), align256(unit(x)), d.tail_step, b0,
                                                   l.n_slots - l.n_main);
                        l.pv_n = std::min(l.pv_n, l.n_main + keep);
                    }
                }
                lent = true;
                continue;
            }
            for (Layer& l : L) {
                if (l.dev != (int) di || l.mtp || l.n_main >= l.n_slots) continue;
                const size_t off = (size_t) (l.xbase - d.tail), u = align256(unit(l));
                int keep = 0;   // (the slots wholly before the buffers)
                while (l.n_main + keep < l.n_slots && off + (size_t) keep * d.tail_step + u <= b0) ++keep;
                l.pv_n = l.n_main + keep;
            }
            lent = true;
        }
        return true;
    }
    // after the run (every device done with its buffers): the experts under them read back into their slots, in file
    // order by a few threads - one that cannot be read leaves VRAM for the CPU lane (the decode finds every other one
    // where it was).  false: DS4_CHECK_LEND found a part read back different from the file - those experts went to the
    // CPU lane too (nothing reads those slots), and the caller fails the prompt before any decode - or a device
    // selection, sync, copy into a slot or table write failed: lend_broken (sticky), no later request runs
    bool borrow_end() {
        if (!lent) return true;
        lent = false;
        std::atomic<bool> broken{false};   // (a runtime failure: the expert tables can no longer be vouched for)
        std::string why;
        for (size_t di = 0; di < devs.size() && !broken; ++di) {
            cudaError_t e = cudaSetDevice(devs[di].id);
            if (e == cudaSuccess) e = cudaStreamSynchronize(devs[di].st);
            if (e == cudaSuccess && di < chunks.size() && chunks[di] != nullptr && chunks[di]->cs != nullptr)
                e = cudaStreamSynchronize(chunks[di]->cs);
            if (e != cudaSuccess) {
                broken = true;
                why = "CUDA" + std::to_string(devs[di].id) + "'s streams: " + cudaGetErrorString(e);
            }
        }
        if (broken) {   // (the devices may still use the buffers: nothing is read back over them)
            lend_broken = true;
            std::fprintf(stderr, "ds4: the prompt path's room was not handed back (%s) - the device's state unknown; "
                                 "no further request runs\n", why.c_str());
            return false;
        }
        struct Job {
            int layer, e;
        };
        std::vector<Job> jobs;
        for (Layer& l : L) {
            if (l.pv_n < l.n_slots)
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] >= l.pv_n) jobs.push_back({l.il, e});
            l.pv_n = l.n_slots;
        }
        if (jobs.empty()) return true;
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.mx_file[0] != lb.mx_file[0]) return la.mx_file[0] < lb.mx_file[0];
            return la.mx_off[0] + (uint64_t) a.e * la.mx_stride[0] < lb.mx_off[0] + (uint64_t) b.e * lb.mx_stride[0];
        });
        const double t0 = now_ms();
        if (rf_bytes == 0)
            for (const Layer& l : L) rf_bytes = std::max(rf_bytes, l.blob);
        const int nt = (int) std::min<size_t>(jobs.size(), 8);
        while ((int) rf_stage.size() < nt) {   // (pinned staging, kept for the next run)
            uint8_t* p = nullptr;
            if (cudaHostAlloc((void**) &p, rf_bytes, cudaHostAllocPortable) != cudaSuccess) break;
            host_allocs.push_back(p);
            rf_stage.push_back(p);
        }
        // (DS4_TP_BORROW: a group's layer's expert read once, each member's part of it split off into a second pinned
        //  staging and copied into that member's slot - as the load and the cache's swaps do)
        bool tp = false;
        for (const Job& j : jobs) tp = tp || L[(size_t) j.layer].nm > 1;
        while (tp && rf_half.size() < rf_stage.size()) {
            uint8_t* p = nullptr;
            if (cudaHostAlloc((void**) &p, rf_bytes, cudaHostAllocPortable) != cudaSuccess) break;
            host_allocs.push_back(p);
            rf_half.push_back(p);
        }
        const size_t n_th = tp ? std::min(rf_stage.size(), rf_half.size()) : rf_stage.size();
        std::vector<std::atomic<size_t>> dev_bytes(devs.size());   // (each device's parts read back)
        for (auto& b : dev_bytes) b.store(0);
        std::atomic<size_t> next{0};
        std::atomic<int> differ{0};
        static const bool check = std::getenv("DS4_CHECK_LEND") != nullptr;   // (each one read back, against the file)
        std::vector<char> bad(jobs.size(), 0);
        std::vector<std::thread> th;
        for (int t = 0; t < (int) n_th; ++t)
            th.emplace_back([&, t] {
                uint8_t* stage = rf_stage[(size_t) t];
                std::vector<uint8_t> back;
                for (;;) {
                    const size_t i = next.fetch_add(1);
                    if (i >= jobs.size()) break;
                    const Layer& l = L[(size_t) jobs[i].layer];
                    const int e = jobs[i].e;
                    if (l.nm > 1) {   // (DS4_TP_BORROW) each member its part
                        uint8_t* half = rf_half[(size_t) t];
                        bool ok = l.blob <= rf_bytes && read_mx_file(l, e, stage), same = true;
                        const bool read = ok;   // (a read that fails: the CPU lane takes it - the file has it)
                        for (int m = 0; m < l.nm && ok; ++m) {
                            const Layer& x = member(l, m);
                            blob_to_half(l, stage, m, half);
                            ok = cudaSetDevice(devs[(size_t) x.dev].id) == cudaSuccess &&
                                 cudaMemcpy(sat(l, x, l.slot[(size_t) e], unit(x)), half, unit(x),
                                            cudaMemcpyHostToDevice) == cudaSuccess;
                            if (!ok) broken = true;   // (a runtime failure, not the file's: the slot's bytes unknown)
                            if (ok) dev_bytes[(size_t) x.dev].fetch_add(unit(x));
                            if (ok && check) {
                                back.resize(unit(x));
                                const bool got = cudaMemcpy(back.data(), sat(l, x, l.slot[(size_t) e], unit(x)),
                                                            unit(x), cudaMemcpyDeviceToHost) == cudaSuccess;
                                if (!got) broken = true;   // (the read back failed: a runtime failure)
                                if (!got || std::memcmp(back.data(), half, unit(x)) != 0) {
                                    differ.fetch_add(1);
                                    same = false;
                                }
                            }
                        }
                        bad[i] = !read || !ok || !same;   // (a part that differs: to the CPU lane, as a failed read)
                        if (ok && same)   // (one copy of it: in VRAM again)
                            for (int r = 0; r < 3; ++r)
                                os::advise(pk.fds[(size_t) l.mx_file[r]], l.mx_off[r] + (uint64_t) e * l.mx_stride[r],
                                           mx_part_bytes(l, r), false);
                        continue;
                    }
                    const bool read = l.blob <= rf_bytes && read_mx_file(l, e, stage);
                    const bool put = read && cudaSetDevice(devs[(size_t) l.dev].id) == cudaSuccess &&
                                     cudaMemcpy(sat(l, l, l.slot[(size_t) e], l.blob), stage, l.blob,
                                                cudaMemcpyHostToDevice) == cudaSuccess;
                    if (read && !put) broken = true;   // (a runtime failure, not the file's)
                    bad[i] = !put;
                    if (check && !bad[i]) {
                        back.resize(l.blob);
                        const bool got = cudaMemcpy(back.data(), sat(l, l, l.slot[(size_t) e], l.blob), l.blob,
                                                    cudaMemcpyDeviceToHost) == cudaSuccess;
                        if (!got) broken = true;   // (the read back failed: a runtime failure)
                        if (!got || std::memcmp(back.data(), stage, l.blob) != 0) {
                            differ.fetch_add(1);
                            bad[i] = 1;   // (to the CPU lane, as a failed read)
                        }
                    }
                    if (!bad[i])   // (one copy of it: in VRAM again)
                        for (int r = 0; r < 3; ++r)
                            os::advise(pk.fds[(size_t) l.mx_file[r]], l.mx_off[r] + (uint64_t) e * l.mx_stride[r],
                                       mx_part_bytes(l, r), false);
                }
            });
        for (auto& t : th) t.join();
        size_t n_bad = 0, bytes = 0;
        for (size_t i = 0; i < jobs.size(); ++i) {
            Layer& l = L[(size_t) jobs[i].layer];
            const int e = jobs[i].e;
            bytes += l.blob;
            if (!bad[i] && n_th > 0) continue;
            ++n_bad;   // (to the CPU lane: the file has it)
            l.slot[(size_t) e] = -1;
            l.host[(size_t) e] = (uint8_t*) mx_mat(l, e, 0);
            --l.n_vram;
            const unsigned long long zero = 0;
            for (int m = 0; m < l.nm; ++m) {   // (a group's: every member's table - DS4_TP_BORROW)
                const Layer& x = member(l, m);
                if (cudaSetDevice(devs[(size_t) x.dev].id) != cudaSuccess ||
                    cudaMemcpy(x.vram_tab + e, &zero, 8, cudaMemcpyHostToDevice) != cudaSuccess)
                    broken = true;   // (the device's table may still name the slot)
            }
        }
        lent_experts += (int64_t) jobs.size();
        lent_ms += now_ms() - t0;
        if (tp) {   // (DS4_TP_BORROW: always - the decode after a prompt waits for it, so its cost is a reading)
            std::string per;
            for (size_t di = 0; di < devs.size(); ++di)
                if (dev_bytes[di].load() > 0) {
                    char b[64];
                    std::snprintf(b, sizeof b, "%sCUDA%d %.2f GB", per.empty() ? "" : ", ", devs[di].id,
                                  dev_bytes[di].load() / 1e9);
                    per += b;
                }
            std::fprintf(stderr, "ds4: the prompt path's room handed back: %zu experts (%.2f GB from the files; %s of "
                                 "their parts) read into VRAM again in %.0f ms (DS4_TP_BORROW)%s%s\n",
                         jobs.size(), bytes / 1e9, per.empty() ? "none" : per.c_str(), now_ms() - t0,
                         n_bad > 0 ? (", " + std::to_string(n_bad) + " of them not (to the CPU lane)").c_str() : "",
                         check ? (differ.load() == 0 ? "; each part matches the model file"
                                                     : ("; MISMATCH: " + std::to_string(differ.load()) +
                                                        " parts differ - their experts to the CPU lane").c_str())
                               : "");
        } else if (o.verbose || n_bad > 0 || check) {
            std::fprintf(stderr, "ds4: the prompt path's room handed back: %zu experts (%.2f GB) read into VRAM again in %.0f ms%s%s\n",
                         jobs.size(), bytes / 1e9, now_ms() - t0,
                         n_bad > 0 ? (", " + std::to_string(n_bad) + " of them not (to the CPU lane)").c_str() : "",
                         check ? (differ.load() == 0 ? "; each matches the model file"
                                                     : ("; MISMATCH: " + std::to_string(differ.load()) +
                                                        " differ - to the CPU lane").c_str())
                               : "");
        }
        if (broken) {
            lend_broken = true;
            std::fprintf(stderr, "ds4: the prompt path's room: a copy into a slot or a table write failed - the "
                                 "device's state unknown; no further request runs\n");
            return false;
        }
        return differ.load() == 0;
    }

    // after a prompt of n tokens on the prompt path (DS4_WARM_MIN, 512, or more): the experts its last rows picked
    // (kWarmRows of them, the last row first, layer by layer) that the decode would read from the files - read into the
    // page cache on a thread of their own while the first tokens decode, up to DS4_WARM_GB (half the RAM left, 32 at
    // most).  Windows used to leave them there (the CPU lane read every pick through the cache, the last ones last);
    // the flow reads past it, and the decode's first tokens read them a page fault at a time - one V100, 64 GB of RAM,
    // Maya-S from an NVMe, after 4K tokens: 2.8 tokens/s the first 64, 8.0 the next.  Only the page cache sees it.
    void warm_after(int n) {
        static const int wmin = std::getenv("DS4_WARM_MIN") ? std::atoi(std::getenv("DS4_WARM_MIN")) : 512;
        if (!file_experts || n < wmin || L.empty() || L[0].lay.fmt != gg::kFmtMXFP4) return;
        if (devs.size() > 1 && std::getenv("DS4_WARM_GB") == nullptr) return;   // (one GPU's, by default)
        const uint64_t avail = ram_room();
        double gb = avail == ~uint64_t{0} ? 8.0 : std::min(32.0, std::max(0.0, ((double) avail - (double) kRamMargin) / 2e9));
        if (const char* v = std::getenv("DS4_WARM_GB")) gb = std::atof(v);
        if (gb <= 0) return;
        std::vector<std::pair<int, int>> w;   // (layer, expert), the order they are read in
        std::vector<char> seen;
        int rows = 0;
        for (const Layer& l : L) rows = std::max(rows, (int) (l.last_picks.size() / kPicks));
        for (int t = rows - 1; t >= 0; --t)
            for (const Layer& l : L) {
                if (l.mtp || (int) (l.last_picks.size() / kPicks) <= t) continue;
                if (seen.size() < (size_t) (l.il + 1) * 1024) seen.resize((size_t) (l.il + 1) * 1024, 0);
                for (int i = 0; i < l.k_exp; ++i) {
                    const int e = l.last_picks[(size_t) t * kPicks + i];
                    if (e < 0 || e >= l.n_exp || seen[(size_t) l.il * 1024 + e] || l.slot[(size_t) e] >= 0 ||
                        (!l.ram.empty() && l.ram[(size_t) e] >= 0) || helper_owned(l, e))
                        continue;
                    seen[(size_t) l.il * 1024 + e] = 1;
                    w.push_back({l.il, e});
                }
            }
        warm_stop.store(false);
        warm_th = std::thread([this, w = std::move(w), budget = gb * 1e9] {
            const double t0 = now_ms();
            double done = 0;
            size_t n_read = 0, n_cached = 0;
            std::vector<std::pair<const void*, size_t>> r(3);
            for (const auto& x : w) {
                if (warm_stop.load(std::memory_order_relaxed) || done >= budget) break;
                const Layer& l = L[(size_t) x.first];
                bool cached = true;
                for (int q = 0; q < 3; ++q) {
                    r[(size_t) q] = {mx_mat(l, x.second, q), mx_part_bytes(l, q)};
                    cached = cached && os::resident_sampled(r[(size_t) q].first, r[(size_t) q].second, 2);
                }
                if (cached) {
                    ++n_cached;
                    continue;
                }
                os::prefetch(r);
                done += (double) l.blob;
                ++n_read;
            }
            if (o.verbose)
                std::fprintf(stderr, "ds4: decode warm-up: %zu of the last rows' %zu experts read ahead (%.1f GB) in %.1f s, "
                                     "%zu in RAM already\n", n_read, w.size(), done / 1e9, (now_ms() - t0) / 1000.0, n_cached);
        });
    }
    void warm_end() {
        warm_stop.store(true);
        if (warm_th.joinable()) warm_th.join();
    }

    // the first layer of a long prompt's second half (forward_chunks' two passes), or -1: the first with compress ratio 1
    // (V4.1: 20), every one after it ratio 1 too and owning no compressed KV or index keys of its own (they read its);
    // on one GPU, or on several (tensor parallel, groups) where no device streams its layers on the flow and no Engram
    // layer comes from it on (the cut then at a chunk's start: forward_chunks), or on a layer split whose earlier layers
    // are on other GPUs while the source and every layer after it share one GPU (the flow allowed: yoco_suffix_gpu).
    // The settings' MAYA_DS4_PROMPT_SKIP (STRATA_DS4_PROMPT_SKIP; DS4_YOCO for tests):
    // 1 (the default) the exact skip, 2 DeepSeek's own serving's (the last 128 rows only: faster, the answers shift a
    // little), 0 off
    static int yoco_mode() {
        static const int m = [] {
            const char* v = std::getenv("DS4_YOCO");
            if (v == nullptr) v = std::getenv("STRATA_DS4_PROMPT_SKIP");
            return v != nullptr ? std::atoi(v) : 1;
        }();
        return m;
    }
    // the device whose Engram slots device di's copies read: a tensor-parallel group's rows read once, by its first
    // member, the others copying from its slots (each member read them itself: the same rows 8 times at --tp 8); its
    // own on the flow or alone (DS4_EG_SHARE=0: every device its own)
    int eg_src_dev(int di) const {
        static const bool share = std::getenv("DS4_EG_SHARE") == nullptr || std::atoi(std::getenv("DS4_EG_SHARE")) != 0;
        const Group& G = groups[(size_t) devs[(size_t) di].grp];
        if (!share || G.mem.size() < 2) return di;
        for (int m : G.mem)
            if (chunks[(size_t) m] == nullptr || chunks[(size_t) m]->flow || chunks[(size_t) m]->eg_host[0] == nullptr)
                return di;
        return G.mem[0];
    }
    std::atomic<bool> eg_abort{false};   // (a device's run failed: the Engram waits end)
    // DS4_YOCO_TP=1: the skip on the flow too for one tensor-parallel group that holds every trunk layer, the cut
    // anywhere in a chunk as on one GPU.  Each member computes the yoco layer's compressed KV and index keys over the
    // chunk's rows itself (its own copy: no member hands them to another within the group), every all-reduce is one
    // (chunk, layer)'s and runs on every member alike, and the skip leaves out the same (chunk, layer)s and the same
    // cut chunk's rows on each - so the members' all-reduces stay paired, and the flow plans nothing for a skipped
    // (chunk, layer) (flow_next, fl_rows) as on one GPU.  Off: a group on the flow never skips, as before
    static bool yoco_tp() {
        static const bool on = [] {
            const char* e = ds4_env("DS4_YOCO_TP");
            return e != nullptr && std::atoi(e) != 0;
        }();
        return on;
    }
    // every trunk layer on one GPU: the cut anywhere in a chunk (Run::cut_r); else at a chunk's start (the sources'
    // rows and the hand-offs between groups go chunk by chunk)
    bool yoco_one_gpu() const {
        for (int il = 0; il < g.nl; ++il)
            if (L[(size_t) il].nm != 1 || L[(size_t) il].dev != L[0].dev) return false;
        return true;
    }
    // a layer split's suffix on one GPU: every layer single-device, the source and every one after it on its GPU
    // (earlier groups still hand off every input row - the source needs them for its kv_only work)
    bool yoco_suffix_gpu(int yl) const {
        for (int il = 0; il < g.nl; ++il)
            if (L[(size_t) il].nm != 1 || (il >= yl && L[(size_t) il].dev != L[(size_t) yl].dev)) return false;
        return true;
    }
    // one tensor-parallel group that holds every trunk layer, under DS4_YOCO_TP (yoco_tp): the skip on the flow too
    bool yoco_tp_group() const {
        if (!yoco_tp() || L[0].nm < 2) return false;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            if (l.nm != L[0].nm || l.grp != L[0].grp || l.dev != L[0].dev) return false;
        }
        return true;
    }
    int yoco_layer() const {
        if (yoco_mode() == 0 || chunk <= 0 || g.nl < 2 || (int) g.ratios.size() < g.nl) return -1;
        int yl = -1;
        for (int il = 0; il < g.nl && yl < 0; ++il)
            if (g.ratios[(size_t) il] == 1) yl = il;
        if (yl <= 0 || !L[(size_t) yl].kv_src) return -1;
        const bool one = yoco_one_gpu(), suffix = !one && yoco_suffix_gpu(yl);
        const bool tp = !one && !suffix && yoco_tp_group();   // (DS4_YOCO_TP: the flow too)
        for (const auto& c : chunks)
            if (!one && !suffix && !tp && c != nullptr && c->flow) return -1;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            if (il > yl && (g.ratios[(size_t) il] != 1 || l.kv_src)) return -1;
            if (!one && il >= yl && l.eg >= 0) return -1;
        }
        return yl;
    }

    // n tokens at positions pos .. in chunks of equal size (at most `chunk`), pipelined over the groups; the logits of
    // the last min(logits_rows, 16) rows (logits_rows > 16: a run of one chunk, every row's into chunk_logits)
    bool forward_chunks(const int* tk, int n, int logits_rows, std::string& err, int snap_slot = -1) {
        if (lend_broken) {
            err = kLendBroken;
            return false;
        }
        if (n < 1) return true;
        if (pos + n > o.max_context) {
            err = "the context is full";
            return false;
        }
        for (int t = 0; t < n; ++t)
            if (tk[t] < 0 || tk[t] >= g.vocab) {
                err = "token " + std::to_string(tk[t]) + " out of range";
                return false;
            }
        // a long prompt's skip: the layers from yoco_layer() on (V4.1: 20-39) read the earlier positions only through
        // that layer's compressed KV and index keys, and each looks back one window (win - 1 positions) more than the
        // layer before - so they need their own work only on the last keep = (nl - yoco) (win - 1) + win rows for the
        // run's last rows and the rings the decode reads to be what the full work gives (up to the experts' summing
        // order).  The chunks stay as they are: the ones before the cut go through the layers before yoco and its
        // kv_only, the cut's chunk through those over all its rows and through the rest from the cut on (Run::r0, a
        // view of its buffers), the chunks after it through every layer - each layer's experts read as without the
        // skip.  On several GPUs the rows before the cut and the rows from it on are chunked apart (the cut a chunk's
        // start: chunk cut_k's rows go to the other groups whole); with the suffix on one GPU of a layer split, or one
        // tensor-parallel group under DS4_YOCO_TP (yoco_tp_group), as on one GPU.  DS4_YOCO=1 (0: off); not with every
        // row's logits (tests)
        const int yl = logits_rows > kWin ? -1 : yoco_layer();
        // (DS4_YOCO_KEEP=<rows>: fewer - DeepSeek's own serving replays the last 128 tokens through those layers
        //  (DeepInfer's "SWA bounded replay"), which shifts the answers a little; at least one window)
        static const int keep_env = std::getenv("DS4_YOCO_KEEP") ? std::atoi(std::getenv("DS4_YOCO_KEEP")) : 0;
        const int keep = yl <= 0 ? 0
                         : keep_env > 0 ? std::max(keep_env, g.win)
                         : yoco_mode() == 2 ? g.win : (g.nl - yl) * (g.win - 1) + g.win;
        const int a = yl > 0 && n - keep >= kYocoMin ? n - keep : 0;
        const bool cut_rows = a > 0 && (yoco_one_gpu() || yoco_suffix_gpu(yl) || yoco_tp_group());
        if (a > 0 && yoco_tp_group()) {   // (DS4_YOCO_TP: once)
            static bool said = false;
            if (!said)
                std::fprintf(stderr, "ds4: a long prompt's skip on the tensor-parallel group of %d (lead CUDA%d): "
                                     "layers %d-%d (DS4_YOCO_TP)\n",
                             L[0].nm, devs[(size_t) L[0].dev].id, yl, g.nl - 1);
            said = true;
        }
        Run run;
        int per = 0;   // (the widest chunk)
        auto part = [&](int a0, int a1) {   // rows [a0, a1) in equal chunks of at most `chunk`
            if (a1 <= a0) return;
            const int nc = (a1 - a0 + chunk - 1) / chunk, w = (a1 - a0 + nc - 1) / nc;
            for (int x = a0; x < a1; x += w) {
                run.p0.push_back(pos + x);
                run.T.push_back(std::min(w, a1 - x));
                run.seq.push_back(++win_seq);
            }
            per = std::max(per, w);
        };
        if (a > 0 && !cut_rows) {
            part(0, a);
            run.yoco = yl;
            run.cut_k = (int) run.T.size();
            run.cut_r = 0;
            part(a, n);
        } else {
            part(0, n);
            if (a > 0) {
                run.yoco = yl;
                run.cut_k = a / per;
                run.cut_r = a - run.cut_k * per;
            }
        }
        if (run.yoco >= 0 && o.verbose)
            std::fprintf(stderr, "ds4: prompt skip: layers %d-%d from CUDA%d, %d early rows KV-only, %d kept\n",
                         yl, g.nl - 1, devs[(size_t) L[(size_t) yl].dev].id, a, n - a);
        logits_all = logits_rows > kWin;
        if (logits_all) chunk_logits.resize((size_t) n * g.vocab);
        for (int t = 0; t < n; ++t) {
            toks.push_back(tk[t]);
            ctoks.push_back(ctok(pos + t, tk[t]));
        }
        warm_end();   // (the last prompt's warm-up: this one streams what it needs)
        struct Lent {   // (every way out, a failed borrow_begin's too: the room handed back once the devices are done)
            Impl* p;
            ~Lent() { (void) p->borrow_end(); }   // (an early way out already fails the prompt)
        } lent_{this};
        if (!borrow_begin(per, err)) return false;
        plan_streams();
        if (snap_slot >= 0) {   // feed_mark: the state before the run's last row, kept by its layers on the way
            run.snap_pos = pos + n - 1;
            for (int il = 0; il < g.nl; ++il) {
                Layer& l = L[(size_t) il];
                Dev& d = devs[(size_t) l.dev];
                if (l.snap_win == nullptr && !dalloc(d, l.snap_win, (size_t) g.win * win_rb(), err)) return false;
                if (l.c_kv != nullptr && l.snap_kv == nullptr &&
                    (!dalloc(d, l.snap_kv, (size_t) l.ratio * g.hd, err) || !dalloc(d, l.snap_sc, (size_t) l.ratio * g.hd, err)))
                    return false;
            }
        }
        const int T_last = run.T.back();
        n_logits = logits_all ? 0 : std::min(logits_rows, T_last);
        const double tl = now_ms();
        {   // each chunk's end on the head device, for the progress reports
            cudaSetDevice(devs[(size_t) head_dev].id);
            while (chunk_done.size() < run.T.size()) {
                cudaEvent_t e = nullptr;
                CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
                chunk_done.push_back(e);
            }
            chunk_rec.reset(new std::atomic<int>[chunk_done.size()]);
            for (size_t i = 0; i < chunk_done.size(); ++i) chunk_rec[i].store(0);
        }
        prof_chunk = prof_on;
        hprof_last = 0;
        const bool lm = lm_begin(run);
        struct LmEnd {   // (every way out: its host memory freed once the device is done with it)
            Impl* p;
            bool on;
            ~LmEnd() {
                if (on) p->lm_end();
            }
        } lm_end_{this, lm};
        std::unique_ptr<EgPrefetch> prefetch;
        static const int eg_prefetch_on = std::getenv("DS4_ENGRAM_PREFETCH") ?
                                          std::max(0, std::atoi(std::getenv("DS4_ENGRAM_PREFETCH"))) : 0;
        static const int eg_zone_kb = std::getenv("DS4_EG_ZONE_KB") ?
                                      std::max(0, std::atoi(std::getenv("DS4_EG_ZONE_KB"))) : 0;
        static const int eg_prefetch_chunks = std::getenv("DS4_ENGRAM_PREFETCH_CHUNKS") ?
                                              std::max(-1, std::atoi(std::getenv("DS4_ENGRAM_PREFETCH_CHUNKS"))) : -1;
        if (eg_prefetch_on && devs.size() == 1 && eg_cache.capacity() > 0) {
            std::vector<std::pair<int, int>> units;
            size_t lookups = 0;
            const size_t cols = (size_t) (pk.eg_ngram - 1) * pk.eg_heads;
            auto add = [&](int k, int il) {
                const int li = L[(size_t) il].eg;
                if (li < 0 || !run.runs(k, il)) return;
                units.push_back({li, k});
                lookups += (size_t) run.T[(size_t) k] * cols;
            };
            if (lm) {
                for (int il = 0; il < g.nl; ++il)
                    for (int k = 0; k < (int) run.T.size(); ++k) add(k, il);
            } else {
                for (int k = 0; k < (int) run.T.size(); ++k)
                    for (int il = 0; il < g.nl; ++il) add(k, il);
            }
            const int nk = (int) run.T.size();
            std::vector<int> eg_layer_ids;
            for (const auto& unit : units)
                if (std::find(eg_layer_ids.begin(), eg_layer_ids.end(), unit.first) == eg_layer_ids.end())
                    eg_layer_ids.push_back(unit.first);
            const size_t eg_layers = eg_layer_ids.size();
            // Consumption credits use compute-chunk indices. A sparse YOCO unit list can start beyond `ahead` or have
            // gaps no consumer can ever credit; keep that valid but unusual layout on the ordinary read path.
            const bool dense_units = units.size() == eg_layers * (size_t) nk;
            std::vector<size_t> token_prefix((size_t) nk + 1, 0);
            for (int k = 0; k < nk; ++k) token_prefix[(size_t) k + 1] = token_prefix[(size_t) k] + run.T[(size_t) k];
            auto max_window_tokens = [&](int ahead) {
                size_t widest = 0;
                for (int start = 0; start + ahead <= nk; ++start)
                    widest = std::max(widest, token_prefix[(size_t) (start + ahead)] - token_prefix[(size_t) start]);
                return widest;
            };
            auto live_lookups = [&](int ahead) {
                // One whole prompt needs no next-window headroom. A bounded pipeline can hold its current window
                // and the previous one until consumption credits arrive; count every layer and do not assume dedup.
                return ahead >= nk ? lookups : 2 * eg_layers * cols * max_window_tokens(ahead);
            };
            const size_t budget = eg_cache.capacity() - eg_cache.capacity() / 4;   // 75%: index/scratch/old rows
            int eg_ahead = 0;
            size_t window_lookups = 0, limit = budget;
            const char* policy = "auto";
            if (eg_prefetch_chunks < 0) {
                if (lookups <= budget) {
                    eg_ahead = nk;   // the whole prompt fits comfortably
                    window_lookups = lookups;
                    policy = "auto whole";
                } else if (lm) {
                    // Layer-major retains completed layers in the shared clock cache while it reads the next one. The
                    // two-window estimate does not bound that occupancy, so automatic mode is whole-or-ordinary here.
                    policy = "auto bounded skipped layer-major";
                } else {
                    int lo = 0, hi = nk - 1;   // largest bounded window whose two-window live set fits
                    while (lo < hi) {
                        const int mid = lo + (hi - lo + 1) / 2;
                        if (live_lookups(mid) <= budget) lo = mid;
                        else hi = mid - 1;
                    }
                    eg_ahead = lo;
                    window_lookups = lo > 0 ? live_lookups(lo) : 0;
                    policy = "auto bounded";
                }
            } else if (eg_prefetch_chunks == 0) {
                eg_ahead = nk;   // explicit experiment: whole prompt, guarded by actual capacity rather than the budget
                window_lookups = lookups;
                limit = eg_cache.capacity();
                policy = "explicit whole";
            } else {
                eg_ahead = std::min(eg_prefetch_chunks, nk);
                window_lookups = live_lookups(eg_ahead);
                policy = "fixed";
            }
            if (dense_units && !units.empty() && eg_ahead > 0 && window_lookups <= limit) {
                prefetch.reset(new EgPrefetch(this, run, std::move(units), lm, eg_ahead));
                eg_pf = prefetch.get();
                if (o.verbose || std::getenv("DS4_EG_PROFILE"))
                    std::fprintf(stderr,
                                 "ds4: Engram prefetch: %s, %s, %zu units, chunk %d, ahead %d (%zu tokens max), "
                                 "live <= %zu / %zu rows, zone %d KiB, up to %.1f MiB scratch/layer\n",
                                 policy, lm ? "layer-major" : "chunk-major", prefetch->units.size(), chunk,
                                 prefetch->ahead, max_window_tokens(eg_ahead),
                                 window_lookups, eg_cache.capacity(), eg_zone_kb,
                                 (double) max_window_tokens(eg_ahead) * cols * (pk.eg_hd + pk.eg_hd / 32) / 1048576.0);
            }
        }
        std::vector<std::string> errs(devs.size());
        halted = false;
        halt.store(false);
        {
            std::lock_guard<std::mutex> lk(halt_mu);
            halt_k = INT_MAX;
            halt_seen = -1;
        }
        bool halting = false;
        eg_abort.store(false);
        if (prefetch) prefetch->start();
        // (DS4_FLOW_HELPER_CHECK: the load's first N runs)
        flow_check_now = flow_helper && flow_check_done < flow_check_runs;
        if (flow_check_now) ++flow_check_done;
        struct CheckEnd {   // (every way out, a failed run's too: the next run decides again)
            bool& now;
            ~CheckEnd() { now = false; }
        } check_end_{flow_check_now};
        for (size_t di = 0; di < devs.size(); ++di)
            workers[di]->submit([this, di, &run, &errs] {
                std::string e;
                if (!run_dev_chunks((int) di, run, e)) {
                    errs[di] = e.empty() ? "a device's thread failed" : e;
                    eg_abort.store(true, std::memory_order_release);
                    if (eg_pf != nullptr) eg_pf->wake();
                }
            });
        size_t reported = 0;
        for (;;) {
            bool all = true;
            for (auto& w : workers) all = all && w->idle();
            if (!all && !halting && cancel && cancel()) {   // a Stop: the devices end the run early
                halting = true;
                std::lock_guard<std::mutex> lk(halt_mu);
                halt_k = halt_seen + 1;
                halt.store(true, std::memory_order_release);
                if (eg_pf != nullptr) eg_pf->wake();
            }
            if (progress && lm) {   // (layer-major: the share of the layers every chunk went through)
                const int nd = lm_layers.load(std::memory_order_acquire);
                if (nd > 0 && nd < g.nl) progress((int64_t) n * nd / g.nl);
            } else if (progress) {   // chunks through every layer (the last layer's device past their event)
                while (reported < run.T.size() && chunk_rec[reported].load(std::memory_order_acquire) &&
                       cudaEventQuery(chunk_done[reported]) == cudaSuccess)
                    ++reported;
                if (reported > 0 && reported < run.T.size())
                    progress(run.p0[reported - 1] + run.T[reported - 1] - run.p0[0]);
            }
            if (all) break;
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
        for (const std::string& e : errs)   // (a device's failure first: a Stop's early end is not one)
            if (!e.empty() && e != kHalted) {
                err = e;
                return false;
            }
        for (const std::string& e : errs)
            if (e == kHalted) {
                halted = true;
                err = "stopped while reading the prompt";
                return false;
            }
        // (before the cache looks at the slots again; no decode after a mismatch or a failure)
        if (!borrow_end()) {
            err = lend_broken ? std::string(kLendBroken)
                              : "DS4_CHECK_LEND: an expert part handed back to VRAM differs from the model file - the "
                                "prompt is not answered (those experts went to the CPU lane)";
            return false;
        }
        st.layer_ms += now_ms() - tl;
        eg_stats();
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        const double th = now_ms();
        CK(cudaStreamSynchronize(d.st));
        st.head_ms += now_ms() - th;
        if (prof_chunk) {   // DS4_PROF: the run's GPU time by stage, every device's summed
            for (Dev& dv : devs) {
                cudaSetDevice(dv.id);
                CK(cudaStreamSynchronize(dv.st));
            }
            cudaSetDevice(d.id);
            prof_collect();
            std::fprintf(stderr,
                         "ds4 prompt GPU time, %d tokens: attention %.0f ms, routing + shared expert %.0f ms, experts %.0f ms "
                         "(with the waits for streamed ones), between layers %.0f ms\n",
                         n, cprof_ms[4] + cprof_ms[5] + cprof_ms[6] + cprof_ms[7] + cprof_ms[1], cprof_ms[2],
                         cprof_ms[3], cprof_ms[0]);
            std::fprintf(stderr,
                         "ds4 prompt attention GPU time: Engram + mixing + projections %.0f ms, compression + indexer "
                         "%.0f ms, q %.0f ms, sparse attention %.0f ms, output projections %.0f ms\n",
                         cprof_ms[4], cprof_ms[5], cprof_ms[6], cprof_ms[7], cprof_ms[1]);
            std::fprintf(stderr,
                         "ds4 prompt host time between the same marks: attention %.0f ms, routing + shared expert %.0f ms, "
                         "experts %.0f ms, between layers %.0f ms\n",
                         hprof_ms[4] + hprof_ms[5] + hprof_ms[6] + hprof_ms[7] + hprof_ms[1], hprof_ms[2],
                         hprof_ms[3], hprof_ms[0]);
            for (double& v : cprof_ms) v = 0;
            for (double& v : hprof_ms) v = 0;
            prof_chunk = false;
        }
        if (o.verbose || std::getenv("DS4_FLOW_STATS") != nullptr) {
            const double ms = now_ms() - tl;
            for (size_t di = 0; di < chunks.size(); ++di) {
                const Chunk& c = *chunks[di];
                if (!c.flow) continue;
                const double db = (double) (c.io->direct_bytes() - c.io_d0) / 1e9;
                const double bb = (double) (c.io->buffered_bytes() - c.io_b0) / 1e9;
                const double fb = db + bb, rb = (double) c.it_ram * (double) L[0].blob / 1e9;   // (a member: its parts)
                char hps[96] = "";   // (DS4_FLOW_HELPER: the items out of the helper's pool)
                if (flow_helper)
                    std::snprintf(hps, sizeof hps, ", %llu from the helper's pool (%.1f GB)",
                                  (unsigned long long) c.it_helper, (double) (c.io->device_bytes() - c.io_h0) / 1e9);
                char lcs[160] = "";
                if (c.lm)
                    std::snprintf(lcs, sizeof lcs, ", %llu again from the layer cache (layer-major, %d chunks, %.1f GB "
                                  "of RAM)", (unsigned long long) c.it_lc, (int) run.T.size(), (double) c.lc_bytes / 1e9);
                std::fprintf(stderr,
                             "ds4 prompt stream, CUDA%d: %d tokens in %.0f ms; %llu experts streamed: %llu from the files "
                             "(%.1f GB, %.2f GB/s: %.1f GB from the disk unbuffered, %.1f GB through the page cache), %llu "
                             "from RAM (%.1f GB)%s%s; %llu likely ones queued early, %llu of them unpicked; the "
                             "compute waited %.0f ms for reads\n",
                             devs[di].id, n, ms, (unsigned long long) (c.it_file + c.it_ram + c.it_lc + c.it_helper),
                             (unsigned long long) c.it_file, fb, fb / std::max(1e-3, ms / 1000.0), db, bb,
                             (unsigned long long) c.it_ram, rb, hps, lcs, (unsigned long long) c.it_spec,
                             (unsigned long long) c.it_spec_unused, c.wait_ms);
            }
        }
        if (flow_check_now)   // (DS4_FLOW_HELPER_CHECK: each member's line, the run's every pool item compared)
            for (size_t di = 0; di < chunks.size(); ++di) {
                const Chunk& c = *chunks[di];
                if (!c.flow) continue;
                std::fprintf(stderr,
                             "ds4 prompt stream, CUDA%d: DS4_FLOW_HELPER_CHECK: %llu of %llu items out of the helper's "
                             "pool compared with the model's files, all bit-identical\n",
                             devs[di].id, (unsigned long long) c.chk_n, (unsigned long long) c.it_helper);
            }
        flow_check_now = false;
        if (pm.on && run.T.size() == 1) {   // (the picks' spread for pick_path: the CPU-lane experts this run picked)
            bool tp = false;
            for (const Layer& l : L) tp = tp || l.nm > 1;
            double picked = 0;
            for (const auto& cp : chunks)
                if (cp != nullptr && cp->flow)
                    picked += (double) (cp->it_file + cp->it_ram + cp->it_helper) - (double) cp->it_spec_unused;
            if (!tp) pm_learn(n, picked);
        }
        if (logits_all) n_logits = (T_last - 1) % kWin + 1;   // (sample() takes the last row of d.logits)
        pos += n;
        st.tokens += n;
        cache_tick(n);
        warm_after(n);
        const int nr = std::min(T_last, tap_cap);
        if (!seed_drafter(pos - nr, nr, 0, err)) return false;
        if (snap_slot >= 0) {   // checkpoint `snap_slot` from what the layers kept (the drafter's blocks: as they are -
            // the next feed seeds them again from its own rows, past this position)
            Check& ckp = ck[snap_slot & 1];
            ckp.pos = run.snap_pos;
            ckp.win.resize(L.size());
            ckp.comp.resize(L.size() * 2);
            for (size_t i = 0; i < L.size(); ++i) {
                Layer& l = L[i];
                Dev& dv = devs[(size_t) l.dev];
                cudaSetDevice(dv.id);
                const bool kept = !l.mtp && l.snap_win != nullptr;
                ckp.win[i].resize((size_t) g.win * win_rb());
                CK(cudaMemcpyAsync(ckp.win[i].data(), kept ? l.snap_win : l.win, ckp.win[i].size(),
                                   cudaMemcpyDeviceToHost, dv.st));
                if (l.c_kv) {
                    ckp.comp[2 * i].resize((size_t) l.ratio * g.hd);
                    ckp.comp[2 * i + 1].resize((size_t) l.ratio * g.hd);
                    CK(cudaMemcpyAsync(ckp.comp[2 * i].data(), kept && l.snap_kv ? l.snap_kv : l.c_kv,
                                       ckp.comp[2 * i].size() * 4, cudaMemcpyDeviceToHost, dv.st));
                    CK(cudaMemcpyAsync(ckp.comp[2 * i + 1].data(), kept && l.snap_sc ? l.snap_sc : l.c_score,
                                       ckp.comp[2 * i + 1].size() * 4, cudaMemcpyDeviceToHost, dv.st));
                }
            }
            for (Dev& dv : devs) {
                cudaSetDevice(dv.id);
                CK(cudaStreamSynchronize(dv.st));
            }
        }
        return true;
    }

    // the window's plan, in window order (the indexer's and the candidate source's sizes carry from window to window)
    void plan_window(int64_t p0, int T, WinPlan& wp) {
        wp.par = par;
        wp.async = par || (!sync_decode && T <= async_max_t);
        wp.vl = 0;
        for (int t = 0; t < T && !imgs.empty(); ++t)
            if (in_image(p0 + t)) wp.vl |= 1u << t;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            if (l.ratio > 0) {
                const int R = l.ratio;
                int n[kWin], k[kWin], clen_max = 0;
                for (int t = 0; t < T; ++t) {
                    n[t] = (int) ((p0 + t + 1) / R);
                    k[t] = std::min(g.ix_topk, n[t]);
                    clen_max = std::max(clen_max, n[t]);
                }
                if (l.ix_src) {
                    for (int t = 0; t < T; ++t) wp.cand[il][t] = cur_cand_n[t];
                    if (clen_max > 0 && l.cand_src)
                        for (int t = 0; t < T; ++t) cur_cand_n[t] = std::min(g.cand_topk, (n[t] + g.cand_blk - 1) / g.cand_blk);
                    for (int t = 0; t < T; ++t) cur_topk_n[t] = k[t];
                }
                for (int t = 0; t < T; ++t) wp.topk[il][t] = cur_topk_n[t];
            }
            wp.seq[il] = 0;
            if (wp.async && !host_free(l)) {
                wp.seq[il] = ++seq_issued;
                layer_of[wp.seq[il] % kRing].store(il, std::memory_order_release);
            }
        }
    }

    // host_free_on's layers: one GPU, every expert in its VRAM (none on the CPU lane, nothing to stream or swap in)
    bool host_free(const Layer& l) const { return host_free_on && l.nm == 1 && l.n_exp > 0 && l.n_vram >= l.n_exp; }
    int head_nm() const { return (int) groups[(size_t) devs[(size_t) head_dev].grp].mem.size(); }
    // the head's columns on member mi of its group of nm: an EXL3 head's split128 of the vocabulary (mat's), a GGUF's
    // BF16 / Q8_0 head's even shares, or split128's where the vocabulary does not split evenly (mat_bf16's) - head_share's,
    // its gather's and the markov steps' rows
    void head_cols(int nm, int mi, int& v0, int& vn) const {
        const Tensor* tw = pk.get("head.weight");
        if (tw != nullptr && gguf_dense(tw->dtype) && g.vocab % nm == 0) {
            vn = g.vocab / nm;
            v0 = mi * vn;
        } else
            split128(g.vocab, nm, mi, v0, vn);
    }
    // the head over `rows` (<= 16) normed rows xn on member mi of the head group (device d): its share of each row's
    // logits (columns [v0, v0 + vn), head_cols); the lead gathers the others' into d.logits (rows V apart) - two
    // slots by seq (Vmax apart, the widest share's), a member reusing one once the lead acknowledged it.  gather
    // false: each member keeps its share (the drafter's markov steps over the group, mk_split)
    bool head_share(Dev& d, int mi, const float* xn, int rows, std::string& err, bool gather = true) {
        const int V = g.vocab, D = g.dim, nm = head_nm();
        int v0 = 0, vn = 0, Vmax = 0, z = 0;
        head_cols(nm, mi, v0, vn);
        head_cols(nm, 0, z, Vmax);
        Group& G = groups[(size_t) d.grp];
        float* out = mi == 0 ? d.logits : d.logits_part;
        const size_t ld = mi == 0 ? (size_t) V : (size_t) vn;
        cudaSetDevice(d.id);
        // (an EXL3 head: as many activations at a time as its split-K partials fit the scratch - 8 for a shared head, 4
        // for a whole one, each pass reading the whole share; a GGUF's: 4 at a time, as before)
        const int per = d.head.fmt != 0 ? 4 : std::max(1, x3::mv_cols(d.head));
        for (int c = 0; c < rows; c += per)
            if (!mv(d, {job(d.head, xn + (size_t) c * D, out + (size_t) c * ld, std::min(per, rows - c), D, ld)}, err))
                return false;
        if (nm == 1 || !gather) return true;
        const unsigned seq = ++d.head_seq;
        const int slot = (int) (seq % 2);
        auto stage = [&](int m) { return G.lg_stage + ((size_t) slot * (nm - 1) + (m - 1)) * kWin * Vmax; };
        auto flag = [&](int m) { return G.lg_flag + ((size_t) slot * (nm - 1) + (m - 1)) * 32; };
        if (mi > 0) {
            if (seq > 2) wait_flags(G.lg_ack + (size_t) slot * 32, 1, 32, seq - 2, d.st);
            Xfer x;
            x.n = 1;
            x.src[0] = d.logits_part;
            x.dst[0] = stage(mi);
            x.bytes[0] = (size_t) rows * vn * 4;
            xfer_put(x, flag(mi), seq, d.xcnt, d.st);
            return true;
        }
        for (int m = 1; m < nm; ++m) {
            int m0 = 0, mn = 0;
            head_cols(nm, m, m0, mn);
            Xfer x;
            x.n = 1;
            x.src[0] = stage(m);
            x.dst[0] = d.logits_part;
            x.bytes[0] = (size_t) rows * mn * 4;
            xfer_get(x, flag(m), seq, d.st);
            CK(cudaMemcpy2DAsync(d.logits + (size_t) m0, (size_t) V * 4, d.logits_part, (size_t) mn * 4,
                                 (size_t) mn * 4, (size_t) rows, cudaMemcpyDeviceToDevice, d.st));
        }
        set_flag(G.lg_ack + (size_t) slot * 32, seq, d.st);
        return true;
    }

    // the head's rows (the last n_logits of the window) on head group member di (its h / pre: the group's)
    bool head_rows_dev(int di, int T, std::string& err) {
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        const int D = g.dim, H = g.hc;
        if (n_logits <= 0) return true;
        const int t0 = T - n_logits;
        hc_pre_norm(d.h + (size_t) t0 * H * D, d.pre + (size_t) t0 * 8, d.norm_w, D, H, n_logits, g.eps, d.x, d.st);
        return head_share(d, d.mi, d.x, n_logits, err);
    }

    // the DSpark drafter's taps: the streams' mean entering target layer il, on device d (after the last seeding read
    // h_taps)
    bool tap(Dev& d, int il, int T, std::string& err) {
        const auto it = std::find(g.d_targets.begin(), g.d_targets.end(), il);
        if (g.n_mtp == 0 || it == g.d_targets.end()) return true;
        const size_t j = (size_t) (it - g.d_targets.begin()), nt = g.d_targets.size();
        const int D = g.dim;
        cudaSetDevice(d.id);
        hc_mean(d.h, T, g.hc, D, d.tap, D, d.st);
        if (!wait_seed(d.st, err)) return false;
        CK(cudaMemcpy2DAsync(h_taps + j * D, nt * D * 4, d.tap, (size_t) D * 4, (size_t) D * 4, (size_t) T,
                             cudaMemcpyDeviceToHost, d.st));
        return true;
    }

    bool forward(const int* tk, int T, int logits_rows, std::string& err, int seed_rows = -1) {
        if (lend_broken) {
            err = kLendBroken;
            return false;
        }
        if (T < 1 || T > kWin) {
            err = "a window of " + std::to_string(T) + " tokens";
            return false;
        }
        if (pos + T > o.max_context) {
            err = "the context is full";
            return false;
        }
        for (int t = 0; t < T; ++t)
            if (tk[t] < 0 || tk[t] >= g.vocab) {
                err = "token " + std::to_string(tk[t]) + " out of range";
                return false;
            }
        const int64_t p0 = pos;
        slot_held = false;   // (the state grows now: what slot_save took is no longer the conversation)
        for (int t = 0; t < T; ++t) {
            toks.push_back(tk[t]);
            ctoks.push_back(ctok(pos + t, tk[t]));
        }
        // the Engram rows asked for now (the first Engram layer's first), collected right before their layer: what is
        // left of their reads by then is the window's Engram time
        const double te = now_ms();
        const int64_t eg_w0 = eg_wait_ns.load();
        for (int li = 0; li < pk.eg_layers; ++li) {
            EgBatch& b = *eg_win[(size_t) li];
            if (b.live) eg_finish(b);   // (a window that failed midway: its reads end before h_eg is reused)
            eg_issue(p0, T, li, nullptr, b);
        }
        st.engram_ms += now_ms() - te;
        const int D = g.dim;
        for (int t = 0; t < T; ++t)   // (h_emb is written again by the next window, after this one's last sync)
            std::memcpy(h_emb + (size_t) t * D, emb_row(p0 + t, tk[t]), (size_t) D * 2);
        plan_window(p0, T, wplan);
        if (helper_n > 0 && wplan.async) helper_window(T, wplan);   // (DS4_HELPER: its share, in seq order)
        prof_window = prof_on && T == 1;
        n_logits = std::min(logits_rows, T);
        const double tl = now_ms();
        if (par) {
            if (!forward_par(p0, T, err)) return false;
        } else if (!forward_serial(p0, T, err)) return false;
        st.layer_ms += now_ms() - tl;
        for (auto& b : eg_win)
            if (b->live) eg_finish(*b);
        st.engram_ms += (double) (eg_wait_ns.load() - eg_w0) / 1e6;
        eg_stats();
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        const double th = now_ms();
        CK(cudaStreamSynchronize(d.st));
        st.head_ms += now_ms() - th;
        prof_collect();
        pos += T;
        st.tokens += T;
        cache_tick(T);
        if (seed_rows != 0 && !seed_drafter(p0, seed_rows < 0 ? T : seed_rows, 0, err)) return false;
        return true;
    }

    // one thread: the layers device after device, the hand-offs through pinned memory and events
    bool forward_serial(int64_t p0, int T, std::string& err) {
        const int D = g.dim, H = g.hc;
        int cur = L[0].dev;
        {
            Dev& d = devs[(size_t) cur];
            cudaSetDevice(d.id);
            CK(cudaMemcpyAsync(d.emb_rows, h_emb, (size_t) T * D * 2, cudaMemcpyHostToDevice, d.st));
            embed(d.emb_rows, T, d.h, D, H, d.st);
            init_pre(d.pre, T, d.st);
        }
        std::vector<float> dump;
        if (dump_h != nullptr) dump.resize((size_t) T * g.nl * H * D);
        for (int il = 0; il < g.nl; ++il) {
            Layer& l = L[(size_t) il];
            if (l.dev != cur) {
                Dev& a = devs[(size_t) cur];
                Dev& b = devs[(size_t) l.dev];
                cudaSetDevice(a.id);
                const size_t nh = (size_t) T * H * D * 4, np = (size_t) T * 8 * 4, nk = (size_t) T * topk_stride() * 4,
                             nc = (size_t) T * cand_stride() * 4;
                uint8_t* bb = a.bounce;
                CK(cudaMemcpyAsync(bb, a.h, nh, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(bb + nh, a.pre, np, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(bb + nh + np, a.topk, nk, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(bb + nh + np + nk, a.cand, nc, cudaMemcpyDeviceToHost, a.st));
                CK(cudaEventRecord(a.ev_out, a.st));
                cudaSetDevice(b.id);
                CK(cudaStreamWaitEvent(b.st, a.ev_out, 0));
                CK(cudaMemcpyAsync(b.h, bb, nh, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.pre, bb + nh, np, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.topk, bb + nh + np, nk, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.cand, bb + nh + np + nk, nc, cudaMemcpyHostToDevice, b.st));
                cur = l.dev;
            }
            if (!tap(devs[(size_t) l.dev], il, T, err)) return false;
            if (!layer(l, 0, p0, T, wplan, err)) return false;
            if (dump_h != nullptr) {   // DS4_DUMP_H: every layer's residual stream, for tools/ds4/compare.py --layers
                Dev& dd = devs[(size_t) l.dev];
                std::vector<float> hv((size_t) T * H * D);
                cudaSetDevice(dd.id);
                CK(cudaMemcpyAsync(hv.data(), dd.h, hv.size() * 4, cudaMemcpyDeviceToHost, dd.st));
                CK(cudaStreamSynchronize(dd.st));
                for (int t = 0; t < T; ++t)
                    std::memcpy(dump.data() + ((size_t) t * g.nl + l.il) * H * D, hv.data() + (size_t) t * H * D,
                                (size_t) H * D * 4);
            }
        }
        if (dump_h != nullptr) std::fwrite(dump.data(), 4, dump.size(), dump_h);
        if (cur != head_dev) {
            err = "the head is not on the last layer's GPU";
            return false;
        }
        return head_rows_dev(head_dev, T, err);
    }

    // threads: each device's thread enqueues its layers (a group's members each their share) at once, the
    // devices waiting on each other through host-mapped flags (the window's seq)
    bool forward_par(int64_t p0, int T, std::string& err) {
        wplan.win = ++win_seq;
        win_now.store(wplan.win, std::memory_order_release);
        std::vector<std::string> errs(devs.size());
        for (size_t di = 0; di < devs.size(); ++di)
            workers[di]->submit([this, di, p0, T, &errs] {
                std::string e;
                if (!run_dev((int) di, p0, T, wplan, e)) errs[di] = e.empty() ? "a device's thread failed" : e;
            });
        for (auto& w : workers) w->wait();
        for (const std::string& e : errs)
            if (!e.empty()) {
                err = e;
                return false;
            }
        return true;
    }

    // the hand-off between groups: h | pre | topk | cand of device d <-> the host-mapped buffer
    Xfer hand_xfer(uint8_t* host, Dev& d, int T, bool put) const {
        const size_t nh = (size_t) T * g.hc * g.dim * 4, np = (size_t) T * 8 * 4, nk = (size_t) T * topk_stride() * 4,
                     nc = (size_t) T * cand_stride() * 4;
        void* dv[4] = {d.h, d.pre, d.topk, d.cand};
        uint8_t* hv[4] = {host, host + nh, host + nh + np, host + nh + np + nk};
        const size_t nb[4] = {nh, np, nk, nc};
        Xfer x;
        x.n = 4;
        for (int i = 0; i < 4; ++i) {
            x.src[i] = put ? (const void*) dv[i] : (const void*) hv[i];
            x.dst[i] = put ? (void*) hv[i] : dv[i];
            x.bytes[i] = nb[i];
        }
        return x;
    }

    bool run_dev(int di, int64_t p0, int T, const WinPlan& wp, std::string& err) {
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int D = g.dim, H = g.hc;
        bool started = false;
        std::vector<char> got(srcs.size(), 0);
        for (int il = 0; il < g.nl; ++il) {
            Layer& L0 = L[(size_t) il];
            int mi = -1;
            for (int m = 0; m < L0.nm; ++m)
                if (member(L0, m).dev == di) mi = m;
            if (mi < 0) continue;
            if (!started) {   // the window's input: the embedding rows, or the previous group's hand-off
                started = true;
                if (il == 0) {
                    CK(cudaMemcpyAsync(d.emb_rows, h_emb, (size_t) T * D * 2, cudaMemcpyHostToDevice, s));
                    embed(d.emb_rows, T, d.h, D, H, s);
                    init_pre(d.pre, T, s);
                } else {
                    const Dev& a = devs[(size_t) L[(size_t) il - 1].dev];
                    xfer_get(hand_xfer(a.hand, d, T, false), a.hand_flag, wp.win, s);
                }
            }
            // the compressed KV / index keys another group's source layer wrote this window
            for (int sidx : {L0.src, L0.ix_src ? L0.ik_src : -1}) {
                if (sidx < 0 || got[(size_t) sidx]) continue;
                got[(size_t) sidx] = 1;
                Src& sr = srcs[(size_t) sidx];
                if (L[(size_t) sr.layer].grp == L0.grp) continue;
                const int64_t g_first = p0 / sr.ratio;
                const int ng = (int) std::max<int64_t>(0, (p0 + T) / sr.ratio - g_first);
                if (ng == 0) continue;
                Xfer x;
                if (sr.ckv[(size_t) di] != nullptr) {
                    x.src[x.n] = sr.x_stage;
                    x.dst[x.n] = sr.ckv[(size_t) di] + (size_t) g_first * ckv_rb();
                    x.bytes[x.n++] = (size_t) ng * ckv_rb();
                }
                if (sr.ik[(size_t) di] != nullptr) {
                    x.src[x.n] = sr.x_stage + x_cap() * ckv_rb();
                    x.dst[x.n] = sr.ik[(size_t) di] + (size_t) g_first * ik_rb();
                    x.bytes[x.n++] = (size_t) ng * ik_rb();
                }
                if (x.n > 0) xfer_get(x, sr.x_flag, wp.win, s);
            }
            if (mi == 0 && !tap(d, il, T, err)) return false;
            if (!layer(L0, mi, p0, T, wp, err)) return false;
            if (dump_l != nullptr && mi == 0) dump_layer(d, d.h, il, p0, T);
            const bool last = il + 1 == g.nl || L[(size_t) il + 1].grp != L0.grp;
            if (last && mi == 0 && il + 1 < g.nl) xfer_put(hand_xfer(d.hand, d, T, true), d.hand_flag, wp.win, d.xcnt, s);
        }
        if (d.grp == devs[(size_t) head_dev].grp && !head_rows_dev(di, T, err)) return false;
        if (!idle_ev.empty()) {   // (its turn over: the expert cache's copies from here, copy_open)
            CK(cudaEventRecord(idle_ev[(size_t) di], s));
            idle_win[(size_t) di].store(wp.win, std::memory_order_release);
        }
        return true;
    }

    // a source's new cache rows (src on device `from`, bytes of them) to the same place of its other devices' copies,
    // through pinned memory: the copy out on the source's stream, each copy in on its device's stream after it
    bool replicate(std::vector<uint8_t*>& copies, uint8_t* stage, cudaEvent_t ev, const uint8_t* src, size_t at,
                   size_t bytes, int from, std::string& err) {
        bool any = false;
        for (size_t od = 0; od < devs.size(); ++od) any = any || (copies[od] != nullptr && (int) od != from);
        if (!any) return true;
        Dev& d = devs[(size_t) from];
        CK(cudaMemcpyAsync(stage, src, bytes, cudaMemcpyDeviceToHost, d.st));
        CK(cudaEventRecord(ev, d.st));
        for (size_t od = 0; od < devs.size(); ++od) {
            if (copies[od] == nullptr || (int) od == from) continue;
            Dev& o2 = devs[od];
            cudaSetDevice(o2.id);
            CK(cudaStreamWaitEvent(o2.st, ev, 0));
            CK(cudaMemcpyAsync(copies[od] + at, stage, bytes, cudaMemcpyHostToDevice, o2.st));
        }
        cudaSetDevice(d.id);
        return true;
    }

    // layer L0 for the window, as group member mi (its share of the heads, of the output projection and of the FFNs;
    // the partial sums all-reduced across the group)
    bool layer(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, std::string& err) {
        Layer& l = member(L0, mi);
        Dev& d = devs[(size_t) l.dev];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int nm = L0.nm;
        // (DS4_HC_FUSE: a decoded token's split and norm in one launch on st, so its mixes are not beside it; =2 a
        // window's rows too)
        const bool fuse = hc_fuse && !l.mtp && (T == 1 || (hc_fuse_win && T <= kWin));
        const bool hs = hc_side() && !fuse;   // (the mixes on st2)
        cudaStream_t hcs = hs ? d.st2 : s;
        const int D = g.dim, H = g.hc, HD = g.hd, NHL = l.ahn, HQ = NHL * HD, OG = l.ogn, FF = l.ffn;
        const ArGroup& ag = groups[(size_t) L0.grp].ar;
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        prof_mark(d, 0);
        // Engram
        if (l.eg >= 0) {
            const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
            const size_t per = (size_t) cols * (ehd + ehd / 32);
            eg_finish(*eg_win[(size_t) l.eg]);   // (asked for when the window began)
            uint8_t* src = h_eg + (size_t) l.eg * eg_cap * per;
            for (int t = 0; t < T; ++t)   // [token][rows | scales] -> [all rows][all scales]
                CK(cudaMemcpyAsync(d.eg_rows + (size_t) t * cols * ehd, src + (size_t) t * per, (size_t) cols * ehd,
                                   cudaMemcpyHostToDevice, s));
            uint8_t* sc = d.eg_rows + (size_t) T * cols * ehd;
            for (int t = 0; t < T; ++t)
                CK(cudaMemcpyAsync(sc + (size_t) t * cols * (ehd / 32), src + (size_t) t * per + (size_t) cols * ehd,
                                   (size_t) cols * (ehd / 32), cudaMemcpyHostToDevice, s));
            engram_dequant(d.eg_rows, sc, T * cols, ehd, d.eg_x, s, (int) eg_q6k[(size_t) l.eg]);
            if (!mv(d, {job(l.eg_wkv, d.eg_x, d.eg_kv, T, (size_t) cols * ehd, (size_t) (H + 1) * D)}, err)) return false;
            engram_gate(d.h, d.eg_kv, l.eg_w, H, D, T, g.eps, s);
        }
        // attention
        // (hc_side: hc_mix + hc_split on st2 beside the attention - the pre norm takes the lagged pre, a_post / a_comb /
        // a_pre are read from the attention's hc_post on, where st waits for them)
        if (hs) {
            CK(cudaEventRecord(d.hc_go, s));
            CK(cudaStreamWaitEvent(d.st2, d.hc_go, 0));
        }
        hc_mix(d.h, l.hca_fn, H * D, (2 + H) * H, T, g.eps, d.mix, hcs);
        gg::PreQ8 xq8;
        if (fuse) {
            hc_split_pre_norm(
                hc_args(l, false, d.mix, d.h, d.pre, d.x, d.xq8, d.xd8, d.a_pre, d.a_post, d.a_comb, nullptr), s, T);
            xq8.x = d.x;
            xq8.q = d.xq8;
            xq8.d = d.xd8;
            xq8.k = D;
            xq8.rows = T;
        } else {
            hc_split(d.mix, l.hca_scale, l.hca_base, H, g.sinkhorn, g.hc_eps, T, d.a_pre, d.a_post, d.a_comb, hcs);
            if (hs) CK(cudaEventRecord(d.hc_done, d.st2));
            hc_pre_norm(d.h, d.pre, l.attn_norm, D, H, T, g.eps, d.x, s);
        }
        {
            x3::MvJob j[4];
            const int nj = attn_in_jobs(l, d.x, d.qr, d.kvr, d.ckr, d.cgr, T, j);
            if (!mv_n(d, j, nj, err, fuse ? &xq8 : nullptr)) return false;
        }
        Finish fq;
        fq.w = l.q_norm;
        fq.eps = g.eps;
        const bool qr8 = (decode_trim & 2) && T <= kWin;   // (DS4_DECODE_TRIM 2: q's norm rounds it to int8 for wq_b)
        gg::PreQ8 qrp;
        if (qr8) {
            fq.q8 = d.qrq8;
            fq.q8d = d.qrd8;
            qrp.x = d.qr;
            qrp.q = d.qrq8;
            qrp.d = d.qrd8;
            qrp.k = g.q_lora;
            qrp.rows = T;
        }
        finish(d.qr, T, g.q_lora, g.q_lora, fq, s);
        if (NHL > 0) {
            x3::MvJob jb = job(l.wq_b, d.qr, d.q, T, g.q_lora, HQ);
            if (!mv_n(d, &jb, 1, err, qr8 ? &qrp : nullptr)) return false;
            Finish fr;
            fr.rd = g.rd;
            fr.pos = (int) p0;
            fr.vpp = NHL;
            fr.freqs = freqs;
            finish(d.q, T * NHL, HD, HD, fr, s);
        }
        // the window rows: the ring's (positions p0 - win ..) then this window's, each query its own 128.  A DSpark
        // block's ring holds the trunk's main KV (positions <= p0 - 1, seeded); its block of drafts attends to all of
        // that ring and to the whole block, and leaves the ring as it was
        ring_to_ext(l.win, d.ext, l.mtp ? (int64_t) g.win : p0, g.win, HD, s);   // (a block's ring: its rows as they lie)
        Finish fk;
        fk.w = l.kv_norm;
        fk.eps = g.eps;
        fk.rd = g.rd;
        fk.pos = (int) p0;
        fk.freqs = freqs;
        fk.quant = 1;
        fk.dst = d.ext + (size_t) g.win * HD;
        fk.dst_stride = HD;
        finish(d.kvr, T, HD, HD, fk, s);
        if (!l.mtp) ext_to_ring(d.ext, l.win, p0, g.win, T, HD, s, spec_win ? l.ring_bak : nullptr);
        AttnRows ar;
        for (int t = 0; t < T; ++t) {
            if (l.mtp) {
                ar.win0[t] = 0;
                ar.nwin[t] = (int) std::min<int64_t>(g.win, p0);
                ar.nsel[t] = T;
                continue;
            }
            const int first = (int) std::max<int64_t>(g.win - p0, t + 1);   // ext row of position max(0, p - win + 1)
            ar.win0[t] = first;
            ar.nwin[t] = g.win + t - first + 1;
            ar.nsel[t] = 0;
        }
        const void* ckv = nullptr;
        int ckv_fmt = kKvFp4;
        if (l.ratio > 0) {
            Src& sr = srcs[(size_t) l.src];
            const int R = l.ratio;
            // the groups this window completes: g_first .. g_first + ng - 1
            const int64_t g_first = p0 / R;              // the first group whose last position is >= p0
            const int64_t g_end = (p0 + T) / R;          // groups completed by p0 + T - 1
            const int ng = (int) std::max<int64_t>(0, g_end - g_first);
            if (l.kv_src) {
                if (R == 1) {
                    Finish fc;
                    fc.w = l.c_norm;
                    fc.eps = g.eps;
                    finish(d.ckr, T, HD, HD, fc, s);
                    if (decode_trim & 4) {   // (DS4_DECODE_TRIM 4: one kernel, no runtime copy)
                        CopyRegions cr;
                        cr.dst[0] = d.latent;
                        cr.src[0] = d.ckr;
                        cr.bytes[0] = (size_t) T * HD * 4;
                        cr.n = 1;
                        if (!copy_regions(cr, s)) {
                            err = "DS4_DECODE_TRIM: the latent copy refused";
                            return false;
                        }
                    } else
                        CK(cudaMemcpyAsync(d.latent, d.ckr, (size_t) T * HD * 4, cudaMemcpyDeviceToDevice, s));
                } else {
                    if (spec_win && l.c_snap != nullptr) {   // to replay the accepted rows if drafts are rejected
                        const size_t ns = (size_t) R * HD * 4, nr = (size_t) T * HD * 4;
                        if (decode_trim & 4) {   // (DS4_DECODE_TRIM 4: the four in one kernel)
                            CopyRegions cr;
                            cr.dst[0] = l.c_snap;
                            cr.src[0] = l.c_kv;
                            cr.bytes[0] = ns;
                            cr.dst[1] = l.c_snap + (size_t) R * HD;
                            cr.src[1] = l.c_score;
                            cr.bytes[1] = ns;
                            cr.dst[2] = l.c_rows;
                            cr.src[2] = d.ckr;
                            cr.bytes[2] = nr;
                            cr.dst[3] = l.c_rows + (size_t) kWin * HD;
                            cr.src[3] = d.cgr;
                            cr.bytes[3] = nr;
                            cr.n = 4;
                            if (!copy_regions(cr, s)) {
                                err = "DS4_DECODE_TRIM: the snapshot copies refused";
                                return false;
                            }
                        } else {
                            CK(cudaMemcpyAsync(l.c_snap, l.c_kv, ns, cudaMemcpyDeviceToDevice, s));
                            CK(cudaMemcpyAsync(l.c_snap + (size_t) R * HD, l.c_score, ns, cudaMemcpyDeviceToDevice, s));
                            CK(cudaMemcpyAsync(l.c_rows, d.ckr, nr, cudaMemcpyDeviceToDevice, s));
                            CK(cudaMemcpyAsync(l.c_rows + (size_t) kWin * HD, d.cgr, nr, cudaMemcpyDeviceToDevice, s));
                        }
                    }
                    compress_win(d.ckr, d.cgr, l.c_kv, l.c_score, R, (int) p0, T, HD, l.c_norm, g.eps, d.latent, s);
                }
            }
            Rows lim;
            int clen_max = 0;
            for (int t = 0; t < T; ++t) {
                lim.n[t] = (int) ((p0 + t + 1) / R);
                lim.k[t] = std::min(g.ix_topk, lim.n[t]);
                clen_max = std::max(clen_max, lim.n[t]);
            }
            if (l.ix_src) {
                Src& ks = srcs[(size_t) l.ik_src];
                if (l.owns_k && ng > 0) {
                    if (!mv(d, {job(l.i_wk, d.latent, d.ikr, ng, HD, g.ix_hd)}, err)) return false;
                    Finish fi;
                    fi.w = l.ik_norm;
                    fi.eps = g.eps;
                    fi.rd = g.rd;
                    fi.pos = (int) (g_first * R);
                    fi.pos_step = R;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    fi.pdst = ks.ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                    fi.pdst_stride = (long long) ik_rb();
                    finish(d.ikr, ng, g.ix_hd, g.ix_hd, fi, s);
                    if (!wp.par && !replicate(ks.ik, ks.h_ik, ks.ev_ik, fi.pdst, (size_t) g_first * ik_rb(),
                                              (size_t) ng * ik_rb(), l.dev, err))
                        return false;
                }
                if (clen_max > 0) {
                    if (!mv(d, {job(l.i_wq_b, d.qr, d.iq, T, g.q_lora, (size_t) g.ix_heads * g.ix_hd)}, err)) return false;
                    Finish fi;
                    fi.rd = g.rd;
                    fi.pos = (int) p0;
                    fi.vpp = g.ix_heads;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    finish(d.iq, T * g.ix_heads, g.ix_hd, g.ix_hd, fi, s);
                    // (iw rows are 64 apart)
                    gemv_f16_rows(l.i_wproj, d.x, (size_t) D, g.ix_heads, D, T,
                                  1.0f / std::sqrt((float) g.ix_hd) / std::sqrt((float) g.ix_heads), d.iw, 64, s);
                    const long long ss = (long long) o.max_context + 64;
                    bool restrict_ = false;
                    for (int t = 0; t < T; ++t)
                        restrict_ = restrict_ || (lim.n[t] + g.cand_blk - 1) / g.cand_blk > g.cand_topk;
                    if (l.uses_cand && restrict_) {
                        Rows cl;   // the candidate positions of each query: its blocks x blk
                        int nmax = 0;
                        for (int t = 0; t < T; ++t) {
                            cl.n[t] = lim.n[t];
                            cl.k[t] = wp.cand[l.il][t];
                            nmax = std::max(nmax, wp.cand[l.il][t] * g.cand_blk);
                        }
                        index_score(d.iq, d.iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, T, nmax, d.cand,
                                    (int) cand_stride(), g.cand_blk, cl, d.scores, ss, s);
                        if (index_check)
                            index_check_rows(d, l.il, d.iq, d.iw, ks.ik[(size_t) l.dev], T, nmax, d.cand, g.cand_blk, cl, ss, s);
                        Rows tr;
                        for (int t = 0; t < T; ++t) {
                            tr.n[t] = wp.cand[l.il][t] * g.cand_blk;
                            tr.k[t] = lim.k[t];
                        }
                        topk(d.scores, ss, T, tr, d.cand, (int) cand_stride(), g.cand_blk, d.topk, (int) topk_stride(), s,
                             &d.tks);
                    } else {
                        index_score(d.iq, d.iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, T, clen_max, nullptr, 0, 1,
                                    lim, d.scores, ss, s);
                        if (index_check)
                            index_check_rows(d, l.il, d.iq, d.iw, ks.ik[(size_t) l.dev], T, clen_max, nullptr, 1, lim, ss, s);
                        if (l.cand_src) {
                            Rows cr;
                            for (int t = 0; t < T; ++t) {
                                cr.n[t] = lim.n[t];
                                cr.k[t] = g.cand_topk;
                            }
                            cand_blocks(d.scores, ss, T, cr, g.cand_blk, d.bm, (long long) bm_stride(), d.cand,
                                        (int) cand_stride(), s);
                        }
                        topk(d.scores, ss, T, lim, nullptr, 0, 1, d.topk, (int) topk_stride(), s, &d.tks);
                        if (topk_check) {   // (into d.cand's rows past the window's: scratch here)
                            const size_t nw = (size_t) T * topk_stride();
                            std::vector<int> tkc_a(nw), tkc_b(nw);
                            CK(cudaMemcpyAsync(tkc_a.data(), d.topk, nw * 4, cudaMemcpyDeviceToHost, s));
                            topk(d.scores, ss, T, lim, nullptr, 0, 1, d.topk, (int) topk_stride(), s);
                            CK(cudaMemcpyAsync(tkc_b.data(), d.topk, nw * 4, cudaMemcpyDeviceToHost, s));
                            CK(cudaStreamSynchronize(s));
                            bool bad = false;
                            for (int t = 0; t < T; ++t)
                                bad = bad || std::memcmp(tkc_a.data() + (size_t) t * topk_stride(),
                                                         tkc_b.data() + (size_t) t * topk_stride(), (size_t) lim.k[t] * 4) != 0;
                            if (bad) ++tkc_bad;
                            const long long nc = ++tkc_calls;
                            if (nc % 256 == 0 || bad)
                                std::fprintf(stderr, "topk check: %lld calls, %lld differed (layer %d, n %d)\n", nc,
                                             tkc_bad.load(), l.il, lim.n[0]);
                        }
                    }
                }
            }
            if (l.kv_src && ng > 0) {
                Finish fc;
                fc.rd = g.rd;
                fc.pos = (int) (g_first * R);
                fc.pos_step = R;
                fc.freqs = freqs;
                fc.quant = 2;
                fc.pdst = sr.ckv[(size_t) l.dev] + (size_t) g_first * ckv_rb();
                fc.pdst_stride = (long long) ckv_rb();
                finish(d.latent, ng, HD, HD, fc, s);
                if (!wp.par && !replicate(sr.ckv, sr.h_ckv, sr.ev_ckv, fc.pdst, (size_t) g_first * ckv_rb(),
                                          (size_t) ng * ckv_rb(), l.dev, err))
                    return false;
                if (wp.par && mi == 0 && sr.remote) {   // the new rows for the other groups' readers
                    Xfer x;
                    x.src[0] = fc.pdst;
                    x.dst[0] = sr.x_stage;
                    x.bytes[0] = (size_t) ng * ckv_rb();
                    x.n = 1;
                    if (l.owns_k && srcs[(size_t) l.ik_src].ik[(size_t) l.dev] != nullptr) {
                        x.src[1] = srcs[(size_t) l.ik_src].ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                        x.dst[1] = sr.x_stage + x_cap() * ckv_rb();
                        x.bytes[1] = (size_t) ng * ik_rb();
                        x.n = 2;
                    }
                    xfer_put(x, sr.x_flag, wp.win, d.xcnt, s);
                }
            }
            for (int t = 0; t < T; ++t) ar.nsel[t] = lim.n[t] > 0 ? wp.topk[l.il][t] : 0;
            ckv = sr.ckv[(size_t) l.dev];
        }
        if (l.mtp) {   // the block's rows (BF16), after the ring's in ext, as every query's selection
            ckv = d.ext + (size_t) g.win * HD;
            ckv_fmt = kKvBf16;
            iota_rows(d.topk, T, T, (int) topk_stride(), s);
        }
        if (NHL > 0) {
            sparse_attn(d.q, d.ext, ckv, d.topk, (int) topk_stride(), ar, l.sink, NHL, HD, T,
                        1.0f / std::sqrt((float) HD), d.o, s, ckv_fmt, 0, &d.attn_scr);
            Finish fo;
            fo.rd = g.rd;
            fo.pos = (int) p0;
            fo.vpp = NHL;
            fo.freqs = freqs;
            fo.inverse = 1;
            fo.quant = 1;
            finish(d.o, T * NHL, HD, HD, fo, s);
            x3::MvJob j[16];
            const int per = HQ / OG;
            for (int gi = 0; gi < OG; ++gi)
                j[gi] = job(l.wo_a[gi], d.o + (size_t) gi * per, d.oa + (size_t) gi * g.o_lora, T, HQ, (size_t) OG * g.o_lora);
            if (!mv_n(d, j, OG, err)) return false;
            if (!mv(d, {job(l.wo_b, d.oa, d.ao, T, (size_t) OG * g.o_lora, D)}, err)) return false;
        } else CK(cudaMemsetAsync(d.ao, 0, (size_t) T * D * sizeof(*d.ao), s));   // (no heads: nothing to add)
        if (nm > 1) allreduce(d.ao, T * D, ag, mi, ++d.ar_seq, d.xcnt, s);
        if (hs) CK(cudaStreamWaitEvent(s, d.hc_done, 0));
        ablate(d, d.ao, T, s);
        hc_post(d.ao, d.h, d.a_post, d.a_comb, D, H, T, d.h2, s);
        std::swap(d.h, d.h2);
        if (dump_l != nullptr && mi == 0) dump_layer(d, d.h, 1000 + l.il, p0, T);   // (DS4_DUMP_L: after the attention)
        prof_mark(d, 1);
        // the MoE
        // (the same beside the MoE: f_post / f_comb / f_pre are read from its hc_post on)
        if (hs) {
            CK(cudaEventRecord(d.hc_go, s));
            CK(cudaStreamWaitEvent(d.st2, d.hc_go, 0));
        }
        hc_mix(d.h, l.hcf_fn, H * D, (2 + H) * H, T, g.eps, d.mix, hcs);
        if (fuse)   // (d.pre's copy of f_pre now: nothing here reads d.pre before the layer's end)
            hc_split_pre_norm(
                hc_args(l, true, d.mix, d.h, d.a_pre, d.x, hc_fuse_win ? d.xq8 : nullptr, hc_fuse_win ? d.xd8 : nullptr,
                        d.f_pre, d.f_post, d.f_comb, d.pre),
                s, T);   // (=2: x rounded for the shared expert's w1 / w3 - xq8 now the FFN's)
        else {
            hc_split(d.mix, l.hcf_scale, l.hcf_base, H, g.sinkhorn, g.hc_eps, T, d.f_pre, d.f_post, d.f_comb, hcs);
            if (hs) CK(cudaEventRecord(d.hc_done, d.st2));
            hc_pre_norm(d.h, d.a_pre, l.ffn_norm, D, H, T, g.eps, d.x, s);
        }
        const gg::PreQ8* ffn_q8 = fuse && hc_fuse_win ? &xq8 : nullptr;   // (the shared expert's w1 / w3 input)
        if (wp.async) {
            // the routing goes to the service thread through the mailbox (a group's lead publishes it, the members
            // make the same plan) while the device runs the shared expert and the VRAM experts (from the plan the
            // router made), and waits for the answer only before the experts' sum
            const unsigned sq = wp.seq[l.il];
            const int slot = (int) (sq % kRing);
            const bool lead = mi == 0 && sq != 0;   // (sq 0: a host-free layer - no mailbox, no wait)
            // (DS4_ROUTE_FUSE: a decoded token's lead with one layer of lookahead and a next layer to guess - the two
            //  gates in one launch, the routing and the guesses in another; =2 a window's rows too; every other case as
            //  before)
            const bool rf_t = T == 1 || (route_fuse_win && T <= kWin);
            const Layer* nx1 = route_fuse && rf_t && !l.mtp && lead && ahead_mode == 1 ? ahead_layer(L0, 1) : nullptr;
            const int m1 = nx1 != nullptr ? std::max(1, std::min(kAhead1, nx1->k_exp + ahead_extra)) : 0;
            RoutePair rp;
            if (nx1 != nullptr) {
                rp.logits = d.glog;
                rp.bias = l.gate_bias;
                rp.n = l.n_exp;
                rp.k = l.k_exp;
                rp.route_scale = g.route_scale;
                rp.vram = l.vram_tab;
                rp.x = d.x;
                rp.dim = D;
                rp.idx = d.ridx;
                rp.w = d.rw;
                rp.plan_ptr = d.plan_ptr;
                rp.req = reqs + slot;
                rp.vl = wp.vl;
                rp.bias_vl = rp.vl != 0 ? l.gate_bias_vl : nullptr;
                rp.seq = sq;
                rp.na0 = m1;
                rp.a_logits = d.glog_a;
                rp.a_bias = nx1->gate_bias;
                rp.a_n = nx1->n_exp;
                rp.m = m1;
                rp.T = T;
            }
            if (route_fusable(l, nx1, m1, D)) {   // (a GEMV not gone in reaches no routing; a routing, no publish)
                if (!gemv_f32_pair(l.gate_w, l.n_exp, d.glog, nx1->gate_w, nx1->n_exp, d.glog_a, d.x, D, s, T,
                                   1024) ||
                    !route_pair(rp, s)) {
                    err = "the fused router stage: a launch did not go in";
                    return false;
                }
            } else {
                gemv_f32(l.gate_w, d.x, l.n_exp, D, T, d.glog, 1024, s);
                // lookahead: the next layers' guesses (their gate on this FFN input), published below
                int na[2] = {0, 0};
                for (int a = 1; lead && a <= std::min(2, ahead_mode); ++a) {
                    const Layer* nx = ahead_layer(L0, a);
                    if (nx == nullptr) break;
                    const int m = a == 1 ? std::max(1, std::min(kAhead1, nx->k_exp + ahead_extra))
                                         : std::min(kPicks, nx->k_exp);
                    float* gl = d.glog_a + (size_t) (a - 1) * kWin * 1024;
                    gemv_f32(nx->gate_w, d.x, nx->n_exp, D, T, gl, 1024, s);   // (normed with the next layer's FFN
                                                                             // weights instead: the same hit rate)
                    route_ahead(gl, nx->gate_bias, nx->n_exp, m, T, reqs + slot, (a - 1) * kAhead1, s);
                    na[a - 1] = m;
                }
                route_publish(d.glog, l.gate_bias, l.n_exp, l.k_exp, T, g.route_scale, l.vram_tab, d.x, D, d.ridx, d.rw,
                              d.plan_ptr, lead ? reqs + slot : nullptr, sq, s, l.gate_bias_vl, l.mtp ? 0u : wp.vl,
                              na[0], na[1], lead && self_answer ? resps + slot : nullptr, d.cpu_any,
                              lane_done);
            }
            {
                x3::MvJob js[2] = {job(l.s1, d.x, d.sg, T, D, FF), job(l.s3, d.x, d.su, T, D, FF)};
                if (!mv_n(d, js, 2, err, ffn_q8)) return false;
            }
            if (!shared_down(d, l, T, FF, err)) return false;
            prof_mark(d, 2);
            const x3::ExpertLayout& lay = nm > 1 ? l.hlay : l.lay;
            if (T == 1 && moe_token_path) {
                const int lc = lead && nm == 1 && lay.fmt == gg::kFmtMXFP4 ? lane_class(l.il) : -1;
                const bool zc_nowait = lc >= 0 && ln_zc_nowait && zc_layer_full(l);
                if (zc_nowait && !zc_nowait_seen.exchange(true))
                    std::fprintf(stderr, "ds4: PCIe lane: layer %d has every non-VRAM expert pinned - no CPU response wait\n",
                                 l.il);
                x3::MoeArgs ma;
                ma.plan_ptr = d.plan_ptr;
                ma.plan_w = d.rw;
                ma.cpu_part = lead && !zc_nowait ? resps[slot].part[0] : nullptr;
                ma.cpu_flag = lead && !zc_nowait ? &resps[slot].cpu[0] : nullptr;
                ma.lay = lay;
                if (l.n_cls > 1) ma.mix = l.mix;   // (a mixed layer: each expert's class's layout)
                ma.k = l.k_exp;
                ma.n_embd = D;
                ma.n_ff = FF;
                ma.limit = g.lim;
                const bool mx = lay.fmt == gg::kFmtMXFP4;
                if (mx) gg::moe_gate_up(ma, d.x, d.xg, s);
                else x3::moe_gate_up(ma, d.x, d.xg, s);
                prof_mark(d, 3);
                // the PCIe lane (a layer that streams): the experts the host reads for it pulled into this GPU's slots as
                // they land, into the plan, their gate / up - all while the CPU lane computes - their down with the VRAM
                // ones' below
                if (lc >= 0) {
                    const LaneDev& LD = ln_dev[(size_t) l.dev];
                    pcie::stream_fetch(ln_pull + slot, sq, LD.dflag, LD.vram, LD.stride, lane_mats(l), !LD.direct,
                                       d.plan_ptr, LD.plan2, l.k_exp, LD.blocks, s);
                    x3::MoeArgs m2 = ma;
                    m2.plan_ptr = LD.plan2;
                    gg::moe_gate_up(m2, d.x, d.xg, s);
                }
                if (lead && !zc_nowait) wait_seq(&resps[slot].seq, sq, s);
                prof_mark(d, 4);
                if (mx) gg::moe_down(ma, d.xg, d.sh_out, d.moe_out, s);
                else x3::moe_down(ma, d.xg, d.sh_out, d.moe_out, s);
            } else {   // each distinct expert read once for the window's tokens
                // the PCIe lane (a layer that streams, ln_win): the window's experts the host streams pulled into this
                // GPU's slots, their entries into the plan - the grouping below takes them as VRAM ones
                const int lc = ln_win && T <= kWin && lead && nm == 1 && lay.fmt == gg::kFmtMXFP4 ? lane_win_class(l.il) : -1;
                if (lc >= 0) {
                    const LaneDev& LD = ln_dev[(size_t) l.dev];
                    pcie::stream_fetch_win(ln_pull + slot, sq, LD.dflag, LD.vram, LD.stride, lane_mats(l), !LD.direct,
                                           d.plan_ptr, T, LD.blocks, s);
                }
                gf::MoeWin mw;
                mw.plan_ptr = d.plan_ptr;
                mw.T = T;
                mw.k = l.k_exp;
                mw.grp_ptr = d.grp_ptr;
                mw.grp_start = d.grp_start;
                mw.grp_ent = d.grp_ent;
                mw.n_groups = d.n_groups;
                gf::moe_win_group(mw, s);
                x3::WinArgs wa;
                wa.grp_ptr = d.grp_ptr;
                wa.grp_start = d.grp_start;
                wa.grp_ent = d.grp_ent;
                wa.n_groups = d.n_groups;
                wa.plan_ptr = d.plan_ptr;
                wa.plan_w = d.rw;
                wa.cpu_part = lead ? &resps[slot].part[0][0] : nullptr;
                wa.cpu_stride = kMaxDim;
                wa.cpu_flag = lead ? resps[slot].cpu : nullptr;
                wa.wait_ptr = lead ? &resps[slot].seq : nullptr;
                wa.wait_val = sq;
                wa.x = d.x;
                wa.x_stride = (size_t) D;
                wa.h = d.xg;
                wa.part = d.ed;
                wa.sh_out = d.sh_out;
                wa.out = d.moe_out;
                wa.out_stride = (size_t) D;
                wa.lay = lay;
                if (l.n_cls > 1) wa.mix = l.mix;
                wa.T = T;
                wa.k = l.k_exp;
                wa.n_embd = D;
                wa.n_ff = FF;
                wa.limit = g.lim;
                if (!(lay.fmt == gg::kFmtMXFP4 ? gg::win_experts(wa, s) : x3::win_experts(wa, s))) {
                    err = "exl3 win_experts failed";
                    return false;
                }
            }
            if (mi == 0) st.experts += (int64_t) T * l.k_exp;
            if (mi == 0 && l.mtp) st.draft_experts += (int64_t) T * l.k_exp;
            if (nm > 1) allreduce(d.moe_out, T * D, ag, mi, ++d.ar_seq, d.xcnt, s);
            if (hs) CK(cudaStreamWaitEvent(s, d.hc_done, 0));
            ablate(d, d.moe_out, T, s);
            hc_post(d.moe_out, d.h, d.f_post, d.f_comb, D, H, T, d.h2, s);
            std::swap(d.h, d.h2);
            if (!fuse) CK(cudaMemcpyAsync(d.pre, d.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));
            prof_mark(d, 5);
            return true;
        }
        if (nm > 1) {
            err = "a tensor-parallel layer on the host-routed path";
            return false;
        }
        // (glog rows are 1024 apart: route reads them so)
        gemv_f32(l.gate_w, d.x, l.n_exp, D, T, d.glog, 1024, s);
        VlBits vb = {};
        vb.w[0] = l.mtp ? 0u : wp.vl;
        route(d.glog, l.gate_bias, l.n_exp, l.k_exp, T, g.route_scale, d.ridx, d.rw, s, l.gate_bias_vl,
              vb.w[0] != 0 ? &vb : nullptr);
        CK(cudaMemcpyAsync(h_idx, d.ridx, (size_t) T * kPicks * 4, cudaMemcpyDeviceToHost, s));
        CK(cudaMemcpyAsync(h_w, d.rw, (size_t) T * kPicks * 4, cudaMemcpyDeviceToHost, s));
        CK(cudaMemcpyAsync(h_x, d.x, (size_t) T * D * 4, cudaMemcpyDeviceToHost, s));
        CK(cudaEventRecord(d.ev, s));
        // the shared expert while the host looks at the picks
        {
            x3::MvJob js[2] = {job(l.s1, d.x, d.sg, T, D, g.ff), job(l.s3, d.x, d.su, T, D, g.ff)};
            if (!mv_n(d, js, 2, err, ffn_q8)) return false;
        }
        if (!shared_down(d, l, T, g.ff, err)) return false;
        const double tw = now_ms();
        CK(cudaEventSynchronize(d.ev));
        st.gpu_wait_ms += now_ms() - tw;
        // the picks by expert: the VRAM ones' rows (gathered inputs, one GEMV per matrix for all their tokens), the
        // CPU lane's entries
        Combine cm;
        Gather ga;
        uint32_t* pr = prof.data() + (size_t) l.il * g.n_exp;
        int vex[kWin * kPicks], vrow0[kWin * kPicks], vn[kWin * kPicks];
        int nvex = 0, nrows = 0;
        std::vector<Ent> ents;
        std::vector<std::pair<int, float>> cpu_rows;   // slot -> (token, weight)
        std::vector<std::vector<std::pair<int, int>>> per((size_t) l.n_exp);   // expert -> (token, pick)
        for (int t = 0; t < T; ++t) {
            cm.n[t] = 0;
            cm.cpu[t] = 0;
            for (int i = 0; i < l.k_exp; ++i) {
                const int e = h_idx[t * kPicks + i];
                if (e < 0 || e >= l.n_exp) {
                    err = "router picked expert " + std::to_string(e);
                    return false;
                }
                ++pr[e];
                l.heat[(size_t) e] += 1.0f;
                if (l.slot[(size_t) e] < 0) l.cpu_hits.push_back(e);
                per[(size_t) e].push_back({t, i});
            }
        }
        int nslots = 0;
        for (int e = 0; e < l.n_exp; ++e) {
            const auto& pe = per[(size_t) e];
            if (pe.empty()) continue;
            if (l.slot[(size_t) e] >= 0) {
                vex[nvex] = e;
                vrow0[nvex] = nrows;
                vn[nvex] = (int) pe.size();
                for (const auto& tp : pe) {
                    ga.src[nrows] = tp.first;
                    const int t = tp.first;
                    cm.row[t][cm.n[t]] = nrows;
                    cm.w[t][cm.n[t]] = h_w[t * kPicks + tp.second];
                    ++cm.n[t];
                    ++nrows;
                }
                ++nvex;
            } else {
                for (size_t a = 0; a < pe.size(); a += kc::kExl3CpuMaxN) {
                    Ent en;
                    en.e = e;
                    en.slot0 = nslots;
                    en.n = (int) std::min<size_t>(kc::kExl3CpuMaxN, pe.size() - a);
                    for (int i = 0; i < en.n; ++i) {
                        en.tok[i] = pe[a + (size_t) i].first;
                        cpu_rows.push_back({pe[a + (size_t) i].first, h_w[pe[a + (size_t) i].first * kPicks + pe[a + (size_t) i].second]});
                        cm.cpu[en.tok[i]] = 1;
                    }
                    nslots += en.n;
                    ents.push_back(en);
                }
            }
        }
        st.experts += (int64_t) T * l.k_exp;
        st.cpu_experts += nslots;
        if (l.mtp) st.draft_experts += (int64_t) T * l.k_exp, st.draft_cpu += nslots;
        if (nrows > 0) {
            gather_rows(d.x, ga, nrows, D, d.xe, s);
            x3::MvJob j[2 * kWin * kPicks];
            int nj = 0;
            for (int i = 0; i < nvex; ++i) {
                const auto& vm = l.vm[(size_t) vex[i]];
                j[nj++] = job(vm[0], d.xe + (size_t) vrow0[i] * D, d.xg + (size_t) vrow0[i] * g.ff, vn[i], D, g.ff);
                j[nj++] = job(vm[1], d.xe + (size_t) vrow0[i] * D, d.xu + (size_t) vrow0[i] * g.ff, vn[i], D, g.ff);
            }
            if (!mv_n(d, j, nj, err)) return false;
            swiglu(d.xg, d.xu, nrows * g.ff, g.lim, d.xhh, s);
            nj = 0;
            for (int i = 0; i < nvex; ++i)
                j[nj++] = job(l.vm[(size_t) vex[i]][2], d.xhh + (size_t) vrow0[i] * g.ff, d.ed + (size_t) vrow0[i] * D,
                              vn[i], g.ff, D);
            if (!mv_n(d, j, nj, err)) return false;
        }
        if (!ents.empty()) {
            const double tc = now_ms();
            cpu_experts(l, h_x, ents);
            std::fill(h_part, h_part + (size_t) T * D, 0.0f);
            for (int sl = 0; sl < nslots; ++sl) {
                float* o = h_part + (size_t) cpu_rows[(size_t) sl].first * D;
                const float wv = cpu_rows[(size_t) sl].second;
                const float* y = c_yd.data() + (size_t) sl * D;
                for (int e = 0; e < D; ++e) o[e] += wv * y[e];
            }
            st.cpu_ms += now_ms() - tc;
            CK(cudaMemcpyAsync(d.cpu_part, h_part, (size_t) T * D * 4, cudaMemcpyHostToDevice, s));
        }
        combine(d.ed, ents.empty() ? nullptr : d.cpu_part, d.sh_out, cm, T, D, d.moe_out, s);
        if (hs) CK(cudaStreamWaitEvent(s, d.hc_done, 0));
        ablate(d, d.moe_out, T, s);
        hc_post(d.moe_out, d.h, d.f_post, d.f_comb, D, H, T, d.h2, s);
        std::swap(d.h, d.h2);
        if (!fuse) CK(cudaMemcpyAsync(d.pre, d.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));
        // (h_part / h_x are written again only after the next layer's route has synchronized, which follows these)
        return true;
    }

    int sample(float temperature, float top_p, int top_k, float min_p, uint64_t seed, uint64_t counter) {
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        strata::kernels::SamplerParams sp;
        sp.temperature = temperature;
        sp.greedy = temperature <= 0.0f;
        sp.top_p = top_p;
        sp.top_k = top_k;
        sp.min_p = min_p;
        sp.seed = seed;
        sp.counter = counter;
        int h = 0;
        const int* hr = pen_rows((int64_t) toks.size(), 1, sp, h);   // (the last fed token's row: every token consumed)
        strata::kernels::sample_tokens(d.logits + (size_t) std::max(0, n_logits - 1) * g.vocab, 1, g.vocab, hr, h,
                                       sp, d.tok, d.st);
        int t = -1;
        cudaMemcpyAsync(&t, d.tok, 4, cudaMemcpyDeviceToHost, d.st);
        cudaStreamSynchronize(d.st);
        return t;
    }

    bool logits(std::vector<float>& out) {
        if (logits_all) {
            out = chunk_logits;
            return true;
        }
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        out.resize((size_t) std::max(1, n_logits) * g.vocab);
        return cudaMemcpy(out.data(), d.logits, out.size() * 4, cudaMemcpyDeviceToHost) == cudaSuccess;
    }

    void save_profile() const {
        if (std::getenv("DS4_CPU_STATS") != nullptr && cpu_calls > 0)
            std::fprintf(stderr, "CPU lane: %ld calls, %.2f experts and %.2f rows a call; per call: gate/up %.3f ms, "
                                 "bands %.3f, down %.3f, down bands %.3f\n", cpu_calls, (double) cpu_ents / cpu_calls,
                         (double) cpu_rows / cpu_calls, cpu_ph_ms[0] / cpu_calls, cpu_ph_ms[1] / cpu_calls,
                         cpu_ph_ms[2] / cpu_calls, cpu_ph_ms[3] / cpu_calls);
        if (std::getenv("DS4_CPU_STATS") != nullptr && rc_ticks > 0)
            std::fprintf(stderr, "recent slots: %lld ticks, %.3f ms a tick, %.2f fills started and %.2f mapped a tick, "
                                 "%.2f streamed experts landed a tick\n",
                         (long long) rc_ticks, rc_tick_ms / rc_ticks, (double) rc_fills_started / rc_ticks,
                         (double) rc_fills_done / rc_ticks, (double) rc_lands / rc_ticks);
        if (std::getenv("DS4_CPU_STATS") != nullptr && cpu_calls > 0) {
            const int thr = pools.empty() ? 1 : (int) (pools[0]->size() + (pools.size() > 1 ? pools[1]->size() : 0));
            for (int i = 0; i < 4; ++i)
                std::fprintf(stderr, "  phase %d: %.1f jobs a call, %.1f us a job; the jobs' time %.0f%% of %d threads x the "
                                     "phase's wall\n", i, (double) cpu_job_n[i] / cpu_calls,
                             cpu_job_n[i] ? cpu_job_ns[i] / 1e3 / cpu_job_n[i] : 0.0,
                             100.0 * cpu_job_ns[i] / 1e6 / (cpu_ph_ms[i] * thr), thr);
        }
        if (o.profile.empty()) return;
        const std::string tmp = o.profile + ".tmp";
        std::FILE* f = std::fopen(tmp.c_str(), "wb");
        if (f == nullptr) return;
        const bool ok = std::fwrite(prof.data(), 4, prof.size(), f) == prof.size();
        std::fclose(f);
        // (the old profile replaced: std::rename does not replace an existing file on Windows, so there the profile
        // never moved on and only .tmp files were left)
        if (!ok || !os::replace_file(tmp, o.profile)) std::remove(tmp.c_str());
    }

    std::vector<std::string> info_lines() const {
        std::vector<std::string> v;
        int nh = 0;
        for (const Layer& l : L) nh += l.n_exp - l.n_vram;
        char b[512];
        // kv=fp4: DeepSeek's own cache layout (the compressed KV and the index keys FP4, the window FP8)
        std::snprintf(b, sizeof b, "INFO context=%lld kv=fp4 kv_resident=%lld expert_slots=%d engine_kind=ds4 "
                                   "cpu_experts=%d ram_experts=%d cpu_threads=%d engine=ds4-0.1",
                      (long long) o.max_context, (long long) o.max_context, g.nl * g.n_exp - nh, nh, ram_held,
                      cpu_threads());
        v.push_back(b);
        // the Monitor's map of each GPU (serve/gpu_map.py, the GLM engine's VRAM lines): what each part holds on the
        // card, in bytes - the dense weights (the drafter's blocks apart), the KV caches, the window's buffers, the
        // drafter's blocks (their weights, a share estimated, and experts), the routed experts' slots, the vision
        // tower (in this process: vision_own); the prompt chunks' buffers (prompt); and tensor parallel's copies (tp,
        // out of weights and kv): of a group of tp_n, each member's (tp_n - 1) / tp_n of the tensors every member holds
        // whole and of its KV caches (every member has its layers' whole KV) - the drafter's few caches on the first
        // GPU at --tp 9 counted with them
        for (const Dev& d : devs) {
            size_t fr = 0, tot = 0;
            cudaSetDevice(d.id);
            mem_info(&fr, &tot);
            int a = -1, z = -1;
            long long slots = 0;
            size_t mtp_exp = 0, mtp_dense = 0;
            for (const Layer& l : L)
                for (int m = 0; m < l.nm; ++m) {
                    const Layer& x = member(l, m);
                    if (x.dev != (int) (&d - devs.data())) continue;
                    if (l.mtp) {
                        mtp_exp += (size_t) l.n_slots * unit(x);
                        mtp_dense += l.dense_bytes;
                        continue;
                    }
                    if (a < 0) a = l.il;
                    z = l.il;
                    slots += l.n_slots;
                }
            mtp_dense = std::min(mtp_dense, d.weights);
            mtp_exp = std::min(mtp_exp, d.experts);
            const size_t tn = groups[(size_t) d.grp].mem.size();
            const size_t tp_w = std::min(d.tp_w, d.weights - mtp_dense), tp_kv = tn > 1 ? d.caches / tn * (tn - 1) : 0;
            // the vision tower: its room while a picture is read (its lender's part less by as much), else nothing -
            // or the room it keeps for the run (kVisResident)
            const bool vdev = img_tok >= 0 && vt.device() == d.id;
            const size_t vis = !vdev ? 0 : vis_res != nullptr ? vis_acct : vis_room != nullptr ? vt.room_bytes() : 0;
            const size_t v_prompt = vdev && vis_room != nullptr && vis_src == kVisChunk ? std::min(vis, d.prompt) : 0;
            const size_t v_pool = vdev && vis_room != nullptr && vis_src == kVisTail ? std::min(vis, d.experts - mtp_exp) : 0;
            char pci[32] = "-";
            if (cudaDeviceGetPCIBusId(pci, sizeof pci, d.id) != cudaSuccess) std::snprintf(pci, sizeof pci, "-");
            std::snprintf(b, sizeof b,
                          "VRAM dev=%d pci=%s total=%zu free=%zu weights=%zu kv=%zu kv_ram=0 act=%zu drafter=%zu window=0 "
                          "pool=%zu tail=0 borrow=0 vision=0 vision_own=%zu prompt=%zu tp=%zu tp_n=%zu slots=%lld ctx=%lld "
                          "layers=%d-%d",
                          d.id, pci, tot, fr, d.weights - mtp_dense - tp_w, d.caches - tp_kv, d.scratch, mtp_dense + mtp_exp,
                          d.experts - mtp_exp - v_pool, vis, d.prompt - v_prompt, tp_w + tp_kv, tn, slots,
                          (long long) o.max_context, a, z);
            v.push_back(b);
        }
        if (commit_kept > 0) {   // (Windows, an integrated GPU: the commit kept experts off the GPU - the server says so)
            std::snprintf(b, sizeof b,
                          "NOTE experts: %.0f GB stay off the GPU - Windows' page file is too small to hold them there; "
                          "a page file of %.0f GB keeps them on the GPU (System > About > Advanced system settings > "
                          "Performance > Advanced > Virtual memory), then restart Maya", commit_kept / 1e9, pagefile_hint);
            v.push_back(b);
            std::snprintf(b, sizeof b, "INFO gpu_commit_capped_gb=%.0f pagefile_hint_gb=%.0f", std::ceil(commit_kept / 1e9),
                          pagefile_hint);
            v.push_back(b);
        }
        if (pk.eg_layers > 0) {   // the n-gram memory's (Engram's) table rows a token reads, for the Monitor
            std::snprintf(b, sizeof b, "INFO engram_layers=%d engram_lookups=%d", pk.eg_layers,
                          pk.eg_layers * (pk.eg_ngram - 1) * pk.eg_heads);
            v.push_back(b);
        }
        if (img_tok >= 0) {   // the server's image resize (DeepSeek's image_processor.py)
            std::snprintf(b, sizeof b,
                          "INFO vision=ds4 vision_patch=%d vision_merge=%d vision_min_pixels=%lld vision_max_tokens=%d "
                          "vision_max_wh_ratio=%lld image_token=%d vision_gpu=%d vision_mib=%lld vision_room_mib=%lld "
                          "vision_room=%s",
                          vg.patch, vg.merge, (long long) pk.num("vision.min_pixels", 0), vg.max_tokens,
                          (long long) pk.num("vision.max_wh_ratio", 0), img_tok, vt.device(),
                          (long long) (vis_acct >> 20), (long long) (vt.room_bytes() >> 20), vis_name(vis_mode));
            v.push_back(b);
        } else if (!vision_err.empty()) {   // (the server offers no pictures and says why)
            std::string why = vision_err;
            for (char& ch : why)
                if (ch == '\n' || ch == '\r') ch = ' ';
            v.push_back("NOTE images: OFF - the model's vision tower did not load (" + why + ")");
            v.push_back("INFO vision=off");
        }
        return v;
    }
};

Model::Model() : p_(new Impl) {}
Model::~Model() = default;
bool Model::load(const Options& o, std::string& err) { return p_->load(o, err); }
bool Model::step(int token, bool logits, std::string& err) { return p_->step(token, logits, err); }
bool Model::feed(const int* tokens, int n, int logits_rows, std::string& err) {
    Impl& p = *p_;
    p.pm.last = -1;
    p.halted = false;
    if (p.chunk > 0 && n >= p.chunk_min) {   // a long run - or one the flow could take, if it is the faster path here
        const double t0 = now_ms();   // (every row's logits (tests): the chunked path, which keeps them all)
        const bool ok = logits_rows > kWin || p.pick_path(n) ? p.forward_chunks(tokens, n, logits_rows, err)
                                                             : p.feed_windows(tokens, n, logits_rows, err);
        if (ok) p.path_done(now_ms() - t0);
        return ok;
    }
    return p.feed_windows(tokens, n, logits_rows, err);
}
bool Model::feed_mark(const int* tokens, int n, int logits_rows, int slot, std::string& err) {
    Impl& p = *p_;
    p.pm.last = -1;
    p.halted = false;
    const double t0 = now_ms();
    if (n >= 2 && p.chunk > 0 && n >= p.chunk_min && p.pick_path(n)) {   // (the last token rides along; its layers
        const bool ok = p.forward_chunks(tokens, n, logits_rows, err, slot);   // keep the state before it)
        if (ok) p.path_done(now_ms() - t0);
        return ok;
    }
    if (n > 1 && !p.feed_windows(tokens, n - 1, 0, err)) return false;
    p.checkpoint(slot);
    const bool ok = n < 1 || p.feed_windows(tokens + n - 1, 1, logits_rows, err);
    if (ok) p.path_done(now_ms() - t0);   // (windows, when pick_path chose them)
    return ok;
}
int Model::feed_unit() const { return p_->chunk > 0 ? std::max(p_->chunk, (int) p_->o.max_context) : kWin; }
void Model::set_progress(std::function<void(int64_t)> f) { p_->progress = std::move(f); }
void Model::set_cancel(std::function<bool()> f) { p_->cancel = std::move(f); }
bool Model::cancelled() const { return p_->halted; }
void Model::begin_request() { p_->begin_request(); }
int Model::sample(float t, float tp, int tk, float mp, uint64_t seed, uint64_t counter) {
    return p_->sample(t, tp, tk, mp, seed, counter);
}
void Model::set_penalties(int last_n, float repeat, float freq, float present) {
    const bool on = last_n > 0 && (repeat != 1.0f || freq != 0.0f || present != 0.0f);
    p_->pen_n = on ? last_n : 0;
    p_->pen_repeat = repeat;
    p_->pen_freq = freq;
    p_->pen_present = present;
}
bool Model::logits(std::vector<float>& out) { return p_->logits(out); }
int Model::image_token() const { return p_->img_tok; }
int Model::dim() const { return p_->g.dim; }
bool Model::encode_image(const uint8_t* rgb, int width, int height, std::vector<uint16_t>& span, std::string& err) {
    return p_->encode_image(rgb, width, height, span, err);
}
void Model::vision_hold() { p_->vis_hold = true; }
bool Model::vision_release() {
    p_->vis_hold = false;
    return p_->vision_release();
}
void Model::set_vision_note(std::function<void()> note) { p_->vis_note = std::move(note); }
void Model::set_images(std::vector<Image> images) {
    std::sort(images.begin(), images.end(), [](const Image& a, const Image& b) { return a.start < b.start; });
    p_->imgs = std::move(images);
}
int Model::draft_block() const { return p_->g.n_mtp > 0 ? p_->g.d_block : 0; }
bool Model::draft(int y, std::vector<int>& d, std::vector<float>& c, std::string& err, float t, float tp, int tk,
                  float mp, uint64_t seed, uint64_t counter) {
    return p_->draft(y, d, c, err, t, tp, tk, mp, seed, counter);
}
bool Model::verify(int y, const std::vector<int>& d, float t, float tp, int tk, float mp, uint64_t seed, uint64_t counter,
                   int& accepted, int& next, std::string& err) {
    return p_->verify(y, d, t, tp, tk, mp, seed, counter, accepted, next, err);
}
int Model::verify_max() const { return kWin; }
bool Model::drafts_sampled() const { return p_->drafts_q; }
int64_t Model::pos() const { return p_->pos; }
int64_t Model::max_context() const { return p_->o.max_context; }
int Model::vocab() const { return p_->g.vocab; }
const std::vector<int32_t>& Model::tokens() const { return p_->toks; }
void Model::reset() { p_->reset(); }
void Model::checkpoint(int slot) { p_->checkpoint(slot); }
bool Model::restore(int64_t limit) { return p_->restore(limit); }
void Model::pin() { p_->pin(); }
std::vector<int64_t> Model::check_positions() const { return p_->check_positions(); }
int64_t Model::restorable(int64_t limit) const { return p_->restorable(limit); }
uint64_t Model::slot_save(std::vector<uint8_t>& out, std::string& err, const std::vector<PicMark>& pics) {
    return p_->slot_save(out, err, pics);
}
bool Model::slot_load(const uint8_t* data, size_t bytes, int64_t n_pos, std::string& err, std::vector<PicMark>* pics) {
    return p_->slot_load(data, bytes, n_pos, err, pics);
}
std::string Model::slot_identity() const { return p_->slot_identity(); }
void Model::save_profile() const { p_->save_profile(); }
const Stats& Model::stats() const { return p_->st; }
std::string Model::describe() const { return p_->describe(); }
std::vector<std::string> Model::info_lines() const { return p_->info_lines(); }
Model::Tiers Model::tiers() const {
    const Impl& m = *p_;
    Tiers t;
    double cb = 0;
    for (const Layer& l : m.L) {
        if (l.mtp) continue;
        t.vram += l.n_vram;
        t.vram_gb += (double) l.n_vram * (double) l.blob / 1e9;
        t.cpu += l.n_exp - l.n_vram;
        cb += (double) (l.n_exp - l.n_vram) * (double) l.blob;
    }
    t.cpu_blob = t.cpu > 0 ? cb / t.cpu : 0;
    // in RAM: the copies (copy_experts / the RAM tier); in place, the read-ahead's share of the page cache; not in
    // place (the experts copied whole into RAM): every CPU-lane expert
    if (m.ram_held > 0) t.ram = m.ram_held;
    else if (m.file_experts) t.ram = t.cpu_blob > 0 ? (int) std::min<double>(t.cpu, (double) m.warm_bytes / t.cpu_blob) : 0;
    else t.ram = t.cpu;
    t.ram_gb = t.ram * t.cpu_blob / 1e9;
    return t;
}

